                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;


ALTER FUNCTION graphql_public.graphql("operationName" text, query text, variables jsonb, extensions jsonb) OWNER TO supabase_admin;

--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
    raise debug 'PgBouncer auth request: %', p_usename;

    return query
    select 
        rolname::text, 
        case when rolvaliduntil < now() 
            then null 
            else rolpassword::text 
        end 
    from pg_authid 
    where rolname=$1 and rolcanlogin;
end;
$_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: _assert_maintenance_write_allowed(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._assert_maintenance_write_allowed() RETURNS TABLE(role_name text, is_global boolean, allowed_don_vi bigint[], default_don_vi bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_user_id text;
  v_allowed bigint[] := ARRAY[]::bigint[];
BEGIN
  v_role := lower(COALESCE(NULLIF(public._get_jwt_claim('app_role'), ''), NULLIF(public._get_jwt_claim('role'), '')));
  v_user_id := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING ERRCODE = '42501';
  END IF;

  IF v_role IN ('user', 'regional_leader') THEN
    RAISE EXCEPTION 'Không có quyền ghi dữ liệu bảo trì' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'global' THEN
    role_name := v_role;
    is_global := true;
    allowed_don_vi := NULL;
    default_don_vi := NULL;
    RETURN NEXT;
    RETURN;
  END IF;

  v_allowed := public.allowed_don_vi_for_session_safe();
  IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
    RAISE EXCEPTION 'Không có quyền ghi dữ liệu bảo trì' USING ERRCODE = '42501';
  END IF;

  role_name := v_role;
  is_global := false;
  allowed_don_vi := v_allowed;
  default_don_vi := v_allowed[1];
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public._assert_maintenance_write_allowed() OWNER TO postgres;

