CREATE FUNCTION public._audit_log_insert(p_admin_user_id bigint, p_admin_username text, p_action_type text, p_target_user_id bigint DEFAULT NULL::bigint, p_target_username text DEFAULT NULL::text, p_action_details jsonb DEFAULT NULL::jsonb, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  BEGIN
    INSERT INTO public.audit_logs (
      admin_user_id, admin_username, action_type, target_user_id, target_username,
      action_details, ip_address, user_agent
    ) VALUES (
      p_admin_user_id, p_admin_username, p_action_type, p_target_user_id, p_target_username,
      p_action_details,
      COALESCE(p_ip_address, inet_client_addr()::TEXT, 'unknown'),
      COALESCE(p_user_agent, current_setting('request.headers', true), 'unknown')
    );
    RETURN TRUE;
  EXCEPTION WHEN others THEN
    RAISE WARNING 'Failed to insert audit log: %', SQLERRM;
    RETURN FALSE;
  END;
END;
$$;


