--
-- Name: _get_jwt_claim(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._get_jwt_claim(claim text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    current_setting('request.jwt.claims', true)::jsonb ->> claim,
    current_setting('request.jwt.claims', true)::json ->> claim,
    NULL
  );
$$;


ALTER FUNCTION public._get_jwt_claim(claim text) OWNER TO postgres;

--
-- Name: _get_jwt_claim_safe(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._get_jwt_claim_safe(claim text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_claim_value TEXT;
    v_jwt_claims JSONB;
BEGIN
    -- Method 1: Try the helper function first
    v_claim_value := public._get_jwt_claim(claim);
    
    IF v_claim_value IS NOT NULL THEN
        RETURN v_claim_value;
    END IF;
    
    -- Method 2: Try direct JSONB extraction
    BEGIN
        v_claim_value := current_setting('request.jwt.claims', true)::jsonb ->> claim;
        IF v_claim_value IS NOT NULL THEN
            RETURN v_claim_value;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- Continue to next method
    END;
    
    -- Method 3: Try direct JSON extraction (fallback)
    BEGIN
        v_claim_value := current_setting('request.jwt.claims', true)::json ->> claim;
        IF v_claim_value IS NOT NULL THEN
            RETURN v_claim_value;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- Continue to next method
    END;
    
    -- Method 4: Parse and extract manually
    BEGIN
        v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
        v_claim_value := v_jwt_claims ->> claim;
        IF v_claim_value IS NOT NULL THEN
            RETURN v_claim_value;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- Return NULL if all methods fail
    END;
    
    RETURN NULL;
END;
$$;


ALTER FUNCTION public._get_jwt_claim_safe(claim text) OWNER TO postgres;

