--
-- Name: _normalize_department_scope(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._normalize_department_scope(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_normalized text;
BEGIN
  IF p_value IS NULL THEN
    RETURN NULL;
  END IF;

  v_normalized := normalize(p_value, NFC);
  v_normalized := replace(v_normalized, chr(160), ' ');
  v_normalized := replace(v_normalized, E'\r', ' ');
  v_normalized := replace(v_normalized, E'\n', ' ');
  v_normalized := replace(v_normalized, E'\t', ' ');
  v_normalized := regexp_replace(v_normalized, '[-]+', ' ', 'g');
  v_normalized := regexp_replace(v_normalized, '\s+', ' ', 'g');
  v_normalized := lower(trim(v_normalized));
  v_normalized := regexp_replace(v_normalized, '(^|\s)ct(\s|$)', '\1chấn thương\2', 'g');
  v_normalized := regexp_replace(v_normalized, '\s+', ' ', 'g');
  v_normalized := trim(v_normalized);

  IF NULLIF(v_normalized, '') IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN v_normalized;
END;
$_$;


ALTER FUNCTION public._normalize_department_scope(p_value text) OWNER TO postgres;

--
-- Name: _sanitize_ilike_pattern(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._sanitize_ilike_pattern(input text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF input IS NULL OR input = '' THEN
    RETURN NULL;
  END IF;
  -- Escape special characters: \ must be escaped first, then % and _
  RETURN replace(replace(replace(input, '\', '\\'), '%', '\%'), '_', '\_');
END;
$$;


ALTER FUNCTION public._sanitize_ilike_pattern(input text) OWNER TO postgres;

--
-- Name: FUNCTION _sanitize_ilike_pattern(input text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public._sanitize_ilike_pattern(input text) IS 'Escape ILIKE special characters (%, _, \) to prevent pattern injection';


