--
-- Name: _technical_configuration_baseline_group_payload(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_baseline_group_payload(p_group_id uuid, p_revision bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'id', g.id,
    'baseline_version_id', g.baseline_version_id,
    'name', g.name,
    'sort_order', g.sort_order,
    'created_at', g.created_at,
    'created_by', g.created_by,
    'updated_at', g.updated_at,
    'updated_by', g.updated_by,
    'revision', p_revision
  )
  FROM public.technical_configuration_baseline_groups g
  WHERE g.id = p_group_id;
$$;


ALTER FUNCTION public._technical_configuration_baseline_group_payload(p_group_id uuid, p_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_baseline_hierarchy_context(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_baseline_hierarchy_context(p_group_id uuid, p_subgroup_id uuid, p_expected_revision bigint) RETURNS TABLE(user_id bigint, version_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_version_id UUID;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT g.baseline_version_id
  INTO v_version_id
  FROM public.technical_configuration_baseline_groups g
  WHERE g.id = p_group_id;
  IF NOT FOUND THEN
    IF EXISTS (
      SELECT 1
      FROM public.technical_configuration_baseline_subgroups s
      WHERE s.id = p_group_id
    ) THEN
      RAISE EXCEPTION 'unsupported_hierarchy_depth' USING ERRCODE = 'PT422';
    END IF;
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  v_user_id := public._technical_configuration_require_editable_baseline_version(
    v_version_id,
    p_expected_revision
  );

  IF p_subgroup_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.technical_configuration_baseline_subgroups s
       WHERE s.id = p_subgroup_id
         AND s.group_id = p_group_id
         AND s.baseline_version_id = v_version_id
     ) THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  user_id := v_user_id;
  version_id := v_version_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public._technical_configuration_baseline_hierarchy_context(p_group_id uuid, p_subgroup_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_baseline_hierarchy_criterion_payload(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_baseline_hierarchy_criterion_payload(p_criterion_id uuid, p_revision bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'id', c.id,
    'baseline_version_id', c.baseline_version_id,
    'group_id', c.group_id,
    'subgroup_id', c.subgroup_id,
    'criterion_code', c.criterion_code,
    'title', c.title,
    'requirement_text', c.requirement_text,
    'sort_order', c.sort_order,
    'source_criterion_id', c.source_criterion_id,
    'created_at', c.created_at,
    'created_by', c.created_by,
    'updated_at', c.updated_at,
    'updated_by', c.updated_by,
    'revision', p_revision
  )
  FROM public.technical_configuration_baseline_criteria c
  WHERE c.id = p_criterion_id;
$$;


ALTER FUNCTION public._technical_configuration_baseline_hierarchy_criterion_payload(p_criterion_id uuid, p_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_baseline_import_apply_v2(uuid, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_baseline_import_apply_v2(p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_validation JSONB;
  v_errors JSONB;
  v_new_criterion_count BIGINT;
  v_group_map JSONB := '{}'::JSONB;
  v_subgroup_map JSONB := '{}'::JSONB;
  v_target_group_ids UUID[] := ARRAY[]::UUID[];
  v_target_subgroup_ids UUID[] := ARRAY[]::UUID[];
  v_target_criterion_ids UUID[] := ARRAY[]::UUID[];
BEGIN
  v_user_id := public._technical_configuration_require_editable_baseline_version(
    p_baseline_version_id,
    p_expected_revision
  );
  v_validation := public._technical_configuration_baseline_import_validate_v2(
    p_baseline_version_id,
    p_template_metadata,
    p_rows,
    p_expected_revision
  );
  v_errors := v_validation->'row_errors';
  IF jsonb_array_length(v_errors) > 0 THEN
    RAISE EXCEPTION 'validation_error'
      USING ERRCODE = 'PT422', DETAIL = v_errors::TEXT;
  END IF;

  SET CONSTRAINTS
    technical_configuration_baseline_groups_version_sort_key,
    tc_baseline_subgroups_group_sort_key,
    technical_configuration_baseline_criteria_group_sort_key,
    tc_baseline_criteria_subgroup_scope_fkey
    DEFERRED;

  WITH incoming_groups AS (
    SELECT
      NULLIF(row->>'group_id', '')::UUID AS group_id,
      row->>'group_name' AS group_name,
      (row->>'target_group_order')::INTEGER AS target_group_order
    FROM jsonb_array_elements(v_validation->'normalized_rows') row
    WHERE row->>'row_type' = 'GROUP'
  ),
  resolved_groups AS (
    SELECT
      i.*,
      COALESCE(i.group_id, gen_random_uuid()) AS resolved_group_id
    FROM incoming_groups i
  )
  SELECT
    COALESCE(
      jsonb_object_agg(
        r.target_group_order::TEXT,
        r.resolved_group_id
        ORDER BY r.target_group_order
      ),
      '{}'::JSONB
    ),
    COALESCE(
      array_agg(r.resolved_group_id ORDER BY r.target_group_order),
      ARRAY[]::UUID[]
    )
  INTO v_group_map, v_target_group_ids
  FROM resolved_groups r;

  WITH incoming_groups AS (
    SELECT
      NULLIF(row->>'group_id', '')::UUID AS group_id,
      row->>'group_name' AS group_name,
      (row->>'target_group_order')::INTEGER AS target_group_order
    FROM jsonb_array_elements(v_validation->'normalized_rows') row
    WHERE row->>'row_type' = 'GROUP'
  )
  UPDATE public.technical_configuration_baseline_groups g
  SET name = i.group_name,
      sort_order = i.target_group_order,
      updated_at = now(),
      updated_by = v_user_id
  FROM incoming_groups i
  WHERE g.id = i.group_id
    AND g.baseline_version_id = p_baseline_version_id;

  WITH incoming_groups AS (
    SELECT
      NULLIF(row->>'group_id', '')::UUID AS group_id,
      row->>'group_name' AS group_name,
      (row->>'target_group_order')::INTEGER AS target_group_order
    FROM jsonb_array_elements(v_validation->'normalized_rows') row
    WHERE row->>'row_type' = 'GROUP'
  )
  INSERT INTO public.technical_configuration_baseline_groups (
    id,
    baseline_version_id,
    name,
    sort_order,
    created_by,
    updated_by
  )
  SELECT
    (v_group_map->>i.target_group_order::TEXT)::UUID,
    p_baseline_version_id,
    i.group_name,
    i.target_group_order,
    v_user_id,
    v_user_id
  FROM incoming_groups i
  WHERE i.group_id IS NULL;

  WITH incoming_subgroups AS (
    SELECT
      NULLIF(row->>'subgroup_id', '')::UUID AS subgroup_id,
      row->>'subgroup_name' AS subgroup_name,
      (row->>'target_group_order')::INTEGER AS target_group_order,
      (row->>'target_subgroup_order')::INTEGER AS target_subgroup_order
    FROM jsonb_array_elements(v_validation->'normalized_rows') row
    WHERE row->>'row_type' = 'SUBGROUP'
  ),
  resolved_subgroups AS (
    SELECT
      i.*,
      COALESCE(i.subgroup_id, gen_random_uuid()) AS resolved_subgroup_id
    FROM incoming_subgroups i
  )
  SELECT
    COALESCE(
      jsonb_object_agg(
        format('%s:%s', r.target_group_order, r.target_subgroup_order),
        r.resolved_subgroup_id
        ORDER BY r.target_group_order, r.target_subgroup_order
      ),
      '{}'::JSONB
    ),
    COALESCE(
      array_agg(
        r.resolved_subgroup_id
        ORDER BY r.target_group_order, r.target_subgroup_order
      ),
      ARRAY[]::UUID[]
    )
  INTO v_subgroup_map, v_target_subgroup_ids
  FROM resolved_subgroups r;

  WITH incoming_subgroups AS (
    SELECT
      NULLIF(row->>'subgroup_id', '')::UUID AS subgroup_id,
      row->>'subgroup_name' AS subgroup_name,
      (row->>'target_group_order')::INTEGER AS target_group_order,
      (row->>'target_subgroup_order')::INTEGER AS target_subgroup_order
    FROM jsonb_array_elements(v_validation->'normalized_rows') row
    WHERE row->>'row_type' = 'SUBGROUP'
  )
  UPDATE public.technical_configuration_baseline_subgroups sg
  SET group_id = (v_group_map->>i.target_group_order::TEXT)::UUID,
      name = i.subgroup_name,
      sort_order = i.target_subgroup_order,
      updated_at = now(),
      updated_by = v_user_id
  FROM incoming_subgroups i
  WHERE sg.id = i.subgroup_id
    AND sg.baseline_version_id = p_baseline_version_id;

  WITH incoming_subgroups AS (
    SELECT
      NULLIF(row->>'subgroup_id', '')::UUID AS subgroup_id,
      row->>'subgroup_name' AS subgroup_name,
      (row->>'target_group_order')::INTEGER AS target_group_order,
      (row->>'target_subgroup_order')::INTEGER AS target_subgroup_order
    FROM jsonb_array_elements(v_validation->'normalized_rows') row
    WHERE row->>'row_type' = 'SUBGROUP'
  )
  INSERT INTO public.technical_configuration_baseline_subgroups (
    id,
    baseline_version_id,
    group_id,
    name,
    sort_order,
    created_by,
    updated_by
  )
  SELECT
    (
      v_subgroup_map->>format(
        '%s:%s',
        i.target_group_order,
        i.target_subgroup_order
      )
    )::UUID,
    p_baseline_version_id,
    (v_group_map->>i.target_group_order::TEXT)::UUID,
    i.subgroup_name,
    i.target_subgroup_order,
    v_user_id,
    v_user_id
  FROM incoming_subgroups i
  WHERE i.subgroup_id IS NULL;

  WITH incoming_criteria AS (
    SELECT
      NULLIF(row->>'criterion_id', '')::UUID AS criterion_id,
      row->>'criterion_code' AS criterion_code,
      NULLIF(row->>'existing_title', '') AS existing_title,
      row->>'requirement_text' AS requirement_text,
      (row->>'target_group_order')::INTEGER AS target_group_order,
      NULLIF(row->>'target_subgroup_order', '')::INTEGER AS target_subgroup_order,
      (row->>'target_criterion_order')::INTEGER AS target_criterion_order
    FROM jsonb_array_elements(v_validation->'normalized_rows') row
    WHERE row->>'row_type' = 'CRITERION'
  )
  UPDATE public.technical_configuration_baseline_criteria c
  SET group_id = (v_group_map->>i.target_group_order::TEXT)::UUID,
      subgroup_id = CASE
        WHEN i.target_subgroup_order IS NULL THEN NULL
        ELSE (
          v_subgroup_map->>format(
            '%s:%s',
            i.target_group_order,
            i.target_subgroup_order
          )
        )::UUID
      END,
      title = i.existing_title,
      requirement_text = i.requirement_text,
      sort_order = i.target_criterion_order,
      updated_at = now(),
      updated_by = v_user_id
  FROM incoming_criteria i
  WHERE c.id = i.criterion_id
    AND c.baseline_version_id = p_baseline_version_id;

  WITH incoming_criteria AS (
    SELECT
      NULLIF(row->>'criterion_id', '')::UUID AS criterion_id,
      row->>'criterion_code' AS criterion_code,
      NULLIF(row->>'existing_title', '') AS existing_title,
      row->>'requirement_text' AS requirement_text,
      (row->>'target_group_order')::INTEGER AS target_group_order,
      NULLIF(row->>'target_subgroup_order', '')::INTEGER AS target_subgroup_order,
      (row->>'target_criterion_order')::INTEGER AS target_criterion_order
    FROM jsonb_array_elements(v_validation->'normalized_rows') row
    WHERE row->>'row_type' = 'CRITERION'
  )
  INSERT INTO public.technical_configuration_baseline_criteria (
    baseline_version_id,
    group_id,
    subgroup_id,
    criterion_code,
    title,
    requirement_text,
    sort_order,
    created_by,
    updated_by
  )
  SELECT
    p_baseline_version_id,
    (v_group_map->>i.target_group_order::TEXT)::UUID,
    CASE
      WHEN i.target_subgroup_order IS NULL THEN NULL
      ELSE (
        v_subgroup_map->>format(
          '%s:%s',
          i.target_group_order,
          i.target_subgroup_order
        )
      )::UUID
    END,
    i.criterion_code,
    i.existing_title,
    i.requirement_text,
    i.target_criterion_order,
    v_user_id,
    v_user_id
  FROM incoming_criteria i
  WHERE i.criterion_id IS NULL;

  SELECT COALESCE(
    array_agg(NULLIF(row->>'criterion_id', '')::UUID),
    ARRAY[]::UUID[]
  )
  INTO v_target_criterion_ids
  FROM jsonb_array_elements(v_validation->'normalized_rows') row
  WHERE row->>'row_type' = 'CRITERION'
    AND NULLIF(row->>'criterion_id', '') IS NOT NULL;

  DELETE FROM public.technical_configuration_baseline_criteria c
  WHERE c.baseline_version_id = p_baseline_version_id
    AND NOT (c.id = ANY(v_target_criterion_ids))
    AND NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_validation->'normalized_rows') row
      WHERE row->>'row_type' = 'CRITERION'
        AND NULLIF(row->>'criterion_id', '') IS NULL
        AND row->>'criterion_code' = c.criterion_code
    );

  DELETE FROM public.technical_configuration_baseline_subgroups sg
  WHERE sg.baseline_version_id = p_baseline_version_id
    AND NOT (sg.id = ANY(v_target_subgroup_ids));

  DELETE FROM public.technical_configuration_baseline_groups g
  WHERE g.baseline_version_id = p_baseline_version_id
    AND NOT (g.id = ANY(v_target_group_ids));

  v_new_criterion_count := (v_validation->'effects'->'criteria'->>'create')::BIGINT;
  UPDATE public.technical_configuration_baseline_versions
  SET next_criterion_number = next_criterion_number + v_new_criterion_count,
      revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = p_baseline_version_id;

  RETURN jsonb_build_object(
    'data', public._technical_configuration_baseline_snapshot(p_baseline_version_id),
    'preview', jsonb_build_object(
      'metadata', v_validation->'metadata',
      'rows', v_validation->'normalized_rows',
      'counts', v_validation->'counts',
      'effects', v_validation->'effects'
    )
  );
END;
$$;


ALTER FUNCTION public._technical_configuration_baseline_import_apply_v2(p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_baseline_import_validate(uuid, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_baseline_import_validate(p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_target JSONB;
  v_next_criterion_number BIGINT;
  v_metadata JSONB;
  v_existing_criterion_codes TEXT[] := ARRAY[]::TEXT[];
  v_normalized_rows JSONB := '[]'::JSONB;
  v_errors JSONB := '[]'::JSONB;
  v_row JSONB;
  v_row_number INTEGER;
  v_key_count INTEGER;
  v_row_type TEXT;
  v_group_order INTEGER;
  v_group_name TEXT;
  v_criterion_order INTEGER;
  v_criterion_code TEXT;
  v_criterion_title TEXT;
  v_requirement_text TEXT;
  v_expected_group_order INTEGER := 1;
  v_expected_criterion_order INTEGER := 1;
  v_current_group_order INTEGER;
  v_seen_criterion_codes TEXT[] := ARRAY[]::TEXT[];
  v_new_criterion_count BIGINT := 0;
  v_allocated_criterion_number BIGINT;
  v_error_count_before INTEGER;
BEGIN
  v_target := public._technical_configuration_baseline_import_validate_metadata(
    p_baseline_version_id,
    p_template_metadata,
    p_expected_revision
  );
  v_metadata := v_target->'metadata';
  v_next_criterion_number := (v_target->>'next_criterion_number')::BIGINT;
  SELECT COALESCE(array_agg(c.criterion_code), ARRAY[]::TEXT[])
  INTO v_existing_criterion_codes
  FROM public.technical_configuration_baseline_criteria c
  WHERE c.baseline_version_id = p_baseline_version_id;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'validation_error'
      USING ERRCODE = 'PT422', DETAIL = 'canonical rows must be an array';
  END IF;

  FOR v_row, v_row_number IN
    SELECT value, ordinality::INTEGER
    FROM jsonb_array_elements(p_rows) WITH ORDINALITY
  LOOP
    v_error_count_before := jsonb_array_length(v_errors);
    v_group_order := NULL;
    v_group_name := NULL;
    v_criterion_order := NULL;
    v_criterion_code := NULL;
    v_criterion_title := NULL;
    v_requirement_text := NULL;

    IF jsonb_typeof(v_row) <> 'object' THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_row_number,
        'code', 'invalid_row_shape',
        'message', 'canonical row must be an object'
      ));
      CONTINUE;
    END IF;

    SELECT count(*) INTO v_key_count FROM jsonb_object_keys(v_row);
    IF v_key_count <> 7
       OR NOT v_row ?& ARRAY[
         'row_type',
         'group_order',
         'group_name',
         'criterion_order',
         'criterion_code',
         'criterion_title',
         'requirement_text'
       ] THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_row_number,
        'code', 'invalid_row_shape',
        'message', 'canonical row has unsupported or missing fields'
      ));
      CONTINUE;
    END IF;

    IF jsonb_typeof(v_row->'row_type') = 'string' THEN
      v_row_type := btrim(v_row->>'row_type');
    ELSE
      v_row_type := NULL;
    END IF;

    IF jsonb_typeof(v_row->'group_order') = 'number'
       AND v_row->>'group_order' ~ '^[0-9]+$' THEN
      BEGIN
        v_group_order := (v_row->>'group_order')::INTEGER;
      EXCEPTION
        WHEN numeric_value_out_of_range THEN
          v_group_order := NULL;
      END;
    END IF;

    IF v_row_type = 'GROUP' THEN
      IF jsonb_typeof(v_row->'group_name') = 'string' THEN
        v_group_name := btrim(
          replace(replace(v_row->>'group_name', E'\r\n', E'\n'), E'\r', E'\n'),
          E' \t\n\r\f\v' || U&'\200B\2060'
        );
      END IF;

      IF v_group_order IS NULL
         OR v_group_order <= 0
         OR v_group_order <> v_expected_group_order THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_row_number,
          'code', 'invalid_group_order',
          'column', 'group_order',
          'message', 'group_order must be positive, unique, and contiguous'
        ));
      END IF;
      IF COALESCE(v_group_name, '') = '' THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_row_number,
          'code', 'required_text',
          'column', 'group_name',
          'message', 'group_name is required'
        ));
      END IF;
      IF v_row->'criterion_order' <> 'null'::JSONB
         OR v_row->'criterion_code' <> 'null'::JSONB
         OR v_row->'criterion_title' <> 'null'::JSONB
         OR v_row->'requirement_text' <> 'null'::JSONB THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_row_number,
          'code', 'invalid_row_shape',
          'message', 'GROUP rows cannot contain criterion fields'
        ));
      END IF;

      IF v_group_order IS NOT NULL AND v_group_order > 0 THEN
        v_current_group_order := v_group_order;
      ELSE
        v_current_group_order := NULL;
      END IF;
      v_expected_group_order := v_expected_group_order + 1;
      v_expected_criterion_order := 1;

      IF jsonb_array_length(v_errors) = v_error_count_before THEN
        v_normalized_rows := v_normalized_rows || jsonb_build_array(jsonb_build_object(
          'row_type', 'GROUP',
          'group_order', v_group_order,
          'group_name', v_group_name,
          'criterion_order', NULL,
          'criterion_code', NULL,
          'criterion_title', NULL,
          'requirement_text', NULL
        ));
      END IF;
      CONTINUE;
    END IF;

    IF v_row_type = 'CRITERION' THEN
      IF jsonb_typeof(v_row->'criterion_order') = 'number'
         AND v_row->>'criterion_order' ~ '^[0-9]+$' THEN
        BEGIN
          v_criterion_order := (v_row->>'criterion_order')::INTEGER;
        EXCEPTION
          WHEN numeric_value_out_of_range THEN
            v_criterion_order := NULL;
        END;
      END IF;
      IF v_row->'criterion_code' <> 'null'::JSONB
         AND jsonb_typeof(v_row->'criterion_code') = 'string' THEN
        v_criterion_code := NULLIF(btrim(v_row->>'criterion_code'), '');
      ELSIF v_row->'criterion_code' <> 'null'::JSONB THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_row_number,
          'code', 'invalid_row_shape',
          'column', 'criterion_code',
          'message', 'criterion_code must be a string or null'
        ));
      END IF;
      IF v_row->'criterion_title' = 'null'::JSONB THEN
        v_criterion_title := NULL;
      ELSIF jsonb_typeof(v_row->'criterion_title') = 'string' THEN
        v_criterion_title := NULLIF(btrim(
          replace(replace(v_row->>'criterion_title', E'\r\n', E'\n'), E'\r', E'\n'),
          E' \t\n\r\f\v' || U&'\200B\2060'
        ), '');
      ELSE
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_row_number,
          'code', 'invalid_row_shape',
          'column', 'criterion_title',
          'message', 'criterion_title must be a string or null'
        ));
      END IF;
      IF jsonb_typeof(v_row->'requirement_text') = 'string' THEN
        v_requirement_text := btrim(
          replace(replace(v_row->>'requirement_text', E'\r\n', E'\n'), E'\r', E'\n'),
          E' \t\n\r\f\v' || U&'\200B\2060'
        );
      END IF;

      IF v_current_group_order IS NULL
         OR v_group_order IS DISTINCT FROM v_current_group_order THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_row_number,
          'code', 'invalid_group_order',
          'column', 'group_order',
          'message', 'CRITERION row must belong to the preceding GROUP'
        ));
      END IF;
      IF v_criterion_order IS NULL
         OR v_criterion_order <= 0
         OR v_criterion_order <> v_expected_criterion_order THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_row_number,
          'code', 'invalid_criterion_order',
          'column', 'criterion_order',
          'message', 'criterion_order must be positive, unique, and contiguous'
        ));
      END IF;
      IF v_row->'group_name' <> 'null'::JSONB THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_row_number,
          'code', 'invalid_row_shape',
          'column', 'group_name',
          'message', 'CRITERION rows cannot repeat group_name'
        ));
      END IF;
      IF COALESCE(v_requirement_text, '') = '' THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_row_number,
          'code', 'required_text',
          'column', 'requirement_text',
          'message', 'requirement_text is required'
        ));
      END IF;

      IF v_criterion_code IS NOT NULL THEN
        IF v_criterion_code !~ '^TC-[0-9]{4,}$' THEN
          v_errors := v_errors || jsonb_build_array(jsonb_build_object(
            'row', v_row_number,
            'code', 'invalid_criterion_code',
            'column', 'criterion_code',
            'message', 'criterion_code must match TC-0001 or be null'
          ));
        ELSIF v_criterion_code = ANY(v_seen_criterion_codes) THEN
          v_errors := v_errors || jsonb_build_array(jsonb_build_object(
            'row', v_row_number,
            'code', 'duplicate_criterion_code',
            'column', 'criterion_code',
            'message', 'criterion_code is duplicated'
          ));
        ELSIF NOT (v_criterion_code = ANY(v_existing_criterion_codes)) THEN
          v_errors := v_errors || jsonb_build_array(jsonb_build_object(
            'row', v_row_number,
            'code', 'changed_criterion_code',
            'column', 'criterion_code',
            'message', 'criterion_code does not belong to the target version'
          ));
        END IF;
        v_seen_criterion_codes := array_append(v_seen_criterion_codes, v_criterion_code);
      ELSIF jsonb_array_length(v_errors) = v_error_count_before THEN
        v_allocated_criterion_number := v_next_criterion_number + v_new_criterion_count;
        v_criterion_code := 'TC-' || lpad(
          v_allocated_criterion_number::TEXT,
          GREATEST(4, length(v_allocated_criterion_number::TEXT)),
          '0'
        );
        IF v_criterion_code = ANY(v_existing_criterion_codes) THEN
          v_errors := v_errors || jsonb_build_array(jsonb_build_object(
            'row', v_row_number,
            'code', 'duplicate_criterion_code',
            'column', 'criterion_code',
            'message', 'allocated criterion_code already exists'
          ));
        ELSE
          v_new_criterion_count := v_new_criterion_count + 1;
          v_seen_criterion_codes := array_append(v_seen_criterion_codes, v_criterion_code);
        END IF;
      END IF;

      v_expected_criterion_order := v_expected_criterion_order + 1;
      IF jsonb_array_length(v_errors) = v_error_count_before THEN
        v_normalized_rows := v_normalized_rows || jsonb_build_array(jsonb_build_object(
          'row_type', 'CRITERION',
          'group_order', v_group_order,
          'group_name', NULL,
          'criterion_order', v_criterion_order,
          'criterion_code', v_criterion_code,
          'criterion_title', v_criterion_title,
          'requirement_text', v_requirement_text
        ));
      END IF;
      CONTINUE;
    END IF;

    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'row', v_row_number,
      'code', 'invalid_row_type',
      'column', 'row_type',
      'message', 'row_type must be GROUP or CRITERION'
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'metadata', v_metadata,
    'rows', v_normalized_rows,
    'row_errors', v_errors,
    'new_criterion_count', v_new_criterion_count
  );
END;
$_$;


ALTER FUNCTION public._technical_configuration_baseline_import_validate(p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_baseline_import_validate_metadata(uuid, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_baseline_import_validate_metadata(p_baseline_version_id uuid, p_template_metadata jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_dossier_id UUID;
  v_revision BIGINT;
  v_next_criterion_number BIGINT;
  v_key_count INTEGER;
BEGIN
  SELECT v.dossier_id, v.revision, v.next_criterion_number
  INTO v_dossier_id, v_revision, v_next_criterion_number
  FROM public.technical_configuration_baseline_versions v
  WHERE v.id = p_baseline_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF p_template_metadata IS NULL
     OR jsonb_typeof(p_template_metadata) <> 'object' THEN
    RAISE EXCEPTION 'template_mismatch'
      USING ERRCODE = 'PT422', DETAIL = 'template metadata must be an object';
  END IF;
  SELECT count(*) INTO v_key_count FROM jsonb_object_keys(p_template_metadata);
  IF v_key_count <> 6
     OR NOT p_template_metadata ?& ARRAY[
       'template_kind',
       'template_version',
       'dossier_id',
       'baseline_version_id',
       'baseline_revision',
       'generated_at'
     ]
     OR jsonb_typeof(p_template_metadata->'template_kind') <> 'string'
     OR jsonb_typeof(p_template_metadata->'template_version') <> 'number'
     OR jsonb_typeof(p_template_metadata->'dossier_id') <> 'string'
     OR jsonb_typeof(p_template_metadata->'baseline_version_id') <> 'string'
     OR jsonb_typeof(p_template_metadata->'baseline_revision') <> 'number'
     OR jsonb_typeof(p_template_metadata->'generated_at') <> 'string' THEN
    RAISE EXCEPTION 'template_mismatch'
      USING ERRCODE = 'PT422', DETAIL = 'template metadata has an invalid shape';
  END IF;

  BEGIN
    PERFORM (p_template_metadata->>'generated_at')::TIMESTAMPTZ;
    IF p_template_metadata->>'template_kind' <> 'technical_configuration_baseline'
       OR p_template_metadata->>'template_version' <> '1'
       OR (p_template_metadata->>'dossier_id')::UUID IS DISTINCT FROM v_dossier_id
       OR (p_template_metadata->>'baseline_version_id')::UUID
         IS DISTINCT FROM p_baseline_version_id
       OR (p_template_metadata->>'baseline_revision')::BIGINT
         IS DISTINCT FROM p_expected_revision
       OR v_revision IS DISTINCT FROM p_expected_revision THEN
      RAISE EXCEPTION 'template_mismatch'
        USING ERRCODE = 'PT422', DETAIL = 'template metadata does not match the target';
    END IF;
  EXCEPTION
    WHEN invalid_text_representation
      OR invalid_datetime_format
      OR datetime_field_overflow
      OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'template_mismatch'
        USING ERRCODE = 'PT422', DETAIL = 'template metadata contains invalid values';
  END;

  RETURN jsonb_build_object(
    'metadata', jsonb_build_object(
      'template_kind', 'technical_configuration_baseline',
      'template_version', 1,
      'dossier_id', v_dossier_id,
      'baseline_version_id', p_baseline_version_id,
      'baseline_revision', v_revision,
      'generated_at', p_template_metadata->>'generated_at'
    ),
    'next_criterion_number', v_next_criterion_number
  );
END;
$$;


ALTER FUNCTION public._technical_configuration_baseline_import_validate_metadata(p_baseline_version_id uuid, p_template_metadata jsonb, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_baseline_import_validate_metadata_v2(uuid, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_baseline_import_validate_metadata_v2(p_baseline_version_id uuid, p_template_metadata jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims JSONB;
  v_role TEXT;
  v_user_id BIGINT;
  v_dossier_id UUID;
  v_revision BIGINT;
  v_next_criterion_number BIGINT;
  v_status TEXT;
  v_archived_at TIMESTAMPTZ;
  v_key_count INTEGER;
BEGIN
  BEGIN
    v_claims := COALESCE(
      NULLIF(current_setting('request.jwt.claims', true), ''),
      '{}'
    )::JSONB;
    v_role := lower(
      COALESCE(
        NULLIF(v_claims->>'app_role', ''),
        NULLIF(v_claims->>'role', '')
      )
    );
    v_user_id := NULLIF(v_claims->>'user_id', '')::BIGINT;
  EXCEPTION
    WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END;

  IF v_role IS NULL
     OR v_user_id IS NULL
     OR NOT (v_role IN ('global', 'admin'))
     OR NOT EXISTS (
       SELECT 1
       FROM public.nhan_vien nv
       WHERE nv.id = v_user_id
     ) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  SELECT
    v.dossier_id,
    v.revision,
    v.next_criterion_number,
    v.status,
    d.archived_at
  INTO
    v_dossier_id,
    v_revision,
    v_next_criterion_number,
    v_status,
    v_archived_at
  FROM public.technical_configuration_baseline_versions v
  JOIN public.technical_configuration_dossiers d ON d.id = v.dossier_id
  WHERE v.id = p_baseline_version_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  IF v_archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived_dossier' USING ERRCODE = 'PT409';
  END IF;
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'locked_version' USING ERRCODE = 'PT409';
  END IF;
  IF v_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'stale_revision' USING ERRCODE = 'PT409';
  END IF;

  IF p_template_metadata IS NULL
     OR jsonb_typeof(p_template_metadata) <> 'object' THEN
    RAISE EXCEPTION 'template_mismatch'
      USING ERRCODE = 'PT422', DETAIL = 'template metadata must be an object';
  END IF;
  SELECT count(*) INTO v_key_count FROM jsonb_object_keys(p_template_metadata);
  IF v_key_count <> 6
     OR NOT p_template_metadata ?& ARRAY[
       'template_kind',
       'template_version',
       'dossier_id',
       'baseline_version_id',
       'baseline_revision',
       'generated_at'
     ]
     OR jsonb_typeof(p_template_metadata->'template_kind') <> 'string'
     OR jsonb_typeof(p_template_metadata->'template_version') <> 'number'
     OR jsonb_typeof(p_template_metadata->'dossier_id') <> 'string'
     OR jsonb_typeof(p_template_metadata->'baseline_version_id') <> 'string'
     OR jsonb_typeof(p_template_metadata->'baseline_revision') <> 'number'
     OR jsonb_typeof(p_template_metadata->'generated_at') <> 'string' THEN
    RAISE EXCEPTION 'template_mismatch'
      USING ERRCODE = 'PT422', DETAIL = 'template metadata has an invalid shape';
  END IF;

  BEGIN
    PERFORM (p_template_metadata->>'generated_at')::TIMESTAMPTZ;
    IF p_template_metadata->>'template_kind' <> 'technical_configuration_baseline'
       OR p_template_metadata->>'template_version' <> '2'
       OR (p_template_metadata->>'dossier_id')::UUID IS DISTINCT FROM v_dossier_id
       OR (p_template_metadata->>'baseline_version_id')::UUID
         IS DISTINCT FROM p_baseline_version_id
       OR (p_template_metadata->>'baseline_revision')::BIGINT
         IS DISTINCT FROM p_expected_revision THEN
      RAISE EXCEPTION 'template_mismatch'
        USING ERRCODE = 'PT422', DETAIL = 'template metadata does not match the target';
    END IF;
  EXCEPTION
    WHEN invalid_text_representation
      OR invalid_datetime_format
      OR datetime_field_overflow
      OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'template_mismatch'
        USING ERRCODE = 'PT422', DETAIL = 'template metadata contains invalid values';
  END;

  RETURN jsonb_build_object(
    'metadata', jsonb_build_object(
      'template_kind', 'technical_configuration_baseline',
      'template_version', 2,
      'dossier_id', v_dossier_id,
      'baseline_version_id', p_baseline_version_id,
      'baseline_revision', v_revision,
      'generated_at', p_template_metadata->>'generated_at'
    ),
    'next_criterion_number', v_next_criterion_number
  );
END;
$$;


ALTER FUNCTION public._technical_configuration_baseline_import_validate_metadata_v2(p_baseline_version_id uuid, p_template_metadata jsonb, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_baseline_import_validate_v2(uuid, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_baseline_import_validate_v2(p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_target JSONB;
  v_metadata JSONB;
  v_next_criterion_number BIGINT;
  v_current_groups JSONB;
  v_current_subgroups JSONB;
  v_current_criteria JSONB;
  v_normalized_rows JSONB := '[]'::JSONB;
  v_errors JSONB := '[]'::JSONB;
  v_counts JSONB;
  v_effects JSONB;
  v_row JSONB;
  v_existing JSONB;
  v_ordinality INTEGER;
  v_key_count INTEGER;
  v_physical_row INTEGER;
  v_error_count_before INTEGER;
  v_stt TEXT;
  v_content TEXT;
  v_group_id_text TEXT;
  v_subgroup_id_text TEXT;
  v_criterion_id_text TEXT;
  v_criterion_code TEXT;
  v_group_id UUID;
  v_subgroup_id UUID;
  v_criterion_id UUID;
  v_row_type TEXT;
  v_group_order INTEGER := 0;
  v_subgroup_order INTEGER := 0;
  v_criterion_order INTEGER := 0;
  v_target_group_id UUID;
  v_target_subgroup_id UUID;
  v_seen_group_ids UUID[] := ARRAY[]::UUID[];
  v_seen_subgroup_ids UUID[] := ARRAY[]::UUID[];
  v_seen_criterion_ids UUID[] := ARRAY[]::UUID[];
  v_new_criterion_count BIGINT := 0;
  v_existing_title TEXT;
  v_original_group_id UUID;
  v_original_subgroup_id UUID;
  v_original_order INTEGER;
BEGIN
  v_target := public._technical_configuration_baseline_import_validate_metadata_v2(
    p_baseline_version_id,
    p_template_metadata,
    p_expected_revision
  );
  v_metadata := v_target->'metadata';
  v_next_criterion_number := (v_target->>'next_criterion_number')::BIGINT;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'validation_error'
      USING ERRCODE = 'PT422', DETAIL = 'hierarchical rows must be an array';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', g.id, 'name', g.name, 'sort_order', g.sort_order
  )), '[]'::JSONB)
  INTO v_current_groups
  FROM public.technical_configuration_baseline_groups g
  WHERE g.baseline_version_id = p_baseline_version_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', sg.id, 'group_id', sg.group_id, 'name', sg.name, 'sort_order', sg.sort_order
  )), '[]'::JSONB)
  INTO v_current_subgroups
  FROM public.technical_configuration_baseline_subgroups sg
  WHERE sg.baseline_version_id = p_baseline_version_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id, 'group_id', c.group_id, 'subgroup_id', c.subgroup_id,
    'criterion_code', c.criterion_code, 'existing_title', c.title,
    'requirement_text', c.requirement_text, 'sort_order', c.sort_order
  )), '[]'::JSONB)
  INTO v_current_criteria
  FROM public.technical_configuration_baseline_criteria c
  WHERE c.baseline_version_id = p_baseline_version_id;

  FOR v_row, v_ordinality IN
    SELECT value, ordinality::INTEGER
    FROM jsonb_array_elements(p_rows) WITH ORDINALITY
  LOOP
    v_error_count_before := jsonb_array_length(v_errors);
    v_physical_row := v_ordinality + 1;
    v_stt := NULL; v_content := NULL; v_group_id_text := NULL;
    v_subgroup_id_text := NULL; v_criterion_id_text := NULL;
    v_criterion_code := NULL; v_group_id := NULL; v_subgroup_id := NULL;
    v_criterion_id := NULL; v_existing := NULL; v_existing_title := NULL;
    v_original_group_id := NULL; v_original_subgroup_id := NULL;
    v_original_order := NULL;

    IF jsonb_typeof(v_row) <> 'object' THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_physical_row, 'code', 'invalid_row_shape',
        'message', 'hierarchical row must be an object'
      ));
      CONTINUE;
    END IF;

    SELECT count(*) INTO v_key_count FROM jsonb_object_keys(v_row);
    IF v_key_count <> 7
       OR NOT v_row ?& ARRAY[
         'row', 'stt', 'content', 'group_id', 'subgroup_id',
         'criterion_id', 'criterion_code'
       ]
       OR jsonb_typeof(v_row->'row') <> 'number'
       OR jsonb_typeof(v_row->'stt') NOT IN ('string', 'number', 'null')
       OR jsonb_typeof(v_row->'content') NOT IN ('string', 'null')
       OR jsonb_typeof(v_row->'group_id') NOT IN ('string', 'null')
       OR jsonb_typeof(v_row->'subgroup_id') NOT IN ('string', 'null')
       OR jsonb_typeof(v_row->'criterion_id') NOT IN ('string', 'null')
       OR jsonb_typeof(v_row->'criterion_code') NOT IN ('string', 'null') THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_physical_row, 'code', 'invalid_row_shape',
        'message', 'hierarchical row has an invalid shape'
      ));
      CONTINUE;
    END IF;

    BEGIN
      IF (v_row->>'row') !~ '^[0-9]+$' OR (v_row->>'row')::INTEGER < 2 THEN
        RAISE EXCEPTION 'invalid physical row';
      END IF;
      v_physical_row := (v_row->>'row')::INTEGER;
    EXCEPTION
      WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_physical_row, 'code', 'invalid_row_shape', 'column', 'row',
          'message', 'row must be a physical worksheet row number'
        ));
        CONTINUE;
    END;

    v_stt := NULLIF(btrim(v_row->>'stt'), '');
    v_content := NULLIF(btrim(v_row->>'content'), '');
    v_group_id_text := NULLIF(btrim(v_row->>'group_id'), '');
    v_subgroup_id_text := NULLIF(btrim(v_row->>'subgroup_id'), '');
    v_criterion_id_text := NULLIF(btrim(v_row->>'criterion_id'), '');
    v_criterion_code := NULLIF(btrim(v_row->>'criterion_code'), '');

    IF v_stt IS NULL AND v_content IS NULL AND v_group_id_text IS NULL
       AND v_subgroup_id_text IS NULL AND v_criterion_id_text IS NULL
       AND v_criterion_code IS NULL THEN
      CONTINUE;
    END IF;

    IF v_stt IS NULL THEN
      v_row_type := 'CRITERION';
    ELSIF upper(v_stt) ~ '^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$' THEN
      v_row_type := 'GROUP';
    ELSIF v_stt ~ '^[1-9][0-9]*$' THEN
      v_row_type := 'SUBGROUP';
    ELSE
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_physical_row, 'code', 'unsupported_marker', 'column', 'stt',
        'message', 'STT must be a Roman numeral, positive integer, or blank'
      ));
      CONTINUE;
    END IF;

    IF v_content IS NULL THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_physical_row, 'code', 'empty_content', 'column', 'content',
        'message', 'content is required for every meaningful row'
      ));
      CONTINUE;
    END IF;

    IF v_row_type = 'GROUP' THEN
      IF v_subgroup_id_text IS NOT NULL OR v_criterion_id_text IS NOT NULL
         OR v_criterion_code IS NOT NULL THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_physical_row, 'code', 'wrong_identity_kind',
          'message', 'group rows may carry only group_id'
        ));
      END IF;
      IF v_group_id_text IS NOT NULL THEN
        BEGIN
          v_group_id := v_group_id_text::UUID;
          SELECT value INTO v_existing
          FROM jsonb_array_elements(v_current_groups)
          WHERE value->>'id' = v_group_id::TEXT;
          IF v_existing IS NULL THEN RAISE EXCEPTION 'foreign'; END IF;
          IF v_group_id = ANY(v_seen_group_ids) THEN
            v_errors := v_errors || jsonb_build_array(jsonb_build_object(
              'row', v_physical_row, 'code', 'duplicate_identity', 'column', 'group_id',
              'message', 'group_id appears more than once'
            ));
          END IF;
        EXCEPTION WHEN invalid_text_representation OR raise_exception THEN
          v_errors := v_errors || jsonb_build_array(jsonb_build_object(
            'row', v_physical_row, 'code', 'foreign_identity', 'column', 'group_id',
            'message', 'group_id does not belong to the target baseline'
          ));
        END;
      END IF;
      IF jsonb_array_length(v_errors) > v_error_count_before THEN CONTINUE; END IF;
      v_group_order := v_group_order + 1;
      v_subgroup_order := 0; v_criterion_order := 0;
      v_target_group_id := v_group_id; v_target_subgroup_id := NULL;
      IF v_group_id IS NOT NULL THEN
        v_seen_group_ids := array_append(v_seen_group_ids, v_group_id);
      END IF;
      v_normalized_rows := v_normalized_rows || jsonb_build_array(jsonb_build_object(
        'row', v_physical_row, 'row_type', 'GROUP',
        'group_id', v_group_id, 'group_name', v_content,
        'original_group_order', (v_existing->>'sort_order')::INTEGER,
        'target_group_order', v_group_order,
        'identity_fallback', v_group_id IS NULL
      ));
      CONTINUE;
    END IF;

    IF v_target_group_id IS NULL AND v_group_order = 0 THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_physical_row,
        'code', CASE WHEN v_row_type = 'SUBGROUP'
          THEN 'subgroup_without_section' ELSE 'content_before_section' END,
        'message', 'meaningful content must follow a main section'
      ));
      CONTINUE;
    END IF;

    IF v_row_type = 'SUBGROUP' THEN
      IF v_group_id_text IS NOT NULL OR v_criterion_id_text IS NOT NULL
         OR v_criterion_code IS NOT NULL THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_physical_row, 'code', 'wrong_identity_kind',
          'message', 'subgroup rows may carry only subgroup_id'
        ));
      END IF;
      IF v_subgroup_id_text IS NOT NULL THEN
        BEGIN
          v_subgroup_id := v_subgroup_id_text::UUID;
          SELECT value INTO v_existing
          FROM jsonb_array_elements(v_current_subgroups)
          WHERE value->>'id' = v_subgroup_id::TEXT;
          IF v_existing IS NULL THEN RAISE EXCEPTION 'foreign'; END IF;
          IF v_subgroup_id = ANY(v_seen_subgroup_ids) THEN
            v_errors := v_errors || jsonb_build_array(jsonb_build_object(
              'row', v_physical_row, 'code', 'duplicate_identity',
              'column', 'subgroup_id', 'message', 'subgroup_id appears more than once'
            ));
          END IF;
        EXCEPTION WHEN invalid_text_representation OR raise_exception THEN
          v_errors := v_errors || jsonb_build_array(jsonb_build_object(
            'row', v_physical_row, 'code', 'foreign_identity', 'column', 'subgroup_id',
            'message', 'subgroup_id does not belong to the target baseline'
          ));
        END;
      END IF;
      IF jsonb_array_length(v_errors) > v_error_count_before THEN CONTINUE; END IF;
      v_subgroup_order := v_subgroup_order + 1;
      v_target_subgroup_id := v_subgroup_id;
      IF v_subgroup_id IS NOT NULL THEN
        v_seen_subgroup_ids := array_append(v_seen_subgroup_ids, v_subgroup_id);
      END IF;
      v_normalized_rows := v_normalized_rows || jsonb_build_array(jsonb_build_object(
        'row', v_physical_row, 'row_type', 'SUBGROUP',
        'subgroup_id', v_subgroup_id, 'subgroup_name', v_content,
        'original_group_id', v_existing->>'group_id',
        'original_subgroup_order', (v_existing->>'sort_order')::INTEGER,
        'target_group_id', v_target_group_id,
        'target_group_order', v_group_order,
        'target_subgroup_order', v_subgroup_order,
        'identity_fallback', v_subgroup_id IS NULL
      ));
      CONTINUE;
    END IF;

    IF v_group_id_text IS NOT NULL OR v_subgroup_id_text IS NOT NULL THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_physical_row, 'code', 'wrong_identity_kind',
        'message', 'criterion rows may carry only criterion_id and criterion_code'
      ));
    END IF;
    IF (v_criterion_id_text IS NULL) <> (v_criterion_code IS NULL) THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_physical_row, 'code', 'partial_identity',
        'message', 'criterion_id and criterion_code must be both present or both absent'
      ));
    ELSIF v_criterion_id_text IS NOT NULL THEN
      BEGIN
        v_criterion_id := v_criterion_id_text::UUID;
        SELECT value INTO v_existing
        FROM jsonb_array_elements(v_current_criteria)
        WHERE value->>'id' = v_criterion_id::TEXT;
        IF v_existing IS NULL THEN RAISE EXCEPTION 'foreign'; END IF;
        IF v_existing->>'criterion_code' <> v_criterion_code THEN
          v_errors := v_errors || jsonb_build_array(jsonb_build_object(
            'row', v_physical_row, 'code', 'changed_criterion_code',
            'column', 'criterion_code', 'message', 'criterion_code does not match identity'
          ));
        END IF;
        IF v_criterion_id = ANY(v_seen_criterion_ids) THEN
          v_errors := v_errors || jsonb_build_array(jsonb_build_object(
            'row', v_physical_row, 'code', 'duplicate_identity', 'column', 'criterion_id',
            'message', 'criterion_id appears more than once'
          ));
        END IF;
      EXCEPTION WHEN invalid_text_representation OR raise_exception THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_physical_row, 'code', 'foreign_identity', 'column', 'criterion_id',
          'message', 'criterion_id does not belong to the target baseline'
        ));
      END;
    END IF;
    IF jsonb_array_length(v_errors) > v_error_count_before THEN CONTINUE; END IF;

    v_criterion_order := v_criterion_order + 1;
    IF v_criterion_id IS NULL THEN
      v_criterion_code := 'TC-' || lpad(
        (v_next_criterion_number + v_new_criterion_count)::TEXT,
        GREATEST(4, length((v_next_criterion_number + v_new_criterion_count)::TEXT)),
        '0'
      );
      v_new_criterion_count := v_new_criterion_count + 1;
    ELSE
      v_seen_criterion_ids := array_append(v_seen_criterion_ids, v_criterion_id);
      v_existing_title := v_existing->>'existing_title';
      v_original_group_id := (v_existing->>'group_id')::UUID;
      v_original_subgroup_id := NULLIF(v_existing->>'subgroup_id', '')::UUID;
      v_original_order := (v_existing->>'sort_order')::INTEGER;
    END IF;
    v_normalized_rows := v_normalized_rows || jsonb_build_array(jsonb_build_object(
      'row', v_physical_row, 'row_type', 'CRITERION',
      'criterion_id', v_criterion_id, 'criterion_code', v_criterion_code,
      'existing_title', v_existing_title, 'requirement_text', v_content,
      'original_group_id', v_original_group_id,
      'original_subgroup_id', v_original_subgroup_id,
      'original_criterion_order', v_original_order,
      'target_group_id', v_target_group_id,
      'target_subgroup_id', v_target_subgroup_id,
      'target_group_order', v_group_order,
      'target_subgroup_order', NULLIF(v_subgroup_order, 0),
      'target_criterion_order', v_criterion_order,
      'identity_fallback', v_criterion_id IS NULL
    ));
  END LOOP;

  WITH rows AS (
    SELECT value AS row FROM jsonb_array_elements(v_normalized_rows)
  )
  SELECT jsonb_build_object(
    'groups', count(*) FILTER (WHERE row->>'row_type' = 'GROUP'),
    'subgroups', count(*) FILTER (WHERE row->>'row_type' = 'SUBGROUP'),
    'criteria', count(*) FILTER (WHERE row->>'row_type' = 'CRITERION')
  ) INTO v_counts
  FROM rows;

  IF jsonb_array_length(v_errors) = 0 THEN
    WITH
    rows AS (SELECT value AS row FROM jsonb_array_elements(v_normalized_rows)),
    groups AS (SELECT row FROM rows WHERE row->>'row_type' = 'GROUP'),
    subgroups AS (SELECT row FROM rows WHERE row->>'row_type' = 'SUBGROUP'),
    criteria AS (SELECT row FROM rows WHERE row->>'row_type' = 'CRITERION')
    SELECT jsonb_build_object(
    'groups', jsonb_build_object(
      'create', (SELECT count(*) FROM groups WHERE row->>'group_id' IS NULL),
      'update', (SELECT count(*) FROM groups WHERE row->>'group_id' IS NOT NULL
        AND row->>'group_name' IS DISTINCT FROM (
          SELECT value->>'name' FROM jsonb_array_elements(v_current_groups)
          WHERE value->>'id' = groups.row->>'group_id')),
      'move', (SELECT count(*) FROM groups WHERE row->>'group_id' IS NOT NULL
        AND (row->>'original_group_order')::INTEGER
          IS DISTINCT FROM (row->>'target_group_order')::INTEGER),
      'delete', (SELECT count(*) FROM jsonb_array_elements(v_current_groups) current_row
        WHERE NOT EXISTS (SELECT 1 FROM groups
          WHERE groups.row->>'group_id' = current_row->>'id'))
    ),
    'subgroups', jsonb_build_object(
      'create', (SELECT count(*) FROM subgroups WHERE row->>'subgroup_id' IS NULL),
      'update', (SELECT count(*) FROM subgroups WHERE row->>'subgroup_id' IS NOT NULL
        AND row->>'subgroup_name' IS DISTINCT FROM (
          SELECT value->>'name' FROM jsonb_array_elements(v_current_subgroups)
          WHERE value->>'id' = subgroups.row->>'subgroup_id')),
      'move', (SELECT count(*) FROM subgroups WHERE row->>'subgroup_id' IS NOT NULL
        AND ((row->>'original_group_id')::UUID
          IS DISTINCT FROM NULLIF(row->>'target_group_id', '')::UUID
          OR (row->>'original_subgroup_order')::INTEGER
          IS DISTINCT FROM (row->>'target_subgroup_order')::INTEGER)),
      'delete', (SELECT count(*) FROM jsonb_array_elements(v_current_subgroups) current_row
        WHERE NOT EXISTS (SELECT 1 FROM subgroups
          WHERE subgroups.row->>'subgroup_id' = current_row->>'id'))
    ),
    'criteria', jsonb_build_object(
      'create', (SELECT count(*) FROM criteria WHERE row->>'criterion_id' IS NULL),
      'update', (SELECT count(*) FROM criteria WHERE row->>'criterion_id' IS NOT NULL
        AND row->>'requirement_text' IS DISTINCT FROM (
          SELECT value->>'requirement_text' FROM jsonb_array_elements(v_current_criteria)
          WHERE value->>'id' = criteria.row->>'criterion_id')),
      'move', (SELECT count(*) FROM criteria WHERE row->>'criterion_id' IS NOT NULL
        AND ((row->>'original_group_id')::UUID
          IS DISTINCT FROM NULLIF(row->>'target_group_id', '')::UUID
          OR NULLIF(row->>'original_subgroup_id', '')::UUID
          IS DISTINCT FROM NULLIF(row->>'target_subgroup_id', '')::UUID
          OR (row->>'original_criterion_order')::INTEGER
          IS DISTINCT FROM (row->>'target_criterion_order')::INTEGER)),
      'delete', (SELECT count(*) FROM jsonb_array_elements(v_current_criteria) current_row
        WHERE NOT EXISTS (SELECT 1 FROM criteria
          WHERE criteria.row->>'criterion_id' = current_row->>'id'))
    )
    ) INTO v_effects;
  END IF;

  RETURN jsonb_build_object(
    'metadata', v_metadata,
    'normalized_rows', v_normalized_rows,
    'row_errors', v_errors,
    'counts', v_counts,
    'effects', v_effects
  );
END;
$_$;


ALTER FUNCTION public._technical_configuration_baseline_import_validate_v2(p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_baseline_normalize_group(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_baseline_normalize_group(p_group_id uuid, p_user_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  SET CONSTRAINTS tc_baseline_subgroups_group_sort_key DEFERRED;
  SET CONSTRAINTS technical_configuration_baseline_criteria_group_sort_key DEFERRED;

  WITH ordered_subgroups AS (
    SELECT
      s.id,
      row_number() OVER (ORDER BY s.sort_order, s.id)::INTEGER AS new_order
    FROM public.technical_configuration_baseline_subgroups s
    WHERE s.group_id = p_group_id
  )
  UPDATE public.technical_configuration_baseline_subgroups s
  SET sort_order = ordered_subgroups.new_order,
      updated_at = now(),
      updated_by = p_user_id
  FROM ordered_subgroups
  WHERE s.id = ordered_subgroups.id
    AND s.sort_order <> ordered_subgroups.new_order;

  WITH ordered_criteria AS (
    SELECT
      c.id,
      row_number() OVER (
        ORDER BY
          CASE WHEN c.subgroup_id IS NULL THEN 0 ELSE 1 END,
          s.sort_order NULLS FIRST,
          c.sort_order,
          c.id
      )::INTEGER AS new_order
    FROM public.technical_configuration_baseline_criteria c
    LEFT JOIN public.technical_configuration_baseline_subgroups s
      ON s.id = c.subgroup_id
     AND s.group_id = c.group_id
     AND s.baseline_version_id = c.baseline_version_id
    WHERE c.group_id = p_group_id
  )
  UPDATE public.technical_configuration_baseline_criteria c
  SET sort_order = ordered_criteria.new_order,
      updated_at = now(),
      updated_by = p_user_id
  FROM ordered_criteria
  WHERE c.id = ordered_criteria.id
    AND c.sort_order <> ordered_criteria.new_order;
END;
$$;


ALTER FUNCTION public._technical_configuration_baseline_normalize_group(p_group_id uuid, p_user_id bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_baseline_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_baseline_snapshot(p_baseline_version_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH direct_criteria_by_group AS (
    SELECT
      c.group_id,
      jsonb_agg(
        jsonb_build_object(
          'id', c.id, 'baseline_version_id', c.baseline_version_id,
          'group_id', c.group_id, 'subgroup_id', c.subgroup_id,
          'criterion_code', c.criterion_code, 'title', c.title,
          'requirement_text', c.requirement_text, 'sort_order', c.sort_order,
          'source_criterion_id', c.source_criterion_id, 'created_at', c.created_at,
          'created_by', c.created_by, 'updated_at', c.updated_at, 'updated_by', c.updated_by
        )
        ORDER BY c.sort_order, c.id
      ) AS criteria
    FROM public.technical_configuration_baseline_criteria c
    WHERE c.baseline_version_id = p_baseline_version_id
      AND c.subgroup_id IS NULL
    GROUP BY c.group_id
  ),
  criteria_by_subgroup AS (
    SELECT
      c.subgroup_id,
      jsonb_agg(
        jsonb_build_object(
          'id', c.id, 'baseline_version_id', c.baseline_version_id,
          'group_id', c.group_id, 'subgroup_id', c.subgroup_id,
          'criterion_code', c.criterion_code, 'title', c.title,
          'requirement_text', c.requirement_text, 'sort_order', c.sort_order,
          'source_criterion_id', c.source_criterion_id, 'created_at', c.created_at,
          'created_by', c.created_by, 'updated_at', c.updated_at, 'updated_by', c.updated_by
        )
        ORDER BY c.sort_order, c.id
      ) AS criteria
    FROM public.technical_configuration_baseline_criteria c
    WHERE c.baseline_version_id = p_baseline_version_id
      AND c.subgroup_id IS NOT NULL
    GROUP BY c.subgroup_id
  ),
  subgroups_by_group AS (
    SELECT
      sg.group_id,
      jsonb_agg(
        jsonb_build_object(
          'id', sg.id, 'baseline_version_id', sg.baseline_version_id,
          'group_id', sg.group_id, 'name', sg.name, 'sort_order', sg.sort_order,
          'created_at', sg.created_at, 'created_by', sg.created_by,
          'updated_at', sg.updated_at, 'updated_by', sg.updated_by,
          'criteria', COALESCE(cbs.criteria, '[]'::JSONB)
        )
        ORDER BY sg.sort_order, sg.id
      ) AS subgroups
    FROM public.technical_configuration_baseline_subgroups sg
    LEFT JOIN criteria_by_subgroup cbs ON cbs.subgroup_id = sg.id
    WHERE sg.baseline_version_id = p_baseline_version_id
    GROUP BY sg.group_id
  ),
  groups_by_version AS (
    SELECT
      g.baseline_version_id,
      jsonb_agg(
        jsonb_build_object(
          'id', g.id, 'baseline_version_id', g.baseline_version_id,
          'name', g.name, 'sort_order', g.sort_order,
          'created_at', g.created_at, 'created_by', g.created_by,
          'updated_at', g.updated_at, 'updated_by', g.updated_by,
          'criteria', COALESCE(dcbg.criteria, '[]'::JSONB),
          'subgroups', COALESCE(sbg.subgroups, '[]'::JSONB)
        )
        ORDER BY g.sort_order, g.id
      ) AS groups
    FROM public.technical_configuration_baseline_groups g
    LEFT JOIN direct_criteria_by_group dcbg ON dcbg.group_id = g.id
    LEFT JOIN subgroups_by_group sbg ON sbg.group_id = g.id
    WHERE g.baseline_version_id = p_baseline_version_id
    GROUP BY g.baseline_version_id
  )
  SELECT jsonb_build_object(
    'id', v.id, 'dossier_id', v.dossier_id,
    'version_number', v.version_number, 'status', v.status,
    'source_baseline_version_id', v.source_baseline_version_id,
    'source_version_number', source_version.version_number,
    'next_criterion_number', v.next_criterion_number, 'revision', v.revision,
    'locked_at', v.locked_at, 'locked_by', v.locked_by,
    'created_at', v.created_at, 'created_by', v.created_by,
    'updated_at', v.updated_at, 'updated_by', v.updated_by,
    'groups', COALESCE(gbv.groups, '[]'::JSONB)
  )
  FROM public.technical_configuration_baseline_versions v
  LEFT JOIN public.technical_configuration_baseline_versions source_version
    ON source_version.id = v.source_baseline_version_id
  LEFT JOIN groups_by_version gbv ON gbv.baseline_version_id = v.id
  WHERE v.id = p_baseline_version_id;
$$;


ALTER FUNCTION public._technical_configuration_baseline_snapshot(p_baseline_version_id uuid) OWNER TO postgres;

