--
-- Name: _technical_configuration_citation_payload(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_citation_payload(p_owner_type text, p_citation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_payload JSONB;
BEGIN
  IF p_owner_type = 'baseline' THEN
    SELECT jsonb_build_object('id', id, 'criterion_id', criterion_id,
      'page_section', page_section, 'excerpt', excerpt)
    INTO v_payload FROM public.technical_configuration_baseline_citations
    WHERE id = p_citation_id;
  ELSE
    SELECT jsonb_build_object('id', id, 'criterion_id', criterion_id,
      'page_section', page_section, 'excerpt', excerpt)
    INTO v_payload FROM public.technical_configuration_reference_citations
    WHERE id = p_citation_id;
  END IF;
  RETURN v_payload;
END;
$$;


ALTER FUNCTION public._technical_configuration_citation_payload(p_owner_type text, p_citation_id uuid) OWNER TO postgres;

--
-- Name: _technical_configuration_derived_status(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_derived_status(p_technical_axis text, p_evidence_axis text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN p_technical_axis IS NULL THEN 'not_evaluated'
    WHEN p_technical_axis = 'not_applicable' THEN 'not_applicable'
    WHEN p_technical_axis = 'fails' THEN 'fails'
    WHEN p_technical_axis = 'unclear' THEN 'unclear'
    WHEN p_evidence_axis IS NULL THEN 'not_evaluated'
    WHEN p_evidence_axis IN ('partial', 'missing') THEN 'insufficient_evidence'
    ELSE p_technical_axis
  END;
$$;


ALTER FUNCTION public._technical_configuration_derived_status(p_technical_axis text, p_evidence_axis text) OWNER TO postgres;

--
-- Name: _technical_configuration_document_payload(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_document_payload(p_owner_type text, p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_payload JSONB;
BEGIN
  IF p_owner_type = 'baseline' THEN
    SELECT jsonb_build_object(
      'id', d.id, 'owner_type', 'baseline', 'owner_id', d.baseline_version_id,
      'name', d.name, 'url', d.url, 'created_by', d.created_by,
      'created_at', d.created_at, 'updated_at', d.updated_at, 'citations',
      COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id', c.id, 'criterion_id', c.criterion_id,
        'page_section', c.page_section, 'excerpt', c.excerpt
      ) ORDER BY c.created_at, c.id)
      FROM public.technical_configuration_baseline_citations c
      WHERE c.baseline_document_id = d.id), '[]'::JSONB)
    ) INTO v_payload FROM public.technical_configuration_baseline_documents d
    WHERE d.id = p_document_id;
  ELSE
    SELECT jsonb_build_object(
      'id', d.id, 'owner_type', 'reference_product', 'owner_id', d.reference_product_id,
      'name', d.name, 'url', d.url, 'created_by', d.created_by,
      'created_at', d.created_at, 'updated_at', d.updated_at, 'citations',
      COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id', c.id, 'criterion_id', c.criterion_id,
        'page_section', c.page_section, 'excerpt', c.excerpt
      ) ORDER BY c.created_at, c.id)
      FROM public.technical_configuration_reference_citations c
      WHERE c.reference_document_id = d.id), '[]'::JSONB)
    ) INTO v_payload FROM public.technical_configuration_reference_documents d
    WHERE d.id = p_document_id;
  END IF;
  RETURN v_payload;
END;
$$;


ALTER FUNCTION public._technical_configuration_document_payload(p_owner_type text, p_document_id uuid) OWNER TO postgres;

--
-- Name: _technical_configuration_normalize_supplier_name(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_normalize_supplier_name(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT lower(btrim(regexp_replace(p_name, '[[:space:]]+', ' ', 'g')));
$$;


ALTER FUNCTION public._technical_configuration_normalize_supplier_name(p_name text) OWNER TO postgres;

