--
-- Name: _technical_configuration_option_document_payload(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_option_document_payload(p_option_document_id uuid, p_baseline_version_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'id', d.id,
    'option_id', d.option_id,
    'name', d.name,
    'url', d.url,
    'created_by', d.created_by,
    'created_at', d.created_at,
    'updated_at', d.updated_at,
    'affected_citation_count', (
      SELECT count(*)
      FROM public.technical_configuration_option_citations linked
      WHERE linked.option_document_id = d.id
    ),
    'citations', CASE
      WHEN p_baseline_version_id IS NULL THEN '[]'::JSONB
      ELSE COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', c.id,
          'criterion_id', c.criterion_id,
          'page_section', c.page_section,
          'excerpt', c.excerpt
        ) ORDER BY c.created_at, c.id)
        FROM public.technical_configuration_option_citations c
        WHERE c.option_document_id = d.id
          AND c.option_id = d.option_id
          AND c.baseline_version_id = p_baseline_version_id
      ), '[]'::JSONB)
    END
  )
  FROM public.technical_configuration_option_documents d
  WHERE d.id = p_option_document_id;
$$;


ALTER FUNCTION public._technical_configuration_option_document_payload(p_option_document_id uuid, p_baseline_version_id uuid) OWNER TO postgres;

--
-- Name: _technical_configuration_option_import_validate(uuid, uuid, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_option_import_validate(p_option_id uuid, p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_dossier_id UUID;
  v_version_dossier_id UUID;
  v_revision BIGINT;
  v_archived_at TIMESTAMPTZ;
  v_key_count INTEGER;
  v_row JSONB;
  v_row_number INTEGER;
  v_group_order INTEGER;
  v_criterion_order INTEGER;
  v_criterion_id UUID;
  v_target JSONB;
  v_targets JSONB;
  v_target_criterion_ids UUID[];
  v_seen_criterion_ids UUID[] := ARRAY[]::UUID[];
  v_normalized_rows JSONB := '[]'::JSONB;
  v_errors JSONB := '[]'::JSONB;
BEGIN
  SELECT o.dossier_id
  INTO v_dossier_id
  FROM public.technical_configuration_options o
  WHERE o.id = p_option_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  SELECT v.dossier_id
  INTO v_version_dossier_id
  FROM public.technical_configuration_baseline_versions v
  WHERE v.id = p_baseline_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  IF v_dossier_id IS DISTINCT FROM v_version_dossier_id THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  SELECT d.revision, d.archived_at
  INTO v_revision, v_archived_at
  FROM public.technical_configuration_dossiers d
  WHERE d.id = v_dossier_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  IF v_archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived_dossier' USING ERRCODE = 'PT409';
  END IF;
  IF v_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'stale_revision' USING ERRCODE = 'PT409';
  END IF;
  IF p_template_metadata IS NULL
     OR jsonb_typeof(p_template_metadata) <> 'object' THEN
    RAISE EXCEPTION 'template_mismatch'
      USING ERRCODE = 'PT422', DETAIL = 'template metadata must be an object';
  END IF;
  SELECT count(*) INTO v_key_count FROM jsonb_object_keys(p_template_metadata);
  IF v_key_count <> 7
     OR NOT p_template_metadata ?& ARRAY[
       'template_kind',
       'template_version',
       'dossier_id',
       'option_id',
       'baseline_version_id',
       'dossier_revision',
       'generated_at'
     ]
     OR jsonb_typeof(p_template_metadata->'template_kind') <> 'string'
     OR jsonb_typeof(p_template_metadata->'template_version') <> 'number'
     OR jsonb_typeof(p_template_metadata->'dossier_id') <> 'string'
     OR jsonb_typeof(p_template_metadata->'option_id') <> 'string'
     OR jsonb_typeof(p_template_metadata->'baseline_version_id') <> 'string'
     OR jsonb_typeof(p_template_metadata->'dossier_revision') <> 'number'
     OR jsonb_typeof(p_template_metadata->'generated_at') <> 'string' THEN
    RAISE EXCEPTION 'template_mismatch'
      USING ERRCODE = 'PT422', DETAIL = 'template metadata has an invalid shape';
  END IF;
  BEGIN
    PERFORM (p_template_metadata->>'generated_at')::TIMESTAMPTZ;
    IF p_template_metadata->>'template_kind' <> 'technical_configuration_option'
       OR p_template_metadata->>'template_version' <> '1'
       OR (p_template_metadata->>'dossier_id')::UUID IS DISTINCT FROM v_dossier_id
       OR (p_template_metadata->>'option_id')::UUID IS DISTINCT FROM p_option_id
       OR (p_template_metadata->>'baseline_version_id')::UUID
         IS DISTINCT FROM p_baseline_version_id
       OR (p_template_metadata->>'dossier_revision')::BIGINT
         IS DISTINCT FROM p_expected_revision THEN
      RAISE EXCEPTION 'template_mismatch'
        USING ERRCODE = 'PT422', DETAIL = 'template metadata does not match the target';
    END IF;
  EXCEPTION
    WHEN invalid_text_representation
      OR invalid_datetime_format
      OR datetime_field_overflow
      OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'template_mismatch'
        USING ERRCODE = 'PT422', DETAIL = 'template metadata contains invalid values';
  END;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'validation_error'
      USING ERRCODE = 'PT422', DETAIL = 'canonical rows must be an array';
  END IF;
  SELECT
    COALESCE(
      jsonb_object_agg(
        c.id::TEXT,
        jsonb_build_object(
          'group_order', g.sort_order,
          'group_name', g.name,
          'criterion_order', c.sort_order,
          'criterion_code', c.criterion_code,
          'criterion_title', c.title,
          'requirement_text', c.requirement_text
        )
      ),
      '{}'::JSONB
    ),
    COALESCE(
      array_agg(c.id ORDER BY g.sort_order, c.sort_order, c.id),
      ARRAY[]::UUID[]
    )
  INTO v_targets, v_target_criterion_ids
  FROM public.technical_configuration_baseline_criteria c
  JOIN public.technical_configuration_baseline_groups g
    ON g.id = c.group_id
   AND g.baseline_version_id = c.baseline_version_id
  WHERE c.baseline_version_id = p_baseline_version_id;
  FOR v_row, v_row_number IN
    SELECT value, ordinality::INTEGER
    FROM jsonb_array_elements(p_rows) WITH ORDINALITY
  LOOP
    IF jsonb_typeof(v_row) <> 'object' THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_row_number, 'code', 'invalid_row_shape',
        'message', 'canonical row must be an object'
      ));
      CONTINUE;
    END IF;
    SELECT count(*) INTO v_key_count FROM jsonb_object_keys(v_row);
    IF v_key_count <> 9
       OR NOT v_row ?& ARRAY[
         'group_order',
         'group_name',
         'criterion_order',
         'criterion_id',
         'criterion_code',
         'criterion_title',
         'requirement_text',
         'response_text',
         'supplementary_information'
       ]
       OR jsonb_typeof(v_row->'group_order') <> 'number'
       OR jsonb_typeof(v_row->'group_name') <> 'string'
       OR jsonb_typeof(v_row->'criterion_order') <> 'number'
       OR jsonb_typeof(v_row->'criterion_id') <> 'string'
       OR jsonb_typeof(v_row->'criterion_code') <> 'string'
       OR jsonb_typeof(v_row->'criterion_title') NOT IN ('string', 'null')
       OR jsonb_typeof(v_row->'requirement_text') <> 'string'
       OR jsonb_typeof(v_row->'response_text') <> 'string'
       OR jsonb_typeof(v_row->'supplementary_information') <> 'string'
       OR v_row->>'group_order' !~ '^[0-9]+$'
       OR v_row->>'criterion_order' !~ '^[0-9]+$' THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_row_number, 'code', 'invalid_row_shape',
        'message', 'canonical row has unsupported or missing fields'
      ));
      CONTINUE;
    END IF;
    BEGIN
      v_group_order := (v_row->>'group_order')::INTEGER;
      v_criterion_order := (v_row->>'criterion_order')::INTEGER;
      v_criterion_id := (v_row->>'criterion_id')::UUID;
    EXCEPTION
      WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'row', v_row_number, 'code', 'invalid_row_shape',
          'message', 'canonical row contains invalid identifiers or order values'
        ));
        CONTINUE;
    END;
    IF v_group_order <= 0 OR v_criterion_order <= 0 THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_row_number, 'code', 'invalid_row_shape',
        'message', 'canonical row order values must be positive'
      ));
      CONTINUE;
    END IF;
    IF v_criterion_id = ANY(v_seen_criterion_ids) THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_row_number, 'criterion_id', v_criterion_id,
        'code', 'duplicate_criterion', 'message', 'criterion is duplicated'
      ));
      CONTINUE;
    END IF;
    v_seen_criterion_ids := array_append(v_seen_criterion_ids, v_criterion_id);
    v_target := v_targets->v_criterion_id::TEXT;
    IF v_target IS NULL THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_row_number, 'criterion_id', v_criterion_id,
        'code', 'unknown_criterion', 'message', 'criterion does not belong to the target'
      ));
      CONTINUE;
    END IF;
    IF v_group_order IS DISTINCT FROM (v_target->>'group_order')::INTEGER
       OR v_row->>'group_name' IS DISTINCT FROM v_target->>'group_name'
       OR v_criterion_order IS DISTINCT FROM (v_target->>'criterion_order')::INTEGER
       OR v_row->>'criterion_code' IS DISTINCT FROM v_target->>'criterion_code'
       OR (CASE
         WHEN v_row->'criterion_title' = 'null'::JSONB THEN NULL
         ELSE v_row->>'criterion_title'
       END) IS DISTINCT FROM v_target->>'criterion_title'
       OR v_row->>'requirement_text' IS DISTINCT FROM v_target->>'requirement_text' THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'row', v_row_number, 'criterion_id', v_criterion_id,
        'code', 'changed_context', 'message', 'read-only criterion context was changed'
      ));
      CONTINUE;
    END IF;
    v_normalized_rows := v_normalized_rows || jsonb_build_array(jsonb_build_object(
      'group_order', (v_target->>'group_order')::INTEGER,
      'group_name', v_target->>'group_name',
      'criterion_order', (v_target->>'criterion_order')::INTEGER,
      'criterion_id', v_criterion_id,
      'criterion_code', v_target->>'criterion_code',
      'criterion_title', v_target->'criterion_title',
      'requirement_text', v_target->>'requirement_text',
      'response_text', v_row->>'response_text',
      'supplementary_information', v_row->>'supplementary_information'
    ));
  END LOOP;
  FOREACH v_criterion_id IN ARRAY v_target_criterion_ids LOOP
    IF NOT (v_criterion_id = ANY(v_seen_criterion_ids)) THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'criterion_id', v_criterion_id, 'code', 'missing_criterion',
        'message', 'criterion is missing from the complete snapshot'
      ));
    END IF;
  END LOOP;
  RETURN jsonb_build_object(
    'dossier_id', v_dossier_id,
    'metadata', jsonb_build_object(
      'template_kind', 'technical_configuration_option',
      'template_version', 1,
      'dossier_id', v_dossier_id,
      'option_id', p_option_id,
      'baseline_version_id', p_baseline_version_id,
      'dossier_revision', v_revision,
      'generated_at', p_template_metadata->>'generated_at'
    ),
    'rows', v_normalized_rows,
    'row_errors', v_errors
  );
END;
$_$;


ALTER FUNCTION public._technical_configuration_option_import_validate(p_option_id uuid, p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_reference_product_payload(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_reference_product_payload(p_reference_product_id uuid, p_revision bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'id', p.id, 'baseline_version_id', p.baseline_version_id,
    'model', p.model, 'manufacturer', p.manufacturer,
    'description', p.description, 'notes', p.notes,
    'created_at', p.created_at, 'created_by', p.created_by,
    'updated_at', p.updated_at, 'updated_by', p.updated_by,
    'revision', p_revision,
    'responses', COALESCE((
      SELECT jsonb_agg(
        public._technical_configuration_reference_response_payload(r.id, p_revision)
        ORDER BY c.sort_order, c.id
      )
      FROM public.technical_configuration_reference_responses r
      JOIN public.technical_configuration_baseline_criteria c
        ON c.id = r.criterion_id
       AND c.baseline_version_id = r.baseline_version_id
      WHERE r.reference_product_id = p.id
    ), '[]'::JSONB)
  )
  FROM public.technical_configuration_reference_products p
  WHERE p.id = p_reference_product_id;
$$;


ALTER FUNCTION public._technical_configuration_reference_product_payload(p_reference_product_id uuid, p_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_reference_ranking_snapshot(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_reference_ranking_snapshot(p_dossier_id uuid, p_baseline_version_id uuid) RETURNS TABLE(option_id uuid, rank_value bigint, supplier_normalized_name text, identity_label text, ranking_item jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH canonical_criteria AS MATERIALIZED (
    SELECT criterion.id AS criterion_id
    FROM public.technical_configuration_baseline_criteria criterion
    WHERE criterion.baseline_version_id = p_baseline_version_id
  ),
  option_universe AS MATERIALIZED (
    SELECT
      option_row.id AS option_id,
      option_row.supplier_id,
      supplier.name AS supplier_name,
      supplier.normalized_name AS supplier_normalized_name,
      COALESCE(option_row.model, option_row.option_name) AS identity_label,
      public._technical_configuration_option_display_label(
        supplier.name,
        option_row.model,
        option_row.option_name
      ) AS display_label
    FROM public.technical_configuration_options option_row
    JOIN public.technical_configuration_suppliers supplier
      ON supplier.id = option_row.supplier_id
     AND supplier.dossier_id = option_row.dossier_id
    WHERE option_row.dossier_id = p_dossier_id
  ),
  scored AS MATERIALIZED (
    SELECT
      option_row.option_id,
      option_row.supplier_id,
      option_row.supplier_name,
      option_row.supplier_normalized_name,
      option_row.identity_label,
      option_row.display_label,
      CASE
        WHEN criterion.criterion_id IS NULL THEN 0
        WHEN assessment.technical_axis = 'not_applicable' THEN 0
        WHEN assessment.technical_axis IS NULL
          OR assessment.evidence_axis IS NULL THEN 1
        ELSE 0
      END AS incomplete_criterion,
      CASE WHEN criterion.criterion_id IS NULL THEN NULL
        ELSE public._technical_configuration_derived_status(
          assessment.technical_axis,
          assessment.evidence_axis
        )
      END AS derived_status
    FROM option_universe option_row
    LEFT JOIN canonical_criteria criterion ON TRUE
    LEFT JOIN public.technical_configuration_comparison_sets comparison_set
      ON comparison_set.option_id = option_row.option_id
     AND comparison_set.baseline_version_id = p_baseline_version_id
     AND comparison_set.dossier_id = p_dossier_id
    LEFT JOIN public.technical_configuration_manual_assessments assessment
      ON assessment.comparison_set_id = comparison_set.id
     AND assessment.baseline_version_id = p_baseline_version_id
     AND assessment.criterion_id = criterion.criterion_id
  ),
  aggregated AS MATERIALIZED (
    SELECT
      scored.option_id,
      scored.supplier_id,
      scored.supplier_name,
      scored.supplier_normalized_name,
      scored.identity_label,
      scored.display_label,
      COUNT(*) FILTER (WHERE scored.incomplete_criterion = 1)
        AS incomplete_criterion_count,
      COUNT(*) FILTER (WHERE scored.derived_status = 'fails') AS failed_count,
      COUNT(*) FILTER (WHERE scored.derived_status = 'insufficient_evidence')
        AS insufficient_evidence_count,
      COUNT(*) FILTER (WHERE scored.derived_status = 'exceeds') AS exceeds_count
    FROM scored
    GROUP BY
      scored.option_id,
      scored.supplier_id,
      scored.supplier_name,
      scored.supplier_normalized_name,
      scored.identity_label,
      scored.display_label
  ),
  eligible_ranked AS MATERIALIZED (
    SELECT
      aggregated.option_id,
      DENSE_RANK() OVER (
        ORDER BY
          aggregated.failed_count,
          aggregated.insufficient_evidence_count,
          aggregated.exceeds_count DESC
      ) AS rank
    FROM aggregated
    WHERE aggregated.incomplete_criterion_count = 0
  )
  SELECT
    aggregated.option_id,
    eligible.rank,
    aggregated.supplier_normalized_name,
    aggregated.identity_label,
    jsonb_build_object(
          'option_id', aggregated.option_id,
          'supplier_id', aggregated.supplier_id,
          'supplier_name', aggregated.supplier_name,
          'display_label', aggregated.display_label,
          'eligibility', CASE
            WHEN aggregated.incomplete_criterion_count = 0 THEN 'eligible'
            ELSE 'incomplete'
          END,
          'incomplete_criterion_count', aggregated.incomplete_criterion_count,
          'failed_count', aggregated.failed_count,
          'insufficient_evidence_count', aggregated.insufficient_evidence_count,
          'exceeds_count', aggregated.exceeds_count,
          'rank', eligible.rank
        )
  FROM aggregated
  LEFT JOIN eligible_ranked eligible ON eligible.option_id = aggregated.option_id;
$$;


ALTER FUNCTION public._technical_configuration_reference_ranking_snapshot(p_dossier_id uuid, p_baseline_version_id uuid) OWNER TO postgres;

--
-- Name: _technical_configuration_reference_ranking_token(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_reference_ranking_token(p_dossier_id uuid, p_baseline_version_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT md5(concat_ws(
    '|',
    p_dossier_id::TEXT,
    p_baseline_version_id::TEXT,
    COALESCE((
      SELECT string_agg(
        concat_ws(
          ':',
          option_row.id::TEXT,
          option_row.supplier_id::TEXT,
          to_char(option_row.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
          to_char(supplier.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US')
        ),
        ',' ORDER BY
          supplier.normalized_name,
          COALESCE(option_row.model, option_row.option_name),
          option_row.id
      )
      FROM public.technical_configuration_options option_row
      JOIN public.technical_configuration_suppliers supplier
        ON supplier.id = option_row.supplier_id
       AND supplier.dossier_id = option_row.dossier_id
      WHERE option_row.dossier_id = p_dossier_id
    ), ''),
    COALESCE((
      SELECT string_agg(
        criterion.id::TEXT,
        ',' ORDER BY group_row.sort_order, criterion.sort_order, criterion.id
      )
      FROM public.technical_configuration_baseline_criteria criterion
      JOIN public.technical_configuration_baseline_groups group_row
        ON group_row.id = criterion.group_id
       AND group_row.baseline_version_id = criterion.baseline_version_id
      WHERE criterion.baseline_version_id = p_baseline_version_id
    ), ''),
    COALESCE((
      SELECT string_agg(
        concat_ws(
          ':',
          comparison_set.id::TEXT,
          to_char(
            comparison_set.updated_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US'
          ),
          COALESCE(assessment.id::TEXT, ''),
          COALESCE(assessment.revision::TEXT, ''),
          COALESCE(assessment.technical_axis, ''),
          COALESCE(assessment.evidence_axis, '')
        ),
        ',' ORDER BY comparison_set.option_id, assessment.criterion_id
      )
      FROM public.technical_configuration_comparison_sets comparison_set
      LEFT JOIN public.technical_configuration_manual_assessments assessment
        ON assessment.comparison_set_id = comparison_set.id
       AND assessment.baseline_version_id = comparison_set.baseline_version_id
      WHERE comparison_set.dossier_id = p_dossier_id
        AND comparison_set.baseline_version_id = p_baseline_version_id
    ), '')
  ));
$$;


ALTER FUNCTION public._technical_configuration_reference_ranking_token(p_dossier_id uuid, p_baseline_version_id uuid) OWNER TO postgres;

--
-- Name: _technical_configuration_reference_response_payload(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_reference_response_payload(p_response_id uuid, p_revision bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'id', r.id, 'baseline_version_id', r.baseline_version_id,
    'reference_product_id', r.reference_product_id, 'criterion_id', r.criterion_id,
    'response_text', r.response_text, 'created_at', r.created_at,
    'created_by', r.created_by, 'updated_at', r.updated_at, 'updated_by', r.updated_by,
    'revision', p_revision
  )
  FROM public.technical_configuration_reference_responses r
  WHERE r.id = p_response_id;
$$;


ALTER FUNCTION public._technical_configuration_reference_response_payload(p_response_id uuid, p_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_require_editable_baseline_version(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_require_editable_baseline_version(p_baseline_version_id uuid, p_expected_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_dossier_id UUID;
  v_revision BIGINT;
  v_status TEXT;
  v_archived_at TIMESTAMPTZ;
BEGIN
  v_user_id := public._technical_configuration_require_global_user();

  SELECT v.dossier_id INTO v_dossier_id
  FROM public.technical_configuration_baseline_versions v
  WHERE v.id = p_baseline_version_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT d.archived_at INTO v_archived_at
  FROM public.technical_configuration_dossiers d
  WHERE d.id = v_dossier_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT v.revision, v.status INTO v_revision, v_status
  FROM public.technical_configuration_baseline_versions v
  WHERE v.id = p_baseline_version_id
    AND v.dossier_id = v_dossier_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF v_archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived_dossier' USING ERRCODE = 'PT409';
  END IF;
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'locked_version' USING ERRCODE = 'PT409';
  END IF;
  IF v_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'stale_revision' USING ERRCODE = 'PT409';
  END IF;

  RETURN v_user_id;
END;
$$;


ALTER FUNCTION public._technical_configuration_require_editable_baseline_version(p_baseline_version_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: _technical_configuration_require_editable_dossier(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_require_editable_dossier(p_dossier_id uuid, p_expected_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_revision BIGINT;
  v_archived_at TIMESTAMPTZ;
BEGIN
  v_user_id := public._technical_configuration_require_global_user();

  SELECT
    d.revision,
    d.archived_at
  INTO
    v_revision,
    v_archived_at
  FROM public.technical_configuration_dossiers d
  WHERE d.id = p_dossier_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF v_archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived_dossier' USING ERRCODE = 'PT409';
  END IF;

  IF v_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'stale_revision' USING ERRCODE = 'PT409';
  END IF;

  RETURN v_user_id;
END;
$$;


ALTER FUNCTION public._technical_configuration_require_editable_dossier(p_dossier_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION _technical_configuration_require_editable_dossier(p_dossier_id uuid, p_expected_revision bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public._technical_configuration_require_editable_dossier(p_dossier_id uuid, p_expected_revision bigint) IS 'Common row-locking archive and revision guard for dossier and descendant mutations.';


--
-- Name: _technical_configuration_require_global_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_require_global_user() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims JSONB;
  v_role TEXT;
  v_user_id BIGINT;
BEGIN
  BEGIN
    v_claims := COALESCE(
      NULLIF(current_setting('request.jwt.claims', true), ''),
      '{}'
    )::JSONB;
    v_role := lower(
      COALESCE(
        NULLIF(v_claims->>'app_role', ''),
        NULLIF(v_claims->>'role', '')
      )
    );
    v_user_id := NULLIF(v_claims->>'user_id', '')::BIGINT;
  EXCEPTION
    WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END;

  IF v_role IS NULL
     OR v_user_id IS NULL
     OR NOT (v_role IN ('global', 'admin'))
     OR NOT EXISTS (
       SELECT 1
       FROM public.nhan_vien nv
       WHERE nv.id = v_user_id
     ) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  RETURN v_user_id;
END;
$$;


ALTER FUNCTION public._technical_configuration_require_global_user() OWNER TO postgres;

--
-- Name: _technical_configuration_result_export_snapshot(uuid, uuid, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_result_export_snapshot(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_snapshot_data JSONB;
  v_snapshot_payload JSONB;
  v_option_total BIGINT;
  v_criterion_total BIGINT;
  v_ranking_snapshot_token TEXT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  IF p_dossier_id IS NULL OR p_baseline_version_id IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  IF p_option_ids IS NOT NULL AND (
    cardinality(p_option_ids) = 0
    OR array_position(p_option_ids, NULL) IS NOT NULL
    OR (
      SELECT count(DISTINCT requested.option_id)
      FROM unnest(p_option_ids) AS requested(option_id)
    ) <> cardinality(p_option_ids)
  ) THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  IF p_criterion_ids IS NOT NULL AND (
    cardinality(p_criterion_ids) = 0
    OR array_position(p_criterion_ids, NULL) IS NOT NULL
    OR (
      SELECT count(DISTINCT requested.criterion_id)
      FROM unnest(p_criterion_ids) AS requested(criterion_id)
    ) <> cardinality(p_criterion_ids)
  ) THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.technical_configuration_baseline_versions version
    WHERE version.id = p_baseline_version_id
      AND version.dossier_id = p_dossier_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  v_ranking_snapshot_token :=
    public._technical_configuration_reference_ranking_token(
      p_dossier_id,
      p_baseline_version_id
    );
  WITH requested_options AS MATERIALIZED (
    SELECT requested.option_id, requested.ordinal::BIGINT
    FROM unnest(p_option_ids) WITH ORDINALITY AS requested(option_id, ordinal)
    WHERE p_option_ids IS NOT NULL
    UNION ALL
    SELECT
      option_row.id,
      row_number() OVER (
        ORDER BY
          supplier.normalized_name,
          COALESCE(option_row.model, option_row.option_name),
          option_row.id
      )
    FROM public.technical_configuration_options option_row
    JOIN public.technical_configuration_suppliers supplier
      ON supplier.id = option_row.supplier_id
     AND supplier.dossier_id = option_row.dossier_id
    WHERE p_option_ids IS NULL
      AND option_row.dossier_id = p_dossier_id
  ),
  scoped_options AS MATERIALIZED (
    SELECT
      requested.ordinal,
      option_row.id AS option_id,
      option_row.supplier_id,
      supplier.name AS supplier_name,
      supplier.normalized_name AS supplier_normalized_name,
      option_row.model,
      option_row.manufacturer,
      option_row.option_name
    FROM requested_options requested
    JOIN public.technical_configuration_options option_row
      ON option_row.id = requested.option_id
     AND option_row.dossier_id = p_dossier_id
    JOIN public.technical_configuration_suppliers supplier
      ON supplier.id = option_row.supplier_id
     AND supplier.dossier_id = option_row.dossier_id
  ),
  requested_criteria AS MATERIALIZED (
    SELECT requested.criterion_id, requested.ordinal::BIGINT
    FROM unnest(p_criterion_ids) WITH ORDINALITY AS requested(criterion_id, ordinal)
    WHERE p_criterion_ids IS NOT NULL
    UNION ALL
    SELECT
      criterion.id,
      row_number() OVER (
        ORDER BY group_row.sort_order, criterion.sort_order, criterion.id
      )
    FROM public.technical_configuration_baseline_criteria criterion
    JOIN public.technical_configuration_baseline_groups group_row
      ON group_row.id = criterion.group_id
     AND group_row.baseline_version_id = criterion.baseline_version_id
    WHERE p_criterion_ids IS NULL
      AND criterion.baseline_version_id = p_baseline_version_id
  ),
  scoped_criteria AS MATERIALIZED (
    SELECT
      requested.ordinal,
      group_row.id AS group_id,
      group_row.name AS group_name,
      group_row.sort_order AS group_order,
      criterion.id AS criterion_id,
      criterion.criterion_code,
      criterion.title AS criterion_title,
      criterion.requirement_text,
      criterion.sort_order AS criterion_order
    FROM requested_criteria requested
    JOIN public.technical_configuration_baseline_criteria criterion
      ON criterion.id = requested.criterion_id
     AND criterion.baseline_version_id = p_baseline_version_id
    JOIN public.technical_configuration_baseline_groups group_row
      ON group_row.id = criterion.group_id
     AND group_row.baseline_version_id = criterion.baseline_version_id
  ),
  dossier_context AS MATERIALIZED (
    SELECT
      dossier.id AS dossier_id,
      dossier.device_type_name,
      dossier.name AS dossier_name,
      dossier.revision AS dossier_revision,
      CASE WHEN dossier.archived_at IS NULL THEN NULL ELSE to_char(
        dossier.archived_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      ) END AS archived_at,
      version.id AS baseline_version_id,
      version.dossier_id AS baseline_dossier_id,
      version.version_number,
      version.status AS baseline_status,
      version.revision AS baseline_revision,
      CASE WHEN version.locked_at IS NULL THEN NULL ELSE to_char(
        version.locked_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      ) END AS locked_at
    FROM public.technical_configuration_dossiers dossier
    JOIN public.technical_configuration_baseline_versions version
      ON version.dossier_id = dossier.id
     AND version.id = p_baseline_version_id
    WHERE dossier.id = p_dossier_id
  )
  SELECT
    jsonb_build_object(
      'dossier', jsonb_build_object(
        'id', context.dossier_id,
        'device_type_name', context.device_type_name,
        'name', context.dossier_name,
        'revision', context.dossier_revision,
        'archived_at', context.archived_at
      ),
      'baseline_version', jsonb_build_object(
        'id', context.baseline_version_id,
        'dossier_id', context.baseline_dossier_id,
        'version_number', context.version_number,
        'status', context.baseline_status,
        'revision', context.baseline_revision,
        'locked_at', context.locked_at
      ),
      'option_ids', COALESCE(
        (
          SELECT jsonb_agg(scoped_option.option_id ORDER BY scoped_option.ordinal)
          FROM scoped_options scoped_option
        ),
        '[]'::JSONB
      ),
      'criterion_ids', COALESCE(
        (
          SELECT jsonb_agg(scoped_criterion.criterion_id ORDER BY scoped_criterion.ordinal)
          FROM scoped_criteria scoped_criterion
        ),
        '[]'::JSONB
      ),
      'option_total', (SELECT count(*) FROM scoped_options),
      'criterion_total', (SELECT count(*) FROM scoped_criteria),
      'ranking_snapshot_token', v_ranking_snapshot_token
    ),
    jsonb_build_object(
      'dossier', jsonb_build_object(
        'id', context.dossier_id,
        'device_type_name', context.device_type_name,
        'name', context.dossier_name,
        'revision', context.dossier_revision,
        'archived_at', context.archived_at
      ),
      'baseline_version', jsonb_build_object(
        'id', context.baseline_version_id,
        'dossier_id', context.baseline_dossier_id,
        'version_number', context.version_number,
        'status', context.baseline_status,
        'revision', context.baseline_revision,
        'locked_at', context.locked_at
      ),
      'options', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'option_id', scoped_option.option_id,
              'supplier_id', scoped_option.supplier_id,
              'supplier_name', scoped_option.supplier_name,
              'supplier_normalized_name', scoped_option.supplier_normalized_name,
              'model', scoped_option.model,
              'manufacturer', scoped_option.manufacturer,
              'option_name', scoped_option.option_name
            )
            ORDER BY scoped_option.ordinal
          )
          FROM scoped_options scoped_option
        ),
        '[]'::JSONB
      ),
      'criteria', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'group_id', scoped_criterion.group_id,
              'group_name', scoped_criterion.group_name,
              'group_order', scoped_criterion.group_order,
              'criterion_id', scoped_criterion.criterion_id,
              'criterion_code', scoped_criterion.criterion_code,
              'criterion_title', scoped_criterion.criterion_title,
              'requirement_text', scoped_criterion.requirement_text,
              'criterion_order', scoped_criterion.criterion_order
            )
            ORDER BY scoped_criterion.ordinal
          )
          FROM scoped_criteria scoped_criterion
        ),
        '[]'::JSONB
      ),
      'comparison_sets', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'comparison_set_id', comparison_set.id,
              'option_id', comparison_set.option_id,
              'baseline_version_id', comparison_set.baseline_version_id
            )
            ORDER BY scoped_option.ordinal
          )
          FROM scoped_options scoped_option
          JOIN public.technical_configuration_comparison_sets comparison_set
            ON comparison_set.option_id = scoped_option.option_id
           AND comparison_set.dossier_id = p_dossier_id
           AND comparison_set.baseline_version_id = p_baseline_version_id
        ),
        '[]'::JSONB
      ),
      'responses', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'response_id', response.id,
              'comparison_set_id', response.comparison_set_id,
              'criterion_id', response.criterion_id,
              'response_text', response.response_text,
              'supplementary_information', response.supplementary_information
            )
            ORDER BY scoped_option.ordinal, scoped_criterion.ordinal
          )
          FROM scoped_options scoped_option
          JOIN public.technical_configuration_comparison_sets comparison_set
            ON comparison_set.option_id = scoped_option.option_id
           AND comparison_set.dossier_id = p_dossier_id
           AND comparison_set.baseline_version_id = p_baseline_version_id
          JOIN public.technical_configuration_option_responses response
            ON response.comparison_set_id = comparison_set.id
           AND response.baseline_version_id = p_baseline_version_id
          JOIN scoped_criteria scoped_criterion
            ON scoped_criterion.criterion_id = response.criterion_id
        ),
        '[]'::JSONB
      ),
      'documents', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'document_id', document.id,
              'option_id', document.option_id,
              'document_name', document.name,
              'document_url', document.url
            )
            ORDER BY scoped_option.ordinal, document.name, document.id
          )
          FROM scoped_options scoped_option
          JOIN public.technical_configuration_option_documents document
            ON document.option_id = scoped_option.option_id
        ),
        '[]'::JSONB
      ),
      'citations', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'citation_id', citation.id,
              'option_id', citation.option_id,
              'comparison_set_id', citation.comparison_set_id,
              'criterion_id', citation.criterion_id,
              'document_id', citation.option_document_id,
              'page_section', citation.page_section,
              'excerpt', citation.excerpt
            )
            ORDER BY
              scoped_option.ordinal,
              scoped_criterion.ordinal,
              citation.option_document_id,
              citation.id
          )
          FROM scoped_options scoped_option
          JOIN public.technical_configuration_comparison_sets comparison_set
            ON comparison_set.option_id = scoped_option.option_id
           AND comparison_set.dossier_id = p_dossier_id
           AND comparison_set.baseline_version_id = p_baseline_version_id
          JOIN public.technical_configuration_option_citations citation
            ON citation.comparison_set_id = comparison_set.id
           AND citation.option_id = scoped_option.option_id
           AND citation.baseline_version_id = p_baseline_version_id
          JOIN scoped_criteria scoped_criterion
            ON scoped_criterion.criterion_id = citation.criterion_id
        ),
        '[]'::JSONB
      ),
      'assessments', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'assessment_id', assessment.id,
              'comparison_set_id', assessment.comparison_set_id,
              'criterion_id', assessment.criterion_id,
              'technical_axis', assessment.technical_axis,
              'evidence_axis', assessment.evidence_axis,
              'assessment_notes', assessment.notes,
              'assessment_revision', assessment.revision
            )
            ORDER BY scoped_option.ordinal, scoped_criterion.ordinal
          )
          FROM scoped_options scoped_option
          JOIN public.technical_configuration_comparison_sets comparison_set
            ON comparison_set.option_id = scoped_option.option_id
           AND comparison_set.dossier_id = p_dossier_id
           AND comparison_set.baseline_version_id = p_baseline_version_id
          JOIN public.technical_configuration_manual_assessments assessment
            ON assessment.comparison_set_id = comparison_set.id
           AND assessment.baseline_version_id = p_baseline_version_id
          JOIN scoped_criteria scoped_criterion
            ON scoped_criterion.criterion_id = assessment.criterion_id
        ),
        '[]'::JSONB
      ),
      'ranking_snapshot_token', v_ranking_snapshot_token
    ),
    (SELECT count(*) FROM scoped_options),
    (SELECT count(*) FROM scoped_criteria)
  INTO v_snapshot_data, v_snapshot_payload, v_option_total, v_criterion_total
  FROM dossier_context context;
  IF p_option_ids IS NOT NULL AND v_option_total <> cardinality(p_option_ids) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  IF p_criterion_ids IS NOT NULL
     AND v_criterion_total <> cardinality(p_criterion_ids) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  RETURN v_snapshot_data || jsonb_build_object(
    'options', v_snapshot_payload->'options',
    'criteria', v_snapshot_payload->'criteria',
    'snapshot_token',
    md5(v_snapshot_payload::TEXT)
  );
END;
$$;


ALTER FUNCTION public._technical_configuration_result_export_snapshot(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[]) OWNER TO postgres;

--
-- Name: _technical_configuration_validate_document_url(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._technical_configuration_validate_document_url(p_url text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_authority TEXT;
  v_host_port TEXT;
  v_host TEXT;
  v_port TEXT;
  v_decoded_host TEXT;
  v_host_bytes BYTEA;
  v_character TEXT;
  v_index INTEGER;
BEGIN
  IF p_url IS NULL
     OR p_url !~* '^https?:\/\/'
     OR p_url ~ '[[:space:]]'
     OR p_url ~ '[[:cntrl:]]'
     OR position(E'\\' IN p_url) > 0 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  v_authority := substring(p_url FROM '^[Hh][Tt][Tt][Pp][Ss]?://([^/?#]+)');
  IF v_authority IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  v_host_port := regexp_replace(v_authority, '^.*@', '');
  IF v_host_port = '' THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  IF left(v_host_port, 1) = '[' THEN
    IF v_host_port !~ '^\[[0-9A-Fa-f:.]+\](?::[0-9]*)?$' THEN
      RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
    END IF;

    v_host := substring(v_host_port FROM '^\[([0-9A-Fa-f:.]+)\]');
    IF v_host IS NULL OR position(':' IN v_host) = 0 THEN
      RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
    END IF;

    BEGIN
      PERFORM v_host::INET;
    EXCEPTION
      WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
    END;

    v_port := substring(v_host_port FROM '\]:([0-9]*)$');
  ELSE
    IF v_host_port ~ ':' THEN
      IF v_host_port !~ '^[^:]+:[0-9]*$' THEN
        RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
      END IF;
      v_host := split_part(v_host_port, ':', 1);
      v_port := split_part(v_host_port, ':', 2);
    ELSE
      v_host := v_host_port;
      v_port := NULL;
    END IF;

    IF v_host = ''
       OR position('[' IN v_host) > 0
       OR position(']' IN v_host) > 0 THEN
      RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
    END IF;

    v_host_bytes := ''::BYTEA;
    v_index := 1;
    WHILE v_index <= char_length(v_host) LOOP
      v_character := substring(v_host FROM v_index FOR 1);
      IF v_character = '%' THEN
        IF substring(v_host FROM v_index FOR 3) !~ '^%[0-9A-Fa-f]{2}$' THEN
          RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
        END IF;
        v_host_bytes :=
          v_host_bytes || decode(substring(v_host FROM v_index + 1 FOR 2), 'hex');
        v_index := v_index + 3;
      ELSE
        v_host_bytes := v_host_bytes || convert_to(v_character, 'UTF8');
        v_index := v_index + 1;
      END IF;
    END LOOP;

    BEGIN
      v_decoded_host := convert_from(v_host_bytes, 'UTF8');
    EXCEPTION
      WHEN character_not_in_repertoire THEN
        RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
    END;

    IF v_decoded_host = ''
       OR v_decoded_host ~ '[[:space:][:cntrl:]/?#@:<>^|%]'
       OR position(U&'\200C' IN v_decoded_host) > 0
       OR position(U&'\200D' IN v_decoded_host) > 0
       OR position(U&'\FFFD' IN v_decoded_host) > 0
       OR v_decoded_host ~* '(^|\.)xn--(\.|$)'
       OR position('[' IN v_decoded_host) > 0
       OR position(']' IN v_decoded_host) > 0
       OR position(E'\\' IN v_decoded_host) > 0 THEN
      RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
    END IF;

    IF v_decoded_host ~ '^[0-9.]+$' THEN
      BEGIN
        PERFORM v_decoded_host::INET;
      EXCEPTION
        WHEN invalid_text_representation THEN
          RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
      END;
    END IF;
  END IF;

  IF v_port IS NOT NULL AND v_port <> '' THEN
    IF length(v_port) > 5 THEN
      RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
    ELSIF v_port::INTEGER > 65535 THEN
      RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
    END IF;
  END IF;
END;
$_$;


ALTER FUNCTION public._technical_configuration_validate_document_url(p_url text) OWNER TO postgres;

--
-- Name: ai_attachment_metadata(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_attachment_metadata(p_thiet_bi_id bigint, p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
  v_equip_don_vi BIGINT;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501'; END IF;
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501'; END IF;
  IF v_role = 'admin' THEN v_role := 'global'; END IF;
  v_is_global := (v_role = 'global');
  IF NOT v_is_global AND v_don_vi IS NULL THEN RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501'; END IF;
  IF p_user_id IS NOT NULL AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_thiet_bi_id IS NULL OR p_thiet_bi_id <= 0 THEN
    RETURN jsonb_build_object('error', 'Invalid thiet_bi_id', 'thiet_bi_id', p_thiet_bi_id);
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NULL THEN RETURN jsonb_build_object('error', 'Facility selection required', 'thiet_bi_id', p_thiet_bi_id); END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN RETURN jsonb_build_object('error', 'No accessible facilities', 'thiet_bi_id', p_thiet_bi_id); END IF;
    IF p_don_vi IS NULL THEN RETURN jsonb_build_object('error', 'Facility selection required', 'thiet_bi_id', p_thiet_bi_id); END IF;
    IF NOT (p_don_vi = ANY(v_allowed)) THEN RETURN jsonb_build_object('error', 'Access denied for selected facility', 'thiet_bi_id', p_thiet_bi_id); END IF;
  END IF;

  SELECT tb.don_vi INTO v_equip_don_vi FROM public.thiet_bi tb
  WHERE tb.id = p_thiet_bi_id AND tb.is_deleted = FALSE
    AND (CASE WHEN v_is_global THEN tb.don_vi = p_don_vi WHEN v_role = 'regional_leader' THEN tb.don_vi = p_don_vi ELSE tb.don_vi = v_don_vi END);

  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Equipment not found or not accessible', 'thiet_bi_id', p_thiet_bi_id); END IF;

  RETURN (
    WITH full_count AS (SELECT COUNT(*)::BIGINT AS cnt FROM public.file_dinh_kem f WHERE f.thiet_bi_id = p_thiet_bi_id),
    attachments AS (
      SELECT f.id, f.ten_file,
        CASE WHEN f.duong_dan_luu_tru ~* '^https?://' THEN 'external_url' ELSE 'storage_path' END AS access_type,
        CASE WHEN f.duong_dan_luu_tru ~* '^https?://' THEN f.duong_dan_luu_tru ELSE NULL END AS url,
        f.ngay_tai_len
      FROM public.file_dinh_kem f WHERE f.thiet_bi_id = p_thiet_bi_id
      ORDER BY f.ngay_tai_len DESC NULLS LAST LIMIT 20
    )
    SELECT jsonb_build_object(
      'kind', 'attachmentMetadata', 'thiet_bi_id', p_thiet_bi_id,
      'attachments', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', a.id, 'ten_file', a.ten_file, 'access_type', a.access_type, 'url', a.url, 'ngay_tai_len', a.ngay_tai_len) ORDER BY a.ngay_tai_len DESC NULLS LAST) FROM attachments a), '[]'::JSONB),
      'total_count', (SELECT cnt FROM full_count)
    )
  );
END;
$$;


ALTER FUNCTION public.ai_attachment_metadata(p_thiet_bi_id bigint, p_don_vi bigint, p_user_id text) OWNER TO postgres;

--
-- Name: ai_category_list(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_category_list(p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_effective BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
BEGIN
  -- JWT claim guards
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_global := (v_role = 'global');

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NOT NULL
     AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL
     AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  -- Tenant isolation (same pattern as ai_equipment_lookup)
  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN
      RETURN jsonb_build_object('data', '[]'::JSONB, 'total', 0);
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  ELSE
    IF p_don_vi IS NOT NULL AND p_don_vi IS DISTINCT FROM v_don_vi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
    v_effective := ARRAY[v_don_vi];
  END IF;

  -- Return categories with parent name for hierarchical context
  RETURN (
    WITH cats AS (
      SELECT
        n.id,
        n.ma_nhom,
        n.ten_nhom,
        n.phan_loai,
        n.mo_ta,
        n.tu_khoa,
        p.ten_nhom AS parent_name,
        COUNT(*) OVER () AS total_count
      FROM public.nhom_thiet_bi n
      LEFT JOIN public.nhom_thiet_bi p ON p.id = n.parent_id
      WHERE (v_effective IS NULL OR n.don_vi_id = ANY(v_effective))
      ORDER BY n.thu_tu_hien_thi ASC NULLS LAST, n.ten_nhom ASC
    )
    SELECT jsonb_build_object(
      'data',
      COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'id', id,
            'ma_nhom', ma_nhom,
            'ten_nhom', ten_nhom,
            'phan_loai', phan_loai,
            'mo_ta', mo_ta,
            'tu_khoa', tu_khoa,
            'parent_name', parent_name
          )
        ),
        '[]'::JSONB
      ),
      'total', COALESCE(MAX(total_count), 0)
    )
    FROM cats
  );
END;
$$;


ALTER FUNCTION public.ai_category_list(p_don_vi bigint, p_user_id text) OWNER TO postgres;

--
-- Name: ai_category_suggestion(text, bigint, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_category_suggestion(p_device_name text, p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text, p_top_k integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_effective BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
  v_device_name TEXT := NULLIF(BTRIM(p_device_name), '');
  v_top_k INTEGER := LEAST(GREATEST(COALESCE(NULLIF(p_top_k, 0), 10), 1), 10);
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_device_name IS NULL THEN
    RAISE EXCEPTION 'device_name is required' USING ERRCODE = '22023';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_global := (v_role = 'global');

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NOT NULL
     AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL
     AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN
      RETURN jsonb_build_object('data', '[]'::JSONB, 'total', 0);
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  ELSE
    IF p_don_vi IS NOT NULL AND p_don_vi IS DISTINCT FROM v_don_vi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
    v_effective := ARRAY[v_don_vi];
  END IF;

  RETURN (
    WITH scoped_categories AS (
      SELECT
        n.id,
        n.ma_nhom,
        n.ten_nhom,
        n.phan_loai,
        p.ten_nhom AS parent_name,
        COALESCE(n.fts, ''::TSVECTOR) AS fts
      FROM public.nhom_thiet_bi n
      LEFT JOIN public.nhom_thiet_bi p ON p.id = n.parent_id
      WHERE (v_effective IS NULL OR n.don_vi_id = ANY(v_effective))
    ),
    all_fts_matches AS (
      SELECT
        sc.id,
        sc.ma_nhom,
        sc.ten_nhom,
        sc.phan_loai,
        sc.parent_name,
        'fts'::TEXT AS match_reason,
        ts_rank_cd(sc.fts, plainto_tsquery('simple', v_device_name)) AS score
      FROM scoped_categories sc
      WHERE sc.fts @@ plainto_tsquery('simple', v_device_name)
    ),
    fts_matches AS (
      SELECT
        afm.id,
        afm.ma_nhom,
        afm.ten_nhom,
        afm.phan_loai,
        afm.parent_name,
        afm.match_reason,
        afm.score
      FROM all_fts_matches afm
      ORDER BY afm.score DESC, afm.ten_nhom ASC
      LIMIT v_top_k
    ),
    trigram_matches AS (
      SELECT
        sc.id,
        sc.ma_nhom,
        sc.ten_nhom,
        sc.phan_loai,
        sc.parent_name,
        'trigram'::TEXT AS match_reason,
        extensions.word_similarity(lower(v_device_name), lower(COALESCE(sc.ten_nhom, ''))) AS score
      FROM scoped_categories sc
      WHERE extensions.word_similarity(lower(v_device_name), lower(COALESCE(sc.ten_nhom, ''))) > 0.3
        AND NOT EXISTS (
          SELECT 1
          FROM all_fts_matches afm
          WHERE afm.id = sc.id
        )
      ORDER BY score DESC, sc.ten_nhom ASC
      LIMIT v_top_k
    ),
    combined_matches AS (
      SELECT * FROM fts_matches
      UNION ALL
      SELECT * FROM trigram_matches
    ),
    ranked_matches AS (
      SELECT
        cm.*,
        ROW_NUMBER() OVER (
          ORDER BY
            CASE WHEN cm.match_reason = 'fts' THEN 0 ELSE 1 END,
            cm.score DESC,
            cm.ten_nhom ASC
        ) AS rank
      FROM combined_matches cm
    ),
    limited_matches AS (
      SELECT *
      FROM ranked_matches
      ORDER BY rank
      LIMIT v_top_k
    )
    SELECT jsonb_build_object(
      'data',
      COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'id', id,
            'ma_nhom', ma_nhom,
            'ten_nhom', ten_nhom,
            'phan_loai', phan_loai,
            'parent_name', parent_name,
            'match_reason', match_reason
          )
          ORDER BY rank
        ),
        '[]'::JSONB
      ),
      'total', COUNT(*)
    )
    FROM limited_matches
  );
END;
$$;


ALTER FUNCTION public.ai_category_suggestion(p_device_name text, p_don_vi bigint, p_user_id text, p_top_k integer) OWNER TO postgres;

--
-- Name: ai_department_list(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_department_list(p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_effective BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
BEGIN
  -- JWT claim guards
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_global := (v_role = 'global');

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NOT NULL
     AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL
     AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  -- Tenant isolation (same pattern as ai_category_list)
  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN
      RETURN jsonb_build_object('data', '[]'::JSONB, 'total', 0);
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  ELSE
    IF p_don_vi IS NOT NULL AND p_don_vi IS DISTINCT FROM v_don_vi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
    v_effective := ARRAY[v_don_vi];
  END IF;

  -- Return distinct department names with equipment count
  RETURN (
    WITH depts AS (
      SELECT
        khoa_phong_quan_ly AS name,
        COUNT(*) AS equipment_count
      FROM public.thiet_bi
      WHERE is_deleted = FALSE
        AND khoa_phong_quan_ly IS NOT NULL
        AND BTRIM(khoa_phong_quan_ly) <> ''
        AND (v_effective IS NULL OR don_vi = ANY(v_effective))
      GROUP BY khoa_phong_quan_ly
      ORDER BY khoa_phong_quan_ly ASC
    )
    SELECT jsonb_build_object(
      'data',
      COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'name', name,
            'equipment_count', equipment_count
          )
        ),
        '[]'::JSONB
      ),
      'total', COALESCE(COUNT(*), 0)
    )
    FROM depts
  );
END;
$$;


ALTER FUNCTION public.ai_department_list(p_don_vi bigint, p_user_id text) OWNER TO postgres;

--
-- Name: ai_device_quota_lookup(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_device_quota_lookup(p_thiet_bi_id bigint, p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
  v_equip_don_vi BIGINT; v_equip_ma TEXT; v_equip_ten TEXT; v_equip_nhom_id BIGINT;
  v_decision_id BIGINT; v_decision_so TEXT; v_decision_trang_thai TEXT; v_decision_ngay_hieu_luc DATE;
  v_category_id BIGINT; v_category_ma TEXT; v_category_ten TEXT;
  v_quota_max INT; v_quota_min INT; v_current_count BIGINT;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501'; END IF;
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501'; END IF;
  IF v_role = 'admin' THEN v_role := 'global'; END IF;
  v_is_global := (v_role = 'global');
  IF NOT v_is_global AND v_don_vi IS NULL THEN RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501'; END IF;
  IF p_user_id IS NOT NULL AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_thiet_bi_id IS NULL OR p_thiet_bi_id <= 0 THEN
    RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'error', 'Invalid thiet_bi_id', 'thiet_bi_id', p_thiet_bi_id);
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NULL THEN RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'error', 'Facility selection required'); END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'error', 'No accessible facilities'); END IF;
    IF p_don_vi IS NULL THEN RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'error', 'Facility selection required'); END IF;
    IF NOT (p_don_vi = ANY(v_allowed)) THEN RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'error', 'Access denied for selected facility'); END IF;
  END IF;

  SELECT tb.don_vi, tb.ma_thiet_bi, tb.ten_thiet_bi, tb.nhom_thiet_bi_id
  INTO v_equip_don_vi, v_equip_ma, v_equip_ten, v_equip_nhom_id
  FROM public.thiet_bi tb WHERE tb.id = p_thiet_bi_id AND tb.is_deleted = FALSE
    AND (CASE WHEN v_is_global THEN tb.don_vi = p_don_vi WHEN v_role = 'regional_leader' THEN tb.don_vi = p_don_vi ELSE tb.don_vi = v_don_vi END);

  IF NOT FOUND THEN RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'error', 'Equipment not found or not accessible', 'thiet_bi_id', p_thiet_bi_id); END IF;

  SELECT qd.id, qd.so_quyet_dinh, qd.trang_thai, qd.ngay_hieu_luc INTO v_decision_id, v_decision_so, v_decision_trang_thai, v_decision_ngay_hieu_luc
  FROM public.quyet_dinh_dinh_muc qd WHERE qd.don_vi_id = v_equip_don_vi AND qd.trang_thai = 'active' ORDER BY qd.ngay_hieu_luc DESC NULLS LAST, qd.id DESC LIMIT 1;

  IF v_decision_id IS NULL THEN
    RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'device', jsonb_build_object('id', p_thiet_bi_id, 'ma_thiet_bi', v_equip_ma, 'ten_thiet_bi', v_equip_ten),
      'status', 'insufficientEvidence', 'scope', jsonb_build_object('mode', 'facility', 'don_vi_id', v_equip_don_vi), 'reason', 'No active quota decision found for this facility', 'evidence_status', 'none');
  END IF;

  IF v_equip_nhom_id IS NULL THEN
    RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'device', jsonb_build_object('id', p_thiet_bi_id, 'ma_thiet_bi', v_equip_ma, 'ten_thiet_bi', v_equip_ten),
      'status', 'notMapped', 'scope', jsonb_build_object('mode', 'facility', 'don_vi_id', v_equip_don_vi),
      'decision', jsonb_build_object('id', v_decision_id, 'so_quyet_dinh', v_decision_so, 'trang_thai', v_decision_trang_thai, 'ngay_hieu_luc', v_decision_ngay_hieu_luc), 'evidence_status', 'partial');
  END IF;

  SELECT ntb.id, ntb.ma_nhom, ntb.ten_nhom INTO v_category_id, v_category_ma, v_category_ten
  FROM public.nhom_thiet_bi ntb WHERE ntb.id = v_equip_nhom_id AND ntb.don_vi_id = v_equip_don_vi;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'device', jsonb_build_object('id', p_thiet_bi_id, 'ma_thiet_bi', v_equip_ma, 'ten_thiet_bi', v_equip_ten),
      'status', 'insufficientEvidence', 'scope', jsonb_build_object('mode', 'facility', 'don_vi_id', v_equip_don_vi), 'reason', 'Category metadata not found for equipment group',
      'decision', jsonb_build_object('id', v_decision_id, 'so_quyet_dinh', v_decision_so, 'trang_thai', v_decision_trang_thai, 'ngay_hieu_luc', v_decision_ngay_hieu_luc), 'evidence_status', 'partial');
  END IF;

  SELECT cd.so_luong_toi_da, cd.so_luong_toi_thieu INTO v_quota_max, v_quota_min
  FROM public.chi_tiet_dinh_muc cd WHERE cd.quyet_dinh_id = v_decision_id AND cd.nhom_thiet_bi_id = v_equip_nhom_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'device', jsonb_build_object('id', p_thiet_bi_id, 'ma_thiet_bi', v_equip_ma, 'ten_thiet_bi', v_equip_ten),
      'status', 'notInApprovedCatalog', 'scope', jsonb_build_object('mode', 'facility', 'don_vi_id', v_equip_don_vi),
      'decision', jsonb_build_object('id', v_decision_id, 'so_quyet_dinh', v_decision_so, 'trang_thai', v_decision_trang_thai, 'ngay_hieu_luc', v_decision_ngay_hieu_luc),
      'category', jsonb_build_object('id', v_category_id, 'ma_nhom', v_category_ma, 'ten_nhom', v_category_ten), 'evidence_status', 'partial');
  END IF;

  SELECT COUNT(*)::BIGINT INTO v_current_count FROM public.thiet_bi tb
  WHERE tb.nhom_thiet_bi_id = v_equip_nhom_id AND tb.don_vi = v_equip_don_vi AND tb.is_deleted = FALSE;

  RETURN jsonb_build_object('kind', 'deviceQuotaLookup', 'device', jsonb_build_object('id', p_thiet_bi_id, 'ma_thiet_bi', v_equip_ma, 'ten_thiet_bi', v_equip_ten),
    'status', 'inQuotaCatalog', 'scope', jsonb_build_object('mode', 'facility', 'don_vi_id', v_equip_don_vi),
    'decision', jsonb_build_object('id', v_decision_id, 'so_quyet_dinh', v_decision_so, 'trang_thai', v_decision_trang_thai, 'ngay_hieu_luc', v_decision_ngay_hieu_luc),
    'category', jsonb_build_object('id', v_category_id, 'ma_nhom', v_category_ma, 'ten_nhom', v_category_ten),
    'quota', jsonb_build_object('so_luong_toi_da', v_quota_max, 'so_luong_toi_thieu', v_quota_min, 'so_luong_hien_co', v_current_count, 'remaining', GREATEST(v_quota_max - v_current_count, 0)),
    'evidence_status', 'complete');
END;
$$;


ALTER FUNCTION public.ai_device_quota_lookup(p_thiet_bi_id bigint, p_don_vi bigint, p_user_id text) OWNER TO postgres;

--
-- Name: ai_equipment_lookup(text, integer, bigint, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_equipment_lookup(query text DEFAULT NULL::text, "limit" integer DEFAULT 10, p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text, status text DEFAULT NULL::text, filters jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_effective BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
  v_limit INT := GREATEST(LEAST(COALESCE("limit", 10), 50), 1);
  v_filters JSONB := COALESCE(filters, '{}'::JSONB);
  v_sanitized_q TEXT := public._sanitize_ilike_pattern(query);
  v_equipment_code_filter TEXT := NULLIF(BTRIM(COALESCE(v_filters->>'equipmentCode', v_filters->>'ma_thiet_bi', v_filters->>'deviceCode')), '');
  v_status_filter TEXT := NULLIF(BTRIM(COALESCE(v_filters->>'status', status)), '');
  v_department_filter_raw TEXT := NULLIF(BTRIM(COALESCE(v_filters->>'department', v_filters->>'khoa_phong', v_filters->>'khoa_phong_quan_ly')), '');
  v_department_filter TEXT := public._sanitize_ilike_pattern(v_department_filter_raw);
  v_location_filter_raw TEXT := NULLIF(BTRIM(COALESCE(v_filters->>'location', v_filters->>'vi_tri_lap_dat')), '');
  v_location_filter TEXT := public._sanitize_ilike_pattern(v_location_filter_raw);
  v_classification_filter TEXT := NULLIF(BTRIM(COALESCE(v_filters->>'classification', v_filters->>'phan_loai_theo_nd98')), '');
  v_model_filter_raw TEXT := NULLIF(BTRIM(COALESCE(v_filters->>'model')), '');
  v_model_filter TEXT := public._sanitize_ilike_pattern(v_model_filter_raw);
  v_serial_filter_raw TEXT := NULLIF(BTRIM(COALESCE(v_filters->>'serial')), '');
  v_serial_filter TEXT := public._sanitize_ilike_pattern(v_serial_filter_raw);
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_global := (v_role = 'global');

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NOT NULL
     AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL
     AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_status_filter IS NOT NULL THEN
    IF v_status_filter ILIKE '%ngưng sử dụng%' OR v_status_filter ILIKE '%ngung su dung%' THEN
      v_status_filter := 'Ngưng sử dụng';
    ELSIF v_status_filter ILIKE '%chưa có nhu cầu sử dụng%' OR v_status_filter ILIKE '%chua co nhu cau su dung%' THEN
      v_status_filter := 'Chưa có nhu cầu sử dụng';
    ELSIF v_status_filter ILIKE '%chờ sửa chữa%' OR v_status_filter ILIKE '%cho sua chua%' THEN
      v_status_filter := 'Chờ sửa chữa';
    ELSIF v_status_filter ILIKE '%chờ bảo trì%' OR v_status_filter ILIKE '%cho bao tri%' THEN
      v_status_filter := 'Chờ bảo trì';
    ELSIF v_status_filter ILIKE '%kiểm định%' OR v_status_filter ILIKE '%kiem dinh%' OR v_status_filter ILIKE '%hiệu chuẩn%' OR v_status_filter ILIKE '%hieu chuan%' THEN
      v_status_filter := 'Chờ hiệu chuẩn/kiểm định';
    ELSIF v_status_filter ILIKE '%hoạt động%' OR v_status_filter ILIKE '%hoat dong%' THEN
      v_status_filter := 'Hoạt động';
    END IF;
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'total', 0,
        'limit', v_limit
      );
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  ELSE
    IF p_don_vi IS NOT NULL AND p_don_vi IS DISTINCT FROM v_don_vi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
    v_effective := ARRAY[v_don_vi];
  END IF;

  RETURN (
    WITH filtered AS (
      SELECT
        tb.id,
        tb.ma_thiet_bi,
        tb.ten_thiet_bi,
        tb.model,
        tb.serial,
        tb.so_luu_hanh,
        tb.tinh_trang_hien_tai,
        tb.khoa_phong_quan_ly,
        tb.vi_tri_lap_dat,
        tb.phan_loai_theo_nd98,
        tb.ngay_bt_tiep_theo,
        tb.ngay_hc_tiep_theo,
        tb.ngay_kd_tiep_theo,
        tb.don_vi,
        dv.name AS facility_name,
        COUNT(*) OVER () AS total_count
      FROM public.thiet_bi tb
      LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
      WHERE tb.is_deleted = FALSE
        AND (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
        AND (
          v_equipment_code_filter IS NULL
          OR tb.ma_thiet_bi = v_equipment_code_filter
        )
        AND (
          v_status_filter IS NULL
          OR tb.tinh_trang_hien_tai = v_status_filter
        )
        -- Department filter: ILIKE + pg_trgm word_similarity fallback
        -- FIX: schema-qualify extensions.word_similarity (pg_trgm lives in extensions schema)
        AND (
          v_department_filter IS NULL
          OR COALESCE(tb.khoa_phong_quan_ly, '') ILIKE '%' || v_department_filter || '%'
          OR (v_department_filter_raw IS NOT NULL
              AND extensions.word_similarity(v_department_filter_raw, COALESCE(tb.khoa_phong_quan_ly, '')) > 0.4)
        )
        -- Location filter: ILIKE + pg_trgm word_similarity fallback
        -- FIX: schema-qualify extensions.word_similarity (pg_trgm lives in extensions schema)
        AND (
          v_location_filter IS NULL
          OR COALESCE(tb.vi_tri_lap_dat, '') ILIKE '%' || v_location_filter || '%'
          OR (v_location_filter_raw IS NOT NULL
              AND extensions.word_similarity(v_location_filter_raw, COALESCE(tb.vi_tri_lap_dat, '')) > 0.4)
        )
        AND (
          v_classification_filter IS NULL
          OR COALESCE(tb.phan_loai_theo_nd98, '') = v_classification_filter
        )
        AND (
          v_model_filter IS NULL
          OR COALESCE(tb.model, '') ILIKE '%' || v_model_filter || '%'
        )
        AND (
          v_serial_filter IS NULL
          OR COALESCE(tb.serial, '') ILIKE '%' || v_serial_filter || '%'
        )
        AND (
          v_sanitized_q IS NULL
          OR tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
          OR tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%'
          OR COALESCE(tb.model, '') ILIKE '%' || v_sanitized_q || '%'
          OR COALESCE(tb.serial, '') ILIKE '%' || v_sanitized_q || '%'
          OR COALESCE(tb.so_luu_hanh, '') ILIKE '%' || v_sanitized_q || '%'
          OR COALESCE(tb.tinh_trang_hien_tai, '') ILIKE '%' || v_sanitized_q || '%'
          OR COALESCE(tb.khoa_phong_quan_ly, '') ILIKE '%' || v_sanitized_q || '%'
          OR COALESCE(tb.vi_tri_lap_dat, '') ILIKE '%' || v_sanitized_q || '%'
          OR COALESCE(tb.phan_loai_theo_nd98, '') ILIKE '%' || v_sanitized_q || '%'
        )
      ORDER BY tb.created_at DESC NULLS LAST, tb.id DESC
      LIMIT v_limit
    )
    SELECT jsonb_build_object(
      'data',
      COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'id', id,
            'ma_thiet_bi', ma_thiet_bi,
            'ten_thiet_bi', ten_thiet_bi,
            'model', model,
            'serial', serial,
            'so_luu_hanh', so_luu_hanh,
            'tinh_trang_hien_tai', tinh_trang_hien_tai,
            'khoa_phong_quan_ly', khoa_phong_quan_ly,
            'vi_tri_lap_dat', vi_tri_lap_dat,
            'phan_loai_theo_nd98', phan_loai_theo_nd98,
            'ngay_bt_tiep_theo', ngay_bt_tiep_theo,
            'ngay_hc_tiep_theo', ngay_hc_tiep_theo,
            'ngay_kd_tiep_theo', ngay_kd_tiep_theo,
            'don_vi', don_vi,
            'facility_name', facility_name
          )
        ),
        '[]'::JSONB
      ),
      'total', COALESCE(MAX(total_count), 0),
      'limit', v_limit,
      'appliedFilters',
      jsonb_strip_nulls(
        jsonb_build_object(
          'equipmentCode', v_equipment_code_filter,
          'status', v_status_filter,
          'department', v_department_filter_raw,
          'location', v_location_filter_raw,
          'classification', v_classification_filter,
          'model', v_model_filter_raw,
          'serial', v_serial_filter_raw
        )
      )
    )
    FROM filtered
  );
END;
$$;


ALTER FUNCTION public.ai_equipment_lookup(query text, "limit" integer, p_don_vi bigint, p_user_id text, status text, filters jsonb) OWNER TO postgres;

--
-- Name: ai_kill_switch_set(boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_kill_switch_set(p_enabled boolean, p_reason text DEFAULT NULL::text) RETURNS TABLE(enabled boolean, reason text, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims_text TEXT := current_setting('request.jwt.claims', true);
  v_claims JSONB;
  v_role TEXT;
  v_user_id TEXT;
  v_reason TEXT := NULLIF(btrim(COALESCE(p_reason, '')), '');
  v_enabled_updated_at TIMESTAMPTZ;
  v_reason_updated_at TIMESTAMPTZ;
BEGIN
  IF p_enabled IS NULL THEN
    RAISE EXCEPTION 'p_enabled is required' USING ERRCODE = '22023';
  END IF;

  IF v_claims_text IS NULL OR btrim(v_claims_text) = '' THEN
    RAISE EXCEPTION 'Missing JWT claims' USING ERRCODE = '42501';
  END IF;

  v_claims := v_claims_text::jsonb;
  v_role := NULLIF(v_claims->>'app_role', '');
  IF v_role IS NULL AND NULLIF(v_claims->>'role', '') = 'service_role' THEN
    v_role := 'service_role';
  END IF;
  v_user_id := NULLIF(v_claims->>'user_id', '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_role <> 'service_role' AND v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('global', 'service_role') THEN
    RAISE EXCEPTION 'Insufficient privileges to set AI kill switch' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.internal_settings(key, value, updated_at)
  VALUES ('ai_kill_switch.enabled', CASE WHEN p_enabled THEN 'true' ELSE 'false' END, now())
  ON CONFLICT (key) DO UPDATE
  SET value = EXCLUDED.value,
      updated_at = EXCLUDED.updated_at
  RETURNING public.internal_settings.updated_at
  INTO v_enabled_updated_at;

  IF v_reason IS NULL THEN
    DELETE FROM public.internal_settings
    WHERE key = 'ai_kill_switch.reason'
    RETURNING public.internal_settings.updated_at
    INTO v_reason_updated_at;

    reason := NULL;
    v_reason_updated_at := COALESCE(v_reason_updated_at, v_enabled_updated_at);
  ELSE
    INSERT INTO public.internal_settings(key, value, updated_at)
    VALUES ('ai_kill_switch.reason', v_reason, now())
    ON CONFLICT (key) DO UPDATE
    SET value = EXCLUDED.value,
        updated_at = EXCLUDED.updated_at
    RETURNING public.internal_settings.value, public.internal_settings.updated_at
    INTO reason, v_reason_updated_at;
  END IF;

  enabled := p_enabled;
  updated_at := GREATEST(v_enabled_updated_at, v_reason_updated_at);

  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.ai_kill_switch_set(p_enabled boolean, p_reason text) OWNER TO postgres;

--
-- Name: ai_kill_switch_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_kill_switch_status() RETURNS TABLE(enabled boolean, reason text, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims_text TEXT := current_setting('request.jwt.claims', true);
  v_claims JSONB;
  v_role TEXT;
  v_user_id TEXT;
  v_enabled_text TEXT;
  v_enabled_updated_at TIMESTAMPTZ;
  v_reason_updated_at TIMESTAMPTZ;
BEGIN
  IF v_claims_text IS NULL OR btrim(v_claims_text) = '' THEN
    RAISE EXCEPTION 'Missing JWT claims' USING ERRCODE = '42501';
  END IF;

  v_claims := v_claims_text::jsonb;
  v_role := NULLIF(v_claims->>'app_role', '');
  IF v_role IS NULL AND NULLIF(v_claims->>'role', '') = 'service_role' THEN
    v_role := 'service_role';
  END IF;
  v_user_id := NULLIF(v_claims->>'user_id', '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_role <> 'service_role' AND v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  SELECT
    MAX(s.value) FILTER (WHERE s.key = 'ai_kill_switch.enabled'),
    MAX(s.updated_at) FILTER (WHERE s.key = 'ai_kill_switch.enabled'),
    MAX(NULLIF(btrim(s.value), '')) FILTER (WHERE s.key = 'ai_kill_switch.reason'),
    MAX(s.updated_at) FILTER (WHERE s.key = 'ai_kill_switch.reason')
  INTO v_enabled_text, v_enabled_updated_at, reason, v_reason_updated_at
  FROM public.internal_settings s
  WHERE s.key IN ('ai_kill_switch.enabled', 'ai_kill_switch.reason');

  enabled := lower(COALESCE(v_enabled_text, 'false')) IN ('true', '1', 'on', 'yes', 'enabled');
  updated_at := GREATEST(v_enabled_updated_at, v_reason_updated_at);

  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.ai_kill_switch_status() OWNER TO postgres;

--
-- Name: ai_maintenance_plan_lookup(bigint, integer, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_maintenance_plan_lookup(p_thiet_bi_id bigint, p_nam integer DEFAULT NULL::integer, p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_effective BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501'; END IF;
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501'; END IF;
  IF p_thiet_bi_id IS NULL OR p_thiet_bi_id <= 0 THEN RAISE EXCEPTION 'thiet_bi_id is required' USING ERRCODE = '22023'; END IF;
  IF v_role = 'admin' THEN v_role := 'global'; END IF;
  v_is_global := (v_role = 'global');
  IF NOT v_is_global AND v_don_vi IS NULL THEN RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501'; END IF;
  IF p_user_id IS NOT NULL AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN v_effective := ARRAY[p_don_vi]; END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN
      RETURN jsonb_build_object('equipment', NULL, 'plans', '[]'::JSONB, 'totalPlans', 0, 'yearFilter', p_nam);
    END IF;
    IF p_don_vi IS NOT NULL THEN
      IF NOT (p_don_vi = ANY(v_allowed)) THEN RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501'; END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE v_effective := v_allowed; END IF;
  ELSE
    IF p_don_vi IS NOT NULL AND p_don_vi IS DISTINCT FROM v_don_vi THEN RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501'; END IF;
    v_effective := ARRAY[v_don_vi];
  END IF;

  RETURN (
    WITH rows AS (
      SELECT kh.id AS plan_id, kh.ten_ke_hoach, kh.nam, kh.loai_cong_viec, kh.trang_thai AS plan_trang_thai, kh.ngay_phe_duyet,
        cv.id AS task_id, cv.don_vi_thuc_hien, cv.diem_hieu_chuan,
        cv.thang_1, cv.thang_2, cv.thang_3, cv.thang_4, cv.thang_5, cv.thang_6,
        cv.thang_7, cv.thang_8, cv.thang_9, cv.thang_10, cv.thang_11, cv.thang_12,
        cv.thang_1_hoan_thanh, cv.thang_2_hoan_thanh, cv.thang_3_hoan_thanh,
        cv.thang_4_hoan_thanh, cv.thang_5_hoan_thanh, cv.thang_6_hoan_thanh,
        cv.thang_7_hoan_thanh, cv.thang_8_hoan_thanh, cv.thang_9_hoan_thanh,
        cv.thang_10_hoan_thanh, cv.thang_11_hoan_thanh, cv.thang_12_hoan_thanh,
        cv.ghi_chu, tb.id AS equipment_id, tb.ma_thiet_bi, tb.ten_thiet_bi, tb.model, tb.don_vi
      FROM public.cong_viec_bao_tri cv
      JOIN public.ke_hoach_bao_tri kh ON kh.id = cv.ke_hoach_id
      JOIN public.thiet_bi tb ON tb.id = cv.thiet_bi_id
      WHERE cv.thiet_bi_id = p_thiet_bi_id
        AND (p_nam IS NULL OR kh.nam = p_nam)
        AND tb.is_deleted = FALSE
        AND (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
    )
    SELECT jsonb_build_object(
      'equipment', (SELECT jsonb_build_object('id', equipment_id, 'ma_thiet_bi', ma_thiet_bi, 'ten_thiet_bi', ten_thiet_bi, 'model', model, 'don_vi', don_vi) FROM rows LIMIT 1),
      'plans', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'plan_id', plan_id, 'ten_ke_hoach', ten_ke_hoach, 'nam', nam, 'loai_cong_viec', loai_cong_viec, 'plan_trang_thai', plan_trang_thai, 'ngay_phe_duyet', ngay_phe_duyet,
        'task_id', task_id, 'don_vi_thuc_hien', don_vi_thuc_hien, 'diem_hieu_chuan', diem_hieu_chuan,
        'thang_1', thang_1, 'thang_2', thang_2, 'thang_3', thang_3, 'thang_4', thang_4, 'thang_5', thang_5, 'thang_6', thang_6,
        'thang_7', thang_7, 'thang_8', thang_8, 'thang_9', thang_9, 'thang_10', thang_10, 'thang_11', thang_11, 'thang_12', thang_12,
        'thang_1_hoan_thanh', thang_1_hoan_thanh, 'thang_2_hoan_thanh', thang_2_hoan_thanh, 'thang_3_hoan_thanh', thang_3_hoan_thanh,
        'thang_4_hoan_thanh', thang_4_hoan_thanh, 'thang_5_hoan_thanh', thang_5_hoan_thanh, 'thang_6_hoan_thanh', thang_6_hoan_thanh,
        'thang_7_hoan_thanh', thang_7_hoan_thanh, 'thang_8_hoan_thanh', thang_8_hoan_thanh, 'thang_9_hoan_thanh', thang_9_hoan_thanh,
        'thang_10_hoan_thanh', thang_10_hoan_thanh, 'thang_11_hoan_thanh', thang_11_hoan_thanh, 'thang_12_hoan_thanh', thang_12_hoan_thanh,
        'ghi_chu', ghi_chu
      ) ORDER BY nam DESC, loai_cong_viec, plan_id, task_id) FROM rows), '[]'::JSONB),
      'totalPlans', COALESCE((SELECT COUNT(DISTINCT plan_id)::BIGINT FROM rows), 0),
      'yearFilter', p_nam
    )
  );
END;
$$;


ALTER FUNCTION public.ai_maintenance_plan_lookup(p_thiet_bi_id bigint, p_nam integer, p_don_vi bigint, p_user_id text) OWNER TO postgres;

--
-- Name: ai_maintenance_summary(text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_maintenance_summary("fromDate" text DEFAULT NULL::text, "toDate" text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_effective BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
  v_from_date DATE := NULL;
  v_to_date DATE := NULL;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_global := (v_role = 'global');

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NOT NULL
     AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL
     AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(BTRIM("fromDate"), '') IS NOT NULL THEN
    v_from_date := NULLIF(BTRIM("fromDate"), '')::DATE;
  END IF;
  IF NULLIF(BTRIM("toDate"), '') IS NOT NULL THEN
    v_to_date := NULLIF(BTRIM("toDate"), '')::DATE;
  END IF;
  IF v_from_date IS NOT NULL AND v_to_date IS NOT NULL AND v_from_date > v_to_date THEN
    RAISE EXCEPTION 'fromDate must be before or equal to toDate' USING ERRCODE = '22007';
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN
      RETURN jsonb_build_object(
        'totalTasks', 0,
        'totalPlans', 0,
        'statusCounts', '{}'::JSONB,
        'taskTypeCounts', '{}'::JSONB,
        'recentTasks', '[]'::JSONB,
        'fromDate', v_from_date,
        'toDate', v_to_date
      );
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  ELSE
    IF p_don_vi IS NOT NULL AND p_don_vi IS DISTINCT FROM v_don_vi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
    v_effective := ARRAY[v_don_vi];
  END IF;

  RETURN (
    WITH filtered AS (
      SELECT
        cv.id AS task_id,
        cv.loai_cong_viec,
        cv.don_vi_thuc_hien,
        cv.updated_at AS task_updated_at,
        kh.id AS plan_id,
        kh.ten_ke_hoach,
        kh.nam,
        kh.trang_thai AS plan_status,
        kh.ngay_phe_duyet,
        tb.id AS equipment_id,
        tb.ma_thiet_bi,
        tb.ten_thiet_bi,
        tb.model
      FROM public.cong_viec_bao_tri cv
      JOIN public.ke_hoach_bao_tri kh ON kh.id = cv.ke_hoach_id
      LEFT JOIN public.thiet_bi tb ON tb.id = cv.thiet_bi_id
      WHERE (v_effective IS NULL OR COALESCE(tb.don_vi, kh.don_vi) = ANY(v_effective))
        AND (
          v_from_date IS NULL
          OR (kh.ngay_phe_duyet IS NOT NULL AND kh.ngay_phe_duyet::DATE >= v_from_date)
        )
        AND (
          v_to_date IS NULL
          OR (kh.ngay_phe_duyet IS NOT NULL AND kh.ngay_phe_duyet::DATE <= v_to_date)
        )
    ),
    status_counts AS (
      SELECT
        COALESCE(NULLIF(BTRIM(plan_status), ''), 'Khong xac dinh') AS k,
        COUNT(DISTINCT plan_id)::BIGINT AS c
      FROM filtered
      GROUP BY 1
    ),
    task_type_counts AS (
      SELECT
        COALESCE(NULLIF(BTRIM(loai_cong_viec), ''), 'khac') AS k,
        COUNT(*)::BIGINT AS c
      FROM filtered
      GROUP BY 1
    ),
    recent AS (
      SELECT *
      FROM filtered
      ORDER BY COALESCE(task_updated_at, ngay_phe_duyet) DESC NULLS LAST, task_id DESC
      LIMIT 20
    )
    SELECT jsonb_build_object(
      'totalTasks', COALESCE((SELECT COUNT(*)::BIGINT FROM filtered), 0),
      'totalPlans', COALESCE((SELECT COUNT(DISTINCT plan_id)::BIGINT FROM filtered), 0),
      'statusCounts', COALESCE((SELECT jsonb_object_agg(k, c) FROM status_counts), '{}'::JSONB),
      'taskTypeCounts', COALESCE((SELECT jsonb_object_agg(k, c) FROM task_type_counts), '{}'::JSONB),
      'recentTasks',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'task_id', task_id,
              'loai_cong_viec', loai_cong_viec,
              'don_vi_thuc_hien', don_vi_thuc_hien,
              'plan_id', plan_id,
              'ten_ke_hoach', ten_ke_hoach,
              'nam', nam,
              'plan_status', plan_status,
              'ngay_phe_duyet', ngay_phe_duyet,
              'equipment_id', equipment_id,
              'ma_thiet_bi', ma_thiet_bi,
              'ten_thiet_bi', ten_thiet_bi,
              'model', model
            )
            ORDER BY COALESCE(task_updated_at, ngay_phe_duyet) DESC NULLS LAST, task_id DESC
          )
          FROM recent
        ),
        '[]'::JSONB
      ),
      'fromDate', v_from_date,
      'toDate', v_to_date
    )
  );
END;
$$;


ALTER FUNCTION public.ai_maintenance_summary("fromDate" text, "toDate" text, p_don_vi bigint, p_user_id text) OWNER TO postgres;

--
-- Name: ai_quota_compliance_summary(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_quota_compliance_summary(p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
  v_effective_don_vi BIGINT;
  v_facility_name TEXT;
  v_decision_id BIGINT;
  v_decision_so TEXT;
  v_decision_trang_thai TEXT;
  v_decision_ngay_hieu_luc DATE;
  v_total_categories BIGINT;
  v_dat_count BIGINT;
  v_thieu_count BIGINT;
  v_vuot_count BIGINT;
  v_unmapped_count BIGINT;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501'; END IF;
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501'; END IF;
  IF v_role = 'admin' THEN v_role := 'global'; END IF;
  v_is_global := (v_role = 'global');
  IF NOT v_is_global AND v_don_vi IS NULL THEN RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501'; END IF;
  IF p_user_id IS NOT NULL AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NULL THEN RETURN jsonb_build_object('kind', 'quotaSummary', 'error', 'Facility selection required', 'evidence_status', 'none'); END IF;
    v_effective_don_vi := p_don_vi;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN RETURN jsonb_build_object('kind', 'quotaSummary', 'error', 'No accessible facilities', 'evidence_status', 'none'); END IF;
    IF p_don_vi IS NULL THEN RETURN jsonb_build_object('kind', 'quotaSummary', 'error', 'Facility selection required', 'evidence_status', 'none'); END IF;
    IF NOT (p_don_vi = ANY(v_allowed)) THEN RETURN jsonb_build_object('kind', 'quotaSummary', 'error', 'Access denied for selected facility', 'evidence_status', 'none'); END IF;
    v_effective_don_vi := p_don_vi;
  ELSE
    -- Local user: reject mismatched facility override, then force own facility
    IF p_don_vi IS NOT NULL AND p_don_vi IS DISTINCT FROM v_don_vi THEN
      RAISE EXCEPTION 'don_vi claim mismatch' USING ERRCODE = '42501';
    END IF;
    v_effective_don_vi := v_don_vi;
  END IF;

  -- Validate facility exists
  SELECT dv.name INTO v_facility_name FROM public.don_vi dv WHERE dv.id = v_effective_don_vi;
  IF NOT FOUND THEN RETURN jsonb_build_object('kind', 'quotaSummary', 'error', 'Facility not found', 'evidence_status', 'none'); END IF;

  SELECT qd.id, qd.so_quyet_dinh, qd.trang_thai, qd.ngay_hieu_luc
  INTO v_decision_id, v_decision_so, v_decision_trang_thai, v_decision_ngay_hieu_luc
  FROM public.quyet_dinh_dinh_muc qd WHERE qd.don_vi_id = v_effective_don_vi AND qd.trang_thai = 'active' ORDER BY qd.ngay_hieu_luc DESC LIMIT 1;

  SELECT COUNT(*)::BIGINT INTO v_unmapped_count FROM public.thiet_bi tb WHERE tb.don_vi = v_effective_don_vi AND tb.nhom_thiet_bi_id IS NULL AND tb.is_deleted = FALSE;

  IF v_decision_id IS NULL THEN
    RETURN jsonb_build_object('kind', 'quotaSummary', 'scope', jsonb_build_object('mode', 'facility', 'don_vi_id', v_effective_don_vi, 'label', v_facility_name), 'decision', NULL, 'summary', jsonb_build_object('total_categories', 0, 'dat_count', 0, 'thieu_count', 0, 'vuot_count', 0, 'unmapped_equipment', v_unmapped_count), 'evidence_status', 'none', 'message', 'No active quota decision found for this facility');
  END IF;

  WITH equipment_counts AS (
    SELECT tb.nhom_thiet_bi_id, COUNT(*)::BIGINT AS so_luong_hien_co
    FROM public.thiet_bi tb WHERE tb.don_vi = v_effective_don_vi AND tb.nhom_thiet_bi_id IS NOT NULL AND tb.is_deleted = FALSE GROUP BY tb.nhom_thiet_bi_id
  ), compliance_status AS (
    SELECT CASE WHEN COALESCE(ec.so_luong_hien_co, 0) < cd.so_luong_toi_thieu THEN 'thieu' WHEN COALESCE(ec.so_luong_hien_co, 0) > cd.so_luong_toi_da THEN 'vuot' ELSE 'dat' END AS trang_thai
    FROM public.chi_tiet_dinh_muc cd LEFT JOIN equipment_counts ec ON ec.nhom_thiet_bi_id = cd.nhom_thiet_bi_id WHERE cd.quyet_dinh_id = v_decision_id
  )
  SELECT COUNT(*)::BIGINT, COUNT(*) FILTER (WHERE trang_thai = 'dat')::BIGINT, COUNT(*) FILTER (WHERE trang_thai = 'thieu')::BIGINT, COUNT(*) FILTER (WHERE trang_thai = 'vuot')::BIGINT
  INTO v_total_categories, v_dat_count, v_thieu_count, v_vuot_count FROM compliance_status;

  RETURN jsonb_build_object('kind', 'quotaSummary', 'scope', jsonb_build_object('mode', 'facility', 'don_vi_id', v_effective_don_vi, 'label', v_facility_name), 'decision', jsonb_build_object('id', v_decision_id, 'so_quyet_dinh', v_decision_so, 'trang_thai', v_decision_trang_thai, 'ngay_hieu_luc', v_decision_ngay_hieu_luc), 'summary', jsonb_build_object('total_categories', COALESCE(v_total_categories, 0), 'dat_count', COALESCE(v_dat_count, 0), 'thieu_count', COALESCE(v_thieu_count, 0), 'vuot_count', COALESCE(v_vuot_count, 0), 'unmapped_equipment', v_unmapped_count), 'evidence_status', 'complete', 'suggested_follow_ups', jsonb_build_array('Xem nhóm thiếu định mức', 'Xem nhóm vượt định mức', 'Xem thiết bị chưa gán danh mục', 'Kiểm tra thiết bị cụ thể'));
END;
$$;


ALTER FUNCTION public.ai_quota_compliance_summary(p_don_vi bigint, p_user_id text) OWNER TO postgres;

--
-- Name: ai_quota_finalize(uuid, text, bigint, bigint, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_quota_finalize(p_reservation_id uuid, p_status text, p_tokens_in bigint, p_tokens_out bigint, p_cost_usd numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims_text TEXT := current_setting('request.jwt.claims', true);
  v_claims JSONB;
  v_claim_user_id TEXT;
  v_role TEXT;
  v_reservation public.ai_quota_reservations%ROWTYPE;
  v_ref RECORD;
  v_tokens_in BIGINT := GREATEST(COALESCE(p_tokens_in, 0), 0);
  v_tokens_out BIGINT := GREATEST(COALESCE(p_tokens_out, 0), 0);
  v_cost_usd NUMERIC(12,6) := GREATEST(COALESCE(p_cost_usd, 0), 0);
  v_now TIMESTAMPTZ := now();
BEGIN
  IF p_status NOT IN ('success', 'error_with_usage', 'error_no_usage') THEN
    RAISE EXCEPTION 'Invalid AI quota finalize status' USING ERRCODE = '22023';
  END IF;

  IF v_claims_text IS NULL OR btrim(v_claims_text) = '' THEN
    RAISE EXCEPTION 'Missing JWT claims' USING ERRCODE = '42501';
  END IF;

  v_claims := v_claims_text::jsonb;
  v_claim_user_id := NULLIF(v_claims->>'user_id', '');
  v_role := NULLIF(v_claims->>'app_role', '');

  IF v_claim_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_reservation
  FROM public.ai_quota_reservations
  WHERE id = p_reservation_id
  FOR UPDATE;

  IF NOT FOUND OR v_reservation.status <> 'reserved' THEN
    RETURN;
  END IF;

  IF v_reservation.user_id IS DISTINCT FROM v_claim_user_id THEN
    RAISE EXCEPTION 'reservation user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  FOR v_ref IN
    SELECT ref->>'scope' AS scope, ref->>'key' AS key, ref->>'window_id' AS window_id
    FROM jsonb_array_elements(v_reservation.counter_refs) AS ref
    ORDER BY ref->>'scope', ref->>'key', ref->>'window_id'
  LOOP
    UPDATE public.ai_quota_counters
    SET reserved = GREATEST(reserved - 1, 0),
        count = count + CASE WHEN p_status IN ('success', 'error_with_usage') THEN 1 ELSE 0 END,
        tokens_in = tokens_in + CASE WHEN p_status IN ('success', 'error_with_usage') THEN v_tokens_in ELSE 0 END,
        tokens_out = tokens_out + CASE WHEN p_status IN ('success', 'error_with_usage') THEN v_tokens_out ELSE 0 END,
        cost_usd = cost_usd + CASE WHEN p_status IN ('success', 'error_with_usage') THEN v_cost_usd ELSE 0 END,
        updated_at = v_now
    WHERE scope = v_ref.scope
      AND key = v_ref.key
      AND window_id = v_ref.window_id;
  END LOOP;

  IF p_status = 'error_no_usage' THEN
    DELETE FROM public.ai_rate_events
    WHERE reservation_id = p_reservation_id;
  END IF;

  UPDATE public.ai_quota_reservations
  SET status = p_status,
      tokens_in = v_tokens_in,
      tokens_out = v_tokens_out,
      cost_usd = v_cost_usd
  WHERE id = p_reservation_id;
END;
$$;


ALTER FUNCTION public.ai_quota_finalize(p_reservation_id uuid, p_status text, p_tokens_in bigint, p_tokens_out bigint, p_cost_usd numeric) OWNER TO postgres;

--
-- Name: ai_quota_release_expired(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_quota_release_expired(p_now timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims_text TEXT := current_setting('request.jwt.claims', true);
  v_claims JSONB;
  v_role TEXT;
  v_now TIMESTAMPTZ := now();
  v_expired RECORD;
  v_ref RECORD;
  v_released INTEGER := 0;
BEGIN
  IF v_claims_text IS NULL OR btrim(v_claims_text) = '' THEN
    RAISE EXCEPTION 'Missing JWT claims' USING ERRCODE = '42501';
  END IF;

  v_claims := v_claims_text::jsonb;
  v_role := COALESCE(NULLIF(v_claims->>'app_role', ''), NULLIF(v_claims->>'role', ''));

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('global', 'service_role') THEN
    RAISE EXCEPTION 'Insufficient privileges to release AI quota reservations' USING ERRCODE = '42501';
  END IF;

  FOR v_expired IN
    SELECT *
    FROM public.ai_quota_reservations
    WHERE status = 'reserved'
      AND expires_at < v_now
    ORDER BY id
    FOR UPDATE
  LOOP
    FOR v_ref IN
      SELECT ref->>'scope' AS scope, ref->>'key' AS key, ref->>'window_id' AS window_id
      FROM jsonb_array_elements(v_expired.counter_refs) AS ref
      ORDER BY ref->>'scope', ref->>'key', ref->>'window_id'
    LOOP
      UPDATE public.ai_quota_counters
      SET reserved = GREATEST(reserved - 1, 0),
          updated_at = v_now
      WHERE scope = v_ref.scope
        AND key = v_ref.key
        AND window_id = v_ref.window_id;
    END LOOP;

    UPDATE public.ai_quota_reservations
    SET status = 'expired'
    WHERE id = v_expired.id;

    v_released := v_released + 1;
  END LOOP;

  RETURN v_released;
END;
$$;


ALTER FUNCTION public.ai_quota_release_expired(p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: ai_quota_reserve(text, integer, integer, integer, integer, integer, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_quota_reserve(p_user_id text, p_tenant_id integer, p_rate_window_ms integer, p_rate_max integer, p_user_daily_max integer, p_tenant_daily_max integer, p_global_daily_max integer, p_ttl_ms integer, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(allowed boolean, reservation_id uuid, reason text, message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims_text TEXT := current_setting('request.jwt.claims', true);
  v_claims JSONB;
  v_claim_user_id TEXT;
  v_role TEXT;
  v_now TIMESTAMPTZ := now();
  v_window_id TEXT;
  v_window_expires_at TIMESTAMPTZ;
  v_counter_refs JSONB;
  v_reservation_id UUID := gen_random_uuid();
  v_rate_count INTEGER;
  v_counter RECORD;
  v_expired RECORD;
  v_ref RECORD;
  v_limit INTEGER;
BEGIN
  IF p_user_id IS NULL OR btrim(p_user_id) = '' THEN
    RAISE EXCEPTION 'Missing user id' USING ERRCODE = '22023';
  END IF;

  IF p_rate_window_ms IS NULL OR p_rate_window_ms <= 0
     OR p_rate_max IS NULL OR p_rate_max < 0
     OR p_user_daily_max IS NULL OR p_user_daily_max < 0
     OR p_tenant_daily_max IS NULL OR p_tenant_daily_max < 0
     OR p_global_daily_max IS NULL OR p_global_daily_max < 0
     OR p_ttl_ms IS NULL OR p_ttl_ms <= 0 THEN
    RAISE EXCEPTION 'Invalid AI quota limit parameter' USING ERRCODE = '22023';
  END IF;

  IF v_claims_text IS NULL OR btrim(v_claims_text) = '' THEN
    RAISE EXCEPTION 'Missing JWT claims' USING ERRCODE = '42501';
  END IF;

  v_claims := v_claims_text::jsonb;
  v_claim_user_id := NULLIF(v_claims->>'user_id', '');
  v_role := NULLIF(v_claims->>'app_role', '');

  IF v_claim_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_claim_user_id IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  v_window_id := to_char(v_now AT TIME ZONE 'UTC', 'YYYY-MM-DD');
  v_window_expires_at := (
    date_trunc('day', v_now AT TIME ZONE 'UTC') + interval '1 day'
  ) AT TIME ZONE 'UTC';

  v_counter_refs := jsonb_build_array(jsonb_build_object(
    'scope', 'user_daily',
    'key', p_user_id,
    'window_id', v_window_id
  ));

  IF p_tenant_id IS NOT NULL THEN
    v_counter_refs := v_counter_refs || jsonb_build_array(jsonb_build_object(
      'scope', 'tenant_daily',
      'key', p_tenant_id::text,
      'window_id', v_window_id
    ));
  END IF;

  v_counter_refs := v_counter_refs || jsonb_build_array(jsonb_build_object(
    'scope', 'global_daily',
    'key', 'global',
    'window_id', v_window_id
  ));

  -- Preserve global lock order: reservations first, then counters.
  FOR v_expired IN
    SELECT *
    FROM public.ai_quota_reservations
    WHERE status = 'reserved'
      AND expires_at < v_now
      AND (
        counter_refs @> jsonb_build_array(jsonb_build_object('scope', 'user_daily', 'key', p_user_id))
        OR (p_tenant_id IS NOT NULL AND counter_refs @> jsonb_build_array(jsonb_build_object('scope', 'tenant_daily', 'key', p_tenant_id::text)))
        OR counter_refs @> jsonb_build_array(jsonb_build_object('scope', 'global_daily', 'key', 'global'))
      )
    ORDER BY id
    FOR UPDATE
  LOOP
    FOR v_ref IN
      SELECT ref->>'scope' AS scope, ref->>'key' AS key, ref->>'window_id' AS window_id
      FROM jsonb_array_elements(v_expired.counter_refs) AS ref
      ORDER BY ref->>'scope', ref->>'key', ref->>'window_id'
    LOOP
      UPDATE public.ai_quota_counters
      SET reserved = GREATEST(reserved - 1, 0),
          updated_at = v_now
      WHERE scope = v_ref.scope
        AND key = v_ref.key
        AND window_id = v_ref.window_id;
    END LOOP;

    UPDATE public.ai_quota_reservations
    SET status = 'expired'
    WHERE id = v_expired.id;
  END LOOP;

  DELETE FROM public.ai_rate_events
  WHERE user_id = p_user_id
    AND ts < v_now - (p_rate_window_ms * interval '1 millisecond');

  WITH refs AS (
    SELECT r.scope, r.key, r.window_id
    FROM jsonb_to_recordset(v_counter_refs) AS r(scope TEXT, key TEXT, window_id TEXT)
    ORDER BY r.scope, r.key, r.window_id
  )
  INSERT INTO public.ai_quota_counters(scope, key, window_id, expires_at, updated_at)
  SELECT refs.scope, refs.key, refs.window_id, v_window_expires_at, v_now
  FROM refs
  ON CONFLICT (scope, key, window_id) DO UPDATE
  SET expires_at = GREATEST(public.ai_quota_counters.expires_at, EXCLUDED.expires_at),
      updated_at = v_now;

  -- Lock the per-user daily counter before checking the sliding rate window.
  -- This serializes reservations for the same user without a separate lock table.
  PERFORM 1
  FROM public.ai_quota_counters c
  WHERE c.scope = 'user_daily'
    AND c.key = p_user_id
    AND c.window_id = v_window_id
  FOR UPDATE;

  SELECT count(*)::integer
  INTO v_rate_count
  FROM public.ai_rate_events
  WHERE user_id = p_user_id
    AND ts >= v_now - (p_rate_window_ms * interval '1 millisecond');

  IF v_rate_count >= p_rate_max THEN
    allowed := false;
    reservation_id := NULL;
    reason := 'rate_limit';
    message := 'AI rate limit exceeded';
    RETURN NEXT;
    RETURN;
  END IF;

  FOR v_counter IN
    SELECT c.*
    FROM public.ai_quota_counters c
    JOIN jsonb_to_recordset(v_counter_refs) AS r(scope TEXT, key TEXT, window_id TEXT)
      ON r.scope = c.scope
     AND r.key = c.key
     AND r.window_id = c.window_id
    ORDER BY c.scope, c.key, c.window_id
    FOR UPDATE OF c
  LOOP
    v_limit := CASE v_counter.scope
      WHEN 'user_daily' THEN p_user_daily_max
      WHEN 'tenant_daily' THEN p_tenant_daily_max
      WHEN 'global_daily' THEN p_global_daily_max
      ELSE 0
    END;

    IF v_counter.count + v_counter.reserved >= v_limit THEN
      allowed := false;
      reservation_id := NULL;
      reason := CASE v_counter.scope
        WHEN 'user_daily' THEN 'user_quota'
        WHEN 'tenant_daily' THEN 'tenant_quota'
        WHEN 'global_daily' THEN 'global_quota'
        ELSE 'quota'
      END;
      message := 'AI daily quota exceeded';
      RETURN NEXT;
      RETURN;
    END IF;
  END LOOP;

  FOR v_ref IN
    SELECT ref->>'scope' AS scope, ref->>'key' AS key, ref->>'window_id' AS window_id
    FROM jsonb_array_elements(v_counter_refs) AS ref
    ORDER BY ref->>'scope', ref->>'key', ref->>'window_id'
  LOOP
    UPDATE public.ai_quota_counters
    SET reserved = reserved + 1,
        updated_at = v_now
    WHERE scope = v_ref.scope
      AND key = v_ref.key
      AND window_id = v_ref.window_id;
  END LOOP;

  INSERT INTO public.ai_rate_events(reservation_id, user_id, ts)
  VALUES (v_reservation_id, p_user_id, v_now);

  INSERT INTO public.ai_quota_reservations(
    id,
    user_id,
    tenant_id,
    reserved_at,
    expires_at,
    status,
    counter_refs
  )
  VALUES (
    v_reservation_id,
    p_user_id,
    p_tenant_id,
    v_now,
    v_now + (p_ttl_ms * interval '1 millisecond'),
    'reserved',
    v_counter_refs
  );

  allowed := true;
  reservation_id := v_reservation_id;
  reason := NULL;
  message := NULL;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.ai_quota_reserve(p_user_id text, p_tenant_id integer, p_rate_window_ms integer, p_rate_max integer, p_user_daily_max integer, p_tenant_daily_max integer, p_global_daily_max integer, p_ttl_ms integer, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: ai_repair_summary(text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_repair_summary(status text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_effective BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
  v_status_filter TEXT := NULLIF(BTRIM(status), '');
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_global := (v_role = 'global');

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NOT NULL
     AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL
     AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN
      RETURN jsonb_build_object(
        'totalRequests', 0,
        'openRequests', 0,
        'statusCounts', '{}'::JSONB,
        'recentRequests', '[]'::JSONB,
        'statusFilter', v_status_filter
      );
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  ELSE
    IF p_don_vi IS NOT NULL AND p_don_vi IS DISTINCT FROM v_don_vi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
    v_effective := ARRAY[v_don_vi];
  END IF;

  RETURN (
    WITH scoped AS (
      SELECT
        r.id,
        r.thiet_bi_id,
        r.ngay_yeu_cau,
        r.trang_thai,
        r.mo_ta_su_co,
        r.hang_muc_sua_chua,
        r.ngay_hoan_thanh,
        r.don_vi_thuc_hien,
        r.ten_don_vi_thue,
        tb.ma_thiet_bi,
        tb.ten_thiet_bi,
        tb.model,
        tb.khoa_phong_quan_ly,
        tb.don_vi,
        dv.name AS facility_name
      FROM public.yeu_cau_sua_chua r
      LEFT JOIN public.thiet_bi tb ON tb.id = r.thiet_bi_id
      LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
      WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
    ),
    filtered AS (
      SELECT *
      FROM scoped
      WHERE v_status_filter IS NULL OR trang_thai = v_status_filter
    ),
    status_counts AS (
      SELECT
        COALESCE(NULLIF(BTRIM(trang_thai), ''), 'Khong xac dinh') AS k,
        COUNT(*)::BIGINT AS c
      FROM scoped
      GROUP BY 1
    ),
    recent AS (
      SELECT *
      FROM filtered
      ORDER BY ngay_yeu_cau DESC NULLS LAST, id DESC
      LIMIT 20
    )
    SELECT jsonb_build_object(
      'totalRequests', COALESCE((SELECT COUNT(*)::BIGINT FROM filtered), 0),
      'openRequests', COALESCE((SELECT COUNT(*)::BIGINT FROM filtered WHERE trang_thai IN ('Chờ xử lý', 'Đã duyệt')), 0),
      'statusCounts', COALESCE((SELECT jsonb_object_agg(k, c) FROM status_counts), '{}'::JSONB),
      'recentRequests',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', id,
              'thiet_bi_id', thiet_bi_id,
              'ngay_yeu_cau', ngay_yeu_cau,
              'trang_thai', trang_thai,
              'mo_ta_su_co', mo_ta_su_co,
              'hang_muc_sua_chua', hang_muc_sua_chua,
              'ngay_hoan_thanh', ngay_hoan_thanh,
              'don_vi_thuc_hien', don_vi_thuc_hien,
              'ten_don_vi_thue', ten_don_vi_thue,
              'ma_thiet_bi', ma_thiet_bi,
              'ten_thiet_bi', ten_thiet_bi,
              'model', model,
              'khoa_phong_quan_ly', khoa_phong_quan_ly,
              'don_vi', don_vi,
              'facility_name', facility_name
            )
            ORDER BY ngay_yeu_cau DESC NULLS LAST, id DESC
          )
          FROM recent
        ),
        '[]'::JSONB
      ),
      'statusFilter', v_status_filter
    )
  );
END;
$$;


ALTER FUNCTION public.ai_repair_summary(status text, p_don_vi bigint, p_user_id text) OWNER TO postgres;

--
-- Name: ai_usage_summary(bigint, integer, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_usage_summary(p_thiet_bi_id bigint, p_months integer DEFAULT 6, p_don_vi bigint DEFAULT NULL::bigint, p_user_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_allowed BIGINT[] := NULL;
  v_is_global BOOLEAN := FALSE;
  v_equip_don_vi BIGINT;
  v_cutoff TIMESTAMPTZ;
  v_months INT := GREATEST(LEAST(COALESCE(p_months, 6), 24), 1);
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;
  IF v_role = 'admin' THEN v_role := 'global'; END IF;
  v_is_global := (v_role = 'global');
  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NOT NULL
     AND NULLIF(BTRIM(p_user_id), '') IS NOT NULL
     AND BTRIM(p_user_id) IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_thiet_bi_id IS NULL OR p_thiet_bi_id <= 0 THEN
    RETURN jsonb_build_object('error', 'Invalid thiet_bi_id', 'thiet_bi_id', p_thiet_bi_id);
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NULL THEN
      RETURN jsonb_build_object('error', 'Facility selection required', 'thiet_bi_id', p_thiet_bi_id);
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR cardinality(v_allowed) = 0 THEN
      RETURN jsonb_build_object('error', 'No accessible facilities', 'thiet_bi_id', p_thiet_bi_id);
    END IF;
    IF p_don_vi IS NULL THEN
      RETURN jsonb_build_object('error', 'Facility selection required', 'thiet_bi_id', p_thiet_bi_id);
    END IF;
    IF NOT (p_don_vi = ANY(v_allowed)) THEN
      RETURN jsonb_build_object('error', 'Access denied for selected facility', 'thiet_bi_id', p_thiet_bi_id);
    END IF;
  END IF;

  SELECT tb.don_vi INTO v_equip_don_vi
  FROM public.thiet_bi tb
  WHERE tb.id = p_thiet_bi_id
    AND tb.is_deleted = FALSE
    AND (CASE WHEN v_is_global THEN tb.don_vi = p_don_vi
              WHEN v_role = 'regional_leader' THEN tb.don_vi = p_don_vi
              ELSE tb.don_vi = v_don_vi END);

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Equipment not found or not accessible', 'thiet_bi_id', p_thiet_bi_id);
  END IF;

  v_cutoff := NOW() - (v_months || ' months')::INTERVAL;

  RETURN (
    WITH usage_data AS (
      SELECT nk.thoi_gian_bat_dau, nk.thoi_gian_ket_thuc, nk.tinh_trang_thiet_bi,
             EXTRACT(EPOCH FROM (nk.thoi_gian_ket_thuc - nk.thoi_gian_bat_dau)) / 3600.0 AS duration_hours
      FROM public.nhat_ky_su_dung nk
      WHERE nk.thiet_bi_id = p_thiet_bi_id AND nk.thoi_gian_bat_dau >= v_cutoff
    ),
    condition_agg AS (
      SELECT COALESCE(NULLIF(BTRIM(tinh_trang_thiet_bi), ''), 'Không xác định') AS condition, COUNT(*)::BIGINT AS cnt
      FROM usage_data GROUP BY 1
    ),
    last_30 AS (
      SELECT COUNT(*)::BIGINT AS c FROM public.nhat_ky_su_dung nk
      WHERE nk.thiet_bi_id = p_thiet_bi_id AND nk.thoi_gian_bat_dau >= NOW() - INTERVAL '30 days'
    ),
    last_90 AS (
      SELECT COUNT(*)::BIGINT AS c FROM public.nhat_ky_su_dung nk
      WHERE nk.thiet_bi_id = p_thiet_bi_id AND nk.thoi_gian_bat_dau >= NOW() - INTERVAL '90 days'
    )
    SELECT jsonb_build_object(
      'thiet_bi_id', p_thiet_bi_id,
      'total_sessions', COALESCE((SELECT COUNT(*)::BIGINT FROM usage_data), 0),
      'avg_duration_hours', COALESCE((SELECT ROUND(AVG(duration_hours)::NUMERIC, 2) FROM usage_data WHERE duration_hours IS NOT NULL), 0),
      'sessions_last_30_days', COALESCE((SELECT c FROM last_30), 0),
      'sessions_last_90_days', COALESCE((SELECT c FROM last_90), 0),
      'condition_counts', COALESCE((SELECT jsonb_object_agg(condition, cnt) FROM condition_agg), '{}'::JSONB),
      'earliest_session', (SELECT MIN(thoi_gian_bat_dau)::DATE FROM usage_data),
      'latest_session', (SELECT MAX(thoi_gian_bat_dau)::DATE FROM usage_data),
      'months_range', v_months
    )
  );
END;
$$;


ALTER FUNCTION public.ai_usage_summary(p_thiet_bi_id bigint, p_months integer, p_don_vi bigint, p_user_id text) OWNER TO postgres;

--
-- Name: allowed_don_vi_for_session(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.allowed_don_vi_for_session() RETURNS bigint[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_role TEXT;
    v_user_don_vi BIGINT;
    v_user_region_id BIGINT;
    v_allowed_don_vi BIGINT[];
    v_jwt_claims JSONB;
BEGIN
    -- Get user context from JWT claims with multiple fallbacks
    -- Method 1: Try safe helper function
    v_user_role := COALESCE(
        public._get_jwt_claim_safe('app_role'),
        public._get_jwt_claim_safe('role')
    );
    
    -- If still NULL, try direct extraction
    IF v_user_role IS NULL THEN
        BEGIN
            v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
            v_user_role := COALESCE(
                v_jwt_claims ->> 'app_role',
                v_jwt_claims ->> 'role'
            );
        EXCEPTION WHEN OTHERS THEN
            v_user_role := NULL;
        END;
    END IF;
    
    -- Get other claims with safe extraction
    v_user_don_vi := NULLIF(public._get_jwt_claim_safe('don_vi'), '')::BIGINT;
    IF v_user_don_vi IS NULL THEN
        BEGIN
            v_jwt_claims := COALESCE(v_jwt_claims, current_setting('request.jwt.claims', true)::jsonb);
            v_user_don_vi := NULLIF(v_jwt_claims ->> 'don_vi', '')::BIGINT;
        EXCEPTION WHEN OTHERS THEN
            v_user_don_vi := NULL;
        END;
    END IF;
    
    v_user_region_id := NULLIF(public._get_jwt_claim_safe('dia_ban'), '')::BIGINT;
    IF v_user_region_id IS NULL THEN
        BEGIN
            v_jwt_claims := COALESCE(v_jwt_claims, current_setting('request.jwt.claims', true)::jsonb);
            v_user_region_id := NULLIF(v_jwt_claims ->> 'dia_ban', '')::BIGINT;
        EXCEPTION WHEN OTHERS THEN
            v_user_region_id := NULL;
        END;
    END IF;
    
    -- Debug logging (can be removed in production)
    RAISE LOG 'JWT Claims - Role: %, DonVi: %, DiaBan: %', v_user_role, v_user_don_vi, v_user_region_id;
    
    -- Handle different role access patterns
    CASE v_user_role
        WHEN 'global' THEN
            -- Global users can access all don_vi
            SELECT array_agg(id) INTO v_allowed_don_vi 
            FROM public.don_vi 
            WHERE active = true;
             
        WHEN 'regional_leader' THEN
            -- Regional leaders can access all don_vi in their region
            IF v_user_region_id IS NULL THEN
                RAISE EXCEPTION 'Regional leader must have dia_ban assigned';
            END IF;
            
            SELECT array_agg(id) INTO v_allowed_don_vi 
            FROM public.don_vi 
            WHERE dia_ban_id = v_user_region_id 
            AND active = true;
            
        WHEN 'admin', 'to_qltb', 'qltb_khoa', 'technician', 'user' THEN
            -- Other roles are limited to their specific don_vi
            IF v_user_don_vi IS NULL THEN
                RAISE EXCEPTION 'User must have don_vi assigned for role %', v_user_role;
            END IF;
            
            v_allowed_don_vi := ARRAY[v_user_don_vi];
            
        ELSE
            -- Unknown role - provide more helpful error
            IF v_user_role IS NULL THEN
                RAISE EXCEPTION 'JWT role claim is NULL or missing. Check JWT configuration.';
            ELSE
                RAISE EXCEPTION 'Unknown role: %', v_user_role;
            END IF;
    END CASE;
    
    -- Return empty array if no access (safety fallback)
    RETURN COALESCE(v_allowed_don_vi, ARRAY[]::BIGINT[]);
END;
$$;


ALTER FUNCTION public.allowed_don_vi_for_session() OWNER TO postgres;

--
-- Name: FUNCTION allowed_don_vi_for_session(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.allowed_don_vi_for_session() IS 'Returns array of don_vi IDs that current session user can access based on role and dia_ban. FIXED: Now uses robust JWT claim reading with multiple fallbacks.';


--
-- Name: allowed_don_vi_for_session_safe(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.allowed_don_vi_for_session_safe() RETURNS bigint[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_role TEXT;
    v_user_don_vi BIGINT;
    v_user_region_id BIGINT;
    v_allowed_don_vi BIGINT[];
    v_jwt_claims JSONB;
BEGIN
    -- Check if JWT claims are available at all
    BEGIN
        v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
    EXCEPTION WHEN OTHERS THEN
        -- No JWT claims available - return empty array
        RETURN ARRAY[]::BIGINT[];
    END;
    
    -- Get user context from JWT claims
    v_user_role := COALESCE(
        v_jwt_claims ->> 'app_role',
        v_jwt_claims ->> 'role'
    );
    
    -- Get other claims - FIX: Read dia_ban directly from JWT
    v_user_don_vi := NULLIF(v_jwt_claims ->> 'don_vi', '')::BIGINT;
    v_user_region_id := NULLIF(v_jwt_claims ->> 'dia_ban', '')::BIGINT;
    
    -- Debug log
    RAISE LOG 'allowed_don_vi_for_session_safe - Role: %, DonVi: %, RegionId: %', 
              v_user_role, v_user_don_vi, v_user_region_id;
    
    -- If no role is found, return empty array instead of raising exception
    IF v_user_role IS NULL OR v_user_role = '' THEN
        RETURN ARRAY[]::BIGINT[];
    END IF;
    
    -- Handle different role access patterns
    CASE lower(v_user_role)
        WHEN 'global' THEN
            -- Global users can access all don_vi
            SELECT array_agg(id) INTO v_allowed_don_vi 
            FROM public.don_vi 
            WHERE active = true;
             
        WHEN 'regional_leader' THEN
            -- Regional leaders can access all don_vi in their region
            -- FIX: v_user_region_id is now correctly read from JWT 'dia_ban' claim
            IF v_user_region_id IS NULL THEN
                RAISE LOG 'Regional leader has no dia_ban claim - returning empty array';
                RETURN ARRAY[]::BIGINT[];
            END IF;
            
            SELECT array_agg(id) INTO v_allowed_don_vi 
            FROM public.don_vi 
            WHERE dia_ban_id = v_user_region_id 
            AND active = true;
            
            RAISE LOG 'Regional leader region % has don_vi: %', v_user_region_id, v_allowed_don_vi;
            
        WHEN 'admin', 'to_qltb', 'qltb_khoa', 'technician', 'user' THEN
            -- Other roles are limited to their specific don_vi
            IF v_user_don_vi IS NULL THEN
                RETURN ARRAY[]::BIGINT[];
            END IF;
            
            v_allowed_don_vi := ARRAY[v_user_don_vi];
            
        ELSE
            -- Unknown role - return empty array instead of raising exception
            RAISE LOG 'Unknown role % - returning empty array', v_user_role;
            RETURN ARRAY[]::BIGINT[];
    END CASE;
    
    -- Return empty array if no access (safety fallback)
    RETURN COALESCE(v_allowed_don_vi, ARRAY[]::BIGINT[]);
END;
$$;


ALTER FUNCTION public.allowed_don_vi_for_session_safe() OWNER TO postgres;

--
-- Name: FUNCTION allowed_don_vi_for_session_safe(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.allowed_don_vi_for_session_safe() IS 'Returns array of don_vi IDs accessible by current session. 
FIXED: Regional leaders now correctly read dia_ban from JWT claims.';


--
-- Name: assistant_query_database_audit_log(text, text, text, integer, integer, integer, bigint, text, text, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assistant_query_database_audit_log(p_status text, p_tool_path text, p_sql_shape text, p_latency_ms integer, p_row_count integer DEFAULT NULL::integer, p_payload_bytes integer DEFAULT NULL::integer, p_effective_facility_id bigint DEFAULT NULL::bigint, p_facility_source text DEFAULT NULL::text, p_error_class text DEFAULT NULL::text, p_requested_facility_id bigint DEFAULT NULL::bigint, p_session_facility_id bigint DEFAULT NULL::bigint, p_raw_role text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_claims jsonb;
  v_role text;
  v_user_id text;
  v_claim_don_vi text;
  v_allowed bigint[];
  v_facility_exists boolean;
  v_action_details jsonb;
BEGIN
  BEGIN
    v_claims := COALESCE(NULLIF(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Missing JWT claims' USING ERRCODE = '42501';
  END;

  v_role := lower(COALESCE(
    NULLIF(v_claims->>'app_role', ''),
    NULLIF(v_claims->>'role', ''),
    ''
  ));
  v_user_id := NULLIF(COALESCE(v_claims->>'user_id', v_claims->>'sub'), '');
  v_claim_don_vi := NULLIF(v_claims->>'don_vi', '');

  IF v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id !~ '^[0-9]+$' THEN
    RAISE EXCEPTION 'Invalid user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF p_tool_path IS DISTINCT FROM 'query_database' THEN
    RAISE EXCEPTION 'Invalid assistant SQL audit tool path'
      USING ERRCODE = '22023';
  END IF;

  IF p_status IS NULL OR p_status NOT IN ('success', 'failure') THEN
    RAISE EXCEPTION 'Invalid assistant SQL audit status'
      USING ERRCODE = '22023';
  END IF;

  IF p_status = 'failure' AND NULLIF(p_error_class, '') IS NULL THEN
    RAISE EXCEPTION 'Assistant SQL audit failure requires error_class'
      USING ERRCODE = '22023';
  END IF;

  IF p_effective_facility_id IS NULL THEN
    RAISE EXCEPTION 'Missing assistant SQL effective facility scope'
      USING ERRCODE = '42501';
  END IF;

  IF p_facility_source IS NULL OR p_facility_source NOT IN ('selected', 'session') THEN
    RAISE EXCEPTION 'Invalid assistant SQL facility source'
      USING ERRCODE = '22023';
  END IF;

  IF p_latency_ms IS NULL OR p_latency_ms < 0 THEN
    RAISE EXCEPTION 'Invalid assistant SQL audit latency'
      USING ERRCODE = '22023';
  END IF;

  IF p_row_count IS NOT NULL AND p_row_count < 0 THEN
    RAISE EXCEPTION 'Invalid assistant SQL audit row count'
      USING ERRCODE = '22023';
  END IF;

  IF p_payload_bytes IS NOT NULL AND p_payload_bytes < 0 THEN
    RAISE EXCEPTION 'Invalid assistant SQL audit payload size'
      USING ERRCODE = '22023';
  END IF;

  IF NULLIF(BTRIM(p_sql_shape), '') IS NULL OR length(p_sql_shape) > 1000 THEN
    RAISE EXCEPTION 'Invalid assistant SQL audit SQL shape'
      USING ERRCODE = '22023';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.don_vi
    WHERE id = p_effective_facility_id
      AND active = true
  )
  INTO v_facility_exists;

  IF NOT v_facility_exists THEN
    RAISE EXCEPTION 'Assistant SQL effective facility scope is not accessible'
      USING ERRCODE = '42501';
  END IF;

  IF v_role <> 'global' THEN
    v_allowed := public.allowed_don_vi_for_session();

    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RAISE EXCEPTION 'Assistant SQL effective facility scope is not accessible'
        USING ERRCODE = '42501';
    END IF;

    IF NOT (p_effective_facility_id = ANY(v_allowed)) THEN
      RAISE EXCEPTION 'Assistant SQL effective facility scope is not accessible'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_role NOT IN ('global', 'regional_leader') THEN
    IF v_claim_don_vi IS NULL OR v_claim_don_vi !~ '^[0-9]+$' THEN
      RAISE EXCEPTION 'Missing don_vi claim for assistant SQL audit scope'
        USING ERRCODE = '42501';
    END IF;

    IF v_claim_don_vi::bigint IS DISTINCT FROM p_effective_facility_id THEN
      RAISE EXCEPTION 'Assistant SQL local role scope mismatch'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_action_details := jsonb_build_object(
    'tool_path', p_tool_path,
    'sql_shape', p_sql_shape,
    'status', p_status,
    'latency_ms', p_latency_ms,
    'row_count', p_row_count,
    'payload_bytes', p_payload_bytes,
    'effective_facility_id', p_effective_facility_id,
    'facility_source', p_facility_source,
    'error_class', NULLIF(p_error_class, ''),
    'normalized_role', v_role,
    'raw_role', COALESCE(NULLIF(p_raw_role, ''), NULLIF(v_claims->>'app_role', ''), NULLIF(v_claims->>'role', '')),
    'requested_facility_id', p_requested_facility_id,
    'session_facility_id', p_session_facility_id
  );

  IF NOT public.audit_log(
    p_action_type := 'assistant_query_database',
    p_entity_type := 'assistant_sql',
    p_entity_id := p_effective_facility_id,
    p_entity_label := 'query_database',
    p_action_details := v_action_details
  ) THEN
    RAISE EXCEPTION 'audit_log failed for assistant query_database'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN TRUE;
END;
$_$;


