--
-- Name: audit_logs_list(integer, integer, bigint, bigint, text, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_logs_list(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_user_id bigint DEFAULT NULL::bigint, p_target_user_id bigint DEFAULT NULL::bigint, p_action_type text DEFAULT NULL::text, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_don_vi text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_role TEXT;
  v_result json;
  v_total_count BIGINT := 0;
BEGIN
  v_user_role := current_setting('request.jwt.claims', true)::json->>'app_role';
  IF v_user_role IS DISTINCT FROM 'global' THEN
    RAISE EXCEPTION 'Access denied: Only global administrators can view audit logs'
      USING ERRCODE = '42501';
  END IF;

  IF p_limit < 1 OR p_limit > 200 THEN p_limit := 50; END IF;
  IF p_offset < 0 THEN p_offset := 0; END IF;

  SELECT COUNT(*) INTO v_total_count
  FROM public.audit_logs al
  WHERE (p_user_id IS NULL OR al.admin_user_id = p_user_id)
    AND (p_target_user_id IS NULL OR al.target_user_id = p_target_user_id)
    AND (p_action_type IS NULL OR al.action_type ILIKE '%' || p_action_type || '%')
    AND (p_date_from IS NULL OR al.created_at >= p_date_from)
    AND (p_date_to IS NULL OR al.created_at <= p_date_to);

  SELECT json_agg(
    json_build_object(
      'id', al.id,
      'admin_user_id', al.admin_user_id,
      'admin_username', al.admin_username,
      'admin_full_name', COALESCE(admin_user.full_name, al.admin_username),
      'action_type', al.action_type,
      'target_user_id', al.target_user_id,
      'target_username', al.target_username,
      'target_full_name', COALESCE(target_user.full_name, al.target_username),
      'action_details', al.action_details,
      'ip_address', al.ip_address,
      'user_agent', al.user_agent,
      'created_at', al.created_at,
      'total_count', v_total_count
    )
  ) INTO v_result
  FROM (
    SELECT 
      al.id, al.admin_user_id, al.admin_username, al.action_type,
      al.target_user_id, al.target_username, al.action_details,
      al.ip_address, al.user_agent, al.created_at
    FROM public.audit_logs al
    WHERE (p_user_id IS NULL OR al.admin_user_id = p_user_id)
      AND (p_target_user_id IS NULL OR al.target_user_id = p_target_user_id)
      AND (p_action_type IS NULL OR al.action_type ILIKE '%' || p_action_type || '%')
      AND (p_date_from IS NULL OR al.created_at >= p_date_from)
      AND (p_date_to IS NULL OR al.created_at <= p_date_to)
    ORDER BY al.created_at DESC
    LIMIT p_limit
    OFFSET p_offset
  ) al
  LEFT JOIN nhan_vien admin_user ON al.admin_user_id = admin_user.id
  LEFT JOIN nhan_vien target_user ON al.target_user_id = target_user.id;

  RETURN COALESCE(v_result, json_build_array());
END;
$$;


ALTER FUNCTION public.audit_logs_list(p_limit integer, p_offset integer, p_user_id bigint, p_target_user_id bigint, p_action_type text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_don_vi text) OWNER TO postgres;

--
-- Name: audit_logs_list_v2(integer, integer, bigint, text, bigint, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_logs_list_v2(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_user_id bigint DEFAULT NULL::bigint, p_entity_type text DEFAULT NULL::text, p_entity_id bigint DEFAULT NULL::bigint, p_action_type text DEFAULT NULL::text, p_text_search text DEFAULT NULL::text, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_role TEXT;
  v_result json;
  v_total_count BIGINT := 0;
BEGIN
  v_user_role := current_setting('request.jwt.claims', true)::json->>'app_role';
  IF v_user_role IS DISTINCT FROM 'global' THEN
    RAISE EXCEPTION 'Access denied: Only global administrators can view audit logs' USING ERRCODE = '42501';
  END IF;

  IF p_limit < 1 OR p_limit > 200 THEN p_limit := 50; END IF;
  IF p_offset < 0 THEN p_offset := 0; END IF;

  -- Derived predicate for legacy user rows
  WITH params AS (
    SELECT p_entity_type = 'user' AS want_user
  )
  SELECT COUNT(*)
  INTO v_total_count
  FROM public.audit_logs al, params
  WHERE (p_user_id IS NULL OR al.admin_user_id = p_user_id)
    AND (
      p_entity_type IS NULL
      OR al.entity_type = p_entity_type
      OR (
        params.want_user
        AND al.entity_type IS NULL
        AND (
          al.target_user_id IS NOT NULL
          OR al.action_type IN (
            'password_change','password_reset_admin','USER_UPDATE','user_create','user_delete','user_role_change','login_success','login_failed','logout'
          )
        )
      )
    )
    AND (p_entity_id IS NULL OR al.entity_id = p_entity_id)
    AND (p_action_type IS NULL OR al.action_type ILIKE '%' || p_action_type || '%')
    AND (p_text_search IS NULL OR (al.entity_label ILIKE '%' || p_text_search || '%' OR al.action_details::text ILIKE '%' || p_text_search || '%'))
    AND (p_date_from IS NULL OR al.created_at >= p_date_from)
    AND (p_date_to IS NULL OR al.created_at <= p_date_to);

  WITH params AS (
    SELECT p_entity_type = 'user' AS want_user
  )
  SELECT json_agg(json_build_object(
    'id', al.id,
    'admin_user_id', al.admin_user_id,
    'admin_username', al.admin_username,
    'action_type', al.action_type,
    'entity_type', al.entity_type,
    'entity_id', al.entity_id,
    'entity_label', al.entity_label,
    'action_details', al.action_details,
    'ip_address', al.ip_address,
    'user_agent', al.user_agent,
    'created_at', al.created_at,
    'total_count', v_total_count
  ))
  INTO v_result
  FROM (
    SELECT *
    FROM public.audit_logs al, params
    WHERE (p_user_id IS NULL OR al.admin_user_id = p_user_id)
      AND (
        p_entity_type IS NULL
        OR al.entity_type = p_entity_type
        OR (
          params.want_user
          AND al.entity_type IS NULL
          AND (
            al.target_user_id IS NOT NULL
            OR al.action_type IN (
              'password_change','password_reset_admin','USER_UPDATE','user_create','user_delete','user_role_change','login_success','login_failed','logout'
            )
          )
        )
      )
      AND (p_entity_id IS NULL OR al.entity_id = p_entity_id)
      AND (p_action_type IS NULL OR al.action_type ILIKE '%' || p_action_type || '%')
      AND (p_text_search IS NULL OR (al.entity_label ILIKE '%' || p_text_search || '%' OR al.action_details::text ILIKE '%' || p_text_search || '%'))
      AND (p_date_from IS NULL OR al.created_at >= p_date_from)
      AND (p_date_to IS NULL OR al.created_at <= p_date_to)
    ORDER BY al.created_at DESC
    LIMIT p_limit OFFSET p_offset
  ) al;

  RETURN COALESCE(v_result, json_build_array());
END;
$$;


