--
-- Name: audit_logs_test(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_logs_test() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_role TEXT;
  v_table_exists BOOLEAN;
  v_count BIGINT;
BEGIN
  -- Get user context from JWT
  BEGIN
    v_user_role := current_setting('request.jwt.claims', true)::json->>'app_role';
  EXCEPTION WHEN others THEN
    v_user_role := 'unknown';
  END;
  
  -- Check if table exists
  SELECT EXISTS(
    SELECT FROM information_schema.tables 
    WHERE table_schema = 'public' AND table_name = 'audit_logs'
  ) INTO v_table_exists;
  
  -- Count existing audit logs if table exists
  IF v_table_exists THEN
    SELECT COUNT(*) INTO v_count FROM public.audit_logs;
  ELSE
    v_count := 0;
  END IF;
  
  RETURN json_build_object(
    'user_role', v_user_role,
    'audit_logs_count', v_count,
    'table_exists', v_table_exists,
    'message', 'Test function is working via PostgREST!',
    'timestamp', NOW()
  );
END;
$$;


ALTER FUNCTION public.audit_logs_test() OWNER TO postgres;

--
-- Name: auth_audit_log_cleanup_scheduled(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auth_audit_log_cleanup_scheduled() RETURNS TABLE(deleted_count bigint, oldest_remaining timestamp with time zone, batches_executed integer, cutoff_date timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_retention_days CONSTANT integer := 90;
  c_batch_size CONSTANT integer := 1000;
  c_max_batches CONSTANT integer := 100;
  v_cutoff_date timestamptz := now() - (c_retention_days || ' days')::interval;
  v_deleted_count bigint := 0;
  v_batch_deleted bigint := 0;
  v_batches_executed integer := 0;
  v_oldest_remaining timestamptz;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('auth_audit_log_cleanup_scheduled'));

  IF v_cutoff_date > now() - interval '24 hours' THEN
    RAISE EXCEPTION 'Cannot delete auth audit logs from the last 24 hours';
  END IF;

  LOOP
    WITH to_delete AS (
      SELECT ctid
      FROM public.auth_audit_log
      WHERE created_at < v_cutoff_date
      ORDER BY created_at
      LIMIT c_batch_size
      FOR UPDATE SKIP LOCKED
    )
    DELETE FROM public.auth_audit_log
    WHERE ctid IN (SELECT ctid FROM to_delete);

    GET DIAGNOSTICS v_batch_deleted = ROW_COUNT;

    EXIT WHEN v_batch_deleted = 0;

    v_deleted_count := v_deleted_count + v_batch_deleted;
    v_batches_executed := v_batches_executed + 1;

    EXIT WHEN v_batches_executed >= c_max_batches;
  END LOOP;

  SELECT MIN(created_at)
  INTO v_oldest_remaining
  FROM public.auth_audit_log;

  RETURN QUERY
  SELECT
    v_deleted_count,
    v_oldest_remaining,
    v_batches_executed,
    v_cutoff_date;
END;
$$;


ALTER FUNCTION public.auth_audit_log_cleanup_scheduled() OWNER TO postgres;

--
-- Name: FUNCTION auth_audit_log_cleanup_scheduled(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.auth_audit_log_cleanup_scheduled() IS 'Scheduled service-role cleanup for auth_audit_log. Hard-purges rows older than 90 days in bounded batches.';


--
-- Name: auth_audit_log_insert(timestamp with time zone, text, text, text, text, text, text, text, text, text, inet, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auth_audit_log_insert(p_created_at timestamp with time zone DEFAULT now(), p_event text DEFAULT NULL::text, p_source text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text, p_signout_reason text DEFAULT NULL::text, p_user_id text DEFAULT NULL::text, p_username text DEFAULT NULL::text, p_tenant_id text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_trace_id text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  BEGIN
    INSERT INTO public.auth_audit_log (
      created_at,
      event,
      reason_code,
      signout_reason,
      user_id,
      username,
      tenant_id,
      request_id,
      trace_id,
      source,
      ip_address,
      user_agent,
      metadata
    )
    VALUES (
      COALESCE(p_created_at, now()),
      p_event,
      p_reason_code,
      p_signout_reason,
      NULLIF(BTRIM(p_user_id), ''),
      NULLIF(BTRIM(p_username), ''),
      NULLIF(BTRIM(p_tenant_id), ''),
      NULLIF(BTRIM(p_request_id), ''),
      NULLIF(BTRIM(p_trace_id), ''),
      p_source,
      p_ip_address,
      NULLIF(BTRIM(p_user_agent), ''),
      p_metadata
    );

    RETURN TRUE;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'auth_audit_log_insert failed: %', SQLERRM;
    RETURN FALSE;
  END;
END;
$$;


