--
-- Name: auth_login_throttle_check(text, inet); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auth_login_throttle_check(p_username text, p_ip_address inet) RETURNS TABLE(allowed boolean, blocked_until timestamp with time zone, retry_after_seconds integer, blocked_scope text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_username_hash text;
  v_block record;
BEGIN
  IF NULLIF(btrim(p_username), '') IS NULL OR p_ip_address IS NULL THEN
    RETURN QUERY SELECT TRUE, NULL::timestamptz, 0, NULL::text;
    RETURN;
  END IF;

  v_username_hash := public._auth_login_throttle_username_hash(p_username);

  SELECT t.bucket_type, t.blocked_until
  INTO v_block
  FROM public.auth_login_attempt_throttle AS t
  WHERE t.ip_address = p_ip_address
    AND t.blocked_until > v_now
    AND (
      (t.bucket_type = 'username_ip' AND t.username_hash = v_username_hash)
      OR (t.bucket_type = 'ip' AND t.username_hash IS NULL)
    )
  ORDER BY t.blocked_until DESC
  LIMIT 1;

  IF FOUND THEN
    RETURN QUERY SELECT
      FALSE,
      v_block.blocked_until,
      GREATEST(1, CEIL(EXTRACT(EPOCH FROM (v_block.blocked_until - v_now)))::integer),
      v_block.bucket_type;
    RETURN;
  END IF;

  RETURN QUERY SELECT TRUE, NULL::timestamptz, 0, NULL::text;
END;
$$;


ALTER FUNCTION public.auth_login_throttle_check(p_username text, p_ip_address inet) OWNER TO postgres;

--
-- Name: FUNCTION auth_login_throttle_check(p_username text, p_ip_address inet); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.auth_login_throttle_check(p_username text, p_ip_address inet) IS 'Service-role-only check for credentials login throttling. Returns allowed=false when username+IP or IP-only bucket is temporarily blocked.';


--
-- Name: auth_login_throttle_cleanup(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auth_login_throttle_cleanup() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted_count integer;
BEGIN
  DELETE FROM public.auth_login_attempt_throttle
  WHERE updated_at < now() - interval '1 day'
    AND (blocked_until IS NULL OR blocked_until < now() - interval '30 minutes');

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
  RETURN v_deleted_count;
END;
$$;


ALTER FUNCTION public.auth_login_throttle_cleanup() OWNER TO postgres;

--
-- Name: auth_login_throttle_record_failure(text, inet); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auth_login_throttle_record_failure(p_username text, p_ip_address inet) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_username_hash text;
BEGIN
  IF NULLIF(btrim(p_username), '') IS NULL OR p_ip_address IS NULL THEN
    RETURN TRUE;
  END IF;

  v_username_hash := public._auth_login_throttle_username_hash(p_username);

  PERFORM public._auth_login_throttle_record_bucket(
    'username_ip',
    v_username_hash,
    p_ip_address,
    5,
    interval '30 minutes',
    interval '30 minutes'
  );

  PERFORM public._auth_login_throttle_record_bucket(
    'ip',
    NULL,
    p_ip_address,
    20,
    interval '30 minutes',
    interval '30 minutes'
  );

  RETURN TRUE;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'auth_login_throttle_record_failure failed: %', SQLERRM;
  RETURN FALSE;
END;
$$;


ALTER FUNCTION public.auth_login_throttle_record_failure(p_username text, p_ip_address inet) OWNER TO postgres;

--
-- Name: FUNCTION auth_login_throttle_record_failure(p_username text, p_ip_address inet); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.auth_login_throttle_record_failure(p_username text, p_ip_address inet) IS 'Service-role-only recorder for failed credentials attempts. Blocks username+IP after 5 failures and IP-only after 20 failures in 30 minutes.';


--
-- Name: auth_login_throttle_record_success(text, inet); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auth_login_throttle_record_success(p_username text, p_ip_address inet) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NULLIF(btrim(p_username), '') IS NULL OR p_ip_address IS NULL THEN
    RETURN TRUE;
  END IF;

  DELETE FROM public.auth_login_attempt_throttle
  WHERE bucket_type = 'username_ip'
    AND username_hash = public._auth_login_throttle_username_hash(p_username)
    AND ip_address = p_ip_address;

  RETURN TRUE;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'auth_login_throttle_record_success failed: %', SQLERRM;
  RETURN FALSE;
END;
$$;


ALTER FUNCTION public.auth_login_throttle_record_success(p_username text, p_ip_address inet) OWNER TO postgres;

