-- Name: FUNCTION auth_login_throttle_record_success(p_username text, p_ip_address inet); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.auth_login_throttle_record_success(p_username text, p_ip_address inet) IS 'Service-role-only reset for successful credentials login. Resets username+IP bucket only.';


--
-- Name: authenticate_user_dual_mode(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authenticate_user_dual_mode(p_username text, p_password text) RETURNS TABLE(user_id bigint, username text, full_name text, role text, khoa_phong text, don_vi bigint, dia_ban_id bigint, dia_ban_ma text, is_authenticated boolean, authentication_mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_username TEXT;
  user_record RECORD;
  password_valid BOOLEAN := FALSE;
  auth_mode TEXT := 'unknown';
  v_resolved_don_vi BIGINT;
  v_resolved_region_id BIGINT;
  v_resolved_region_ma TEXT;
  v_tenant_active BOOLEAN := TRUE;
  v_region_active BOOLEAN := TRUE;
BEGIN
  v_username := lower(trim(p_username));

  SELECT
    nv.id,
    nv.username,
    nv.full_name,
    nv.role,
    nv.khoa_phong,
    nv.password,
    nv.hashed_password,
    nv.current_don_vi,
    nv.don_vi,
    nv.dia_ban_id as nhan_vien_region_id,
    COALESCE(dv_current.dia_ban_id, dv_home.dia_ban_id) AS don_vi_joined_region_id,
    COALESCE(dv_current.active, TRUE) AS current_don_vi_active,
    COALESCE(dv_home.active, TRUE) AS home_don_vi_active
  INTO user_record
  FROM public.nhan_vien nv
  LEFT JOIN public.don_vi dv_current ON dv_current.id = nv.current_don_vi
  LEFT JOIN public.don_vi dv_home ON dv_home.id = nv.don_vi
  WHERE lower(nv.username) = v_username
  LIMIT 1;

  IF user_record.id IS NULL THEN
    RETURN QUERY SELECT
      NULL::BIGINT,
      v_username,
      NULL::TEXT,
      NULL::TEXT,
      NULL::TEXT,
      NULL::BIGINT,
      NULL::BIGINT,
      NULL::TEXT,
      FALSE,
      'user_not_found'::TEXT;
    RETURN;
  END IF;

  -- Guard against obvious hashed passwords submitted as input
  IF p_password = 'hashed password'
     OR p_password ILIKE '%hash%'
     OR p_password ILIKE '%crypt%'
     OR length(p_password) > 200 THEN
    RETURN QUERY SELECT
      user_record.id,
      user_record.username,
      user_record.full_name,
      user_record.role,
      user_record.khoa_phong,
      NULL::BIGINT,
      NULL::BIGINT,
      NULL::TEXT,
      FALSE,
      'blocked_suspicious'::TEXT;
    RETURN;
  END IF;

  -- Verify password using hashed column first, then legacy plaintext fallback
  IF user_record.hashed_password IS NOT NULL AND user_record.hashed_password <> '' THEN
    password_valid := (extensions.crypt(p_password, user_record.hashed_password) = user_record.hashed_password);
    IF password_valid THEN
      auth_mode := 'hashed';
    END IF;
  END IF;

  IF NOT password_valid
     AND user_record.password IS NOT NULL
     AND user_record.password <> 'hashed password' THEN
    password_valid := (user_record.password = p_password);
    IF password_valid THEN
      auth_mode := 'plain';
    END IF;
  END IF;

  IF NOT password_valid THEN
    RETURN QUERY SELECT
      user_record.id,
      user_record.username,
      user_record.full_name,
      user_record.role,
      user_record.khoa_phong,
      NULL::BIGINT,
      NULL::BIGINT,
      NULL::TEXT,
      FALSE,
      auth_mode;
    RETURN;
  END IF;

  v_resolved_don_vi := COALESCE(user_record.current_don_vi, user_record.don_vi);
  
  -- Get tenant and region information
  IF v_resolved_don_vi IS NOT NULL THEN
    SELECT dv.active, dv.dia_ban_id
    INTO v_tenant_active, v_resolved_region_id
    FROM public.don_vi dv
    WHERE dv.id = v_resolved_don_vi
    LIMIT 1;

    IF NOT FOUND THEN
      v_tenant_active := TRUE;
      v_resolved_region_id := COALESCE(user_record.nhan_vien_region_id, user_record.don_vi_joined_region_id);
    ELSE
      v_tenant_active := COALESCE(v_tenant_active, TRUE);
      IF v_resolved_region_id IS NULL THEN
        v_resolved_region_id := COALESCE(user_record.nhan_vien_region_id, user_record.don_vi_joined_region_id);
      END IF;
    END IF;
  ELSE
    v_tenant_active := TRUE;
    v_resolved_region_id := COALESCE(user_record.nhan_vien_region_id, user_record.don_vi_joined_region_id);
  END IF;

  -- Get region metadata
  IF v_resolved_region_id IS NOT NULL THEN
    SELECT db.ma_dia_ban, db.active
    INTO v_resolved_region_ma, v_region_active
    FROM public.dia_ban db
    WHERE db.id = v_resolved_region_id
    LIMIT 1;

    IF NOT FOUND THEN
      v_resolved_region_ma := NULL;
      v_region_active := TRUE;
    ELSE
      v_region_active := COALESCE(v_region_active, TRUE);
    END IF;
  ELSE
    v_resolved_region_ma := NULL;
    v_region_active := TRUE;
  END IF;

  -- Reject access if tenant/region is inactive for scoped roles
  IF LOWER(COALESCE(user_record.role, '')) NOT IN ('global', 'admin') THEN
    IF v_resolved_don_vi IS NOT NULL AND v_tenant_active IS DISTINCT FROM TRUE THEN
      RETURN QUERY SELECT
        user_record.id,
        user_record.username,
        user_record.full_name,
        user_record.role,
        user_record.khoa_phong,
        v_resolved_don_vi,
        v_resolved_region_id,
        v_resolved_region_ma,
        FALSE,
        'tenant_inactive'::TEXT;
      RETURN;
    END IF;
  END IF;

  IF LOWER(COALESCE(user_record.role, '')) = 'regional_leader' THEN
    IF v_resolved_region_id IS NULL THEN
      RETURN QUERY SELECT
        user_record.id,
        user_record.username,
        user_record.full_name,
        user_record.role,
        user_record.khoa_phong,
        v_resolved_don_vi,
        NULL::BIGINT,
        NULL::TEXT,
        FALSE,
        'missing_dia_ban'::TEXT;
      RETURN;
    END IF;

    IF v_region_active IS DISTINCT FROM TRUE THEN
      RETURN QUERY SELECT
        user_record.id,
        user_record.username,
        user_record.full_name,
        user_record.role,
        user_record.khoa_phong,
        v_resolved_don_vi,
        v_resolved_region_id,
        v_resolved_region_ma,
        FALSE,
        'dia_ban_inactive'::TEXT;
      RETURN;
    END IF;
  END IF;

  RETURN QUERY SELECT
    user_record.id,
    user_record.username,
    user_record.full_name,
    user_record.role,
    user_record.khoa_phong,
    v_resolved_don_vi,
    v_resolved_region_id,
    v_resolved_region_ma,
    TRUE,
    auth_mode;
END;
$$;


ALTER FUNCTION public.authenticate_user_dual_mode(p_username text, p_password text) OWNER TO postgres;

--
-- Name: FUNCTION authenticate_user_dual_mode(p_username text, p_password text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.authenticate_user_dual_mode(p_username text, p_password text) IS 'Authenticates a user supporting hashed/plain passwords and returns role, don_vi, dia_ban claims. FIXED: Resolved variable-column name conflicts by renaming all variables.';


--
-- Name: change_password(integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.change_password(p_user_id integer, p_old_password text, p_new_password text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims JSONB := COALESCE(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_role TEXT := LOWER(COALESCE(NULLIF(v_claims->>'app_role', ''), NULLIF(v_claims->>'role', '')));
  v_claim_user_id INTEGER;
  v_user_agent TEXT := COALESCE(
    NULLIF((COALESCE(NULLIF(current_setting('request.headers', true), ''), '{}')::jsonb)->>'user-agent', ''),
    'unknown'
  );
  user_record RECORD;
  password_valid BOOLEAN := FALSE;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(v_claims->>'user_id', '') IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  BEGIN
    v_claim_user_id := (v_claims->>'user_id')::INTEGER;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'Invalid user_id claim' USING ERRCODE = '42501';
  END;

  IF p_user_id IS NULL OR p_user_id <> v_claim_user_id THEN
    RAISE EXCEPTION 'user_id claim mismatch' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(p_old_password, '') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Current password is incorrect');
  END IF;

  IF NULLIF(p_new_password, '') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'New password is required');
  END IF;

  SELECT id, username, password, hashed_password
  INTO user_record
  FROM public.nhan_vien
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'User not found');
  END IF;

  IF user_record.hashed_password IS NOT NULL AND user_record.hashed_password <> '' THEN
    password_valid := (extensions.crypt(p_old_password, user_record.hashed_password) = user_record.hashed_password);
  ELSE
    password_valid := (user_record.password = p_old_password);
  END IF;

  IF password_valid IS DISTINCT FROM TRUE THEN
    RETURN jsonb_build_object('success', false, 'message', 'Current password is incorrect');
  END IF;

  UPDATE public.nhan_vien
  SET hashed_password = extensions.crypt(p_new_password, extensions.gen_salt('bf', 12)),
      password = 'hashed password',
      password_changed_at = NOW()
  WHERE id = p_user_id;

  BEGIN
    INSERT INTO public.audit_logs (
      admin_user_id,
      admin_username,
      action_type,
      target_user_id,
      target_username,
      action_details,
      ip_address,
      user_agent
    ) VALUES (
      p_user_id,
      user_record.username,
      'password_change',
      p_user_id,
      user_record.username,
      'User changed password',
      COALESCE(pg_catalog.inet_client_addr(), '0.0.0.0'::INET),
      v_user_agent
    );
  EXCEPTION WHEN others THEN
    RAISE WARNING 'Failed to log password change: %', SQLERRM;
  END;

  RETURN jsonb_build_object('success', true, 'message', 'Password updated successfully');
END;
$$;


