COMMENT ON FUNCTION public.change_password(p_user_id integer, p_old_password text, p_new_password text) IS 'Allows the current authenticated session user to change only their own password with hashed storage, audit logging, and JWT claim guard.';


--
-- Name: create_user(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_user(p_username text, p_password text, p_full_name text, p_role text, p_khoa_phong text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_new_user_id INTEGER;
BEGIN
  IF NOT public.validate_username(p_username) THEN
    RAISE EXCEPTION 'Invalid username format';
  END IF;

  INSERT INTO public.nhan_vien (
    username,
    password,
    hashed_password,
    full_name,
    role,
    khoa_phong
  ) VALUES (
    p_username,
    'hashed password',
    extensions.crypt(p_password, extensions.gen_salt('bf', 12)),
    p_full_name,
    p_role,
    p_khoa_phong
  )
  RETURNING id INTO v_new_user_id;

  RETURN v_new_user_id;
END;
$$;


