--
-- Name: dashboard_equipment_total(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dashboard_equipment_total() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jwt_claims jsonb;
  v_role text;
  v_user_id text;
  v_allowed_don_vi bigint[];
  v_department_scope text;
  result integer;
BEGIN
  v_jwt_claims := COALESCE(NULLIF(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  v_role := lower(COALESCE(v_jwt_claims->>'app_role', v_jwt_claims->>'role', ''));
  v_user_id := NULLIF(COALESCE(v_jwt_claims->>'user_id', v_jwt_claims->>'sub'), '');

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  IF v_role <> 'global'
     AND (v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) IS NULL) THEN
    RETURN 0;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims->>'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN 0;
    END IF;
  END IF;

  SELECT COUNT(*)::integer INTO result
  FROM public.thiet_bi tb
  WHERE tb.is_deleted = false
    AND (
      v_role = 'global'
      OR tb.don_vi = ANY(v_allowed_don_vi)
    )
    AND (
      v_role <> 'user'
      OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
    );

  RETURN COALESCE(result, 0);
END;
$$;


ALTER FUNCTION public.dashboard_equipment_total() OWNER TO postgres;

--
-- Name: dashboard_kpi_summary(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dashboard_kpi_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_user_id text;
  v_jwt_claims jsonb;
BEGIN
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;

  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));
  v_user_id := NULLIF(v_jwt_claims ->> 'user_id', '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'totalEquipment', public.dashboard_equipment_total(),
    'maintenanceCount', public.dashboard_maintenance_count(),
    'repairRequests', public.dashboard_repair_request_stats(),
    'maintenancePlans', public.dashboard_maintenance_plan_stats()
  );
END;
$$;


