--
-- Name: dashboard_maintenance_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dashboard_maintenance_count() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jwt_claims jsonb;
  v_role text;
  v_user_id text;
  v_allowed_don_vi bigint[];
  v_department_scope text;
  result integer;
BEGIN
  v_jwt_claims := COALESCE(NULLIF(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  v_role := lower(COALESCE(v_jwt_claims->>'app_role', v_jwt_claims->>'role', ''));
  v_user_id := NULLIF(COALESCE(v_jwt_claims->>'user_id', v_jwt_claims->>'sub'), '');

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  IF v_role <> 'global'
     AND (v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) IS NULL) THEN
    RETURN 0;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims->>'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN 0;
    END IF;
  END IF;

  SELECT COUNT(*)::integer INTO result
  FROM public.thiet_bi tb
  WHERE tb.is_deleted = false
    AND (
      v_role = 'global'
      OR tb.don_vi = ANY(v_allowed_don_vi)
    )
    AND (
      v_role <> 'user'
      OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
    )
    AND (
      tb.tinh_trang_hien_tai ILIKE '%Chờ bảo trì%'
      OR tb.tinh_trang_hien_tai ILIKE '%Chờ hiệu chuẩn%'
      OR tb.tinh_trang_hien_tai ILIKE '%Chờ kiểm định%'
      OR tb.tinh_trang_hien_tai ILIKE '%bảo trì%'
      OR tb.tinh_trang_hien_tai ILIKE '%hiệu chuẩn%'
      OR tb.tinh_trang_hien_tai ILIKE '%kiểm định%'
    );

  RETURN COALESCE(result, 0);
END;
$$;


ALTER FUNCTION public.dashboard_maintenance_count() OWNER TO postgres;

--
-- Name: dashboard_maintenance_plan_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dashboard_maintenance_plan_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jwt_claims jsonb;
  v_role text;
  v_user_id text;
  v_allowed_don_vi bigint[];
  v_department_scope text;
  result jsonb;
BEGIN
  v_jwt_claims := COALESCE(NULLIF(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  v_role := lower(COALESCE(v_jwt_claims->>'app_role', v_jwt_claims->>'role', ''));
  v_user_id := NULLIF(COALESCE(v_jwt_claims->>'user_id', v_jwt_claims->>'sub'), '');

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  IF v_role <> 'global'
     AND (v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) IS NULL) THEN
    RETURN jsonb_build_object('total', 0, 'draft', 0, 'approved', 0, 'plans', '[]'::jsonb);
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims->>'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN jsonb_build_object('total', 0, 'draft', 0, 'approved', 0, 'plans', '[]'::jsonb);
    END IF;
  END IF;

  WITH tenant_filtered_plans AS (
    SELECT kh.*
    FROM public.ke_hoach_bao_tri kh
    WHERE (
        v_role = 'global'
        OR kh.don_vi = ANY(v_allowed_don_vi)
      )
      AND (
        v_role <> 'user'
        OR public._normalize_department_scope(kh.khoa_phong) = v_department_scope
      )
  ),
  plan_counts AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE trang_thai = 'Bản nháp') AS draft,
      COUNT(*) FILTER (WHERE trang_thai = 'Đã duyệt') AS approved
    FROM tenant_filtered_plans
  ),
  recent_plans AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', tfp.id,
        'ten_ke_hoach', tfp.ten_ke_hoach,
        'nam', tfp.nam,
        'khoa_phong', tfp.khoa_phong,
        'loai_cong_viec', tfp.loai_cong_viec,
        'trang_thai', tfp.trang_thai,
        'created_at', tfp.created_at
      ) ORDER BY tfp.created_at DESC
    ) AS plans
    FROM (
      SELECT *
      FROM tenant_filtered_plans
      ORDER BY created_at DESC
      LIMIT 10
    ) tfp
  )
  SELECT jsonb_build_object(
    'total', COALESCE(pc.total, 0),
    'draft', COALESCE(pc.draft, 0),
    'approved', COALESCE(pc.approved, 0),
    'plans', COALESCE(rp.plans, '[]'::jsonb)
  )
  INTO result
  FROM plan_counts pc
  CROSS JOIN recent_plans rp;

  RETURN COALESCE(result, jsonb_build_object('total', 0, 'draft', 0, 'approved', 0, 'plans', '[]'::jsonb));
END;
$$;


ALTER FUNCTION public.dashboard_maintenance_plan_stats() OWNER TO postgres;

--
-- Name: FUNCTION dashboard_maintenance_plan_stats(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dashboard_maintenance_plan_stats() IS 'Returns maintenance plan statistics with proper role-based filtering.
- Global: stats from all active tenants
- Regional Leader: stats from all tenants in assigned region
- Other roles: stats from their own tenant only';


--
-- Name: dashboard_recent_activities(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dashboard_recent_activities(p_limit integer DEFAULT 15) RETURNS TABLE(activity_id bigint, action_type text, action_label text, entity_type text, entity_label text, actor_name text, facility_name text, occurred_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role_raw    TEXT := COALESCE(
                      NULLIF(public._get_jwt_claim('app_role'), ''),
                      NULLIF(public._get_jwt_claim('role'), ''),
                      '');
  v_role        TEXT := lower(v_role_raw);
  v_user_id     TEXT := COALESCE(
                      NULLIF(public._get_jwt_claim('user_id'), ''),
                      NULLIF(public._get_jwt_claim('sub'), ''));
  v_don_vi_raw  TEXT := NULLIF(public._get_jwt_claim('don_vi'), '');
  v_don_vi      BIGINT;
  v_is_global   BOOLEAN;
  v_allowed     BIGINT[];
  v_safe_limit  INT;
BEGIN
  IF v_don_vi_raw ~ '^[0-9]+$' THEN
    v_don_vi := v_don_vi_raw::BIGINT;
  END IF;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  v_is_global := v_role IN ('global', 'admin');

  IF NOT v_is_global THEN
    IF v_role <> 'regional_leader' AND v_don_vi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
    END IF;

    v_allowed := public.allowed_don_vi_for_session_safe();

    IF array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;
  END IF;

  v_safe_limit := LEAST(GREATEST(COALESCE(p_limit, 15), 1), 50);

  RETURN QUERY
  SELECT
    al.id AS activity_id,
    al.action_type AS action_type,
    CASE al.action_type
      WHEN 'repair_request_create' THEN 'Tạo yêu cầu sửa chữa'
      WHEN 'repair_request_update' THEN 'Cập nhật yêu cầu sửa chữa'
      WHEN 'repair_request_approve' THEN 'Phê duyệt sửa chữa'
      WHEN 'repair_request_complete' THEN 'Hoàn thành sửa chữa'
      WHEN 'transfer_request_create' THEN 'Tạo yêu cầu luân chuyển'
      WHEN 'transfer_request_update' THEN 'Cập nhật yêu cầu luân chuyển'
      WHEN 'transfer_request_update_status' THEN 'Cập nhật trạng thái luân chuyển'
      WHEN 'transfer_request_complete' THEN 'Hoàn thành luân chuyển'
      WHEN 'maintenance_plan_create' THEN 'Tạo kế hoạch bảo trì'
      WHEN 'equipment_create' THEN 'Thêm thiết bị mới'
      ELSE al.action_type
    END AS action_label,
    al.entity_type AS entity_type,
    al.entity_label AS entity_label,
    COALESCE(nv.full_name, al.admin_username) AS actor_name,
    dv.name AS facility_name,
    al.created_at AS occurred_at
  FROM public.audit_logs al
  LEFT JOIN public.nhan_vien nv
    ON nv.id = al.admin_user_id
  LEFT JOIN public.don_vi dv
    ON dv.id = CASE
      WHEN NULLIF(al.tenant_don_vi, '') ~ '^[0-9]+$'
        THEN NULLIF(al.tenant_don_vi, '')::BIGINT
      ELSE NULL
    END
  WHERE al.action_type IN (
    'repair_request_create',
    'repair_request_update',
    'repair_request_approve',
    'repair_request_complete',
    'transfer_request_create',
    'transfer_request_update',
    'transfer_request_update_status',
    'transfer_request_complete',
    'maintenance_plan_create',
    'equipment_create'
  )
    AND al.created_at >= NOW() - INTERVAL '30 days'
    AND (
      v_is_global
      OR CASE
        WHEN NULLIF(al.tenant_don_vi, '') ~ '^[0-9]+$'
          THEN NULLIF(al.tenant_don_vi, '')::BIGINT = ANY(v_allowed)
        ELSE FALSE
      END
    )
  ORDER BY al.created_at DESC
  LIMIT v_safe_limit;
END;
$_$;


