--
-- Name: FUNCTION dashboard_recent_activities(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dashboard_recent_activities(p_limit integer) IS 'Returns recent notable activities from audit_logs for the dashboard feed widget. Tenant-isolated via JWT claims and allowed_don_vi_for_session_safe(). Empty-string role and user_id claims fall back to role/sub respectively. Invalid or non-numeric tenant_don_vi audit rows stay visible only to global users. Supports global, single-tenant, and regional_leader (multi-tenant via dia_ban) roles.';


--
-- Name: dashboard_repair_request_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dashboard_repair_request_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jwt_claims jsonb;
  v_role text;
  v_user_id text;
  v_allowed_don_vi bigint[];
  v_department_scope text;
  result jsonb;
BEGIN
  v_jwt_claims := COALESCE(NULLIF(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  v_role := lower(COALESCE(v_jwt_claims->>'app_role', v_jwt_claims->>'role', ''));
  v_user_id := NULLIF(COALESCE(v_jwt_claims->>'user_id', v_jwt_claims->>'sub'), '');

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  IF v_role <> 'global'
     AND (v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) IS NULL) THEN
    RETURN jsonb_build_object('total', 0, 'pending', 0, 'approved', 0, 'completed', 0);
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims->>'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN jsonb_build_object('total', 0, 'pending', 0, 'approved', 0, 'completed', 0);
    END IF;
  END IF;

  WITH repair_counts AS (
    SELECT
      COUNT(*) FILTER (WHERE yc.trang_thai = 'Chờ xử lý') AS pending,
      COUNT(*) FILTER (WHERE yc.trang_thai = 'Đã duyệt') AS approved,
      COUNT(*) FILTER (WHERE yc.trang_thai IN ('Hoàn thành', 'Không HT')) AS completed
    FROM public.yeu_cau_sua_chua yc
    INNER JOIN public.thiet_bi tb ON tb.id = yc.thiet_bi_id
    WHERE tb.is_deleted = false
      AND (
        v_role = 'global'
        OR tb.don_vi = ANY(v_allowed_don_vi)
      )
      AND (
        v_role <> 'user'
        OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
      )
  )
  SELECT jsonb_build_object(
    'total', COALESCE(rc.pending + rc.approved, 0),
    'pending', COALESCE(rc.pending, 0),
    'approved', COALESCE(rc.approved, 0),
    'completed', COALESCE(rc.completed, 0)
  )
  INTO result
  FROM repair_counts rc;

  RETURN COALESCE(result, jsonb_build_object('total', 0, 'pending', 0, 'approved', 0, 'completed', 0));
END;
$$;


ALTER FUNCTION public.dashboard_repair_request_stats() OWNER TO postgres;

--
-- Name: debug_jwt_claims(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.debug_jwt_claims() RETURNS TABLE(claim_name text, claim_value text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_jwt_claims JSONB;
BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
    
    -- Return all claims as key-value pairs
    RETURN QUERY
    SELECT 
        key::TEXT as claim_name,
        value::TEXT as claim_value
    FROM jsonb_each_text(v_jwt_claims);
END;
$$;


