--
-- Name: departments_list(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.departments_list() RETURNS TABLE(name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := '';
  v_claim_donvi BIGINT := NULL;
  v_effective_donvi BIGINT := NULL;
BEGIN
  v_role := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_claim_donvi := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;

  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := NULL;
  ELSE
    v_effective_donvi := v_claim_donvi;
  END IF;

  RETURN QUERY
  SELECT DISTINCT coalesce(tb.khoa_phong_quan_ly, '') as name
  FROM public.thiet_bi tb
  WHERE coalesce(tb.khoa_phong_quan_ly, '') <> ''
    AND tb.is_deleted = false
    AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)
  ORDER BY 1;
END;
$$;


ALTER FUNCTION public.departments_list() OWNER TO postgres;

--
-- Name: departments_list_for_facilities(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.departments_list_for_facilities(p_don_vi_array bigint[] DEFAULT NULL::bigint[]) RETURNS TABLE(name text, count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_allowed bigint[];
  v_facilities_to_query bigint[];
  v_single_don_vi bigint;
BEGIN
  v_role := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role IN ('global', 'admin') THEN
    IF p_don_vi_array IS NULL OR array_length(p_don_vi_array, 1) IS NULL THEN
      v_facilities_to_query := NULL;
    ELSE
      v_facilities_to_query := p_don_vi_array;
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi_array IS NULL OR array_length(p_don_vi_array, 1) IS NULL THEN
      v_facilities_to_query := v_allowed;
    ELSE
      SELECT ARRAY_AGG(fid)
      INTO v_facilities_to_query
      FROM UNNEST(p_don_vi_array) AS fid
      WHERE fid = ANY(v_allowed);

      IF v_facilities_to_query IS NULL OR array_length(v_facilities_to_query, 1) IS NULL THEN
        RAISE EXCEPTION 'Access denied to requested facilities' USING ERRCODE = '42501';
      END IF;
    END IF;
  ELSE
    v_single_don_vi := NULLIF(public._get_jwt_claim('don_vi'), '')::bigint;
    IF v_single_don_vi IS NULL THEN
      RETURN;
    END IF;
    v_facilities_to_query := ARRAY[v_single_don_vi];
  END IF;

  RETURN QUERY
  SELECT
    tb.khoa_phong_quan_ly AS name,
    COUNT(*) AS count
  FROM public.thiet_bi tb
  WHERE tb.is_deleted = false
    AND (v_facilities_to_query IS NULL OR tb.don_vi = ANY(v_facilities_to_query))
    AND tb.khoa_phong_quan_ly IS NOT NULL
    AND tb.khoa_phong_quan_ly != ''
  GROUP BY tb.khoa_phong_quan_ly
  ORDER BY tb.khoa_phong_quan_ly;
END;
$$;


ALTER FUNCTION public.departments_list_for_facilities(p_don_vi_array bigint[]) OWNER TO postgres;

--
-- Name: FUNCTION departments_list_for_facilities(p_don_vi_array bigint[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.departments_list_for_facilities(p_don_vi_array bigint[]) IS 'Returns list of departments across multiple facilities with equipment counts.
Authorization follows same pattern as equipment_aggregates_for_reports.

Parameters:
- p_don_vi_array: Array of facility IDs (NULL = all allowed)

Returns TABLE:
- name: Department name
- count: Number of equipment in that department

Security:
- SECURITY DEFINER with search_path = public, pg_temp
- Validates access via allowed_don_vi_for_session_safe()';


--
-- Name: departments_list_for_tenant(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.departments_list_for_tenant(p_don_vi bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_user_id TEXT;
  v_allowed BIGINT[];
  v_effective BIGINT[];
  v_department_scope TEXT;
  v_jwt_claims JSONB;
BEGIN
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;

  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));
  v_user_id := NULLIF(v_jwt_claims ->> 'user_id', '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role = 'global' THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF v_allowed IS NULL OR NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims ->> 'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN;
    END IF;
  END IF;

  RETURN QUERY
  SELECT jsonb_build_object(
    'name', COALESCE(NULLIF(TRIM(khoa_phong_quan_ly), ''), 'Chưa phân loại'),
    'count', COUNT(*)::INTEGER
  )
  FROM public.thiet_bi tb
  WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
    AND tb.is_deleted = false
    AND (v_role <> 'user' OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope)
  GROUP BY COALESCE(NULLIF(TRIM(khoa_phong_quan_ly), ''), 'Chưa phân loại')
  ORDER BY COUNT(*) DESC;
END;
$$;


ALTER FUNCTION public.departments_list_for_tenant(p_don_vi bigint) OWNER TO postgres;

