--
-- Name: device_quota_suggestion_job_store_rpc(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.device_quota_suggestion_job_store_rpc(p_action text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims JSONB := NULLIF(current_setting('request.jwt.claims', true), '')::jsonb;
  v_role TEXT := '';
  v_user_id TEXT := NULL;
  v_scope_key TEXT := NULL;
  v_is_service_role BOOLEAN := FALSE;
  v_allowed_don_vi BIGINT[] := NULL;
  v_job JSONB := '{}'::jsonb;
  v_chunks JSONB := '[]'::jsonb;
  v_job_id UUID := NULL;
  v_chunk_id UUID := NULL;
  v_don_vi_id BIGINT := NULL;
  v_row public.device_quota_suggestion_jobs%ROWTYPE;
  v_chunk public.device_quota_suggestion_job_chunks%ROWTYPE;
  v_rows JSONB := '[]'::jsonb;
BEGIN
  IF p_action IS NULL OR btrim(p_action) = '' THEN
    RAISE EXCEPTION 'Missing action' USING ERRCODE = '22023';
  END IF;

  IF v_claims IS NULL THEN
    RAISE EXCEPTION 'Missing JWT claims' USING ERRCODE = '42501';
  END IF;

  v_role := lower(COALESCE(v_claims->>'app_role', v_claims->>'role', ''));
  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_service_role := v_role = 'service_role';

  IF v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF NOT v_is_service_role THEN
    v_user_id := NULLIF(COALESCE(v_claims->>'user_id', v_claims->>'sub'), '');
    IF v_user_id IS NULL THEN
      RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
    END IF;
    v_scope_key := 'user:' || v_user_id;
    v_allowed_don_vi := public.allowed_don_vi_for_session();
  END IF;

  IF p_action = 'create_job' THEN
    v_job := COALESCE(p_payload->'job', '{}'::jsonb);
    v_chunks := COALESCE(p_payload->'chunks', '[]'::jsonb);
    v_don_vi_id := NULLIF(v_job->>'don_vi_id', '')::bigint;

    IF NOT v_is_service_role THEN
      IF v_job->>'scope_key' IS DISTINCT FROM v_scope_key THEN
        RAISE EXCEPTION 'scope_key claim mismatch' USING ERRCODE = '42501';
      END IF;
      IF v_don_vi_id IS NULL OR NOT (v_don_vi_id = ANY(v_allowed_don_vi)) THEN
        RAISE EXCEPTION 'Facility scope denied' USING ERRCODE = '42501';
      END IF;
    END IF;

    INSERT INTO public.device_quota_suggestion_jobs (
      catalog_signature,
      category_snapshot,
      data_signature,
      don_vi_id,
      error,
      item_counts,
      processed_unique_names,
      provider,
      result,
      scope_key,
      status,
      total_unique_names
    )
    VALUES (
      v_job->>'catalog_signature',
      COALESCE(v_job->'category_snapshot', '[]'::jsonb),
      v_job->>'data_signature',
      v_don_vi_id,
      v_job->>'error',
      COALESCE(v_job->'item_counts', '{}'::jsonb),
      COALESCE(NULLIF(v_job->>'processed_unique_names', '')::integer, 0),
      COALESCE(v_job->>'provider', 'vm'),
      v_job->'result',
      v_job->>'scope_key',
      COALESCE(v_job->>'status', 'queued'),
      COALESCE(NULLIF(v_job->>'total_unique_names', '')::integer, 0)
    )
    RETURNING * INTO v_row;

    INSERT INTO public.device_quota_suggestion_job_chunks (
      chunk_index,
      device_name_count,
      device_names,
      job_id,
      status,
      unique_name_count
    )
    SELECT
      chunk_index,
      device_name_count,
      COALESCE(device_names, '[]'::jsonb),
      v_row.id,
      'queued',
      unique_name_count
    FROM jsonb_to_recordset(v_chunks) AS chunk_rows(
      chunk_index INTEGER,
      device_name_count INTEGER,
      device_names JSONB,
      unique_name_count INTEGER
    );

    RETURN to_jsonb(v_row);
  END IF;

  IF p_action = 'find_active_job' THEN
    v_don_vi_id := NULLIF(p_payload->>'don_vi_id', '')::bigint;
    IF NOT v_is_service_role THEN
      IF p_payload->>'scope_key' IS DISTINCT FROM v_scope_key THEN
        RAISE EXCEPTION 'scope_key claim mismatch' USING ERRCODE = '42501';
      END IF;
      IF v_don_vi_id IS NULL OR NOT (v_don_vi_id = ANY(v_allowed_don_vi)) THEN
        RAISE EXCEPTION 'Facility scope denied' USING ERRCODE = '42501';
      END IF;
    END IF;

    SELECT *
    INTO v_row
    FROM public.device_quota_suggestion_jobs
    WHERE don_vi_id = v_don_vi_id
      AND scope_key = p_payload->>'scope_key'
      AND data_signature = p_payload->>'data_signature'
      AND status IN ('queued', 'processing', 'succeeded')
    ORDER BY created_at DESC
    LIMIT 1;

    RETURN CASE WHEN v_row.id IS NULL THEN NULL ELSE to_jsonb(v_row) END;
  END IF;

  IF p_action = 'get_job' THEN
    v_job_id := NULLIF(p_payload->>'job_id', '')::uuid;
    SELECT * INTO v_row
    FROM public.device_quota_suggestion_jobs
    WHERE id = v_job_id;

    IF v_row.id IS NULL THEN
      RETURN NULL;
    END IF;
    IF NOT v_is_service_role AND v_row.scope_key IS DISTINCT FROM v_scope_key THEN
      RETURN NULL;
    END IF;
    RETURN to_jsonb(v_row);
  END IF;

  IF p_action = 'get_chunk' THEN
    v_chunk_id := NULLIF(p_payload->>'chunk_id', '')::uuid;
    SELECT c.*
    INTO v_chunk
    FROM public.device_quota_suggestion_job_chunks c
    JOIN public.device_quota_suggestion_jobs j ON j.id = c.job_id
    WHERE c.id = v_chunk_id
      AND (v_is_service_role OR j.scope_key = v_scope_key);

    RETURN CASE WHEN v_chunk.id IS NULL THEN NULL ELSE to_jsonb(v_chunk) END;
  END IF;

  IF p_action = 'get_job_chunks' THEN
    v_job_id := NULLIF(p_payload->>'job_id', '')::uuid;
    SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.chunk_index), '[]'::jsonb)
    INTO v_rows
    FROM public.device_quota_suggestion_job_chunks c
    JOIN public.device_quota_suggestion_jobs j ON j.id = c.job_id
    WHERE c.job_id = v_job_id
      AND (v_is_service_role OR j.scope_key = v_scope_key);

    RETURN v_rows;
  END IF;

  IF p_action = 'list_queued_chunks' THEN
    IF NOT v_is_service_role THEN
      RAISE EXCEPTION 'Worker action requires service role' USING ERRCODE = '42501';
    END IF;

    SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.created_at, c.id), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT *
      FROM public.device_quota_suggestion_job_chunks
      WHERE status = 'queued'
      ORDER BY created_at, id
      LIMIT GREATEST(1, LEAST(COALESCE(NULLIF(p_payload->>'limit', '')::integer, 1), 25))
    ) c;

    RETURN v_rows;
  END IF;

  IF p_action = 'mark_chunk_processing' THEN
    v_chunk_id := NULLIF(p_payload->>'chunk_id', '')::uuid;
    UPDATE public.device_quota_suggestion_job_chunks
    SET attempts = attempts + 1,
        status = 'processing',
        error = NULL
    WHERE id = v_chunk_id
      AND status = 'queued'
    RETURNING * INTO v_chunk;

    RETURN jsonb_build_object('claimed', v_chunk.id IS NOT NULL);
  END IF;

  IF p_action = 'mark_chunk_failed' THEN
    v_chunk_id := NULLIF(p_payload->>'chunk_id', '')::uuid;
    UPDATE public.device_quota_suggestion_job_chunks
    SET error = p_payload->>'error',
        status = 'failed'
    WHERE id = v_chunk_id;
    RETURN jsonb_build_object('ok', true);
  END IF;

  IF p_action = 'mark_chunk_succeeded' THEN
    v_chunk_id := NULLIF(p_payload->>'chunk_id', '')::uuid;
    UPDATE public.device_quota_suggestion_job_chunks
    SET error = NULL,
        result = p_payload->'result',
        status = 'succeeded'
    WHERE id = v_chunk_id;
    RETURN jsonb_build_object('ok', true);
  END IF;

  v_job_id := NULLIF(p_payload->>'job_id', '')::uuid;

  IF NOT v_is_service_role AND p_action IN (
    'mark_job_failed',
    'mark_job_processing',
    'mark_job_succeeded',
    'reset_failed_chunks',
    'update_job_progress'
  ) THEN
    PERFORM 1
    FROM public.device_quota_suggestion_jobs
    WHERE id = v_job_id
      AND scope_key = v_scope_key;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Suggestion job not found' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF p_action = 'mark_job_failed' THEN
    UPDATE public.device_quota_suggestion_jobs
    SET error = p_payload->>'error',
        status = 'failed'
    WHERE id = v_job_id;
    RETURN jsonb_build_object('ok', true);
  END IF;

  IF p_action = 'mark_job_processing' THEN
    UPDATE public.device_quota_suggestion_jobs
    SET error = NULL,
        status = 'processing'
    WHERE id = v_job_id;
    RETURN jsonb_build_object('ok', true);
  END IF;

  IF p_action = 'mark_job_succeeded' THEN
    UPDATE public.device_quota_suggestion_jobs
    SET error = NULL,
        result = p_payload->'result',
        status = 'succeeded'
    WHERE id = v_job_id;
    RETURN jsonb_build_object('ok', true);
  END IF;

  IF p_action = 'reset_failed_chunks' THEN
    UPDATE public.device_quota_suggestion_job_chunks
    SET error = NULL,
        status = 'queued'
    WHERE job_id = v_job_id
      AND status = 'failed';
    RETURN jsonb_build_object('ok', true);
  END IF;

  IF p_action = 'update_job_progress' THEN
    UPDATE public.device_quota_suggestion_jobs
    SET processed_unique_names = COALESCE(
      NULLIF(p_payload->>'processed_unique_names', '')::integer,
      processed_unique_names
    )
    WHERE id = v_job_id;
    RETURN jsonb_build_object('ok', true);
  END IF;

  RAISE EXCEPTION 'Unknown suggestion job store action: %', p_action USING ERRCODE = '22023';
END;
$$;


ALTER FUNCTION public.device_quota_suggestion_job_store_rpc(p_action text, p_payload jsonb) OWNER TO postgres;

--
-- Name: FUNCTION device_quota_suggestion_job_store_rpc(p_action text, p_payload jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.device_quota_suggestion_job_store_rpc(p_action text, p_payload jsonb) IS 'Service-role-only RPC persistence boundary for async Device Quota suggestion jobs. Client/user access remains through Next.js job APIs, which validate session access before invoking this function. Rollback by adding a later migration that restores the previous grant contract if needed.';


--
-- Name: dinh_muc_chi_tiet_bulk_import(bigint, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_chi_tiet_bulk_import(p_quyet_dinh_id bigint, p_items jsonb, p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_effective_donvi BIGINT := NULL;
  v_decision_record RECORD;
  v_len INT;
  v_idx INT := 0;
  v_inserted INT := 0;
  v_updated INT := 0;
  v_failed INT := 0;
  v_details JSONB := '[]'::jsonb;
  v_item JSONB;
  v_ma_nhom TEXT;
  v_so_luong_dinh_muc INT;
  v_so_luong_toi_thieu INT;
  v_ghi_chu TEXT;
  v_nhom_thiet_bi_id BIGINT;
  v_existing_id BIGINT;
  v_upsert_result JSONB;
  v_err TEXT;
  v_operation TEXT;
BEGIN
  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi;
  ELSE
    IF v_claim_donvi IS NULL THEN
      RAISE EXCEPTION 'Access denied: tenant claim (don_vi) is required for non-global users';
    END IF;
    v_effective_donvi := v_claim_donvi;
  END IF;

  IF p_quyet_dinh_id IS NULL THEN
    RAISE EXCEPTION 'Decision ID (p_quyet_dinh_id) is required';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'p_items must be a JSON array';
  END IF;

  v_len := jsonb_array_length(p_items);
  IF v_len = 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'inserted', 0,
      'updated', 0,
      'failed', 0,
      'total', 0,
      'details', '[]'::jsonb
    );
  END IF;

  SELECT id, don_vi_id, trang_thai, so_quyet_dinh
  INTO v_decision_record
  FROM public.quyet_dinh_dinh_muc
  WHERE id = p_quyet_dinh_id;

  IF v_decision_record IS NULL THEN
    RAISE EXCEPTION 'Quota decision not found (id=%)', p_quyet_dinh_id;
  END IF;

  IF v_effective_donvi IS NOT NULL AND v_decision_record.don_vi_id != v_effective_donvi THEN
    RAISE EXCEPTION 'Access denied: decision belongs to different tenant';
  END IF;

  -- FIX: Allow both draft and active (was: != 'draft')
  IF v_decision_record.trang_thai NOT IN ('draft', 'active') THEN
    RAISE EXCEPTION 'Cannot import line items to inactive decisions. Decision status: %',
      v_decision_record.trang_thai;
  END IF;

  FOR v_idx IN 0 .. v_len - 1 LOOP
    v_item := p_items->v_idx;
    v_ma_nhom := v_item->>'ma_nhom';

    BEGIN
      v_so_luong_dinh_muc := NULLIF(v_item->>'so_luong_dinh_muc', '')::INT;
      v_so_luong_toi_thieu := NULLIF(v_item->>'so_luong_toi_thieu', '')::INT;
      v_ghi_chu := NULLIF(v_item->>'ghi_chu', '');

      IF v_ma_nhom IS NULL OR v_ma_nhom = '' THEN
        RAISE EXCEPTION 'Category code (ma_nhom) is required';
      END IF;

      IF v_so_luong_dinh_muc IS NULL THEN
        RAISE EXCEPTION 'Quota quantity (so_luong_dinh_muc) is required';
      END IF;

      IF v_so_luong_dinh_muc <= 0 THEN
        RAISE EXCEPTION 'Quota quantity must be greater than 0 (got: %)', v_so_luong_dinh_muc;
      END IF;

      IF v_so_luong_toi_thieu IS NOT NULL THEN
        IF v_so_luong_toi_thieu < 0 THEN
          RAISE EXCEPTION 'Minimum quantity cannot be negative (got: %)', v_so_luong_toi_thieu;
        END IF;
        IF v_so_luong_toi_thieu > v_so_luong_dinh_muc THEN
          RAISE EXCEPTION 'Minimum quantity (%) cannot exceed quota quantity (%)',
            v_so_luong_toi_thieu, v_so_luong_dinh_muc;
        END IF;
      END IF;

      SELECT id INTO v_nhom_thiet_bi_id
      FROM public.nhom_thiet_bi
      WHERE ma_nhom = v_ma_nhom
        AND don_vi_id = v_decision_record.don_vi_id;

      IF v_nhom_thiet_bi_id IS NULL THEN
        RAISE EXCEPTION 'Category not found: % (for this facility)', v_ma_nhom;
      END IF;

      IF EXISTS (
        SELECT 1 FROM public.nhom_thiet_bi
        WHERE parent_id = v_nhom_thiet_bi_id
      ) THEN
        RAISE EXCEPTION 'Category % is a parent category. Only leaf categories (no children) can have quotas.', v_ma_nhom;
      END IF;

      SELECT id INTO v_existing_id
      FROM public.chi_tiet_dinh_muc
      WHERE quyet_dinh_id = p_quyet_dinh_id
        AND nhom_thiet_bi_id = v_nhom_thiet_bi_id;

      v_upsert_result := public.dinh_muc_chi_tiet_upsert(
        p_id := v_existing_id,
        p_quyet_dinh_id := p_quyet_dinh_id,
        p_nhom_thiet_bi_id := v_nhom_thiet_bi_id,
        p_so_luong_toi_da := v_so_luong_dinh_muc,
        p_so_luong_toi_thieu := COALESCE(v_so_luong_toi_thieu, 0),
        p_ghi_chu := v_ghi_chu,
        p_don_vi := v_effective_donvi
      );

      v_operation := v_upsert_result->>'operation';
      IF v_operation = 'created' THEN
        v_inserted := v_inserted + 1;
      ELSE
        v_updated := v_updated + 1;
      END IF;

      v_details := v_details || jsonb_build_array(jsonb_build_object(
        'index', v_idx,
        'success', true,
        'operation', v_operation,
        'ma_nhom', v_ma_nhom,
        'id', v_upsert_result->'id'
      ));

    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
      v_details := v_details || jsonb_build_array(jsonb_build_object(
        'index', v_idx,
        'success', false,
        'error', COALESCE(v_err, SQLERRM),
        'ma_nhom', v_ma_nhom
      ));
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', v_failed = 0,
    'inserted', v_inserted,
    'updated', v_updated,
    'failed', v_failed,
    'total', v_len,
    'details', v_details
  );
END;
$$;


ALTER FUNCTION public.dinh_muc_chi_tiet_bulk_import(p_quyet_dinh_id bigint, p_items jsonb, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_chi_tiet_bulk_import(p_quyet_dinh_id bigint, p_items jsonb, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_chi_tiet_bulk_import(p_quyet_dinh_id bigint, p_items jsonb, p_don_vi bigint) IS 'Bulk import quota line items from Excel for a decision.
Input: p_items = [{ma_nhom, so_luong_dinh_muc, so_luong_toi_thieu?, ghi_chu?}]
Validates:
  - Decision exists, belongs to tenant, and is in draft or active status
  - Each ma_nhom exists in nhom_thiet_bi for the same facility
  - Each ma_nhom must be a LEAF category (no children)
  - so_luong_dinh_muc > 0 (required)
  - so_luong_toi_thieu <= so_luong_dinh_muc (if provided)
Returns:
  {success, inserted, updated, failed, total, details: [{index, success, operation?, error?, ma_nhom}]}
Roles: global, admin, to_qltb only.
Uses: dinh_muc_chi_tiet_upsert for each item (inherits validation and audit logging).';


--
-- Name: dinh_muc_chi_tiet_delete(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_chi_tiet_delete(p_id bigint, p_don_vi bigint DEFAULT NULL::bigint, p_ly_do text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := public._get_jwt_user_id();
  v_effective_donvi BIGINT := NULL;
  v_existing RECORD;
  v_category_info RECORD;
BEGIN
  -- Permission check: only global, admin, to_qltb can delete
  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role';
  END IF;

  -- Input validation
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'Line item ID (p_id) is required';
  END IF;

  -- Tenant isolation
  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi;
  ELSE
    v_effective_donvi := v_claim_donvi;
  END IF;

  -- Get existing line item with decision info
  SELECT ct.*, qd.don_vi_id as decision_donvi, qd.trang_thai as decision_status,
         qd.so_quyet_dinh
  INTO v_existing
  FROM public.chi_tiet_dinh_muc ct
  JOIN public.quyet_dinh_dinh_muc qd ON qd.id = ct.quyet_dinh_id
  WHERE ct.id = p_id;

  IF v_existing IS NULL THEN
    RAISE EXCEPTION 'Line item not found (id=%)', p_id;
  END IF;

  -- Verify tenant access
  IF v_effective_donvi IS NOT NULL AND v_existing.decision_donvi != v_effective_donvi THEN
    RAISE EXCEPTION 'Access denied: line item belongs to different tenant';
  END IF;

  -- Verify decision is in draft status
  IF v_existing.decision_status != 'draft' THEN
    RAISE EXCEPTION 'Cannot delete line items from non-draft decisions. Decision status: %',
      v_existing.decision_status;
  END IF;

  -- Get category info for better audit log
  SELECT ma_nhom, ten_nhom INTO v_category_info
  FROM public.nhom_thiet_bi WHERE id = v_existing.nhom_thiet_bi_id;

  -- Write audit log BEFORE deletion (since chi_tiet_id will be SET NULL on delete)
  INSERT INTO public.lich_su_dinh_muc (
    chi_tiet_id,
    quyet_dinh_id,
    don_vi_id,
    thao_tac,
    snapshot_truoc,
    ly_do,
    thuc_hien_boi
  ) VALUES (
    p_id,
    v_existing.quyet_dinh_id,
    v_existing.decision_donvi,
    'huy',
    jsonb_build_object(
      'id', v_existing.id,
      'quyet_dinh_id', v_existing.quyet_dinh_id,
      'nhom_thiet_bi_id', v_existing.nhom_thiet_bi_id,
      'ma_nhom', v_category_info.ma_nhom,
      'ten_nhom', v_category_info.ten_nhom,
      'so_luong_toi_da', v_existing.so_luong_toi_da,
      'so_luong_toi_thieu', v_existing.so_luong_toi_thieu,
      'ghi_chu', v_existing.ghi_chu
    ),
    COALESCE(p_ly_do, 'Line item deleted'),
    v_user_id
  );

  -- Delete the line item
  DELETE FROM public.chi_tiet_dinh_muc WHERE id = p_id;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_id', p_id,
    'quyet_dinh_id', v_existing.quyet_dinh_id,
    'nhom_thiet_bi_id', v_existing.nhom_thiet_bi_id,
    'ma_nhom', v_category_info.ma_nhom,
    'ten_nhom', v_category_info.ten_nhom
  );
END;
$$;


ALTER FUNCTION public.dinh_muc_chi_tiet_delete(p_id bigint, p_don_vi bigint, p_ly_do text) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_chi_tiet_delete(p_id bigint, p_don_vi bigint, p_ly_do text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_chi_tiet_delete(p_id bigint, p_don_vi bigint, p_ly_do text) IS 'Delete a quota line item from a draft decision.
Validates: decision is in draft status
Returns: {success, deleted_id, quyet_dinh_id, nhom_thiet_bi_id, ma_nhom, ten_nhom}
Roles: global, admin, to_qltb only.
Audit: Creates lich_su_dinh_muc record with thao_tac=huy before deletion.';


--
-- Name: dinh_muc_chi_tiet_list(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_chi_tiet_list(p_quyet_dinh_id bigint, p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_effective_donvi BIGINT := NULL;
  v_decision_donvi BIGINT;
  v_data JSONB := '[]'::jsonb;
BEGIN
  -- Input validation
  IF p_quyet_dinh_id IS NULL THEN
    RAISE EXCEPTION 'Decision ID (p_quyet_dinh_id) is required';
  END IF;

  -- Tenant isolation: global/admin can specify, others forced to their tenant
  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi; -- NULL means all tenants for global
  ELSE
    v_effective_donvi := v_claim_donvi; -- Always their own tenant
  END IF;

  -- Verify decision exists and get its tenant
  SELECT don_vi_id INTO v_decision_donvi
  FROM public.quyet_dinh_dinh_muc
  WHERE id = p_quyet_dinh_id;

  IF v_decision_donvi IS NULL THEN
    RAISE EXCEPTION 'Quota decision not found (id=%)', p_quyet_dinh_id;
  END IF;

  -- Verify tenant access
  IF v_effective_donvi IS NOT NULL AND v_decision_donvi != v_effective_donvi THEN
    RAISE EXCEPTION 'Access denied: decision belongs to different tenant';
  END IF;

  -- Get line items with category details and current equipment count
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', ct.id,
      'quyet_dinh_id', ct.quyet_dinh_id,
      'nhom_thiet_bi_id', ct.nhom_thiet_bi_id,
      'so_luong_dinh_muc', ct.so_luong_toi_da,  -- Alias for frontend compatibility
      'so_luong_toi_thieu', ct.so_luong_toi_thieu,
      'ghi_chu', ct.ghi_chu,
      'created_at', ct.created_at,
      'updated_at', ct.updated_at,
      -- Category info
      'ma_nhom', nt.ma_nhom,
      'ten_nhom', nt.ten_nhom,
      'phan_loai', nt.phan_loai,
      'don_vi_tinh', nt.don_vi_tinh,
      -- Current equipment count in this category for this tenant
      'so_luong_hien_co', (
        SELECT count(*)
        FROM public.thiet_bi tb
        WHERE tb.nhom_thiet_bi_id = ct.nhom_thiet_bi_id
          AND tb.don_vi = v_decision_donvi
      )
    ) ORDER BY nt.thu_tu_hien_thi, nt.ma_nhom
  ), '[]'::jsonb) INTO v_data
  FROM public.chi_tiet_dinh_muc ct
  JOIN public.nhom_thiet_bi nt ON nt.id = ct.nhom_thiet_bi_id
  WHERE ct.quyet_dinh_id = p_quyet_dinh_id;

  RETURN jsonb_build_object(
    'data', v_data,
    'quyet_dinh_id', p_quyet_dinh_id,
    'total', jsonb_array_length(v_data)
  );
END;
$$;


ALTER FUNCTION public.dinh_muc_chi_tiet_list(p_quyet_dinh_id bigint, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_chi_tiet_list(p_quyet_dinh_id bigint, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_chi_tiet_list(p_quyet_dinh_id bigint, p_don_vi bigint) IS 'Lists quota line items for a decision with category details and current equipment counts.
Returns: {data: [...], quyet_dinh_id, total}
Each item includes: id, quyet_dinh_id, nhom_thiet_bi_id, so_luong_dinh_muc, so_luong_toi_thieu,
  ghi_chu, ma_nhom, ten_nhom, phan_loai, don_vi_tinh, so_luong_hien_co
Tenant isolation: global/admin can specify tenant, others see only their tenant decisions.';


--
-- Name: dinh_muc_chi_tiet_upsert(bigint, bigint, bigint, integer, integer, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_chi_tiet_upsert(p_id bigint DEFAULT NULL::bigint, p_quyet_dinh_id bigint DEFAULT NULL::bigint, p_nhom_thiet_bi_id bigint DEFAULT NULL::bigint, p_so_luong_toi_da integer DEFAULT NULL::integer, p_so_luong_toi_thieu integer DEFAULT NULL::integer, p_ghi_chu text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := public._get_jwt_user_id();
  v_effective_donvi BIGINT := NULL;
  v_decision_record RECORD;
  v_category_donvi BIGINT;
  v_existing RECORD;
  v_new_id BIGINT;
  v_snapshot_truoc JSONB := NULL;
  v_snapshot_sau JSONB;
  v_thao_tac TEXT;
BEGIN
  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi;
  ELSE
    v_effective_donvi := v_claim_donvi;
  END IF;

  IF p_id IS NULL THEN
    IF p_quyet_dinh_id IS NULL THEN
      RAISE EXCEPTION 'Decision ID (p_quyet_dinh_id) is required for new line items';
    END IF;
    IF p_nhom_thiet_bi_id IS NULL THEN
      RAISE EXCEPTION 'Category ID (p_nhom_thiet_bi_id) is required for new line items';
    END IF;
    IF p_so_luong_toi_da IS NULL THEN
      RAISE EXCEPTION 'Maximum quantity (p_so_luong_toi_da) is required for new line items';
    END IF;
  END IF;

  IF p_so_luong_toi_da IS NOT NULL AND p_so_luong_toi_da < 0 THEN
    RAISE EXCEPTION 'Maximum quantity must be non-negative';
  END IF;
  IF p_so_luong_toi_thieu IS NOT NULL AND p_so_luong_toi_thieu < 0 THEN
    RAISE EXCEPTION 'Minimum quantity must be non-negative';
  END IF;
  IF p_so_luong_toi_da IS NOT NULL AND p_so_luong_toi_thieu IS NOT NULL
     AND p_so_luong_toi_thieu > p_so_luong_toi_da THEN
    RAISE EXCEPTION 'Minimum quantity (%) cannot exceed maximum quantity (%)',
      p_so_luong_toi_thieu, p_so_luong_toi_da;
  END IF;

  IF p_id IS NOT NULL THEN
    SELECT ct.*, qd.don_vi_id as decision_donvi, qd.trang_thai as decision_status
    INTO v_existing
    FROM public.chi_tiet_dinh_muc ct
    JOIN public.quyet_dinh_dinh_muc qd ON qd.id = ct.quyet_dinh_id
    WHERE ct.id = p_id;

    IF v_existing IS NULL THEN
      RAISE EXCEPTION 'Line item not found (id=%)', p_id;
    END IF;

    IF v_effective_donvi IS NOT NULL AND v_existing.decision_donvi != v_effective_donvi THEN
      RAISE EXCEPTION 'Access denied: line item belongs to different tenant';
    END IF;

    -- FIX: Allow both draft and active (was: != 'draft')
    IF v_existing.decision_status NOT IN ('draft', 'active') THEN
      RAISE EXCEPTION 'Cannot modify line items of inactive decisions. Decision status: %',
        v_existing.decision_status;
    END IF;

    IF p_nhom_thiet_bi_id IS NOT NULL AND p_nhom_thiet_bi_id != v_existing.nhom_thiet_bi_id THEN
      SELECT don_vi_id INTO v_category_donvi
      FROM public.nhom_thiet_bi WHERE id = p_nhom_thiet_bi_id;

      IF v_category_donvi IS NULL THEN
        RAISE EXCEPTION 'Category not found (id=%)', p_nhom_thiet_bi_id;
      END IF;

      IF v_category_donvi != v_existing.decision_donvi THEN
        RAISE EXCEPTION 'Category must belong to the same facility as the decision';
      END IF;
    END IF;

    v_snapshot_truoc := jsonb_build_object(
      'id', v_existing.id,
      'quyet_dinh_id', v_existing.quyet_dinh_id,
      'nhom_thiet_bi_id', v_existing.nhom_thiet_bi_id,
      'so_luong_toi_da', v_existing.so_luong_toi_da,
      'so_luong_toi_thieu', v_existing.so_luong_toi_thieu,
      'ghi_chu', v_existing.ghi_chu
    );

    DECLARE
      v_final_min INT := COALESCE(p_so_luong_toi_thieu, v_existing.so_luong_toi_thieu);
      v_final_max INT := COALESCE(p_so_luong_toi_da, v_existing.so_luong_toi_da);
    BEGIN
      IF v_final_min > v_final_max THEN
        RAISE EXCEPTION 'Minimum quantity (%) cannot exceed maximum quantity (%). Current min=%, max=%; updating min to %, max to %',
          v_final_min, v_final_max,
          v_existing.so_luong_toi_thieu, v_existing.so_luong_toi_da,
          COALESCE(p_so_luong_toi_thieu::TEXT, '(unchanged)'),
          COALESCE(p_so_luong_toi_da::TEXT, '(unchanged)');
      END IF;
    END;

    UPDATE public.chi_tiet_dinh_muc SET
      nhom_thiet_bi_id = COALESCE(p_nhom_thiet_bi_id, nhom_thiet_bi_id),
      so_luong_toi_da = COALESCE(p_so_luong_toi_da, so_luong_toi_da),
      so_luong_toi_thieu = COALESCE(p_so_luong_toi_thieu, so_luong_toi_thieu),
      ghi_chu = CASE WHEN p_ghi_chu IS NOT NULL THEN p_ghi_chu ELSE ghi_chu END,
      updated_at = NOW()
    WHERE id = p_id
    RETURNING id INTO v_new_id;

    v_thao_tac := 'dieu_chinh';

  ELSE
    SELECT * INTO v_decision_record
    FROM public.quyet_dinh_dinh_muc
    WHERE id = p_quyet_dinh_id;

    IF v_decision_record IS NULL THEN
      RAISE EXCEPTION 'Quota decision not found (id=%)', p_quyet_dinh_id;
    END IF;

    IF v_effective_donvi IS NOT NULL AND v_decision_record.don_vi_id != v_effective_donvi THEN
      RAISE EXCEPTION 'Access denied: decision belongs to different tenant';
    END IF;

    -- FIX: Allow both draft and active (was: != 'draft')
    IF v_decision_record.trang_thai NOT IN ('draft', 'active') THEN
      RAISE EXCEPTION 'Cannot add line items to inactive decisions. Decision status: %',
        v_decision_record.trang_thai;
    END IF;

    SELECT don_vi_id INTO v_category_donvi
    FROM public.nhom_thiet_bi WHERE id = p_nhom_thiet_bi_id;

    IF v_category_donvi IS NULL THEN
      RAISE EXCEPTION 'Category not found (id=%)', p_nhom_thiet_bi_id;
    END IF;

    IF v_category_donvi != v_decision_record.don_vi_id THEN
      RAISE EXCEPTION 'Category must belong to the same facility as the decision';
    END IF;

    INSERT INTO public.chi_tiet_dinh_muc (
      quyet_dinh_id,
      nhom_thiet_bi_id,
      so_luong_toi_da,
      so_luong_toi_thieu,
      ghi_chu
    ) VALUES (
      p_quyet_dinh_id,
      p_nhom_thiet_bi_id,
      p_so_luong_toi_da,
      COALESCE(p_so_luong_toi_thieu, 0),
      p_ghi_chu
    )
    RETURNING id INTO v_new_id;

    v_thao_tac := 'tao';
  END IF;

  SELECT ct.*, qd.don_vi_id as decision_donvi
  INTO v_existing
  FROM public.chi_tiet_dinh_muc ct
  JOIN public.quyet_dinh_dinh_muc qd ON qd.id = ct.quyet_dinh_id
  WHERE ct.id = v_new_id;

  v_snapshot_sau := jsonb_build_object(
    'id', v_existing.id,
    'quyet_dinh_id', v_existing.quyet_dinh_id,
    'nhom_thiet_bi_id', v_existing.nhom_thiet_bi_id,
    'so_luong_toi_da', v_existing.so_luong_toi_da,
    'so_luong_toi_thieu', v_existing.so_luong_toi_thieu,
    'ghi_chu', v_existing.ghi_chu
  );

  INSERT INTO public.lich_su_dinh_muc (
    chi_tiet_id,
    quyet_dinh_id,
    don_vi_id,
    thao_tac,
    snapshot_truoc,
    snapshot_sau,
    thuc_hien_boi
  ) VALUES (
    v_new_id,
    v_existing.quyet_dinh_id,
    v_existing.decision_donvi,
    v_thao_tac,
    v_snapshot_truoc,
    v_snapshot_sau,
    v_user_id
  );

  RETURN jsonb_build_object(
    'id', v_new_id,
    'operation', CASE WHEN v_thao_tac = 'tao' THEN 'created' ELSE 'updated' END,
    'quyet_dinh_id', v_existing.quyet_dinh_id,
    'nhom_thiet_bi_id', v_existing.nhom_thiet_bi_id,
    'so_luong_toi_da', v_existing.so_luong_toi_da,
    'so_luong_toi_thieu', v_existing.so_luong_toi_thieu,
    'ghi_chu', v_existing.ghi_chu
  );
END;
$$;


ALTER FUNCTION public.dinh_muc_chi_tiet_upsert(p_id bigint, p_quyet_dinh_id bigint, p_nhom_thiet_bi_id bigint, p_so_luong_toi_da integer, p_so_luong_toi_thieu integer, p_ghi_chu text, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_chi_tiet_upsert(p_id bigint, p_quyet_dinh_id bigint, p_nhom_thiet_bi_id bigint, p_so_luong_toi_da integer, p_so_luong_toi_thieu integer, p_ghi_chu text, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_chi_tiet_upsert(p_id bigint, p_quyet_dinh_id bigint, p_nhom_thiet_bi_id bigint, p_so_luong_toi_da integer, p_so_luong_toi_thieu integer, p_ghi_chu text, p_don_vi bigint) IS 'Create or update a quota line item. Allows both draft and active decisions.
If p_id is NULL: INSERT new line item (requires p_quyet_dinh_id, p_nhom_thiet_bi_id, p_so_luong_toi_da)
If p_id is NOT NULL: UPDATE existing line item
Validates: decision is in draft or active status, category belongs to same tenant
Roles: global, admin, to_qltb only.
Audit: Creates lich_su_dinh_muc record with thao_tac=tao (insert) or dieu_chinh (update).';


--
-- Name: dinh_muc_compliance_detail(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_compliance_detail(p_quyet_dinh_id bigint DEFAULT NULL::bigint, p_don_vi bigint DEFAULT NULL::bigint) RETURNS TABLE(quyet_dinh_id bigint, nhom_thiet_bi_id bigint, ma_nhom text, ten_nhom text, phan_loai text, so_luong_toi_thieu integer, so_luong_toi_da integer, so_luong_hien_co bigint, trang_thai_tuan_thu text, chenh_lech integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_decision_id BIGINT;
  v_decision_don_vi BIGINT;
  v_allowed_facilities BIGINT[];
BEGIN
  -- Fallback for older tokens using 'role' instead of 'app_role'
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;

  -- Tenant isolation based on role
  IF v_role IN ('global', 'admin') THEN
    -- Global/admin can access any tenant (use provided p_don_vi)
    NULL;
  ELSIF v_role = 'regional_leader' THEN
    -- Regional leader: validate p_don_vi against allowed facilities
    v_allowed_facilities := public.allowed_don_vi_for_session();
    IF p_don_vi IS NULL OR NOT (p_don_vi = ANY(v_allowed_facilities)) THEN
      RAISE EXCEPTION 'Access denied: facility % is not in your region', p_don_vi;
    END IF;
  ELSE
    -- Other roles: force to their own tenant
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;

  -- If still no tenant specified, return empty
  IF p_don_vi IS NULL THEN
    RETURN;
  END IF;

  -- Determine which decision to use
  IF p_quyet_dinh_id IS NOT NULL THEN
    -- Verify decision belongs to this tenant
    SELECT qd.id, qd.don_vi_id INTO v_decision_id, v_decision_don_vi
    FROM public.quyet_dinh_dinh_muc qd
    WHERE qd.id = p_quyet_dinh_id;

    IF v_decision_don_vi IS NULL OR v_decision_don_vi != p_don_vi THEN
      -- Decision not found or belongs to different tenant
      RETURN;
    END IF;
  ELSE
    -- Find active decision for this tenant
    SELECT qd.id INTO v_decision_id
    FROM public.quyet_dinh_dinh_muc qd
    WHERE qd.don_vi_id = p_don_vi
      AND qd.trang_thai = 'active'
    ORDER BY qd.ngay_hieu_luc DESC
    LIMIT 1;

    -- No active decision found
    IF v_decision_id IS NULL THEN
      RETURN;
    END IF;
  END IF;

  -- Return compliance details for each category in the decision
  RETURN QUERY
  WITH equipment_counts AS (
    -- Count equipment per category for this tenant
    SELECT
      tb.nhom_thiet_bi_id,
      COUNT(*)::BIGINT AS cnt
    FROM public.thiet_bi tb
    WHERE tb.don_vi = p_don_vi
      AND tb.nhom_thiet_bi_id IS NOT NULL
    GROUP BY tb.nhom_thiet_bi_id
  ),
  compliance_data AS (
    SELECT
      v_decision_id AS quyet_dinh_id,
      ntb.id AS nhom_thiet_bi_id,
      ntb.ma_nhom,
      ntb.ten_nhom,
      ntb.phan_loai,
      cd.so_luong_toi_thieu,
      cd.so_luong_toi_da,
      COALESCE(ec.cnt, 0)::BIGINT AS so_luong_hien_co,
      CASE
        WHEN COALESCE(ec.cnt, 0) < cd.so_luong_toi_thieu THEN 'thieu'
        WHEN COALESCE(ec.cnt, 0) > cd.so_luong_toi_da THEN 'vuot'
        ELSE 'dat'
      END AS trang_thai_tuan_thu,
      -- Calculate difference from acceptable range
      -- Negative if under minimum, positive if over maximum, 0 if in range
      CASE
        WHEN COALESCE(ec.cnt, 0) < cd.so_luong_toi_thieu THEN
          (COALESCE(ec.cnt, 0) - cd.so_luong_toi_thieu)::INT
        WHEN COALESCE(ec.cnt, 0) > cd.so_luong_toi_da THEN
          (COALESCE(ec.cnt, 0) - cd.so_luong_toi_da)::INT
        ELSE 0
      END AS chenh_lech
    FROM public.chi_tiet_dinh_muc cd
    INNER JOIN public.nhom_thiet_bi ntb ON ntb.id = cd.nhom_thiet_bi_id
    LEFT JOIN equipment_counts ec ON ec.nhom_thiet_bi_id = cd.nhom_thiet_bi_id
    WHERE cd.quyet_dinh_id = v_decision_id
  )
  SELECT
    cdata.quyet_dinh_id,
    cdata.nhom_thiet_bi_id,
    cdata.ma_nhom,
    cdata.ten_nhom,
    cdata.phan_loai,
    cdata.so_luong_toi_thieu,
    cdata.so_luong_toi_da,
    cdata.so_luong_hien_co,
    cdata.trang_thai_tuan_thu,
    cdata.chenh_lech
  FROM compliance_data cdata
  ORDER BY
    -- Order by compliance status: thieu (under) first, then vuot (over), then dat (compliant)
    CASE cdata.trang_thai_tuan_thu
      WHEN 'thieu' THEN 1
      WHEN 'vuot' THEN 2
      WHEN 'dat' THEN 3
    END,
    cdata.ma_nhom;
END;
$$;


ALTER FUNCTION public.dinh_muc_compliance_detail(p_quyet_dinh_id bigint, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_compliance_detail(p_quyet_dinh_id bigint, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_compliance_detail(p_quyet_dinh_id bigint, p_don_vi bigint) IS 'Get per-category compliance status for a quota decision.
   If p_quyet_dinh_id is NULL, uses active decision for tenant.
   Returns category details with quota limits, current counts, and compliance status.
   Ordered by compliance priority: thieu (under quota), vuot (over quota), dat (compliant).';


--
-- Name: dinh_muc_compliance_summary(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_compliance_summary(p_quyet_dinh_id bigint DEFAULT NULL::bigint, p_don_vi bigint DEFAULT NULL::bigint) RETURNS TABLE(quyet_dinh_id bigint, so_quyet_dinh text, ten_don_vi text, total_categories bigint, dat_count bigint, thieu_count bigint, vuot_count bigint, unassigned_equipment bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_decision_id BIGINT;
  v_decision_don_vi BIGINT;
  v_allowed_facilities BIGINT[];
  v_facility_name TEXT;
BEGIN
  -- Fallback for older tokens using 'role' instead of 'app_role'
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;

  -- Tenant isolation based on role
  IF v_role IN ('global', 'admin') THEN
    -- Global/admin can access any tenant (use provided p_don_vi)
    NULL;
  ELSIF v_role = 'regional_leader' THEN
    -- Regional leader: validate p_don_vi against allowed facilities
    v_allowed_facilities := public.allowed_don_vi_for_session();
    IF p_don_vi IS NULL OR NOT (p_don_vi = ANY(v_allowed_facilities)) THEN
      RAISE EXCEPTION 'Access denied: facility % is not in your region', p_don_vi;
    END IF;
  ELSE
    -- Other roles: force to their own tenant
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;

  -- If still no tenant specified, return empty
  IF p_don_vi IS NULL THEN
    RETURN;
  END IF;

  -- Fetch facility name for report headers
  SELECT dv.name INTO v_facility_name
  FROM public.don_vi dv
  WHERE dv.id = p_don_vi;

  -- Determine which decision to use
  IF p_quyet_dinh_id IS NOT NULL THEN
    -- Verify decision belongs to this tenant
    SELECT qd.id, qd.don_vi_id INTO v_decision_id, v_decision_don_vi
    FROM public.quyet_dinh_dinh_muc qd
    WHERE qd.id = p_quyet_dinh_id;

    IF v_decision_don_vi IS NULL OR v_decision_don_vi != p_don_vi THEN
      -- Decision not found or belongs to different tenant
      RETURN;
    END IF;
  ELSE
    -- Find active decision for this tenant
    SELECT qd.id INTO v_decision_id
    FROM public.quyet_dinh_dinh_muc qd
    WHERE qd.don_vi_id = p_don_vi
      AND qd.trang_thai = 'active'
    ORDER BY qd.ngay_hieu_luc DESC
    LIMIT 1;

    -- No active decision found
    IF v_decision_id IS NULL THEN
      RETURN QUERY
      SELECT
        NULL::BIGINT AS quyet_dinh_id,
        NULL::TEXT AS so_quyet_dinh,
        v_facility_name AS ten_don_vi,
        0::BIGINT AS total_categories,
        0::BIGINT AS dat_count,
        0::BIGINT AS thieu_count,
        0::BIGINT AS vuot_count,
        (
          SELECT COUNT(*)::BIGINT
          FROM public.thiet_bi tb
          WHERE tb.don_vi = p_don_vi
            AND tb.nhom_thiet_bi_id IS NULL
        ) AS unassigned_equipment;
      RETURN;
    END IF;
  END IF;

  -- Calculate compliance statistics
  RETURN QUERY
  WITH equipment_counts AS (
    -- Count equipment per category for this tenant
    SELECT
      tb.nhom_thiet_bi_id,
      COUNT(*)::BIGINT AS so_luong_hien_co
    FROM public.thiet_bi tb
    WHERE tb.don_vi = p_don_vi
      AND tb.nhom_thiet_bi_id IS NOT NULL
    GROUP BY tb.nhom_thiet_bi_id
  ),
  compliance_status AS (
    -- Calculate compliance for each line item in the decision
    SELECT
      cd.nhom_thiet_bi_id,
      cd.so_luong_toi_thieu,
      cd.so_luong_toi_da,
      COALESCE(ec.so_luong_hien_co, 0) AS so_luong_hien_co,
      CASE
        WHEN COALESCE(ec.so_luong_hien_co, 0) < cd.so_luong_toi_thieu THEN 'thieu'
        WHEN COALESCE(ec.so_luong_hien_co, 0) > cd.so_luong_toi_da THEN 'vuot'
        ELSE 'dat'
      END AS trang_thai_tuan_thu
    FROM public.chi_tiet_dinh_muc cd
    LEFT JOIN equipment_counts ec ON ec.nhom_thiet_bi_id = cd.nhom_thiet_bi_id
    WHERE cd.quyet_dinh_id = v_decision_id
  )
  SELECT
    v_decision_id AS quyet_dinh_id,
    qd.so_quyet_dinh,
    v_facility_name AS ten_don_vi,
    COUNT(*)::BIGINT AS total_categories,
    COUNT(*) FILTER (WHERE cs.trang_thai_tuan_thu = 'dat')::BIGINT AS dat_count,
    COUNT(*) FILTER (WHERE cs.trang_thai_tuan_thu = 'thieu')::BIGINT AS thieu_count,
    COUNT(*) FILTER (WHERE cs.trang_thai_tuan_thu = 'vuot')::BIGINT AS vuot_count,
    (
      SELECT COUNT(*)::BIGINT
      FROM public.thiet_bi tb
      WHERE tb.don_vi = p_don_vi
        AND tb.nhom_thiet_bi_id IS NULL
    ) AS unassigned_equipment
  FROM compliance_status cs
  CROSS JOIN public.quyet_dinh_dinh_muc qd
  WHERE qd.id = v_decision_id
  GROUP BY qd.so_quyet_dinh;
END;
$$;


ALTER FUNCTION public.dinh_muc_compliance_summary(p_quyet_dinh_id bigint, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_compliance_summary(p_quyet_dinh_id bigint, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_compliance_summary(p_quyet_dinh_id bigint, p_don_vi bigint) IS 'Get dashboard-level compliance statistics for a quota decision.
   If p_quyet_dinh_id is NULL, uses active decision for tenant.
   Returns counts for compliant (dat), under quota (thieu), and over quota (vuot) categories.
   Includes ten_don_vi (facility name) for report headers.';


--
-- Name: dinh_muc_nhom_bulk_import(jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_nhom_bulk_import(p_items jsonb, p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := NULLIF(public._get_jwt_claim('user_id'), '')::BIGINT;
  v_effective_donvi BIGINT := NULL;
  v_len INT;
  v_idx INT;
  v_inserted INT := 0;
  v_failed INT := 0;
  v_details JSONB := '[]'::jsonb;
  v_item JSONB;
  v_original_idx INT;
  v_ma_nhom TEXT;
  v_ten_nhom TEXT;
  v_parent_ma_nhom TEXT;
  v_phan_loai TEXT;
  v_don_vi_tinh TEXT;
  v_thu_tu_hien_thi INT;
  v_mo_ta TEXT;
  v_parent_id BIGINT;
  v_new_id BIGINT;
  v_err TEXT;
  v_sorted_items JSONB;
  v_batch_lookup JSONB := '{}'::jsonb;
BEGIN
  -- SECURITY: Permission check
  IF v_role IS NULL OR v_role = '' THEN
    v_role := lower(COALESCE(public._get_jwt_claim('role'), ''));
  END IF;

  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role';
  END IF;

  -- SECURITY: Tenant isolation
  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi;
  ELSE
    IF v_claim_donvi IS NULL THEN
      RAISE EXCEPTION 'Access denied: tenant claim (don_vi) is required for non-global users';
    END IF;
    v_effective_donvi := v_claim_donvi;
  END IF;

  IF v_effective_donvi IS NULL THEN
    RAISE EXCEPTION 'Tenant ID (p_don_vi) is required';
  END IF;

  -- INPUT VALIDATION
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'p_items must be a JSON array';
  END IF;

  v_len := jsonb_array_length(p_items);
  IF v_len = 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'inserted', 0,
      'failed', 0,
      'total', 0,
      'details', '[]'::jsonb
    );
  END IF;

  -- ADVISORY LOCK
  PERFORM pg_advisory_xact_lock(hashtext('nhom_thiet_bi_import_' || v_effective_donvi::text));

  -- VALIDATION: Check for duplicate ma_nhom within batch
  DECLARE
    v_dup_codes TEXT;
  BEGIN
    SELECT string_agg(ma_nhom, ', ')
    INTO v_dup_codes
    FROM (
      SELECT elem->>'ma_nhom' AS ma_nhom
      FROM jsonb_array_elements(p_items) AS elem
      GROUP BY elem->>'ma_nhom'
      HAVING COUNT(*) > 1
    ) dups;

    IF v_dup_codes IS NOT NULL THEN
      RAISE EXCEPTION 'Duplicate category codes within batch: %', v_dup_codes;
    END IF;
  END;

  -- CYCLE DETECTION
  DECLARE
    v_has_cycle BOOLEAN := FALSE;
  BEGIN
    WITH RECURSIVE batch_items AS (
      SELECT
        elem->>'ma_nhom' AS ma_nhom,
        elem->>'parent_ma_nhom' AS parent_ma_nhom
      FROM jsonb_array_elements(p_items) AS elem
      WHERE elem->>'parent_ma_nhom' IS NOT NULL
        AND elem->>'parent_ma_nhom' <> ''
    ),
    cycle_check AS (
      SELECT
        ma_nhom AS start_node,
        ma_nhom AS current_node,
        ARRAY[ma_nhom] AS path,
        false AS is_cycle
      FROM batch_items

      UNION ALL

      SELECT
        cc.start_node,
        bi.parent_ma_nhom,
        cc.path || bi.parent_ma_nhom,
        bi.parent_ma_nhom = ANY(cc.path) AS is_cycle
      FROM cycle_check cc
      INNER JOIN batch_items bi ON bi.ma_nhom = cc.current_node
      WHERE NOT cc.is_cycle
        AND array_length(cc.path, 1) < v_len + 1
    )
    SELECT TRUE INTO v_has_cycle FROM cycle_check WHERE is_cycle LIMIT 1;

    IF v_has_cycle THEN
      RAISE EXCEPTION 'Cycle detected in parent references within batch';
    END IF;
  END;

  -- TOPOLOGICAL SORT
  WITH indexed_items AS (
    SELECT
      elem AS item,
      (row_number() OVER ()) - 1 AS original_idx,
      array_length(string_to_array(elem->>'ma_nhom', '.'), 1) AS depth,
      CASE
        WHEN elem->>'parent_ma_nhom' IS NULL OR elem->>'parent_ma_nhom' = '' THEN 0
        WHEN EXISTS (
          SELECT 1 FROM public.nhom_thiet_bi n
          WHERE n.ma_nhom = elem->>'parent_ma_nhom'
            AND n.don_vi_id = v_effective_donvi
        ) THEN 0
        ELSE 1
      END AS needs_batch_parent
    FROM jsonb_array_elements(p_items) AS elem
  )
  SELECT jsonb_agg(
    jsonb_set(item, '{_original_idx}', to_jsonb(original_idx))
    ORDER BY needs_batch_parent, depth, original_idx
  )
  INTO v_sorted_items
  FROM indexed_items;

  -- PROCESS EACH ITEM (in topological order)
  FOR v_idx IN 0 .. jsonb_array_length(v_sorted_items) - 1 LOOP
    v_item := v_sorted_items->v_idx;
    v_original_idx := (v_item->>'_original_idx')::INT;

    BEGIN
      -- Extract all user-input fields inside the per-item error boundary
      -- so that invalid data (e.g. non-numeric thu_tu_hien_thi) is caught
      -- per-item instead of aborting the entire import.
      v_ma_nhom := NULLIF(TRIM(v_item->>'ma_nhom'), '');
      v_ten_nhom := NULLIF(TRIM(v_item->>'ten_nhom'), '');
      v_parent_ma_nhom := NULLIF(TRIM(v_item->>'parent_ma_nhom'), '');
      v_phan_loai := NULLIF(TRIM(v_item->>'phan_loai'), '');
      v_don_vi_tinh := NULLIF(TRIM(v_item->>'don_vi_tinh'), '');
      v_thu_tu_hien_thi := NULLIF(v_item->>'thu_tu_hien_thi', '')::INT;
      v_mo_ta := NULLIF(TRIM(v_item->>'mo_ta'), '');

      -- Validate required fields
      IF v_ma_nhom IS NULL THEN
        RAISE EXCEPTION 'Category code (ma_nhom) is required';
      END IF;

      IF v_ten_nhom IS NULL THEN
        RAISE EXCEPTION 'Category name (ten_nhom) is required';
      END IF;

      -- Validate phan_loai
      IF v_phan_loai IS NOT NULL AND v_phan_loai NOT IN ('A', 'B') THEN
        RAISE EXCEPTION 'Classification (phan_loai) must be A or B, got: %', v_phan_loai;
      END IF;

      -- Check for duplicate against existing DB
      IF EXISTS (
        SELECT 1 FROM public.nhom_thiet_bi
        WHERE ma_nhom = v_ma_nhom AND don_vi_id = v_effective_donvi
      ) THEN
        RAISE EXCEPTION 'Category code already exists: %', v_ma_nhom;
      END IF;

      -- Resolve parent_id from parent_ma_nhom
      v_parent_id := NULL;
      IF v_parent_ma_nhom IS NOT NULL THEN
        IF v_batch_lookup ? v_parent_ma_nhom THEN
          v_parent_id := (v_batch_lookup->>v_parent_ma_nhom)::BIGINT;
        ELSE
          SELECT id INTO v_parent_id
          FROM public.nhom_thiet_bi
          WHERE ma_nhom = v_parent_ma_nhom
            AND don_vi_id = v_effective_donvi;

          IF v_parent_id IS NULL THEN
            RAISE EXCEPTION 'Parent category not found: %', v_parent_ma_nhom;
          END IF;
        END IF;
      END IF;

      -- Insert the category
      INSERT INTO public.nhom_thiet_bi (
        don_vi_id,
        parent_id,
        ma_nhom,
        ten_nhom,
        phan_loai,
        don_vi_tinh,
        thu_tu_hien_thi,
        mo_ta,
        created_by,
        updated_by
      ) VALUES (
        v_effective_donvi,
        v_parent_id,
        v_ma_nhom,
        v_ten_nhom,
        v_phan_loai,
        COALESCE(v_don_vi_tinh, 'Cái'),
        COALESCE(v_thu_tu_hien_thi, 0),
        v_mo_ta,
        v_user_id,
        v_user_id
      )
      RETURNING id INTO v_new_id;

      -- Add to batch lookup for subsequent items
      v_batch_lookup := v_batch_lookup || jsonb_build_object(v_ma_nhom, v_new_id);

      -- Record success
      v_inserted := v_inserted + 1;
      v_details := v_details || jsonb_build_array(jsonb_build_object(
        'index', v_original_idx,
        'success', true,
        'ma_nhom', v_ma_nhom,
        'id', v_new_id
      ));

    EXCEPTION WHEN OTHERS THEN
      -- Record failure
      v_failed := v_failed + 1;
      GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
      v_details := v_details || jsonb_build_array(jsonb_build_object(
        'index', v_original_idx,
        'success', false,
        'ma_nhom', COALESCE(v_ma_nhom, '(unknown)'),
        'error', COALESCE(v_err, SQLERRM)
      ));
    END;
  END LOOP;

  -- RETURN RESULT
  SELECT jsonb_agg(detail ORDER BY (detail->>'index')::int)
  INTO v_details
  FROM jsonb_array_elements(v_details) AS detail;

  RETURN jsonb_build_object(
    'success', v_failed = 0,
    'inserted', v_inserted,
    'failed', v_failed,
    'total', v_len,
    'details', COALESCE(v_details, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION public.dinh_muc_nhom_bulk_import(p_items jsonb, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_nhom_bulk_import(p_items jsonb, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_nhom_bulk_import(p_items jsonb, p_don_vi bigint) IS 'Bulk import equipment categories from Excel.
Input: p_items = [{ma_nhom, ten_nhom, parent_ma_nhom?, phan_loai?, don_vi_tinh?, thu_tu_hien_thi?, mo_ta?}]
Features:
  - Topological sort: parents processed before children
  - Cycle detection: prevents circular parent references (batch-level)
  - Duplicate within batch: hard-stop (data quality issue)
  - Duplicate against existing: per-item (allows partial success)
  - Parent resolution: looks up parent_ma_nhom in DB and within batch
  - Per-item error recovery: one failure does not abort others
  - Advisory lock: prevents concurrent imports
Roles: global, admin, to_qltb only.';


--
-- Name: dinh_muc_nhom_delete(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_nhom_delete(p_id bigint, p_don_vi bigint DEFAULT NULL::bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := public._get_jwt_user_id();
  v_category_don_vi BIGINT;
  v_equipment_count BIGINT;
  v_child_count BIGINT;
  v_quota_count BIGINT;
BEGIN
  -- 1. Permission check: only global, admin, to_qltb can delete
  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role.';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authenticated user_id claim is required';
  END IF;

  -- 2. Tenant isolation: non-global/admin users must use their own tenant
  IF v_role NOT IN ('global', 'admin') THEN
    p_don_vi := v_claim_donvi;
    -- SECURITY: Non-global/admin roles MUST have a tenant - fail closed if missing
    IF p_don_vi IS NULL THEN
      RAISE EXCEPTION 'Access denied: tenant context required';
    END IF;
  END IF;

  -- Validate category ID
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'Category ID (p_id) is required.';
  END IF;

  -- Verify category exists and lock row to prevent TOCTOU before dependency checks + delete
  SELECT don_vi_id INTO v_category_don_vi
  FROM public.nhom_thiet_bi
  WHERE id = p_id
  FOR UPDATE;

  IF v_category_don_vi IS NULL THEN
    RAISE EXCEPTION 'Category not found.';
  END IF;

  -- Enforce tenant ownership
  IF p_don_vi IS NOT NULL AND v_category_don_vi != p_don_vi THEN
    RAISE EXCEPTION 'Category belongs to different tenant.';
  END IF;

  -- 3. Check for linked equipment
  SELECT COUNT(*) INTO v_equipment_count
  FROM public.thiet_bi
  WHERE nhom_thiet_bi_id = p_id;

  IF v_equipment_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete category: % equipment item(s) are linked. Unlink equipment first.', v_equipment_count;
  END IF;

  -- 4. Check for child categories
  SELECT COUNT(*) INTO v_child_count
  FROM public.nhom_thiet_bi
  WHERE parent_id = p_id;

  IF v_child_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete category: % child category(ies) exist. Delete or reassign children first.', v_child_count;
  END IF;

  -- 5. Check for quota line items referencing this category
  SELECT COUNT(*) INTO v_quota_count
  FROM public.chi_tiet_dinh_muc
  WHERE nhom_thiet_bi_id = p_id;

  IF v_quota_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete category: % quota line item(s) reference this category. Remove from quotas first.', v_quota_count;
  END IF;

  -- 6. Delete the category
  DELETE FROM public.nhom_thiet_bi
  WHERE id = p_id;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION public.dinh_muc_nhom_delete(p_id bigint, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_nhom_delete(p_id bigint, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_nhom_delete(p_id bigint, p_don_vi bigint) IS 'Delete equipment category with dependency checks.
   Prevents deletion if equipment, child categories, or quota items exist.
   Returns TRUE on success, raises exception on failure.';


--
-- Name: dinh_muc_nhom_get(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_nhom_get(p_id bigint, p_don_vi bigint DEFAULT NULL::bigint) RETURNS TABLE(id bigint, don_vi_id bigint, parent_id bigint, ma_nhom text, ten_nhom text, phan_loai text, don_vi_tinh text, thu_tu_hien_thi integer, mo_ta text, tu_khoa text[], created_at timestamp with time zone, updated_at timestamp with time zone, created_by bigint, updated_by bigint, so_luong_hien_co bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_category_don_vi BIGINT;
  v_allowed_facilities BIGINT[];
BEGIN
  -- Fallback for older tokens
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;

  -- Tenant isolation based on role
  IF v_role IN ('global', 'admin') THEN
    -- Global/admin can access any tenant (use provided p_don_vi)
    NULL;
  ELSIF v_role = 'regional_leader' THEN
    -- Regional leader: validate p_don_vi against allowed facilities
    v_allowed_facilities := public.allowed_don_vi_for_session();
    IF p_don_vi IS NULL OR NOT (p_don_vi = ANY(v_allowed_facilities)) THEN
      RAISE EXCEPTION 'Access denied: facility % is not in your region', p_don_vi;
    END IF;
  ELSE
    -- Other roles: force to their own tenant
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;

  -- Verify category belongs to the specified tenant
  SELECT n.don_vi_id INTO v_category_don_vi
  FROM public.nhom_thiet_bi n
  WHERE n.id = p_id;

  IF v_category_don_vi IS NULL THEN
    -- Category not found
    RETURN;
  END IF;

  -- Enforce tenant ownership
  IF p_don_vi IS NOT NULL AND v_category_don_vi != p_don_vi THEN
    -- Category belongs to different tenant
    RETURN;
  END IF;

  -- Return category with equipment count
  RETURN QUERY
  SELECT
    n.id,
    n.don_vi_id,
    n.parent_id,
    n.ma_nhom,
    n.ten_nhom,
    n.phan_loai,
    n.don_vi_tinh,
    n.thu_tu_hien_thi,
    n.mo_ta,
    n.tu_khoa,
    n.created_at,
    n.updated_at,
    n.created_by,
    n.updated_by,
    COALESCE((
      SELECT COUNT(*)::BIGINT
      FROM public.thiet_bi tb
      WHERE tb.nhom_thiet_bi_id = n.id
    ), 0) AS so_luong_hien_co
  FROM public.nhom_thiet_bi n
  WHERE n.id = p_id;
END;
$$;


ALTER FUNCTION public.dinh_muc_nhom_get(p_id bigint, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_nhom_get(p_id bigint, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_nhom_get(p_id bigint, p_don_vi bigint) IS 'Get single equipment category by ID with equipment count.
   Returns null if category not found or user lacks tenant access.';


--
-- Name: dinh_muc_nhom_list(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_nhom_list(p_don_vi bigint DEFAULT NULL::bigint) RETURNS TABLE(id bigint, parent_id bigint, ma_nhom text, ten_nhom text, phan_loai text, don_vi_tinh text, thu_tu_hien_thi integer, mo_ta text, tu_khoa text[], level integer, so_luong_hien_co bigint, so_luong_toi_da integer, so_luong_toi_thieu integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims JSONB := COALESCE(
    NULLIF(current_setting('request.jwt.claims', true), '')::JSONB,
    '{}'::JSONB
  );
  v_role TEXT := COALESCE(NULLIF(v_claims->>'app_role', ''), NULLIF(v_claims->>'role', ''));
  v_user_id TEXT := NULLIF(v_claims->>'user_id', '');
  v_don_vi TEXT := v_claims->>'don_vi';
  v_allowed_facilities BIGINT[];
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING errcode = '42501';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    NULL;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed_facilities := public.allowed_don_vi_for_session();
    IF p_don_vi IS NULL OR NOT (p_don_vi = ANY(v_allowed_facilities)) THEN
      RAISE EXCEPTION 'Access denied: facility % is not in your region', p_don_vi
        USING errcode = '42501';
    END IF;
  ELSE
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;

  IF p_don_vi IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH RECURSIVE category_tree AS (
    SELECT
      n.id,
      n.parent_id,
      n.ma_nhom,
      n.ten_nhom,
      n.phan_loai,
      n.don_vi_tinh,
      n.thu_tu_hien_thi,
      n.mo_ta,
      n.tu_khoa,
      1 AS level,
      ARRAY[lpad(COALESCE(n.thu_tu_hien_thi, 0)::text, 10, '0') || ':' || n.ma_nhom] AS sort_path
    FROM public.nhom_thiet_bi n
    WHERE n.don_vi_id = p_don_vi
      AND n.parent_id IS NULL

    UNION ALL

    SELECT
      n.id,
      n.parent_id,
      n.ma_nhom,
      n.ten_nhom,
      n.phan_loai,
      n.don_vi_tinh,
      n.thu_tu_hien_thi,
      n.mo_ta,
      n.tu_khoa,
      ct.level + 1,
      ct.sort_path || (lpad(COALESCE(n.thu_tu_hien_thi, 0)::text, 10, '0') || ':' || n.ma_nhom)
    FROM public.nhom_thiet_bi n
    INNER JOIN category_tree ct ON n.parent_id = ct.id
    WHERE n.don_vi_id = p_don_vi
  ),
  equipment_counts AS (
    SELECT
      tb.nhom_thiet_bi_id,
      COUNT(*)::BIGINT AS cnt
    FROM public.thiet_bi tb
    WHERE tb.don_vi = p_don_vi
      AND tb.nhom_thiet_bi_id IS NOT NULL
    GROUP BY tb.nhom_thiet_bi_id
  ),
  active_quotas AS (
    SELECT
      cd.nhom_thiet_bi_id,
      cd.so_luong_toi_da,
      cd.so_luong_toi_thieu
    FROM public.chi_tiet_dinh_muc cd
    INNER JOIN public.quyet_dinh_dinh_muc qd ON qd.id = cd.quyet_dinh_id
    WHERE qd.don_vi_id = p_don_vi
      AND qd.trang_thai = 'active'
  )
  SELECT
    ct.id,
    ct.parent_id,
    ct.ma_nhom,
    ct.ten_nhom,
    ct.phan_loai,
    ct.don_vi_tinh,
    ct.thu_tu_hien_thi,
    ct.mo_ta,
    ct.tu_khoa,
    ct.level,
    COALESCE(ec.cnt, 0) AS so_luong_hien_co,
    aq.so_luong_toi_da,
    aq.so_luong_toi_thieu
  FROM category_tree ct
  LEFT JOIN equipment_counts ec ON ec.nhom_thiet_bi_id = ct.id
  LEFT JOIN active_quotas aq ON aq.nhom_thiet_bi_id = ct.id
  ORDER BY ct.sort_path;
END;
$$;


ALTER FUNCTION public.dinh_muc_nhom_list(p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_nhom_list(p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_nhom_list(p_don_vi bigint) IS 'List device quota categories with hierarchy, equipment counts, and active quota min/max fields.';


--
-- Name: dinh_muc_nhom_list_paginated(bigint, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_nhom_list_paginated(p_don_vi bigint DEFAULT NULL::bigint, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20, p_search text DEFAULT NULL::text) RETURNS TABLE(id bigint, parent_id bigint, ma_nhom text, ten_nhom text, phan_loai text, don_vi_tinh text, thu_tu_hien_thi integer, mo_ta text, tu_khoa text[], level integer, so_luong_hien_co bigint, so_luong_toi_da integer, so_luong_toi_thieu integer, total_root_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role  TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_allowed_facilities BIGINT[];
  v_search TEXT;
  v_offset INT;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    NULL;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed_facilities := public.allowed_don_vi_for_session();
    IF p_don_vi IS NULL OR NOT (p_don_vi = ANY(v_allowed_facilities)) THEN
      RAISE EXCEPTION 'Access denied: facility % is not in your region', p_don_vi;
    END IF;
  ELSE
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;

  IF p_don_vi IS NULL THEN
    RETURN;
  END IF;

  p_page      := GREATEST(1, COALESCE(p_page, 1));
  p_page_size := GREATEST(1, LEAST(100, COALESCE(p_page_size, 20)));
  v_offset    := (p_page - 1) * p_page_size;

  v_search := NULLIF(TRIM(p_search), '');
  IF v_search IS NOT NULL THEN
    v_search := '%' || lower(v_search) || '%';
  END IF;

  RETURN QUERY
  WITH RECURSIVE
  full_tree AS (
    SELECT n.id, n.parent_id, n.ma_nhom, n.ten_nhom,
      n.phan_loai, n.don_vi_tinh, n.thu_tu_hien_thi, n.mo_ta, n.tu_khoa
    FROM public.nhom_thiet_bi n
    WHERE n.don_vi_id = p_don_vi
  ),
  matching_ids AS (
    SELECT ft.id FROM full_tree ft
    WHERE v_search IS NOT NULL
      AND (lower(ft.ma_nhom) LIKE v_search
        OR lower(ft.ten_nhom) LIKE v_search
        OR lower(COALESCE(ft.mo_ta, '')) LIKE v_search)
  ),
  ancestors AS (
    SELECT ft.id, ft.parent_id FROM full_tree ft
    WHERE ft.id IN (SELECT mi.id FROM matching_ids mi)
    UNION
    SELECT ft.id, ft.parent_id FROM full_tree ft
    INNER JOIN ancestors a ON a.parent_id = ft.id
  ),
  matching_root_ids AS (
    SELECT a.id FROM ancestors a WHERE a.parent_id IS NULL
  ),
  eligible_roots AS (
    SELECT ft.id, ft.ma_nhom, ft.thu_tu_hien_thi,
      lpad(COALESCE(ft.thu_tu_hien_thi, 0)::text, 10, '0') || ':' || ft.ma_nhom AS sort_key
    FROM full_tree ft
    WHERE ft.parent_id IS NULL
      AND (v_search IS NULL OR ft.id IN (SELECT mr.id FROM matching_root_ids mr))
  ),
  root_count AS (SELECT COUNT(*)::BIGINT AS cnt FROM eligible_roots),
  paged_roots AS (
    SELECT er.id FROM eligible_roots er ORDER BY er.sort_key
    LIMIT p_page_size OFFSET v_offset
  ),
  category_tree AS (
    SELECT ft.id, ft.parent_id, ft.ma_nhom, ft.ten_nhom,
      ft.phan_loai, ft.don_vi_tinh, ft.thu_tu_hien_thi, ft.mo_ta, ft.tu_khoa,
      1 AS level,
      ARRAY[lpad(COALESCE(ft.thu_tu_hien_thi, 0)::text, 10, '0') || ':' || ft.ma_nhom] AS sort_path
    FROM full_tree ft WHERE ft.id IN (SELECT pr.id FROM paged_roots pr)
    UNION ALL
    SELECT ft.id, ft.parent_id, ft.ma_nhom, ft.ten_nhom,
      ft.phan_loai, ft.don_vi_tinh, ft.thu_tu_hien_thi, ft.mo_ta, ft.tu_khoa,
      ct.level + 1,
      ct.sort_path || (lpad(COALESCE(ft.thu_tu_hien_thi, 0)::text, 10, '0') || ':' || ft.ma_nhom)
    FROM full_tree ft INNER JOIN category_tree ct ON ft.parent_id = ct.id
  ),
  equipment_counts AS (
    SELECT tb.nhom_thiet_bi_id, COUNT(*)::BIGINT AS cnt
    FROM public.thiet_bi tb
    WHERE tb.don_vi = p_don_vi AND tb.nhom_thiet_bi_id IS NOT NULL
    GROUP BY tb.nhom_thiet_bi_id
  ),
  active_quotas AS (
    SELECT cd.nhom_thiet_bi_id, cd.so_luong_toi_da, cd.so_luong_toi_thieu
    FROM public.chi_tiet_dinh_muc cd
    INNER JOIN public.quyet_dinh_dinh_muc qd ON qd.id = cd.quyet_dinh_id
    WHERE qd.don_vi_id = p_don_vi AND qd.trang_thai = 'active'
  )
  SELECT ct.id, ct.parent_id, ct.ma_nhom, ct.ten_nhom,
    ct.phan_loai, ct.don_vi_tinh, ct.thu_tu_hien_thi, ct.mo_ta, ct.tu_khoa, ct.level,
    COALESCE(ec.cnt, 0) AS so_luong_hien_co,
    aq.so_luong_toi_da, aq.so_luong_toi_thieu,
    rc.cnt AS total_root_count
  FROM category_tree ct
  LEFT JOIN equipment_counts ec ON ec.nhom_thiet_bi_id = ct.id
  LEFT JOIN active_quotas aq ON aq.nhom_thiet_bi_id = ct.id
  CROSS JOIN root_count rc
  ORDER BY ct.sort_path;
END;
$$;


ALTER FUNCTION public.dinh_muc_nhom_list_paginated(p_don_vi bigint, p_page integer, p_page_size integer, p_search text) OWNER TO postgres;

--
-- Name: dinh_muc_nhom_upsert(bigint, bigint, bigint, text, text, text, text, integer, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_nhom_upsert(p_id bigint DEFAULT NULL::bigint, p_don_vi bigint DEFAULT NULL::bigint, p_parent_id bigint DEFAULT NULL::bigint, p_ma_nhom text DEFAULT NULL::text, p_ten_nhom text DEFAULT NULL::text, p_phan_loai text DEFAULT NULL::text, p_don_vi_tinh text DEFAULT NULL::text, p_thu_tu_hien_thi integer DEFAULT NULL::integer, p_mo_ta text DEFAULT NULL::text, p_tu_khoa text[] DEFAULT NULL::text[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_user_id TEXT := current_setting('request.jwt.claims', true)::json->>'user_id';
  v_category_don_vi BIGINT;
  v_result_id BIGINT;
BEGIN
  -- Fallback for older tokens
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;

  -- 1. Permission check: only global, admin, to_qltb can write
  IF v_role IS NULL OR v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role.';
  END IF;

  -- 2. Tenant isolation: non-global/admin users must use their own tenant
  IF v_role NOT IN ('global', 'admin') THEN
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;

  -- Validate tenant ID is provided
  IF p_don_vi IS NULL THEN
    RAISE EXCEPTION 'Tenant ID (p_don_vi) is required.';
  END IF;

  -- Validate required fields for insert
  IF p_id IS NULL THEN
    IF p_ma_nhom IS NULL OR TRIM(p_ma_nhom) = '' THEN
      RAISE EXCEPTION 'Category code (p_ma_nhom) is required.';
    END IF;
    IF p_ten_nhom IS NULL OR TRIM(p_ten_nhom) = '' THEN
      RAISE EXCEPTION 'Category name (p_ten_nhom) is required.';
    END IF;
  END IF;

  -- Validate phan_loai if provided
  IF p_phan_loai IS NOT NULL AND p_phan_loai NOT IN ('A', 'B') THEN
    RAISE EXCEPTION 'Classification (p_phan_loai) must be A or B.';
  END IF;

  -- Validate parent category belongs to same tenant
  -- Note: p_parent_id = 0 is a sentinel meaning "set to root (NULL)"
  IF p_parent_id IS NOT NULL AND p_parent_id > 0 THEN
    SELECT don_vi_id INTO v_category_don_vi
    FROM public.nhom_thiet_bi
    WHERE id = p_parent_id;

    IF v_category_don_vi IS NULL THEN
      RAISE EXCEPTION 'Parent category not found.';
    END IF;

    IF v_category_don_vi != p_don_vi THEN
      RAISE EXCEPTION 'Parent category must belong to the same tenant.';
    END IF;
  END IF;

  -- 3. Business logic: INSERT or UPDATE
  IF p_id IS NULL THEN
    -- INSERT new category
    -- Note: p_parent_id = 0 is a sentinel meaning "create at root (NULL)"
    INSERT INTO public.nhom_thiet_bi (
      don_vi_id,
      parent_id,
      ma_nhom,
      ten_nhom,
      phan_loai,
      don_vi_tinh,
      thu_tu_hien_thi,
      mo_ta,
      tu_khoa,
      created_by,
      updated_by
    ) VALUES (
      p_don_vi,
      CASE WHEN p_parent_id IS NULL OR p_parent_id <= 0 THEN NULL ELSE p_parent_id END,
      TRIM(p_ma_nhom),
      TRIM(p_ten_nhom),
      COALESCE(p_phan_loai, 'B'),
      COALESCE(p_don_vi_tinh, 'Cái'),
      COALESCE(p_thu_tu_hien_thi, 0),
      p_mo_ta,
      p_tu_khoa,
      NULLIF(v_user_id, '')::BIGINT,
      NULLIF(v_user_id, '')::BIGINT
    )
    RETURNING id INTO v_result_id;

  ELSE
    -- UPDATE existing category
    -- First verify category belongs to this tenant
    SELECT don_vi_id INTO v_category_don_vi
    FROM public.nhom_thiet_bi
    WHERE id = p_id;

    IF v_category_don_vi IS NULL THEN
      RAISE EXCEPTION 'Category not found.';
    END IF;

    IF v_category_don_vi != p_don_vi THEN
      RAISE EXCEPTION 'Category belongs to different tenant.';
    END IF;

    -- Prevent circular parent reference
    -- Note: p_parent_id = 0 is a sentinel meaning "set to root (NULL)"
    IF p_parent_id IS NOT NULL AND p_parent_id > 0 THEN
      IF p_parent_id = p_id THEN
        RAISE EXCEPTION 'Category cannot be its own parent.';
      END IF;

      IF EXISTS (
        WITH RECURSIVE ancestors AS (
          SELECT id, parent_id
          FROM public.nhom_thiet_bi
          WHERE id = p_parent_id
            AND don_vi_id = p_don_vi

          UNION ALL

          SELECT n.id, n.parent_id
          FROM public.nhom_thiet_bi n
          JOIN ancestors a ON n.id = a.parent_id
          WHERE n.don_vi_id = p_don_vi
        )
        SELECT 1
        FROM ancestors
        WHERE id = p_id
      ) THEN
        RAISE EXCEPTION 'Circular parent reference is not allowed.';
      END IF;
    END IF;

    -- Update category
    -- Note: p_parent_id = 0 means "set to root (NULL)", NULL means "keep existing"
    UPDATE public.nhom_thiet_bi
    SET
      parent_id = CASE
        WHEN p_parent_id = 0 THEN NULL           -- Sentinel: move to root
        WHEN p_parent_id IS NULL THEN parent_id  -- Not provided: keep existing
        ELSE p_parent_id                          -- Provided: set new parent
      END,
      ma_nhom = COALESCE(NULLIF(TRIM(p_ma_nhom), ''), ma_nhom),
      ten_nhom = COALESCE(NULLIF(TRIM(p_ten_nhom), ''), ten_nhom),
      phan_loai = COALESCE(p_phan_loai, phan_loai),
      don_vi_tinh = COALESCE(p_don_vi_tinh, don_vi_tinh),
      thu_tu_hien_thi = COALESCE(p_thu_tu_hien_thi, thu_tu_hien_thi),
      mo_ta = COALESCE(p_mo_ta, mo_ta),
      tu_khoa = COALESCE(p_tu_khoa, tu_khoa),
      updated_at = NOW(),
      updated_by = NULLIF(v_user_id, '')::BIGINT
    WHERE id = p_id
    RETURNING id INTO v_result_id;
  END IF;

  RETURN v_result_id;
END;
$$;


ALTER FUNCTION public.dinh_muc_nhom_upsert(p_id bigint, p_don_vi bigint, p_parent_id bigint, p_ma_nhom text, p_ten_nhom text, p_phan_loai text, p_don_vi_tinh text, p_thu_tu_hien_thi integer, p_mo_ta text, p_tu_khoa text[]) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_nhom_upsert(p_id bigint, p_don_vi bigint, p_parent_id bigint, p_ma_nhom text, p_ten_nhom text, p_phan_loai text, p_don_vi_tinh text, p_thu_tu_hien_thi integer, p_mo_ta text, p_tu_khoa text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_nhom_upsert(p_id bigint, p_don_vi bigint, p_parent_id bigint, p_ma_nhom text, p_ten_nhom text, p_phan_loai text, p_don_vi_tinh text, p_thu_tu_hien_thi integer, p_mo_ta text, p_tu_khoa text[]) IS 'Create or update equipment category.
   Pass NULL for p_id to create new, or provide p_id to update existing.
   For p_parent_id: NULL = keep existing, 0 = move to root, >0 = set new parent.
   Enforces tenant isolation, role permissions, and circular-parent prevention.';


--
-- Name: dinh_muc_quyet_dinh_activate(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_quyet_dinh_activate(p_id bigint, p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := public._get_jwt_user_id();
  v_effective_donvi BIGINT := NULL;
  v_current RECORD;
  v_previous_active_id BIGINT;
  v_result JSONB;
BEGIN
  -- Permission check
  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authenticated user_id claim is required';
  END IF;

  -- Tenant isolation
  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi; -- NULL means all tenants for global/admin only
  ELSE
    v_effective_donvi := v_claim_donvi;
    -- SECURITY: Non-global/admin roles MUST have a tenant - fail closed if missing
    IF v_effective_donvi IS NULL THEN
      RAISE EXCEPTION 'Access denied: tenant context required';
    END IF;
  END IF;

  -- Get + lock decision row to reduce activation race window
  SELECT * INTO v_current
  FROM public.quyet_dinh_dinh_muc
  WHERE id = p_id
    AND (v_effective_donvi IS NULL OR don_vi_id = v_effective_donvi)
  FOR UPDATE;

  IF v_current IS NULL THEN
    RAISE EXCEPTION 'Quota decision not found or access denied (id=%)', p_id;
  END IF;

  -- Only draft decisions can be activated
  IF v_current.trang_thai != 'draft' THEN
    RAISE EXCEPTION 'Only draft decisions can be activated. Current status: %', v_current.trang_thai;
  END IF;

  -- Find + lock current active decision for this tenant before deactivating.
  SELECT id INTO v_previous_active_id
  FROM public.quyet_dinh_dinh_muc
  WHERE don_vi_id = v_current.don_vi_id
    AND trang_thai = 'active'
    AND id != p_id
  FOR UPDATE;

  IF v_previous_active_id IS NOT NULL THEN
    -- Deactivate previous active decision
    UPDATE public.quyet_dinh_dinh_muc
    SET trang_thai = 'inactive',
        updated_at = NOW(),
        updated_by = v_user_id
    WHERE id = v_previous_active_id;

    -- Audit log for deactivation
    INSERT INTO public.lich_su_dinh_muc (
      quyet_dinh_id,
      don_vi_id,
      thao_tac,
      snapshot_truoc,
      snapshot_sau,
      ly_do,
      thuc_hien_boi
    ) VALUES (
      v_previous_active_id,
      v_current.don_vi_id,
      'cap_nhat',
      jsonb_build_object('trang_thai', 'active'),
      jsonb_build_object('trang_thai', 'inactive'),
      'Auto-deactivated when decision #' || p_id || ' was activated',
      v_user_id
    );
  END IF;

  -- Activate the decision
  UPDATE public.quyet_dinh_dinh_muc
  SET trang_thai = 'active',
      updated_at = NOW(),
      updated_by = v_user_id
  WHERE id = p_id;

  -- Audit log for activation
  INSERT INTO public.lich_su_dinh_muc (
    quyet_dinh_id,
    don_vi_id,
    thao_tac,
    snapshot_truoc,
    snapshot_sau,
    thuc_hien_boi
  ) VALUES (
    p_id,
    v_current.don_vi_id,
    'cong_khai',
    jsonb_build_object('trang_thai', 'draft'),
    jsonb_build_object('trang_thai', 'active'),
    v_user_id
  );

  -- Return updated decision
  v_result := public.dinh_muc_quyet_dinh_get(p_id, v_effective_donvi);

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.dinh_muc_quyet_dinh_activate(p_id bigint, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_quyet_dinh_activate(p_id bigint, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_quyet_dinh_activate(p_id bigint, p_don_vi bigint) IS 'Activate a draft quota decision. Any currently active decision for the same tenant will be deactivated.
Roles: global, admin, to_qltb only.
Audit: Creates lich_su_dinh_muc record with thao_tac=cong_khai.';


--
-- Name: dinh_muc_quyet_dinh_create(text, date, date, text, text, bigint, date, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_quyet_dinh_create(p_so_quyet_dinh text, p_ngay_ban_hanh date, p_ngay_hieu_luc date, p_nguoi_ky text, p_chuc_vu_nguoi_ky text, p_don_vi bigint DEFAULT NULL::bigint, p_ngay_het_hieu_luc date DEFAULT NULL::date, p_ghi_chu text DEFAULT NULL::text, p_thay_the_cho_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := public._get_jwt_user_id();
  v_effective_donvi BIGINT := NULL;
  v_new_id BIGINT;
  v_result JSONB;
BEGIN
  -- Permission check: only global, admin, to_qltb can create
  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authenticated user_id claim is required';
  END IF;

  -- Tenant isolation
  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := COALESCE(p_don_vi, v_claim_donvi);
  ELSE
    v_effective_donvi := v_claim_donvi;
  END IF;

  IF v_effective_donvi IS NULL THEN
    RAISE EXCEPTION 'Tenant (don_vi) is required';
  END IF;

  -- Validate required fields
  IF p_so_quyet_dinh IS NULL OR trim(p_so_quyet_dinh) = '' THEN
    RAISE EXCEPTION 'Decision number (so_quyet_dinh) is required';
  END IF;

  IF p_nguoi_ky IS NULL OR trim(p_nguoi_ky) = '' THEN
    RAISE EXCEPTION 'Signer name (nguoi_ky) is required';
  END IF;

  IF p_chuc_vu_nguoi_ky IS NULL OR trim(p_chuc_vu_nguoi_ky) = '' THEN
    RAISE EXCEPTION 'Signer position (chuc_vu_nguoi_ky) is required';
  END IF;

  -- Create decision in draft status
  INSERT INTO public.quyet_dinh_dinh_muc (
    don_vi_id,
    so_quyet_dinh,
    ngay_ban_hanh,
    ngay_hieu_luc,
    ngay_het_hieu_luc,
    nguoi_ky,
    chuc_vu_nguoi_ky,
    trang_thai,
    ghi_chu,
    thay_the_cho_id,
    created_by,
    updated_by
  ) VALUES (
    v_effective_donvi,
    trim(p_so_quyet_dinh),
    p_ngay_ban_hanh,
    p_ngay_hieu_luc,
    p_ngay_het_hieu_luc,
    trim(p_nguoi_ky),
    trim(p_chuc_vu_nguoi_ky),
    'draft',
    p_ghi_chu,
    p_thay_the_cho_id,
    v_user_id,
    v_user_id
  )
  RETURNING id INTO v_new_id;

  -- Write audit log
  INSERT INTO public.lich_su_dinh_muc (
    quyet_dinh_id,
    don_vi_id,
    thao_tac,
    snapshot_sau,
    thuc_hien_boi
  ) VALUES (
    v_new_id,
    v_effective_donvi,
    'tao',
    jsonb_build_object(
      'so_quyet_dinh', trim(p_so_quyet_dinh),
      'ngay_ban_hanh', p_ngay_ban_hanh,
      'ngay_hieu_luc', p_ngay_hieu_luc,
      'ngay_het_hieu_luc', p_ngay_het_hieu_luc,
      'nguoi_ky', trim(p_nguoi_ky),
      'chuc_vu_nguoi_ky', trim(p_chuc_vu_nguoi_ky),
      'trang_thai', 'draft'
    ),
    v_user_id
  );

  -- Return the created decision
  v_result := public.dinh_muc_quyet_dinh_get(v_new_id, v_effective_donvi);

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.dinh_muc_quyet_dinh_create(p_so_quyet_dinh text, p_ngay_ban_hanh date, p_ngay_hieu_luc date, p_nguoi_ky text, p_chuc_vu_nguoi_ky text, p_don_vi bigint, p_ngay_het_hieu_luc date, p_ghi_chu text, p_thay_the_cho_id bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_quyet_dinh_create(p_so_quyet_dinh text, p_ngay_ban_hanh date, p_ngay_hieu_luc date, p_nguoi_ky text, p_chuc_vu_nguoi_ky text, p_don_vi bigint, p_ngay_het_hieu_luc date, p_ghi_chu text, p_thay_the_cho_id bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_quyet_dinh_create(p_so_quyet_dinh text, p_ngay_ban_hanh date, p_ngay_hieu_luc date, p_nguoi_ky text, p_chuc_vu_nguoi_ky text, p_don_vi bigint, p_ngay_het_hieu_luc date, p_ghi_chu text, p_thay_the_cho_id bigint) IS 'Create a new quota decision in draft status.
Required: so_quyet_dinh, ngay_ban_hanh, ngay_hieu_luc, nguoi_ky, chuc_vu_nguoi_ky
Roles: global, admin, to_qltb only.
Audit: Creates lich_su_dinh_muc record with thao_tac=tao.';


--
-- Name: dinh_muc_quyet_dinh_delete(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_quyet_dinh_delete(p_id bigint, p_don_vi bigint DEFAULT NULL::bigint, p_ly_do text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := public._get_jwt_user_id();
  v_effective_donvi BIGINT := NULL;
  v_current RECORD;
BEGIN
  -- Permission check
  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authenticated user_id claim is required';
  END IF;

  -- Tenant isolation
  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi; -- NULL means all tenants for global/admin only
  ELSE
    v_effective_donvi := v_claim_donvi;
    -- SECURITY: Non-global/admin roles MUST have a tenant - fail closed if missing
    IF v_effective_donvi IS NULL THEN
      RAISE EXCEPTION 'Access denied: tenant context required';
    END IF;
  END IF;

  -- Lock decision row to avoid TOCTOU between status check and delete
  SELECT * INTO v_current
  FROM public.quyet_dinh_dinh_muc
  WHERE id = p_id
    AND (v_effective_donvi IS NULL OR don_vi_id = v_effective_donvi)
  FOR UPDATE;

  IF v_current IS NULL THEN
    RAISE EXCEPTION 'Quota decision not found or access denied (id=%)', p_id;
  END IF;

  -- Only draft decisions can be deleted
  IF v_current.trang_thai != 'draft' THEN
    RAISE EXCEPTION 'Only draft decisions can be deleted. Current status: %', v_current.trang_thai;
  END IF;

  -- Write audit log BEFORE deletion (since quyet_dinh_id will be SET NULL on delete)
  INSERT INTO public.lich_su_dinh_muc (
    quyet_dinh_id,
    don_vi_id,
    thao_tac,
    snapshot_truoc,
    ly_do,
    thuc_hien_boi
  ) VALUES (
    p_id,
    v_current.don_vi_id,
    'huy',
    jsonb_build_object(
      'id', v_current.id,
      'so_quyet_dinh', v_current.so_quyet_dinh,
      'ngay_ban_hanh', v_current.ngay_ban_hanh,
      'ngay_hieu_luc', v_current.ngay_hieu_luc,
      'ngay_het_hieu_luc', v_current.ngay_het_hieu_luc,
      'nguoi_ky', v_current.nguoi_ky,
      'chuc_vu_nguoi_ky', v_current.chuc_vu_nguoi_ky,
      'trang_thai', v_current.trang_thai,
      'ghi_chu', v_current.ghi_chu
    ),
    COALESCE(p_ly_do, 'Draft decision deleted'),
    v_user_id
  );

  -- Delete the decision (cascade will delete chi_tiet_dinh_muc)
  DELETE FROM public.quyet_dinh_dinh_muc WHERE id = p_id;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_id', p_id,
    'so_quyet_dinh', v_current.so_quyet_dinh
  );
END;
$$;


