Returns JSONB with {data, total, page, pageSize} structure.
Tenant isolation: global/admin can filter by tenant, others see only their tenant.';


--
-- Name: dinh_muc_quyet_dinh_update(bigint, text, date, date, date, text, text, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_quyet_dinh_update(p_id bigint, p_so_quyet_dinh text DEFAULT NULL::text, p_ngay_ban_hanh date DEFAULT NULL::date, p_ngay_hieu_luc date DEFAULT NULL::date, p_ngay_het_hieu_luc date DEFAULT NULL::date, p_nguoi_ky text DEFAULT NULL::text, p_chuc_vu_nguoi_ky text DEFAULT NULL::text, p_ghi_chu text DEFAULT NULL::text, p_thay_the_cho_id bigint DEFAULT NULL::bigint, p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := public._get_jwt_user_id();
  v_effective_donvi BIGINT := NULL;
  v_current RECORD;
  v_snapshot_truoc JSONB;
  v_result JSONB;
BEGIN
  -- Permission check
  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authenticated user_id claim is required';
  END IF;

  -- Tenant isolation
  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi; -- NULL means all tenants for global/admin only
  ELSE
    v_effective_donvi := v_claim_donvi;
    -- SECURITY: Non-global/admin roles MUST have a tenant - fail closed if missing
    IF v_effective_donvi IS NULL THEN
      RAISE EXCEPTION 'Access denied: tenant context required';
    END IF;
  END IF;

  -- Lock row during validation to prevent status races with activate/delete RPCs.
  SELECT * INTO v_current
  FROM public.quyet_dinh_dinh_muc
  WHERE id = p_id
    AND (v_effective_donvi IS NULL OR don_vi_id = v_effective_donvi)
  FOR UPDATE;

  IF v_current IS NULL THEN
    RAISE EXCEPTION 'Quota decision not found or access denied (id=%)', p_id;
  END IF;

  -- Only draft decisions can be updated
  IF v_current.trang_thai != 'draft' THEN
    RAISE EXCEPTION 'Only draft decisions can be updated. Current status: %', v_current.trang_thai;
  END IF;

  -- Create snapshot before update
  v_snapshot_truoc := jsonb_build_object(
    'so_quyet_dinh', v_current.so_quyet_dinh,
    'ngay_ban_hanh', v_current.ngay_ban_hanh,
    'ngay_hieu_luc', v_current.ngay_hieu_luc,
    'ngay_het_hieu_luc', v_current.ngay_het_hieu_luc,
    'nguoi_ky', v_current.nguoi_ky,
    'chuc_vu_nguoi_ky', v_current.chuc_vu_nguoi_ky,
    'ghi_chu', v_current.ghi_chu,
    'thay_the_cho_id', v_current.thay_the_cho_id
  );

  -- Update decision
  UPDATE public.quyet_dinh_dinh_muc SET
    so_quyet_dinh = COALESCE(NULLIF(trim(p_so_quyet_dinh), ''), so_quyet_dinh),
    ngay_ban_hanh = COALESCE(p_ngay_ban_hanh, ngay_ban_hanh),
    ngay_hieu_luc = COALESCE(p_ngay_hieu_luc, ngay_hieu_luc),
    ngay_het_hieu_luc = COALESCE(p_ngay_het_hieu_luc, ngay_het_hieu_luc),
    nguoi_ky = COALESCE(NULLIF(trim(p_nguoi_ky), ''), nguoi_ky),
    chuc_vu_nguoi_ky = COALESCE(NULLIF(trim(p_chuc_vu_nguoi_ky), ''), chuc_vu_nguoi_ky),
    ghi_chu = CASE WHEN p_ghi_chu IS NOT NULL THEN p_ghi_chu ELSE ghi_chu END,
    thay_the_cho_id = CASE WHEN p_thay_the_cho_id IS NOT NULL THEN p_thay_the_cho_id ELSE thay_the_cho_id END,
    updated_at = NOW(),
    updated_by = v_user_id
  WHERE id = p_id;

  -- Get updated decision for snapshot_sau
  v_result := public.dinh_muc_quyet_dinh_get(p_id, v_effective_donvi);

  -- Write audit log
  INSERT INTO public.lich_su_dinh_muc (
    quyet_dinh_id,
    don_vi_id,
    thao_tac,
    snapshot_truoc,
    snapshot_sau,
    thuc_hien_boi
  ) VALUES (
    p_id,
    v_current.don_vi_id,
    'cap_nhat',
    v_snapshot_truoc,
    jsonb_build_object(
      'so_quyet_dinh', COALESCE(NULLIF(trim(p_so_quyet_dinh), ''), v_current.so_quyet_dinh),
      'ngay_ban_hanh', COALESCE(p_ngay_ban_hanh, v_current.ngay_ban_hanh),
      'ngay_hieu_luc', COALESCE(p_ngay_hieu_luc, v_current.ngay_hieu_luc),
      'ngay_het_hieu_luc', COALESCE(p_ngay_het_hieu_luc, v_current.ngay_het_hieu_luc),
      'nguoi_ky', COALESCE(NULLIF(trim(p_nguoi_ky), ''), v_current.nguoi_ky),
      'chuc_vu_nguoi_ky', COALESCE(NULLIF(trim(p_chuc_vu_nguoi_ky), ''), v_current.chuc_vu_nguoi_ky),
      'ghi_chu', CASE WHEN p_ghi_chu IS NOT NULL THEN p_ghi_chu ELSE v_current.ghi_chu END,
      'thay_the_cho_id', CASE WHEN p_thay_the_cho_id IS NOT NULL THEN p_thay_the_cho_id ELSE v_current.thay_the_cho_id END
    ),
    v_user_id
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.dinh_muc_quyet_dinh_update(p_id bigint, p_so_quyet_dinh text, p_ngay_ban_hanh date, p_ngay_hieu_luc date, p_ngay_het_hieu_luc date, p_nguoi_ky text, p_chuc_vu_nguoi_ky text, p_ghi_chu text, p_thay_the_cho_id bigint, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_quyet_dinh_update(p_id bigint, p_so_quyet_dinh text, p_ngay_ban_hanh date, p_ngay_hieu_luc date, p_ngay_het_hieu_luc date, p_nguoi_ky text, p_chuc_vu_nguoi_ky text, p_ghi_chu text, p_thay_the_cho_id bigint, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_quyet_dinh_update(p_id bigint, p_so_quyet_dinh text, p_ngay_ban_hanh date, p_ngay_hieu_luc date, p_ngay_het_hieu_luc date, p_nguoi_ky text, p_chuc_vu_nguoi_ky text, p_ghi_chu text, p_thay_the_cho_id bigint, p_don_vi bigint) IS 'Update a draft quota decision. Active/inactive decisions cannot be updated.
Roles: global, admin, to_qltb only.
Audit: Creates lich_su_dinh_muc record with thao_tac=cap_nhat and before/after snapshots.';


--
-- Name: dinh_muc_thiet_bi_by_ids(bigint[], bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_thiet_bi_by_ids(p_thiet_bi_ids bigint[], p_don_vi bigint DEFAULT NULL::bigint) RETURNS TABLE(id bigint, ma_thiet_bi text, ten_thiet_bi text, model text, serial text, hang_san_xuat text, khoa_phong_quan_ly text, tinh_trang text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role  TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_user_id TEXT := current_setting('request.jwt.claims', true)::json->>'user_id';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_allowed_facilities BIGINT[];
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL OR v_user_id = '' THEN
    RAISE EXCEPTION 'Missing user_id claim' USING errcode = '42501';
  END IF;

  IF v_role NOT IN ('global', 'admin') AND (v_don_vi IS NULL OR v_don_vi = '') THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING errcode = '42501';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    NULL;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed_facilities := public.allowed_don_vi_for_session();
    IF p_don_vi IS NULL OR NOT (p_don_vi = ANY(v_allowed_facilities)) THEN
      RAISE EXCEPTION 'Access denied: facility % is not in your region', p_don_vi;
    END IF;
  ELSE
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
    IF p_don_vi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim' USING errcode = '42501';
    END IF;
  END IF;

  IF p_don_vi IS NULL THEN
    RETURN;
  END IF;

  IF p_thiet_bi_ids IS NULL OR array_length(p_thiet_bi_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    tb.id,
    tb.ma_thiet_bi,
    tb.ten_thiet_bi,
    tb.model,
    tb.serial,
    tb.hang_san_xuat,
    tb.khoa_phong_quan_ly,
    tb.tinh_trang_hien_tai AS tinh_trang
  FROM public.thiet_bi tb
  WHERE tb.id = ANY(p_thiet_bi_ids)
    AND (p_don_vi IS NULL OR tb.don_vi = p_don_vi)
  ORDER BY tb.ten_thiet_bi, tb.ma_thiet_bi;
END;
$$;


ALTER FUNCTION public.dinh_muc_thiet_bi_by_ids(p_thiet_bi_ids bigint[], p_don_vi bigint) OWNER TO postgres;

--
-- Name: dinh_muc_thiet_bi_by_nhom(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_thiet_bi_by_nhom(p_nhom_id bigint, p_don_vi bigint DEFAULT NULL::bigint) RETURNS TABLE(id bigint, ma_thiet_bi text, ten_thiet_bi text, model text, serial text, hang_san_xuat text, khoa_phong_quan_ly text, tinh_trang text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_user_id TEXT := NULLIF(current_setting('request.jwt.claims', true)::json->>'user_id', '');
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_category_don_vi BIGINT;
  v_allowed_facilities BIGINT[];
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING errcode = '42501';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    NULL;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed_facilities := public.allowed_don_vi_for_session();
    IF p_don_vi IS NULL OR NOT (p_don_vi = ANY(v_allowed_facilities)) THEN
      RAISE EXCEPTION 'Access denied: facility % is not in your region', p_don_vi
        USING errcode = '42501';
    END IF;
  ELSE
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
    IF p_don_vi IS NULL THEN
      RAISE EXCEPTION 'Missing facility claim' USING errcode = '42501';
    END IF;
  END IF;

  IF p_nhom_id IS NULL THEN
    RAISE EXCEPTION 'Category ID (p_nhom_id) is required.';
  END IF;

  SELECT ntb.don_vi_id
  INTO v_category_don_vi
  FROM public.nhom_thiet_bi ntb
  WHERE ntb.id = p_nhom_id;

  IF v_category_don_vi IS NULL THEN
    RETURN;
  END IF;

  IF p_don_vi IS NOT NULL AND v_category_don_vi != p_don_vi THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    tb.id,
    tb.ma_thiet_bi,
    tb.ten_thiet_bi,
    tb.model,
    tb.serial,
    tb.hang_san_xuat,
    tb.khoa_phong_quan_ly,
    tb.tinh_trang_hien_tai AS tinh_trang
  FROM public.thiet_bi tb
  WHERE tb.nhom_thiet_bi_id = p_nhom_id
    AND tb.don_vi = v_category_don_vi
  ORDER BY tb.ten_thiet_bi, tb.ma_thiet_bi;
END;
$$;


ALTER FUNCTION public.dinh_muc_thiet_bi_by_nhom(p_nhom_id bigint, p_don_vi bigint) OWNER TO postgres;

