--
-- Name: FUNCTION dinh_muc_thiet_bi_link(p_thiet_bi_ids bigint[], p_nhom_id bigint, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_thiet_bi_link(p_thiet_bi_ids bigint[], p_nhom_id bigint, p_don_vi bigint) IS 'Bulk link equipment to a category for quota tracking.
   Validates tenant ownership, updates equipment, and writes audit log.
   Returns count of equipment successfully linked.';


--
-- Name: dinh_muc_thiet_bi_link_batch(jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_thiet_bi_link_batch(p_mappings jsonb, p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_user_id TEXT := current_setting('request.jwt.claims', true)::json->>'user_id';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_mapping JSONB;
  v_nhom_id BIGINT;
  v_group_device_ids BIGINT[];
  v_category_don_vi BIGINT;
  v_valid_ids BIGINT[];
  v_group_affected INT;
  v_group_skipped_assigned INT;
  v_group_skipped_not_found INT;
  v_total_affected INT := 0;
  v_total_skipped_assigned INT := 0;
  v_total_skipped_not_found INT := 0;
  v_groups_detail JSONB := '[]'::JSONB;
  v_duplicate_ids BIGINT[];
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING errcode = '42501';
  END IF;
  IF v_user_id IS NULL OR v_user_id = '' THEN
    RAISE EXCEPTION 'Missing user_id claim' USING errcode = '42501';
  END IF;
  IF v_role NOT IN ('global', 'admin') AND (v_don_vi IS NULL OR v_don_vi = '') THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING errcode = '42501';
  END IF;
  IF v_role = 'regional_leader' THEN
    RAISE EXCEPTION 'Insufficient permissions: regional_leader cannot save mappings' USING errcode = '42501';
  END IF;
  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role.' USING errcode = '42501';
  END IF;
  IF v_role NOT IN ('global', 'admin') THEN
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;
  IF p_don_vi IS NULL THEN
    RAISE EXCEPTION 'Tenant ID (p_don_vi) is required.' USING errcode = '42501';
  END IF;
  IF p_mappings IS NULL OR jsonb_typeof(p_mappings) != 'array' OR jsonb_array_length(p_mappings) = 0 THEN
    RAISE EXCEPTION 'p_mappings must be a non-empty JSON array.';
  END IF;
  SELECT ARRAY_AGG(did) INTO v_duplicate_ids
  FROM (
    SELECT (elem.val)::TEXT::BIGINT AS did
    FROM jsonb_array_elements(p_mappings) AS m,
         LATERAL jsonb_array_elements(m->'thiet_bi_ids') AS elem(val)
    GROUP BY (elem.val)::TEXT
    HAVING COUNT(*) > 1
  ) dups(did);
  IF v_duplicate_ids IS NOT NULL AND array_length(v_duplicate_ids, 1) > 0 THEN
    RAISE EXCEPTION 'Duplicate device_id(s) found across groups: %', v_duplicate_ids;
  END IF;
  FOR v_mapping IN SELECT * FROM jsonb_array_elements(p_mappings)
  LOOP
    v_nhom_id := (v_mapping->>'nhom_id')::BIGINT;
    SELECT ARRAY_AGG(val::TEXT::BIGINT) INTO v_group_device_ids
    FROM jsonb_array_elements(v_mapping->'thiet_bi_ids') AS val;
    IF v_nhom_id IS NULL THEN
      RAISE EXCEPTION 'Each mapping must have a nhom_id.';
    END IF;
    IF v_group_device_ids IS NULL OR array_length(v_group_device_ids, 1) IS NULL THEN
      RAISE EXCEPTION 'Each mapping must have a non-empty thiet_bi_ids array.';
    END IF;
    SELECT don_vi_id INTO v_category_don_vi FROM public.nhom_thiet_bi WHERE id = v_nhom_id;
    IF v_category_don_vi IS NULL THEN
      RAISE EXCEPTION 'Category not found (ID: %).', v_nhom_id;
    END IF;
    IF v_category_don_vi != p_don_vi THEN
      RAISE EXCEPTION 'Category (ID: %) belongs to different tenant.', v_nhom_id;
    END IF;
    SELECT ARRAY_AGG(tb.id) INTO v_valid_ids
    FROM public.thiet_bi tb
    WHERE tb.id = ANY(v_group_device_ids)
      AND tb.don_vi = p_don_vi
      AND tb.nhom_thiet_bi_id IS NULL
    FOR UPDATE SKIP LOCKED;
    v_group_affected := COALESCE(array_length(v_valid_ids, 1), 0);
    SELECT COUNT(*)::INT INTO v_group_skipped_assigned
    FROM public.thiet_bi tb
    WHERE tb.id = ANY(v_group_device_ids)
      AND tb.don_vi = p_don_vi
      AND (
        tb.nhom_thiet_bi_id IS NOT NULL
        OR NOT (tb.id = ANY(COALESCE(v_valid_ids, '{}'::BIGINT[])))
      );
    v_group_skipped_not_found := array_length(v_group_device_ids, 1)
      - v_group_affected
      - v_group_skipped_assigned;
    IF v_group_affected > 0 THEN
      UPDATE public.thiet_bi SET nhom_thiet_bi_id = v_nhom_id WHERE id = ANY(v_valid_ids);
      INSERT INTO public.thiet_bi_nhom_audit_log (
        don_vi_id, thiet_bi_ids, nhom_thiet_bi_id,
        action, performed_by, performed_at, metadata
      ) VALUES (
        p_don_vi, v_valid_ids, v_nhom_id,
        'link_batch', NULLIF(v_user_id, '')::BIGINT, NOW(),
        jsonb_build_object(
          'source', 'suggested_mapping',
          'requested_ids', to_jsonb(v_group_device_ids),
          'linked_ids', to_jsonb(v_valid_ids)
        )
      );
    END IF;
    v_total_affected := v_total_affected + v_group_affected;
    v_total_skipped_assigned := v_total_skipped_assigned + v_group_skipped_assigned;
    v_total_skipped_not_found := v_total_skipped_not_found + v_group_skipped_not_found;
    v_groups_detail := v_groups_detail || jsonb_build_object(
      'nhom_id', v_nhom_id,
      'affected', v_group_affected,
      'skipped', (array_length(v_group_device_ids, 1) - v_group_affected)
    );
  END LOOP;
  RETURN jsonb_build_object(
    'affected_count', v_total_affected,
    'skipped_already_assigned', v_total_skipped_assigned,
    'skipped_not_found', v_total_skipped_not_found,
    'groups', v_groups_detail
  );
END;
$$;


ALTER FUNCTION public.dinh_muc_thiet_bi_link_batch(p_mappings jsonb, p_don_vi bigint) OWNER TO postgres;

--
-- Name: dinh_muc_thiet_bi_unassigned(bigint, text, integer, integer, text[], text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_thiet_bi_unassigned(p_don_vi bigint DEFAULT NULL::bigint, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_khoa_phong_array text[] DEFAULT NULL::text[], p_nguoi_su_dung_array text[] DEFAULT NULL::text[], p_vi_tri_lap_dat_array text[] DEFAULT NULL::text[], p_nguon_kinh_phi_array text[] DEFAULT NULL::text[]) RETURNS TABLE(id bigint, ma_thiet_bi text, ten_thiet_bi text, model text, serial text, hang_san_xuat text, khoa_phong_quan_ly text, tinh_trang text, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_user_id TEXT := current_setting('request.jwt.claims', true)::json->>'user_id';
  v_sanitized_search TEXT;
  v_total BIGINT;
  v_allowed_facilities BIGINT[];
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING errcode = '42501';
  END IF;

  IF v_role NOT IN ('global', 'admin') AND (v_don_vi IS NULL OR v_don_vi = '') THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING errcode = '42501';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    NULL;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed_facilities := public.allowed_don_vi_for_session();
    IF p_don_vi IS NULL OR NOT (p_don_vi = ANY(v_allowed_facilities)) THEN
      RAISE EXCEPTION 'Access denied: facility % is not in your region', p_don_vi;
    END IF;
  ELSE
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;

  IF p_don_vi IS NULL THEN
    RETURN;
  END IF;

  IF p_limit IS NULL OR p_limit < 1 THEN
    p_limit := 50;
  END IF;
  IF p_limit > 500 THEN
    p_limit := 500;
  END IF;
  IF p_offset IS NULL OR p_offset < 0 THEN
    p_offset := 0;
  END IF;

  v_sanitized_search := public._sanitize_ilike_pattern(LOWER(TRIM(p_search)));

  SELECT COUNT(*) INTO v_total
  FROM public.thiet_bi tb
  WHERE tb.don_vi = p_don_vi
    AND tb.nhom_thiet_bi_id IS NULL
    AND (
      v_sanitized_search IS NULL
      OR LOWER(COALESCE(tb.ten_thiet_bi, '')) LIKE '%' || v_sanitized_search || '%'
      OR LOWER(COALESCE(tb.ma_thiet_bi, '')) LIKE '%' || v_sanitized_search || '%'
      OR LOWER(COALESCE(tb.model, '')) LIKE '%' || v_sanitized_search || '%'
      OR LOWER(COALESCE(tb.serial, '')) LIKE '%' || v_sanitized_search || '%'
      OR LOWER(COALESCE(tb.so_luu_hanh, '')) LIKE '%' || v_sanitized_search || '%'
    )
    AND (p_khoa_phong_array IS NULL OR cardinality(p_khoa_phong_array) = 0 OR tb.khoa_phong_quan_ly = ANY(p_khoa_phong_array))
    AND (p_nguoi_su_dung_array IS NULL OR cardinality(p_nguoi_su_dung_array) = 0 OR tb.nguoi_dang_truc_tiep_quan_ly = ANY(p_nguoi_su_dung_array))
    AND (p_vi_tri_lap_dat_array IS NULL OR cardinality(p_vi_tri_lap_dat_array) = 0 OR tb.vi_tri_lap_dat = ANY(p_vi_tri_lap_dat_array))
    AND (p_nguon_kinh_phi_array IS NULL OR cardinality(p_nguon_kinh_phi_array) = 0 OR tb.nguon_kinh_phi = ANY(p_nguon_kinh_phi_array));

  RETURN QUERY
  SELECT
    tb.id,
    tb.ma_thiet_bi,
    tb.ten_thiet_bi,
    tb.model,
    tb.serial,
    tb.hang_san_xuat,
    tb.khoa_phong_quan_ly,
    tb.tinh_trang_hien_tai AS tinh_trang,
    v_total AS total_count
  FROM public.thiet_bi tb
  WHERE tb.don_vi = p_don_vi
    AND tb.nhom_thiet_bi_id IS NULL
    AND (
      v_sanitized_search IS NULL
      OR LOWER(COALESCE(tb.ten_thiet_bi, '')) LIKE '%' || v_sanitized_search || '%'
      OR LOWER(COALESCE(tb.ma_thiet_bi, '')) LIKE '%' || v_sanitized_search || '%'
      OR LOWER(COALESCE(tb.model, '')) LIKE '%' || v_sanitized_search || '%'
      OR LOWER(COALESCE(tb.serial, '')) LIKE '%' || v_sanitized_search || '%'
      OR LOWER(COALESCE(tb.so_luu_hanh, '')) LIKE '%' || v_sanitized_search || '%'
    )
    AND (p_khoa_phong_array IS NULL OR cardinality(p_khoa_phong_array) = 0 OR tb.khoa_phong_quan_ly = ANY(p_khoa_phong_array))
    AND (p_nguoi_su_dung_array IS NULL OR cardinality(p_nguoi_su_dung_array) = 0 OR tb.nguoi_dang_truc_tiep_quan_ly = ANY(p_nguoi_su_dung_array))
    AND (p_vi_tri_lap_dat_array IS NULL OR cardinality(p_vi_tri_lap_dat_array) = 0 OR tb.vi_tri_lap_dat = ANY(p_vi_tri_lap_dat_array))
    AND (p_nguon_kinh_phi_array IS NULL OR cardinality(p_nguon_kinh_phi_array) = 0 OR tb.nguon_kinh_phi = ANY(p_nguon_kinh_phi_array))
  ORDER BY tb.ten_thiet_bi, tb.ma_thiet_bi
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.dinh_muc_thiet_bi_unassigned(p_don_vi bigint, p_search text, p_limit integer, p_offset integer, p_khoa_phong_array text[], p_nguoi_su_dung_array text[], p_vi_tri_lap_dat_array text[], p_nguon_kinh_phi_array text[]) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_thiet_bi_unassigned(p_don_vi bigint, p_search text, p_limit integer, p_offset integer, p_khoa_phong_array text[], p_nguoi_su_dung_array text[], p_vi_tri_lap_dat_array text[], p_nguon_kinh_phi_array text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_thiet_bi_unassigned(p_don_vi bigint, p_search text, p_limit integer, p_offset integer, p_khoa_phong_array text[], p_nguoi_su_dung_array text[], p_vi_tri_lap_dat_array text[], p_nguon_kinh_phi_array text[]) IS 'List unassigned equipment (not linked to any category) with search, pagination, and faceted filters';


--
-- Name: dinh_muc_thiet_bi_unassigned_filter_options(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_thiet_bi_unassigned_filter_options(p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_user_id TEXT := current_setting('request.jwt.claims', true)::json->>'user_id';
  v_allowed_facilities BIGINT[];
  v_result JSONB;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING errcode = '42501';
  END IF;

  IF v_role NOT IN ('global', 'admin') AND (v_don_vi IS NULL OR v_don_vi = '') THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING errcode = '42501';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    NULL;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed_facilities := public.allowed_don_vi_for_session();
    IF p_don_vi IS NULL OR NOT (p_don_vi = ANY(v_allowed_facilities)) THEN
      RAISE EXCEPTION 'Access denied: facility % is not in your region', p_don_vi;
    END IF;
  ELSE
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;

  IF p_don_vi IS NULL THEN
    v_result := '{"departments":[],"users":[],"locations":[],"fundingSources":[]}'::JSONB;
    RETURN v_result;
  END IF;

  SELECT jsonb_build_object(
    'departments', COALESCE((
      SELECT jsonb_agg(DISTINCT tb.khoa_phong_quan_ly ORDER BY tb.khoa_phong_quan_ly)
      FROM public.thiet_bi tb
      WHERE tb.don_vi = p_don_vi
        AND tb.nhom_thiet_bi_id IS NULL
        AND tb.khoa_phong_quan_ly IS NOT NULL
        AND tb.khoa_phong_quan_ly != ''
    ), '[]'::JSONB),
    'users', COALESCE((
      SELECT jsonb_agg(DISTINCT tb.nguoi_dang_truc_tiep_quan_ly ORDER BY tb.nguoi_dang_truc_tiep_quan_ly)
      FROM public.thiet_bi tb
      WHERE tb.don_vi = p_don_vi
        AND tb.nhom_thiet_bi_id IS NULL
        AND tb.nguoi_dang_truc_tiep_quan_ly IS NOT NULL
        AND tb.nguoi_dang_truc_tiep_quan_ly != ''
    ), '[]'::JSONB),
    'locations', COALESCE((
      SELECT jsonb_agg(DISTINCT tb.vi_tri_lap_dat ORDER BY tb.vi_tri_lap_dat)
      FROM public.thiet_bi tb
      WHERE tb.don_vi = p_don_vi
        AND tb.nhom_thiet_bi_id IS NULL
        AND tb.vi_tri_lap_dat IS NOT NULL
        AND tb.vi_tri_lap_dat != ''
    ), '[]'::JSONB),
    'fundingSources', COALESCE((
      SELECT jsonb_agg(DISTINCT tb.nguon_kinh_phi ORDER BY tb.nguon_kinh_phi)
      FROM public.thiet_bi tb
      WHERE tb.don_vi = p_don_vi
        AND tb.nhom_thiet_bi_id IS NULL
        AND tb.nguon_kinh_phi IS NOT NULL
        AND tb.nguon_kinh_phi != ''
    ), '[]'::JSONB)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


