--
-- Name: dinh_muc_thiet_bi_unassigned_names(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_thiet_bi_unassigned_names(p_don_vi bigint DEFAULT NULL::bigint) RETURNS TABLE(ten_thiet_bi text, device_count bigint, device_ids bigint[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_user_id TEXT := current_setting('request.jwt.claims', true)::json->>'user_id';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_allowed_facilities BIGINT[];
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL OR v_user_id = '' THEN
    RAISE EXCEPTION 'Missing user_id claim' USING errcode = '42501';
  END IF;

  IF v_role NOT IN ('global', 'admin') AND (v_don_vi IS NULL OR v_don_vi = '') THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING errcode = '42501';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    NULL;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed_facilities := public.allowed_don_vi_for_session();
    IF p_don_vi IS NULL OR NOT (p_don_vi = ANY(v_allowed_facilities)) THEN
      RAISE EXCEPTION 'Access denied: facility % is not in your region', p_don_vi;
    END IF;
  ELSE
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;

  IF p_don_vi IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    BTRIM(tb.ten_thiet_bi) AS ten_thiet_bi,
    COUNT(*)::BIGINT AS device_count,
    ARRAY_AGG(tb.id ORDER BY tb.id) AS device_ids
  FROM public.thiet_bi tb
  WHERE tb.don_vi = p_don_vi
    AND tb.nhom_thiet_bi_id IS NULL
    AND NULLIF(BTRIM(tb.ten_thiet_bi), '') IS NOT NULL
  GROUP BY BTRIM(tb.ten_thiet_bi)
  ORDER BY COUNT(*) DESC, BTRIM(tb.ten_thiet_bi);
END;
$$;


ALTER FUNCTION public.dinh_muc_thiet_bi_unassigned_names(p_don_vi bigint) OWNER TO postgres;

--
-- Name: dinh_muc_thiet_bi_unlink(bigint[], bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_thiet_bi_unlink(p_thiet_bi_ids bigint[], p_nhom_id bigint, p_don_vi bigint DEFAULT NULL::bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := current_setting('request.jwt.claims', true)::json->>'app_role';
  v_don_vi TEXT := current_setting('request.jwt.claims', true)::json->>'don_vi';
  v_user_id TEXT := NULLIF(current_setting('request.jwt.claims', true)::json->>'user_id', '');
  v_affected_count INT := 0;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    v_role := current_setting('request.jwt.claims', true)::json->>'role';
  END IF;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING errcode = '42501';
  END IF;

  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions for category unlink'
      USING errcode = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = 'to_qltb' THEN
    p_don_vi := NULLIF(v_don_vi, '')::BIGINT;
  END IF;

  IF p_don_vi IS NULL THEN
    RAISE EXCEPTION 'Tenant ID is required' USING errcode = '42501';
  END IF;

  IF p_thiet_bi_ids IS NULL OR array_length(p_thiet_bi_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'p_thiet_bi_ids cannot be empty'
      USING errcode = '22023';
  END IF;

  IF p_nhom_id IS NULL THEN
    RAISE EXCEPTION 'Category ID is required' USING errcode = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.nhom_thiet_bi AS category
    WHERE category.id = p_nhom_id
      AND category.don_vi_id = p_don_vi
    FOR SHARE
  ) THEN
    RAISE EXCEPTION 'Category is outside the tenant scope'
      USING errcode = '42501';
  END IF;

  WITH affected_equipment AS (
    UPDATE public.thiet_bi
    SET nhom_thiet_bi_id = NULL
    WHERE id = ANY(p_thiet_bi_ids)
      AND don_vi = p_don_vi
      AND nhom_thiet_bi_id = p_nhom_id
    RETURNING id
  ),
  inserted_audit AS (
    INSERT INTO public.thiet_bi_nhom_audit_log (
      don_vi_id,
      thiet_bi_ids,
      nhom_thiet_bi_id,
      action,
      performed_by,
      performed_at,
      metadata
    )
    SELECT
      p_don_vi,
      ARRAY_AGG(id),
      p_nhom_id,
      'unlink',
      v_user_id::BIGINT,
      NOW(),
      jsonb_build_object('previous_nhom_id', p_nhom_id)
    FROM affected_equipment
    HAVING COUNT(*) > 0
    RETURNING id
  )
  SELECT COUNT(*)::INT
  INTO v_affected_count
  FROM affected_equipment;

  RETURN v_affected_count;
END;
$$;


ALTER FUNCTION public.dinh_muc_thiet_bi_unlink(p_thiet_bi_ids bigint[], p_nhom_id bigint, p_don_vi bigint) OWNER TO postgres;

--
-- Name: dinh_muc_unified_import(jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dinh_muc_unified_import(p_items jsonb, p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), ''));
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := public._get_jwt_user_id();
  v_effective_donvi BIGINT := NULL;
  v_decision_id BIGINT;
  v_so_quyet_dinh TEXT;
  v_bulk_result JSONB;
BEGIN
  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Insufficient permissions. Required: global, admin, or to_qltb role';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi;
  ELSE
    IF v_claim_donvi IS NULL THEN
      RAISE EXCEPTION 'Access denied: tenant claim (don_vi) is required for non-global users';
    END IF;
    v_effective_donvi := v_claim_donvi;
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'p_items must be a non-empty JSON array';
  END IF;

  IF v_effective_donvi IS NULL THEN
    RAISE EXCEPTION 'Tenant ID (don_vi) is required';
  END IF;

  -- Auto-generate decision number with collision-resistant suffix
  v_so_quyet_dinh := format('AUTO-%s-%s', to_char(clock_timestamp(), 'YYYYMMDD-HH24MISS-US'), txid_current());

  -- Create draft decision (placeholder signer fields — user updates before activating)
  INSERT INTO public.quyet_dinh_dinh_muc (
    so_quyet_dinh,
    don_vi_id,
    trang_thai,
    ngay_ban_hanh,
    ngay_hieu_luc,
    nguoi_ky,
    chuc_vu_nguoi_ky,
    created_by
  ) VALUES (
    v_so_quyet_dinh,
    v_effective_donvi,
    'draft',
    CURRENT_DATE,
    CURRENT_DATE,
    '(Nhập tự động)',
    '(Cập nhật sau)',
    v_user_id
  )
  RETURNING id INTO v_decision_id;

  -- Audit log for decision creation
  INSERT INTO public.lich_su_dinh_muc (
    quyet_dinh_id,
    don_vi_id,
    thao_tac,
    snapshot_sau,
    thuc_hien_boi
  ) VALUES (
    v_decision_id,
    v_effective_donvi,
    'tao',
    jsonb_build_object(
      'id', v_decision_id,
      'so_quyet_dinh', v_so_quyet_dinh,
      'trang_thai', 'draft',
      'source', 'unified_import'
    ),
    v_user_id
  );

  -- Delegate to existing bulk import (reuses all validation + UPSERT logic)
  v_bulk_result := public.dinh_muc_chi_tiet_bulk_import(
    p_quyet_dinh_id := v_decision_id,
    p_items := p_items,
    p_don_vi := v_effective_donvi
  );

  -- Return combined result
  RETURN jsonb_build_object(
    'success', v_bulk_result->'success',
    'decision_id', v_decision_id,
    'so_quyet_dinh', v_so_quyet_dinh,
    'inserted', v_bulk_result->'inserted',
    'updated', v_bulk_result->'updated',
    'failed', v_bulk_result->'failed',
    'total', v_bulk_result->'total',
    'details', v_bulk_result->'details'
  );
END;
$$;


ALTER FUNCTION public.dinh_muc_unified_import(p_items jsonb, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION dinh_muc_unified_import(p_items jsonb, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.dinh_muc_unified_import(p_items jsonb, p_don_vi bigint) IS 'Creates a draft quota decision and imports quota line items in one step.
Input: p_items [{ma_nhom, so_luong_dinh_muc, so_luong_toi_thieu?, ghi_chu?}]
Returns: {success, decision_id, so_quyet_dinh, inserted, updated, failed, total, details}.';


--
-- Name: don_vi_branding_get(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.don_vi_branding_get(p_id bigint DEFAULT NULL::bigint) RETURNS TABLE(id bigint, name text, logo_url text, print_location text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_role text;
  v_role_fallback text;
  v_claim_don_vi bigint;
  v_effective_id bigint;
BEGIN
  v_role := lower(coalesce(public._get_jwt_claim('app_role')::text, ''));
  v_role_fallback := lower(coalesce(public._get_jwt_claim('role')::text, ''));
  IF v_role = '' THEN
    v_role := v_role_fallback;
  END IF;

  v_claim_don_vi := NULLIF(public._get_jwt_claim('don_vi'), '')::bigint;

  -- The RPC proxy normalizes admin to global before signing the JWT.
  IF v_role = 'global' THEN
    v_effective_id := COALESCE(p_id, v_claim_don_vi);
  ELSE
    v_effective_id := v_claim_don_vi;
    IF v_effective_id IS NULL THEN
      RAISE EXCEPTION 'Thiếu thông tin đơn vị trong phiên đăng nhập'
        USING HINT = 'missing_don_vi_claim';
    END IF;
    IF p_id IS NOT NULL AND p_id <> v_effective_id THEN
      RAISE EXCEPTION 'Forbidden'
        USING HINT = 'tenant_mismatch';
    END IF;
  END IF;

  IF v_effective_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    d.id,
    d.name,
    d.logo_url,
    db.ten_dia_ban AS print_location
  FROM public.don_vi d
  LEFT JOIN public.dia_ban db ON db.id = d.dia_ban_id
  WHERE d.id = v_effective_id;
END;
$$;


ALTER FUNCTION public.don_vi_branding_get(p_id bigint) OWNER TO postgres;

--
-- Name: don_vi_create(text, text, boolean, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.don_vi_create(p_code text, p_name text, p_active boolean DEFAULT true, p_membership_quota integer DEFAULT NULL::integer, p_logo_url text DEFAULT NULL::text, p_google_drive_folder_url text DEFAULT NULL::text) RETURNS TABLE(id bigint, code text, name text, active boolean, membership_quota integer, logo_url text, google_drive_folder_url text, used_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE v_role text; v_new_id bigint;
BEGIN
  v_role := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  IF v_role = 'admin' THEN v_role := 'global'; END IF;
  IF v_role <> 'global' THEN
    RAISE EXCEPTION 'Forbidden' USING HINT = 'global_only';
  END IF;

  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Tên đơn vị không được trống' USING HINT = 'validation_error';
  END IF;
  IF p_code IS NOT NULL AND EXISTS(SELECT 1 FROM public.don_vi dv WHERE dv.code = p_code) THEN
    RAISE EXCEPTION 'Mã đơn vị đã tồn tại' USING HINT = 'code_unique';
  END IF;

  INSERT INTO public.don_vi(code, name, active, membership_quota, logo_url, google_drive_folder_url)
  VALUES (p_code, btrim(p_name), coalesce(p_active,true), p_membership_quota, p_logo_url, p_google_drive_folder_url)
  RETURNING public.don_vi.id INTO v_new_id;

  RETURN QUERY SELECT * FROM public.don_vi_get(v_new_id);
END;
$$;


ALTER FUNCTION public.don_vi_create(p_code text, p_name text, p_active boolean, p_membership_quota integer, p_logo_url text, p_google_drive_folder_url text) OWNER TO postgres;

--
-- Name: don_vi_get(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.don_vi_get(p_id bigint) RETURNS TABLE(id bigint, code text, name text, active boolean, membership_quota integer, logo_url text, google_drive_folder_url text, used_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE v_role text;
BEGIN
  v_role := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  IF v_role = 'admin' THEN v_role := 'global'; END IF;
  IF v_role <> 'global' THEN
    RAISE EXCEPTION 'Forbidden' USING HINT = 'global_only';
  END IF;

  RETURN QUERY
  SELECT d.id, d.code, d.name, d.active, d.membership_quota, d.logo_url, d.google_drive_folder_url, COALESCE(m.used_count,0) AS used_count
  FROM public.don_vi d
  LEFT JOIN (
    SELECT don_vi, COUNT(*)::int AS used_count
    FROM public.user_don_vi_memberships
    GROUP BY don_vi
  ) m ON m.don_vi = d.id
  WHERE d.id = p_id;
END;
$$;


ALTER FUNCTION public.don_vi_get(p_id bigint) OWNER TO postgres;

--
-- Name: don_vi_list(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.don_vi_list(p_q text DEFAULT NULL::text, p_sort text DEFAULT 'name'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20) RETURNS TABLE(id bigint, code text, name text, active boolean, membership_quota integer, logo_url text, used_count integer)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_role text;
  v_offset integer;
  v_order_by text;
  v_sql text;
BEGIN
  v_role := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  IF v_role = 'admin' THEN v_role := 'global'; END IF;
  IF v_role <> 'global' THEN
    RETURN; -- empty set for non-global
  END IF;

  v_offset := GREATEST((coalesce(p_page,1) - 1) * coalesce(p_page_size,20), 0);
  v_order_by := CASE lower(coalesce(p_sort,'name'))
    WHEN 'name' THEN 'name'
    WHEN 'code' THEN 'code'
    WHEN 'created_at' THEN 'created_at'
    WHEN 'active' THEN 'active'
    ELSE 'name'
  END;

  v_sql :=
    'WITH membership_counts AS (
       SELECT current_don_vi AS don_vi, COUNT(*)::int AS used_count
       FROM public.nhan_vien
       WHERE current_don_vi IS NOT NULL
       GROUP BY current_don_vi
     )
     SELECT d.id, d.code, d.name, d.active, d.membership_quota, d.logo_url, COALESCE(mc.used_count,0) AS used_count
     FROM public.don_vi d
     LEFT JOIN membership_counts mc ON mc.don_vi = d.id
     WHERE ($1 IS NULL OR $1 = '''' OR d.name ILIKE ''%''||$1||''%'' OR d.code ILIKE ''%''||$1||''%'')
     ' || format(' ORDER BY %I ', v_order_by) || 'LIMIT $2 OFFSET $3';

  RETURN QUERY EXECUTE v_sql USING p_q, p_page_size, v_offset;
END;
$_$;


ALTER FUNCTION public.don_vi_list(p_q text, p_sort text, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: don_vi_set_active(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.don_vi_set_active(p_id bigint, p_active boolean) RETURNS TABLE(id bigint, code text, name text, active boolean, membership_quota integer, logo_url text, used_count integer)
    LANGUAGE plpgsql
    AS $$
DECLARE v_role text;
BEGIN
  v_role := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  IF v_role = 'admin' THEN v_role := 'global'; END IF;
  IF v_role <> 'global' THEN
    RAISE EXCEPTION 'Forbidden' USING HINT = 'global_only';
  END IF;

  UPDATE public.don_vi AS dv
  SET active = COALESCE(p_active, dv.active)
  WHERE dv.id = p_id;

  RETURN QUERY SELECT * FROM public.don_vi_get(p_id);
END;
$$;


ALTER FUNCTION public.don_vi_set_active(p_id bigint, p_active boolean) OWNER TO postgres;

--
-- Name: don_vi_update(bigint, text, text, boolean, integer, text, text, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.don_vi_update(p_id bigint, p_code text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_active boolean DEFAULT NULL::boolean, p_membership_quota integer DEFAULT NULL::integer, p_logo_url text DEFAULT NULL::text, p_google_drive_folder_url text DEFAULT NULL::text, p_set_membership_quota boolean DEFAULT false, p_set_logo_url boolean DEFAULT false, p_set_google_drive_folder_url boolean DEFAULT false) RETURNS TABLE(id bigint, code text, name text, active boolean, membership_quota integer, logo_url text, google_drive_folder_url text, used_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE 
  v_role text; 
  v_existing public.don_vi%ROWTYPE;
BEGIN
  v_role := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  IF v_role = 'admin' THEN v_role := 'global'; END IF;
  IF v_role <> 'global' THEN
    RAISE EXCEPTION 'Forbidden' USING HINT = 'global_only';
  END IF;

  SELECT d.* INTO v_existing FROM public.don_vi d WHERE d.id = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Đơn vị không tồn tại' USING HINT = 'not_found';
  END IF;

  IF p_code IS NOT NULL AND p_code <> v_existing.code AND EXISTS(SELECT 1 FROM public.don_vi dv WHERE dv.code = p_code AND dv.id <> p_id) THEN
    RAISE EXCEPTION 'Mã đơn vị đã tồn tại' USING HINT = 'code_unique';
  END IF;

  UPDATE public.don_vi AS dv SET
    code = COALESCE(p_code, dv.code),
    name = COALESCE(NULLIF(btrim(p_name),''), dv.name),
    active = COALESCE(p_active, dv.active),
    membership_quota = CASE WHEN p_set_membership_quota THEN p_membership_quota ELSE dv.membership_quota END,
    logo_url = CASE WHEN p_set_logo_url THEN p_logo_url ELSE dv.logo_url END,
    google_drive_folder_url = CASE WHEN p_set_google_drive_folder_url THEN p_google_drive_folder_url ELSE dv.google_drive_folder_url END
  WHERE dv.id = p_id;

  RETURN QUERY SELECT * FROM public.don_vi_get(p_id);
END;
$$;


ALTER FUNCTION public.don_vi_update(p_id bigint, p_code text, p_name text, p_active boolean, p_membership_quota integer, p_logo_url text, p_google_drive_folder_url text, p_set_membership_quota boolean, p_set_logo_url boolean, p_set_google_drive_folder_url boolean) OWNER TO postgres;

--
-- Name: don_vi_user_hierarchy(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.don_vi_user_hierarchy(p_q text DEFAULT NULL::text, p_only_active boolean DEFAULT false) RETURNS TABLE(tenant_id bigint, tenant_code text, tenant_name text, tenant_active boolean, membership_quota integer, logo_url text, used_count integer, users jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_query text := NULLIF(btrim(coalesce(p_q, '')), '');
BEGIN
  v_role := lower(coalesce(public._get_jwt_claim('app_role'), ''));
  IF v_role <> 'global' THEN
    RAISE EXCEPTION 'Forbidden' USING HINT = 'global_only';
  END IF;

  RETURN QUERY
  SELECT
    d.id AS tenant_id,
    d.code AS tenant_code,
    d.name AS tenant_name,
    d.active AS tenant_active,
    d.membership_quota,
    d.logo_url,
    COALESCE(u.used_count, 0) AS used_count,
    COALESCE(user_list.users, '[]'::jsonb) AS users
  FROM public.don_vi d
  LEFT JOIN (
    SELECT current_don_vi AS don_vi, COUNT(*)::int AS used_count
    FROM public.nhan_vien
    WHERE current_don_vi IS NOT NULL
    GROUP BY current_don_vi
  ) u ON u.don_vi = d.id
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', nv.id,
        'username', nv.username,
        'full_name', nv.full_name,
        'role', lower(nv.role),
        'khoa_phong', nv.khoa_phong,
        'current_don_vi', nv.current_don_vi,
        'created_at', nv.created_at
      ) ORDER BY lower(nv.role), nv.full_name
    ) AS users
    FROM public.nhan_vien nv
    WHERE nv.current_don_vi = d.id
  ) user_list ON TRUE
  WHERE
    (NOT p_only_active OR COALESCE(d.active, TRUE) = TRUE)
    AND (
      v_query IS NULL
      OR d.name ILIKE '%' || v_query || '%'
      OR d.code ILIKE '%' || v_query || '%'
      OR EXISTS (
        SELECT 1
        FROM public.nhan_vien nv2
        WHERE nv2.current_don_vi = d.id
          AND (
            nv2.full_name ILIKE '%' || v_query || '%'
            OR nv2.username ILIKE '%' || v_query || '%'
          )
      )
    )
  ORDER BY d.name;
END;
$$;


ALTER FUNCTION public.don_vi_user_hierarchy(p_q text, p_only_active boolean) OWNER TO postgres;

--
-- Name: enforce_hashed_password(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_hashed_password() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NEW.password IS NOT NULL AND NEW.password <> 'hashed password' THEN
    NEW.hashed_password := extensions.crypt(NEW.password, extensions.gen_salt('bf', 12));
    NEW.password := 'hashed password';
  END IF;

  IF NEW.hashed_password IS NOT NULL AND (NEW.password IS NULL OR NEW.password <> 'hashed password') THEN
    NEW.password := 'hashed password';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_hashed_password() OWNER TO postgres;

--
-- Name: equipment_aggregate_search(text, text, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_aggregate_search(p_query text, p_group_by text DEFAULT 'region'::text, p_region_id bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id text := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_query text := NULLIF(BTRIM(COALESCE(p_query, '')), '');
  v_sanitized_query text;
  v_group_by text := COALESCE(lower(NULLIF(BTRIM(COALESCE(p_group_by, 'region')), '')), 'region');
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_allowed_facilities bigint[] := NULL;
  v_rows jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_scope_label text;
BEGIN
  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('global', 'regional_leader') THEN
    RAISE EXCEPTION 'Access denied for role %', v_role USING ERRCODE = '42501';
  END IF;

  IF v_query IS NULL THEN
    RAISE EXCEPTION 'Search query is required' USING ERRCODE = '22023';
  END IF;

  IF v_group_by NOT IN ('region', 'facility') THEN
    RAISE EXCEPTION 'Unsupported group_by %', p_group_by USING ERRCODE = '22023';
  END IF;

  v_sanitized_query := public._sanitize_ilike_pattern(v_query);
  IF v_sanitized_query IS NULL THEN
    RAISE EXCEPTION 'Search query is required' USING ERRCODE = '22023';
  END IF;

  IF v_role = 'regional_leader' THEN
    v_allowed_facilities := public.allowed_don_vi_for_session_safe();
    IF v_allowed_facilities IS NULL OR cardinality(v_allowed_facilities) = 0 THEN
      v_allowed_facilities := ARRAY[]::bigint[];
    END IF;
  END IF;

  IF v_role = 'global' THEN
    v_scope_label := CASE WHEN p_region_id IS NULL THEN 'Toàn hệ thống' ELSE 'Theo địa bàn' END;
  ELSE
    v_scope_label := 'Địa bàn phụ trách';
  END IF;

  WITH scoped_facilities AS (
    SELECT
      dv.id AS facility_id,
      dv.name AS facility_name,
      dv.dia_ban_id AS region_id,
      db.ten_dia_ban AS region_name
    FROM public.don_vi dv
    LEFT JOIN public.dia_ban db ON db.id = dv.dia_ban_id
    WHERE dv.active = true
      AND (v_role = 'global' OR dv.id = ANY(v_allowed_facilities))
      AND (p_region_id IS NULL OR dv.dia_ban_id = p_region_id)
  ),
  raw_matched_equipment AS (
    SELECT tb.id, tb.don_vi AS facility_id, tb.nhom_thiet_bi_id, sf.region_id, sf.region_name, sf.facility_name
    FROM scoped_facilities sf
    JOIN public.thiet_bi tb ON tb.don_vi = sf.facility_id
    WHERE tb.is_deleted = false
      AND (
        tb.ten_thiet_bi ILIKE ('%' || v_sanitized_query || '%')
        OR tb.model ILIKE ('%' || v_sanitized_query || '%')
        OR tb.serial ILIKE ('%' || v_sanitized_query || '%')
      )

    UNION ALL

    SELECT tb.id, tb.don_vi AS facility_id, tb.nhom_thiet_bi_id, sf.region_id, sf.region_name, sf.facility_name
    FROM scoped_facilities sf
    JOIN public.thiet_bi tb ON tb.don_vi = sf.facility_id
    JOIN public.nhom_thiet_bi ntb ON ntb.id = tb.nhom_thiet_bi_id AND ntb.don_vi_id = tb.don_vi
    WHERE tb.is_deleted = false
      AND (
        ntb.ten_nhom ILIKE ('%' || v_sanitized_query || '%')
        OR EXISTS (
          SELECT 1
          FROM unnest(COALESCE(ntb.tu_khoa, ARRAY[]::text[])) AS kw(keyword)
          WHERE kw.keyword ILIKE ('%' || v_sanitized_query || '%')
        )
      )
  ),
  matched_equipment AS (
    SELECT DISTINCT ON (id) id, facility_id, nhom_thiet_bi_id, region_id, region_name, facility_name
    FROM raw_matched_equipment
    ORDER BY id
  ),
  active_decisions AS (
    SELECT DISTINCT ON (qd.don_vi_id)
      qd.don_vi_id AS facility_id,
      qd.id AS decision_id
    FROM public.quyet_dinh_dinh_muc qd
    JOIN (SELECT DISTINCT facility_id FROM matched_equipment) mf ON mf.facility_id = qd.don_vi_id
    WHERE qd.trang_thai = 'active'
    ORDER BY qd.don_vi_id, qd.ngay_hieu_luc DESC NULLS LAST, qd.id DESC
  ),
  matched_groups AS (
    SELECT
      me.facility_id,
      me.nhom_thiet_bi_id,
      COUNT(*)::bigint AS matched_count
    FROM matched_equipment me
    GROUP BY me.facility_id, me.nhom_thiet_bi_id
  ),
  group_current_counts AS (
    SELECT
      mg.facility_id,
      mg.nhom_thiet_bi_id,
      COUNT(tb.id)::bigint AS current_count
    FROM matched_groups mg
    JOIN public.thiet_bi tb
      ON tb.don_vi = mg.facility_id
     AND tb.nhom_thiet_bi_id = mg.nhom_thiet_bi_id
     AND tb.is_deleted = false
    WHERE mg.nhom_thiet_bi_id IS NOT NULL
    GROUP BY mg.facility_id, mg.nhom_thiet_bi_id
  ),
  group_quota_status AS (
    SELECT
      mg.facility_id,
      mg.nhom_thiet_bi_id,
      mg.matched_count,
      ad.decision_id,
      cd.so_luong_toi_thieu,
      cd.so_luong_toi_da,
      COALESCE(gcc.current_count, 0)::bigint AS current_count,
      CASE
        WHEN ad.decision_id IS NULL THEN 'no_active_quota'
        WHEN mg.nhom_thiet_bi_id IS NULL THEN 'unassigned_category'
        WHEN cd.nhom_thiet_bi_id IS NULL THEN 'not_in_unit_quota'
        WHEN COALESCE(gcc.current_count, 0) < cd.so_luong_toi_thieu THEN 'below_minimum'
        WHEN COALESCE(gcc.current_count, 0) > cd.so_luong_toi_da THEN 'over_limit'
        ELSE 'within_limit'
      END AS quota_status
    FROM matched_groups mg
    LEFT JOIN active_decisions ad ON ad.facility_id = mg.facility_id
    LEFT JOIN public.chi_tiet_dinh_muc cd
      ON cd.quyet_dinh_id = ad.decision_id
     AND cd.nhom_thiet_bi_id = mg.nhom_thiet_bi_id
    LEFT JOIN group_current_counts gcc
      ON gcc.facility_id = mg.facility_id
     AND gcc.nhom_thiet_bi_id = mg.nhom_thiet_bi_id
  ),
  facility_quota AS (
    SELECT
      gqs.facility_id,
      CASE
        WHEN COUNT(DISTINCT gqs.quota_status) > 1 THEN 'mixed'
        ELSE MIN(gqs.quota_status)
      END AS quota_status,
      SUM(gqs.current_count) FILTER (WHERE gqs.so_luong_toi_da IS NOT NULL)::bigint AS quota_current_count,
      SUM(gqs.so_luong_toi_thieu) FILTER (WHERE gqs.so_luong_toi_thieu IS NOT NULL)::bigint AS quota_min_count,
      SUM(gqs.so_luong_toi_da) FILTER (WHERE gqs.so_luong_toi_da IS NOT NULL)::bigint AS quota_max_count,
      array_agg(DISTINCT gqs.quota_status ORDER BY gqs.quota_status) AS quota_notes
    FROM group_quota_status gqs
    GROUP BY gqs.facility_id
  ),
  region_rows AS (
    SELECT
      'region'::text AS group_type,
      me.region_id AS group_id,
      COALESCE(me.region_name, 'Chưa phân vùng') AS group_name,
      NULL::bigint AS parent_region_id,
      NULL::text AS parent_region_name,
      COUNT(me.id)::bigint AS equipment_count,
      COUNT(DISTINCT me.facility_id)::bigint AS facility_count,
      NULL::bigint AS quota_current_count,
      NULL::bigint AS quota_min_count,
      NULL::bigint AS quota_max_count,
      NULL::text AS quota_status,
      ARRAY[]::text[] AS quota_notes
    FROM matched_equipment me
    GROUP BY me.region_id, me.region_name
  ),
  facility_rows AS (
    SELECT
      'facility'::text AS group_type,
      me.facility_id AS group_id,
      me.facility_name AS group_name,
      me.region_id AS parent_region_id,
      me.region_name AS parent_region_name,
      COUNT(me.id)::bigint AS equipment_count,
      1::bigint AS facility_count,
      fq.quota_current_count,
      fq.quota_min_count,
      fq.quota_max_count,
      fq.quota_status,
      COALESCE(fq.quota_notes, ARRAY[]::text[]) AS quota_notes
    FROM matched_equipment me
    LEFT JOIN facility_quota fq ON fq.facility_id = me.facility_id
    GROUP BY
      me.facility_id,
      me.facility_name,
      me.region_id,
      me.region_name,
      fq.quota_current_count,
      fq.quota_min_count,
      fq.quota_max_count,
      fq.quota_status,
      fq.quota_notes
  ),
  selected_rows AS (
    SELECT
      group_type,
      group_id,
      group_name,
      parent_region_id,
      parent_region_name,
      equipment_count,
      facility_count,
      quota_current_count,
      quota_min_count,
      quota_max_count,
      quota_status,
      quota_notes
    FROM region_rows
    WHERE v_group_by = 'region'
    UNION ALL
    SELECT
      group_type,
      group_id,
      group_name,
      parent_region_id,
      parent_region_name,
      equipment_count,
      facility_count,
      quota_current_count,
      quota_min_count,
      quota_max_count,
      quota_status,
      quota_notes
    FROM facility_rows
    WHERE v_group_by = 'facility'
  ),
  limited_rows AS (
    SELECT
      group_type,
      group_id,
      group_name,
      parent_region_id,
      parent_region_name,
      equipment_count,
      facility_count,
      quota_current_count,
      quota_min_count,
      quota_max_count,
      quota_status,
      quota_notes
    FROM selected_rows
    ORDER BY equipment_count DESC, group_name ASC, group_id ASC
    LIMIT v_limit
  ),
  totals AS (
    SELECT
      COUNT(*)::bigint AS total_equipment_count,
      (
        COUNT(DISTINCT region_id)
        + CASE WHEN COUNT(*) FILTER (WHERE region_id IS NULL) > 0 THEN 1 ELSE 0 END
      )::bigint AS region_count,
      COUNT(DISTINCT facility_id)::bigint AS facility_count
    FROM matched_equipment
  )
  SELECT
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'groupType', lr.group_type,
          'groupId', lr.group_id,
          'groupName', lr.group_name,
          'parentRegionId', lr.parent_region_id,
          'parentRegionName', lr.parent_region_name,
          'equipmentCount', lr.equipment_count,
          'facilityCount', lr.facility_count,
          'quotaCurrentCount', lr.quota_current_count,
          'quotaMinCount', lr.quota_min_count,
          'quotaMaxCount', lr.quota_max_count,
          'quotaStatus', lr.quota_status,
          'quotaNotes', lr.quota_notes
        )
        ORDER BY lr.equipment_count DESC, lr.group_name ASC, lr.group_id ASC
      ) FILTER (WHERE lr.group_type IS NOT NULL),
      '[]'::jsonb
    ),
    jsonb_build_object(
      'totalEquipmentCount', COALESCE(MAX(t.total_equipment_count), 0),
      'regionCount', COALESCE(MAX(t.region_count), 0),
      'facilityCount', COALESCE(MAX(t.facility_count), 0),
      'query', v_query,
      'scopeLabel', v_scope_label
    )
  INTO v_rows, v_summary
  FROM totals t
  LEFT JOIN limited_rows lr ON true;

  RETURN jsonb_build_object(
    'rows', v_rows,
    'summary', v_summary
  );
END;
$$;


ALTER FUNCTION public.equipment_aggregate_search(p_query text, p_group_by text, p_region_id bigint, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION equipment_aggregate_search(p_query text, p_group_by text, p_region_id bigint, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_aggregate_search(p_query text, p_group_by text, p_region_id bigint, p_limit integer) IS 'Role-scoped deterministic aggregate equipment keyword search for global/admin and regional leader users.';


--
-- Name: equipment_aggregates_for_reports(bigint[], text, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_aggregates_for_reports(p_don_vi_array bigint[] DEFAULT NULL::bigint[], p_khoa_phong text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_allowed bigint[];
  v_facilities_to_query bigint[];
  v_total_imported bigint := 0;
  v_total_exported bigint := 0;
  v_current_stock bigint := 0;
  v_result jsonb;
  v_from_ts timestamptz;
  v_to_ts_excl timestamptz;
  v_single_don_vi bigint;
BEGIN
  v_role := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_allowed := public.allowed_don_vi_for_session_safe();

  IF p_khoa_phong IS NOT NULL AND btrim(p_khoa_phong) = '' THEN
    p_khoa_phong := NULL;
  END IF;

  IF p_date_from IS NOT NULL THEN
    v_from_ts := (p_date_from)::timestamptz;
  END IF;
  IF p_date_to IS NOT NULL THEN
    v_to_ts_excl := ((p_date_to + 1))::timestamptz;
  END IF;

  IF v_role IN ('global', 'admin') THEN
    IF p_don_vi_array IS NULL OR array_length(p_don_vi_array, 1) IS NULL THEN
      v_facilities_to_query := NULL;
    ELSE
      v_facilities_to_query := p_don_vi_array;
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN jsonb_build_object('totalImported', 0, 'totalExported', 0, 'currentStock', 0, 'netChange', 0);
    END IF;

    IF p_don_vi_array IS NULL OR array_length(p_don_vi_array, 1) IS NULL THEN
      v_facilities_to_query := v_allowed;
    ELSE
      SELECT ARRAY_AGG(fid)
      INTO v_facilities_to_query
      FROM UNNEST(p_don_vi_array) AS fid
      WHERE fid = ANY(v_allowed);

      IF v_facilities_to_query IS NULL OR array_length(v_facilities_to_query, 1) IS NULL THEN
        RAISE EXCEPTION 'Access denied to requested facilities' USING ERRCODE = '42501';
      END IF;
    END IF;
  ELSE
    v_single_don_vi := NULLIF(public._get_jwt_claim('don_vi'), '')::bigint;
    IF v_single_don_vi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim for role %', v_role USING ERRCODE = '42501';
    END IF;
    v_facilities_to_query := ARRAY[v_single_don_vi];
  END IF;

  -- totalImported: historical count of equipment registered in the date range.
  -- Intentionally excludes is_deleted filter — soft-deleted equipment was still
  -- physically imported and must be reflected in the historical record.
  -- Single query: when v_facilities_to_query IS NULL the tenant condition is
  -- always TRUE (no filter), matching the previous global-user branch exactly.
  SELECT COUNT(*)
  INTO v_total_imported
  FROM public.thiet_bi tb
  WHERE (v_facilities_to_query IS NULL OR tb.don_vi = ANY(v_facilities_to_query))
    AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong)
    AND (v_from_ts IS NULL OR tb.created_at >= v_from_ts)
    AND (v_to_ts_excl IS NULL OR tb.created_at < v_to_ts_excl);

  -- totalExported: historical count of equipment transferred/disposed in the date range.
  -- Intentionally excludes is_deleted filter — the transfer/disposal event occurred
  -- regardless of the equipment's current soft-delete status.
  SELECT COUNT(DISTINCT ylc.thiet_bi_id)
  INTO v_total_exported
  FROM public.yeu_cau_luan_chuyen ylc
  INNER JOIN public.thiet_bi tb ON ylc.thiet_bi_id = tb.id
  WHERE (v_facilities_to_query IS NULL OR tb.don_vi = ANY(v_facilities_to_query))
    AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong)
    AND ylc.trang_thai IN ('da_ban_giao', 'hoan_thanh')
    AND (
      (
        ylc.loai_hinh IN ('noi_bo', 'ben_ngoai')
        AND ylc.ngay_ban_giao IS NOT NULL
        AND (v_from_ts IS NULL OR ylc.ngay_ban_giao >= v_from_ts)
        AND (v_to_ts_excl IS NULL OR ylc.ngay_ban_giao < v_to_ts_excl)
      ) OR (
        ylc.muc_dich = 'thanh_ly'
        AND ylc.ngay_hoan_thanh IS NOT NULL
        AND (v_from_ts IS NULL OR ylc.ngay_hoan_thanh >= v_from_ts)
        AND (v_to_ts_excl IS NULL OR ylc.ngay_hoan_thanh < v_to_ts_excl)
      )
    );

  -- currentStock: current active inventory count.
  -- Correctly keeps is_deleted = false — only non-deleted equipment is in stock.
  SELECT COUNT(*)
  INTO v_current_stock
  FROM public.thiet_bi tb
  WHERE tb.is_deleted = false
    AND (v_facilities_to_query IS NULL OR tb.don_vi = ANY(v_facilities_to_query))
    AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong);

  v_result := jsonb_build_object(
    'totalImported', COALESCE(v_total_imported, 0),
    'totalExported', COALESCE(v_total_exported, 0),
    'currentStock', COALESCE(v_current_stock, 0),
    'netChange', COALESCE(v_total_imported, 0) - COALESCE(v_total_exported, 0)
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.equipment_aggregates_for_reports(p_don_vi_array bigint[], p_khoa_phong text, p_date_from date, p_date_to date) OWNER TO postgres;

--
-- Name: FUNCTION equipment_aggregates_for_reports(p_don_vi_array bigint[], p_khoa_phong text, p_date_from date, p_date_to date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_aggregates_for_reports(p_don_vi_array bigint[], p_khoa_phong text, p_date_from date, p_date_to date) IS 'Returns aggregated equipment statistics across multiple facilities for Reports page.
Authorization:
- Global/admin: can aggregate across all facilities or specified subset
- Regional leader: aggregates only across allowed facilities (from allowed_don_vi_for_session_safe)
- Other roles: must include a valid don_vi claim, else 42501 is raised

Parameters:
- p_don_vi_array: Array of facility IDs to aggregate (NULL = all allowed)
- p_khoa_phong: Department filter (NULL or empty = all departments)
- p_date_from, p_date_to: Date bounds for half-open interval [from, to) used on timestamps

Returns JSONB:
{
  "totalImported": number,    -- Equipment created in date range
  "totalExported": number,    -- Equipment transferred/liquidated in date range (DISTINCT thiet_bi_id)
  "currentStock": number,     -- Total current equipment count (no date filter)
  "netChange": number         -- totalImported - totalExported
}

Security:
- SECURITY DEFINER with search_path = public, pg_temp
- Facility access validated via allowed_don_vi_for_session_safe()
- PUBLIC execute revoked; granted to authenticated only';


--
-- Name: equipment_attachment_create(integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_attachment_create(p_thiet_bi_id integer, p_ten_file text, p_duong_dan text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    AS $$
  insert into file_dinh_kem(thiet_bi_id, ten_file, duong_dan_luu_tru)
  values (p_thiet_bi_id, p_ten_file, p_duong_dan)
  returning id::text;
$$;


ALTER FUNCTION public.equipment_attachment_create(p_thiet_bi_id integer, p_ten_file text, p_duong_dan text) OWNER TO postgres;

--
-- Name: equipment_attachment_delete(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_attachment_delete(p_id text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    AS $$
  delete from file_dinh_kem where id::text = p_id;
$$;


ALTER FUNCTION public.equipment_attachment_delete(p_id text) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: file_dinh_kem; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.file_dinh_kem (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    thiet_bi_id bigint NOT NULL,
