--
-- Name: equipment_attention_list(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_attention_list(p_limit integer DEFAULT 5) RETURNS SETOF public.thiet_bi
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := '';
  v_allowed_don_vi BIGINT[];
  v_jwt_claims JSONB;
BEGIN
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RETURN;
  END;

  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  IF v_role = '' OR v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) IS NULL THEN
    RETURN;
  END IF;

  IF v_role = 'global' THEN
    RETURN QUERY
    SELECT *
    FROM public.thiet_bi tb
    WHERE tb.is_deleted = false
      AND tb.tinh_trang_hien_tai IN ('Chờ sửa chữa', 'Chờ bảo trì', 'Chờ hiệu chuẩn/kiểm định')
    ORDER BY tb.ngay_bt_tiep_theo ASC NULLS LAST
    LIMIT GREATEST(p_limit, 1);

    RETURN;
  END IF;

  RETURN QUERY
  SELECT *
  FROM public.thiet_bi tb
  WHERE tb.don_vi = ANY(v_allowed_don_vi)
    AND tb.is_deleted = false
    AND tb.tinh_trang_hien_tai IN ('Chờ sửa chữa', 'Chờ bảo trì', 'Chờ hiệu chuẩn/kiểm định')
  ORDER BY tb.ngay_bt_tiep_theo ASC NULLS LAST
  LIMIT GREATEST(p_limit, 1);
END;
$$;


ALTER FUNCTION public.equipment_attention_list(p_limit integer) OWNER TO postgres;

--
-- Name: equipment_attention_list_paginated(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_attention_list_paginated(p_page integer DEFAULT 1, p_page_size integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := '';
  v_allowed_don_vi BIGINT[];
  v_jwt_claims JSONB;
  v_page INT := GREATEST(COALESCE(p_page, 1), 1);
  v_page_size INT := LEAST(GREATEST(COALESCE(p_page_size, 10), 1), 50);
  v_offset INT := 0;
  v_result JSONB;
BEGIN
  v_offset := (v_page - 1) * v_page_size;

  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'data', '[]'::jsonb,
      'total', 0,
      'page', v_page,
      'pageSize', v_page_size,
      'hasMore', false
    );
  END;

  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  IF v_role = '' OR v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'data', '[]'::jsonb,
      'total', 0,
      'page', v_page,
      'pageSize', v_page_size,
      'hasMore', false
    );
  END IF;

  WITH filtered AS (
    SELECT
      tb.id,
      tb.ten_thiet_bi,
      tb.ma_thiet_bi,
      tb.model,
      tb.tinh_trang_hien_tai,
      tb.vi_tri_lap_dat,
      tb.ngay_bt_tiep_theo
    FROM public.thiet_bi tb
    WHERE (
      v_role = 'global'
      OR tb.don_vi = ANY(v_allowed_don_vi)
    )
    AND tb.is_deleted = false
    AND tb.tinh_trang_hien_tai IN ('Chờ sửa chữa', 'Chờ bảo trì', 'Chờ hiệu chuẩn/kiểm định')
  ),
  totals AS (
    SELECT COUNT(*)::BIGINT AS total FROM filtered
  ),
  paged AS (
    SELECT * FROM filtered
    ORDER BY ngay_bt_tiep_theo ASC NULLS LAST, id ASC
    LIMIT v_page_size OFFSET v_offset
  )
  SELECT jsonb_build_object(
    'data', COALESCE(
      (
        SELECT jsonb_agg(jsonb_build_object(
          'id', p.id,
          'ten_thiet_bi', p.ten_thiet_bi,
          'ma_thiet_bi', p.ma_thiet_bi,
          'model', p.model,
          'tinh_trang_hien_tai', p.tinh_trang_hien_tai,
          'vi_tri_lap_dat', p.vi_tri_lap_dat,
          'ngay_bt_tiep_theo', p.ngay_bt_tiep_theo
        )) FROM paged p
      ),
      '[]'::jsonb
    ),
    'total', COALESCE((SELECT total FROM totals), 0),
    'page', v_page,
    'pageSize', v_page_size,
    'hasMore', COALESCE((SELECT total FROM totals), 0) > (v_offset + v_page_size)
  ) INTO v_result;

  RETURN COALESCE(v_result, jsonb_build_object(
    'data', '[]'::jsonb,
    'total', 0,
    'page', v_page,
    'pageSize', v_page_size,
    'hasMore', false
  ));
END;
$$;


ALTER FUNCTION public.equipment_attention_list_paginated(p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION equipment_attention_list_paginated(p_page integer, p_page_size integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_attention_list_paginated(p_page integer, p_page_size integer) IS 'Paginated equipment list for dashboard attention card; defaults to 10 items/page and respects tenant + regional leader scope.';


--
-- Name: equipment_bulk_delete(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_bulk_delete(p_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := NULLIF(public._get_jwt_claim('user_id'), '')::BIGINT;
  v_is_global BOOLEAN := false;
  v_expected_count INTEGER;
  v_count INTEGER;
  v_missing_ids BIGINT[];
  v_already_deleted_ids BIGINT[];
  v_batch_id UUID := gen_random_uuid();
  v_row RECORD;
BEGIN
  -- Mandatory JWT claim guards for write RPCs.
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  v_is_global := v_role = 'global';

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF NOT v_is_global AND v_donvi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  -- Permission check: only global/to_qltb can delete (allow-list).
  IF v_role NOT IN ('global', 'to_qltb') THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = '42501';
  END IF;

  -- Input validation.
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL OR array_length(p_ids, 1) = 0 THEN
    RAISE EXCEPTION 'p_ids must not be null or empty' USING ERRCODE = '22023';
  END IF;

  -- Critical: deduplicate before count-based validations and row-count assertions.
  p_ids := ARRAY(SELECT DISTINCT unnest(p_ids));
  v_expected_count := array_length(p_ids, 1);

  IF v_expected_count > 100 THEN
    RAISE EXCEPTION 'Bulk delete supports at most 100 ids per call' USING ERRCODE = '22023';
  END IF;

  -- Lock rows in deterministic order to prevent deadlocks.
  -- Non-global users only lock rows from their own tenant to avoid cross-tenant existence oracle.
  CREATE TEMP TABLE IF NOT EXISTS _equipment_bulk_delete_locked (
    id BIGINT PRIMARY KEY,
    don_vi BIGINT,
    is_deleted BOOLEAN,
    ma_thiet_bi TEXT,
    ten_thiet_bi TEXT
  ) ON COMMIT DROP;

  TRUNCATE TABLE _equipment_bulk_delete_locked;

  INSERT INTO _equipment_bulk_delete_locked (id, don_vi, is_deleted, ma_thiet_bi, ten_thiet_bi)
  SELECT tb.id, tb.don_vi, tb.is_deleted, tb.ma_thiet_bi, tb.ten_thiet_bi
  FROM public.thiet_bi tb
  WHERE tb.id = ANY(p_ids)
    AND (v_is_global OR tb.don_vi = v_donvi)
  ORDER BY tb.id
  FOR UPDATE;

  SELECT count(*) INTO v_count
  FROM _equipment_bulk_delete_locked;

  IF v_count <> v_expected_count THEN
    SELECT ARRAY(
      SELECT req.id
      FROM unnest(p_ids) AS req(id)
      LEFT JOIN _equipment_bulk_delete_locked l ON l.id = req.id
      WHERE l.id IS NULL
      ORDER BY req.id
    ) INTO v_missing_ids;

    RAISE EXCEPTION 'Equipment ids not found: %', array_to_string(v_missing_ids, ', ')
      USING ERRCODE = 'P0002';
  END IF;

  SELECT ARRAY(
    SELECT l.id
    FROM _equipment_bulk_delete_locked l
    WHERE l.is_deleted IS DISTINCT FROM false
    ORDER BY l.id
  ) INTO v_already_deleted_ids;

  IF COALESCE(array_length(v_already_deleted_ids, 1), 0) > 0 THEN
    RAISE EXCEPTION 'Equipment not found or already deleted: %', array_to_string(v_already_deleted_ids, ', ')
      USING ERRCODE = 'P0002';
  END IF;

  -- Defense in depth: keep deletion constraints in UPDATE.
  UPDATE public.thiet_bi tb
  SET is_deleted = true
  WHERE tb.id = ANY(p_ids)
    AND tb.is_deleted = false
    AND (v_is_global OR tb.don_vi = v_donvi);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> v_expected_count THEN
    RAISE EXCEPTION 'Bulk delete row count mismatch (expected %, got %)', v_expected_count, v_count
      USING ERRCODE = 'P0001';
  END IF;

  FOR v_row IN
    SELECT l.id, l.ma_thiet_bi, l.ten_thiet_bi, l.don_vi
    FROM _equipment_bulk_delete_locked l
    ORDER BY l.id
  LOOP
    PERFORM public.audit_log(
      p_action_type := 'equipment_bulk_delete',
      p_entity_type := 'equipment',
      p_entity_id := v_row.id,
      p_entity_label := COALESCE(v_row.ma_thiet_bi, v_row.ten_thiet_bi, 'equipment-' || v_row.id::TEXT),
      p_action_details := jsonb_build_object(
        'soft_deleted', true,
        'id', v_row.id,
        'ma_thiet_bi', v_row.ma_thiet_bi,
        'ten_thiet_bi', v_row.ten_thiet_bi,
        'don_vi', v_row.don_vi,
        'batch_id', v_batch_id,
        'batch_size', v_expected_count
      )
    );
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_count', v_expected_count,
    'ids', COALESCE(
      (SELECT jsonb_agg(l.id ORDER BY l.id) FROM _equipment_bulk_delete_locked l),
      '[]'::JSONB
    ),
    'batch_id', v_batch_id
  );
END;
$$;


ALTER FUNCTION public.equipment_bulk_delete(p_ids bigint[]) OWNER TO postgres;

--
-- Name: FUNCTION equipment_bulk_delete(p_ids bigint[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_bulk_delete(p_ids bigint[]) IS 'Bulk soft-delete for equipment. Uses tenant-scoped locking for non-global users to avoid cross-tenant existence oracle.';


--
-- Name: equipment_bulk_import(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_bulk_import(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_len int;
  v_idx int := 0;
  v_success int := 0;
  v_failed int := 0;
  v_details jsonb := '[]'::jsonb;
  v_item jsonb;
  v_err text;
BEGIN
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'p_items must be a JSON array' USING ERRCODE = '22P02';
  END IF;

  v_len := jsonb_array_length(p_items);
  IF v_len = 0 THEN
    RETURN jsonb_build_object('success', true, 'inserted', 0, 'failed', 0, 'total', 0, 'details', '[]'::jsonb);
  END IF;

  FOR v_idx IN 0 .. v_len - 1 LOOP
    v_item := p_items->v_idx;

    -- Inject nguon_nhap='excel' for bulk imports
    v_item := v_item || '{"nguon_nhap": "excel"}'::jsonb;

    BEGIN
      -- Reuse existing single-insert RPC for validations and tenant assignment
      PERFORM public.equipment_create(v_item);
      v_success := v_success + 1;
      v_details := v_details || jsonb_build_array(jsonb_build_object(
        'index', v_idx,
        'success', true
      ));
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
      v_details := v_details || jsonb_build_array(jsonb_build_object(
        'index', v_idx,
        'success', false,
        'error', COALESCE(v_err, SQLERRM)
      ));
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'inserted', v_success,
    'failed', v_failed,
    'total', v_len,
    'details', v_details
  );
END;
$$;


ALTER FUNCTION public.equipment_bulk_import(p_items jsonb) OWNER TO postgres;

--
-- Name: equipment_classifications_list_for_tenant(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_classifications_list_for_tenant(p_don_vi bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_user_id TEXT;
  v_allowed BIGINT[];
  v_effective BIGINT[];
  v_department_scope TEXT;
  v_jwt_claims JSONB;
BEGIN
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;

  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));
  v_user_id := NULLIF(v_jwt_claims ->> 'user_id', '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role = 'global' THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF v_allowed IS NULL OR NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims ->> 'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN;
    END IF;
  END IF;

  RETURN QUERY
  SELECT jsonb_build_object(
    'name', COALESCE(NULLIF(TRIM(phan_loai_theo_nd98), ''), 'Chưa phân loại'),
    'count', COUNT(*)::INTEGER
  )
  FROM public.thiet_bi tb
  WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
    AND tb.is_deleted = false
    AND (v_role <> 'user' OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope)
  GROUP BY COALESCE(NULLIF(TRIM(phan_loai_theo_nd98), ''), 'Chưa phân loại')
  ORDER BY COUNT(*) DESC;
END;
$$;


ALTER FUNCTION public.equipment_classifications_list_for_tenant(p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION equipment_classifications_list_for_tenant(p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_classifications_list_for_tenant(p_don_vi bigint) IS 'Returns classification list for tenant equipment. FIXED: Now uses fallback handling for missing JWT claims.';


--
-- Name: equipment_count(text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_count(p_statuses text[] DEFAULT NULL::text[], p_q text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role        TEXT     := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_allowed     BIGINT[] := public.allowed_don_vi_for_session();
  v_cnt         BIGINT;
  v_sanitized_q TEXT;
BEGIN
  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  IF v_role = 'global' THEN
    SELECT COUNT(*) INTO v_cnt
    FROM public.thiet_bi tb
    WHERE tb.is_deleted = false
      AND (v_sanitized_q IS NULL OR tb.ten_thiet_bi ILIKE ('%' || v_sanitized_q || '%') OR tb.ma_thiet_bi ILIKE ('%' || v_sanitized_q || '%'))
      AND (p_statuses IS NULL OR tb.tinh_trang_hien_tai = ANY(p_statuses));
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN 0;
    END IF;

    SELECT COUNT(*) INTO v_cnt
    FROM public.thiet_bi tb
    WHERE tb.don_vi = ANY(v_allowed)
      AND tb.is_deleted = false
      AND (v_sanitized_q IS NULL OR tb.ten_thiet_bi ILIKE ('%' || v_sanitized_q || '%') OR tb.ma_thiet_bi ILIKE ('%' || v_sanitized_q || '%'))
      AND (p_statuses IS NULL OR tb.tinh_trang_hien_tai = ANY(p_statuses));
  END IF;

  RETURN COALESCE(v_cnt, 0);
END;
$$;


ALTER FUNCTION public.equipment_count(p_statuses text[], p_q text) OWNER TO postgres;

--
-- Name: equipment_count_enhanced(text[], text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_count_enhanced(p_statuses text[] DEFAULT NULL::text[], p_q text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_khoa_phong text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_user_id text;
  v_allowed bigint[];
  v_effective_donvi bigint;
  v_cnt bigint;
  v_sanitized_q text;
  v_department_scope text;
  v_requested_department_scope text;
BEGIN
  v_role := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id := NULLIF(public._get_jwt_claim('user_id'), '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role = 'global' THEN
    v_effective_donvi := p_don_vi;
  ELSIF v_role = 'regional_leader' THEN
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN 0;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF p_don_vi = ANY(v_allowed) THEN
        v_effective_donvi := p_don_vi;
      ELSE
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
    ELSE
      v_effective_donvi := NULLIF(public._get_jwt_claim('don_vi'), '')::bigint;
      IF v_effective_donvi IS NULL THEN
        RETURN 0;
      END IF;
    END IF;
  ELSIF v_role IN ('to_qltb', 'qltb_khoa', 'technician', 'user') THEN
    v_effective_donvi := NULLIF(public._get_jwt_claim('don_vi'), '')::bigint;
    IF v_effective_donvi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim for role %', v_role USING ERRCODE = '42501';
    END IF;

    IF v_allowed IS NULL
       OR array_length(v_allowed, 1) IS NULL
       OR NOT (v_effective_donvi = ANY(v_allowed)) THEN
      RAISE EXCEPTION 'Access denied for role %', v_role USING ERRCODE = '42501';
    END IF;

    IF p_don_vi IS NOT NULL AND p_don_vi <> v_effective_donvi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'Access denied for role %', v_role USING ERRCODE = '42501';
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(public._get_jwt_claim('khoa_phong'));
    IF v_department_scope IS NULL THEN
      RETURN 0;
    END IF;

    IF p_khoa_phong IS NOT NULL THEN
      v_requested_department_scope := public._normalize_department_scope(p_khoa_phong);
      IF v_requested_department_scope IS DISTINCT FROM v_department_scope THEN
        RETURN 0;
      END IF;
    END IF;
  END IF;

  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  SELECT COUNT(*)
  INTO v_cnt
  FROM public.thiet_bi tb
  WHERE tb.is_deleted = false
    AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)
    AND (
      (v_role = 'user' AND public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope)
      OR
      (v_role <> 'user' AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong))
    )
    AND (
      v_sanitized_q IS NULL
      OR tb.ten_thiet_bi ILIKE ('%' || v_sanitized_q || '%')
      OR tb.ma_thiet_bi ILIKE ('%' || v_sanitized_q || '%')
    )
    AND (p_statuses IS NULL OR tb.tinh_trang_hien_tai = ANY(p_statuses));

  RETURN COALESCE(v_cnt, 0);
END;
$$;


