FIXED: Added regional_leader support with allowed_don_vi_for_session_safe() validation.';


--
-- Name: equipment_create(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_create(p_payload jsonb) RETURNS public.thiet_bi
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT := COALESCE(public._get_jwt_claim('app_role'), '');
  v_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := NULLIF(public._get_jwt_claim('user_id'), '')::BIGINT;
  v_khoa_phong TEXT := COALESCE(p_payload->>'khoa_phong_quan_ly', NULL);
  v_status TEXT := NULLIF(TRIM(p_payload->>'tinh_trang_hien_tai'), '');
  v_ngay_dua_vao_su_dung TEXT := NULLIF(TRIM(p_payload->>'ngay_dua_vao_su_dung'), '');
  v_ngay_ngung_su_dung TEXT := NULLIF(TRIM(p_payload->>'ngay_ngung_su_dung'), '');
  v_valid_statuses TEXT[] := ARRAY[
    'Hoạt động', 'Chờ sửa chữa', 'Chờ bảo trì',
    'Chờ hiệu chuẩn/kiểm định', 'Ngưng sử dụng', 'Chưa có nhu cầu sử dụng'
  ];
  rec public.thiet_bi;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('global','to_qltb','technician') THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = '42501';
  END IF;

  IF v_role <> 'global' AND v_donvi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'technician' THEN
    PERFORM 1
    FROM public.nhan_vien nv
    WHERE nv.id = v_user_id
      AND nv.khoa_phong = v_khoa_phong;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Technician department mismatch' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_status IS NOT NULL AND NOT (v_status = ANY(v_valid_statuses)) THEN
    RAISE EXCEPTION 'Invalid status: %. Must be one of: %', v_status, array_to_string(v_valid_statuses, ', ')
      USING ERRCODE = '22023';
  END IF;

  IF v_ngay_ngung_su_dung IS NOT NULL AND v_status IS DISTINCT FROM 'Ngưng sử dụng' THEN
    RAISE EXCEPTION 'Ngày ngừng sử dụng chỉ được phép khi tình trạng là "Ngưng sử dụng"'
      USING ERRCODE = '22023';
  END IF;

  IF v_ngay_ngung_su_dung IS NOT NULL AND (
    v_ngay_ngung_su_dung !~ '^\d{4}-\d{2}-\d{2}$'
    OR to_char(to_date(v_ngay_ngung_su_dung, 'YYYY-MM-DD'), 'YYYY-MM-DD') <> v_ngay_ngung_su_dung
  ) THEN
    RAISE EXCEPTION 'Định dạng ngày không hợp lệ. Sử dụng: YYYY-MM-DD'
      USING ERRCODE = '22023';
  END IF;

  IF
    v_ngay_ngung_su_dung IS NOT NULL
    AND v_ngay_dua_vao_su_dung IS NOT NULL
    AND v_ngay_dua_vao_su_dung ~ '^\d{4}-\d{2}-\d{2}$'
    AND to_char(to_date(v_ngay_dua_vao_su_dung, 'YYYY-MM-DD'), 'YYYY-MM-DD') = v_ngay_dua_vao_su_dung
    AND v_ngay_ngung_su_dung < v_ngay_dua_vao_su_dung
  THEN
    RAISE EXCEPTION 'Ngày ngừng sử dụng phải sau hoặc bằng ngày đưa vào sử dụng'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.thiet_bi (
    ten_thiet_bi,
    ma_thiet_bi,
    khoa_phong_quan_ly,
    model,
    serial,
    cau_hinh_thiet_bi,
    phu_kien_kem_theo,
    hang_san_xuat,
    noi_san_xuat,
    nam_san_xuat,
    ngay_nhap,
    ngay_dua_vao_su_dung,
    ngay_ngung_su_dung,
    nguon_kinh_phi,
    gia_goc,
    nam_tinh_hao_mon,
    ty_le_hao_mon,
    han_bao_hanh,
    vi_tri_lap_dat,
    nguoi_dang_truc_tiep_quan_ly,
    tinh_trang_hien_tai,
    ghi_chu,
    chu_ky_bt_dinh_ky,
    ngay_bt_tiep_theo,
    chu_ky_hc_dinh_ky,
    ngay_hc_tiep_theo,
    chu_ky_kd_dinh_ky,
    ngay_kd_tiep_theo,
    phan_loai_theo_nd98,
    don_vi,
    nguon_nhap,
    so_luu_hanh
  )
  VALUES (
    p_payload->>'ten_thiet_bi',
    p_payload->>'ma_thiet_bi',
    v_khoa_phong,
    NULLIF(p_payload->>'model',''),
    NULLIF(p_payload->>'serial',''),
    NULLIF(p_payload->>'cau_hinh_thiet_bi',''),
    NULLIF(p_payload->>'phu_kien_kem_theo',''),
    NULLIF(p_payload->>'hang_san_xuat',''),
    NULLIF(p_payload->>'noi_san_xuat',''),
    NULLIF(p_payload->>'nam_san_xuat','')::INT,
    NULLIF(p_payload->>'ngay_nhap',''),
    v_ngay_dua_vao_su_dung,
    v_ngay_ngung_su_dung,
    NULLIF(p_payload->>'nguon_kinh_phi',''),
    NULLIF(p_payload->>'gia_goc','')::NUMERIC,
    NULLIF(p_payload->>'nam_tinh_hao_mon','')::INT,
    NULLIF(p_payload->>'ty_le_hao_mon',''),
    NULLIF(p_payload->>'han_bao_hanh',''),
    NULLIF(p_payload->>'vi_tri_lap_dat',''),
    NULLIF(p_payload->>'nguoi_dang_truc_tiep_quan_ly',''),
    v_status,
    NULLIF(p_payload->>'ghi_chu',''),
    NULLIF(p_payload->>'chu_ky_bt_dinh_ky','')::INT,
    CASE WHEN COALESCE(p_payload->>'ngay_bt_tiep_theo','') = '' THEN NULL ELSE (p_payload->>'ngay_bt_tiep_theo')::DATE END,
    NULLIF(p_payload->>'chu_ky_hc_dinh_ky','')::INT,
    CASE WHEN COALESCE(p_payload->>'ngay_hc_tiep_theo','') = '' THEN NULL ELSE (p_payload->>'ngay_hc_tiep_theo')::DATE END,
    NULLIF(p_payload->>'chu_ky_kd_dinh_ky','')::INT,
    CASE WHEN COALESCE(p_payload->>'ngay_kd_tiep_theo','') = '' THEN NULL ELSE (p_payload->>'ngay_kd_tiep_theo')::DATE END,
    NULLIF(p_payload->>'phan_loai_theo_nd98',''),
    v_donvi,
    COALESCE(NULLIF(p_payload->>'nguon_nhap',''), 'manual'),
    NULLIF(p_payload->>'so_luu_hanh','')
  )
  RETURNING * INTO rec;

  RETURN rec;
END;
$_$;


ALTER FUNCTION public.equipment_create(p_payload jsonb) OWNER TO postgres;

--
-- Name: equipment_create(text, text, text, text, text, text, date, numeric, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_create(p_ten_thiet_bi text, p_so_serial text DEFAULT NULL::text, p_mo_ta text DEFAULT NULL::text, p_khoa_phong text DEFAULT NULL::text, p_vi_tri text DEFAULT NULL::text, p_trang_thai text DEFAULT 'hoat_dong'::text, p_ngay_mua date DEFAULT CURRENT_DATE, p_gia_mua numeric DEFAULT NULL::numeric, p_han_bao_hanh date DEFAULT NULL::date, p_don_vi text DEFAULT NULL::text) RETURNS TABLE(id bigint, ten_thiet_bi text, so_serial text, mo_ta text, khoa_phong text, vi_tri text, trang_thai text, ngay_mua date, gia_mua numeric, han_bao_hanh date, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_id BIGINT;
  current_user_ctx RECORD;
BEGIN
  SELECT * INTO current_user_ctx FROM _get_current_user_context();
  IF current_user_ctx.role NOT IN ('global', 'to_qltb', 'admin') THEN
    RAISE EXCEPTION 'Insufficient permissions to create equipment' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.thiet_bi (
    ten_thiet_bi, so_serial, mo_ta, khoa_phong, vi_tri,
    trang_thai, ngay_mua, gia_mua, han_bao_hanh, don_vi
  ) VALUES (
    p_ten_thiet_bi, p_so_serial, p_mo_ta, p_khoa_phong, p_vi_tri,
    p_trang_thai, p_ngay_mua, p_gia_mua, p_han_bao_hanh, 
    COALESCE(p_don_vi, current_user_ctx.don_vi)
  ) RETURNING thiet_bi.id INTO new_id;

  -- Unified audit log
  PERFORM public.audit_log(
    'equipment_create',
    'device',
    new_id,
    p_ten_thiet_bi,
    jsonb_build_object('equipment_id', new_id, 'equipment_name', p_ten_thiet_bi, 'serial_number', p_so_serial, 'department', p_khoa_phong, 'status', p_trang_thai)
  );

  RETURN QUERY
  SELECT 
    tb.id, tb.ten_thiet_bi, tb.so_serial, tb.mo_ta, tb.khoa_phong, tb.vi_tri,
    tb.trang_thai, tb.ngay_mua, tb.gia_mua, tb.han_bao_hanh, tb.created_at
  FROM thiet_bi tb
  WHERE tb.id = new_id;
END;
$$;


ALTER FUNCTION public.equipment_create(p_ten_thiet_bi text, p_so_serial text, p_mo_ta text, p_khoa_phong text, p_vi_tri text, p_trang_thai text, p_ngay_mua date, p_gia_mua numeric, p_han_bao_hanh date, p_don_vi text) OWNER TO postgres;

--
-- Name: FUNCTION equipment_create(p_ten_thiet_bi text, p_so_serial text, p_mo_ta text, p_khoa_phong text, p_vi_tri text, p_trang_thai text, p_ngay_mua date, p_gia_mua numeric, p_han_bao_hanh date, p_don_vi text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_create(p_ten_thiet_bi text, p_so_serial text, p_mo_ta text, p_khoa_phong text, p_vi_tri text, p_trang_thai text, p_ngay_mua date, p_gia_mua numeric, p_han_bao_hanh date, p_don_vi text) IS 'Create equipment with audit logging. Enhanced version with activity tracking.';


--
-- Name: equipment_delete(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_delete(p_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := NULLIF(public._get_jwt_claim('user_id'), '')::BIGINT;
  v_code TEXT;
  v_name TEXT;
  v_row_don_vi BIGINT;
  v_is_deleted BOOLEAN;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role <> 'global' AND v_donvi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('global', 'to_qltb') THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = '42501';
  END IF;

  SELECT tb.ma_thiet_bi, tb.ten_thiet_bi, tb.don_vi, tb.is_deleted
  INTO v_code, v_name, v_row_don_vi, v_is_deleted
  FROM public.thiet_bi tb
  WHERE tb.id = p_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Equipment not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_role <> 'global' AND v_row_don_vi IS DISTINCT FROM v_donvi THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  IF v_is_deleted IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'Equipment not found or already deleted' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.thiet_bi
  SET is_deleted = true
  WHERE id = p_id AND is_deleted = false
    AND (v_role = 'global' OR don_vi = v_donvi);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Equipment not found or already deleted' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.audit_log(
    p_action_type := 'equipment_delete',
    p_entity_type := 'equipment',
    p_entity_id := p_id,
    p_entity_label := COALESCE(v_code, v_name, 'equipment-' || p_id::text),
    p_action_details := jsonb_build_object(
      'soft_deleted', true, 'id', p_id,
      'ma_thiet_bi', v_code, 'ten_thiet_bi', v_name, 'don_vi', v_row_don_vi
    )
  );

  RETURN jsonb_build_object('success', true, 'id', p_id, 'soft_deleted', true);
END;
$$;


ALTER FUNCTION public.equipment_delete(p_id bigint) OWNER TO postgres;

--
-- Name: FUNCTION equipment_delete(p_id bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_delete(p_id bigint) IS 'Soft-delete equipment. Uses SELECT FOR UPDATE to prevent TOCTOU race conditions. Tenant isolation enforced atomically with row lock.';


--
-- Name: equipment_department_distribution(text, bigint, text, text[], text, text[], text, text[], text, text[], text, text[], text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_department_distribution(p_q text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_khoa_phong text DEFAULT NULL::text, p_khoa_phong_array text[] DEFAULT NULL::text[], p_nguoi_su_dung text DEFAULT NULL::text, p_nguoi_su_dung_array text[] DEFAULT NULL::text[], p_vi_tri_lap_dat text DEFAULT NULL::text, p_vi_tri_lap_dat_array text[] DEFAULT NULL::text[], p_tinh_trang text DEFAULT NULL::text, p_tinh_trang_array text[] DEFAULT NULL::text[], p_phan_loai text DEFAULT NULL::text, p_phan_loai_array text[] DEFAULT NULL::text[], p_nguon_kinh_phi text DEFAULT NULL::text, p_nguon_kinh_phi_array text[] DEFAULT NULL::text[]) RETURNS TABLE(department text, label text, count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := '';
  v_user_id TEXT := NULL;
  v_claim_donvi BIGINT := NULL;
  v_allowed_don_vi BIGINT[];
  v_effective_donvi BIGINT := NULL;
  v_department_scope TEXT;
  v_where TEXT := '1=1 AND is_deleted = false';
  v_jwt_claims JSONB;
  v_sanitized_q TEXT;
  v_unclassified_label CONSTANT TEXT := 'Chưa phân loại';
  v_empty_user_label CONSTANT TEXT := 'Chưa có người sử dụng';
  v_empty_location_label CONSTANT TEXT := 'Chưa có vị trí';
BEGIN
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;

  v_role := COALESCE(
    v_jwt_claims ->>'app_role',
    v_jwt_claims ->>'role',
    ''
  );
  v_user_id := NULLIF(v_jwt_claims ->>'user_id', '');
  v_claim_donvi := NULLIF(v_jwt_claims ->>'don_vi', '')::BIGINT;

  IF lower(v_role) = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  IF lower(v_role) = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims ->>'khoa_phong');
  END IF;

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  IF lower(v_role) IN ('global', 'admin') THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective_donvi := p_don_vi;
    ELSE
      v_effective_donvi := NULL;
    END IF;
  ELSE
    IF v_allowed_don_vi IS NOT NULL AND array_length(v_allowed_don_vi, 1) > 0 THEN
      IF p_don_vi IS NOT NULL THEN
        IF p_don_vi = ANY(v_allowed_don_vi) THEN
          v_effective_donvi := p_don_vi;
        ELSE
          RETURN;
        END IF;
      ELSE
        v_effective_donvi := NULL;
      END IF;
    ELSE
      RETURN;
    END IF;
  END IF;

  IF lower(v_role) = 'user' AND v_department_scope IS NULL THEN
    RETURN;
  END IF;

  IF v_effective_donvi IS NOT NULL THEN
    v_where := v_where || ' AND don_vi = ' || v_effective_donvi;
  END IF;

  IF v_effective_donvi IS NULL AND lower(v_role) NOT IN ('global', 'admin') AND v_allowed_don_vi IS NOT NULL THEN
    v_where := v_where || ' AND don_vi = ANY(ARRAY[' || array_to_string(v_allowed_don_vi, ',') || '])';
  END IF;

  IF lower(v_role) = 'user' THEN
    v_where := v_where || ' AND public._normalize_department_scope(khoa_phong_quan_ly) = '
      || quote_literal(v_department_scope);
  END IF;

  IF p_khoa_phong_array IS NOT NULL AND array_length(p_khoa_phong_array, 1) > 0 THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(khoa_phong_quan_ly), ''''), ' || quote_literal(v_unclassified_label) || ') = ANY(ARRAY[' ||
               array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_khoa_phong_array) AS x), ',') || '])';
  ELSIF p_khoa_phong IS NOT NULL AND trim(p_khoa_phong) != '' THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(khoa_phong_quan_ly), ''''), ' || quote_literal(v_unclassified_label) || ') = ' || quote_literal(p_khoa_phong);
  END IF;

  IF p_nguoi_su_dung_array IS NOT NULL AND array_length(p_nguoi_su_dung_array, 1) > 0 THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(nguoi_dang_truc_tiep_quan_ly), ''''), ' || quote_literal(v_empty_user_label) || ') = ANY(ARRAY[' ||
               array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_nguoi_su_dung_array) AS x), ',') || '])';
  ELSIF p_nguoi_su_dung IS NOT NULL AND trim(p_nguoi_su_dung) != '' THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(nguoi_dang_truc_tiep_quan_ly), ''''), ' || quote_literal(v_empty_user_label) || ') = ' || quote_literal(p_nguoi_su_dung);
  END IF;

  IF p_vi_tri_lap_dat_array IS NOT NULL AND array_length(p_vi_tri_lap_dat_array, 1) > 0 THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(vi_tri_lap_dat), ''''), ' || quote_literal(v_empty_location_label) || ') = ANY(ARRAY[' ||
               array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_vi_tri_lap_dat_array) AS x), ',') || '])';
  ELSIF p_vi_tri_lap_dat IS NOT NULL AND trim(p_vi_tri_lap_dat) != '' THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(vi_tri_lap_dat), ''''), ' || quote_literal(v_empty_location_label) || ') = ' || quote_literal(p_vi_tri_lap_dat);
  END IF;

  IF p_tinh_trang_array IS NOT NULL AND array_length(p_tinh_trang_array, 1) > 0 THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(tinh_trang_hien_tai), ''''), ' || quote_literal(v_unclassified_label) || ') = ANY(ARRAY[' ||
               array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_tinh_trang_array) AS x), ',') || '])';
  ELSIF p_tinh_trang IS NOT NULL AND trim(p_tinh_trang) != '' THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(tinh_trang_hien_tai), ''''), ' || quote_literal(v_unclassified_label) || ') = ' || quote_literal(p_tinh_trang);
  END IF;

  IF p_phan_loai_array IS NOT NULL AND array_length(p_phan_loai_array, 1) > 0 THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(phan_loai_theo_nd98), ''''), ' || quote_literal(v_unclassified_label) || ') = ANY(ARRAY[' ||
               array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_phan_loai_array) AS x), ',') || '])';
  ELSIF p_phan_loai IS NOT NULL AND trim(p_phan_loai) != '' THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(phan_loai_theo_nd98), ''''), ' || quote_literal(v_unclassified_label) || ') = ' || quote_literal(p_phan_loai);
  END IF;

  IF p_nguon_kinh_phi_array IS NOT NULL AND array_length(p_nguon_kinh_phi_array, 1) > 0 THEN
    IF 'Chưa có' = ANY(p_nguon_kinh_phi_array) THEN
      DECLARE v_non_empty_sources TEXT[];
      BEGIN
        SELECT ARRAY(SELECT x FROM unnest(p_nguon_kinh_phi_array) AS x WHERE x != 'Chưa có') INTO v_non_empty_sources;
        IF v_non_empty_sources IS NOT NULL AND array_length(v_non_empty_sources, 1) > 0 THEN
          v_where := v_where || ' AND (nguon_kinh_phi IS NULL OR TRIM(nguon_kinh_phi) = '''' OR TRIM(nguon_kinh_phi) = ANY(ARRAY[' ||
            array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(v_non_empty_sources) AS x), ',') || ']))';
        ELSE
          v_where := v_where || ' AND (nguon_kinh_phi IS NULL OR TRIM(nguon_kinh_phi) = '''')';
        END IF;
      END;
    ELSE
      v_where := v_where || ' AND TRIM(nguon_kinh_phi) = ANY(ARRAY[' ||
        array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_nguon_kinh_phi_array) AS x), ',') || '])';
    END IF;
  ELSIF p_nguon_kinh_phi IS NOT NULL AND trim(p_nguon_kinh_phi) != '' THEN
    IF p_nguon_kinh_phi = 'Chưa có' THEN
      v_where := v_where || ' AND (nguon_kinh_phi IS NULL OR TRIM(nguon_kinh_phi) = '''')';
    ELSE
      v_where := v_where || ' AND TRIM(nguon_kinh_phi) = ' || quote_literal(p_nguon_kinh_phi);
    END IF;
  END IF;

  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  IF v_sanitized_q IS NOT NULL THEN
    v_where := v_where || ' AND (ten_thiet_bi ILIKE ' || quote_literal('%' || v_sanitized_q || '%') ||
              ' OR ma_thiet_bi ILIKE ' || quote_literal('%' || v_sanitized_q || '%') ||
              ' OR serial ILIKE ' || quote_literal('%' || v_sanitized_q || '%') ||
              ' OR so_luu_hanh ILIKE ' || quote_literal('%' || v_sanitized_q || '%') ||
              ' OR model ILIKE ' || quote_literal('%' || v_sanitized_q || '%') || ')';
  END IF;

  RETURN QUERY EXECUTE format(
    'SELECT department,
            COALESCE(department, ''Chưa cập nhật'') AS label,
            COUNT(*)::integer AS "count"
       FROM (
         SELECT NULLIF(BTRIM(khoa_phong_quan_ly), '''') AS department
         FROM public.thiet_bi
         WHERE %s
       ) scoped
       GROUP BY department
       ORDER BY COUNT(*) DESC, label ASC',
    v_where
  );
END;
$$;


ALTER FUNCTION public.equipment_department_distribution(p_q text, p_don_vi bigint, p_khoa_phong text, p_khoa_phong_array text[], p_nguoi_su_dung text, p_nguoi_su_dung_array text[], p_vi_tri_lap_dat text, p_vi_tri_lap_dat_array text[], p_tinh_trang text, p_tinh_trang_array text[], p_phan_loai text, p_phan_loai_array text[], p_nguon_kinh_phi text, p_nguon_kinh_phi_array text[]) OWNER TO postgres;

--
-- Name: FUNCTION equipment_department_distribution(p_q text, p_don_vi bigint, p_khoa_phong text, p_khoa_phong_array text[], p_nguoi_su_dung text, p_nguoi_su_dung_array text[], p_vi_tri_lap_dat text, p_vi_tri_lap_dat_array text[], p_tinh_trang text, p_tinh_trang_array text[], p_phan_loai text, p_phan_loai_array text[], p_nguon_kinh_phi text, p_nguon_kinh_phi_array text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_department_distribution(p_q text, p_don_vi bigint, p_khoa_phong text, p_khoa_phong_array text[], p_nguoi_su_dung text, p_nguoi_su_dung_array text[], p_vi_tri_lap_dat text, p_vi_tri_lap_dat_array text[], p_tinh_trang text, p_tinh_trang_array text[], p_phan_loai text, p_phan_loai_array text[], p_nguon_kinh_phi text, p_nguon_kinh_phi_array text[]) IS 'Returns department distribution counts for the filtered Equipment result set.';


--
-- Name: equipment_departments_list(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_departments_list() RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims jsonb := coalesce(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_role text := coalesce(nullif(v_claims->>'app_role',''), nullif(v_claims->>'role',''));
  v_allowed bigint[] := NULL;
BEGIN
  IF v_role = 'global' THEN
    RETURN QUERY
    SELECT DISTINCT trim(both from tb.khoa_phong_quan_ly)
    FROM public.thiet_bi tb
    WHERE tb.khoa_phong_quan_ly IS NOT NULL
      AND length(trim(tb.khoa_phong_quan_ly)) > 0
    ORDER BY 1;
  ELSE
    v_allowed := public.allowed_don_vi_for_session();

    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    RETURN QUERY
    SELECT DISTINCT trim(both from tb.khoa_phong_quan_ly)
    FROM public.thiet_bi tb
    WHERE tb.don_vi = ANY(v_allowed)
      AND tb.khoa_phong_quan_ly IS NOT NULL
      AND length(trim(tb.khoa_phong_quan_ly)) > 0
    ORDER BY 1;
  END IF;
END;
$$;


ALTER FUNCTION public.equipment_departments_list() OWNER TO postgres;

--
-- Name: equipment_filter_buckets(text, bigint, text[], text[], text[], text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_filter_buckets(p_q text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_khoa_phong_array text[] DEFAULT NULL::text[], p_nguoi_su_dung_array text[] DEFAULT NULL::text[], p_vi_tri_lap_dat_array text[] DEFAULT NULL::text[], p_tinh_trang_array text[] DEFAULT NULL::text[], p_phan_loai_array text[] DEFAULT NULL::text[], p_nguon_kinh_phi_array text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_user_id text;
  v_allowed bigint[];
  v_effective bigint[];
  v_department_scope text;
  v_jwt_claims jsonb;
  v_sanitized_q text;
  v_result jsonb;
  v_unclassified_label CONSTANT text := 'Chưa phân loại';
  v_empty_user_label CONSTANT text := 'Chưa có người sử dụng';
  v_empty_location_label CONSTANT text := 'Chưa có vị trí';
  v_empty_funding_label CONSTANT text := 'Chưa có';
  v_empty_result CONSTANT jsonb := jsonb_build_object(
    'department', '[]'::jsonb,
    'user', '[]'::jsonb,
    'location', '[]'::jsonb,
    'status', '[]'::jsonb,
    'classification', '[]'::jsonb,
    'fundingSource', '[]'::jsonb
  );
BEGIN
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;

  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));
  v_user_id := NULLIF(v_jwt_claims ->> 'user_id', '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role = 'global' THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN v_empty_result;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims ->> 'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN v_empty_result;
    END IF;
  END IF;

  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  WITH base_equipment AS MATERIALIZED (
    SELECT
      COALESCE(NULLIF(TRIM(tb.khoa_phong_quan_ly), ''), v_unclassified_label) AS department_name,
      COALESCE(NULLIF(TRIM(tb.nguoi_dang_truc_tiep_quan_ly), ''), v_empty_user_label) AS user_name,
      COALESCE(NULLIF(TRIM(tb.vi_tri_lap_dat), ''), v_empty_location_label) AS location_name,
      COALESCE(NULLIF(TRIM(tb.tinh_trang_hien_tai), ''), v_unclassified_label) AS status_name,
      COALESCE(NULLIF(TRIM(tb.phan_loai_theo_nd98), ''), v_unclassified_label) AS classification_name,
      COALESCE(NULLIF(TRIM(tb.nguon_kinh_phi), ''), v_empty_funding_label) AS funding_source_name
    FROM public.thiet_bi tb
    WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
      AND tb.is_deleted = false
      AND (
        v_role <> 'user'
        OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
      )
      AND (
        v_sanitized_q IS NULL
        OR tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%'
        OR tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
        OR tb.serial ILIKE '%' || v_sanitized_q || '%'
        OR tb.so_luu_hanh ILIKE '%' || v_sanitized_q || '%'
        OR tb.model ILIKE '%' || v_sanitized_q || '%'
      )
  )
  SELECT jsonb_build_object(
    'department', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('name', bucket.name, 'count', bucket.count) ORDER BY bucket.count DESC, bucket.name)
      FROM (
        SELECT department_name AS name, COUNT(*)::integer AS count
        FROM base_equipment
        WHERE (p_nguoi_su_dung_array IS NULL OR array_length(p_nguoi_su_dung_array, 1) IS NULL OR user_name = ANY(p_nguoi_su_dung_array))
          AND (p_vi_tri_lap_dat_array IS NULL OR array_length(p_vi_tri_lap_dat_array, 1) IS NULL OR location_name = ANY(p_vi_tri_lap_dat_array))
          AND (p_tinh_trang_array IS NULL OR array_length(p_tinh_trang_array, 1) IS NULL OR status_name = ANY(p_tinh_trang_array))
          AND (p_phan_loai_array IS NULL OR array_length(p_phan_loai_array, 1) IS NULL OR classification_name = ANY(p_phan_loai_array))
          AND (p_nguon_kinh_phi_array IS NULL OR array_length(p_nguon_kinh_phi_array, 1) IS NULL OR funding_source_name = ANY(p_nguon_kinh_phi_array))
        GROUP BY department_name
      ) bucket
    ), '[]'::jsonb),
    'user', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('name', bucket.name, 'count', bucket.count) ORDER BY bucket.count DESC, bucket.name)
      FROM (
        SELECT user_name AS name, COUNT(*)::integer AS count
        FROM base_equipment
        WHERE (p_khoa_phong_array IS NULL OR array_length(p_khoa_phong_array, 1) IS NULL OR department_name = ANY(p_khoa_phong_array))
          AND (p_vi_tri_lap_dat_array IS NULL OR array_length(p_vi_tri_lap_dat_array, 1) IS NULL OR location_name = ANY(p_vi_tri_lap_dat_array))
          AND (p_tinh_trang_array IS NULL OR array_length(p_tinh_trang_array, 1) IS NULL OR status_name = ANY(p_tinh_trang_array))
          AND (p_phan_loai_array IS NULL OR array_length(p_phan_loai_array, 1) IS NULL OR classification_name = ANY(p_phan_loai_array))
          AND (p_nguon_kinh_phi_array IS NULL OR array_length(p_nguon_kinh_phi_array, 1) IS NULL OR funding_source_name = ANY(p_nguon_kinh_phi_array))
        GROUP BY user_name
      ) bucket
    ), '[]'::jsonb),
    'location', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('name', bucket.name, 'count', bucket.count) ORDER BY bucket.count DESC, bucket.name)
      FROM (
        SELECT location_name AS name, COUNT(*)::integer AS count
        FROM base_equipment
        WHERE (p_khoa_phong_array IS NULL OR array_length(p_khoa_phong_array, 1) IS NULL OR department_name = ANY(p_khoa_phong_array))
          AND (p_nguoi_su_dung_array IS NULL OR array_length(p_nguoi_su_dung_array, 1) IS NULL OR user_name = ANY(p_nguoi_su_dung_array))
          AND (p_tinh_trang_array IS NULL OR array_length(p_tinh_trang_array, 1) IS NULL OR status_name = ANY(p_tinh_trang_array))
          AND (p_phan_loai_array IS NULL OR array_length(p_phan_loai_array, 1) IS NULL OR classification_name = ANY(p_phan_loai_array))
          AND (p_nguon_kinh_phi_array IS NULL OR array_length(p_nguon_kinh_phi_array, 1) IS NULL OR funding_source_name = ANY(p_nguon_kinh_phi_array))
        GROUP BY location_name
      ) bucket
    ), '[]'::jsonb),
    'status', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('name', bucket.name, 'count', bucket.count) ORDER BY bucket.count DESC, bucket.name)
      FROM (
        SELECT status_name AS name, COUNT(*)::integer AS count
        FROM base_equipment
        WHERE (p_khoa_phong_array IS NULL OR array_length(p_khoa_phong_array, 1) IS NULL OR department_name = ANY(p_khoa_phong_array))
          AND (p_nguoi_su_dung_array IS NULL OR array_length(p_nguoi_su_dung_array, 1) IS NULL OR user_name = ANY(p_nguoi_su_dung_array))
          AND (p_vi_tri_lap_dat_array IS NULL OR array_length(p_vi_tri_lap_dat_array, 1) IS NULL OR location_name = ANY(p_vi_tri_lap_dat_array))
          AND (p_phan_loai_array IS NULL OR array_length(p_phan_loai_array, 1) IS NULL OR classification_name = ANY(p_phan_loai_array))
          AND (p_nguon_kinh_phi_array IS NULL OR array_length(p_nguon_kinh_phi_array, 1) IS NULL OR funding_source_name = ANY(p_nguon_kinh_phi_array))
        GROUP BY status_name
      ) bucket
    ), '[]'::jsonb),
    'classification', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('name', bucket.name, 'count', bucket.count) ORDER BY bucket.count DESC, bucket.name)
      FROM (
        SELECT classification_name AS name, COUNT(*)::integer AS count
        FROM base_equipment
        WHERE (p_khoa_phong_array IS NULL OR array_length(p_khoa_phong_array, 1) IS NULL OR department_name = ANY(p_khoa_phong_array))
          AND (p_nguoi_su_dung_array IS NULL OR array_length(p_nguoi_su_dung_array, 1) IS NULL OR user_name = ANY(p_nguoi_su_dung_array))
          AND (p_vi_tri_lap_dat_array IS NULL OR array_length(p_vi_tri_lap_dat_array, 1) IS NULL OR location_name = ANY(p_vi_tri_lap_dat_array))
          AND (p_tinh_trang_array IS NULL OR array_length(p_tinh_trang_array, 1) IS NULL OR status_name = ANY(p_tinh_trang_array))
          AND (p_nguon_kinh_phi_array IS NULL OR array_length(p_nguon_kinh_phi_array, 1) IS NULL OR funding_source_name = ANY(p_nguon_kinh_phi_array))
        GROUP BY classification_name
      ) bucket
    ), '[]'::jsonb),
    'fundingSource', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('name', bucket.name, 'count', bucket.count) ORDER BY bucket.count DESC, bucket.name)
      FROM (
        SELECT funding_source_name AS name, COUNT(*)::integer AS count
        FROM base_equipment
        WHERE (p_khoa_phong_array IS NULL OR array_length(p_khoa_phong_array, 1) IS NULL OR department_name = ANY(p_khoa_phong_array))
          AND (p_nguoi_su_dung_array IS NULL OR array_length(p_nguoi_su_dung_array, 1) IS NULL OR user_name = ANY(p_nguoi_su_dung_array))
          AND (p_vi_tri_lap_dat_array IS NULL OR array_length(p_vi_tri_lap_dat_array, 1) IS NULL OR location_name = ANY(p_vi_tri_lap_dat_array))
          AND (p_tinh_trang_array IS NULL OR array_length(p_tinh_trang_array, 1) IS NULL OR status_name = ANY(p_tinh_trang_array))
          AND (p_phan_loai_array IS NULL OR array_length(p_phan_loai_array, 1) IS NULL OR classification_name = ANY(p_phan_loai_array))
        GROUP BY funding_source_name
      ) bucket
    ), '[]'::jsonb)
  )
  INTO v_result;

  RETURN COALESCE(v_result, v_empty_result);
END;
$$;


ALTER FUNCTION public.equipment_filter_buckets(p_q text, p_don_vi bigint, p_khoa_phong_array text[], p_nguoi_su_dung_array text[], p_vi_tri_lap_dat_array text[], p_tinh_trang_array text[], p_phan_loai_array text[], p_nguon_kinh_phi_array text[]) OWNER TO postgres;

--
-- Name: FUNCTION equipment_filter_buckets(p_q text, p_don_vi bigint, p_khoa_phong_array text[], p_nguoi_su_dung_array text[], p_vi_tri_lap_dat_array text[], p_tinh_trang_array text[], p_phan_loai_array text[], p_nguon_kinh_phi_array text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_filter_buckets(p_q text, p_don_vi bigint, p_khoa_phong_array text[], p_nguoi_su_dung_array text[], p_vi_tri_lap_dat_array text[], p_tinh_trang_array text[], p_phan_loai_array text[], p_nguon_kinh_phi_array text[]) IS 'Returns cascading equipment filter option buckets for the scoped Equipment result set.';


--
-- Name: equipment_filter_options(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_filter_options(p_filter_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB := '[]'::jsonb;
BEGIN
  CASE lower(p_filter_type)
    WHEN 'khoa_phong' THEN
      SELECT jsonb_agg(opt) INTO v_result FROM public.equipment_filter_options_khoa_phong() opt;
      
    WHEN 'nguoi_su_dung' THEN
      SELECT jsonb_agg(opt) INTO v_result FROM public.equipment_filter_options_nguoi_su_dung() opt;
      
    WHEN 'vi_tri_lap_dat' THEN
      SELECT jsonb_agg(opt) INTO v_result FROM public.equipment_filter_options_vi_tri_lap_dat() opt;
      
    WHEN 'tinh_trang' THEN
      SELECT jsonb_agg(opt) INTO v_result FROM public.equipment_filter_options_tinh_trang() opt;
      
    WHEN 'phan_loai' THEN
      SELECT jsonb_agg(opt) INTO v_result FROM public.equipment_filter_options_phan_loai() opt;
      
    ELSE
      -- Return all filter options if no specific type requested
      SELECT jsonb_build_object(
        'khoa_phong', (SELECT jsonb_agg(opt) FROM public.equipment_filter_options_khoa_phong() opt),
        'nguoi_su_dung', (SELECT jsonb_agg(opt) FROM public.equipment_filter_options_nguoi_su_dung() opt),
        'vi_tri_lap_dat', (SELECT jsonb_agg(opt) FROM public.equipment_filter_options_vi_tri_lap_dat() opt),
        'tinh_trang', (SELECT jsonb_agg(opt) FROM public.equipment_filter_options_tinh_trang() opt),
        'phan_loai', (SELECT jsonb_agg(opt) FROM public.equipment_filter_options_phan_loai() opt)
      ) INTO v_result;
  END CASE;
  
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.equipment_filter_options(p_filter_type text) OWNER TO postgres;

--
-- Name: equipment_filter_options_khoa_phong(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_filter_options_khoa_phong() RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_allowed_don_vi BIGINT[];
  v_effective_donvi BIGINT;
  v_jwt_claims JSONB;
  v_where TEXT := '1=1';
BEGIN
  -- Get JWT claims with fallback
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;
  
  -- Get role and claims
  v_role := COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  );
  
  -- Get allowed don_vi based on role
  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();
  
  -- Tenant isolation
  IF lower(v_role) = 'global' THEN
    v_effective_donvi := NULL; -- All tenants
  ELSE
    IF v_allowed_don_vi IS NOT NULL AND array_length(v_allowed_don_vi, 1) > 0 THEN
      v_effective_donvi := v_allowed_don_vi[1]; -- Use first allowed don_vi
    ELSE
      v_effective_donvi := NULL;
    END IF;
  END IF;

  -- Build WHERE clause for tenant filtering
  IF lower(v_role) = 'regional_leader' AND v_effective_donvi IS NULL THEN
    v_where := v_where || ' AND don_vi = ANY(' || quote_literal(v_allowed_don_vi) || ')';
  ELSIF v_effective_donvi IS NOT NULL THEN
    v_where := v_where || ' AND don_vi = ' || v_effective_donvi;
  END IF;

  RETURN QUERY
  SELECT jsonb_build_object('value', dept.khoa_phong_quan_ly, 'label', dept.khoa_phong_quan_ly)
  FROM (
    SELECT DISTINCT COALESCE(NULLIF(TRIM(khoa_phong_quan_ly), ''), 'Chưa phân loại') as khoa_phong_quan_ly
    FROM public.thiet_bi
    WHERE v_where
    ORDER BY khoa_phong_quan_ly
  ) dept;
END;
$$;


