--
-- Name: equipment_funding_sources_list_for_tenant(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_funding_sources_list_for_tenant(p_don_vi bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_user_id TEXT;
  v_allowed BIGINT[];
  v_effective BIGINT[];
  v_department_scope TEXT;
  v_jwt_claims JSONB;
BEGIN
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;

  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));
  v_user_id := NULLIF(v_jwt_claims ->> 'user_id', '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role = 'global' THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims ->> 'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN;
    END IF;
  END IF;

  RETURN QUERY
  SELECT jsonb_build_object(
    'name', COALESCE(NULLIF(TRIM(nguon_kinh_phi), ''), 'Chưa có'),
    'count', COUNT(*)::INTEGER
  )
  FROM public.thiet_bi tb
  WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
    AND tb.is_deleted = false
    AND (v_role <> 'user' OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope)
  GROUP BY COALESCE(NULLIF(TRIM(nguon_kinh_phi), ''), 'Chưa có')
  ORDER BY COUNT(*) DESC;
END;
$$;


ALTER FUNCTION public.equipment_funding_sources_list_for_tenant(p_don_vi bigint) OWNER TO postgres;

--
-- Name: equipment_get(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_get(p_id bigint) RETURNS public.thiet_bi
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(public._get_jwt_claim('user_id'), '');
  v_allowed BIGINT[] := public.allowed_don_vi_for_session();
  v_department_scope TEXT;
  rec public.thiet_bi;
BEGIN
  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(public._get_jwt_claim('khoa_phong'));
  END IF;

  IF v_role = 'global' THEN
    SELECT * INTO rec
    FROM public.thiet_bi
    WHERE id = p_id
      AND is_deleted = false;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RAISE EXCEPTION 'Equipment not found or access denied' USING ERRCODE = '42501';
    END IF;

    SELECT *
    INTO rec
    FROM public.thiet_bi
    WHERE id = p_id
      AND don_vi = ANY(v_allowed)
      AND is_deleted = false;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Equipment not found or access denied' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'user' THEN
    IF v_department_scope IS NULL
       OR public._normalize_department_scope(rec.khoa_phong_quan_ly) IS DISTINCT FROM v_department_scope THEN
      RAISE EXCEPTION 'Equipment not found or access denied' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN rec;
END;
$$;


ALTER FUNCTION public.equipment_get(p_id bigint) OWNER TO postgres;

--
-- Name: equipment_get_by_code(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_get_by_code(p_ma_thiet_bi text) RETURNS public.thiet_bi
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(public._get_jwt_claim('user_id'), '');
  v_allowed BIGINT[] := public.allowed_don_vi_for_session();
  v_department_scope TEXT;
  rec public.thiet_bi;
BEGIN
  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(public._get_jwt_claim('khoa_phong'));
  END IF;

  IF p_ma_thiet_bi IS NULL OR trim(p_ma_thiet_bi) = '' THEN
    RAISE EXCEPTION 'ma_thiet_bi_required' USING ERRCODE = '22023';
  END IF;

  IF v_role = 'global' THEN
    SELECT *
      INTO rec
    FROM public.thiet_bi
    WHERE lower(ma_thiet_bi) = lower(p_ma_thiet_bi)
      AND is_deleted = false
    LIMIT 1;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RAISE EXCEPTION 'Equipment not found or access denied' USING ERRCODE = '42501';
    END IF;

    SELECT *
      INTO rec
    FROM public.thiet_bi
    WHERE lower(ma_thiet_bi) = lower(p_ma_thiet_bi)
      AND don_vi = ANY(v_allowed)
      AND is_deleted = false
    LIMIT 1;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Equipment not found or access denied' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'user' THEN
    IF v_department_scope IS NULL
       OR public._normalize_department_scope(rec.khoa_phong_quan_ly) IS DISTINCT FROM v_department_scope THEN
      RAISE EXCEPTION 'Equipment not found or access denied' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN rec;
END;
$$;


