--
-- Name: equipment_list(text, text, integer, integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_list(p_q text DEFAULT NULL::text, p_sort text DEFAULT 'id.asc'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_don_vi bigint DEFAULT NULL::bigint) RETURNS SETOF public.thiet_bi
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(public._get_jwt_claim('user_id'), '');
  v_allowed BIGINT[] := public.allowed_don_vi_for_session();
  v_effective BIGINT[] := NULL;
  v_department_scope TEXT;
  v_sort_col TEXT;
  v_sort_dir TEXT;
  v_offset INT := GREATEST(p_page - 1, 0) * GREATEST(p_page_size, 1);
  v_sql TEXT;
  v_sanitized_q TEXT;
BEGIN
  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(public._get_jwt_claim('khoa_phong'));
  END IF;

  IF v_role = 'global' THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT p_don_vi = ANY(v_allowed) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_effective IS NOT NULL AND array_length(v_effective, 1) IS NULL THEN
    RETURN;
  END IF;

  IF v_role = 'user' AND v_department_scope IS NULL THEN
    RETURN;
  END IF;

  v_sort_col := split_part(p_sort, '.', 1);
  v_sort_dir := CASE LOWER(split_part(p_sort, '.', 2)) WHEN 'desc' THEN 'DESC' ELSE 'ASC' END;
  IF v_sort_col NOT IN (
    'id','ten_thiet_bi','ma_thiet_bi','khoa_phong_quan_ly','don_vi','tinh_trang_hien_tai','phan_loai_theo_nd98','model','serial'
  ) THEN
    v_sort_col := 'id';
  END IF;

  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  v_sql := 'SELECT * FROM public.thiet_bi WHERE is_deleted = false';
  IF v_effective IS NOT NULL THEN
    v_sql := v_sql || format(' AND don_vi = ANY(%L::BIGINT[])', v_effective);
  END IF;

  IF v_role = 'user' THEN
    v_sql := v_sql || format(
      ' AND public._normalize_department_scope(khoa_phong_quan_ly) = %L',
      v_department_scope
    );
  END IF;

  IF v_sanitized_q IS NOT NULL THEN
    v_sql := v_sql || format(' AND (ten_thiet_bi ILIKE %L OR ma_thiet_bi ILIKE %L)',
      '%' || v_sanitized_q || '%', '%' || v_sanitized_q || '%');
  END IF;

  v_sql := v_sql || format(' ORDER BY %I %s OFFSET %s LIMIT %s', v_sort_col, v_sort_dir, v_offset, GREATEST(p_page_size, 1));

  RETURN QUERY EXECUTE v_sql;
END;
$$;


ALTER FUNCTION public.equipment_list(p_q text, p_sort text, p_page integer, p_page_size integer, p_don_vi bigint) OWNER TO postgres;

--
-- Name: equipment_list_enhanced(text, text, integer, integer, bigint, text, text[], text, text[], text, text[], text, text[], text, text[], text, text[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_list_enhanced(p_q text DEFAULT NULL::text, p_sort text DEFAULT 'id.asc'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_don_vi bigint DEFAULT NULL::bigint, p_khoa_phong text DEFAULT NULL::text, p_khoa_phong_array text[] DEFAULT NULL::text[], p_nguoi_su_dung text DEFAULT NULL::text, p_nguoi_su_dung_array text[] DEFAULT NULL::text[], p_vi_tri_lap_dat text DEFAULT NULL::text, p_vi_tri_lap_dat_array text[] DEFAULT NULL::text[], p_tinh_trang text DEFAULT NULL::text, p_tinh_trang_array text[] DEFAULT NULL::text[], p_phan_loai text DEFAULT NULL::text, p_phan_loai_array text[] DEFAULT NULL::text[], p_nguon_kinh_phi text DEFAULT NULL::text, p_nguon_kinh_phi_array text[] DEFAULT NULL::text[], p_liquidation_last boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := '';
  v_user_id TEXT := NULL;
  v_claim_donvi BIGINT := NULL;
  v_allowed_don_vi BIGINT[];
  v_effective_donvi BIGINT := NULL;
  v_department_scope TEXT;
  v_sort_col TEXT := 'id';
  v_sort_dir TEXT := 'ASC';
  v_order_by TEXT;
  v_limit INT := GREATEST(p_page_size, 1);
  v_offset INT := GREATEST(p_page - 1, 0) * GREATEST(p_page_size, 1);
  v_where TEXT := '1=1 AND is_deleted = false';
  v_total BIGINT := 0;
  v_data JSONB := '[]'::jsonb;
  v_jwt_claims JSONB;
  v_sanitized_q TEXT;
  v_unclassified_label CONSTANT TEXT := 'Chưa phân loại';
  v_empty_user_label CONSTANT TEXT := 'Chưa có người sử dụng';
  v_empty_location_label CONSTANT TEXT := 'Chưa có vị trí';
BEGIN
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;

  v_role := COALESCE(
    v_jwt_claims ->>'app_role',
    v_jwt_claims ->>'role',
    ''
  );
  v_user_id := NULLIF(v_jwt_claims ->>'user_id', '');
  v_claim_donvi := NULLIF(v_jwt_claims ->>'don_vi', '')::BIGINT;

  IF lower(v_role) = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  IF lower(v_role) = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims ->>'khoa_phong');
  END IF;

  IF p_sort IS NOT NULL AND p_sort != '' THEN
    v_sort_col := split_part(p_sort, '.', 1);
    v_sort_dir := UPPER(COALESCE(NULLIF(split_part(p_sort, '.', 2), ''), 'ASC'));
    IF v_sort_dir NOT IN ('ASC', 'DESC') THEN
      v_sort_dir := 'ASC';
    END IF;
    IF v_sort_col NOT IN (
      'id', 'ma_thiet_bi', 'ten_thiet_bi', 'model', 'serial',
      'khoa_phong_quan_ly', 'tinh_trang_hien_tai', 'vi_tri_lap_dat',
      'nguoi_dang_truc_tiep_quan_ly', 'phan_loai_theo_nd98', 'nguon_kinh_phi', 'don_vi',
      'gia_goc', 'ngay_nhap', 'ngay_dua_vao_su_dung', 'ngay_bt_tiep_theo',
      'so_luu_hanh'
    ) THEN
      v_sort_col := 'id';
    END IF;
  END IF;

  IF p_liquidation_last THEN
    v_order_by := format(
      'CASE
         WHEN public._normalize_department_scope(tb.khoa_phong_quan_ly)
                = public._normalize_department_scope(''VT-TBYT- KHO THANH LÍ'')
          AND btrim(tb.tinh_trang_hien_tai) = ''Ngưng sử dụng''
         THEN 1
         ELSE 0
       END ASC,
       CASE
         WHEN public._normalize_department_scope(tb.khoa_phong_quan_ly)
                = public._normalize_department_scope(''VT-TBYT- KHO THANH LÍ'')
          AND btrim(tb.tinh_trang_hien_tai) = ''Ngưng sử dụng''
         THEN COALESCE(NULLIF(btrim(tb.ngay_ngung_su_dung), ''''), '''')
         ELSE ''''
       END ASC,
       tb.%I %s,
       tb.id ASC',
      v_sort_col,
      v_sort_dir
    );
  ELSE
    v_order_by := format('tb.%I %s', v_sort_col, v_sort_dir);
  END IF;

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  IF lower(v_role) IN ('global', 'admin') THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective_donvi := p_don_vi;
    ELSE
      v_effective_donvi := NULL;
    END IF;
  ELSE
    IF v_allowed_don_vi IS NOT NULL AND array_length(v_allowed_don_vi, 1) > 0 THEN
      IF p_don_vi IS NOT NULL THEN
        IF p_don_vi = ANY(v_allowed_don_vi) THEN
          v_effective_donvi := p_don_vi;
        ELSE
          RETURN jsonb_build_object('data', '[]'::jsonb, 'total', 0, 'page', p_page, 'pageSize', p_page_size, 'error', 'Access denied for tenant');
        END IF;
      ELSE
        v_effective_donvi := NULL;
      END IF;
    ELSE
      RETURN jsonb_build_object('data', '[]'::jsonb, 'total', 0, 'page', p_page, 'pageSize', p_page_size, 'error', 'No tenant access');
    END IF;
  END IF;

  IF lower(v_role) = 'user' AND v_department_scope IS NULL THEN
    RETURN jsonb_build_object('data', '[]'::jsonb, 'total', 0, 'page', p_page, 'pageSize', p_page_size);
  END IF;

  IF v_effective_donvi IS NOT NULL THEN
    v_where := v_where || ' AND don_vi = ' || v_effective_donvi;
  END IF;

  IF v_effective_donvi IS NULL AND lower(v_role) NOT IN ('global', 'admin') AND v_allowed_don_vi IS NOT NULL THEN
    v_where := v_where || ' AND don_vi = ANY(ARRAY[' || array_to_string(v_allowed_don_vi, ',') || '])';
  END IF;

  IF lower(v_role) = 'user' THEN
    v_where := v_where || ' AND public._normalize_department_scope(khoa_phong_quan_ly) = '
      || quote_literal(v_department_scope);
  END IF;

  IF p_khoa_phong_array IS NOT NULL AND array_length(p_khoa_phong_array, 1) > 0 THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(khoa_phong_quan_ly), ''''), ' || quote_literal(v_unclassified_label) || ') = ANY(ARRAY[' ||
               array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_khoa_phong_array) AS x), ',') || '])';
  ELSIF p_khoa_phong IS NOT NULL AND trim(p_khoa_phong) != '' THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(khoa_phong_quan_ly), ''''), ' || quote_literal(v_unclassified_label) || ') = ' || quote_literal(p_khoa_phong);
  END IF;

  IF p_nguoi_su_dung_array IS NOT NULL AND array_length(p_nguoi_su_dung_array, 1) > 0 THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(nguoi_dang_truc_tiep_quan_ly), ''''), ' || quote_literal(v_empty_user_label) || ') = ANY(ARRAY[' ||
               array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_nguoi_su_dung_array) AS x), ',') || '])';
  ELSIF p_nguoi_su_dung IS NOT NULL AND trim(p_nguoi_su_dung) != '' THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(nguoi_dang_truc_tiep_quan_ly), ''''), ' || quote_literal(v_empty_user_label) || ') = ' || quote_literal(p_nguoi_su_dung);
  END IF;

  IF p_vi_tri_lap_dat_array IS NOT NULL AND array_length(p_vi_tri_lap_dat_array, 1) > 0 THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(vi_tri_lap_dat), ''''), ' || quote_literal(v_empty_location_label) || ') = ANY(ARRAY[' ||
               array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_vi_tri_lap_dat_array) AS x), ',') || '])';
  ELSIF p_vi_tri_lap_dat IS NOT NULL AND trim(p_vi_tri_lap_dat) != '' THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(vi_tri_lap_dat), ''''), ' || quote_literal(v_empty_location_label) || ') = ' || quote_literal(p_vi_tri_lap_dat);
  END IF;

  IF p_tinh_trang_array IS NOT NULL AND array_length(p_tinh_trang_array, 1) > 0 THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(tinh_trang_hien_tai), ''''), ' || quote_literal(v_unclassified_label) || ') = ANY(ARRAY[' ||
               array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_tinh_trang_array) AS x), ',') || '])';
  ELSIF p_tinh_trang IS NOT NULL AND trim(p_tinh_trang) != '' THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(tinh_trang_hien_tai), ''''), ' || quote_literal(v_unclassified_label) || ') = ' || quote_literal(p_tinh_trang);
  END IF;

  IF p_phan_loai_array IS NOT NULL AND array_length(p_phan_loai_array, 1) > 0 THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(phan_loai_theo_nd98), ''''), ' || quote_literal(v_unclassified_label) || ') = ANY(ARRAY[' ||
               array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_phan_loai_array) AS x), ',') || '])';
  ELSIF p_phan_loai IS NOT NULL AND trim(p_phan_loai) != '' THEN
    v_where := v_where || ' AND COALESCE(NULLIF(TRIM(phan_loai_theo_nd98), ''''), ' || quote_literal(v_unclassified_label) || ') = ' || quote_literal(p_phan_loai);
  END IF;

  IF p_nguon_kinh_phi_array IS NOT NULL AND array_length(p_nguon_kinh_phi_array, 1) > 0 THEN
    IF 'Chưa có' = ANY(p_nguon_kinh_phi_array) THEN
      DECLARE v_non_empty_sources TEXT[];
      BEGIN
        SELECT ARRAY(SELECT x FROM unnest(p_nguon_kinh_phi_array) AS x WHERE x != 'Chưa có') INTO v_non_empty_sources;
        IF v_non_empty_sources IS NOT NULL AND array_length(v_non_empty_sources, 1) > 0 THEN
          v_where := v_where || ' AND (nguon_kinh_phi IS NULL OR TRIM(nguon_kinh_phi) = '''' OR TRIM(nguon_kinh_phi) = ANY(ARRAY[' ||
            array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(v_non_empty_sources) AS x), ',') || ']))';
        ELSE
          v_where := v_where || ' AND (nguon_kinh_phi IS NULL OR TRIM(nguon_kinh_phi) = '''')';
        END IF;
      END;
    ELSE
      v_where := v_where || ' AND TRIM(nguon_kinh_phi) = ANY(ARRAY[' ||
        array_to_string(ARRAY(SELECT quote_literal(x) FROM unnest(p_nguon_kinh_phi_array) AS x), ',') || '])';
    END IF;
  ELSIF p_nguon_kinh_phi IS NOT NULL AND trim(p_nguon_kinh_phi) != '' THEN
    IF p_nguon_kinh_phi = 'Chưa có' THEN
      v_where := v_where || ' AND (nguon_kinh_phi IS NULL OR TRIM(nguon_kinh_phi) = '''')';
    ELSE
      v_where := v_where || ' AND TRIM(nguon_kinh_phi) = ' || quote_literal(p_nguon_kinh_phi);
    END IF;
  END IF;

  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  IF v_sanitized_q IS NOT NULL THEN
    v_where := v_where || ' AND (ten_thiet_bi ILIKE ' || quote_literal('%' || v_sanitized_q || '%') ||
              ' OR ma_thiet_bi ILIKE ' || quote_literal('%' || v_sanitized_q || '%') ||
              ' OR serial ILIKE ' || quote_literal('%' || v_sanitized_q || '%') ||
              ' OR so_luu_hanh ILIKE ' || quote_literal('%' || v_sanitized_q || '%') ||
              ' OR model ILIKE ' || quote_literal('%' || v_sanitized_q || '%') || ')';
  END IF;

  EXECUTE format('SELECT count(*) FROM public.thiet_bi WHERE %s', v_where) INTO v_total;

  EXECUTE format(
    'SELECT COALESCE(jsonb_agg(t), ''[]''::jsonb) FROM (
       SELECT (jsonb_build_object(
         ''ma_thiet_bi'', tb.ma_thiet_bi,
         ''ten_thiet_bi'', tb.ten_thiet_bi,
         ''model'', tb.model,
         ''serial'', tb.serial,
         ''cau_hinh_thiet_bi'', tb.cau_hinh_thiet_bi,
         ''phu_kien_kem_theo'', tb.phu_kien_kem_theo,
         ''hang_san_xuat'', tb.hang_san_xuat,
         ''noi_san_xuat'', tb.noi_san_xuat,
         ''nam_san_xuat'', tb.nam_san_xuat,
         ''ngay_nhap'', tb.ngay_nhap,
         ''ngay_dua_vao_su_dung'', tb.ngay_dua_vao_su_dung,
         ''nguon_kinh_phi'', tb.nguon_kinh_phi,
         ''gia_goc'', tb.gia_goc,
         ''nam_tinh_hao_mon'', tb.nam_tinh_hao_mon,
         ''ty_le_hao_mon'', tb.ty_le_hao_mon,
         ''han_bao_hanh'', tb.han_bao_hanh,
         ''vi_tri_lap_dat'', tb.vi_tri_lap_dat,
         ''nguoi_dang_truc_tiep_quan_ly'', tb.nguoi_dang_truc_tiep_quan_ly,
         ''khoa_phong_quan_ly'', tb.khoa_phong_quan_ly,
         ''tinh_trang_hien_tai'', tb.tinh_trang_hien_tai,
         ''ghi_chu'', tb.ghi_chu,
         ''chu_ky_bt_dinh_ky'', tb.chu_ky_bt_dinh_ky,
         ''ngay_bt_tiep_theo'', tb.ngay_bt_tiep_theo,
         ''chu_ky_hc_dinh_ky'', tb.chu_ky_hc_dinh_ky,
         ''ngay_hc_tiep_theo'', tb.ngay_hc_tiep_theo,
         ''chu_ky_kd_dinh_ky'', tb.chu_ky_kd_dinh_ky,
         ''ngay_kd_tiep_theo'', tb.ngay_kd_tiep_theo,
         ''phan_loai_theo_nd98'', tb.phan_loai_theo_nd98,
         ''id'', tb.id,
         ''created_at'', tb.created_at,
         ''don_vi'', tb.don_vi,
         ''nguon_nhap'', tb.nguon_nhap,
         ''so_luu_hanh'', tb.so_luu_hanh,
         ''nhom_thiet_bi_id'', tb.nhom_thiet_bi_id,
         ''is_deleted'', tb.is_deleted,
         ''ngay_ngung_su_dung'', tb.ngay_ngung_su_dung,
         ''google_drive_folder_url'', dv.google_drive_folder_url,
         ''don_vi_name'', dv.name,
         ''active_repair_request_id'', ar.active_id
       )) AS t
       FROM public.thiet_bi tb
       LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
       LEFT JOIN LATERAL (
         SELECT r.id AS active_id
         FROM public.yeu_cau_sua_chua r
         WHERE r.thiet_bi_id = tb.id
           AND r.trang_thai IN (''Chờ xử lý'', ''Đã duyệt'')
         ORDER BY r.ngay_yeu_cau DESC, r.id DESC
         LIMIT 1
       ) ar ON TRUE
       WHERE %s
       ORDER BY %s
       OFFSET %s LIMIT %s
     ) sub',
    v_where, v_order_by, v_offset, v_limit
  ) INTO v_data;

  RETURN jsonb_build_object(
    'data', v_data,
    'total', v_total,
    'page', p_page,
    'pageSize', p_page_size
  );
END;
$$;


ALTER FUNCTION public.equipment_list_enhanced(p_q text, p_sort text, p_page integer, p_page_size integer, p_don_vi bigint, p_khoa_phong text, p_khoa_phong_array text[], p_nguoi_su_dung text, p_nguoi_su_dung_array text[], p_vi_tri_lap_dat text, p_vi_tri_lap_dat_array text[], p_tinh_trang text, p_tinh_trang_array text[], p_phan_loai text, p_phan_loai_array text[], p_nguon_kinh_phi text, p_nguon_kinh_phi_array text[], p_liquidation_last boolean) OWNER TO postgres;

--
-- Name: equipment_list_for_reports(text, text, integer, integer, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_list_for_reports(p_q text DEFAULT NULL::text, p_sort text DEFAULT 'id.asc'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 10000, p_don_vi bigint DEFAULT NULL::bigint, p_khoa_phong text DEFAULT NULL::text) RETURNS SETOF public.thiet_bi
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role text;
  v_user_id text;
  v_allowed bigint[];
  v_effective_donvi bigint;
  v_sort_col text;
  v_sort_dir text;
  v_offset int;
  v_limit int;
  v_sanitized_q text;
  v_department_scope text;
  v_requested_department_scope text;
BEGIN
  v_role := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id := NULLIF(public._get_jwt_claim('user_id'), '');
  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi;
  ELSIF v_role = 'regional_leader' THEN
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF p_don_vi = ANY(v_allowed) THEN
        v_effective_donvi := p_don_vi;
      ELSE
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
    ELSE
      v_effective_donvi := NULLIF(public._get_jwt_claim('don_vi'), '')::bigint;
      IF v_effective_donvi IS NULL THEN
        RETURN;
      END IF;
    END IF;
  ELSE
    v_effective_donvi := NULLIF(public._get_jwt_claim('don_vi'), '')::bigint;
    IF v_effective_donvi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim for role %', v_role USING ERRCODE = '42501';
    END IF;

    IF p_don_vi IS NOT NULL AND p_don_vi != v_effective_donvi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(public._get_jwt_claim('khoa_phong'));
    IF v_department_scope IS NULL THEN
      RETURN;
    END IF;

    IF p_khoa_phong IS NOT NULL THEN
      v_requested_department_scope := public._normalize_department_scope(p_khoa_phong);
      IF v_requested_department_scope IS DISTINCT FROM v_department_scope THEN
        RETURN;
      END IF;
    END IF;
  END IF;

  v_sort_col := split_part(p_sort, '.', 1);
  v_sort_dir := CASE lower(split_part(p_sort, '.', 2)) WHEN 'desc' THEN 'DESC' ELSE 'ASC' END;
  IF v_sort_col NOT IN ('id', 'ten_thiet_bi', 'ma_thiet_bi', 'khoa_phong_quan_ly', 'don_vi') THEN
    v_sort_col := 'id';
  END IF;

  v_limit := GREATEST(COALESCE(p_page_size, 10000), 1);
  v_offset := GREATEST((p_page - 1), 0) * v_limit;
  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  RETURN QUERY EXECUTE format(
    'SELECT * FROM public.thiet_bi
     WHERE is_deleted = false
       AND ($1::bigint IS NULL OR don_vi = $1)
       AND (
         ($7::text IS NOT NULL AND public._normalize_department_scope(khoa_phong_quan_ly) = $7)
         OR
         ($7::text IS NULL AND ($2::text IS NULL OR khoa_phong_quan_ly = $2))
       )
       AND ($3::text IS NULL OR ten_thiet_bi ILIKE $5 OR ma_thiet_bi ILIKE $5)
     ORDER BY %I %s
     OFFSET $4 LIMIT $6',
    v_sort_col,
    v_sort_dir
  ) USING
    v_effective_donvi,
    p_khoa_phong,
    v_sanitized_q,
    v_offset,
    ('%' || COALESCE(v_sanitized_q, '') || '%'),
    v_limit,
    CASE WHEN v_role = 'user' THEN v_department_scope ELSE NULL END;
END;
$_$;


ALTER FUNCTION public.equipment_list_for_reports(p_q text, p_sort text, p_page integer, p_page_size integer, p_don_vi bigint, p_khoa_phong text) OWNER TO postgres;

--
-- Name: FUNCTION equipment_list_for_reports(p_q text, p_sort text, p_page integer, p_page_size integer, p_don_vi bigint, p_khoa_phong text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_list_for_reports(p_q text, p_sort text, p_page integer, p_page_size integer, p_don_vi bigint, p_khoa_phong text) IS 'Returns equipment list for reports with tenant and department filtering.
FIXED: Added regional_leader support with allowed_don_vi_for_session_safe() validation.';


--
-- Name: equipment_locations_list_for_tenant(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_locations_list_for_tenant(p_don_vi bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_user_id TEXT;
  v_allowed BIGINT[];
  v_effective BIGINT[];
  v_department_scope TEXT;
  v_jwt_claims JSONB;
BEGIN
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;

  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));
  v_user_id := NULLIF(v_jwt_claims ->> 'user_id', '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role = 'global' THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF v_allowed IS NULL OR NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims ->> 'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN;
    END IF;
  END IF;

  RETURN QUERY
  SELECT jsonb_build_object(
    'name', COALESCE(NULLIF(TRIM(vi_tri_lap_dat), ''), 'Chưa có vị trí'),
    'count', COUNT(*)::INTEGER
  )
  FROM public.thiet_bi tb
  WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
    AND tb.is_deleted = false
    AND (v_role <> 'user' OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope)
  GROUP BY COALESCE(NULLIF(TRIM(vi_tri_lap_dat), ''), 'Chưa có vị trí')
  ORDER BY COUNT(*) DESC;
END;
$$;


ALTER FUNCTION public.equipment_locations_list_for_tenant(p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION equipment_locations_list_for_tenant(p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_locations_list_for_tenant(p_don_vi bigint) IS 'Returns location list for tenant equipment. FIXED: Now uses consistent JWT claim reading.';


--
-- Name: equipment_restore(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_restore(p_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := NULLIF(public._get_jwt_claim('user_id'), '')::BIGINT;
  v_code TEXT;
  v_name TEXT;
  v_row_don_vi BIGINT;
  v_is_deleted BOOLEAN;
  v_tenant_active BOOLEAN;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role <> 'global' AND v_donvi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('global', 'to_qltb') THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = '42501';
  END IF;

  SELECT tb.ma_thiet_bi, tb.ten_thiet_bi, tb.don_vi, tb.is_deleted
  INTO v_code, v_name, v_row_don_vi, v_is_deleted
  FROM public.thiet_bi tb
  WHERE tb.id = p_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Equipment not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_role <> 'global' AND v_row_don_vi IS DISTINCT FROM v_donvi THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  IF v_is_deleted IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Equipment not found or not deleted' USING ERRCODE = 'P0002';
  END IF;

  IF v_row_don_vi IS NULL THEN
    RAISE EXCEPTION 'Cannot restore equipment without tenant assignment'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT dv.active INTO v_tenant_active
  FROM public.don_vi dv WHERE dv.id = v_row_don_vi;

  IF NOT FOUND OR v_tenant_active IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Cannot restore equipment because tenant is missing or inactive'
      USING ERRCODE = 'P0001';
  END IF;

  IF v_code IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.thiet_bi
    WHERE lower(ma_thiet_bi) = lower(v_code)
      AND is_deleted = false
      AND id <> p_id
  ) THEN
    RAISE EXCEPTION 'Cannot restore: equipment code "%" is already in use by active equipment', v_code
      USING ERRCODE = '23505';
  END IF;

  UPDATE public.thiet_bi
  SET is_deleted = false
  WHERE id = p_id AND is_deleted = true
    AND (v_role = 'global' OR don_vi = v_donvi);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Equipment not found or already restored' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.audit_log(
    p_action_type := 'equipment_restore',
    p_entity_type := 'equipment',
    p_entity_id := p_id,
    p_entity_label := COALESCE(v_code, v_name, 'equipment-' || p_id::text),
    p_action_details := jsonb_build_object(
      'restored', true, 'id', p_id,
      'ma_thiet_bi', v_code, 'ten_thiet_bi', v_name, 'don_vi', v_row_don_vi
    )
  );

  RETURN jsonb_build_object('success', true, 'id', p_id, 'restored', true);
END;
$$;


ALTER FUNCTION public.equipment_restore(p_id bigint) OWNER TO postgres;

--
-- Name: equipment_status_distribution(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_status_distribution(p_don_vi bigint DEFAULT NULL::bigint, p_khoa_phong text DEFAULT NULL::text, p_vi_tri text DEFAULT NULL::text) RETURNS TABLE(tinh_trang text, so_luong bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_allowed bigint[];
  v_effective_donvi bigint;
BEGIN
  v_role := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi;
  ELSIF v_role = 'regional_leader' THEN
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF p_don_vi = ANY(v_allowed) THEN
        v_effective_donvi := p_don_vi;
      ELSE
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
    ELSE
      RETURN;
    END IF;
  ELSE
    v_effective_donvi := NULLIF(public._get_jwt_claim('don_vi'), '')::bigint;
    IF v_effective_donvi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim for role %', v_role USING ERRCODE = '42501';
    END IF;

    IF p_don_vi IS NOT NULL AND p_don_vi != v_effective_donvi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    COALESCE(NULLIF(TRIM(tb.tinh_trang_hien_tai), ''), U&'Kh\00F4ng x\00E1c \0111\1ECBnh') AS tinh_trang,
    COUNT(tb.id)::bigint AS so_luong
  FROM public.thiet_bi tb
  WHERE tb.is_deleted = false
    AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)
    AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong)
    AND (p_vi_tri IS NULL OR tb.vi_tri_lap_dat = p_vi_tri)
  GROUP BY COALESCE(NULLIF(TRIM(tb.tinh_trang_hien_tai), ''), U&'Kh\00F4ng x\00E1c \0111\1ECBnh')
  ORDER BY so_luong DESC;
END;
$$;


ALTER FUNCTION public.equipment_status_distribution(p_don_vi bigint, p_khoa_phong text, p_vi_tri text) OWNER TO postgres;

--
-- Name: equipment_status_distribution(text, bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_status_distribution(p_q text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_khoa_phong text DEFAULT NULL::text, p_vi_tri text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_allowed bigint[];
  v_effective_donvi bigint;
  v_search text := NULL;
  result jsonb;
BEGIN
  v_role := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role IN ('global', 'admin') THEN
    v_effective_donvi := p_don_vi;
  ELSIF v_role = 'regional_leader' THEN
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN jsonb_build_object(
        'total_equipment', 0,
        'status_counts', jsonb_build_object(
          'hoat_dong', 0,
          'cho_sua_chua', 0,
          'cho_bao_tri', 0,
          'cho_hieu_chuan', 0,
          'ngung_su_dung', 0,
          'chua_co_nhu_cau', 0
        ),
        'by_department', '[]'::jsonb,
        'by_location', '[]'::jsonb,
        'departments', '[]'::jsonb,
        'locations', '[]'::jsonb
      );
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF p_don_vi = ANY(v_allowed) THEN
        v_effective_donvi := p_don_vi;
      ELSE
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
    ELSE
      RETURN jsonb_build_object(
        'total_equipment', 0,
        'status_counts', jsonb_build_object(
          'hoat_dong', 0,
          'cho_sua_chua', 0,
          'cho_bao_tri', 0,
          'cho_hieu_chuan', 0,
          'ngung_su_dung', 0,
          'chua_co_nhu_cau', 0
        ),
        'by_department', '[]'::jsonb,
        'by_location', '[]'::jsonb,
        'departments', '[]'::jsonb,
        'locations', '[]'::jsonb
      );
    END IF;
  ELSE
    v_effective_donvi := NULLIF(public._get_jwt_claim('don_vi'), '')::bigint;
    IF v_effective_donvi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim for role %', v_role USING ERRCODE = '42501';
    END IF;

    IF p_don_vi IS NOT NULL AND p_don_vi != v_effective_donvi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
  END IF;

  IF p_q IS NOT NULL AND length(trim(p_q)) > 0 THEN
    v_search := '%' || public._sanitize_ilike_pattern(p_q) || '%';
  END IF;

  WITH filtered AS (
    SELECT
      tb.*,
      COALESCE(NULLIF(trim(tb.khoa_phong_quan_ly), ''), U&'Ch\01B0a ph\00E2n lo\1EA1i') AS department_name,
      COALESCE(NULLIF(trim(tb.vi_tri_lap_dat), ''), U&'Ch\01B0a x\00E1c \0111\1ECBnh') AS location_name,
      NULLIF(trim(COALESCE(tb.tinh_trang_hien_tai, '')), '') AS raw_status
    FROM public.thiet_bi tb
    WHERE tb.is_deleted = false
      AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)
      AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong)
      AND (p_vi_tri IS NULL OR tb.vi_tri_lap_dat = p_vi_tri)
      AND (
        v_search IS NULL
        OR tb.ten_thiet_bi ILIKE v_search
        OR tb.ma_thiet_bi ILIKE v_search
      )
  ), mapped AS (
    SELECT
      f.*,
      CASE
        WHEN raw_status IS NULL THEN 'hoat_dong'
        WHEN raw_status ILIKE '%Hoạt động%' OR raw_status ILIKE '%Hoat dong%' OR raw_status ILIKE '%đang sử%' OR raw_status ILIKE '%dang su%' THEN 'hoat_dong'
        WHEN raw_status ILIKE '%sửa chữa%' OR raw_status ILIKE '%sua chua%' OR raw_status ILIKE '%sửa%' OR raw_status ILIKE '%sua%' THEN 'cho_sua_chua'
        WHEN raw_status ILIKE '%bảo trì%' OR raw_status ILIKE '%bao tri%' THEN 'cho_bao_tri'
        WHEN raw_status ILIKE '%hiệu chuẩn%' OR raw_status ILIKE '%hieu chuan%' OR raw_status ILIKE '%kiểm định%' OR raw_status ILIKE '%kiem dinh%' OR raw_status ILIKE '%HC/KD%' THEN 'cho_hieu_chuan'
        WHEN raw_status ILIKE '%ngưng%' OR raw_status ILIKE '%ngung%' OR raw_status ILIKE '%stop%' THEN 'ngung_su_dung'
        WHEN raw_status ILIKE '%chưa có nhu cầu%' OR raw_status ILIKE '%chua co nhu cau%' THEN 'chua_co_nhu_cau'
        ELSE 'hoat_dong'
      END AS status_key
    FROM filtered f
  ), totals AS (
    SELECT
      COUNT(*)::int AS total_equipment,
      COUNT(*) FILTER (WHERE status_key = 'hoat_dong')::int AS hoat_dong,
      COUNT(*) FILTER (WHERE status_key = 'cho_sua_chua')::int AS cho_sua_chua,
      COUNT(*) FILTER (WHERE status_key = 'cho_bao_tri')::int AS cho_bao_tri,
      COUNT(*) FILTER (WHERE status_key = 'cho_hieu_chuan')::int AS cho_hieu_chuan,
      COUNT(*) FILTER (WHERE status_key = 'ngung_su_dung')::int AS ngung_su_dung,
      COUNT(*) FILTER (WHERE status_key = 'chua_co_nhu_cau')::int AS chua_co_nhu_cau
    FROM mapped
  )
  SELECT jsonb_build_object(
    'total_equipment', totals.total_equipment,
    'status_counts', jsonb_build_object(
      'hoat_dong', totals.hoat_dong,
      'cho_sua_chua', totals.cho_sua_chua,
      'cho_bao_tri', totals.cho_bao_tri,
      'cho_hieu_chuan', totals.cho_hieu_chuan,
      'ngung_su_dung', totals.ngung_su_dung,
      'chua_co_nhu_cau', totals.chua_co_nhu_cau
    ),
    'by_department', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'name', d.department_name,
          'total', d.total,
          'hoat_dong', d.hoat_dong,
          'cho_sua_chua', d.cho_sua_chua,
          'cho_bao_tri', d.cho_bao_tri,
          'cho_hieu_chuan', d.cho_hieu_chuan,
          'ngung_su_dung', d.ngung_su_dung,
          'chua_co_nhu_cau', d.chua_co_nhu_cau
        )
      )
      FROM (
        SELECT
          department_name,
          COUNT(*)::int AS total,
          COUNT(*) FILTER (WHERE status_key = 'hoat_dong')::int AS hoat_dong,
          COUNT(*) FILTER (WHERE status_key = 'cho_sua_chua')::int AS cho_sua_chua,
          COUNT(*) FILTER (WHERE status_key = 'cho_bao_tri')::int AS cho_bao_tri,
          COUNT(*) FILTER (WHERE status_key = 'cho_hieu_chuan')::int AS cho_hieu_chuan,
          COUNT(*) FILTER (WHERE status_key = 'ngung_su_dung')::int AS ngung_su_dung,
          COUNT(*) FILTER (WHERE status_key = 'chua_co_nhu_cau')::int AS chua_co_nhu_cau
        FROM mapped
        GROUP BY department_name
        ORDER BY total DESC
      ) d
    ), '[]'::jsonb),
    'by_location', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'name', l.location_name,
          'total', l.total,
          'hoat_dong', l.hoat_dong,
          'cho_sua_chua', l.cho_sua_chua,
          'cho_bao_tri', l.cho_bao_tri,
          'cho_hieu_chuan', l.cho_hieu_chuan,
          'ngung_su_dung', l.ngung_su_dung,
          'chua_co_nhu_cau', l.chua_co_nhu_cau
        )
      )
      FROM (
        SELECT
          location_name,
          COUNT(*)::int AS total,
          COUNT(*) FILTER (WHERE status_key = 'hoat_dong')::int AS hoat_dong,
          COUNT(*) FILTER (WHERE status_key = 'cho_sua_chua')::int AS cho_sua_chua,
          COUNT(*) FILTER (WHERE status_key = 'cho_bao_tri')::int AS cho_bao_tri,
          COUNT(*) FILTER (WHERE status_key = 'cho_hieu_chuan')::int AS cho_hieu_chuan,
          COUNT(*) FILTER (WHERE status_key = 'ngung_su_dung')::int AS ngung_su_dung,
          COUNT(*) FILTER (WHERE status_key = 'chua_co_nhu_cau')::int AS chua_co_nhu_cau
        FROM mapped
        GROUP BY location_name
        ORDER BY total DESC
      ) l
    ), '[]'::jsonb),
    'departments', COALESCE((
      SELECT jsonb_agg(name ORDER BY name)
      FROM (SELECT DISTINCT department_name AS name FROM mapped) AS dept_lookup
    ), '[]'::jsonb),
    'locations', COALESCE((
      SELECT jsonb_agg(name ORDER BY name)
      FROM (SELECT DISTINCT location_name AS name FROM mapped) AS loc_lookup
    ), '[]'::jsonb)
  )
  INTO result
  FROM totals;

  RETURN COALESCE(result, jsonb_build_object(
    'total_equipment', 0,
    'status_counts', jsonb_build_object(
      'hoat_dong', 0,
      'cho_sua_chua', 0,
      'cho_bao_tri', 0,
      'cho_hieu_chuan', 0,
      'ngung_su_dung', 0,
      'chua_co_nhu_cau', 0
    ),
    'by_department', '[]'::jsonb,
    'by_location', '[]'::jsonb,
    'departments', '[]'::jsonb,
    'locations', '[]'::jsonb
  ));
END;
$$;


ALTER FUNCTION public.equipment_status_distribution(p_q text, p_don_vi bigint, p_khoa_phong text, p_vi_tri text) OWNER TO postgres;

--
-- Name: FUNCTION equipment_status_distribution(p_q text, p_don_vi bigint, p_khoa_phong text, p_vi_tri text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_status_distribution(p_q text, p_don_vi bigint, p_khoa_phong text, p_vi_tri text) IS 'Returns equipment status distribution with department and location breakdowns in JSONB format.
FIXED: Added regional_leader support while preserving original JSONB structure for frontend compatibility.
Regional leaders must specify p_don_vi parameter to view facility-specific data.';


--
-- Name: equipment_statuses_list_for_tenant(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_statuses_list_for_tenant(p_don_vi bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_user_id TEXT;
  v_allowed BIGINT[];
  v_effective BIGINT[];
  v_department_scope TEXT;
  v_jwt_claims JSONB;
BEGIN
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;

  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));
  v_user_id := NULLIF(v_jwt_claims ->> 'user_id', '');

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  v_allowed := public.allowed_don_vi_for_session_safe();

  IF v_role = 'global' THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF v_allowed IS NULL OR NOT (p_don_vi = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims ->> 'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN;
    END IF;
  END IF;

  RETURN QUERY
  SELECT jsonb_build_object(
    'name', COALESCE(NULLIF(TRIM(tinh_trang_hien_tai), ''), 'Chưa phân loại'),
    'count', COUNT(*)::INTEGER
  )
  FROM public.thiet_bi tb
  WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
    AND tb.is_deleted = false
    AND (v_role <> 'user' OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope)
  GROUP BY COALESCE(NULLIF(TRIM(tinh_trang_hien_tai), ''), 'Chưa phân loại')
  ORDER BY COUNT(*) DESC;
END;
$$;


ALTER FUNCTION public.equipment_statuses_list_for_tenant(p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION equipment_statuses_list_for_tenant(p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.equipment_statuses_list_for_tenant(p_don_vi bigint) IS 'Returns status list for tenant equipment. FIXED: Now uses consistent JWT claim reading.';


--
-- Name: equipment_update(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_update(p_id bigint, p_patch jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_user_id BIGINT := NULLIF(public._get_jwt_claim('user_id'), '')::BIGINT;
  v_khoa_phong_new TEXT := COALESCE(p_patch->>'khoa_phong_quan_ly', NULL);
  v_patch_status TEXT := NULLIF(TRIM(p_patch->>'tinh_trang_hien_tai'), '');
  v_valid_statuses TEXT[] := ARRAY[
    'Hoạt động', 'Chờ sửa chữa', 'Chờ bảo trì',
    'Chờ hiệu chuẩn/kiểm định', 'Ngưng sử dụng', 'Chưa có nhu cầu sử dụng'
  ];
  v_existing public.thiet_bi%ROWTYPE;
  v_effective_status TEXT;
  v_effective_ngay_dua_vao_su_dung TEXT;
  v_effective_ngay_ngung_su_dung TEXT;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role IN ('regional_leader','user') THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = '42501';
  END IF;

  IF v_role <> 'global' AND v_donvi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF v_role <> 'global' THEN
    SELECT *
    INTO v_existing
    FROM public.thiet_bi
    WHERE id = p_id AND don_vi = v_donvi
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Access denied for update' USING ERRCODE = '42501';
    END IF;
  ELSE
    SELECT *
    INTO v_existing
    FROM public.thiet_bi
    WHERE id = p_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Equipment not found with ID: %', p_id;
    END IF;
  END IF;

  IF v_role = 'technician' AND v_khoa_phong_new IS NOT NULL THEN
    PERFORM 1
    FROM public.nhan_vien nv
    WHERE nv.id = v_user_id
      AND nv.khoa_phong = v_khoa_phong_new;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Technician department mismatch' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_effective_status := CASE
    WHEN p_patch ? 'tinh_trang_hien_tai' THEN v_patch_status
    ELSE v_existing.tinh_trang_hien_tai
  END;

  v_effective_ngay_dua_vao_su_dung := CASE
    WHEN p_patch ? 'ngay_dua_vao_su_dung' THEN NULLIF(TRIM(p_patch->>'ngay_dua_vao_su_dung'), '')
    ELSE v_existing.ngay_dua_vao_su_dung
  END;

  v_effective_ngay_ngung_su_dung := CASE
    WHEN p_patch ? 'ngay_ngung_su_dung' THEN NULLIF(TRIM(p_patch->>'ngay_ngung_su_dung'), '')
    ELSE v_existing.ngay_ngung_su_dung
  END;

  IF p_patch ? 'tinh_trang_hien_tai' THEN
    IF v_patch_status IS NOT NULL AND NOT (v_patch_status = ANY(v_valid_statuses)) THEN
      RAISE EXCEPTION 'Invalid status: %. Must be one of: %', v_patch_status, array_to_string(v_valid_statuses, ', ')
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_effective_ngay_ngung_su_dung IS NOT NULL AND v_effective_status IS DISTINCT FROM 'Ngưng sử dụng' THEN
    RAISE EXCEPTION 'Ngày ngừng sử dụng chỉ được phép khi tình trạng là "Ngưng sử dụng"'
      USING ERRCODE = '22023';
  END IF;

  IF v_effective_ngay_ngung_su_dung IS NOT NULL AND (
    v_effective_ngay_ngung_su_dung !~ '^\d{4}-\d{2}-\d{2}$'
    OR to_char(to_date(v_effective_ngay_ngung_su_dung, 'YYYY-MM-DD'), 'YYYY-MM-DD') <> v_effective_ngay_ngung_su_dung
  ) THEN
    RAISE EXCEPTION 'Định dạng ngày không hợp lệ. Sử dụng: YYYY-MM-DD'
      USING ERRCODE = '22023';
  END IF;

  IF
    v_effective_ngay_ngung_su_dung IS NOT NULL
    AND v_effective_ngay_dua_vao_su_dung IS NOT NULL
    AND v_effective_ngay_dua_vao_su_dung ~ '^\d{4}-\d{2}-\d{2}$'
    AND to_char(to_date(v_effective_ngay_dua_vao_su_dung, 'YYYY-MM-DD'), 'YYYY-MM-DD') = v_effective_ngay_dua_vao_su_dung
    AND v_effective_ngay_ngung_su_dung < v_effective_ngay_dua_vao_su_dung
  THEN
    RAISE EXCEPTION 'Ngày ngừng sử dụng phải sau hoặc bằng ngày đưa vào sử dụng'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.thiet_bi SET
    ten_thiet_bi = CASE WHEN p_patch ? 'ten_thiet_bi' THEN NULLIF(p_patch->>'ten_thiet_bi', '') ELSE ten_thiet_bi END,
    ma_thiet_bi = CASE WHEN p_patch ? 'ma_thiet_bi' THEN NULLIF(p_patch->>'ma_thiet_bi', '') ELSE ma_thiet_bi END,
    model = CASE WHEN p_patch ? 'model' THEN NULLIF(p_patch->>'model', '') ELSE model END,
    serial = CASE WHEN p_patch ? 'serial' THEN NULLIF(p_patch->>'serial', '') ELSE serial END,
    cau_hinh_thiet_bi = CASE WHEN p_patch ? 'cau_hinh_thiet_bi' THEN NULLIF(p_patch->>'cau_hinh_thiet_bi', '') ELSE cau_hinh_thiet_bi END,
    phu_kien_kem_theo = CASE WHEN p_patch ? 'phu_kien_kem_theo' THEN NULLIF(p_patch->>'phu_kien_kem_theo', '') ELSE phu_kien_kem_theo END,
    hang_san_xuat = CASE WHEN p_patch ? 'hang_san_xuat' THEN NULLIF(p_patch->>'hang_san_xuat', '') ELSE hang_san_xuat END,
    noi_san_xuat = CASE WHEN p_patch ? 'noi_san_xuat' THEN NULLIF(p_patch->>'noi_san_xuat', '') ELSE noi_san_xuat END,
    nam_san_xuat = CASE
      WHEN p_patch ? 'nam_san_xuat' AND p_patch->>'nam_san_xuat' <> '' THEN (p_patch->>'nam_san_xuat')::INTEGER
      WHEN p_patch ? 'nam_san_xuat' THEN NULL
      ELSE nam_san_xuat
    END,
    ngay_nhap = CASE WHEN p_patch ? 'ngay_nhap' THEN NULLIF(p_patch->>'ngay_nhap', '') ELSE ngay_nhap END,
    ngay_dua_vao_su_dung = CASE WHEN p_patch ? 'ngay_dua_vao_su_dung' THEN NULLIF(p_patch->>'ngay_dua_vao_su_dung', '') ELSE ngay_dua_vao_su_dung END,
    ngay_ngung_su_dung = CASE WHEN p_patch ? 'ngay_ngung_su_dung' THEN NULLIF(TRIM(p_patch->>'ngay_ngung_su_dung'), '') ELSE ngay_ngung_su_dung END,
    han_bao_hanh = CASE WHEN p_patch ? 'han_bao_hanh' THEN NULLIF(p_patch->>'han_bao_hanh', '') ELSE han_bao_hanh END,
    nguon_kinh_phi = CASE WHEN p_patch ? 'nguon_kinh_phi' THEN NULLIF(p_patch->>'nguon_kinh_phi', '') ELSE nguon_kinh_phi END,
    gia_goc = CASE
      WHEN p_patch ? 'gia_goc' AND p_patch->>'gia_goc' <> '' THEN (p_patch->>'gia_goc')::DECIMAL
      WHEN p_patch ? 'gia_goc' THEN NULL
      ELSE gia_goc
    END,
    nam_tinh_hao_mon = CASE
      WHEN p_patch ? 'nam_tinh_hao_mon' AND p_patch->>'nam_tinh_hao_mon' <> '' THEN (p_patch->>'nam_tinh_hao_mon')::INTEGER
      WHEN p_patch ? 'nam_tinh_hao_mon' THEN NULL
      ELSE nam_tinh_hao_mon
    END,
    ty_le_hao_mon = CASE WHEN p_patch ? 'ty_le_hao_mon' THEN NULLIF(p_patch->>'ty_le_hao_mon', '') ELSE ty_le_hao_mon END,
    khoa_phong_quan_ly = CASE WHEN p_patch ? 'khoa_phong_quan_ly' THEN NULLIF(p_patch->>'khoa_phong_quan_ly', '') ELSE khoa_phong_quan_ly END,
    vi_tri_lap_dat = CASE WHEN p_patch ? 'vi_tri_lap_dat' THEN NULLIF(p_patch->>'vi_tri_lap_dat', '') ELSE vi_tri_lap_dat END,
    nguoi_dang_truc_tiep_quan_ly = CASE WHEN p_patch ? 'nguoi_dang_truc_tiep_quan_ly' THEN NULLIF(p_patch->>'nguoi_dang_truc_tiep_quan_ly', '') ELSE nguoi_dang_truc_tiep_quan_ly END,
    tinh_trang_hien_tai = CASE WHEN p_patch ? 'tinh_trang_hien_tai' THEN v_patch_status ELSE tinh_trang_hien_tai END,
    ghi_chu = CASE WHEN p_patch ? 'ghi_chu' THEN NULLIF(p_patch->>'ghi_chu', '') ELSE ghi_chu END,
    chu_ky_bt_dinh_ky = CASE
      WHEN p_patch ? 'chu_ky_bt_dinh_ky' AND p_patch->>'chu_ky_bt_dinh_ky' <> '' THEN (p_patch->>'chu_ky_bt_dinh_ky')::INTEGER
      WHEN p_patch ? 'chu_ky_bt_dinh_ky' THEN NULL
      ELSE chu_ky_bt_dinh_ky
    END,
    chu_ky_hc_dinh_ky = CASE
      WHEN p_patch ? 'chu_ky_hc_dinh_ky' AND p_patch->>'chu_ky_hc_dinh_ky' <> '' THEN (p_patch->>'chu_ky_hc_dinh_ky')::INTEGER
      WHEN p_patch ? 'chu_ky_hc_dinh_ky' THEN NULL
      ELSE chu_ky_hc_dinh_ky
    END,
    chu_ky_kd_dinh_ky = CASE
      WHEN p_patch ? 'chu_ky_kd_dinh_ky' AND p_patch->>'chu_ky_kd_dinh_ky' <> '' THEN (p_patch->>'chu_ky_kd_dinh_ky')::INTEGER
      WHEN p_patch ? 'chu_ky_kd_dinh_ky' THEN NULL
      ELSE chu_ky_kd_dinh_ky
    END,
    ngay_bt_tiep_theo = CASE
      WHEN p_patch ? 'ngay_bt_tiep_theo' AND p_patch->>'ngay_bt_tiep_theo' <> '' THEN (p_patch->>'ngay_bt_tiep_theo')::DATE
      WHEN p_patch ? 'ngay_bt_tiep_theo' THEN NULL
      ELSE ngay_bt_tiep_theo
    END,
    ngay_hc_tiep_theo = CASE
      WHEN p_patch ? 'ngay_hc_tiep_theo' AND p_patch->>'ngay_hc_tiep_theo' <> '' THEN (p_patch->>'ngay_hc_tiep_theo')::DATE
      WHEN p_patch ? 'ngay_hc_tiep_theo' THEN NULL
      ELSE ngay_hc_tiep_theo
    END,
    ngay_kd_tiep_theo = CASE
      WHEN p_patch ? 'ngay_kd_tiep_theo' AND p_patch->>'ngay_kd_tiep_theo' <> '' THEN (p_patch->>'ngay_kd_tiep_theo')::DATE
      WHEN p_patch ? 'ngay_kd_tiep_theo' THEN NULL
      ELSE ngay_kd_tiep_theo
    END,
    phan_loai_theo_nd98 = CASE WHEN p_patch ? 'phan_loai_theo_nd98' THEN NULLIF(p_patch->>'phan_loai_theo_nd98', '') ELSE phan_loai_theo_nd98 END,
    so_luu_hanh = CASE WHEN p_patch ? 'so_luu_hanh' THEN NULLIF(p_patch->>'so_luu_hanh', '') ELSE so_luu_hanh END
  WHERE id = p_id;

  RETURN TRUE;
END;
$_$;


ALTER FUNCTION public.equipment_update(p_id bigint, p_patch jsonb) OWNER TO postgres;

--
-- Name: equipment_update(bigint, text, text, text, text, text, text, date, numeric, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_update(p_id bigint, p_ten_thiet_bi text DEFAULT NULL::text, p_so_serial text DEFAULT NULL::text, p_mo_ta text DEFAULT NULL::text, p_khoa_phong text DEFAULT NULL::text, p_vi_tri text DEFAULT NULL::text, p_trang_thai text DEFAULT NULL::text, p_ngay_mua date DEFAULT NULL::date, p_gia_mua numeric DEFAULT NULL::numeric, p_han_bao_hanh date DEFAULT NULL::date) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  current_user_ctx RECORD;
  old_record thiet_bi%ROWTYPE;
  changes_made JSONB := '{}'::JSONB;
BEGIN
  SELECT * INTO current_user_ctx FROM _get_current_user_context();
  IF current_user_ctx.role NOT IN ('global', 'to_qltb', 'admin') THEN
    RAISE EXCEPTION 'Insufficient permissions to update equipment' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO old_record FROM thiet_bi WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Equipment not found with ID: %', p_id; END IF;

  IF p_ten_thiet_bi IS NOT NULL AND p_ten_thiet_bi != old_record.ten_thiet_bi THEN
    changes_made := changes_made || jsonb_build_object('ten_thiet_bi', jsonb_build_object('old', old_record.ten_thiet_bi, 'new', p_ten_thiet_bi));
  END IF;
  IF p_trang_thai IS NOT NULL AND p_trang_thai != old_record.trang_thai THEN
    changes_made := changes_made || jsonb_build_object('trang_thai', jsonb_build_object('old', old_record.trang_thai, 'new', p_trang_thai));
  END IF;

  UPDATE thiet_bi SET
    ten_thiet_bi = COALESCE(p_ten_thiet_bi, ten_thiet_bi),
    so_serial = COALESCE(p_so_serial, so_serial),
    mo_ta = COALESCE(p_mo_ta, mo_ta),
    khoa_phong = COALESCE(p_khoa_phong, khoa_phong),
    vi_tri = COALESCE(p_vi_tri, vi_tri),
    trang_thai = COALESCE(p_trang_thai, trang_thai),
    ngay_mua = COALESCE(p_ngay_mua, ngay_mua),
    gia_mua = COALESCE(p_gia_mua, gia_mua),
    han_bao_hanh = COALESCE(p_han_bao_hanh, han_bao_hanh),
    updated_at = NOW()
  WHERE id = p_id;

  IF jsonb_object_keys(changes_made) IS NOT NULL THEN
    PERFORM public.audit_log(
      'equipment_update',
      'device',
      p_id,
      COALESCE(p_ten_thiet_bi, old_record.ten_thiet_bi),
      jsonb_build_object('equipment_id', p_id, 'equipment_name', COALESCE(p_ten_thiet_bi, old_record.ten_thiet_bi), 'changes', changes_made)
    );
  END IF;

  RETURN TRUE;
END;
$$;


