-- Name: FUNCTION equipment_update(p_id bigint, p_ten_thiet_bi text, p_so_serial text, p_mo_ta text, p_khoa_phong text, p_vi_tri text, p_trang_thai text, p_ngay_mua date, p_gia_mua numeric, p_han_bao_hanh date); Type: COMMENT; Schema: public; Owner: postgres
