--
-- Name: get_repair_request_facilities(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_repair_request_facilities() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := '';
  v_allowed_don_vi BIGINT[];
  v_jwt_claims JSONB;
  v_result JSONB;
BEGIN
  -- Get JWT claims
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;
  
  -- Get role from JWT (prefer app_role, fallback to role)
  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));
  
  -- Get allowed facilities based on role and region (handles global, regional_leader, regular users)
  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();
  
  -- CASE 1: Global users - return all facilities that have repair requests
  IF v_role = 'global' THEN
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', dv.id,
        'name', dv.name
      )
      ORDER BY dv.name
    )
    INTO v_result
    FROM (
      SELECT DISTINCT dv.id, dv.name
      FROM public.yeu_cau_sua_chua r
      INNER JOIN public.thiet_bi tb ON tb.id = r.thiet_bi_id
      INNER JOIN public.don_vi dv ON dv.id = tb.don_vi
      WHERE tb.don_vi IS NOT NULL
    ) dv;
    
    RETURN COALESCE(v_result, '[]'::jsonb);
  END IF;
  
  -- CASE 2: Non-global users (regional leaders, regular users)
  IF v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) = 0 THEN
    -- No access to any facilities
    RETURN '[]'::jsonb;
  END IF;
  
  -- Return only allowed facilities that have repair requests
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', dv.id,
      'name', dv.name
    )
    ORDER BY dv.name
  )
  INTO v_result
  FROM (
    SELECT DISTINCT dv.id, dv.name
    FROM public.yeu_cau_sua_chua r
    INNER JOIN public.thiet_bi tb ON tb.id = r.thiet_bi_id
    INNER JOIN public.don_vi dv ON dv.id = tb.don_vi
    WHERE tb.don_vi = ANY(v_allowed_don_vi)  -- Tenant isolation
      AND tb.don_vi IS NOT NULL
  ) dv;
  
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_repair_request_facilities() OWNER TO postgres;

--
-- Name: FUNCTION get_repair_request_facilities(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_repair_request_facilities() IS 'Returns list of facilities (id, name) that have repair requests, respecting tenant isolation. 
For global users: all facilities with repair requests.
For regional leaders: only facilities in their region (via dia_ban claim) that have repair requests.
For regular users: only their current facility if it has repair requests.
Lightweight alternative to calling repair_request_list just to extract facility names.';


--
-- Name: get_session_profile_for_jwt(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_session_profile_for_jwt(p_user_id bigint) RETURNS TABLE(password_changed_at timestamp with time zone, current_don_vi bigint, don_vi bigint, khoa_phong text, full_name text, dia_ban_id bigint, ma_dia_ban text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_claims jsonb;
  v_claim_app_role_text text;
  v_claim_user_id bigint;
  v_claim_user_id_text text;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'Forbidden session profile access' USING errcode = '42501';
  END IF;

  v_claims := COALESCE(NULLIF(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
  v_claim_app_role_text := NULLIF(v_claims->>'app_role', '');
  v_claim_user_id_text := NULLIF(v_claims->>'user_id', '');

  IF v_claim_app_role_text IS NULL THEN
    RAISE EXCEPTION 'Forbidden session profile access' USING errcode = '42501';
  END IF;

  IF v_claim_user_id_text IS NULL OR v_claim_user_id_text !~ '^[0-9]+$' THEN
    RAISE EXCEPTION 'Forbidden session profile access' USING errcode = '42501';
  END IF;

  v_claim_user_id := v_claim_user_id_text::bigint;

  IF v_claim_user_id <> p_user_id THEN
    RAISE EXCEPTION 'Forbidden session profile access' USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT
    nv.password_changed_at::timestamptz,
    nv.current_don_vi::bigint,
    nv.don_vi::bigint,
    nv.khoa_phong::text,
    nv.full_name::text,
    COALESCE(nv.dia_ban_id, dv.dia_ban_id)::bigint AS dia_ban_id,
    db.ma_dia_ban::text
  FROM public.nhan_vien nv
  LEFT JOIN public.don_vi dv
    ON dv.id = COALESCE(nv.current_don_vi, nv.don_vi)
  LEFT JOIN public.dia_ban db
    ON db.id = COALESCE(nv.dia_ban_id, dv.dia_ban_id)
  WHERE nv.id = p_user_id
  LIMIT 1;
END;
$_$;


ALTER FUNCTION public.get_session_profile_for_jwt(p_user_id bigint) OWNER TO postgres;

--
-- Name: get_transfer_counts(bigint[], bigint[], text[], text[], timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_transfer_counts(p_facility_ids bigint[] DEFAULT NULL::bigint[], p_assignee_ids bigint[] DEFAULT NULL::bigint[], p_types text[] DEFAULT NULL::text[], p_statuses text[] DEFAULT NULL::text[], p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_search_text text DEFAULT NULL::text) RETURNS TABLE(total_count bigint, cho_duyet_count bigint, da_duyet_count bigint, dang_luan_chuyen_count bigint, da_ban_giao_count bigint, hoan_thanh_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_role TEXT;
  v_user_don_vi BIGINT;
  v_user_dia_ban BIGINT;
BEGIN
  v_user_role := current_setting('request.jwt.claims', true)::json->>'role';
  v_user_don_vi := (current_setting('request.jwt.claims', true)::json->>'don_vi')::BIGINT;
  v_user_dia_ban := (current_setting('request.jwt.claims', true)::json->>'dia_ban_id')::BIGINT;

  IF v_user_role IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: Authentication required';
  END IF;

  IF v_user_role NOT IN ('global', 'regional_leader') THEN
    p_facility_ids := ARRAY[v_user_don_vi];
  END IF;

  IF v_user_role = 'regional_leader' THEN
    IF p_facility_ids IS NULL THEN
      p_facility_ids := ARRAY(
        SELECT dv.id
        FROM don_vi dv
        WHERE dv.dia_ban_id = v_user_dia_ban
      );
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    COUNT(*) AS total_count,
    COUNT(*) FILTER (WHERE yclc.trang_thai = 'cho_duyet') AS cho_duyet_count,
    COUNT(*) FILTER (WHERE yclc.trang_thai = 'da_duyet') AS da_duyet_count,
    COUNT(*) FILTER (WHERE yclc.trang_thai = 'dang_luan_chuyen') AS dang_luan_chuyen_count,
    COUNT(*) FILTER (WHERE yclc.trang_thai = 'da_ban_giao') AS da_ban_giao_count,
    COUNT(*) FILTER (WHERE yclc.trang_thai = 'hoan_thanh') AS hoan_thanh_count
  FROM yeu_cau_luan_chuyen yclc
  INNER JOIN thiet_bi tb ON yclc.thiet_bi_id = tb.id
  WHERE
    (p_facility_ids IS NULL OR tb.don_vi = ANY(p_facility_ids))
    AND (p_assignee_ids IS NULL OR yclc.nguoi_yeu_cau_id = ANY(p_assignee_ids))
    AND (p_types IS NULL OR yclc.loai_hinh = ANY(p_types))
    AND (p_statuses IS NULL OR yclc.trang_thai = ANY(p_statuses))
    AND (p_date_from IS NULL OR yclc.created_at >= p_date_from)
    AND (p_date_to IS NULL OR yclc.created_at <= p_date_to)
    AND (
      p_search_text IS NULL
      OR to_tsvector('simple',
        COALESCE(yclc.ma_yeu_cau, '') || ' ' ||
        COALESCE(yclc.ly_do_luan_chuyen, '') || ' ' ||
        COALESCE(tb.ten_thiet_bi, '') || ' ' ||
        COALESCE(tb.ma_thiet_bi, '')
      ) @@ plainto_tsquery('simple', p_search_text)
    );
END;
$$;


ALTER FUNCTION public.get_transfer_counts(p_facility_ids bigint[], p_assignee_ids bigint[], p_types text[], p_statuses text[], p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_search_text text) OWNER TO postgres;

--
-- Name: FUNCTION get_transfer_counts(p_facility_ids bigint[], p_assignee_ids bigint[], p_types text[], p_statuses text[], p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_search_text text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_transfer_counts(p_facility_ids bigint[], p_assignee_ids bigint[], p_types text[], p_statuses text[], p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_search_text text) IS 'Get transfer counts grouped by status for Kanban overview header with full filter support.';


--
-- Name: get_transfer_request_facilities(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_transfer_request_facilities() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := '';
  v_allowed_don_vi BIGINT[];
  v_jwt_claims JSONB;
  v_result JSONB;
BEGIN
  -- Get JWT claims safely
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_jwt_claims := NULL;
  END;
  
  -- Get role from JWT claims
  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));
  
  -- Get allowed facilities for this user (handles regional_leader multi-facility access)
  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();
  
  -- Global users: Return all facilities that have transfer requests
  IF v_role = 'global' THEN
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', dv.id,
        'name', dv.name
      )
      ORDER BY dv.name
    )
    INTO v_result
    FROM (
      SELECT DISTINCT dv.id, dv.name
      FROM public.yeu_cau_luan_chuyen yc
      INNER JOIN public.thiet_bi tb ON tb.id = yc.thiet_bi_id
      INNER JOIN public.don_vi dv ON dv.id = tb.don_vi
      WHERE tb.don_vi IS NOT NULL
    ) dv;
    
    RETURN COALESCE(v_result, '[]'::jsonb);
  END IF;
  
  -- Non-global users (regional leaders, regular users)
  IF v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) = 0 THEN
    -- No access to any facilities
    RETURN '[]'::jsonb;
  END IF;
  
  -- Return only allowed facilities that have transfer requests
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', dv.id,
      'name', dv.name
    )
    ORDER BY dv.name
  )
  INTO v_result
  FROM (
    SELECT DISTINCT dv.id, dv.name
    FROM public.yeu_cau_luan_chuyen yc
    INNER JOIN public.thiet_bi tb ON tb.id = yc.thiet_bi_id
    INNER JOIN public.don_vi dv ON dv.id = tb.don_vi
    WHERE tb.don_vi = ANY(v_allowed_don_vi)  -- Tenant isolation
      AND tb.don_vi IS NOT NULL
  ) dv;
  
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_transfer_request_facilities() OWNER TO postgres;

--
-- Name: FUNCTION get_transfer_request_facilities(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_transfer_request_facilities() IS 'Returns lightweight list of facilities that have transfer requests (id and name only).
For global users, returns all facilities with transfer requests.
For regional leaders, returns only facilities in their region that have transfer requests.
For regular users, returns their own facility if it has transfer requests.
Security: Uses allowed_don_vi_for_session_safe() for tenant isolation.
Performance: ~1-2KB payload vs ~500KB fetching full transfer list.';


--
-- Name: handle_new_repair_request_notification(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_repair_request_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_user_ids uuid[];
  v_supabase_url text;
  v_function_url text;
  v_thiet_bi_name text;
  v_request_id int;
  v_internal_secret text; -- Shared secret for Edge Function auth
BEGIN
  v_request_id := NEW.id;

  -- Prefer reading the secret from public.internal_settings to avoid GUC dependency
  BEGIN
    EXECUTE $SQL$
      SELECT value::text FROM public.internal_settings WHERE lower(key) = 'internal_function_secret' LIMIT 1
    $SQL$
    INTO v_internal_secret;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_internal_secret := NULL;
  END;

  -- Resolve Supabase base URL from settings table first, then fallback to GUC
  BEGIN
    EXECUTE $SQL$
      SELECT value::text FROM public.internal_settings WHERE lower(key) = 'supabase_url' LIMIT 1
    $SQL$
    INTO v_supabase_url;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_supabase_url := NULL;
  END;

  IF v_supabase_url IS NULL OR v_supabase_url = '' THEN
    v_supabase_url := current_setting('app.settings.supabase_url', true);
  END IF;

  IF v_supabase_url IS NULL OR v_supabase_url = '' THEN
    RAISE WARNING 'handle_new_repair_request_notification: supabase_url is not configured';
    RETURN NEW;
  END IF;

  -- Normalize URL and construct function endpoint
  v_supabase_url := regexp_replace(v_supabase_url, '/+$', ''); -- strip trailing slash
  v_function_url := v_supabase_url || '/functions/v1/send-push-notification';

  -- Fallback to GUC if table lookup did not return a secret
  IF v_internal_secret IS NULL OR v_internal_secret = '' THEN
    v_internal_secret := current_setting('app.settings.internal_function_secret', true);
  END IF;

  IF v_internal_secret IS NULL OR v_internal_secret = '' THEN
    RAISE WARNING 'handle_new_repair_request_notification: internal function secret is not configured';
    RETURN NEW;
  END IF;

  -- 1. Get Equipment Name
  SELECT ten_thiet_bi INTO v_thiet_bi_name FROM public.thiet_bi WHERE id = NEW.thiet_bi_id;

  -- 2. Find Users to Notify (Global Admins and Technicians/Managers)
  -- Logic: Notify all users with role 'global' or 'to_qltb' (Equipment Management Team)
  SELECT array_agg(id) INTO v_user_ids
  FROM auth.users
  WHERE (raw_app_meta_data->>'role' IN ('global', 'to_qltb') OR raw_user_meta_data->>'role' IN ('global', 'to_qltb'));
  
  IF v_user_ids IS NULL OR array_length(v_user_ids, 1) = 0 THEN
    RETURN NEW;
  END IF;

  -- 3. Call Edge Function via pg_net
  -- Note: We don't wait for the response (async)
  PERFORM net.http_post(
    url := v_function_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-internal-secret', v_internal_secret
    ),
    body := jsonb_build_object(
      'userIds', v_user_ids,
      'notificationPayload', jsonb_build_object(
        'title', 'Yêu cầu sửa chữa mới',
        'body', 'Thiết bị ' || coalesce(v_thiet_bi_name, 'Unknown') || ' cần sửa chữa.',
        'data', jsonb_build_object('url', '/repair-requests?id=' || v_request_id)
      )
    )
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Log error but don't fail the transaction
  RAISE WARNING 'Failed to send notification trigger: %', SQLERRM;
  RETURN NEW;
END;
$_$;


