--
-- Name: header_notifications_summary(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.header_notifications_summary(p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jwt_claims jsonb;
  v_role text;
  v_user_id text;
  v_is_global boolean := false;
  v_allowed_don_vi bigint[];
  v_filter_don_vi bigint := NULL;
  v_department_scope text;
  v_repairs bigint := 0;
  v_transfers bigint := 0;
BEGIN
  v_jwt_claims := COALESCE(NULLIF(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  v_role := lower(COALESCE(v_jwt_claims->>'app_role', v_jwt_claims->>'role', ''));
  v_user_id := NULLIF(COALESCE(v_jwt_claims->>'user_id', v_jwt_claims->>'sub'), '');

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_global := v_role = 'global';

  IF NOT v_is_global THEN
    v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

    IF v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) IS NULL THEN
      RETURN jsonb_build_object('pending_repairs', 0, 'pending_transfers', 0);
    END IF;

    IF p_don_vi IS NOT NULL AND NOT (p_don_vi = ANY(v_allowed_don_vi)) THEN
      RETURN jsonb_build_object('pending_repairs', 0, 'pending_transfers', 0);
    END IF;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims->>'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN jsonb_build_object('pending_repairs', 0, 'pending_transfers', 0);
    END IF;
  END IF;

  IF p_don_vi IS NOT NULL THEN
    v_filter_don_vi := p_don_vi;
  END IF;

  SELECT COUNT(*) INTO v_repairs
  FROM public.yeu_cau_sua_chua r
  INNER JOIN public.thiet_bi tb ON tb.id = r.thiet_bi_id
  WHERE r.trang_thai IN ('Chờ xử lý', 'Đã duyệt')
    AND tb.is_deleted = false
    AND (
      (v_filter_don_vi IS NOT NULL AND tb.don_vi = v_filter_don_vi)
      OR (v_filter_don_vi IS NULL AND v_is_global)
      OR (v_filter_don_vi IS NULL AND NOT v_is_global AND tb.don_vi = ANY(v_allowed_don_vi))
    )
    AND (
      v_role <> 'user'
      OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
    );

  SELECT COUNT(*) INTO v_transfers
  FROM public.yeu_cau_luan_chuyen t
  INNER JOIN public.thiet_bi tb ON tb.id = t.thiet_bi_id
  WHERE t.trang_thai IN ('cho_duyet', 'da_duyet')
    AND tb.is_deleted = false
    AND (
      (v_filter_don_vi IS NOT NULL AND tb.don_vi = v_filter_don_vi)
      OR (v_filter_don_vi IS NULL AND v_is_global)
      OR (v_filter_don_vi IS NULL AND NOT v_is_global AND tb.don_vi = ANY(v_allowed_don_vi))
    )
    AND (
      v_role <> 'user'
      OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
    );

  RETURN jsonb_build_object(
    'pending_repairs', COALESCE(v_repairs, 0),
    'pending_transfers', COALESCE(v_transfers, 0)
  );
END;
$$;


ALTER FUNCTION public.header_notifications_summary(p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION header_notifications_summary(p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.header_notifications_summary(p_don_vi bigint) IS 'Returns pending repair/transfer notification counts for the current JWT scope; p_don_vi narrows counts to an authorized selected facility. Counts require a matching equipment row.';


--
-- Name: maintenance_calendar_events(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_calendar_events(p_year integer, p_month integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := '';
  v_allowed_don_vi BIGINT[];
  v_jwt_claims JSONB;
  v_month_field TEXT;
  v_completion_field TEXT;
  v_result JSONB;
  v_stats JSONB;
BEGIN
  -- Validate month parameter
  IF p_month < 1 OR p_month > 12 THEN
    RAISE EXCEPTION 'Invalid month: %. Must be between 1 and 12', p_month USING ERRCODE = '22023';
  END IF;
  
  -- Get JWT claims
  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    -- No JWT claims - return empty result
    RETURN jsonb_build_object(
      'events', '[]'::jsonb,
      'departments', '[]'::jsonb,
      'stats', jsonb_build_object(
        'total', 0,
        'completed', 0,
        'pending', 0,
        'byType', '{}'::jsonb
      )
    );
  END;
  
  -- Get role from claims
  v_role := lower(COALESCE(
    v_jwt_claims ->> 'app_role',
    v_jwt_claims ->> 'role',
    ''
  ));
  
  -- Get allowed facilities based on role and region
  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();
  
  -- If no role or no allowed facilities, return empty result
  IF v_role = '' OR v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'events', '[]'::jsonb,
      'departments', '[]'::jsonb,
      'stats', jsonb_build_object(
        'total', 0,
        'completed', 0,
        'pending', 0,
        'byType', '{}'::jsonb
      )
    );
  END IF;
  
  -- Build dynamic field names for the month
  v_month_field := 'thang_' || p_month::TEXT;
  v_completion_field := v_month_field || '_hoan_thanh';
  
  -- Build calendar events with proper filtering
  WITH approved_plans AS (
    -- Get approved maintenance plans for the year (with regional filtering)
    SELECT kh.id, kh.ten_ke_hoach, kh.nam, kh.khoa_phong, kh.loai_cong_viec, kh.don_vi
    FROM public.ke_hoach_bao_tri kh
    WHERE kh.nam = p_year
      AND kh.trang_thai = 'Đã duyệt'
      AND (v_role = 'global' OR kh.don_vi = ANY(v_allowed_don_vi))
  ),
  monthly_tasks AS (
    -- Get tasks scheduled for this month with equipment info
    SELECT 
      cv.id,
      cv.ke_hoach_id,
      cv.thiet_bi_id,
      cv.loai_cong_viec,
      CASE 
        WHEN p_month = 1 THEN cv.thang_1_hoan_thanh
        WHEN p_month = 2 THEN cv.thang_2_hoan_thanh
        WHEN p_month = 3 THEN cv.thang_3_hoan_thanh
        WHEN p_month = 4 THEN cv.thang_4_hoan_thanh
        WHEN p_month = 5 THEN cv.thang_5_hoan_thanh
        WHEN p_month = 6 THEN cv.thang_6_hoan_thanh
        WHEN p_month = 7 THEN cv.thang_7_hoan_thanh
        WHEN p_month = 8 THEN cv.thang_8_hoan_thanh
        WHEN p_month = 9 THEN cv.thang_9_hoan_thanh
        WHEN p_month = 10 THEN cv.thang_10_hoan_thanh
        WHEN p_month = 11 THEN cv.thang_11_hoan_thanh
        WHEN p_month = 12 THEN cv.thang_12_hoan_thanh
      END AS is_completed,
      tb.ma_thiet_bi,
      tb.ten_thiet_bi,
      tb.khoa_phong_quan_ly,
      tb.don_vi AS equipment_don_vi,
      ap.ten_ke_hoach AS plan_name
    FROM public.cong_viec_bao_tri cv
    INNER JOIN approved_plans ap ON ap.id = cv.ke_hoach_id
    INNER JOIN public.thiet_bi tb ON tb.id = cv.thiet_bi_id
    WHERE 
      CASE 
        WHEN p_month = 1 THEN cv.thang_1
        WHEN p_month = 2 THEN cv.thang_2
        WHEN p_month = 3 THEN cv.thang_3
        WHEN p_month = 4 THEN cv.thang_4
        WHEN p_month = 5 THEN cv.thang_5
        WHEN p_month = 6 THEN cv.thang_6
        WHEN p_month = 7 THEN cv.thang_7
        WHEN p_month = 8 THEN cv.thang_8
        WHEN p_month = 9 THEN cv.thang_9
        WHEN p_month = 10 THEN cv.thang_10
        WHEN p_month = 11 THEN cv.thang_11
        WHEN p_month = 12 THEN cv.thang_12
      END = TRUE
      -- Additional equipment-level filtering for regional leaders
      AND (v_role = 'global' OR tb.don_vi = ANY(v_allowed_don_vi))
  ),
  events_json AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', mt.id,
        'title', mt.ten_thiet_bi,
        'type', COALESCE(mt.loai_cong_viec, 'Bảo trì'),
        'date', make_date(p_year, p_month, 15)::TEXT, -- Mid-month as default
        'equipmentCode', mt.ma_thiet_bi,
        'equipmentName', mt.ten_thiet_bi,
        'department', COALESCE(mt.khoa_phong_quan_ly, 'Không xác định'),
        'isCompleted', COALESCE(mt.is_completed, FALSE),
        'planName', mt.plan_name,
        'planId', mt.ke_hoach_id,
        'taskId', mt.id
      )
    ) AS events
    FROM monthly_tasks mt
  ),
  departments_json AS (
    SELECT jsonb_agg(DISTINCT COALESCE(mt.khoa_phong_quan_ly, 'Không xác định') ORDER BY COALESCE(mt.khoa_phong_quan_ly, 'Không xác định')) AS departments
    FROM monthly_tasks mt
  ),
  type_counts AS (
    SELECT 
      COALESCE(mt.loai_cong_viec, 'Bảo trì') AS task_type,
      COUNT(*) AS type_count
    FROM monthly_tasks mt
    GROUP BY COALESCE(mt.loai_cong_viec, 'Bảo trì')
  ),
  stats_calculation AS (
    SELECT
      COUNT(*)::INT AS total,
      COUNT(*) FILTER (WHERE mt.is_completed = TRUE)::INT AS completed,
      COUNT(*) FILTER (WHERE COALESCE(mt.is_completed, FALSE) = FALSE)::INT AS pending
    FROM monthly_tasks mt
  ),
  by_type_json AS (
    SELECT
      CASE
        WHEN COUNT(*) = 0 THEN '{}'::jsonb
        ELSE jsonb_object_agg(tc.task_type, tc.type_count)
      END AS by_type
    FROM type_counts tc
  )
  SELECT jsonb_build_object(
    'events', COALESCE(ej.events, '[]'::jsonb),
    'departments', COALESCE(dj.departments, '[]'::jsonb),
    'stats', jsonb_build_object(
      'total', COALESCE(sc.total, 0),
      'completed', COALESCE(sc.completed, 0),
      'pending', COALESCE(sc.pending, 0),
      'byType', COALESCE(btj.by_type, '{}'::jsonb)
    )
  ) INTO v_result
  FROM events_json ej
  CROSS JOIN departments_json dj
  CROSS JOIN stats_calculation sc
  CROSS JOIN by_type_json btj;
  
  RETURN COALESCE(v_result, jsonb_build_object(
    'events', '[]'::jsonb,
    'departments', '[]'::jsonb,
    'stats', jsonb_build_object(
      'total', 0,
      'completed', 0,
      'pending', 0,
      'byType', '{}'::jsonb
    )
  ));
END;
$$;


ALTER FUNCTION public.maintenance_calendar_events(p_year integer, p_month integer) OWNER TO postgres;

--
-- Name: maintenance_plan_approve(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_plan_approve(p_id bigint, p_nguoi_duyet text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_guard record;
  v_plan public.ke_hoach_bao_tri;
BEGIN
  SELECT * INTO v_guard FROM public._assert_maintenance_write_allowed();

  SELECT *
  INTO v_plan
  FROM public.ke_hoach_bao_tri
  WHERE id = p_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF NOT v_guard.is_global AND (v_plan.don_vi IS NULL OR NOT v_plan.don_vi = ANY(v_guard.allowed_don_vi)) THEN
    RAISE EXCEPTION 'Không có quyền trên kế hoạch bảo trì thuộc đơn vị khác' USING ERRCODE = '42501';
  END IF;

  UPDATE public.ke_hoach_bao_tri
  SET trang_thai = 'Đã duyệt',
      ngay_phe_duyet = now(),
      nguoi_duyet = p_nguoi_duyet
  WHERE id = p_id;
END;
$$;


ALTER FUNCTION public.maintenance_plan_approve(p_id bigint, p_nguoi_duyet text) OWNER TO postgres;

--
-- Name: maintenance_plan_create(text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_plan_create(p_ten_ke_hoach text, p_nam integer, p_loai_cong_viec text, p_khoa_phong text, p_nguoi_lap_ke_hoach text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_guard record;
  v_new_id integer;
BEGIN
  SELECT * INTO v_guard FROM public._assert_maintenance_write_allowed();

  IF v_guard.is_global THEN
    RAISE EXCEPTION 'global/admin cannot create tenant maintenance plans' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.ke_hoach_bao_tri(
    ten_ke_hoach,
    nam,
    loai_cong_viec,
    khoa_phong,
    nguoi_lap_ke_hoach,
    trang_thai,
    don_vi
  )
  VALUES (
    p_ten_ke_hoach,
    p_nam,
    p_loai_cong_viec,
    NULLIF(p_khoa_phong, ''),
    p_nguoi_lap_ke_hoach,
    'Bản nháp',
    v_guard.default_don_vi
  )
  RETURNING id INTO v_new_id;

  IF NOT public.audit_log(
    'maintenance_plan_create',
    'maintenance_plan',
    v_new_id,
    p_ten_ke_hoach,
    jsonb_build_object(
      'nam', p_nam,
      'loai_cong_viec', p_loai_cong_viec,
      'khoa_phong', NULLIF(p_khoa_phong, '')
    )
  ) THEN
    RAISE EXCEPTION 'audit_log failed for maintenance_plan %', v_new_id;
  END IF;

  RETURN v_new_id;
END;
$$;


ALTER FUNCTION public.maintenance_plan_create(p_ten_ke_hoach text, p_nam integer, p_loai_cong_viec text, p_khoa_phong text, p_nguoi_lap_ke_hoach text) OWNER TO postgres;

--
-- Name: maintenance_plan_delete(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_plan_delete(p_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_guard record;
  v_plan public.ke_hoach_bao_tri;
BEGIN
  SELECT * INTO v_guard FROM public._assert_maintenance_write_allowed();

  SELECT *
  INTO v_plan
  FROM public.ke_hoach_bao_tri
  WHERE id = p_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF NOT v_guard.is_global AND (v_plan.don_vi IS NULL OR NOT v_plan.don_vi = ANY(v_guard.allowed_don_vi)) THEN
    RAISE EXCEPTION 'Không có quyền trên kế hoạch bảo trì thuộc đơn vị khác' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.ke_hoach_bao_tri WHERE id = p_id;
END;
$$;


ALTER FUNCTION public.maintenance_plan_delete(p_id bigint) OWNER TO postgres;

--
-- Name: maintenance_plan_get(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_plan_get(p_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_allowed_don_vi BIGINT[];
  v_jwt_claims JSONB;
  v_result JSONB;
BEGIN
  IF p_id IS NULL THEN
    RETURN NULL;
  END IF;

  BEGIN
    v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;

  v_role := lower(COALESCE(
    v_jwt_claims->>'app_role',
    v_jwt_claims->>'role',
    ''
  ));

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  SELECT jsonb_build_object(
    'id', kh.id,
    'ten_ke_hoach', kh.ten_ke_hoach,
    'nam', kh.nam,
    'loai_cong_viec', kh.loai_cong_viec,
    'khoa_phong', kh.khoa_phong,
    'nguoi_lap_ke_hoach', kh.nguoi_lap_ke_hoach,
    'trang_thai', kh.trang_thai,
    'ngay_phe_duyet', kh.ngay_phe_duyet,
    'nguoi_duyet', kh.nguoi_duyet,
    'ly_do_khong_duyet', kh.ly_do_khong_duyet,
    'created_at', kh.created_at,
    'don_vi', kh.don_vi,
    'facility_name', dv.name
  )
  INTO v_result
  FROM public.ke_hoach_bao_tri kh
  LEFT JOIN public.don_vi dv ON dv.id = kh.don_vi
  WHERE kh.id = p_id
    AND (
      v_role = 'global'
      OR (
        v_allowed_don_vi IS NOT NULL
        AND array_length(v_allowed_don_vi, 1) IS NOT NULL
        AND kh.don_vi = ANY(v_allowed_don_vi)
      )
    )
  LIMIT 1;

  RETURN v_result;
END;
$$;


