-- Name: FUNCTION maintenance_plan_get(p_id bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.maintenance_plan_get(p_id bigint) IS 'Fetches a single maintenance plan by id with tenant/region access filtering.

Returns the plan payload with facility_name, or NULL if not found or not accessible.';


--
-- Name: maintenance_plan_list(text, bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_plan_list(p_q text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_user_id TEXT;
  v_don_vi BIGINT;
  v_is_global BOOLEAN := FALSE;
  v_allowed_don_vi BIGINT[];
  v_jwt_claims JSONB;
  v_page INT;
  v_page_size INT;
  v_offset INT;
  v_total BIGINT;
  v_result JSONB;
  v_sanitized_q TEXT;
BEGIN
  v_jwt_claims := COALESCE(current_setting('request.jwt.claims', true), '{}')::jsonb;

  v_role := lower(COALESCE(
    v_jwt_claims->>'app_role',
    v_jwt_claims->>'role',
    ''
  ));
  v_user_id := NULLIF(COALESCE(v_jwt_claims->>'user_id', v_jwt_claims->>'sub'), '');
  v_don_vi := NULLIF(v_jwt_claims->>'don_vi', '')::BIGINT;

  IF v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_global := (v_role = 'global');

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  IF NOT v_is_global AND (v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) IS NULL) THEN
    RETURN jsonb_build_object(
      'data', '[]'::jsonb,
      'total', 0,
      'page', COALESCE(p_page, 1),
      'pageSize', COALESCE(p_page_size, 50)
    );
  END IF;

  v_page := GREATEST(1, COALESCE(p_page, 1));
  v_page_size := LEAST(200, GREATEST(1, COALESCE(p_page_size, 50)));
  v_offset := (v_page - 1) * v_page_size;

  IF NOT v_is_global AND p_don_vi IS NOT NULL AND NOT (p_don_vi = ANY(v_allowed_don_vi)) THEN
    RAISE EXCEPTION 'Access denied to facility %', p_don_vi
      USING ERRCODE = '42501',
            HINT = 'You do not have permission to access this facility';
  END IF;

  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  SELECT COUNT(*) INTO v_total
  FROM ke_hoach_bao_tri kh
  LEFT JOIN don_vi dv ON kh.don_vi = dv.id
  WHERE (
    v_sanitized_q IS NULL
    OR kh.ten_ke_hoach ILIKE '%' || v_sanitized_q || '%'
    OR COALESCE(kh.khoa_phong, '') ILIKE '%' || v_sanitized_q || '%'
    OR COALESCE(kh.nguoi_lap_ke_hoach, '') ILIKE '%' || v_sanitized_q || '%'
    OR COALESCE(kh.loai_cong_viec, '') ILIKE '%' || v_sanitized_q || '%'
    OR COALESCE(dv.name, '') ILIKE '%' || v_sanitized_q || '%'
    OR CAST(kh.nam AS TEXT) ILIKE '%' || v_sanitized_q || '%'
  ) AND (
    CASE
      WHEN p_don_vi IS NOT NULL THEN kh.don_vi = p_don_vi
      ELSE v_is_global OR kh.don_vi = ANY(v_allowed_don_vi)
    END
  );

  SELECT jsonb_build_object(
    'data', COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', kh.id,
        'ten_ke_hoach', kh.ten_ke_hoach,
        'nam', kh.nam,
        'loai_cong_viec', kh.loai_cong_viec,
        'khoa_phong', kh.khoa_phong,
        'nguoi_lap_ke_hoach', kh.nguoi_lap_ke_hoach,
        'trang_thai', kh.trang_thai,
        'ngay_phe_duyet', kh.ngay_phe_duyet,
        'nguoi_duyet', kh.nguoi_duyet,
        'ly_do_khong_duyet', kh.ly_do_khong_duyet,
        'created_at', kh.created_at,
        'don_vi', kh.don_vi,
        'facility_name', kh.facility_name
      ) ORDER BY kh.nam DESC, kh.created_at DESC
    ), '[]'::jsonb),
    'total', v_total,
    'page', v_page,
    'pageSize', v_page_size
  ) INTO v_result
  FROM (
    SELECT
      kh.id,
      kh.ten_ke_hoach,
      kh.nam,
      kh.loai_cong_viec,
      kh.khoa_phong,
      kh.nguoi_lap_ke_hoach,
      kh.trang_thai,
      kh.ngay_phe_duyet,
      kh.nguoi_duyet,
      kh.ly_do_khong_duyet,
      kh.created_at,
      kh.don_vi,
      dv.name AS facility_name
    FROM ke_hoach_bao_tri kh
    LEFT JOIN don_vi dv ON kh.don_vi = dv.id
    WHERE (
      v_sanitized_q IS NULL
      OR kh.ten_ke_hoach ILIKE '%' || v_sanitized_q || '%'
      OR COALESCE(kh.khoa_phong, '') ILIKE '%' || v_sanitized_q || '%'
      OR COALESCE(kh.nguoi_lap_ke_hoach, '') ILIKE '%' || v_sanitized_q || '%'
      OR COALESCE(kh.loai_cong_viec, '') ILIKE '%' || v_sanitized_q || '%'
      OR COALESCE(dv.name, '') ILIKE '%' || v_sanitized_q || '%'
      OR CAST(kh.nam AS TEXT) ILIKE '%' || v_sanitized_q || '%'
    ) AND (
      CASE
        WHEN p_don_vi IS NOT NULL THEN kh.don_vi = p_don_vi
        ELSE v_is_global OR kh.don_vi = ANY(v_allowed_don_vi)
      END
    )
    ORDER BY kh.nam DESC, kh.created_at DESC
    LIMIT v_page_size
    OFFSET v_offset
  ) kh;

  RETURN COALESCE(v_result, jsonb_build_object(
    'data', '[]'::jsonb,
    'total', 0,
    'page', v_page,
    'pageSize', v_page_size
  ));
END;
$$;


ALTER FUNCTION public.maintenance_plan_list(p_q text, p_don_vi bigint, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION maintenance_plan_list(p_q text, p_don_vi bigint, p_page integer, p_page_size integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.maintenance_plan_list(p_q text, p_don_vi bigint, p_page integer, p_page_size integer) IS 'Lists maintenance plans with server-side pagination and facility filtering.

PARAMETERS:
- p_q: Text search across name, department, year, work type, facility name
- p_don_vi: Facility filter (NULL = all accessible facilities)
- p_page: Page number (default 1, min 1)
- p_page_size: Items per page (default 50, max 200)

SECURITY:
- Tenant visibility governed by allowed_don_vi_for_session_safe()
- Search patterns sanitized via _sanitize_ilike_pattern()
';


--
-- Name: maintenance_plan_reject(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_plan_reject(p_id bigint, p_nguoi_duyet text, p_ly_do text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_guard record;
  v_plan public.ke_hoach_bao_tri;
BEGIN
  SELECT * INTO v_guard FROM public._assert_maintenance_write_allowed();

  SELECT *
  INTO v_plan
  FROM public.ke_hoach_bao_tri
  WHERE id = p_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF NOT v_guard.is_global AND (v_plan.don_vi IS NULL OR NOT v_plan.don_vi = ANY(v_guard.allowed_don_vi)) THEN
    RAISE EXCEPTION 'Không có quyền trên kế hoạch bảo trì thuộc đơn vị khác' USING ERRCODE = '42501';
  END IF;

  UPDATE public.ke_hoach_bao_tri
  SET trang_thai = 'Không duyệt',
      ngay_phe_duyet = now(),
      nguoi_duyet = p_nguoi_duyet,
      ly_do_khong_duyet = p_ly_do
  WHERE id = p_id;
END;
$$;


ALTER FUNCTION public.maintenance_plan_reject(p_id bigint, p_nguoi_duyet text, p_ly_do text) OWNER TO postgres;

--
-- Name: maintenance_plan_status_counts(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_plan_status_counts(p_don_vi bigint DEFAULT NULL::bigint, p_q text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jwt_claims jsonb;
  v_role text;
  v_user_id text;
  v_don_vi bigint;
  v_is_global boolean := false;
  v_allowed_don_vi bigint[];
  v_department_scope text;
  v_result jsonb;
  v_sanitized_q text;
BEGIN
  v_jwt_claims := COALESCE(NULLIF(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  v_role := lower(COALESCE(v_jwt_claims->>'app_role', v_jwt_claims->>'role', ''));
  v_user_id := NULLIF(COALESCE(v_jwt_claims->>'user_id', v_jwt_claims->>'sub'), '');
  v_don_vi := NULLIF(v_jwt_claims->>'don_vi', '')::bigint;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_global := v_role = 'global';

  IF v_role NOT IN ('global', 'regional_leader') AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  v_allowed_don_vi := public.allowed_don_vi_for_session_safe();

  IF NOT v_is_global AND (v_allowed_don_vi IS NULL OR array_length(v_allowed_don_vi, 1) IS NULL) THEN
    RETURN jsonb_build_object('Bản nháp', 0, 'Đã duyệt', 0, 'Không duyệt', 0);
  END IF;

  IF NOT v_is_global AND p_don_vi IS NOT NULL AND NOT (p_don_vi = ANY(v_allowed_don_vi)) THEN
    RAISE EXCEPTION 'Access denied to facility %', p_don_vi
      USING ERRCODE = '42501',
            HINT = 'You do not have permission to access this facility';
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_jwt_claims->>'khoa_phong');
    IF v_department_scope IS NULL THEN
      RETURN jsonb_build_object('Bản nháp', 0, 'Đã duyệt', 0, 'Không duyệt', 0);
    END IF;
  END IF;

  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  SELECT jsonb_build_object(
    'Bản nháp', COALESCE(SUM(CASE WHEN kh.trang_thai = 'Bản nháp' THEN 1 ELSE 0 END), 0),
    'Đã duyệt', COALESCE(SUM(CASE WHEN kh.trang_thai = 'Đã duyệt' THEN 1 ELSE 0 END), 0),
    'Không duyệt', COALESCE(SUM(CASE WHEN kh.trang_thai = 'Không duyệt' THEN 1 ELSE 0 END), 0)
  )
  INTO v_result
  FROM public.ke_hoach_bao_tri kh
  LEFT JOIN public.don_vi dv ON kh.don_vi = dv.id
  WHERE (
      v_sanitized_q IS NULL
      OR kh.ten_ke_hoach ILIKE '%' || v_sanitized_q || '%'
      OR COALESCE(kh.khoa_phong, '') ILIKE '%' || v_sanitized_q || '%'
      OR COALESCE(kh.nguoi_lap_ke_hoach, '') ILIKE '%' || v_sanitized_q || '%'
      OR COALESCE(kh.loai_cong_viec, '') ILIKE '%' || v_sanitized_q || '%'
      OR COALESCE(dv.name, '') ILIKE '%' || v_sanitized_q || '%'
      OR CAST(kh.nam AS text) ILIKE '%' || v_sanitized_q || '%'
    )
    AND (
      CASE
        WHEN p_don_vi IS NOT NULL THEN kh.don_vi = p_don_vi
        ELSE v_is_global OR kh.don_vi = ANY(v_allowed_don_vi)
      END
    )
    AND (
      v_role <> 'user'
      OR public._normalize_department_scope(kh.khoa_phong) = v_department_scope
    );

  RETURN COALESCE(v_result, jsonb_build_object('Bản nháp', 0, 'Đã duyệt', 0, 'Không duyệt', 0));
END;
$$;


ALTER FUNCTION public.maintenance_plan_status_counts(p_don_vi bigint, p_q text) OWNER TO postgres;

--
-- Name: FUNCTION maintenance_plan_status_counts(p_don_vi bigint, p_q text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.maintenance_plan_status_counts(p_don_vi bigint, p_q text) IS 'Returns status distribution counts for maintenance plans, scoped by tenant security.

PARAMETERS:
- p_don_vi: Facility filter (NULL = all accessible facilities)
- p_q: Text search across name, department, year, work type, facility name

RETURNS: JSONB { "Bản nháp": N, "Đã duyệt": N, "Không duyệt": N }

SECURITY:
- Global users: see all plans from all active tenants
- Regional leaders: see plans only from facilities in assigned region
- Regular users: see plans only from their tenant
- Facility filter enforces access via allowed_don_vi_for_session_safe()
- ILIKE patterns sanitized via _sanitize_ilike_pattern()

PATTERN: Matches maintenance_plan_list tenant scoping (migration 20251013093831)
ISSUE: #214 — KPI Status Cards Batch 3';


--
-- Name: maintenance_plan_update(bigint, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_plan_update(p_id bigint, p_ten_ke_hoach text, p_nam integer, p_loai_cong_viec text, p_khoa_phong text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_guard record;
  v_plan public.ke_hoach_bao_tri;
BEGIN
  SELECT * INTO v_guard FROM public._assert_maintenance_write_allowed();

  SELECT *
  INTO v_plan
  FROM public.ke_hoach_bao_tri
  WHERE id = p_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Kế hoạch không tồn tại' USING ERRCODE = 'P0002';
  END IF;

  IF NOT v_guard.is_global AND (v_plan.don_vi IS NULL OR NOT v_plan.don_vi = ANY(v_guard.allowed_don_vi)) THEN
    RAISE EXCEPTION 'Không có quyền trên kế hoạch bảo trì thuộc đơn vị khác' USING ERRCODE = '42501';
  END IF;

  UPDATE public.ke_hoach_bao_tri
  SET ten_ke_hoach = COALESCE(p_ten_ke_hoach, ten_ke_hoach),
      nam = COALESCE(p_nam, nam),
      loai_cong_viec = COALESCE(p_loai_cong_viec, loai_cong_viec),
      khoa_phong = COALESCE(NULLIF(p_khoa_phong, ''), khoa_phong)
  WHERE id = p_id;
END;
$$;


ALTER FUNCTION public.maintenance_plan_update(p_id bigint, p_ten_ke_hoach text, p_nam integer, p_loai_cong_viec text, p_khoa_phong text) OWNER TO postgres;

--
-- Name: maintenance_stats_enhanced(date, date, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_stats_enhanced(p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_allowed BIGINT[] := public.allowed_don_vi_for_session();
  v_effective BIGINT[] := NULL;
  result JSONB;
  v_from DATE := COALESCE(p_date_from, CURRENT_DATE - INTERVAL '1 year');
  v_to DATE := COALESCE(p_date_to, CURRENT_DATE);
BEGIN
  IF v_role = 'global' THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN jsonb_build_object(
        'repair_summary', jsonb_build_object('total_requests',0,'completed',0,'pending',0,'in_progress',0),
        'maintenance_summary', jsonb_build_object('total_plans',0,'total_tasks',0,'completed_tasks',0)
      );
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT p_don_vi = ANY(v_allowed) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_effective IS NOT NULL AND array_length(v_effective, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'repair_summary', jsonb_build_object('total_requests',0,'completed',0,'pending',0,'in_progress',0),
      'maintenance_summary', jsonb_build_object('total_plans',0,'total_tasks',0,'completed_tasks',0)
    );
  END IF;

  SELECT jsonb_build_object(
    'repair_summary', (
      SELECT jsonb_build_object(
        'total_requests', COUNT(*),
        'completed', COUNT(*) FILTER (WHERE yc.trang_thai = 'hoan_thanh'),
        'pending', COUNT(*) FILTER (WHERE yc.trang_thai = 'cho_duyet'),
        'in_progress', COUNT(*) FILTER (WHERE yc.trang_thai = 'dang_xu_ly')
      )
      FROM public.yeu_cau_sua_chua yc
      LEFT JOIN public.thiet_bi tb ON yc.thiet_bi_id = tb.id
      WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
        AND yc.created_at::date BETWEEN v_from AND v_to
    ),
    'maintenance_summary', (
      SELECT jsonb_build_object(
        'total_plans', COUNT(DISTINCT kh.id),
        'total_tasks', COUNT(cv.id),
        'completed_tasks', COUNT(*) FILTER (WHERE cv.trang_thai = 'hoan_thanh')
      )
      FROM public.ke_hoach_bao_tri kh
      LEFT JOIN public.cong_viec_bao_tri cv ON kh.id = cv.ke_hoach_id
      LEFT JOIN public.thiet_bi tb ON cv.thiet_bi_id = tb.id
      WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
        AND kh.created_at::date BETWEEN v_from AND v_to
    )
  ) INTO result;

  RETURN COALESCE(result, jsonb_build_object(
    'repair_summary', jsonb_build_object('total_requests',0,'completed',0,'pending',0,'in_progress',0),
    'maintenance_summary', jsonb_build_object('total_plans',0,'total_tasks',0,'completed_tasks',0)
  ));
END;
$$;


ALTER FUNCTION public.maintenance_stats_enhanced(p_date_from date, p_date_to date, p_don_vi bigint) OWNER TO postgres;

--
-- Name: maintenance_stats_enhanced(date, date, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_stats_enhanced(p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_don_vi bigint DEFAULT NULL::bigint, p_khoa_phong text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role TEXT := COALESCE(public._get_jwt_claim('app_role'), '');
  v_claim_donvi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_effective_donvi BIGINT := NULL;
  result JSONB;
  v_from DATE := COALESCE(p_date_from, CURRENT_DATE - INTERVAL '1 year');
  v_to DATE := COALESCE(p_date_to, CURRENT_DATE);
BEGIN
  IF v_role = 'global' THEN
    v_effective_donvi := p_don_vi; -- NULL => all
  ELSE
    v_effective_donvi := v_claim_donvi;
  END IF;

  SELECT jsonb_build_object(
    'repair_summary', (
      SELECT jsonb_build_object(
        'total_requests', COUNT(*),
        'completed', COUNT(*) FILTER (WHERE yc.trang_thai = 'hoan_thanh'),
        'pending', COUNT(*) FILTER (WHERE yc.trang_thai = 'cho_duyet'),
        'in_progress', COUNT(*) FILTER (WHERE yc.trang_thai = 'dang_xu_ly')
      )
      FROM public.yeu_cau_sua_chua yc
      LEFT JOIN public.thiet_bi tb ON yc.thiet_bi_id = tb.id
      WHERE (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)
        AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong)
        AND yc.created_at::date BETWEEN v_from AND v_to
    ),
    'maintenance_summary', (
      SELECT jsonb_build_object(
        'total_plans', COUNT(DISTINCT kh.id),
        'total_tasks', COUNT(cv.id),
        'completed_tasks', COUNT(*) FILTER (WHERE cv.trang_thai = 'hoan_thanh')
      )
      FROM public.ke_hoach_bao_tri kh
      LEFT JOIN public.cong_viec_bao_tri cv ON kh.id = cv.ke_hoach_id
      LEFT JOIN public.thiet_bi tb ON cv.thiet_bi_id = tb.id
      WHERE (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)
        AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong)
        AND kh.created_at::date BETWEEN v_from AND v_to
    )
  ) INTO result;

  RETURN result;
END;
$$;


ALTER FUNCTION public.maintenance_stats_enhanced(p_date_from date, p_date_to date, p_don_vi bigint, p_khoa_phong text) OWNER TO postgres;

--
-- Name: maintenance_stats_for_reports(date, date, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_stats_for_reports(p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_don_vi bigint DEFAULT NULL::bigint, p_khoa_phong text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id text := nullif(public._get_jwt_claim('user_id'), '');
  v_is_global boolean := false;
  v_claim_donvi bigint := nullif(public._get_jwt_claim('don_vi'), '')::bigint;
  v_allowed bigint[];
  v_effective bigint[];
  v_from date := coalesce(p_date_from, current_date - interval '1 year');
  v_to date := coalesce(p_date_to, current_date);
  v_from_year integer := extract(year from v_from)::integer;
  v_to_year integer := extract(year from v_to)::integer;
  result jsonb;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  v_is_global := v_role IN ('global', 'admin');

  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      v_effective := ARRAY[]::bigint[];
    ELSIF p_don_vi IS NOT NULL THEN
      IF p_don_vi = ANY(v_allowed) THEN
        v_effective := ARRAY[p_don_vi];
      ELSE
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING errcode = '42501';
      END IF;
    ELSE
      v_effective := v_allowed;
    END IF;
  ELSE
    IF v_claim_donvi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim for non-global role %', v_role USING errcode = '42501';
    END IF;
    IF p_don_vi IS NOT NULL AND p_don_vi <> v_claim_donvi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING errcode = '42501';
    END IF;
    v_effective := ARRAY[v_claim_donvi];
  END IF;

  SELECT jsonb_build_object(
    'repair_summary', (
      SELECT jsonb_build_object(
        'total_requests', count(*),
        'completed', count(*) FILTER (
          WHERE lower(coalesce(yc.trang_thai, '')) LIKE '%hoàn thành%'
             OR lower(coalesce(yc.trang_thai, '')) LIKE '%hoan thanh%'
        ),
        'pending', count(*) FILTER (
          WHERE lower(coalesce(yc.trang_thai, '')) LIKE '%chờ%'
             OR lower(coalesce(yc.trang_thai, '')) LIKE '%cho%'
        ),
        'in_progress', count(*) FILTER (
          WHERE lower(coalesce(yc.trang_thai, '')) LIKE '%đã duyệt%'
             OR lower(coalesce(yc.trang_thai, '')) LIKE '%da duyet%'
        ),
        'total_cost', coalesce(sum(yc.chi_phi_sua_chua) FILTER (
          WHERE lower(coalesce(yc.trang_thai, '')) LIKE '%hoàn thành%'
             OR lower(coalesce(yc.trang_thai, '')) LIKE '%hoan thanh%'
        ), 0),
        'average_completed_cost', coalesce(avg(yc.chi_phi_sua_chua) FILTER (
          WHERE (lower(coalesce(yc.trang_thai, '')) LIKE '%hoàn thành%'
             OR lower(coalesce(yc.trang_thai, '')) LIKE '%hoan thanh%')
            AND yc.chi_phi_sua_chua IS NOT NULL
        ), 0),
        'cost_recorded_count', count(*) FILTER (
          WHERE (lower(coalesce(yc.trang_thai, '')) LIKE '%hoàn thành%'
             OR lower(coalesce(yc.trang_thai, '')) LIKE '%hoan thanh%')
            AND yc.chi_phi_sua_chua IS NOT NULL
        ),
        'cost_missing_count', count(*) FILTER (
          WHERE (lower(coalesce(yc.trang_thai, '')) LIKE '%hoàn thành%'
             OR lower(coalesce(yc.trang_thai, '')) LIKE '%hoan thanh%')
            AND yc.chi_phi_sua_chua IS NULL
        )
      )
      FROM public.yeu_cau_sua_chua yc
      LEFT JOIN public.thiet_bi tb ON yc.thiet_bi_id = tb.id
      WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
        AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong)
        AND coalesce(yc.ngay_yeu_cau, yc.ngay_duyet, yc.ngay_hoan_thanh) IS NOT NULL
        AND (coalesce(yc.ngay_yeu_cau, yc.ngay_duyet, yc.ngay_hoan_thanh) AT TIME ZONE 'Asia/Ho_Chi_Minh')::date BETWEEN v_from AND v_to
    ),
    'maintenance_summary', (
      SELECT jsonb_build_object(
        'total_plans', count(DISTINCT kh.id),
        'total_tasks', count(cv.id),
        'completed_tasks', count(*) FILTER (
          WHERE
            coalesce(cv.thang_1_hoan_thanh,false) OR coalesce(cv.thang_2_hoan_thanh,false) OR
            coalesce(cv.thang_3_hoan_thanh,false) OR coalesce(cv.thang_4_hoan_thanh,false) OR
            coalesce(cv.thang_5_hoan_thanh,false) OR coalesce(cv.thang_6_hoan_thanh,false) OR
            coalesce(cv.thang_7_hoan_thanh,false) OR coalesce(cv.thang_8_hoan_thanh,false) OR
            coalesce(cv.thang_9_hoan_thanh,false) OR coalesce(cv.thang_10_hoan_thanh,false) OR
            coalesce(cv.thang_11_hoan_thanh,false) OR coalesce(cv.thang_12_hoan_thanh,false) OR
            cv.ngay_hoan_thanh_1 IS NOT NULL OR cv.ngay_hoan_thanh_2 IS NOT NULL OR
            cv.ngay_hoan_thanh_3 IS NOT NULL OR cv.ngay_hoan_thanh_4 IS NOT NULL OR
            cv.ngay_hoan_thanh_5 IS NOT NULL OR cv.ngay_hoan_thanh_6 IS NOT NULL OR
            cv.ngay_hoan_thanh_7 IS NOT NULL OR cv.ngay_hoan_thanh_8 IS NOT NULL OR
            cv.ngay_hoan_thanh_9 IS NOT NULL OR cv.ngay_hoan_thanh_10 IS NOT NULL OR
            cv.ngay_hoan_thanh_11 IS NOT NULL OR cv.ngay_hoan_thanh_12 IS NOT NULL
        )
      )
      FROM public.ke_hoach_bao_tri kh
      LEFT JOIN public.cong_viec_bao_tri cv ON kh.id = cv.ke_hoach_id
      LEFT JOIN public.thiet_bi tb ON cv.thiet_bi_id = tb.id
      WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
        AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong)
        AND kh.nam BETWEEN v_from_year AND v_to_year
    )
  ) INTO result;

  RETURN coalesce(result, jsonb_build_object(
    'repair_summary', jsonb_build_object(
      'total_requests', 0,
      'completed', 0,
      'pending', 0,
      'in_progress', 0,
      'total_cost', 0,
      'average_completed_cost', 0,
      'cost_recorded_count', 0,
      'cost_missing_count', 0
    ),
    'maintenance_summary', jsonb_build_object(
      'total_plans', 0,
      'total_tasks', 0,
      'completed_tasks', 0
    )
  ));
END;
$$;


