--
-- Name: maintenance_task_complete(bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_task_complete(p_task_id bigint, p_month integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_guard record;
  v_task public.cong_viec_bao_tri;
  v_plan public.ke_hoach_bao_tri;
  v_equipment_don_vi bigint;
  v_date timestamptz := now();
  v_month_col text;
  v_month_date_col text;
BEGIN
  SELECT * INTO v_guard FROM public._assert_maintenance_write_allowed();

  IF p_month IS NULL OR p_month < 1 OR p_month > 12 THEN
    RAISE EXCEPTION 'Tháng hoàn thành không hợp lệ' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_task
  FROM public.cong_viec_bao_tri
  WHERE id = p_task_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT *
  INTO v_plan
  FROM public.ke_hoach_bao_tri
  WHERE id = v_task.ke_hoach_id
  FOR UPDATE;

  IF NOT v_guard.is_global AND (v_plan.don_vi IS NULL OR NOT v_plan.don_vi = ANY(v_guard.allowed_don_vi)) THEN
    RAISE EXCEPTION 'Không có quyền hoàn thành công việc bảo trì thuộc đơn vị khác' USING ERRCODE = '42501';
  END IF;

  IF v_task.thiet_bi_id IS NOT NULL THEN
    SELECT don_vi
    INTO v_equipment_don_vi
    FROM public.thiet_bi
    WHERE id = v_task.thiet_bi_id
      AND is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Thiết bị không tồn tại' USING ERRCODE = 'P0002';
    END IF;

    IF NOT v_guard.is_global AND (v_equipment_don_vi IS NULL OR NOT v_equipment_don_vi = ANY(v_guard.allowed_don_vi)) THEN
      RAISE EXCEPTION 'Không có quyền hoàn thành công việc bảo trì cho thiết bị thuộc đơn vị khác' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_month_col := format('thang_%s_hoan_thanh', p_month);
  v_month_date_col := format('ngay_hoan_thanh_%s', p_month);

  EXECUTE format('UPDATE public.cong_viec_bao_tri SET %I = true, %I = $1, updated_at = $1 WHERE id = $2', v_month_col, v_month_date_col)
    USING v_date, p_task_id;

  IF v_task.thiet_bi_id IS NOT NULL THEN
    INSERT INTO public.lich_su_thiet_bi(thiet_bi_id, loai_su_kien, mo_ta, chi_tiet, ngay_thuc_hien)
    VALUES (
      v_task.thiet_bi_id,
      v_task.loai_cong_viec,
      format('Hoàn thành %s tháng %s/%s theo kế hoạch "%s"', v_task.loai_cong_viec, p_month, v_plan.nam, v_plan.ten_ke_hoach),
      jsonb_build_object('cong_viec_id', p_task_id, 'thang', p_month, 'ten_ke_hoach', v_plan.ten_ke_hoach, 'khoa_phong', v_plan.khoa_phong, 'nam', v_plan.nam),
      v_date
    );
  END IF;
END;
$_$;


ALTER FUNCTION public.maintenance_task_complete(p_task_id bigint, p_month integer) OWNER TO postgres;

--
-- Name: maintenance_task_update(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_task_update(p_id bigint, p_task jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_guard record;
  v_task public.cong_viec_bao_tri;
  v_plan_don_vi bigint;
  v_new_plan_don_vi bigint;
  v_new_equipment_don_vi bigint;
BEGIN
  SELECT * INTO v_guard FROM public._assert_maintenance_write_allowed();

  SELECT *
  INTO v_task
  FROM public.cong_viec_bao_tri
  WHERE id = p_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Công việc bảo trì không tồn tại' USING ERRCODE = 'P0002';
  END IF;

  SELECT don_vi
  INTO v_plan_don_vi
  FROM public.ke_hoach_bao_tri
  WHERE id = v_task.ke_hoach_id
  FOR UPDATE;

  IF NOT v_guard.is_global AND (v_plan_don_vi IS NULL OR NOT v_plan_don_vi = ANY(v_guard.allowed_don_vi)) THEN
    RAISE EXCEPTION 'Không có quyền cập nhật công việc bảo trì thuộc đơn vị khác' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(p_task->>'ke_hoach_id', '') IS NOT NULL THEN
    SELECT don_vi
    INTO v_new_plan_don_vi
    FROM public.ke_hoach_bao_tri
    WHERE id = NULLIF(p_task->>'ke_hoach_id', '')::bigint
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Kế hoạch bảo trì không tồn tại' USING ERRCODE = 'P0002';
    END IF;

    IF NOT v_guard.is_global AND (v_new_plan_don_vi IS NULL OR NOT v_new_plan_don_vi = ANY(v_guard.allowed_don_vi)) THEN
      RAISE EXCEPTION 'Không có quyền chuyển công việc bảo trì sang kế hoạch thuộc đơn vị khác' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NULLIF(p_task->>'thiet_bi_id', '') IS NOT NULL THEN
    SELECT don_vi
    INTO v_new_equipment_don_vi
    FROM public.thiet_bi
    WHERE id = NULLIF(p_task->>'thiet_bi_id', '')::bigint
      AND is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Thiết bị không tồn tại' USING ERRCODE = 'P0002';
    END IF;

    IF NOT v_guard.is_global AND (v_new_equipment_don_vi IS NULL OR NOT v_new_equipment_don_vi = ANY(v_guard.allowed_don_vi)) THEN
      RAISE EXCEPTION 'Không có quyền gán công việc bảo trì cho thiết bị thuộc đơn vị khác' USING ERRCODE = '42501';
    END IF;
  END IF;

  UPDATE public.cong_viec_bao_tri
  SET ke_hoach_id = COALESCE(NULLIF(p_task->>'ke_hoach_id', '')::bigint, ke_hoach_id),
      thiet_bi_id = COALESCE(NULLIF(p_task->>'thiet_bi_id', '')::bigint, thiet_bi_id),
      loai_cong_viec = COALESCE(p_task->>'loai_cong_viec', loai_cong_viec),
      diem_hieu_chuan = COALESCE(p_task->>'diem_hieu_chuan', diem_hieu_chuan),
      don_vi_thuc_hien = COALESCE(p_task->>'don_vi_thuc_hien', don_vi_thuc_hien),
      thang_1 = COALESCE((p_task->>'thang_1')::boolean, thang_1), thang_2 = COALESCE((p_task->>'thang_2')::boolean, thang_2),
      thang_3 = COALESCE((p_task->>'thang_3')::boolean, thang_3), thang_4 = COALESCE((p_task->>'thang_4')::boolean, thang_4),
      thang_5 = COALESCE((p_task->>'thang_5')::boolean, thang_5), thang_6 = COALESCE((p_task->>'thang_6')::boolean, thang_6),
      thang_7 = COALESCE((p_task->>'thang_7')::boolean, thang_7), thang_8 = COALESCE((p_task->>'thang_8')::boolean, thang_8),
      thang_9 = COALESCE((p_task->>'thang_9')::boolean, thang_9), thang_10 = COALESCE((p_task->>'thang_10')::boolean, thang_10),
      thang_11 = COALESCE((p_task->>'thang_11')::boolean, thang_11), thang_12 = COALESCE((p_task->>'thang_12')::boolean, thang_12),
      thang_1_hoan_thanh = COALESCE((p_task->>'thang_1_hoan_thanh')::boolean, thang_1_hoan_thanh), thang_2_hoan_thanh = COALESCE((p_task->>'thang_2_hoan_thanh')::boolean, thang_2_hoan_thanh),
      thang_3_hoan_thanh = COALESCE((p_task->>'thang_3_hoan_thanh')::boolean, thang_3_hoan_thanh), thang_4_hoan_thanh = COALESCE((p_task->>'thang_4_hoan_thanh')::boolean, thang_4_hoan_thanh),
      thang_5_hoan_thanh = COALESCE((p_task->>'thang_5_hoan_thanh')::boolean, thang_5_hoan_thanh), thang_6_hoan_thanh = COALESCE((p_task->>'thang_6_hoan_thanh')::boolean, thang_6_hoan_thanh),
      thang_7_hoan_thanh = COALESCE((p_task->>'thang_7_hoan_thanh')::boolean, thang_7_hoan_thanh), thang_8_hoan_thanh = COALESCE((p_task->>'thang_8_hoan_thanh')::boolean, thang_8_hoan_thanh),
      thang_9_hoan_thanh = COALESCE((p_task->>'thang_9_hoan_thanh')::boolean, thang_9_hoan_thanh), thang_10_hoan_thanh = COALESCE((p_task->>'thang_10_hoan_thanh')::boolean, thang_10_hoan_thanh),
      thang_11_hoan_thanh = COALESCE((p_task->>'thang_11_hoan_thanh')::boolean, thang_11_hoan_thanh), thang_12_hoan_thanh = COALESCE((p_task->>'thang_12_hoan_thanh')::boolean, thang_12_hoan_thanh),
      ngay_hoan_thanh_1 = COALESCE((p_task->>'ngay_hoan_thanh_1')::timestamptz, ngay_hoan_thanh_1), ngay_hoan_thanh_2 = COALESCE((p_task->>'ngay_hoan_thanh_2')::timestamptz, ngay_hoan_thanh_2),
      ngay_hoan_thanh_3 = COALESCE((p_task->>'ngay_hoan_thanh_3')::timestamptz, ngay_hoan_thanh_3), ngay_hoan_thanh_4 = COALESCE((p_task->>'ngay_hoan_thanh_4')::timestamptz, ngay_hoan_thanh_4),
      ngay_hoan_thanh_5 = COALESCE((p_task->>'ngay_hoan_thanh_5')::timestamptz, ngay_hoan_thanh_5), ngay_hoan_thanh_6 = COALESCE((p_task->>'ngay_hoan_thanh_6')::timestamptz, ngay_hoan_thanh_6),
      ngay_hoan_thanh_7 = COALESCE((p_task->>'ngay_hoan_thanh_7')::timestamptz, ngay_hoan_thanh_7), ngay_hoan_thanh_8 = COALESCE((p_task->>'ngay_hoan_thanh_8')::timestamptz, ngay_hoan_thanh_8),
      ngay_hoan_thanh_9 = COALESCE((p_task->>'ngay_hoan_thanh_9')::timestamptz, ngay_hoan_thanh_9), ngay_hoan_thanh_10 = COALESCE((p_task->>'ngay_hoan_thanh_10')::timestamptz, ngay_hoan_thanh_10),
      ngay_hoan_thanh_11 = COALESCE((p_task->>'ngay_hoan_thanh_11')::timestamptz, ngay_hoan_thanh_11), ngay_hoan_thanh_12 = COALESCE((p_task->>'ngay_hoan_thanh_12')::timestamptz, ngay_hoan_thanh_12),
      ghi_chu = COALESCE(p_task->>'ghi_chu', ghi_chu),
      updated_at = now()
  WHERE id = p_id;
END;
$$;


ALTER FUNCTION public.maintenance_task_update(p_id bigint, p_task jsonb) OWNER TO postgres;

--
-- Name: maintenance_tasks_bulk_insert(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_tasks_bulk_insert(p_tasks jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_guard record;
  v_item jsonb;
  v_ke_hoach_id bigint;
  v_thiet_bi_id bigint;
  v_plan public.ke_hoach_bao_tri;
  v_equipment_don_vi bigint;
BEGIN
  SELECT * INTO v_guard FROM public._assert_maintenance_write_allowed();

  IF p_tasks IS NULL OR jsonb_array_length(p_tasks) = 0 THEN
    RETURN;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_tasks) AS value LOOP
    v_ke_hoach_id := NULLIF(v_item->>'ke_hoach_id', '')::bigint;
    v_thiet_bi_id := NULLIF(v_item->>'thiet_bi_id', '')::bigint;

    SELECT *
    INTO v_plan
    FROM public.ke_hoach_bao_tri
    WHERE id = v_ke_hoach_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Kế hoạch bảo trì không tồn tại' USING ERRCODE = 'P0002';
    END IF;

    IF NOT v_guard.is_global AND (v_plan.don_vi IS NULL OR NOT v_plan.don_vi = ANY(v_guard.allowed_don_vi)) THEN
      RAISE EXCEPTION 'Không có quyền thêm công việc bảo trì cho kế hoạch thuộc đơn vị khác' USING ERRCODE = '42501';
    END IF;

    IF v_thiet_bi_id IS NOT NULL THEN
      SELECT don_vi
      INTO v_equipment_don_vi
      FROM public.thiet_bi
      WHERE id = v_thiet_bi_id
        AND is_deleted = false
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Thiết bị không tồn tại' USING ERRCODE = 'P0002';
      END IF;

      IF NOT v_guard.is_global AND (v_equipment_don_vi IS NULL OR NOT v_equipment_don_vi = ANY(v_guard.allowed_don_vi)) THEN
        RAISE EXCEPTION 'Không có quyền thêm công việc bảo trì cho thiết bị thuộc đơn vị khác' USING ERRCODE = '42501';
      END IF;
    END IF;
  END LOOP;

  INSERT INTO public.cong_viec_bao_tri (
    ke_hoach_id, thiet_bi_id, loai_cong_viec, diem_hieu_chuan, don_vi_thuc_hien,
    thang_1, thang_2, thang_3, thang_4, thang_5, thang_6,
    thang_7, thang_8, thang_9, thang_10, thang_11, thang_12, ghi_chu
  )
  SELECT
    (t->>'ke_hoach_id')::bigint, NULLIF(t->>'thiet_bi_id', '')::bigint,
    t->>'loai_cong_viec', t->>'diem_hieu_chuan', t->>'don_vi_thuc_hien',
    COALESCE((t->>'thang_1')::boolean, false), COALESCE((t->>'thang_2')::boolean, false),
    COALESCE((t->>'thang_3')::boolean, false), COALESCE((t->>'thang_4')::boolean, false),
    COALESCE((t->>'thang_5')::boolean, false), COALESCE((t->>'thang_6')::boolean, false),
    COALESCE((t->>'thang_7')::boolean, false), COALESCE((t->>'thang_8')::boolean, false),
    COALESCE((t->>'thang_9')::boolean, false), COALESCE((t->>'thang_10')::boolean, false),
    COALESCE((t->>'thang_11')::boolean, false), COALESCE((t->>'thang_12')::boolean, false),
    t->>'ghi_chu'
  FROM jsonb_array_elements(p_tasks) AS t;
END;
$$;


ALTER FUNCTION public.maintenance_tasks_bulk_insert(p_tasks jsonb) OWNER TO postgres;

--
-- Name: maintenance_tasks_delete(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_tasks_delete(p_ids bigint[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_guard record;
  v_denied_count bigint;
BEGIN
  SELECT * INTO v_guard FROM public._assert_maintenance_write_allowed();

  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  IF NOT v_guard.is_global THEN
    PERFORM 1
    FROM public.cong_viec_bao_tri cv
    JOIN public.ke_hoach_bao_tri kh ON kh.id = cv.ke_hoach_id
    WHERE cv.id = ANY(p_ids)
    FOR UPDATE OF cv, kh;

    PERFORM 1
    FROM public.cong_viec_bao_tri cv
    JOIN public.thiet_bi tb ON tb.id = cv.thiet_bi_id
    WHERE cv.id = ANY(p_ids)
    FOR UPDATE OF tb;

    SELECT count(*)
    INTO v_denied_count
    FROM public.cong_viec_bao_tri cv
    JOIN public.ke_hoach_bao_tri kh ON kh.id = cv.ke_hoach_id
    LEFT JOIN public.thiet_bi tb ON tb.id = cv.thiet_bi_id
    WHERE cv.id = ANY(p_ids)
      AND (
        kh.don_vi IS NULL
        OR NOT kh.don_vi = ANY(v_guard.allowed_don_vi)
        OR (
          cv.thiet_bi_id IS NOT NULL
          AND (tb.id IS NULL OR tb.don_vi IS NULL OR NOT tb.don_vi = ANY(v_guard.allowed_don_vi))
        )
      );

    IF v_denied_count > 0 THEN
      RAISE EXCEPTION 'Không có quyền xóa công việc bảo trì thuộc đơn vị khác' USING ERRCODE = '42501';
    END IF;
  END IF;

  DELETE FROM public.cong_viec_bao_tri WHERE id = ANY(p_ids);
END;
$$;


ALTER FUNCTION public.maintenance_tasks_delete(p_ids bigint[]) OWNER TO postgres;

--
-- Name: cong_viec_bao_tri; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.cong_viec_bao_tri (
    id bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    ke_hoach_id bigint NOT NULL,
    thiet_bi_id bigint,
    loai_cong_viec text,
    diem_hieu_chuan text,
    don_vi_thuc_hien text,
    thang_1 boolean DEFAULT false,
    thang_2 boolean DEFAULT false,
    thang_3 boolean DEFAULT false,
    thang_4 boolean DEFAULT false,
    thang_5 boolean DEFAULT false,
    thang_6 boolean DEFAULT false,
    thang_7 boolean DEFAULT false,
    thang_8 boolean DEFAULT false,
    thang_9 boolean DEFAULT false,
    thang_10 boolean DEFAULT false,
    thang_11 boolean DEFAULT false,
    thang_12 boolean DEFAULT false,
    ghi_chu text,
    thang_1_hoan_thanh boolean DEFAULT false,
    thang_2_hoan_thanh boolean DEFAULT false,
    thang_3_hoan_thanh boolean DEFAULT false,
    thang_4_hoan_thanh boolean DEFAULT false,
    thang_5_hoan_thanh boolean DEFAULT false,
    thang_6_hoan_thanh boolean DEFAULT false,
    thang_7_hoan_thanh boolean DEFAULT false,
    thang_8_hoan_thanh boolean DEFAULT false,
    thang_9_hoan_thanh boolean DEFAULT false,
    thang_10_hoan_thanh boolean DEFAULT false,
    thang_11_hoan_thanh boolean DEFAULT false,
    thang_12_hoan_thanh boolean DEFAULT false,
    ngay_hoan_thanh_1 timestamp with time zone,
    ngay_hoan_thanh_2 timestamp with time zone,
    ngay_hoan_thanh_3 timestamp with time zone,
    ngay_hoan_thanh_4 timestamp with time zone,
    ngay_hoan_thanh_5 timestamp with time zone,
    ngay_hoan_thanh_6 timestamp with time zone,
    ngay_hoan_thanh_7 timestamp with time zone,
    ngay_hoan_thanh_8 timestamp with time zone,
    ngay_hoan_thanh_9 timestamp with time zone,
    ngay_hoan_thanh_10 timestamp with time zone,
    ngay_hoan_thanh_11 timestamp with time zone,
    ngay_hoan_thanh_12 timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now()
);


ALTER TABLE public.cong_viec_bao_tri OWNER TO postgres;

--
-- Name: maintenance_tasks_list(bigint, bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_tasks_list(p_ke_hoach_id bigint DEFAULT NULL::bigint, p_thiet_bi_id bigint DEFAULT NULL::bigint, p_loai_cong_viec text DEFAULT NULL::text, p_don_vi_thuc_hien text DEFAULT NULL::text) RETURNS SETOF public.cong_viec_bao_tri
    LANGUAGE sql SECURITY DEFINER
    AS $$
  select * from cong_viec_bao_tri
  where (p_ke_hoach_id is null or ke_hoach_id = p_ke_hoach_id)
    and (p_thiet_bi_id is null or thiet_bi_id = p_thiet_bi_id)
    and (p_loai_cong_viec is null or loai_cong_viec = p_loai_cong_viec)
    and (p_don_vi_thuc_hien is null or don_vi_thuc_hien = p_don_vi_thuc_hien)
  order by created_at desc;
$$;


ALTER FUNCTION public.maintenance_tasks_list(p_ke_hoach_id bigint, p_thiet_bi_id bigint, p_loai_cong_viec text, p_don_vi_thuc_hien text) OWNER TO postgres;

--
-- Name: maintenance_tasks_list_with_equipment(bigint, bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintenance_tasks_list_with_equipment(p_ke_hoach_id bigint DEFAULT NULL::bigint, p_thiet_bi_id bigint DEFAULT NULL::bigint, p_loai_cong_viec text DEFAULT NULL::text, p_don_vi_thuc_hien text DEFAULT NULL::text) RETURNS TABLE(id bigint, ke_hoach_id bigint, thiet_bi_id bigint, loai_cong_viec text, diem_hieu_chuan text, don_vi_thuc_hien text, thang_1 boolean, thang_2 boolean, thang_3 boolean, thang_4 boolean, thang_5 boolean, thang_6 boolean, thang_7 boolean, thang_8 boolean, thang_9 boolean, thang_10 boolean, thang_11 boolean, thang_12 boolean, ghi_chu text, created_at timestamp with time zone, updated_at timestamp with time zone, ma_thiet_bi text, ten_thiet_bi text, model text, khoa_phong_quan_ly text, vi_tri_lap_dat text, thang_1_hoan_thanh boolean, thang_2_hoan_thanh boolean, thang_3_hoan_thanh boolean, thang_4_hoan_thanh boolean, thang_5_hoan_thanh boolean, thang_6_hoan_thanh boolean, thang_7_hoan_thanh boolean, thang_8_hoan_thanh boolean, thang_9_hoan_thanh boolean, thang_10_hoan_thanh boolean, thang_11_hoan_thanh boolean, thang_12_hoan_thanh boolean, thiet_bi jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_allowed BIGINT[] := NULL;
BEGIN
  -- Use allowed_don_vi_for_session_safe() helper for proper multi-tenant filtering
  -- This handles global, regional_leader, and facility-level roles correctly
  IF v_role <> 'global' THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    
    -- Defensive NULL and empty array handling
    -- array_length returns NULL for empty arrays '{}' or NULL arrays
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL OR array_length(v_allowed, 1) = 0 THEN
      -- User has no accessible facilities, return empty result
      -- This is a safe fallback and should not normally occur for valid users
      RETURN;
    END IF;
  END IF;

  -- Return maintenance tasks with equipment info and proper tenant filtering
  RETURN QUERY
  SELECT 
    cv.id,
    cv.ke_hoach_id,
    cv.thiet_bi_id,
    cv.loai_cong_viec,
    cv.diem_hieu_chuan,
    cv.don_vi_thuc_hien,
    cv.thang_1,
    cv.thang_2,
    cv.thang_3,
    cv.thang_4,
    cv.thang_5,
    cv.thang_6,
    cv.thang_7,
    cv.thang_8,
    cv.thang_9,
    cv.thang_10,
    cv.thang_11,
    cv.thang_12,
    cv.ghi_chu,
    cv.created_at,
    cv.updated_at,
    -- Equipment fields (maintained for backward compatibility)
    tb.ma_thiet_bi,
    tb.ten_thiet_bi,
    tb.model,
    tb.khoa_phong_quan_ly,
    tb.vi_tri_lap_dat,
    -- Completion status
    cv.thang_1_hoan_thanh,
    cv.thang_2_hoan_thanh,
    cv.thang_3_hoan_thanh,
    cv.thang_4_hoan_thanh,
    cv.thang_5_hoan_thanh,
    cv.thang_6_hoan_thanh,
    cv.thang_7_hoan_thanh,
    cv.thang_8_hoan_thanh,
    cv.thang_9_hoan_thanh,
    cv.thang_10_hoan_thanh,
    cv.thang_11_hoan_thanh,
    cv.thang_12_hoan_thanh,
    -- Nested equipment object (provides thiet_bi.ma_thiet_bi, thiet_bi.ten_thiet_bi access)
    CASE 
      WHEN tb.id IS NOT NULL THEN
        jsonb_build_object(
          'id', tb.id,
          'ma_thiet_bi', tb.ma_thiet_bi,
          'ten_thiet_bi', tb.ten_thiet_bi,
          'model', COALESCE(tb.model, ''),
          'khoa_phong_quan_ly', COALESCE(tb.khoa_phong_quan_ly, ''),
          'vi_tri_lap_dat', COALESCE(tb.vi_tri_lap_dat, ''),
          'hang_san_xuat', COALESCE(tb.hang_san_xuat, ''),
          'noi_san_xuat', COALESCE(tb.noi_san_xuat, ''),
          'nam_san_xuat', tb.nam_san_xuat,
          'serial', COALESCE(tb.serial, '')
        )
      ELSE NULL
    END as thiet_bi
  FROM public.cong_viec_bao_tri cv
  LEFT JOIN public.thiet_bi tb ON cv.thiet_bi_id = tb.id
  WHERE (p_ke_hoach_id IS NULL OR cv.ke_hoach_id = p_ke_hoach_id)
    AND (p_thiet_bi_id IS NULL OR cv.thiet_bi_id = p_thiet_bi_id)
    AND (p_loai_cong_viec IS NULL OR cv.loai_cong_viec = p_loai_cong_viec)
    AND (p_don_vi_thuc_hien IS NULL OR cv.don_vi_thuc_hien = p_don_vi_thuc_hien)
    AND (
      v_role = 'global'
      OR cv.thiet_bi_id IS NULL
      OR tb.don_vi = ANY(v_allowed)  -- âœ… FIXED: Use array check instead of single value
    )
  ORDER BY cv.created_at DESC;
END;
$$;


ALTER FUNCTION public.maintenance_tasks_list_with_equipment(p_ke_hoach_id bigint, p_thiet_bi_id bigint, p_loai_cong_viec text, p_don_vi_thuc_hien text) OWNER TO postgres;

--
-- Name: FUNCTION maintenance_tasks_list_with_equipment(p_ke_hoach_id bigint, p_thiet_bi_id bigint, p_loai_cong_viec text, p_don_vi_thuc_hien text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.maintenance_tasks_list_with_equipment(p_ke_hoach_id bigint, p_thiet_bi_id bigint, p_loai_cong_viec text, p_don_vi_thuc_hien text) IS 'Lists maintenance tasks with equipment details. Supports multi-tenant filtering:
- global: All tasks from all tenants
- regional_leader: All tasks from facilities in assigned dia_ban (READ-ONLY)
- Other roles: Tasks from assigned don_vi only

Security: SECURITY DEFINER with owner=postgres, search_path pinned to public,pg_temp.
Access: authenticated role only (not anon).';


