--
-- Name: refresh_dia_ban_unit_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_dia_ban_unit_counts() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    UPDATE public.dia_ban db
    SET so_luong_don_vi_truc_thuoc = sub.count_don_vi
    FROM (
        SELECT dia_ban_id, COUNT(*) AS count_don_vi
        FROM public.don_vi
        WHERE dia_ban_id IS NOT NULL
        GROUP BY dia_ban_id
    ) sub
    WHERE db.id = sub.dia_ban_id;
END;
$$;


ALTER FUNCTION public.refresh_dia_ban_unit_counts() OWNER TO postgres;

--
-- Name: repair_request_active_for_equipment(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_active_for_equipment(p_thiet_bi_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id text := nullif(public._get_jwt_claim('user_id'), '');
  v_is_global boolean := false;
  v_allowed bigint[] := NULL;
  v_request jsonb := NULL;
  v_department_scope text := NULL;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  v_is_global := v_role IN ('global', 'admin');

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(public._get_jwt_claim('khoa_phong'));
    IF v_department_scope IS NULL THEN
      RETURN jsonb_build_object('active_count', 0, 'request', NULL);
    END IF;
  END IF;

  IF NOT v_is_global THEN
    v_allowed := public.allowed_don_vi_for_session();
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN jsonb_build_object('active_count', 0, 'request', NULL);
    END IF;
  END IF;

  WITH active AS (
    SELECT
      r.id,
      r.thiet_bi_id,
      r.ngay_yeu_cau,
      r.trang_thai,
      r.mo_ta_su_co,
      r.hang_muc_sua_chua,
      r.ngay_mong_muon_hoan_thanh,
      r.nguoi_yeu_cau,
      r.ngay_duyet,
      r.ngay_hoan_thanh,
      r.nguoi_duyet,
      r.nguoi_xac_nhan,
      r.don_vi_thuc_hien,
      r.ten_don_vi_thue,
      r.ket_qua_sua_chua,
      r.ly_do_khong_hoan_thanh,
      r.chi_phi_sua_chua,
      tb.ten_thiet_bi,
      tb.ma_thiet_bi,
      tb.model,
      tb.serial,
      tb.khoa_phong_quan_ly,
      tb.don_vi AS thiet_bi_don_vi,
      dv.name AS facility_name
    FROM public.yeu_cau_sua_chua r
    JOIN public.thiet_bi tb ON tb.id = r.thiet_bi_id
    LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
    WHERE r.thiet_bi_id = p_thiet_bi_id
      AND r.trang_thai IN ('Chờ xử lý', 'Đã duyệt')
      AND coalesce(tb.is_deleted, false) = false
      AND (v_is_global OR tb.don_vi = ANY(v_allowed))
      AND (
        v_role <> 'user'
        OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
      )
    ORDER BY coalesce(r.ngay_duyet, r.ngay_yeu_cau) DESC, r.id DESC
  ),
  counted AS (
    SELECT count(*)::int AS c
    FROM active
  )
  SELECT jsonb_build_object(
    'active_count', counted.c,
    'request',
    CASE
      WHEN counted.c = 0 THEN NULL
      ELSE (
        SELECT jsonb_build_object(
          'id', a.id,
          'thiet_bi_id', a.thiet_bi_id,
          'ngay_yeu_cau', a.ngay_yeu_cau,
          'trang_thai', a.trang_thai,
          'mo_ta_su_co', a.mo_ta_su_co,
          'hang_muc_sua_chua', a.hang_muc_sua_chua,
          'ngay_mong_muon_hoan_thanh', a.ngay_mong_muon_hoan_thanh,
          'nguoi_yeu_cau', a.nguoi_yeu_cau,
          'ngay_duyet', a.ngay_duyet,
          'ngay_hoan_thanh', a.ngay_hoan_thanh,
          'nguoi_duyet', a.nguoi_duyet,
          'nguoi_xac_nhan', a.nguoi_xac_nhan,
          'don_vi_thuc_hien', a.don_vi_thuc_hien,
          'ten_don_vi_thue', a.ten_don_vi_thue,
          'ket_qua_sua_chua', a.ket_qua_sua_chua,
          'ly_do_khong_hoan_thanh', a.ly_do_khong_hoan_thanh,
          'chi_phi_sua_chua', a.chi_phi_sua_chua,
          'thiet_bi', jsonb_build_object(
            'ten_thiet_bi', a.ten_thiet_bi,
            'ma_thiet_bi', a.ma_thiet_bi,
            'model', a.model,
            'serial', a.serial,
            'khoa_phong_quan_ly', a.khoa_phong_quan_ly,
            'facility_name', a.facility_name,
            'facility_id', a.thiet_bi_don_vi
          )
        )
        FROM active a
        ORDER BY coalesce(a.ngay_duyet, a.ngay_yeu_cau) DESC, a.id DESC
        LIMIT 1
      )
    END
  )
  INTO v_request
  FROM counted;

  RETURN v_request;
END;
$$;


ALTER FUNCTION public.repair_request_active_for_equipment(p_thiet_bi_id integer) OWNER TO postgres;

--
-- Name: repair_request_approve(integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_approve(p_id integer, p_nguoi_duyet text, p_don_vi_thuc_hien text, p_ten_don_vi_thue text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims jsonb;
  v_role text;
  v_is_global boolean := false;
  v_user_id bigint;
  v_don_vi bigint;
  v_locked record;
  v_req public.yeu_cau_sua_chua%ROWTYPE;
  v_tb_don_vi bigint;
BEGIN
  v_claims := coalesce(current_setting('request.jwt.claims', true), '{}'::text)::jsonb;
  v_role := lower(coalesce(nullif(v_claims->>'app_role', ''), nullif(v_claims->>'role', '')));
  v_is_global := v_role in ('global', 'admin');
  v_user_id := nullif(v_claims->>'user_id', '')::bigint;
  v_don_vi := nullif(v_claims->>'don_vi', '')::bigint;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  IF v_role = 'regional_leader' THEN
    RAISE EXCEPTION 'Permission denied' USING errcode = '42501';
  END IF;

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim for non-global role %', v_role USING errcode = '42501';
  END IF;

  SELECT ycss.*, tb.don_vi AS tb_don_vi
  INTO v_locked
  FROM public.yeu_cau_sua_chua ycss
  JOIN public.thiet_bi tb ON tb.id = ycss.thiet_bi_id
  WHERE ycss.id = p_id
    AND tb.is_deleted = false
  FOR UPDATE OF ycss, tb;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Yêu cầu không tồn tại';
  END IF;

  v_tb_don_vi := v_locked.tb_don_vi;

  IF NOT v_is_global AND v_tb_don_vi IS DISTINCT FROM v_don_vi THEN
    RAISE EXCEPTION 'Không có quyền trên thiết bị thuộc đơn vị khác' USING errcode = '42501';
  END IF;

  IF v_locked.trang_thai IS DISTINCT FROM 'Chờ xử lý' THEN
    RAISE EXCEPTION 'Chỉ có thể duyệt yêu cầu ở trạng thái Chờ xử lý' USING errcode = '22023';
  END IF;

  UPDATE public.yeu_cau_sua_chua
  SET trang_thai = 'Đã duyệt',
      ngay_duyet = now(),
      nguoi_duyet = p_nguoi_duyet,
      don_vi_thuc_hien = p_don_vi_thuc_hien,
      ten_don_vi_thue = CASE
        WHEN p_don_vi_thuc_hien = 'thue_ngoai' THEN p_ten_don_vi_thue
        ELSE NULL
      END
  WHERE id = p_id
  RETURNING * INTO v_req;

  PERFORM public.repair_request_sync_equipment_status(v_req.thiet_bi_id);

  INSERT INTO public.lich_su_thiet_bi(thiet_bi_id, loai_su_kien, mo_ta, chi_tiet, yeu_cau_id)
  VALUES (
    v_req.thiet_bi_id,
    'Sửa chữa',
    'Duyệt yêu cầu sửa chữa',
    jsonb_build_object(
      'nguoi_duyet', v_req.nguoi_duyet,
      'ngay_duyet', v_req.ngay_duyet,
      'don_vi_thuc_hien', v_req.don_vi_thuc_hien,
      'ten_don_vi_thue', v_req.ten_don_vi_thue
    ),
    p_id
  );

  IF NOT public.audit_log(
    'repair_request_approve',
    'repair_request',
    p_id,
    NULL,
    jsonb_build_object(
      'trang_thai', v_req.trang_thai,
      'nguoi_duyet', v_req.nguoi_duyet,
      'ngay_duyet', v_req.ngay_duyet,
      'don_vi_thuc_hien', v_req.don_vi_thuc_hien,
      'ten_don_vi_thue', v_req.ten_don_vi_thue
    )
  ) THEN
    RAISE EXCEPTION 'audit_log failed for repair_request %', p_id;
  END IF;
END;
$$;


ALTER FUNCTION public.repair_request_approve(p_id integer, p_nguoi_duyet text, p_don_vi_thuc_hien text, p_ten_don_vi_thue text) OWNER TO postgres;

--
-- Name: repair_request_change_history_list(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_change_history_list(p_repair_request_id integer) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jwt_claims JSONB := COALESCE(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_role TEXT;
  v_user_id TEXT;
  v_is_global BOOLEAN := FALSE;
  v_allowed BIGINT[] := NULL;
  v_request_don_vi BIGINT;
BEGIN
  IF p_repair_request_id IS NULL THEN
    RETURN;
  END IF;

  v_role := lower(COALESCE(
    NULLIF(v_jwt_claims->>'app_role', ''),
    NULLIF(v_jwt_claims->>'role', ''),
    ''
  ));
  v_user_id := NULLIF(COALESCE(v_jwt_claims->>'user_id', v_jwt_claims->>'sub'), '');

  IF v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;
  v_is_global := (v_role = 'global');

  SELECT tb.don_vi
  INTO v_request_don_vi
  FROM public.yeu_cau_sua_chua ycss
  JOIN public.thiet_bi tb ON tb.id = ycss.thiet_bi_id
  WHERE ycss.id = p_repair_request_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Yêu cầu sửa chữa không tồn tại hoặc bạn không có quyền truy cập'
      USING ERRCODE = '42501';
  END IF;

  IF NOT v_is_global THEN
    v_allowed := public.allowed_don_vi_for_session();

    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RAISE EXCEPTION 'Yêu cầu sửa chữa không tồn tại hoặc bạn không có quyền truy cập'
        USING ERRCODE = '42501';
    END IF;

    IF v_request_don_vi IS NULL OR NOT (v_request_don_vi = ANY(v_allowed)) THEN
      RAISE EXCEPTION 'Yêu cầu sửa chữa không tồn tại hoặc bạn không có quyền truy cập'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH request_context AS (
    SELECT
      ycss.nguoi_yeu_cau,
      ycss.nguoi_duyet,
      ycss.nguoi_xac_nhan
    FROM public.yeu_cau_sua_chua ycss
    WHERE ycss.id = p_repair_request_id
  ),
  domain_history AS (
    SELECT
      ls.id,
      ls.ngay_thuc_hien AS created_at,
      CASE ls.mo_ta
        WHEN 'Tạo yêu cầu sửa chữa' THEN 'repair_request_create'
        WHEN 'Cập nhật nội dung yêu cầu sửa chữa' THEN 'repair_request_update'
        WHEN 'Duyệt yêu cầu sửa chữa' THEN 'repair_request_approve'
        WHEN 'Yêu cầu sửa chữa cập nhật trạng thái' THEN 'repair_request_complete'
        WHEN 'Xóa yêu cầu sửa chữa' THEN 'repair_request_delete'
        ELSE NULL
      END AS action_type,
      CASE ls.mo_ta
        WHEN 'Tạo yêu cầu sửa chữa' THEN
          COALESCE(
            NULLIF(BTRIM(req.nguoi_yeu_cau), ''),
            NULLIF(BTRIM(ls.chi_tiet->>'nguoi_yeu_cau'), '')
          )
        WHEN 'Duyệt yêu cầu sửa chữa' THEN
          COALESCE(
            NULLIF(BTRIM(ls.chi_tiet->>'nguoi_duyet'), ''),
            NULLIF(BTRIM(req.nguoi_duyet), '')
          )
        WHEN 'Yêu cầu sửa chữa cập nhật trạng thái' THEN
          COALESCE(
            NULLIF(BTRIM(ls.chi_tiet->>'nguoi_xac_nhan'), ''),
            NULLIF(BTRIM(req.nguoi_xac_nhan), '')
          )
        ELSE NULL
      END AS admin_full_name,
      CASE ls.mo_ta
        WHEN 'Tạo yêu cầu sửa chữa' THEN
          jsonb_strip_nulls(
            (COALESCE(ls.chi_tiet, '{}'::jsonb) - 'hang_muc')
            || jsonb_build_object(
              'hang_muc_sua_chua', NULLIF(ls.chi_tiet->>'hang_muc', ''),
              'nguoi_yeu_cau', COALESCE(
                NULLIF(BTRIM(req.nguoi_yeu_cau), ''),
                NULLIF(BTRIM(ls.chi_tiet->>'nguoi_yeu_cau'), '')
              ),
              'trang_thai', 'Chờ xử lý'
            )
          )
        WHEN 'Cập nhật nội dung yêu cầu sửa chữa' THEN
          jsonb_strip_nulls(
            (COALESCE(ls.chi_tiet, '{}'::jsonb) - 'hang_muc')
            || jsonb_build_object(
              'hang_muc_sua_chua', NULLIF(ls.chi_tiet->>'hang_muc', '')
            )
          )
        WHEN 'Duyệt yêu cầu sửa chữa' THEN
          jsonb_strip_nulls(
            COALESCE(ls.chi_tiet, '{}'::jsonb)
            || jsonb_build_object(
              'nguoi_duyet', COALESCE(
                NULLIF(BTRIM(ls.chi_tiet->>'nguoi_duyet'), ''),
                NULLIF(BTRIM(req.nguoi_duyet), '')
              ),
              'trang_thai', 'Đã duyệt'
            )
          )
        WHEN 'Yêu cầu sửa chữa cập nhật trạng thái' THEN
          CASE
            WHEN COALESCE(ls.chi_tiet->>'trang_thai', '') = 'Không HT' THEN
              jsonb_strip_nulls(
                (COALESCE(ls.chi_tiet, '{}'::jsonb) - 'ket_qua')
                || jsonb_build_object(
                  'ly_do_khong_hoan_thanh', NULLIF(ls.chi_tiet->>'ket_qua', '')
                )
              )
            ELSE
              jsonb_strip_nulls(
                (COALESCE(ls.chi_tiet, '{}'::jsonb) - 'ket_qua')
                || jsonb_build_object(
                  'ket_qua_sua_chua', NULLIF(ls.chi_tiet->>'ket_qua', '')
                )
              )
          END
        ELSE
          COALESCE(ls.chi_tiet, '{}'::jsonb)
      END AS action_details
    FROM public.lich_su_thiet_bi ls
    CROSS JOIN request_context req
    WHERE ls.yeu_cau_id = p_repair_request_id
      AND ls.loai_su_kien = 'Sửa chữa'
      AND ls.mo_ta IN (
        'Tạo yêu cầu sửa chữa',
        'Cập nhật nội dung yêu cầu sửa chữa',
        'Duyệt yêu cầu sửa chữa',
        'Yêu cầu sửa chữa cập nhật trạng thái',
        'Xóa yêu cầu sửa chữa'
      )
  )
  SELECT jsonb_build_object(
    'id', dh.id,
    'action_type', dh.action_type,
    'admin_username', 'system',
    'admin_full_name', dh.admin_full_name,
    'action_details', dh.action_details,
    'created_at', dh.created_at
  )
  FROM domain_history dh
  WHERE dh.action_type IS NOT NULL
  ORDER BY dh.created_at DESC, dh.id DESC;
END;
$$;


ALTER FUNCTION public.repair_request_change_history_list(p_repair_request_id integer) OWNER TO postgres;

--
-- Name: FUNCTION repair_request_change_history_list(p_repair_request_id integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.repair_request_change_history_list(p_repair_request_id integer) IS 'Lists repair-request domain history from lich_su_thiet_bi with the same tenant access semantics as repair_request_get.';


--
-- Name: repair_request_complete(integer, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_complete(p_id integer, p_completion text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_chi_phi_sua_chua numeric DEFAULT NULL::numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_claims jsonb;
  v_role text;
  v_is_global boolean := false;
  v_user_id bigint;
  v_don_vi bigint;
  v_thiet_bi_id bigint;
  v_tb_don_vi bigint;
  v_locked_status text;
  v_locked_completed_at timestamptz;
  v_status text;
  v_result text;
  v_reason text;
  v_cost numeric(14,2);
  v_normalized_completion text;
  v_normalized_reason text;
BEGIN
  v_claims := coalesce(current_setting('request.jwt.claims', true), '{}'::text)::jsonb;
  v_role := lower(coalesce(nullif(v_claims->>'app_role', ''), nullif(v_claims->>'role', '')));
  v_is_global := v_role in ('global', 'admin');
  v_user_id := nullif(v_claims->>'user_id', '')::bigint;
  v_don_vi := nullif(v_claims->>'don_vi', '')::bigint;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  IF v_role = 'regional_leader' THEN
    RAISE EXCEPTION 'Permission denied' USING errcode = '42501';
  END IF;

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim for non-global role %', v_role USING errcode = '42501';
  END IF;

  SELECT ycss.thiet_bi_id, ycss.trang_thai, ycss.ngay_hoan_thanh, tb.don_vi
  INTO v_thiet_bi_id, v_locked_status, v_locked_completed_at, v_tb_don_vi
  FROM public.yeu_cau_sua_chua ycss
  JOIN public.thiet_bi tb ON tb.id = ycss.thiet_bi_id
  WHERE ycss.id = p_id
    AND tb.is_deleted = false
  FOR UPDATE OF ycss, tb;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Yêu cầu không tồn tại';
  END IF;

  IF NOT v_is_global AND v_tb_don_vi IS DISTINCT FROM v_don_vi THEN
    RAISE EXCEPTION 'Không có quyền trên thiết bị thuộc đơn vị khác' USING errcode = '42501';
  END IF;

  IF v_locked_completed_at IS NOT NULL OR v_locked_status IN ('Hoàn thành', 'Không HT') THEN
    RAISE EXCEPTION 'Không thể hoàn thành lại yêu cầu đã hoàn thành' USING errcode = '22023';
  END IF;

  IF p_chi_phi_sua_chua IS NOT NULL AND p_chi_phi_sua_chua < 0 THEN
    RAISE EXCEPTION 'Chi phí sửa chữa không được âm' USING errcode = '22023';
  END IF;

  v_normalized_completion := nullif(
    regexp_replace(coalesce(p_completion, ''), '^[[:space:]]+|[[:space:]]+$', '', 'g'),
    ''
  );
  v_normalized_reason := nullif(
    regexp_replace(coalesce(p_reason, ''), '^[[:space:]]+|[[:space:]]+$', '', 'g'),
    ''
  );

  IF v_normalized_completion IS NULL
     AND v_normalized_reason IS NULL THEN
    RAISE EXCEPTION 'Phải nhập kết quả sửa chữa hoặc lý do không hoàn thành'
      USING errcode = '22023';
  END IF;

  IF v_normalized_completion IS NOT NULL THEN
    v_status := 'Hoàn thành';
    v_result := v_normalized_completion;
    v_reason := NULL;
    v_cost := p_chi_phi_sua_chua;
  ELSE
    v_status := 'Không HT';
    v_result := NULL;
    v_reason := v_normalized_reason;
    v_cost := NULL;
  END IF;

  UPDATE public.yeu_cau_sua_chua
  SET trang_thai = v_status,
      ngay_hoan_thanh = now(),
      ket_qua_sua_chua = v_result,
      ly_do_khong_hoan_thanh = v_reason,
      chi_phi_sua_chua = v_cost
  WHERE id = p_id;

  PERFORM public.repair_request_sync_equipment_status(v_thiet_bi_id);

  INSERT INTO public.lich_su_thiet_bi(thiet_bi_id, loai_su_kien, mo_ta, chi_tiet, yeu_cau_id)
  VALUES (
    v_thiet_bi_id,
    'Sửa chữa',
    'Yêu cầu sửa chữa cập nhật trạng thái',
    jsonb_build_object(
      'ket_qua', coalesce(v_result, v_reason),
      'trang_thai', v_status,
      'chi_phi_sua_chua', v_cost
    ),
    p_id
  );

  IF NOT public.audit_log(
    'repair_request_complete',
    'repair_request',
    p_id,
    NULL,
    jsonb_build_object(
      'trang_thai', v_status,
      'ket_qua_sua_chua', v_result,
      'ly_do_khong_hoan_thanh', v_reason,
      'chi_phi_sua_chua', v_cost
    )
  ) THEN
    RAISE EXCEPTION 'audit_log failed for repair_request %', p_id;
  END IF;
END;
$_$;


ALTER FUNCTION public.repair_request_complete(p_id integer, p_completion text, p_reason text, p_chi_phi_sua_chua numeric) OWNER TO postgres;

--
-- Name: repair_request_create(integer, text, text, date, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_create(p_thiet_bi_id integer, p_mo_ta_su_co text, p_hang_muc_sua_chua text, p_ngay_mong_muon_hoan_thanh date, p_nguoi_yeu_cau text, p_don_vi_thuc_hien text, p_ten_don_vi_thue text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id integer;
  v_claims jsonb;
  v_role text;
  v_is_global boolean := false;
  v_user_id bigint;
  v_don_vi bigint;
  v_department_scope text;
  v_tb record;
  v_snapshot_status text;
BEGIN
  v_claims := coalesce(current_setting('request.jwt.claims', true), '{}'::text)::jsonb;
  v_role := lower(coalesce(nullif(v_claims->>'app_role', ''), nullif(v_claims->>'role', '')));
  v_is_global := v_role in ('global', 'admin');
  v_user_id := nullif(v_claims->>'user_id', '')::bigint;
  v_don_vi := nullif(v_claims->>'don_vi', '')::bigint;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  IF v_role = 'regional_leader' THEN
    RAISE EXCEPTION 'Permission denied' USING errcode = '42501';
  END IF;

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim for non-global role %', v_role USING errcode = '42501';
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_claims->>'khoa_phong');
  END IF;

  SELECT
    tb.id,
    tb.don_vi,
    tb.khoa_phong_quan_ly,
    tb.tinh_trang_hien_tai,
    tb.ma_thiet_bi,
    tb.ten_thiet_bi
  INTO v_tb
  FROM public.thiet_bi tb
  WHERE tb.id = p_thiet_bi_id
    AND tb.is_deleted = false
  FOR UPDATE OF tb;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Thiết bị không tồn tại' USING errcode = 'P0002';
  END IF;

  IF NOT v_is_global AND v_tb.don_vi IS DISTINCT FROM v_don_vi THEN
    RAISE EXCEPTION 'Không có quyền trên thiết bị thuộc đơn vị khác' USING errcode = '42501';
  END IF;

  IF v_role = 'user'
     AND (
       v_department_scope IS NULL
       OR public._normalize_department_scope(v_tb.khoa_phong_quan_ly) IS DISTINCT FROM v_department_scope
     ) THEN
    RAISE EXCEPTION 'Không có quyền trên thiết bị thuộc khoa/phòng khác' USING errcode = '42501';
  END IF;

  v_snapshot_status := v_tb.tinh_trang_hien_tai;

  IF v_tb.tinh_trang_hien_tai = 'Chờ sửa chữa' THEN
    SELECT ycss.tinh_trang_thiet_bi_truoc_yeu_cau
    INTO v_snapshot_status
    FROM public.yeu_cau_sua_chua ycss
    WHERE ycss.thiet_bi_id = p_thiet_bi_id
      AND ycss.trang_thai IN ('Chờ xử lý', 'Đã duyệt', 'Không HT')
      AND ycss.tinh_trang_thiet_bi_truoc_yeu_cau IS NOT NULL
      AND ycss.tinh_trang_thiet_bi_truoc_yeu_cau <> 'Chờ sửa chữa'
    ORDER BY ycss.id DESC
    LIMIT 1;

    v_snapshot_status := coalesce(
      v_snapshot_status,
      nullif(v_tb.tinh_trang_hien_tai, 'Chờ sửa chữa'),
      'Hoạt động'
    );
  END IF;

  INSERT INTO public.yeu_cau_sua_chua(
    thiet_bi_id,
    mo_ta_su_co,
    hang_muc_sua_chua,
    ngay_mong_muon_hoan_thanh,
    nguoi_yeu_cau,
    trang_thai,
    don_vi_thuc_hien,
    ten_don_vi_thue,
    tinh_trang_thiet_bi_truoc_yeu_cau
  )
  VALUES (
    p_thiet_bi_id,
    p_mo_ta_su_co,
    p_hang_muc_sua_chua,
    p_ngay_mong_muon_hoan_thanh,
    p_nguoi_yeu_cau,
    'Chờ xử lý',
    p_don_vi_thuc_hien,
    p_ten_don_vi_thue,
    v_snapshot_status
  )
  RETURNING id INTO v_id;

  PERFORM public.repair_request_sync_equipment_status(p_thiet_bi_id::bigint);

  INSERT INTO public.lich_su_thiet_bi(thiet_bi_id, loai_su_kien, mo_ta, chi_tiet, yeu_cau_id)
  VALUES (
    p_thiet_bi_id,
    'Sửa chữa',
    'Tạo yêu cầu sửa chữa',
    jsonb_build_object(
      'mo_ta_su_co', p_mo_ta_su_co,
      'hang_muc', p_hang_muc_sua_chua,
      'ngay_mong_muon_hoan_thanh', p_ngay_mong_muon_hoan_thanh,
      'don_vi_thuc_hien', p_don_vi_thuc_hien,
      'ten_don_vi_thue', p_ten_don_vi_thue
    ),
    v_id
  );

  IF NOT public.audit_log(
    'repair_request_create',
    'repair_request',
    v_id,
    NULL,
    jsonb_build_object(
      'thiet_bi_id', p_thiet_bi_id,
      'mo_ta_su_co', p_mo_ta_su_co
    )
  ) THEN
    RAISE EXCEPTION 'audit_log failed for repair_request %', v_id;
  END IF;

  INSERT INTO public.zbs_notification_outbox (
    event_type,
    source_type,
    source_id,
    don_vi_id,
    recipient_config_id,
    recipient_phone,
    template_data,
    tracking_id
  )
  SELECT
    'repair_request_created',
    'repair_request',
    v_id,
    v_tb.don_vi,
    cfg.id,
    cfg.recipient_phone,
    jsonb_build_object(
      'repair_request_id', v_id,
      'equipment_id', v_tb.id,
      'equipment_code', v_tb.ma_thiet_bi,
      'equipment_name', v_tb.ten_thiet_bi,
      'department', v_tb.khoa_phong_quan_ly,
      'issue_description', p_mo_ta_su_co,
      'repair_scope', p_hang_muc_sua_chua,
      'requested_completion_date', p_ngay_mong_muon_hoan_thanh,
      'requester', p_nguoi_yeu_cau,
      'don_vi_id', v_tb.don_vi,
      'don_vi_thuc_hien', p_don_vi_thuc_hien,
      'ten_don_vi_thue', p_ten_don_vi_thue
    ),
    format('repair_request:%s:%s', v_id, cfg.id)
  FROM public.zbs_recipient_configs cfg
  WHERE cfg.don_vi_id = v_tb.don_vi
    AND cfg.event_type = 'repair_request_created'
    AND cfg.active = true
  ON CONFLICT (event_type, source_type, source_id, recipient_config_id) DO NOTHING;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.repair_request_create(p_thiet_bi_id integer, p_mo_ta_su_co text, p_hang_muc_sua_chua text, p_ngay_mong_muon_hoan_thanh date, p_nguoi_yeu_cau text, p_don_vi_thuc_hien text, p_ten_don_vi_thue text) OWNER TO postgres;

--
-- Name: repair_request_delete(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_delete(p_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims jsonb;
  v_role text;
  v_is_global boolean := false;
  v_user_id bigint;
  v_don_vi bigint;
  v_locked record;
  v_fallback_status text;
BEGIN
  v_claims := coalesce(current_setting('request.jwt.claims', true), '{}'::text)::jsonb;
  v_role := lower(coalesce(nullif(v_claims->>'app_role', ''), nullif(v_claims->>'role', '')));
  v_is_global := v_role in ('global', 'admin');
  v_user_id := nullif(v_claims->>'user_id', '')::bigint;
  v_don_vi := nullif(v_claims->>'don_vi', '')::bigint;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  IF v_role = 'regional_leader' THEN
    RAISE EXCEPTION 'Permission denied' USING errcode = '42501';
  END IF;

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim for non-global role %', v_role USING errcode = '42501';
  END IF;

  -- Intentionally allow delete cleanup even after equipment soft-delete.
  -- Other repair RPCs block deleted equipment because they mutate active workflow state.
  SELECT ycss.*, tb.don_vi AS tb_don_vi, tb.tinh_trang_hien_tai AS tb_tinh_trang_hien_tai
  INTO v_locked
  FROM public.yeu_cau_sua_chua ycss
  JOIN public.thiet_bi tb ON tb.id = ycss.thiet_bi_id
  WHERE ycss.id = p_id
  FOR UPDATE OF ycss, tb;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF NOT v_is_global AND v_locked.tb_don_vi IS DISTINCT FROM v_don_vi THEN
    RAISE EXCEPTION 'Không có quyền trên thiết bị thuộc đơn vị khác' USING errcode = '42501';
  END IF;

  -- Never feed a repair-driven intermediate status back into the sync helper
  -- when the deleted row is the last surviving repair request.
  v_fallback_status := coalesce(
    nullif(v_locked.tinh_trang_thiet_bi_truoc_yeu_cau, 'Chờ sửa chữa'),
    nullif(v_locked.tb_tinh_trang_hien_tai, 'Chờ sửa chữa'),
    'Hoạt động'
  );

  IF NOT public.audit_log(
    'repair_request_delete',
    'repair_request',
    p_id,
    NULL,
    jsonb_build_object(
      'thiet_bi_id', v_locked.thiet_bi_id,
      'trang_thai', v_locked.trang_thai
    )
  ) THEN
    RAISE EXCEPTION 'audit_log failed for repair_request %', p_id;
  END IF;

  DELETE FROM public.yeu_cau_sua_chua
  WHERE id = p_id;

  PERFORM public.repair_request_sync_equipment_status(v_locked.thiet_bi_id, v_fallback_status);

  INSERT INTO public.lich_su_thiet_bi(thiet_bi_id, loai_su_kien, mo_ta, chi_tiet)
  VALUES (
    v_locked.thiet_bi_id,
    'Sửa chữa',
    'Xóa yêu cầu sửa chữa',
    jsonb_build_object('yeu_cau_id', p_id)
  );
END;
$$;


ALTER FUNCTION public.repair_request_delete(p_id integer) OWNER TO postgres;

--
-- Name: repair_request_get(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_get(p_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id text := nullif(public._get_jwt_claim('user_id'), '');
  v_is_global boolean := false;
  v_allowed bigint[] := NULL;
  v_department_scope text := NULL;
  v_result jsonb := NULL;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  v_is_global := v_role IN ('global', 'admin');

  IF NOT v_is_global THEN
    v_allowed := public.allowed_don_vi_for_session();
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RAISE EXCEPTION 'Yêu cầu sửa chữa không tồn tại hoặc bạn không có quyền truy cập' USING errcode = '42501';
    END IF;
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(public._get_jwt_claim('khoa_phong'));
  END IF;

  SELECT to_jsonb(r.*)
  INTO v_result
  FROM public.yeu_cau_sua_chua r
  JOIN public.thiet_bi tb ON tb.id = r.thiet_bi_id
  WHERE r.id = p_id
    AND (
      v_is_global
      OR tb.don_vi = ANY(v_allowed)
    )
    AND (
      v_role <> 'user'
      OR (
        v_department_scope IS NOT NULL
        AND public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
      )
    );

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Yêu cầu sửa chữa không tồn tại hoặc bạn không có quyền truy cập' USING errcode = '42501';
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.repair_request_get(p_id integer) OWNER TO postgres;

--
-- Name: repair_request_list(text, text, integer, integer, bigint, date, date, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_list(p_q text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_don_vi bigint DEFAULT NULL::bigint, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_statuses text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id text := nullif(public._get_jwt_claim('user_id'), '');
  v_is_global boolean := false;
  v_effective_donvi bigint := NULL;
  v_allowed bigint[] := NULL;
  v_limit integer := greatest(coalesce(p_page_size, 50), 1);
  v_offset integer := greatest((coalesce(p_page, 1) - 1) * v_limit, 0);
  v_page integer := (v_offset / v_limit)::integer + 1;
  v_total bigint := 0;
  v_data jsonb := '[]'::jsonb;
  v_statuses text[] := NULL;
  v_sanitized_q text := NULL;
  v_department_scope text := NULL;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  v_is_global := v_role IN ('global', 'admin');
  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(public._get_jwt_claim('khoa_phong'));
    IF v_department_scope IS NULL THEN
      RETURN jsonb_build_object('data', '[]'::jsonb, 'total', 0, 'page', v_page, 'pageSize', v_limit);
    END IF;
  END IF;

  IF p_statuses IS NOT NULL AND array_length(p_statuses, 1) IS NOT NULL THEN
    v_statuses := p_statuses;
  ELSIF p_status IS NOT NULL AND p_status <> '' THEN
    v_statuses := ARRAY[p_status];
  END IF;

  IF v_is_global THEN
    v_effective_donvi := p_don_vi;
  ELSE
    v_allowed := public.allowed_don_vi_for_session();
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN jsonb_build_object('data', '[]'::jsonb, 'total', 0, 'page', v_page, 'pageSize', v_limit);
    END IF;
    IF p_don_vi IS NOT NULL THEN
      IF p_don_vi = ANY(v_allowed) THEN
        v_effective_donvi := p_don_vi;
      ELSE
        RETURN jsonb_build_object('data', '[]'::jsonb, 'total', 0, 'page', v_page, 'pageSize', v_limit);
      END IF;
    END IF;
  END IF;

  SELECT count(*) INTO v_total
  FROM public.yeu_cau_sua_chua r
  LEFT JOIN public.thiet_bi tb ON tb.id = r.thiet_bi_id
  WHERE (
    (v_is_global AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)) OR
    (NOT v_is_global AND ((v_effective_donvi IS NOT NULL AND tb.don_vi = v_effective_donvi) OR (v_effective_donvi IS NULL AND tb.don_vi = ANY(v_allowed))))
  )
  AND (
    v_role <> 'user'
    OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
  )
  AND (v_statuses IS NULL OR r.trang_thai = ANY(v_statuses))
  AND (
    v_sanitized_q IS NULL OR
    r.mo_ta_su_co ILIKE '%' || v_sanitized_q || '%' OR
    r.hang_muc_sua_chua ILIKE '%' || v_sanitized_q || '%' OR
    tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%' OR
    tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
  )
  AND (p_date_from IS NULL OR r.ngay_yeu_cau >= (p_date_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
  AND (p_date_to IS NULL OR r.ngay_yeu_cau < ((p_date_to + interval '1 day')::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'));

  SELECT coalesce(jsonb_agg(row_data ORDER BY ngay_yeu_cau DESC), '[]'::jsonb) INTO v_data
  FROM (
    SELECT
      jsonb_build_object(
        'id', r.id,
        'thiet_bi_id', r.thiet_bi_id,
        'ngay_yeu_cau', r.ngay_yeu_cau,
        'trang_thai', r.trang_thai,
        'mo_ta_su_co', r.mo_ta_su_co,
        'hang_muc_sua_chua', r.hang_muc_sua_chua,
        'ngay_mong_muon_hoan_thanh', r.ngay_mong_muon_hoan_thanh,
        'nguoi_yeu_cau', r.nguoi_yeu_cau,
        'ngay_duyet', r.ngay_duyet,
        'ngay_hoan_thanh', r.ngay_hoan_thanh,
        'nguoi_duyet', r.nguoi_duyet,
        'nguoi_xac_nhan', r.nguoi_xac_nhan,
        'don_vi_thuc_hien', r.don_vi_thuc_hien,
        'ten_don_vi_thue', r.ten_don_vi_thue,
        'ket_qua_sua_chua', r.ket_qua_sua_chua,
        'ly_do_khong_hoan_thanh', r.ly_do_khong_hoan_thanh,
        'chi_phi_sua_chua', r.chi_phi_sua_chua,
        'equipment_is_deleted', tb.is_deleted,
        'thiet_bi', jsonb_build_object(
          'ten_thiet_bi', tb.ten_thiet_bi,
          'ma_thiet_bi', tb.ma_thiet_bi,
          'model', tb.model,
          'hang_san_xuat', tb.hang_san_xuat,
          'serial', tb.serial,
          'khoa_phong_quan_ly', tb.khoa_phong_quan_ly,
          'facility_name', dv.name,
          'facility_id', tb.don_vi,
          'is_deleted', tb.is_deleted
        )
      ) AS row_data,
      r.ngay_yeu_cau
    FROM public.yeu_cau_sua_chua r
    LEFT JOIN public.thiet_bi tb ON tb.id = r.thiet_bi_id
    LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
    WHERE (
      (v_is_global AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)) OR
      (NOT v_is_global AND ((v_effective_donvi IS NOT NULL AND tb.don_vi = v_effective_donvi) OR (v_effective_donvi IS NULL AND tb.don_vi = ANY(v_allowed))))
    )
    AND (
      v_role <> 'user'
      OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
    )
    AND (v_statuses IS NULL OR r.trang_thai = ANY(v_statuses))
    AND (
      v_sanitized_q IS NULL OR
      r.mo_ta_su_co ILIKE '%' || v_sanitized_q || '%' OR
      r.hang_muc_sua_chua ILIKE '%' || v_sanitized_q || '%' OR
      tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%' OR
      tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
    )
    AND (p_date_from IS NULL OR r.ngay_yeu_cau >= (p_date_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
    AND (p_date_to IS NULL OR r.ngay_yeu_cau < ((p_date_to + interval '1 day')::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
    ORDER BY r.ngay_yeu_cau DESC
    OFFSET v_offset
    LIMIT v_limit
  ) subq;

  RETURN jsonb_build_object('data', v_data, 'total', v_total, 'page', v_page, 'pageSize', v_limit);
END;
$$;


ALTER FUNCTION public.repair_request_list(p_q text, p_status text, p_page integer, p_page_size integer, p_don_vi bigint, p_date_from date, p_date_to date, p_statuses text[]) OWNER TO postgres;

--
-- Name: FUNCTION repair_request_list(p_q text, p_status text, p_page integer, p_page_size integer, p_don_vi bigint, p_date_from date, p_date_to date, p_statuses text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.repair_request_list(p_q text, p_status text, p_page integer, p_page_size integer, p_don_vi bigint, p_date_from date, p_date_to date, p_statuses text[]) IS 'Lists repair requests with facility scoping, pagination, VN-local date range filtering, optional search, and multi-status filtering (p_statuses).';


--
-- Name: repair_request_status_counts(text, bigint, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_status_counts(p_q text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id text := nullif(public._get_jwt_claim('user_id'), '');
  v_is_global boolean := false;
  v_effective_donvi bigint := NULL;
  v_allowed bigint[] := NULL;
  v_sanitized_q text := NULL;
  v_department_scope text := NULL;
  v_today date := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  v_is_global := v_role IN ('global', 'admin');
  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(public._get_jwt_claim('khoa_phong'));
    IF v_department_scope IS NULL THEN
      RETURN jsonb_build_object(
        'counts', jsonb_build_object(
          'Chờ xử lý', 0,
          'Đã duyệt', 0,
          'Hoàn thành', 0,
          'Không HT', 0
        ),
        'overdue_summary', jsonb_build_object(
          'total', 0,
          'overdue', 0,
          'due_today', 0,
          'due_soon', 0,
          'items', '[]'::jsonb
        )
      );
    END IF;
  END IF;

  IF v_is_global THEN
    v_effective_donvi := p_don_vi;
  ELSE
    v_allowed := public.allowed_don_vi_for_session();
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN jsonb_build_object(
        'counts', jsonb_build_object(
          'Chờ xử lý', 0,
          'Đã duyệt', 0,
          'Hoàn thành', 0,
          'Không HT', 0
        ),
        'overdue_summary', jsonb_build_object(
          'total', 0,
          'overdue', 0,
          'due_today', 0,
          'due_soon', 0,
          'items', '[]'::jsonb
        )
      );
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF p_don_vi = ANY(v_allowed) THEN
        v_effective_donvi := p_don_vi;
      ELSE
        RETURN jsonb_build_object(
          'counts', jsonb_build_object(
            'Chờ xử lý', 0,
            'Đã duyệt', 0,
            'Hoàn thành', 0,
            'Không HT', 0
          ),
          'overdue_summary', jsonb_build_object(
            'total', 0,
            'overdue', 0,
            'due_today', 0,
            'due_soon', 0,
            'items', '[]'::jsonb
          )
        );
      END IF;
    END IF;
  END IF;

  RETURN (
    WITH filtered AS (
      SELECT
        r.id,
        r.thiet_bi_id,
        r.ngay_yeu_cau,
        r.trang_thai,
        r.mo_ta_su_co,
        r.hang_muc_sua_chua,
        r.ngay_mong_muon_hoan_thanh,
        r.nguoi_yeu_cau,
        r.ngay_duyet,
        r.ngay_hoan_thanh,
        r.nguoi_duyet,
        r.nguoi_xac_nhan,
        r.don_vi_thuc_hien,
        r.ten_don_vi_thue,
        r.ket_qua_sua_chua,
        r.ly_do_khong_hoan_thanh,
        r.chi_phi_sua_chua,
        tb.ten_thiet_bi,
        tb.ma_thiet_bi,
        tb.model,
        tb.serial,
        tb.khoa_phong_quan_ly,
        tb.don_vi AS facility_id,
        dv.name AS facility_name
      FROM public.yeu_cau_sua_chua r
      LEFT JOIN public.thiet_bi tb ON tb.id = r.thiet_bi_id
      LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
      WHERE (
        (v_is_global AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi))
        OR (
          NOT v_is_global
          AND (
            (v_effective_donvi IS NOT NULL AND tb.don_vi = v_effective_donvi)
            OR (v_effective_donvi IS NULL AND tb.don_vi = ANY(v_allowed))
          )
        )
      )
      AND (
        v_role <> 'user'
        OR public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope
      )
      AND (
        v_sanitized_q IS NULL
        OR r.mo_ta_su_co ILIKE '%' || v_sanitized_q || '%'
        OR r.hang_muc_sua_chua ILIKE '%' || v_sanitized_q || '%'
        OR tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%'
        OR tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
      )
      AND (p_date_from IS NULL OR r.ngay_yeu_cau >= (p_date_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
      AND (p_date_to IS NULL OR r.ngay_yeu_cau < ((p_date_to + interval '1 day')::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
    ),
    due_items AS (
      SELECT
        *,
        (ngay_mong_muon_hoan_thanh - v_today) AS days_difference
      FROM filtered
      WHERE trang_thai IN ('Chờ xử lý', 'Đã duyệt')
        AND ngay_mong_muon_hoan_thanh IS NOT NULL
        AND ngay_mong_muon_hoan_thanh <= v_today + 7
    ),
    aggregated AS (
      SELECT
        count(*) FILTER (WHERE trang_thai = 'Chờ xử lý') AS cnt_cho_xu_ly,
        count(*) FILTER (WHERE trang_thai = 'Đã duyệt') AS cnt_da_duyet,
        count(*) FILTER (WHERE trang_thai = 'Hoàn thành') AS cnt_hoan_thanh,
        count(*) FILTER (WHERE trang_thai = 'Không HT') AS cnt_khong_ht
      FROM filtered
    ),
    due_aggregated AS (
      SELECT
        count(*) AS total_count,
        count(*) FILTER (WHERE days_difference < 0) AS overdue_count,
        count(*) FILTER (WHERE days_difference = 0) AS due_today_count,
        count(*) FILTER (WHERE days_difference BETWEEN 1 AND 7) AS due_soon_count
      FROM due_items
    ),
    ranked_items AS (
      SELECT *
      FROM due_items
      ORDER BY ngay_mong_muon_hoan_thanh ASC, id ASC
      LIMIT 50
    )
    SELECT jsonb_build_object(
      'counts', jsonb_build_object(
        'Chờ xử lý', COALESCE(aggregated.cnt_cho_xu_ly, 0),
        'Đã duyệt', COALESCE(aggregated.cnt_da_duyet, 0),
        'Hoàn thành', COALESCE(aggregated.cnt_hoan_thanh, 0),
        'Không HT', COALESCE(aggregated.cnt_khong_ht, 0)
      ),
      'overdue_summary', jsonb_build_object(
        'total', COALESCE(due_aggregated.total_count, 0),
        'overdue', COALESCE(due_aggregated.overdue_count, 0),
        'due_today', COALESCE(due_aggregated.due_today_count, 0),
        'due_soon', COALESCE(due_aggregated.due_soon_count, 0),
        'items', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', id,
              'thiet_bi_id', thiet_bi_id,
              'ngay_yeu_cau', ngay_yeu_cau,
              'trang_thai', trang_thai,
              'mo_ta_su_co', mo_ta_su_co,
              'hang_muc_sua_chua', hang_muc_sua_chua,
              'ngay_mong_muon_hoan_thanh', ngay_mong_muon_hoan_thanh,
              'nguoi_yeu_cau', nguoi_yeu_cau,
              'ngay_duyet', ngay_duyet,
              'ngay_hoan_thanh', ngay_hoan_thanh,
              'nguoi_duyet', nguoi_duyet,
              'nguoi_xac_nhan', nguoi_xac_nhan,
              'don_vi_thuc_hien', don_vi_thuc_hien,
              'ten_don_vi_thue', ten_don_vi_thue,
              'ket_qua_sua_chua', ket_qua_sua_chua,
              'ly_do_khong_hoan_thanh', ly_do_khong_hoan_thanh,
              'chi_phi_sua_chua', chi_phi_sua_chua,
              'days_difference', days_difference,
              'thiet_bi', jsonb_build_object(
                'ten_thiet_bi', ten_thiet_bi,
                'ma_thiet_bi', ma_thiet_bi,
                'model', model,
                'serial', serial,
                'khoa_phong_quan_ly', khoa_phong_quan_ly,
                'facility_name', facility_name,
                'facility_id', facility_id
              )
            )
            ORDER BY ngay_mong_muon_hoan_thanh ASC, id ASC
          )
          FROM ranked_items
        ), '[]'::jsonb)
      )
    )
    FROM aggregated, due_aggregated
  );
END;
$$;


ALTER FUNCTION public.repair_request_status_counts(p_q text, p_don_vi bigint, p_date_from date, p_date_to date) OWNER TO postgres;

--
-- Name: FUNCTION repair_request_status_counts(p_q text, p_don_vi bigint, p_date_from date, p_date_to date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.repair_request_status_counts(p_q text, p_don_vi bigint, p_date_from date, p_date_to date) IS 'Returns counts per status for current filters (q, date range, facility), excluding status filter; respects tenant isolation and role-based scoping.';


--
-- Name: repair_request_sync_equipment_status(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_sync_equipment_status(p_thiet_bi_id bigint, p_fallback_status text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_current_status text;
  v_is_deleted boolean := false;
  v_has_open_request boolean := false;
  v_latest_status text;
  v_next_status text;
BEGIN
  SELECT tb.tinh_trang_hien_tai, tb.is_deleted
  INTO v_current_status, v_is_deleted
  FROM public.thiet_bi tb
  WHERE tb.id = p_thiet_bi_id
  FOR UPDATE OF tb;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_is_deleted THEN
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.yeu_cau_sua_chua ycss
    WHERE ycss.thiet_bi_id = p_thiet_bi_id
      AND ycss.trang_thai IN ('Chờ xử lý', 'Đã duyệt')
  )
  INTO v_has_open_request;

  IF v_has_open_request THEN
    v_next_status := 'Chờ sửa chữa';
  ELSE
    SELECT ycss.trang_thai
    INTO v_latest_status
    FROM public.yeu_cau_sua_chua ycss
    WHERE ycss.thiet_bi_id = p_thiet_bi_id
    ORDER BY ycss.id DESC
    LIMIT 1;

    IF FOUND THEN
      IF v_latest_status = 'Hoàn thành' THEN
        v_next_status := 'Hoạt động';
      ELSE
        v_next_status := 'Chờ sửa chữa';
      END IF;
    ELSE
      v_next_status := coalesce(p_fallback_status, v_current_status);
    END IF;
  END IF;

  IF v_next_status IS DISTINCT FROM v_current_status THEN
    UPDATE public.thiet_bi
    SET tinh_trang_hien_tai = v_next_status
    WHERE id = p_thiet_bi_id;
  END IF;
END;
$$;


ALTER FUNCTION public.repair_request_sync_equipment_status(p_thiet_bi_id bigint, p_fallback_status text) OWNER TO postgres;

--
-- Name: repair_request_update(integer, text, text, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_update(p_id integer, p_mo_ta_su_co text, p_hang_muc_sua_chua text, p_ngay_mong_muon_hoan_thanh date, p_don_vi_thuc_hien text, p_ten_don_vi_thue text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims jsonb;
  v_role text;
  v_is_global boolean := false;
  v_user_id bigint;
  v_don_vi bigint;
  v_locked record;
  v_req public.yeu_cau_sua_chua%ROWTYPE;
  v_tb_don_vi bigint;
BEGIN
  v_claims := coalesce(current_setting('request.jwt.claims', true), '{}'::text)::jsonb;
  v_role := lower(coalesce(nullif(v_claims->>'app_role', ''), nullif(v_claims->>'role', '')));
  v_is_global := v_role in ('global', 'admin');
  v_user_id := nullif(v_claims->>'user_id', '')::bigint;
  v_don_vi := nullif(v_claims->>'don_vi', '')::bigint;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  IF v_role = 'regional_leader' THEN
    RAISE EXCEPTION 'Permission denied' USING errcode = '42501';
  END IF;

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim for non-global role %', v_role USING errcode = '42501';
  END IF;

  SELECT ycss.*, tb.don_vi AS tb_don_vi
  INTO v_locked
  FROM public.yeu_cau_sua_chua ycss
  JOIN public.thiet_bi tb ON tb.id = ycss.thiet_bi_id
  WHERE ycss.id = p_id
    AND tb.is_deleted = false
  FOR UPDATE OF ycss, tb;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Yêu cầu không tồn tại';
  END IF;

  v_tb_don_vi := v_locked.tb_don_vi;

  IF NOT v_is_global AND v_tb_don_vi IS DISTINCT FROM v_don_vi THEN
    RAISE EXCEPTION 'Không có quyền trên thiết bị thuộc đơn vị khác' USING errcode = '42501';
  END IF;

  UPDATE public.yeu_cau_sua_chua
  SET mo_ta_su_co = p_mo_ta_su_co,
      hang_muc_sua_chua = p_hang_muc_sua_chua,
      ngay_mong_muon_hoan_thanh = p_ngay_mong_muon_hoan_thanh,
      don_vi_thuc_hien = p_don_vi_thuc_hien,
      ten_don_vi_thue = p_ten_don_vi_thue
  WHERE id = p_id
  RETURNING * INTO v_req;

  INSERT INTO public.lich_su_thiet_bi(thiet_bi_id, loai_su_kien, mo_ta, chi_tiet, yeu_cau_id)
  VALUES (
    v_req.thiet_bi_id,
    'Sửa chữa',
    'Cập nhật nội dung yêu cầu sửa chữa',
    jsonb_build_object(
      'mo_ta_su_co', v_req.mo_ta_su_co,
      'hang_muc', v_req.hang_muc_sua_chua,
      'ngay_mong_muon_hoan_thanh', v_req.ngay_mong_muon_hoan_thanh,
      'don_vi_thuc_hien', v_req.don_vi_thuc_hien,
      'ten_don_vi_thue', v_req.ten_don_vi_thue
    ),
    p_id
  );

  IF NOT public.audit_log(
    'repair_request_update',
    'repair_request',
    p_id,
    NULL,
    jsonb_build_object(
      'mo_ta_su_co', v_req.mo_ta_su_co,
      'hang_muc_sua_chua', v_req.hang_muc_sua_chua,
      'ngay_mong_muon_hoan_thanh', v_req.ngay_mong_muon_hoan_thanh,
      'don_vi_thuc_hien', v_req.don_vi_thuc_hien,
      'ten_don_vi_thue', v_req.ten_don_vi_thue
    )
  ) THEN
    RAISE EXCEPTION 'audit_log failed for repair_request %', p_id;
  END IF;
END;
$$;


ALTER FUNCTION public.repair_request_update(p_id integer, p_mo_ta_su_co text, p_hang_muc_sua_chua text, p_ngay_mong_muon_hoan_thanh date, p_don_vi_thuc_hien text, p_ten_don_vi_thue text) OWNER TO postgres;

--
-- Name: reset_password_by_admin(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reset_password_by_admin(p_admin_user_id bigint, p_target_user_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_claims JSONB := COALESCE(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_role TEXT := LOWER(NULLIF(COALESCE(v_claims->>'app_role', v_claims->>'role'), ''));
  v_claim_user_id BIGINT := NULLIF(v_claims->>'user_id', '')::BIGINT;
  admin_rec public.nhan_vien%ROWTYPE;
  target_rec public.nhan_vien%ROWTYPE;
  new_password TEXT := 'userqltb';
BEGIN
  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_claim_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_claim_user_id IS DISTINCT FROM p_admin_user_id THEN
    RAISE EXCEPTION 'admin user claim mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO admin_rec
  FROM public.nhan_vien
  WHERE id = p_admin_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Admin user not found');
  END IF;

  IF admin_rec.role NOT IN ('admin', 'global') OR v_role <> 'global' THEN
    RAISE EXCEPTION 'Access denied: Admin or Global privileges required' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO target_rec
  FROM public.nhan_vien
  WHERE id = p_target_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Target user not found');
  END IF;

  UPDATE public.nhan_vien
  SET hashed_password = extensions.crypt(new_password, extensions.gen_salt('bf', 12)),
      password = 'hashed password',
      password_changed_at = NOW(),
      failed_attempts = 0,
      password_reset_required = TRUE
  WHERE id = p_target_user_id;

  INSERT INTO public.audit_logs (
    admin_user_id,
    admin_username,
    action_type,
    target_user_id,
    target_username,
    action_details,
    ip_address,
    user_agent,
    entity_type,
    entity_id,
    entity_label
  ) VALUES (
    p_admin_user_id,
    admin_rec.username,
    'password_reset_admin',
    p_target_user_id,
    target_rec.username,
    jsonb_build_object('reason', 'admin reset password to default value'),
    COALESCE(pg_catalog.inet_client_addr(), '0.0.0.0'::INET),
    COALESCE(
      NULLIF((COALESCE(NULLIF(current_setting('request.headers', true), ''), '{}')::jsonb)->>'user-agent', ''),
      'unknown'
    ),
    'nhan_vien',
    p_target_user_id,
    target_rec.username
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', format('Password for user %s has been reset to the default.', target_rec.username),
    'username', target_rec.username,
    'new_password', new_password
  );
END;
$$;


ALTER FUNCTION public.reset_password_by_admin(p_admin_user_id bigint, p_target_user_id bigint) OWNER TO postgres;

--
-- Name: FUNCTION reset_password_by_admin(p_admin_user_id bigint, p_target_user_id bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reset_password_by_admin(p_admin_user_id bigint, p_target_user_id bigint) IS 'Admin/global RPC to reset a user password to the default value with audit logging.';


--
-- Name: technical_configuration_assessment_upsert(uuid, uuid, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_assessment_upsert(p_comparison_set_id uuid, p_criterion_id uuid, p_technical_axis text, p_evidence_axis text, p_notes text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_dossier_id UUID;
  v_baseline_version_id UUID;
  v_criterion_version_id UUID;
  v_archived_at TIMESTAMPTZ;
  v_assessment_id UUID;
  v_current_revision BIGINT;
  v_data JSONB;
BEGIN
  v_user_id := public._technical_configuration_require_global_user();

  IF p_comparison_set_id IS NULL
     OR p_criterion_id IS NULL
     OR p_expected_revision IS NULL OR p_expected_revision < 0 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  IF p_technical_axis IS NOT NULL
     AND p_technical_axis NOT IN (
       'exceeds',
       'meets',
       'fails',
       'unclear',
       'not_applicable'
     ) THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  IF p_evidence_axis IS NOT NULL
     AND p_evidence_axis NOT IN (
       'complete',
       'partial',
       'missing',
       'not_required'
     ) THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT cs.dossier_id
  INTO v_dossier_id
  FROM public.technical_configuration_comparison_sets cs
  WHERE cs.id = p_comparison_set_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT d.archived_at
  INTO v_archived_at
  FROM public.technical_configuration_dossiers d
  WHERE d.id = v_dossier_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF v_archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived_dossier' USING ERRCODE = 'PT409';
  END IF;

  SELECT cs.baseline_version_id
  INTO v_baseline_version_id
  FROM public.technical_configuration_comparison_sets cs
  WHERE cs.id = p_comparison_set_id
    AND cs.dossier_id = v_dossier_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT c.baseline_version_id
  INTO v_criterion_version_id
  FROM public.technical_configuration_baseline_criteria c
  WHERE c.id = p_criterion_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF v_baseline_version_id IS DISTINCT FROM v_criterion_version_id THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT a.id, a.revision
  INTO v_assessment_id, v_current_revision
  FROM public.technical_configuration_manual_assessments a
  WHERE a.comparison_set_id = p_comparison_set_id
    AND a.criterion_id = p_criterion_id
  FOR UPDATE;

  IF FOUND THEN
    IF v_current_revision IS DISTINCT FROM p_expected_revision THEN
      RAISE EXCEPTION 'stale_revision' USING ERRCODE = 'PT409';
    END IF;

    UPDATE public.technical_configuration_manual_assessments AS a
    SET technical_axis = p_technical_axis,
        evidence_axis = p_evidence_axis,
        notes = COALESCE(p_notes, ''),
        revision = a.revision + 1,
        updated_at = now(),
        updated_by = v_user_id
    WHERE a.id = v_assessment_id;
  ELSE
    IF p_expected_revision = 0 THEN
      INSERT INTO public.technical_configuration_manual_assessments (
        comparison_set_id,
        baseline_version_id,
        criterion_id,
        technical_axis,
        evidence_axis,
        notes,
        created_by,
        updated_by
      )
      VALUES (
        p_comparison_set_id,
        v_baseline_version_id,
        p_criterion_id,
        p_technical_axis,
        p_evidence_axis,
        COALESCE(p_notes, ''),
        v_user_id,
        v_user_id
      )
      ON CONFLICT (comparison_set_id, criterion_id) DO NOTHING
      RETURNING id INTO v_assessment_id;

      IF v_assessment_id IS NULL THEN
        RAISE EXCEPTION 'stale_revision' USING ERRCODE = 'PT409';
      END IF;
    ELSE
      RAISE EXCEPTION 'stale_revision' USING ERRCODE = 'PT409';
    END IF;
  END IF;

  SELECT jsonb_build_object(
    'id', a.id,
    'comparison_set_id', a.comparison_set_id,
    'baseline_version_id', a.baseline_version_id,
    'criterion_id', a.criterion_id,
    'technical_axis', a.technical_axis,
    'evidence_axis', a.evidence_axis,
    'notes', a.notes,
    'revision', a.revision,
    'created_by', a.created_by,
    'created_at', a.created_at,
    'updated_by', a.updated_by,
    'updated_at', a.updated_at
  )
  INTO v_data
  FROM public.technical_configuration_manual_assessments a
  WHERE a.id = v_assessment_id;

  RETURN jsonb_build_object('data', v_data);
END;
$$;


ALTER FUNCTION public.technical_configuration_assessment_upsert(p_comparison_set_id uuid, p_criterion_id uuid, p_technical_axis text, p_evidence_axis text, p_notes text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_assessments_list(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_assessments_list(p_comparison_set_id uuid, p_page integer, p_page_size integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_baseline_version_id UUID;
  v_total BIGINT;
  v_data JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  IF p_comparison_set_id IS NULL
     OR p_page IS NULL OR p_page < 1
     OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT cs.baseline_version_id
  INTO v_baseline_version_id
  FROM public.technical_configuration_comparison_sets cs
  WHERE cs.id = p_comparison_set_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  WITH ordered_assessments AS MATERIALIZED (
    SELECT
      jsonb_build_object(
        'id', a.id,
        'comparison_set_id', a.comparison_set_id,
        'baseline_version_id', a.baseline_version_id,
        'criterion_id', a.criterion_id,
        'technical_axis', a.technical_axis,
        'evidence_axis', a.evidence_axis,
        'notes', a.notes,
        'revision', a.revision,
        'created_by', a.created_by,
        'created_at', a.created_at,
        'updated_by', a.updated_by,
        'updated_at', a.updated_at
      ) AS item,
      bg.sort_order AS group_order,
      bc.sort_order AS criterion_order,
      bc.id AS criterion_id
    FROM public.technical_configuration_manual_assessments a
    JOIN public.technical_configuration_baseline_criteria bc
      ON bc.id = a.criterion_id
     AND bc.baseline_version_id = a.baseline_version_id
    JOIN public.technical_configuration_baseline_groups bg
      ON bg.id = bc.group_id
     AND bg.baseline_version_id = bc.baseline_version_id
    WHERE a.comparison_set_id = p_comparison_set_id
      AND a.baseline_version_id = v_baseline_version_id
    ORDER BY bg.sort_order, bc.sort_order, bc.id
  ),
  paged_assessments AS (
    SELECT *
    FROM ordered_assessments
    ORDER BY group_order, criterion_order, criterion_id
    LIMIT p_page_size
    OFFSET (p_page - 1)::BIGINT * p_page_size
  )
  SELECT
    (SELECT count(*) FROM ordered_assessments),
    COALESCE(
      jsonb_agg(
        paged.item
        ORDER BY paged.group_order, paged.criterion_order, paged.criterion_id
      ),
      '[]'::JSONB
    )
  INTO v_total, v_data
  FROM paged_assessments paged;

  RETURN jsonb_build_object(
    'data', v_data,
    'total', v_total,
    'page', p_page,
    'page_size', p_page_size
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_assessments_list(p_comparison_set_id uuid, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_bulk_preview(uuid, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_bulk_preview(p_group_id uuid, p_items jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_version_id UUID;
  v_next_number BIGINT;
  v_next_order INTEGER;
  v_data JSONB;
  v_errors JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT baseline_version_id INTO v_version_id
  FROM public.technical_configuration_baseline_groups
  WHERE id = p_group_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  PERFORM public._technical_configuration_require_editable_baseline_version(
    v_version_id,
    p_expected_revision
  );
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT next_criterion_number INTO v_next_number
  FROM public.technical_configuration_baseline_versions
  WHERE id = v_version_id;
  SELECT COALESCE(MAX(sort_order), 0) + 1 INTO v_next_order
  FROM public.technical_configuration_baseline_criteria
  WHERE group_id = p_group_id;

  WITH items AS (
    SELECT value, ordinality
    FROM jsonb_array_elements(p_items) WITH ORDINALITY
  ),
  normalized AS (
    SELECT
      value,
      ordinality,
      value->>'title' AS title,
      value->>'requirement_text' AS requirement_text,
      jsonb_typeof(value) = 'object' AS is_object,
      NOT EXISTS (
        SELECT 1
        FROM jsonb_object_keys(
          CASE WHEN jsonb_typeof(value) = 'object' THEN value ELSE '{}'::JSONB END
        ) AS item_key(key)
        WHERE key NOT IN ('title', 'requirement_text')
      ) AS has_only_supported_fields,
      COALESCE(
        jsonb_typeof(value->'requirement_text') = 'string'
          AND btrim(value->>'requirement_text') <> '',
        FALSE
      ) AS has_valid_requirement,
      NOT (value ? 'title')
        OR value->'title' = 'null'::JSONB
        OR jsonb_typeof(value->'title') = 'string' AS has_valid_title
    FROM items
  ),
  validated AS (
    SELECT
      *,
      is_object
        AND has_only_supported_fields
        AND has_valid_requirement
        AND has_valid_title AS is_valid,
      CASE
        WHEN NOT is_object THEN 'item must be an object'
        WHEN NOT has_only_supported_fields THEN 'unsupported field'
        WHEN NOT has_valid_requirement THEN 'requirement_text must be a non-empty string'
        WHEN NOT has_valid_title THEN 'title must be a string or null'
      END AS error_message
    FROM normalized
  )
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'criterion_code', 'TC-' || lpad((v_next_number + ordinality - 1)::TEXT, 4, '0'),
      'title', NULLIF(btrim(title), ''),
      'requirement_text', btrim(requirement_text),
      'sort_order', v_next_order + ordinality - 1
    ) ORDER BY ordinality) FILTER (WHERE is_valid), '[]'::JSONB),
    COALESCE(jsonb_agg(jsonb_build_object(
      'row', ordinality,
      'code', 'validation_error',
      'message', error_message
    ) ORDER BY ordinality) FILTER (WHERE NOT is_valid), '[]'::JSONB)
  INTO v_data, v_errors
  FROM validated;

  RETURN jsonb_build_object('data', v_data, 'errors', v_errors);
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_bulk_preview(p_group_id uuid, p_items jsonb, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_citation_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_citation_delete(p_baseline_citation_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_user_id BIGINT; v_version_id UUID; v_revision BIGINT;
BEGIN
  SELECT baseline_version_id INTO v_version_id FROM public.technical_configuration_baseline_citations WHERE id = p_baseline_citation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404'; END IF;
  v_user_id := public._technical_configuration_require_editable_baseline_version(v_version_id, p_expected_revision);
  DELETE FROM public.technical_configuration_baseline_citations WHERE id = p_baseline_citation_id;
  v_revision := public._technical_configuration_baseline_bump_revision(v_version_id, v_user_id);
  RETURN jsonb_build_object('data', jsonb_build_object('id', p_baseline_citation_id, 'revision', v_revision));
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_citation_delete(p_baseline_citation_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_citation_upsert(uuid, uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_citation_upsert(p_baseline_document_id uuid, p_criterion_id uuid, p_page_section text, p_excerpt text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_user_id BIGINT; v_version_id UUID; v_id UUID; v_revision BIGINT;
BEGIN
  SELECT baseline_version_id INTO v_version_id FROM public.technical_configuration_baseline_documents WHERE id = p_baseline_document_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404'; END IF;
  v_user_id := public._technical_configuration_require_editable_baseline_version(v_version_id, p_expected_revision);
  IF NOT EXISTS (SELECT 1 FROM public.technical_configuration_baseline_criteria
                 WHERE id = p_criterion_id AND baseline_version_id = v_version_id) THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  INSERT INTO public.technical_configuration_baseline_citations
    (baseline_version_id, baseline_document_id, criterion_id, page_section, excerpt, created_by, updated_by)
  VALUES (v_version_id, p_baseline_document_id, p_criterion_id, p_page_section, p_excerpt, v_user_id, v_user_id)
  ON CONFLICT (baseline_document_id, criterion_id) DO UPDATE
  SET page_section = EXCLUDED.page_section, excerpt = EXCLUDED.excerpt,
      updated_at = now(), updated_by = EXCLUDED.updated_by RETURNING id INTO v_id;
  v_revision := public._technical_configuration_baseline_bump_revision(v_version_id, v_user_id);
  RETURN jsonb_build_object('data',
    public._technical_configuration_citation_payload('baseline', v_id) || jsonb_build_object('revision', v_revision));
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_citation_upsert(p_baseline_document_id uuid, p_criterion_id uuid, p_page_section text, p_excerpt text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_copy(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_copy(p_source_baseline_version_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_response JSONB; v_new_version_id UUID; v_user_id BIGINT;
BEGIN
  v_user_id := public._technical_configuration_require_global_user();
  v_response := public._technical_configuration_baseline_copy_p7a1(
    p_source_baseline_version_id, p_expected_revision);
  v_new_version_id := (v_response->'data'->>'id')::UUID;
  CREATE TEMP TABLE technical_configuration_baseline_document_copy_map (
    source_document_id UUID PRIMARY KEY, target_document_id UUID NOT NULL UNIQUE
  ) ON COMMIT DROP;
  INSERT INTO pg_temp.technical_configuration_baseline_document_copy_map
  SELECT id, gen_random_uuid() FROM public.technical_configuration_baseline_documents
  WHERE baseline_version_id = p_source_baseline_version_id;
  INSERT INTO public.technical_configuration_baseline_documents
    (id, baseline_version_id, name, url, created_by, updated_by)
  SELECT m.target_document_id, v_new_version_id, d.name, d.url, v_user_id, v_user_id
  FROM pg_temp.technical_configuration_baseline_document_copy_map m
  JOIN public.technical_configuration_baseline_documents d ON d.id = m.source_document_id;
  INSERT INTO public.technical_configuration_baseline_citations
    (baseline_version_id, baseline_document_id, criterion_id, page_section, excerpt, created_by, updated_by)
  SELECT v_new_version_id, m.target_document_id, target_criterion.id,
    c.page_section, c.excerpt, v_user_id, v_user_id
  FROM public.technical_configuration_baseline_citations c
  JOIN pg_temp.technical_configuration_baseline_document_copy_map m ON m.source_document_id = c.baseline_document_id
  JOIN public.technical_configuration_baseline_criteria target_criterion
    ON target_criterion.baseline_version_id = v_new_version_id
   AND target_criterion.source_criterion_id = c.criterion_id;
  CREATE TEMP TABLE technical_configuration_reference_document_copy_map (
    source_document_id UUID PRIMARY KEY, target_document_id UUID NOT NULL UNIQUE
  ) ON COMMIT DROP;
  INSERT INTO pg_temp.technical_configuration_reference_document_copy_map
  SELECT id, gen_random_uuid() FROM public.technical_configuration_reference_documents
  WHERE baseline_version_id = p_source_baseline_version_id;
  INSERT INTO public.technical_configuration_reference_documents
    (id, baseline_version_id, reference_product_id, name, url, created_by, updated_by)
  SELECT m.target_document_id, v_new_version_id, product_map.target_reference_product_id,
    d.name, d.url, v_user_id, v_user_id
  FROM pg_temp.technical_configuration_reference_document_copy_map m
  JOIN public.technical_configuration_reference_documents d ON d.id = m.source_document_id
  JOIN pg_temp.technical_configuration_reference_product_copy_map product_map
    ON product_map.source_reference_product_id = d.reference_product_id;
  INSERT INTO public.technical_configuration_reference_citations
    (baseline_version_id, reference_document_id, criterion_id, page_section, excerpt, created_by, updated_by)
  SELECT v_new_version_id, m.target_document_id, target_criterion.id,
    c.page_section, c.excerpt, v_user_id, v_user_id
  FROM public.technical_configuration_reference_citations c
  JOIN pg_temp.technical_configuration_reference_document_copy_map m ON m.source_document_id = c.reference_document_id
  JOIN public.technical_configuration_baseline_criteria target_criterion
    ON target_criterion.baseline_version_id = v_new_version_id
   AND target_criterion.source_criterion_id = c.criterion_id;
  RETURN v_response;
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_copy(p_source_baseline_version_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_criteria_reorder(uuid, uuid[], bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_criteria_reorder(p_group_id uuid, p_criterion_ids uuid[], p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT; v_version_id UUID; v_revision BIGINT;
  v_existing_count BIGINT; v_input_count BIGINT;
  v_distinct_count BIGINT; v_matching_count BIGINT;
BEGIN
  SELECT context.user_id, context.version_id
  INTO v_user_id, v_version_id
  FROM public._technical_configuration_baseline_hierarchy_context(
    p_group_id, NULL, p_expected_revision
  ) context;
  IF p_criterion_ids IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT COUNT(*) INTO v_existing_count
  FROM public.technical_configuration_baseline_criteria
  WHERE group_id = p_group_id;
  SELECT COUNT(*), COUNT(DISTINCT item_id)
  INTO v_input_count, v_distinct_count
  FROM unnest(p_criterion_ids) input(item_id);
  SELECT COUNT(*) INTO v_matching_count
  FROM public.technical_configuration_baseline_criteria
  WHERE group_id = p_group_id
    AND id = ANY(p_criterion_ids);
  IF cardinality(p_criterion_ids) <> v_existing_count
     OR v_input_count <> v_distinct_count
     OR v_matching_count <> v_existing_count THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SET CONSTRAINTS technical_configuration_baseline_criteria_group_sort_key DEFERRED;
  UPDATE public.technical_configuration_baseline_criteria c
  SET sort_order = input.new_order::INTEGER,
      updated_at = now(),
      updated_by = v_user_id
  FROM unnest(p_criterion_ids) WITH ORDINALITY input(id, new_order)
  WHERE c.id = input.id;
  PERFORM public._technical_configuration_baseline_normalize_group(
    p_group_id, v_user_id
  );
  v_revision := public._technical_configuration_baseline_bump_revision(
    v_version_id, v_user_id
  );
  RETURN jsonb_build_object(
    'data', public._technical_configuration_baseline_snapshot(v_version_id)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_criteria_reorder(p_group_id uuid, p_criterion_ids uuid[], p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_criterion_create(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_criterion_create(p_group_id uuid, p_title text, p_requirement_text text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT; v_version_id UUID; v_criterion_id UUID;
  v_criterion_number BIGINT; v_criterion_code TEXT;
  v_sort_order INTEGER; v_revision BIGINT;
BEGIN
  SELECT context.user_id, context.version_id
  INTO v_user_id, v_version_id
  FROM public._technical_configuration_baseline_hierarchy_context(
    p_group_id, NULL, p_expected_revision
  ) context;
  IF p_requirement_text IS NULL OR btrim(p_requirement_text) = '' THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT COALESCE(MAX(sort_order), 0) + 1 INTO v_sort_order
  FROM public.technical_configuration_baseline_criteria
  WHERE group_id = p_group_id;
  UPDATE public.technical_configuration_baseline_versions
  SET next_criterion_number = next_criterion_number + 1,
      revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = v_version_id
  RETURNING next_criterion_number - 1, revision
  INTO v_criterion_number, v_revision;
  v_criterion_code := 'TC-' || lpad(
    v_criterion_number::TEXT,
    GREATEST(4, length(v_criterion_number::TEXT)),
    '0'
  );

  BEGIN
    INSERT INTO public.technical_configuration_baseline_criteria (
      baseline_version_id, group_id, subgroup_id, criterion_code, title,
      requirement_text, sort_order, created_by, updated_by
    ) VALUES (
      v_version_id, p_group_id, NULL, v_criterion_code,
      NULLIF(btrim(p_title), ''), btrim(p_requirement_text),
      v_sort_order, v_user_id, v_user_id
    ) RETURNING id INTO v_criterion_id;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END;

  PERFORM public._technical_configuration_baseline_normalize_group(
    p_group_id, v_user_id
  );
  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_baseline_criterion_payload(
      v_criterion_id, v_revision
    )
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_criterion_create(p_group_id uuid, p_title text, p_requirement_text text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_criterion_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_criterion_delete(p_criterion_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_version_id UUID;
  v_group_id UUID;
  v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT baseline_version_id, group_id INTO v_version_id, v_group_id
  FROM public.technical_configuration_baseline_criteria
  WHERE id = p_criterion_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  v_user_id := public._technical_configuration_require_editable_baseline_version(
    v_version_id,
    p_expected_revision
  );
  DELETE FROM public.technical_configuration_baseline_criteria
  WHERE id = p_criterion_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  WITH ordered AS (
    SELECT id, row_number() OVER (ORDER BY sort_order, id)::INTEGER AS new_order
    FROM public.technical_configuration_baseline_criteria
    WHERE group_id = v_group_id
  )
  UPDATE public.technical_configuration_baseline_criteria c
  SET sort_order = ordered.new_order, updated_at = now(), updated_by = v_user_id
  FROM ordered
  WHERE c.id = ordered.id AND c.sort_order <> ordered.new_order;

  v_revision := public._technical_configuration_baseline_bump_revision(
    v_version_id,
    v_user_id
  );
  RETURN jsonb_build_object('data', jsonb_build_object(
    'id', p_criterion_id,
    'revision', v_revision
  ));
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_criterion_delete(p_criterion_id uuid, p_expected_revision bigint) OWNER TO postgres;

