--
-- Name: technical_configuration_baseline_documents_list(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_documents_list(p_baseline_version_id uuid, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_page INTEGER := COALESCE(p_page, 1);
  v_page_size INTEGER := COALESCE(p_page_size, 50);
  v_result JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  IF NOT EXISTS (
    SELECT 1
    FROM public.technical_configuration_baseline_versions
    WHERE id = p_baseline_version_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF v_page < 1 OR v_page_size < 1 OR v_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  WITH documents AS (
    SELECT
      id, 'baseline'::TEXT AS owner_type, baseline_version_id AS owner_id,
      name, url, created_by, created_at, updated_at
    FROM public.technical_configuration_baseline_documents
    WHERE baseline_version_id = p_baseline_version_id
    UNION ALL
    SELECT
      id, 'reference_product', reference_product_id, name, url,
      created_by, created_at, updated_at
    FROM public.technical_configuration_reference_documents
    WHERE baseline_version_id = p_baseline_version_id
  ),
  paged_documents AS (
    SELECT *
    FROM documents
    ORDER BY created_at, owner_type, id
    LIMIT v_page_size
    OFFSET (v_page - 1)::BIGINT * v_page_size
  ),
  citation_rows AS (
    SELECT
      d.owner_type,
      d.id AS document_id,
      c.id,
      c.criterion_id,
      cr.baseline_version_id,
      cr.group_id,
      cr.subgroup_id,
      cr.criterion_code,
      c.page_section,
      c.excerpt,
      c.created_at,
      g.sort_order AS group_sort_order,
      sg.sort_order AS subgroup_sort_order,
      cr.sort_order AS criterion_sort_order
    FROM public.technical_configuration_baseline_citations c
    INNER JOIN paged_documents d
      ON d.owner_type = 'baseline' AND d.id = c.baseline_document_id
    INNER JOIN public.technical_configuration_baseline_criteria cr
      ON cr.id = c.criterion_id AND cr.baseline_version_id = p_baseline_version_id
    INNER JOIN public.technical_configuration_baseline_groups g
      ON g.id = cr.group_id AND g.baseline_version_id = cr.baseline_version_id
    LEFT JOIN public.technical_configuration_baseline_subgroups sg
      ON sg.id = cr.subgroup_id
      AND sg.group_id = cr.group_id
      AND sg.baseline_version_id = cr.baseline_version_id
    WHERE c.baseline_version_id = p_baseline_version_id
    UNION ALL
    SELECT
      d.owner_type,
      d.id,
      c.id,
      c.criterion_id,
      cr.baseline_version_id,
      cr.group_id,
      cr.subgroup_id,
      cr.criterion_code,
      c.page_section,
      c.excerpt,
      c.created_at,
      g.sort_order,
      sg.sort_order,
      cr.sort_order
    FROM public.technical_configuration_reference_citations c
    INNER JOIN paged_documents d
      ON d.owner_type = 'reference_product' AND d.id = c.reference_document_id
    INNER JOIN public.technical_configuration_baseline_criteria cr
      ON cr.id = c.criterion_id AND cr.baseline_version_id = p_baseline_version_id
    INNER JOIN public.technical_configuration_baseline_groups g
      ON g.id = cr.group_id AND g.baseline_version_id = cr.baseline_version_id
    LEFT JOIN public.technical_configuration_baseline_subgroups sg
      ON sg.id = cr.subgroup_id
      AND sg.group_id = cr.group_id
      AND sg.baseline_version_id = cr.baseline_version_id
    WHERE c.baseline_version_id = p_baseline_version_id
  ),
  citations_by_document AS (
    SELECT
      cr.owner_type,
      cr.document_id,
      jsonb_agg(
        jsonb_build_object(
          'id', cr.id,
          'criterion_id', cr.criterion_id,
          'baseline_version_id', cr.baseline_version_id,
          'group_id', cr.group_id,
          'subgroup_id', cr.subgroup_id,
          'criterion_code', cr.criterion_code,
          'page_section', cr.page_section,
          'excerpt', cr.excerpt
        )
        ORDER BY
          cr.group_sort_order,
          (cr.subgroup_id IS NOT NULL),
          cr.subgroup_sort_order,
          cr.criterion_sort_order,
          cr.created_at,
          cr.id
      ) AS citations
    FROM citation_rows cr
    GROUP BY cr.owner_type, cr.document_id
  )
  SELECT jsonb_build_object(
    'data',
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', d.id,
            'owner_type', d.owner_type,
            'owner_id', d.owner_id,
            'name', d.name,
            'url', d.url,
            'created_by', d.created_by,
            'created_at', d.created_at,
            'updated_at', d.updated_at,
            'citations', COALESCE(cbd.citations, '[]'::JSONB)
          )
          ORDER BY d.created_at, d.owner_type, d.id
        )
        FROM paged_documents d
        LEFT JOIN citations_by_document cbd
          ON cbd.owner_type = d.owner_type AND cbd.document_id = d.id
      ),
      '[]'::JSONB
    ),
    'total', (SELECT count(*) FROM documents),
    'page', v_page,
    'page_size', v_page_size
  )
  INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_documents_list(p_baseline_version_id uuid, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_draft_create(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_draft_create(p_dossier_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_dossier_revision BIGINT;
  v_version_id UUID;
  v_version_number BIGINT;
BEGIN
  v_user_id := public._technical_configuration_require_editable_dossier(
    p_dossier_id,
    p_expected_revision
  );
  IF EXISTS (
    SELECT 1
    FROM public.technical_configuration_baseline_versions
    WHERE dossier_id = p_dossier_id AND status = 'draft'
  ) THEN
    RAISE EXCEPTION 'draft_already_exists' USING ERRCODE = 'PT409';
  END IF;
  SELECT COALESCE(MAX(v.version_number), 0) + 1
  INTO v_version_number
  FROM public.technical_configuration_baseline_versions v
  WHERE v.dossier_id = p_dossier_id;
  INSERT INTO public.technical_configuration_baseline_versions (
    dossier_id,
    version_number,
    created_by,
    updated_by
  )
  VALUES (p_dossier_id, v_version_number, v_user_id, v_user_id)
  RETURNING id INTO v_version_id;
  INSERT INTO public.technical_configuration_baseline_groups (
    baseline_version_id,
    name,
    sort_order,
    created_by,
    updated_by
  )
  VALUES
    (v_version_id, 'Yêu cầu chung', 1, v_user_id, v_user_id),
    (v_version_id, 'Yêu cầu cấu hình cung cấp', 2, v_user_id, v_user_id),
    (v_version_id, 'Yêu cầu kỹ thuật', 3, v_user_id, v_user_id),
    (v_version_id, 'Yêu cầu khác', 4, v_user_id, v_user_id);
  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = p_dossier_id
  RETURNING revision INTO v_dossier_revision;
  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_baseline_snapshot(v_version_id)
      || jsonb_build_object('dossier_revision', v_dossier_revision)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_draft_create(p_dossier_id uuid, p_expected_revision bigint) OWNER TO postgres;

