--
-- Name: technical_configuration_baseline_groups_reorder(uuid, uuid[], bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_groups_reorder(p_baseline_version_id uuid, p_group_ids uuid[], p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_existing_count BIGINT;
  v_input_count BIGINT;
  v_distinct_count BIGINT;
  v_matching_count BIGINT;
  v_revision BIGINT;
BEGIN
  v_user_id := public._technical_configuration_require_editable_baseline_version(
    p_baseline_version_id,
    p_expected_revision
  );
  IF p_group_ids IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT COUNT(*) INTO v_existing_count
  FROM public.technical_configuration_baseline_groups
  WHERE baseline_version_id = p_baseline_version_id;

  SELECT COUNT(*), COUNT(DISTINCT item_id)
  INTO v_input_count, v_distinct_count
  FROM unnest(p_group_ids) AS input(item_id);

  SELECT COUNT(*) INTO v_matching_count
  FROM public.technical_configuration_baseline_groups
  WHERE baseline_version_id = p_baseline_version_id
    AND id = ANY(p_group_ids);

  IF cardinality(p_group_ids) <> v_existing_count
     OR v_input_count <> v_distinct_count
     OR v_matching_count <> v_existing_count THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SET CONSTRAINTS technical_configuration_baseline_groups_version_sort_key DEFERRED;
  UPDATE public.technical_configuration_baseline_groups g
  SET sort_order = input.new_order::INTEGER,
      updated_at = now(),
      updated_by = v_user_id
  FROM unnest(p_group_ids) WITH ORDINALITY AS input(id, new_order)
  WHERE g.id = input.id;

  UPDATE public.technical_configuration_baseline_versions
  SET revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = p_baseline_version_id
  RETURNING revision INTO v_revision;

  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_baseline_snapshot(p_baseline_version_id)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_groups_reorder(p_baseline_version_id uuid, p_group_ids uuid[], p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_hierarchy_criteria_reorder(uuid, uuid, uuid[], bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_hierarchy_criteria_reorder(p_group_id uuid, p_subgroup_id uuid, p_criterion_ids uuid[], p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT; v_version_id UUID; v_revision BIGINT;
  v_existing_count BIGINT; v_input_count BIGINT;
  v_distinct_count BIGINT; v_matching_count BIGINT;
BEGIN
  SELECT context.user_id, context.version_id
  INTO v_user_id, v_version_id
  FROM public._technical_configuration_baseline_hierarchy_context(
    p_group_id, p_subgroup_id, p_expected_revision
  ) context;
  IF p_criterion_ids IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT COUNT(*) INTO v_existing_count
  FROM public.technical_configuration_baseline_criteria
  WHERE group_id = p_group_id
    AND subgroup_id IS NOT DISTINCT FROM p_subgroup_id;
  SELECT COUNT(*), COUNT(DISTINCT item_id)
  INTO v_input_count, v_distinct_count
  FROM unnest(p_criterion_ids) input(item_id);
  SELECT COUNT(*) INTO v_matching_count
  FROM public.technical_configuration_baseline_criteria
  WHERE group_id = p_group_id
    AND subgroup_id IS NOT DISTINCT FROM p_subgroup_id
    AND id = ANY(p_criterion_ids);
  IF cardinality(p_criterion_ids) <> v_existing_count
     OR v_input_count <> v_distinct_count
     OR v_matching_count <> v_existing_count THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SET CONSTRAINTS technical_configuration_baseline_criteria_group_sort_key DEFERRED;
  UPDATE public.technical_configuration_baseline_criteria c
  SET sort_order = input.new_order::INTEGER,
      updated_at = now(),
      updated_by = v_user_id
  FROM unnest(p_criterion_ids) WITH ORDINALITY input(id, new_order)
  WHERE c.id = input.id;
  PERFORM public._technical_configuration_baseline_normalize_group(
    p_group_id, v_user_id
  );
  v_revision := public._technical_configuration_baseline_bump_revision(
    v_version_id, v_user_id
  );
  RETURN jsonb_build_object(
    'data', public._technical_configuration_baseline_snapshot(v_version_id)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_hierarchy_criteria_reorder(p_group_id uuid, p_subgroup_id uuid, p_criterion_ids uuid[], p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_hierarchy_criterion_create(uuid, uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_hierarchy_criterion_create(p_group_id uuid, p_subgroup_id uuid, p_title text, p_requirement_text text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT; v_version_id UUID; v_criterion_id UUID;
  v_criterion_number BIGINT; v_criterion_code TEXT;
  v_sort_order INTEGER; v_revision BIGINT;
BEGIN
  SELECT context.user_id, context.version_id
  INTO v_user_id, v_version_id
  FROM public._technical_configuration_baseline_hierarchy_context(
    p_group_id, p_subgroup_id, p_expected_revision
  ) context;
  IF p_requirement_text IS NULL OR btrim(p_requirement_text) = '' THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT next_criterion_number INTO v_criterion_number
  FROM public.technical_configuration_baseline_versions
  WHERE id = v_version_id;
  v_criterion_code := 'TC-' || lpad(
    v_criterion_number::TEXT,
    GREATEST(4, length(v_criterion_number::TEXT)),
    '0'
  );
  SELECT COALESCE(MAX(sort_order), 0) + 1 INTO v_sort_order
  FROM public.technical_configuration_baseline_criteria
  WHERE group_id = p_group_id;

  INSERT INTO public.technical_configuration_baseline_criteria (
    baseline_version_id, group_id, subgroup_id, criterion_code, title,
    requirement_text, sort_order, created_by, updated_by
  ) VALUES (
    v_version_id, p_group_id, p_subgroup_id, v_criterion_code,
    NULLIF(btrim(p_title), ''), btrim(p_requirement_text),
    v_sort_order, v_user_id, v_user_id
  ) RETURNING id INTO v_criterion_id;

  PERFORM public._technical_configuration_baseline_normalize_group(
    p_group_id, v_user_id
  );
  UPDATE public.technical_configuration_baseline_versions
  SET next_criterion_number = next_criterion_number + 1,
      revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = v_version_id
  RETURNING revision INTO v_revision;
  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_baseline_hierarchy_criterion_payload(
      v_criterion_id, v_revision
    )
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_hierarchy_criterion_create(p_group_id uuid, p_subgroup_id uuid, p_title text, p_requirement_text text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_hierarchy_criterion_move(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_hierarchy_criterion_move(p_criterion_id uuid, p_target_group_id uuid, p_target_subgroup_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT; v_target_version_id UUID; v_source_version_id UUID;
  v_source_group_id UUID; v_sort_order INTEGER; v_revision BIGINT;
BEGIN
  SELECT context.user_id, context.version_id
  INTO v_user_id, v_target_version_id
  FROM public._technical_configuration_baseline_hierarchy_context(
    p_target_group_id, p_target_subgroup_id, p_expected_revision
  ) context;

  SELECT c.baseline_version_id, c.group_id
  INTO v_source_version_id, v_source_group_id
  FROM public.technical_configuration_baseline_criteria c
  WHERE c.id = p_criterion_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  IF v_source_version_id <> v_target_version_id THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT COALESCE(MAX(sort_order), 0) + 1 INTO v_sort_order
  FROM public.technical_configuration_baseline_criteria
  WHERE group_id = p_target_group_id;
  SET CONSTRAINTS technical_configuration_baseline_criteria_group_sort_key DEFERRED;
  UPDATE public.technical_configuration_baseline_criteria
  SET group_id = p_target_group_id,
      subgroup_id = p_target_subgroup_id,
      sort_order = v_sort_order,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = p_criterion_id;

  PERFORM public._technical_configuration_baseline_normalize_group(
    v_source_group_id, v_user_id
  );
  IF p_target_group_id <> v_source_group_id THEN
    PERFORM public._technical_configuration_baseline_normalize_group(
      p_target_group_id, v_user_id
    );
  END IF;
  v_revision := public._technical_configuration_baseline_bump_revision(
    v_target_version_id, v_user_id
  );
  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_baseline_hierarchy_criterion_payload(
      p_criterion_id, v_revision
    )
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_hierarchy_criterion_move(p_criterion_id uuid, p_target_group_id uuid, p_target_subgroup_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_import_apply(uuid, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_import_apply(p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_validation JSONB;
  v_errors JSONB;
  v_new_criterion_count BIGINT;
  v_existing_group_ids UUID[] := ARRAY[]::UUID[];
  v_target_group_ids UUID[] := ARRAY[]::UUID[];
  v_kept_criterion_codes TEXT[] := ARRAY[]::TEXT[];
  v_group_map JSONB := '{}'::JSONB;
BEGIN
  v_user_id := public._technical_configuration_require_editable_baseline_version(
    p_baseline_version_id,
    p_expected_revision
  );
  v_validation := public._technical_configuration_baseline_import_validate(
    p_baseline_version_id,
    p_template_metadata,
    p_rows,
    p_expected_revision
  );
  v_errors := v_validation->'row_errors';
  IF jsonb_array_length(v_errors) > 0 THEN
    RAISE EXCEPTION 'validation_error'
      USING ERRCODE = 'PT422', DETAIL = v_errors::TEXT;
  END IF;

  SET CONSTRAINTS
    technical_configuration_baseline_groups_version_sort_key,
    technical_configuration_baseline_criteria_group_sort_key
    DEFERRED;

  SELECT COALESCE(array_agg(g.id ORDER BY g.sort_order, g.id), ARRAY[]::UUID[])
  INTO v_existing_group_ids
  FROM public.technical_configuration_baseline_groups g
  WHERE g.baseline_version_id = p_baseline_version_id;

  WITH incoming_groups AS (
    SELECT
      (value->>'group_order')::INTEGER AS group_order,
      value->>'group_name' AS group_name
    FROM jsonb_array_elements(v_validation->'rows')
    WHERE value->>'row_type' = 'GROUP'
  ),
  resolved_groups AS (
    SELECT
      i.group_order,
      COALESCE(v_existing_group_ids[i.group_order], gen_random_uuid()) AS group_id
    FROM incoming_groups i
  )
  SELECT
    COALESCE(
      jsonb_object_agg(r.group_order::TEXT, r.group_id ORDER BY r.group_order),
      '{}'::JSONB
    ),
    COALESCE(array_agg(r.group_id ORDER BY r.group_order), ARRAY[]::UUID[])
  INTO v_group_map, v_target_group_ids
  FROM resolved_groups r;

  WITH incoming_groups AS (
    SELECT
      (value->>'group_order')::INTEGER AS group_order,
      value->>'group_name' AS group_name
    FROM jsonb_array_elements(v_validation->'rows')
    WHERE value->>'row_type' = 'GROUP'
  )
  UPDATE public.technical_configuration_baseline_groups g
  SET name = i.group_name,
      sort_order = i.group_order,
      updated_at = now(),
      updated_by = v_user_id
  FROM incoming_groups i
  WHERE g.id = (v_group_map->>i.group_order::TEXT)::UUID;

  WITH incoming_groups AS (
    SELECT
      (value->>'group_order')::INTEGER AS group_order,
      value->>'group_name' AS group_name
    FROM jsonb_array_elements(v_validation->'rows')
    WHERE value->>'row_type' = 'GROUP'
  )
  INSERT INTO public.technical_configuration_baseline_groups (
    id,
    baseline_version_id,
    name,
    sort_order,
    created_by,
    updated_by
  )
  SELECT
    (v_group_map->>i.group_order::TEXT)::UUID,
    p_baseline_version_id,
    i.group_name,
    i.group_order,
    v_user_id,
    v_user_id
  FROM incoming_groups i
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.technical_configuration_baseline_groups g
    WHERE g.id = (v_group_map->>i.group_order::TEXT)::UUID
  );

  WITH incoming_criteria AS (
    SELECT
      value->>'criterion_code' AS criterion_code,
      (value->>'group_order')::INTEGER AS group_order,
      (value->>'criterion_order')::INTEGER AS criterion_order,
      NULLIF(value->>'criterion_title', '') AS criterion_title,
      value->>'requirement_text' AS requirement_text
    FROM jsonb_array_elements(v_validation->'rows')
    WHERE value->>'row_type' = 'CRITERION'
  )
  UPDATE public.technical_configuration_baseline_criteria c
  SET group_id = (v_group_map->>i.group_order::TEXT)::UUID,
      title = i.criterion_title,
      requirement_text = i.requirement_text,
      sort_order = i.criterion_order,
      updated_at = now(),
      updated_by = v_user_id
  FROM incoming_criteria i
  WHERE c.baseline_version_id = p_baseline_version_id
    AND c.criterion_code = i.criterion_code;

  WITH incoming_criteria AS (
    SELECT
      value->>'criterion_code' AS criterion_code,
      (value->>'group_order')::INTEGER AS group_order,
      (value->>'criterion_order')::INTEGER AS criterion_order,
      NULLIF(value->>'criterion_title', '') AS criterion_title,
      value->>'requirement_text' AS requirement_text
    FROM jsonb_array_elements(v_validation->'rows')
    WHERE value->>'row_type' = 'CRITERION'
  )
  INSERT INTO public.technical_configuration_baseline_criteria (
    baseline_version_id,
    group_id,
    criterion_code,
    title,
    requirement_text,
    sort_order,
    created_by,
    updated_by
  )
  SELECT
    p_baseline_version_id,
    (v_group_map->>i.group_order::TEXT)::UUID,
    i.criterion_code,
    i.criterion_title,
    i.requirement_text,
    i.criterion_order,
    v_user_id,
    v_user_id
  FROM incoming_criteria i
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.technical_configuration_baseline_criteria c
    WHERE c.baseline_version_id = p_baseline_version_id
      AND c.criterion_code = i.criterion_code
  );

  SELECT COALESCE(array_agg(value->>'criterion_code'), ARRAY[]::TEXT[])
  INTO v_kept_criterion_codes
  FROM jsonb_array_elements(v_validation->'rows')
  WHERE value->>'row_type' = 'CRITERION';

  DELETE FROM public.technical_configuration_baseline_criteria c
  WHERE c.baseline_version_id = p_baseline_version_id
    AND NOT (c.criterion_code = ANY(v_kept_criterion_codes));

  DELETE FROM public.technical_configuration_baseline_groups g
  WHERE g.baseline_version_id = p_baseline_version_id
    AND NOT (g.id = ANY(v_target_group_ids));

  v_new_criterion_count := (v_validation->>'new_criterion_count')::BIGINT;
  UPDATE public.technical_configuration_baseline_versions
  SET next_criterion_number = next_criterion_number + v_new_criterion_count,
      revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = p_baseline_version_id;

  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_baseline_snapshot(p_baseline_version_id)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_import_apply(p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) OWNER TO postgres;

