--
-- Name: technical_configuration_baseline_import_preview(uuid, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_import_preview(p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_validation JSONB;
BEGIN
  PERFORM public._technical_configuration_require_editable_baseline_version(
    p_baseline_version_id,
    p_expected_revision
  );
  v_validation := public._technical_configuration_baseline_import_validate(
    p_baseline_version_id,
    p_template_metadata,
    p_rows,
    p_expected_revision
  );

  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'metadata', v_validation->'metadata',
      'rows', v_validation->'rows'
    ),
    'errors', v_validation->'row_errors'
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_import_preview(p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) OWNER TO postgres;

