--
-- Name: technical_configuration_baseline_lock(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_lock(p_baseline_version_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_group_count BIGINT;
  v_criterion_count BIGINT;
  v_distinct_code_count BIGINT;
BEGIN
  v_user_id := public._technical_configuration_require_editable_baseline_version(
    p_baseline_version_id,
    p_expected_revision
  );
  SELECT COUNT(*)
  INTO v_group_count
  FROM public.technical_configuration_baseline_groups g
  WHERE g.baseline_version_id = p_baseline_version_id;
  SELECT
    COUNT(*),
    COUNT(DISTINCT c.criterion_code)
  INTO
    v_criterion_count,
    v_distinct_code_count
  FROM public.technical_configuration_baseline_criteria c
  WHERE c.baseline_version_id = p_baseline_version_id
    AND btrim(c.requirement_text) <> '';
  -- P5 must extend this function when persisted import-error state exists.
  IF v_group_count < 1
     OR v_criterion_count < 1
     OR v_distinct_code_count <> v_criterion_count THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  UPDATE public.technical_configuration_baseline_versions
  SET status = 'locked',
      locked_at = now(),
      locked_by = v_user_id,
      revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = p_baseline_version_id;
  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_baseline_snapshot(p_baseline_version_id)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_lock(p_baseline_version_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_subgroup_create(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_subgroup_create(p_group_id uuid, p_name text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT; v_version_id UUID; v_subgroup_id UUID;
  v_sort_order INTEGER; v_revision BIGINT;
BEGIN
  SELECT context.user_id, context.version_id
  INTO v_user_id, v_version_id
  FROM public._technical_configuration_baseline_hierarchy_context(
    p_group_id, NULL, p_expected_revision
  ) context;
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT COALESCE(MAX(sort_order), 0) + 1 INTO v_sort_order
  FROM public.technical_configuration_baseline_subgroups
  WHERE group_id = p_group_id;
  INSERT INTO public.technical_configuration_baseline_subgroups (
    baseline_version_id, group_id, name, sort_order, created_by, updated_by
  ) VALUES (
    v_version_id, p_group_id, btrim(p_name), v_sort_order, v_user_id, v_user_id
  ) RETURNING id INTO v_subgroup_id;

  PERFORM public._technical_configuration_baseline_normalize_group(
    p_group_id, v_user_id
  );
  v_revision := public._technical_configuration_baseline_bump_revision(
    v_version_id, v_user_id
  );
  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_baseline_subgroup_payload(
      v_subgroup_id, v_revision
    )
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_subgroup_create(p_group_id uuid, p_name text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_subgroup_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_subgroup_delete(p_subgroup_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_group_id UUID; v_user_id BIGINT; v_version_id UUID; v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  SELECT s.group_id INTO v_group_id
  FROM public.technical_configuration_baseline_subgroups s
  WHERE s.id = p_subgroup_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT context.user_id, context.version_id
  INTO v_user_id, v_version_id
  FROM public._technical_configuration_baseline_hierarchy_context(
    v_group_id, p_subgroup_id, p_expected_revision
  ) context;
  IF EXISTS (
    SELECT 1
    FROM public.technical_configuration_baseline_criteria
    WHERE subgroup_id = p_subgroup_id
  ) THEN
    RAISE EXCEPTION 'subgroup_not_empty' USING ERRCODE = 'PT409';
  END IF;

  DELETE FROM public.technical_configuration_baseline_subgroups
  WHERE id = p_subgroup_id;
  PERFORM public._technical_configuration_baseline_normalize_group(
    v_group_id, v_user_id
  );
  v_revision := public._technical_configuration_baseline_bump_revision(
    v_version_id, v_user_id
  );
  RETURN jsonb_build_object(
    'data', jsonb_build_object('id', p_subgroup_id, 'revision', v_revision)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_subgroup_delete(p_subgroup_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_subgroup_update(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_subgroup_update(p_subgroup_id uuid, p_name text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_group_id UUID; v_user_id BIGINT; v_version_id UUID; v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  SELECT s.group_id INTO v_group_id
  FROM public.technical_configuration_baseline_subgroups s
  WHERE s.id = p_subgroup_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT context.user_id, context.version_id
  INTO v_user_id, v_version_id
  FROM public._technical_configuration_baseline_hierarchy_context(
    v_group_id, p_subgroup_id, p_expected_revision
  ) context;
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  UPDATE public.technical_configuration_baseline_subgroups
  SET name = btrim(p_name), updated_at = now(), updated_by = v_user_id
  WHERE id = p_subgroup_id;
  PERFORM public._technical_configuration_baseline_normalize_group(
    v_group_id, v_user_id
  );
  v_revision := public._technical_configuration_baseline_bump_revision(
    v_version_id, v_user_id
  );
  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_baseline_subgroup_payload(
      p_subgroup_id, v_revision
    )
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_subgroup_update(p_subgroup_id uuid, p_name text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_subgroups_reorder(uuid, uuid[], bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_subgroups_reorder(p_group_id uuid, p_subgroup_ids uuid[], p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT; v_version_id UUID; v_revision BIGINT;
  v_existing_count BIGINT; v_input_count BIGINT;
  v_distinct_count BIGINT; v_matching_count BIGINT;
BEGIN
  SELECT context.user_id, context.version_id
  INTO v_user_id, v_version_id
  FROM public._technical_configuration_baseline_hierarchy_context(
    p_group_id, NULL, p_expected_revision
  ) context;
  IF p_subgroup_ids IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT COUNT(*) INTO v_existing_count
  FROM public.technical_configuration_baseline_subgroups
  WHERE group_id = p_group_id;
  SELECT COUNT(*), COUNT(DISTINCT item_id)
  INTO v_input_count, v_distinct_count
  FROM unnest(p_subgroup_ids) input(item_id);
  SELECT COUNT(*) INTO v_matching_count
  FROM public.technical_configuration_baseline_subgroups
  WHERE group_id = p_group_id AND id = ANY(p_subgroup_ids);
  IF cardinality(p_subgroup_ids) <> v_existing_count
     OR v_input_count <> v_distinct_count
     OR v_matching_count <> v_existing_count THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SET CONSTRAINTS tc_baseline_subgroups_group_sort_key DEFERRED;
  UPDATE public.technical_configuration_baseline_subgroups s
  SET sort_order = input.new_order::INTEGER,
      updated_at = now(),
      updated_by = v_user_id
  FROM unnest(p_subgroup_ids) WITH ORDINALITY input(id, new_order)
  WHERE s.id = input.id;
  PERFORM public._technical_configuration_baseline_normalize_group(
    p_group_id, v_user_id
  );
  v_revision := public._technical_configuration_baseline_bump_revision(
    v_version_id, v_user_id
  );
  RETURN jsonb_build_object(
    'data', public._technical_configuration_baseline_snapshot(v_version_id)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_subgroups_reorder(p_group_id uuid, p_subgroup_ids uuid[], p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_baseline_versions_list(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_baseline_versions_list(p_dossier_id uuid, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  IF p_page IS NULL
     OR p_page < 1
     OR p_page_size IS NULL
     OR NOT (p_page_size BETWEEN 1 AND 100) THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  PERFORM 1
  FROM public.technical_configuration_dossiers d
  WHERE d.id = p_dossier_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  WITH paged_versions AS (
    SELECT
      v.id,
      v.dossier_id,
      v.version_number,
      v.status,
      v.source_baseline_version_id,
      source_version.version_number AS source_version_number,
      v.next_criterion_number,
      v.revision,
      v.locked_at,
      v.locked_by,
      v.created_at,
      v.created_by,
      v.updated_at,
      v.updated_by
    FROM public.technical_configuration_baseline_versions v
    LEFT JOIN public.technical_configuration_baseline_versions source_version
      ON source_version.id = v.source_baseline_version_id
    WHERE v.dossier_id = p_dossier_id
    ORDER BY v.version_number DESC, v.id
    LIMIT p_page_size
    OFFSET (p_page - 1)::BIGINT * p_page_size
  ),
  direct_criteria_by_group AS (
    SELECT
      c.group_id,
      jsonb_agg(
        jsonb_build_object(
          'id', c.id, 'baseline_version_id', c.baseline_version_id,
          'group_id', c.group_id, 'subgroup_id', c.subgroup_id,
          'criterion_code', c.criterion_code, 'title', c.title,
          'requirement_text', c.requirement_text, 'sort_order', c.sort_order,
          'source_criterion_id', c.source_criterion_id, 'created_at', c.created_at,
          'created_by', c.created_by, 'updated_at', c.updated_at, 'updated_by', c.updated_by
        )
        ORDER BY c.sort_order, c.id
      ) AS criteria
    FROM public.technical_configuration_baseline_criteria c
    INNER JOIN paged_versions pv ON pv.id = c.baseline_version_id
    WHERE c.subgroup_id IS NULL
    GROUP BY c.group_id
  ),
  criteria_by_subgroup AS (
    SELECT
      c.subgroup_id,
      jsonb_agg(
        jsonb_build_object(
          'id', c.id, 'baseline_version_id', c.baseline_version_id,
          'group_id', c.group_id, 'subgroup_id', c.subgroup_id,
          'criterion_code', c.criterion_code, 'title', c.title,
          'requirement_text', c.requirement_text, 'sort_order', c.sort_order,
          'source_criterion_id', c.source_criterion_id, 'created_at', c.created_at,
          'created_by', c.created_by, 'updated_at', c.updated_at, 'updated_by', c.updated_by
        )
        ORDER BY c.sort_order, c.id
      ) AS criteria
    FROM public.technical_configuration_baseline_criteria c
    INNER JOIN paged_versions pv ON pv.id = c.baseline_version_id
    WHERE c.subgroup_id IS NOT NULL
    GROUP BY c.subgroup_id
  ),
  subgroups_by_group AS (
    SELECT
      sg.group_id,
      jsonb_agg(
        jsonb_build_object(
          'id', sg.id, 'baseline_version_id', sg.baseline_version_id,
          'group_id', sg.group_id, 'name', sg.name, 'sort_order', sg.sort_order,
          'created_at', sg.created_at, 'created_by', sg.created_by,
          'updated_at', sg.updated_at, 'updated_by', sg.updated_by,
          'criteria', COALESCE(cbs.criteria, '[]'::JSONB)
        )
        ORDER BY sg.sort_order, sg.id
      ) AS subgroups
    FROM public.technical_configuration_baseline_subgroups sg
    INNER JOIN paged_versions pv ON pv.id = sg.baseline_version_id
    LEFT JOIN criteria_by_subgroup cbs ON cbs.subgroup_id = sg.id
    GROUP BY sg.group_id
  ),
  groups_by_version AS (
    SELECT
      g.baseline_version_id,
      jsonb_agg(
        jsonb_build_object(
          'id', g.id, 'baseline_version_id', g.baseline_version_id,
          'name', g.name, 'sort_order', g.sort_order,
          'created_at', g.created_at, 'created_by', g.created_by,
          'updated_at', g.updated_at, 'updated_by', g.updated_by,
          'criteria', COALESCE(dcbg.criteria, '[]'::JSONB),
          'subgroups', COALESCE(sbg.subgroups, '[]'::JSONB)
        )
        ORDER BY g.sort_order, g.id
      ) AS groups
    FROM public.technical_configuration_baseline_groups g
    INNER JOIN paged_versions pv ON pv.id = g.baseline_version_id
    LEFT JOIN direct_criteria_by_group dcbg ON dcbg.group_id = g.id
    LEFT JOIN subgroups_by_group sbg ON sbg.group_id = g.id
    GROUP BY g.baseline_version_id
  )
  SELECT jsonb_build_object(
    'data',
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', pv.id, 'dossier_id', pv.dossier_id,
            'version_number', pv.version_number, 'status', pv.status,
            'source_baseline_version_id', pv.source_baseline_version_id,
            'source_version_number', pv.source_version_number,
            'next_criterion_number', pv.next_criterion_number, 'revision', pv.revision,
            'locked_at', pv.locked_at, 'locked_by', pv.locked_by,
            'created_at', pv.created_at, 'created_by', pv.created_by,
            'updated_at', pv.updated_at, 'updated_by', pv.updated_by,
            'groups', COALESCE(gbv.groups, '[]'::JSONB)
          )
          ORDER BY pv.version_number DESC, pv.id
        )
        FROM paged_versions pv
        LEFT JOIN groups_by_version gbv ON gbv.baseline_version_id = pv.id
      ),
      '[]'::JSONB
    ),
    'total',
    (
      SELECT count(*)
      FROM public.technical_configuration_baseline_versions v
      WHERE v.dossier_id = p_dossier_id
    ),
    'page', p_page,
    'page_size', p_page_size
  )
  INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.technical_configuration_baseline_versions_list(p_dossier_id uuid, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_comparison_get(uuid, uuid[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_comparison_get(p_baseline_version_id uuid, p_option_ids uuid[], p_page integer, p_page_size integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_dossier_id UUID;
  v_option_count BIGINT;
  v_distinct_option_count BIGINT;
  v_valid_option_count BIGINT;
  v_total BIGINT;
  v_data JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  v_option_count := COALESCE(array_length(p_option_ids, 1), 0);
  IF p_baseline_version_id IS NULL
     OR p_option_ids IS NULL
     OR array_ndims(p_option_ids) IS DISTINCT FROM 1
     OR v_option_count < 1
     OR v_option_count > 8
     OR array_position(p_option_ids, NULL) IS NOT NULL
     OR p_page IS NULL OR p_page < 1
     OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT
    COUNT(*),
    COUNT(DISTINCT requested.option_id)
  INTO v_option_count, v_distinct_option_count
  FROM unnest(p_option_ids) AS requested(option_id);

  IF v_option_count IS DISTINCT FROM v_distinct_option_count THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT v.dossier_id
  INTO v_dossier_id
  FROM public.technical_configuration_baseline_versions v
  WHERE v.id = p_baseline_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT COUNT(*)
  INTO v_valid_option_count
  FROM unnest(p_option_ids) AS requested(option_id)
  JOIN public.technical_configuration_options o
    ON o.id = requested.option_id
   AND o.dossier_id = v_dossier_id;

  IF v_valid_option_count IS DISTINCT FROM v_option_count THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT COUNT(*)
  INTO v_total
  FROM public.technical_configuration_baseline_criteria c
  WHERE c.baseline_version_id = p_baseline_version_id;

  WITH selected_options AS (
    SELECT
      requested.ordinal,
      o.id AS option_id,
      o.supplier_id,
      s.name AS supplier_name,
      o.model,
      o.manufacturer,
      o.option_name,
      s.name || ' · ' || COALESCE(o.model, o.option_name) AS display_label
    FROM unnest(p_option_ids) WITH ORDINALITY AS requested(option_id, ordinal)
    JOIN public.technical_configuration_options o
      ON o.id = requested.option_id
     AND o.dossier_id = v_dossier_id
    JOIN public.technical_configuration_suppliers s
      ON s.id = o.supplier_id
     AND s.dossier_id = o.dossier_id
  ),
  paged_criteria AS (
    SELECT
      g.id AS group_id,
      g.name AS group_name,
      g.sort_order AS group_sort_order,
      c.id AS criterion_id,
      c.criterion_code,
      c.title,
      c.requirement_text,
      c.sort_order AS criterion_sort_order,
      c.baseline_version_id
    FROM public.technical_configuration_baseline_criteria c
    JOIN public.technical_configuration_baseline_groups g
      ON g.id = c.group_id
     AND g.baseline_version_id = c.baseline_version_id
    WHERE c.baseline_version_id = p_baseline_version_id
    ORDER BY g.sort_order, c.sort_order, c.id
    LIMIT p_page_size
    OFFSET ((p_page::BIGINT - 1) * p_page_size::BIGINT)
  ),
  baseline_evidence AS (
    SELECT
      paged.criterion_id,
      COUNT(DISTINCT citation.baseline_document_id) AS document_total,
      COUNT(citation.id) AS citation_total
    FROM paged_criteria paged
    LEFT JOIN public.technical_configuration_baseline_citations citation
      ON citation.criterion_id = paged.criterion_id
     AND citation.baseline_version_id = paged.baseline_version_id
    GROUP BY paged.criterion_id
  ),
  option_evidence AS (
    SELECT
      selected.option_id,
      paged.criterion_id,
      COUNT(DISTINCT citation.option_document_id) AS document_total,
      COUNT(citation.id) AS citation_total
    FROM selected_options selected
    CROSS JOIN paged_criteria paged
    LEFT JOIN public.technical_configuration_comparison_sets comparison_set
      ON comparison_set.option_id = selected.option_id
     AND comparison_set.baseline_version_id = paged.baseline_version_id
    LEFT JOIN public.technical_configuration_option_citations citation
      ON citation.comparison_set_id = comparison_set.id
     AND citation.option_id = selected.option_id
     AND citation.baseline_version_id = paged.baseline_version_id
     AND citation.criterion_id = paged.criterion_id
    GROUP BY selected.option_id, paged.criterion_id
  ),
  option_values AS (
    SELECT
      paged.criterion_id,
      selected.ordinal,
      selected.option_id,
      comparison_set.id AS comparison_set_id,
      CASE
        WHEN response.id IS NULL THEN NULL
        ELSE jsonb_build_object(
          'id', response.id,
          'response_text', response.response_text,
          'supplementary_information', response.supplementary_information
        )
      END AS response,
      jsonb_build_object(
        'document_count', evidence.document_total,
        'citation_count', evidence.citation_total,
        'has_evidence', evidence.citation_total > 0
      ) AS evidence
    FROM paged_criteria paged
    CROSS JOIN selected_options selected
    LEFT JOIN public.technical_configuration_comparison_sets comparison_set
      ON comparison_set.option_id = selected.option_id
     AND comparison_set.baseline_version_id = paged.baseline_version_id
    LEFT JOIN public.technical_configuration_option_responses response
      ON response.comparison_set_id = comparison_set.id
     AND response.baseline_version_id = paged.baseline_version_id
     AND response.criterion_id = paged.criterion_id
    JOIN option_evidence evidence
      ON evidence.option_id = selected.option_id
     AND evidence.criterion_id = paged.criterion_id
  ),
  option_value_arrays AS (
    SELECT
      values.criterion_id,
      jsonb_agg(
        jsonb_build_object(
          'option_id', values.option_id,
          'comparison_set_id', values.comparison_set_id,
          'response', values.response,
          'evidence', values.evidence
        )
        ORDER BY values.ordinal
      ) AS option_values
    FROM option_values values
    GROUP BY values.criterion_id
  ),
  option_array AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', selected.option_id,
        'supplier_id', selected.supplier_id,
        'supplier_name', selected.supplier_name,
        'model', selected.model,
        'manufacturer', selected.manufacturer,
        'option_name', selected.option_name,
        'display_label', selected.display_label
      )
      ORDER BY selected.ordinal
    ) AS options
    FROM selected_options selected
  ),
  criteria_array AS (
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'group', jsonb_build_object(
            'id', paged.group_id,
            'name', paged.group_name,
            'sort_order', paged.group_sort_order
          ),
          'criterion', jsonb_build_object(
            'id', paged.criterion_id,
            'criterion_code', paged.criterion_code,
            'title', paged.title,
            'requirement_text', paged.requirement_text,
            'sort_order', paged.criterion_sort_order
          ),
          'baseline_evidence', jsonb_build_object(
            'document_count', evidence.document_total,
            'citation_count', evidence.citation_total,
            'has_evidence', evidence.citation_total > 0
          ),
          'option_values', values.option_values
        )
        ORDER BY paged.group_sort_order, paged.criterion_sort_order, paged.criterion_id
      ),
      '[]'::JSONB
    ) AS criteria
    FROM paged_criteria paged
    JOIN baseline_evidence evidence
      ON evidence.criterion_id = paged.criterion_id
    JOIN option_value_arrays values
      ON values.criterion_id = paged.criterion_id
  )
  SELECT jsonb_build_object(
    'dossier', jsonb_build_object(
      'id', d.id,
      'device_type_name', d.device_type_name,
      'name', d.name,
      'revision', d.revision,
      'archived_at', d.archived_at
    ),
    'baseline_version', jsonb_build_object(
      'id', v.id,
      'dossier_id', v.dossier_id,
      'version_number', v.version_number,
      'status', v.status,
      'revision', v.revision
    ),
    'options', option_array.options,
    'criteria', criteria_array.criteria
  )
  INTO v_data
  FROM public.technical_configuration_dossiers d
  JOIN public.technical_configuration_baseline_versions v
    ON v.dossier_id = d.id
   AND v.id = p_baseline_version_id
  CROSS JOIN option_array
  CROSS JOIN criteria_array
  WHERE d.id = v_dossier_id;

  RETURN jsonb_build_object(
    'data', v_data,
    'total', v_total,
    'page', p_page,
    'page_size', p_page_size
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_comparison_get(p_baseline_version_id uuid, p_option_ids uuid[], p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_comparison_set_get(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_comparison_set_get(p_option_id uuid, p_baseline_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_option_dossier_id UUID;
  v_version_dossier_id UUID;
  v_data JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT o.dossier_id
  INTO v_option_dossier_id
  FROM public.technical_configuration_options o
  WHERE o.id = p_option_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT v.dossier_id
  INTO v_version_dossier_id
  FROM public.technical_configuration_baseline_versions v
  WHERE v.id = p_baseline_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF v_option_dossier_id IS DISTINCT FROM v_version_dossier_id THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT jsonb_build_object(
    'id', cs.id,
    'dossier_id', cs.dossier_id,
    'option_id', cs.option_id,
    'baseline_version_id', cs.baseline_version_id,
    'created_at', cs.created_at,
    'created_by', cs.created_by,
    'updated_at', cs.updated_at,
    'updated_by', cs.updated_by,
    'revision', d.revision,
    'responses', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', r.id,
            'comparison_set_id', r.comparison_set_id,
            'baseline_version_id', r.baseline_version_id,
            'criterion_id', r.criterion_id,
            'response_text', r.response_text,
            'supplementary_information', r.supplementary_information,
            'created_at', r.created_at,
            'created_by', r.created_by,
            'updated_at', r.updated_at,
            'updated_by', r.updated_by,
            'revision', d.revision
          )
          ORDER BY bg.sort_order, bc.sort_order, bc.id
        )
        FROM public.technical_configuration_option_responses r
        JOIN public.technical_configuration_baseline_criteria bc
          ON bc.id = r.criterion_id
         AND bc.baseline_version_id = r.baseline_version_id
        JOIN public.technical_configuration_baseline_groups bg
          ON bg.id = bc.group_id
         AND bg.baseline_version_id = bc.baseline_version_id
        WHERE r.comparison_set_id = cs.id
      ),
      '[]'::JSONB
    )
  )
  INTO v_data
  FROM public.technical_configuration_comparison_sets cs
  JOIN public.technical_configuration_dossiers d
    ON d.id = cs.dossier_id
  WHERE cs.option_id = p_option_id
    AND cs.baseline_version_id = p_baseline_version_id;

  IF v_data IS NULL THEN
    RETURN jsonb_build_object('data', NULL);
  END IF;

  RETURN jsonb_build_object('data', v_data);
END;
$$;


ALTER FUNCTION public.technical_configuration_comparison_set_get(p_option_id uuid, p_baseline_version_id uuid) OWNER TO postgres;

--
-- Name: technical_configuration_comparison_set_get_or_create(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_comparison_set_get_or_create(p_option_id uuid, p_baseline_version_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_option_dossier_id UUID;
  v_version_dossier_id UUID;
  v_comparison_set_id UUID;
  v_revision BIGINT;
  v_data JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT o.dossier_id
  INTO v_option_dossier_id
  FROM public.technical_configuration_options o
  WHERE o.id = p_option_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT v.dossier_id
  INTO v_version_dossier_id
  FROM public.technical_configuration_baseline_versions v
  WHERE v.id = p_baseline_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF v_option_dossier_id IS DISTINCT FROM v_version_dossier_id THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT cs.id
  INTO v_comparison_set_id
  FROM public.technical_configuration_comparison_sets cs
  WHERE cs.option_id = p_option_id
    AND cs.baseline_version_id = p_baseline_version_id;

  IF v_comparison_set_id IS NOT NULL THEN
    SELECT d.revision
    INTO v_revision
    FROM public.technical_configuration_dossiers d
    WHERE d.id = v_option_dossier_id
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
    END IF;

    SELECT cs.id
    INTO v_comparison_set_id
    FROM public.technical_configuration_comparison_sets cs
    WHERE cs.id = v_comparison_set_id
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
    END IF;
  ELSE
    v_user_id := public._technical_configuration_require_editable_dossier(
      v_option_dossier_id,
      p_expected_revision
    );

    SELECT cs.id
    INTO v_comparison_set_id
    FROM public.technical_configuration_comparison_sets cs
    WHERE cs.option_id = p_option_id
      AND cs.baseline_version_id = p_baseline_version_id;

    IF v_comparison_set_id IS NULL THEN
      INSERT INTO public.technical_configuration_comparison_sets (
        dossier_id,
        option_id,
        baseline_version_id,
        created_by,
        updated_by
      )
      VALUES (
        v_option_dossier_id,
        p_option_id,
        p_baseline_version_id,
        v_user_id,
        v_user_id
      )
      RETURNING id INTO v_comparison_set_id;

      UPDATE public.technical_configuration_dossiers
      SET revision = revision + 1,
          updated_at = now(),
          updated_by = v_user_id
      WHERE id = v_option_dossier_id
      RETURNING revision INTO v_revision;
    ELSE
      SELECT d.revision
      INTO v_revision
      FROM public.technical_configuration_dossiers d
      WHERE d.id = v_option_dossier_id;
    END IF;
  END IF;

  SELECT jsonb_build_object(
    'id', cs.id,
    'dossier_id', cs.dossier_id,
    'option_id', cs.option_id,
    'baseline_version_id', cs.baseline_version_id,
    'created_at', cs.created_at,
    'created_by', cs.created_by,
    'updated_at', cs.updated_at,
    'updated_by', cs.updated_by,
    'revision', v_revision,
    'responses', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', r.id,
            'comparison_set_id', r.comparison_set_id,
            'baseline_version_id', r.baseline_version_id,
            'criterion_id', r.criterion_id,
            'response_text', r.response_text,
            'supplementary_information', r.supplementary_information,
            'created_at', r.created_at,
            'created_by', r.created_by,
            'updated_at', r.updated_at,
            'updated_by', r.updated_by,
            'revision', v_revision
          )
          ORDER BY bg.sort_order, bc.sort_order, bc.id
        )
        FROM public.technical_configuration_option_responses r
        JOIN public.technical_configuration_baseline_criteria bc
          ON bc.id = r.criterion_id
         AND bc.baseline_version_id = r.baseline_version_id
        JOIN public.technical_configuration_baseline_groups bg
          ON bg.id = bc.group_id
         AND bg.baseline_version_id = bc.baseline_version_id
        WHERE r.comparison_set_id = cs.id
      ),
      '[]'::JSONB
    )
  )
  INTO v_data
  FROM public.technical_configuration_comparison_sets cs
  WHERE cs.id = v_comparison_set_id;

  RETURN jsonb_build_object('data', v_data);
END;
$$;


ALTER FUNCTION public.technical_configuration_comparison_set_get_or_create(p_option_id uuid, p_baseline_version_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_dossiers_archive(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_dossiers_archive(p_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_data JSONB;
BEGIN
  v_user_id := public._technical_configuration_require_editable_dossier(
    p_id,
    p_expected_revision
  );

  UPDATE public.technical_configuration_dossiers
  SET archived_at = now(),
      archived_by = v_user_id,
      revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = p_id
  RETURNING jsonb_build_object(
    'id', id,
    'device_type_name', device_type_name,
    'name', name,
    'description', description,
    'revision', revision,
    'archived_at', archived_at,
    'archived_by', archived_by,
    'created_at', created_at,
    'created_by', created_by,
    'updated_at', updated_at,
    'updated_by', updated_by
  )
  INTO v_data;

  RETURN jsonb_build_object('data', v_data);
END;
$$;


ALTER FUNCTION public.technical_configuration_dossiers_archive(p_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_dossiers_create(text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_dossiers_create(p_device_type_name text, p_name text, p_description text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_data JSONB;
BEGIN
  v_user_id := public._technical_configuration_require_global_user();

  IF p_expected_revision IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION 'stale_revision' USING ERRCODE = 'PT409';
  END IF;

  IF p_device_type_name IS NULL
     OR btrim(p_device_type_name) = ''
     OR p_name IS NULL
     OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  INSERT INTO public.technical_configuration_dossiers (
    device_type_name,
    name,
    description,
    revision,
    created_by,
    updated_by
  )
  VALUES (
    btrim(p_device_type_name),
    btrim(p_name),
    NULLIF(btrim(p_description), ''),
    1,
    v_user_id,
    v_user_id
  )
  RETURNING jsonb_build_object(
    'id', id,
    'device_type_name', device_type_name,
    'name', name,
    'description', description,
    'revision', revision,
    'archived_at', archived_at,
    'archived_by', archived_by,
    'created_at', created_at,
    'created_by', created_by,
    'updated_at', updated_at,
    'updated_by', updated_by
  )
  INTO v_data;

  RETURN jsonb_build_object('data', v_data);
END;
$$;


ALTER FUNCTION public.technical_configuration_dossiers_create(p_device_type_name text, p_name text, p_description text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_dossiers_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_dossiers_delete(p_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted_id UUID;
  v_dossier RECORD;
  v_audit_ok BOOLEAN;
BEGIN
  PERFORM public._technical_configuration_require_editable_dossier(
    p_id,
    p_expected_revision
  );

  IF EXISTS (
    SELECT 1
    FROM public.technical_configuration_baseline_versions v
    WHERE v.dossier_id = p_id
      AND v.status = 'locked'
  ) THEN
    RAISE EXCEPTION 'locked_dossier' USING ERRCODE = 'PT409';
  END IF;

  SELECT
    d.id,
    d.device_type_name,
    d.name,
    d.description,
    d.revision
  INTO v_dossier
  FROM public.technical_configuration_dossiers d
  WHERE d.id = p_id;

  v_audit_ok := public.audit_log(
    'technical_configuration_dossier_delete',
    'technical_configuration_dossier',
    NULL::BIGINT,
    v_dossier.name,
    jsonb_build_object(
      'dossier_id', v_dossier.id,
      'device_type_name', v_dossier.device_type_name,
      'name', v_dossier.name,
      'description', v_dossier.description,
      'revision', v_dossier.revision,
      'delete_kind', 'hard'
    )
  );
  IF v_audit_ok IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'audit_log_failed' USING ERRCODE = 'PT500';
  END IF;

  DELETE FROM public.technical_configuration_dossiers d
  WHERE d.id = p_id
  RETURNING d.id INTO v_deleted_id;

  RETURN jsonb_build_object(
    'data',
    jsonb_build_object(
      'id',
      v_deleted_id
    )
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_dossiers_delete(p_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION technical_configuration_dossiers_delete(p_id uuid, p_expected_revision bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.technical_configuration_dossiers_delete(p_id uuid, p_expected_revision bigint) IS 'Hard-deletes an active never-locked technical configuration dossier aggregate after fail-closed audit logging.';


