--
-- Name: technical_configuration_dossiers_list(integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_dossiers_list(p_page integer DEFAULT 1, p_page_size integer DEFAULT 20, p_include_archived boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  IF p_page IS NULL
     OR p_page_size IS NULL
     OR p_page < 1
     OR p_page_size < 1
     OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  WITH dossier_page AS MATERIALIZED (
    SELECT
      d.id,
      d.device_type_name,
      d.name,
      d.description,
      d.revision,
      d.archived_at,
      d.archived_by,
      d.created_at,
      d.created_by,
      d.updated_at,
      d.updated_by
    FROM public.technical_configuration_dossiers d
    WHERE p_include_archived OR d.archived_at IS NULL
    ORDER BY d.updated_at DESC, d.id
    LIMIT p_page_size
    OFFSET (p_page - 1)::BIGINT * p_page_size
  ),
  locked_dossiers AS (
    SELECT DISTINCT v.dossier_id
    FROM public.technical_configuration_baseline_versions v
    JOIN dossier_page page
      ON page.id = v.dossier_id
    WHERE v.status = 'locked'
  ),
  paged AS (
    SELECT
      page.*,
      (
        page.archived_at IS NULL
        AND locked.dossier_id IS NULL
      ) AS can_delete
    FROM dossier_page page
    LEFT JOIN locked_dossiers locked
      ON locked.dossier_id = page.id
  )
  SELECT jsonb_build_object(
    'data',
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', p.id,
            'device_type_name', p.device_type_name,
            'name', p.name,
            'description', p.description,
            'revision', p.revision,
            'archived_at', p.archived_at,
            'archived_by', p.archived_by,
            'created_at', p.created_at,
            'created_by', p.created_by,
            'updated_at', p.updated_at,
            'updated_by', p.updated_by,
            'can_delete', p.can_delete
          )
          ORDER BY p.updated_at DESC, p.id
        )
        FROM paged p
      ),
      '[]'::JSONB
    ),
    'total',
    (
      SELECT count(*)
      FROM public.technical_configuration_dossiers d
      WHERE p_include_archived OR d.archived_at IS NULL
    ),
    'page',
    p_page,
    'page_size',
    p_page_size
  )
  INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.technical_configuration_dossiers_list(p_page integer, p_page_size integer, p_include_archived boolean) OWNER TO postgres;

--
-- Name: technical_configuration_dossiers_update(uuid, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
