CREATE FUNCTION public.technical_configuration_dossiers_update(p_id uuid, p_device_type_name text, p_name text, p_description text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
