--
-- Name: technical_configuration_evaluation_criteria_list(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_evaluation_criteria_list(p_option_id uuid, p_baseline_version_id uuid, p_status_filter text, p_page integer, p_page_size integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_comparison_page_size CONSTANT INTEGER := 50;
  v_dossier_id UUID;
  v_total BIGINT;
  v_data JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  IF p_option_id IS NULL
     OR p_baseline_version_id IS NULL
     OR p_status_filter IS NULL
     OR p_status_filter NOT IN ('all', 'not_evaluated', 'fails', 'insufficient_evidence')
     OR p_page IS NULL OR p_page < 1
     OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT version.dossier_id
  INTO v_dossier_id
  FROM public.technical_configuration_baseline_versions version
  WHERE version.id = p_baseline_version_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.technical_configuration_options option_row
    WHERE option_row.id = p_option_id
      AND option_row.dossier_id = v_dossier_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  WITH canonical_criteria AS MATERIALIZED (
    SELECT
      criterion.id AS criterion_id,
      row_number() OVER (
        ORDER BY
          group_row.sort_order,
          group_row.id,
          CASE WHEN criterion.subgroup_id IS NULL THEN 0 ELSE 1 END,
          CASE
            WHEN criterion.subgroup_id IS NULL THEN 0
            ELSE COALESCE(subgroup_row.sort_order, 2147483647)
          END,
          CASE
            WHEN criterion.subgroup_id IS NULL
              THEN '00000000-0000-0000-0000-000000000000'::UUID
            ELSE COALESCE(
              subgroup_row.id,
              'ffffffff-ffff-ffff-ffff-ffffffffffff'::UUID
            )
          END,
          criterion.sort_order,
          criterion.id
      ) AS canonical_index,
      CASE
        WHEN assessment.technical_axis IS NULL THEN 'not_evaluated'
        WHEN assessment.technical_axis = 'not_applicable' THEN 'not_applicable'
        WHEN assessment.technical_axis = 'fails' THEN 'fails'
        WHEN assessment.technical_axis = 'unclear' THEN 'unclear'
        WHEN assessment.evidence_axis IS NULL THEN 'not_evaluated'
        WHEN assessment.evidence_axis IN ('partial', 'missing')
          THEN 'insufficient_evidence'
        ELSE assessment.technical_axis
      END AS derived_status
    FROM public.technical_configuration_baseline_criteria criterion
    JOIN public.technical_configuration_baseline_groups group_row
      ON group_row.id = criterion.group_id
     AND group_row.baseline_version_id = criterion.baseline_version_id
    LEFT JOIN public.technical_configuration_baseline_subgroups subgroup_row
      ON subgroup_row.id = criterion.subgroup_id
     AND subgroup_row.group_id = criterion.group_id
     AND subgroup_row.baseline_version_id = criterion.baseline_version_id
    LEFT JOIN public.technical_configuration_comparison_sets comparison_set
      ON comparison_set.option_id = p_option_id
     AND comparison_set.baseline_version_id = p_baseline_version_id
    LEFT JOIN public.technical_configuration_manual_assessments assessment
      ON assessment.comparison_set_id = comparison_set.id
     AND assessment.baseline_version_id = criterion.baseline_version_id
     AND assessment.criterion_id = criterion.id
    WHERE criterion.baseline_version_id = p_baseline_version_id
  ),
  filtered_criteria AS MATERIALIZED (
    SELECT
      canonical.criterion_id,
      canonical.canonical_index,
      ((canonical.canonical_index - 1) / v_comparison_page_size) + 1 AS canonical_page
    FROM canonical_criteria canonical
    WHERE p_status_filter = 'all'
       OR canonical.derived_status = p_status_filter
  ),
  paged_criteria AS (
    SELECT *
    FROM filtered_criteria filtered
    ORDER BY filtered.canonical_index
    LIMIT p_page_size
    OFFSET (p_page - 1)::BIGINT * p_page_size
  )
  SELECT
    (SELECT count(*) FROM filtered_criteria),
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'criterion_id', paged.criterion_id,
          'canonical_index', paged.canonical_index,
          'canonical_page', paged.canonical_page
        )
        ORDER BY paged.canonical_index
      ),
      '[]'::JSONB
    )
  INTO v_total, v_data
  FROM paged_criteria paged;

  RETURN jsonb_build_object(
    'data', v_data,
    'total', v_total,
    'page', p_page,
    'page_size', p_page_size
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_evaluation_criteria_list(p_option_id uuid, p_baseline_version_id uuid, p_status_filter text, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_option_citation_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_citation_delete(p_option_citation_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_dossier_id UUID;
  v_user_id BIGINT;
  v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT o.dossier_id INTO v_dossier_id
  FROM public.technical_configuration_option_citations c
  JOIN public.technical_configuration_option_documents d
    ON d.id = c.option_document_id
  JOIN public.technical_configuration_options o ON o.id = d.option_id
  WHERE c.id = p_option_citation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id, p_expected_revision
  );
  DELETE FROM public.technical_configuration_option_citations
  WHERE id = p_option_citation_id;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1, updated_at = now(), updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;

  RETURN jsonb_build_object('data', jsonb_build_object(
    'id', p_option_citation_id,
    'revision', v_revision
  ));
END;
$$;


ALTER FUNCTION public.technical_configuration_option_citation_delete(p_option_citation_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_option_citation_upsert(uuid, uuid, uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_citation_upsert(p_option_document_id uuid, p_comparison_set_id uuid, p_criterion_id uuid, p_page_section text, p_excerpt text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_option_id UUID;
  v_dossier_id UUID;
  v_set_option_id UUID;
  v_set_dossier_id UUID;
  v_baseline_version_id UUID;
  v_criterion_version_id UUID;
  v_user_id BIGINT;
  v_citation_id UUID;
  v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT d.option_id, o.dossier_id
  INTO v_option_id, v_dossier_id
  FROM public.technical_configuration_option_documents d
  JOIN public.technical_configuration_options o ON o.id = d.option_id
  WHERE d.id = p_option_document_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT cs.option_id, cs.dossier_id, cs.baseline_version_id
  INTO v_set_option_id, v_set_dossier_id, v_baseline_version_id
  FROM public.technical_configuration_comparison_sets cs
  WHERE cs.id = p_comparison_set_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  IF v_option_id IS DISTINCT FROM v_set_option_id
     OR v_dossier_id IS DISTINCT FROM v_set_dossier_id THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT c.baseline_version_id INTO v_criterion_version_id
  FROM public.technical_configuration_baseline_criteria c
  WHERE c.id = p_criterion_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  IF v_baseline_version_id IS DISTINCT FROM v_criterion_version_id THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id, p_expected_revision
  );
  INSERT INTO public.technical_configuration_option_citations (
    option_id, baseline_version_id, comparison_set_id, option_document_id,
    criterion_id, page_section, excerpt, created_by, updated_by
  )
  VALUES (
    v_option_id, v_baseline_version_id, p_comparison_set_id, p_option_document_id,
    p_criterion_id, p_page_section, p_excerpt, v_user_id, v_user_id
  )
  ON CONFLICT (option_document_id, comparison_set_id, criterion_id) DO UPDATE
  SET page_section = EXCLUDED.page_section,
      excerpt = EXCLUDED.excerpt,
      updated_at = now(),
      updated_by = EXCLUDED.updated_by
  RETURNING id INTO v_citation_id;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1, updated_at = now(), updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;

  RETURN jsonb_build_object('data', (
    SELECT jsonb_build_object(
      'id', c.id,
      'criterion_id', c.criterion_id,
      'page_section', c.page_section,
      'excerpt', c.excerpt,
      'revision', v_revision
    )
    FROM public.technical_configuration_option_citations c
    WHERE c.id = v_citation_id
  ));
END;
$$;


ALTER FUNCTION public.technical_configuration_option_citation_upsert(p_option_document_id uuid, p_comparison_set_id uuid, p_criterion_id uuid, p_page_section text, p_excerpt text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_option_create(uuid, text, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_create(p_supplier_id uuid, p_model text, p_manufacturer text, p_option_name text, p_notes text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_user_id BIGINT;
  v_dossier_id UUID;
  v_supplier_name TEXT;
  v_revision BIGINT;
  v_data JSONB;
  v_model TEXT := NULLIF(btrim(regexp_replace(p_model, '[[:space:]]+', ' ', 'g')), '');
  v_manufacturer TEXT := NULLIF(btrim(regexp_replace(p_manufacturer, '[[:space:]]+', ' ', 'g')), '');
  v_option_name TEXT := NULLIF(btrim(regexp_replace(p_option_name, '[[:space:]]+', ' ', 'g')), '');
  v_notes TEXT := NULLIF(
    regexp_replace(p_notes, '^[[:space:]]+|[[:space:]]+$', '', 'g'),
    ''
  );
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT s.dossier_id
  INTO v_dossier_id
  FROM public.technical_configuration_suppliers s
  WHERE s.id = p_supplier_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id,
    p_expected_revision
  );

  SELECT s.name
  INTO v_supplier_name
  FROM public.technical_configuration_suppliers s
  WHERE s.id = p_supplier_id
    AND s.dossier_id = v_dossier_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF v_model IS NULL AND v_option_name IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  INSERT INTO public.technical_configuration_options (
    dossier_id, supplier_id, model, manufacturer, option_name, notes,
    created_by, updated_by
  )
  VALUES (
    v_dossier_id, p_supplier_id, v_model, v_manufacturer, v_option_name, v_notes,
    v_user_id, v_user_id
  )
  RETURNING jsonb_build_object(
    'id', id,
    'dossier_id', dossier_id,
    'supplier_id', supplier_id,
    'supplier_name', v_supplier_name,
    'model', model,
    'manufacturer', manufacturer,
    'option_name', option_name,
    'notes', notes,
    'display_label', v_supplier_name || ' · ' || COALESCE(model, option_name),
    'created_at', created_at,
    'created_by', created_by,
    'updated_at', updated_at,
    'updated_by', updated_by
  )
  INTO v_data;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;

  RETURN jsonb_build_object(
    'data',
    v_data || jsonb_build_object('revision', v_revision)
  );
END;
$_$;


ALTER FUNCTION public.technical_configuration_option_create(p_supplier_id uuid, p_model text, p_manufacturer text, p_option_name text, p_notes text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_option_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_delete(p_option_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_dossier_id UUID;
  v_supplier_id UUID;
  v_deleted_id UUID;
  v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT o.dossier_id, o.supplier_id
  INTO v_dossier_id, v_supplier_id
  FROM public.technical_configuration_options o
  WHERE o.id = p_option_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id,
    p_expected_revision
  );

  DELETE FROM public.technical_configuration_options
  WHERE id = p_option_id
    AND dossier_id = v_dossier_id
    AND supplier_id = v_supplier_id
  RETURNING id INTO v_deleted_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;

  RETURN jsonb_build_object(
    'data',
    jsonb_build_object('id', v_deleted_id, 'revision', v_revision)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_option_delete(p_option_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_option_document_create(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_document_create(p_option_id uuid, p_name text, p_url text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_dossier_id UUID;
  v_user_id BIGINT;
  v_document_id UUID;
  v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT o.dossier_id INTO v_dossier_id
  FROM public.technical_configuration_options o
  WHERE o.id = p_option_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id, p_expected_revision
  );
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  PERFORM public._technical_configuration_validate_document_url(p_url);

  INSERT INTO public.technical_configuration_option_documents (
    option_id, name, url, created_by, updated_by
  )
  VALUES (p_option_id, btrim(p_name), p_url, v_user_id, v_user_id)
  RETURNING id INTO v_document_id;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1, updated_at = now(), updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;

  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_option_document_payload(v_document_id, NULL)
      || jsonb_build_object('revision', v_revision)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_option_document_create(p_option_id uuid, p_name text, p_url text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_option_document_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_document_delete(p_option_document_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_dossier_id UUID;
  v_user_id BIGINT;
  v_revision BIGINT;
  v_affected_citation_count BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT o.dossier_id INTO v_dossier_id
  FROM public.technical_configuration_option_documents d
  JOIN public.technical_configuration_options o ON o.id = d.option_id
  WHERE d.id = p_option_document_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id, p_expected_revision
  );
  SELECT count(*) INTO v_affected_citation_count
  FROM public.technical_configuration_option_citations
  WHERE option_document_id = p_option_document_id;

  DELETE FROM public.technical_configuration_option_documents
  WHERE id = p_option_document_id;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1, updated_at = now(), updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;

  RETURN jsonb_build_object('data', jsonb_build_object(
    'id', p_option_document_id,
    'revision', v_revision,
    'affected_citation_count', v_affected_citation_count
  ));
END;
$$;


ALTER FUNCTION public.technical_configuration_option_document_delete(p_option_document_id uuid, p_expected_revision bigint) OWNER TO postgres;

