--
-- Name: technical_configuration_option_documents_list(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_documents_list(p_option_id uuid, p_baseline_version_id uuid, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_page INTEGER := COALESCE(p_page, 1);
  v_page_size INTEGER := COALESCE(p_page_size, 50);
  v_option_dossier_id UUID;
  v_version_dossier_id UUID;
  v_result JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  IF v_page < 1 OR v_page_size < 1 OR v_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  SELECT o.dossier_id
  INTO v_option_dossier_id
  FROM public.technical_configuration_options o
  WHERE o.id = p_option_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT v.dossier_id
  INTO v_version_dossier_id
  FROM public.technical_configuration_baseline_versions v
  WHERE v.id = p_baseline_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  IF v_option_dossier_id IS DISTINCT FROM v_version_dossier_id THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  WITH documents AS (
    SELECT d.*
    FROM public.technical_configuration_option_documents d
    WHERE d.option_id = p_option_id
  ),
  paged AS (
    SELECT d.*
    FROM documents d
    ORDER BY d.created_at, d.id
    LIMIT v_page_size
    OFFSET ((v_page - 1)::BIGINT * v_page_size)
  ),
  citation_counts AS (
    SELECT c.option_document_id, count(*) AS affected_citation_count
    FROM paged p
    JOIN public.technical_configuration_option_citations c
      ON c.option_document_id = p.id
    GROUP BY c.option_document_id
  ),
  exact_citations AS (
    SELECT
      c.option_document_id,
      jsonb_agg(jsonb_build_object(
        'id', c.id,
        'criterion_id', c.criterion_id,
        'page_section', c.page_section,
        'excerpt', c.excerpt
      ) ORDER BY c.created_at, c.id) AS citations
    FROM public.technical_configuration_option_citations c
    JOIN public.technical_configuration_comparison_sets comparison_set
      ON comparison_set.id = c.comparison_set_id
     AND comparison_set.option_id = p_option_id
     AND comparison_set.baseline_version_id = p_baseline_version_id
    GROUP BY c.option_document_id
  )
  SELECT jsonb_build_object(
    'data', COALESCE(jsonb_agg(jsonb_build_object(
      'id', d.id,
      'option_id', d.option_id,
      'name', d.name,
      'url', d.url,
      'created_by', d.created_by,
      'created_at', d.created_at,
      'updated_at', d.updated_at,
      'affected_citation_count', COALESCE(counts.affected_citation_count, 0),
      'citations', COALESCE(exact.citations, '[]'::JSONB)
    ) ORDER BY d.created_at, d.id), '[]'::JSONB),
    'total', (SELECT count(*) FROM documents),
    'page', v_page,
    'page_size', v_page_size
  )
  INTO v_result
  FROM paged d
  LEFT JOIN citation_counts counts ON counts.option_document_id = d.id
  LEFT JOIN exact_citations exact ON exact.option_document_id = d.id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.technical_configuration_option_documents_list(p_option_id uuid, p_baseline_version_id uuid, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_option_import_apply(uuid, uuid, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_import_apply(p_option_id uuid, p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_dossier_id UUID;
  v_validation JSONB;
  v_errors JSONB;
  v_comparison_set_id UUID;
  v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  SELECT o.dossier_id
  INTO v_dossier_id
  FROM public.technical_configuration_options o
  WHERE o.id = p_option_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id,
    p_expected_revision
  );
  PERFORM 1
  FROM public.technical_configuration_baseline_versions v
  WHERE v.id = p_baseline_version_id
    AND v.dossier_id = v_dossier_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  v_validation := public._technical_configuration_option_import_validate(
    p_option_id,
    p_baseline_version_id,
    p_template_metadata,
    p_rows,
    p_expected_revision
  );
  v_errors := v_validation->'row_errors';
  IF jsonb_array_length(v_errors) > 0 THEN
    RAISE EXCEPTION 'validation_error'
      USING ERRCODE = 'PT422', DETAIL = v_errors::TEXT;
  END IF;
  SELECT cs.id
  INTO v_comparison_set_id
  FROM public.technical_configuration_comparison_sets cs
  WHERE cs.option_id = p_option_id
    AND cs.baseline_version_id = p_baseline_version_id
  FOR UPDATE;
  IF v_comparison_set_id IS NULL THEN
    INSERT INTO public.technical_configuration_comparison_sets (
      dossier_id,
      option_id,
      baseline_version_id,
      created_by,
      updated_by
    )
    VALUES (
      v_dossier_id,
      p_option_id,
      p_baseline_version_id,
      v_user_id,
      v_user_id
    )
    RETURNING id INTO v_comparison_set_id;
  ELSE
    UPDATE public.technical_configuration_comparison_sets
    SET updated_at = now(),
        updated_by = v_user_id
    WHERE id = v_comparison_set_id;
  END IF;
  DELETE FROM public.technical_configuration_option_responses r
  USING jsonb_array_elements(v_validation->'rows') AS incoming(row)
  WHERE r.comparison_set_id = v_comparison_set_id
    AND r.criterion_id = (incoming.row->>'criterion_id')::UUID
    AND incoming.row->>'response_text' = ''
    AND incoming.row->>'supplementary_information' = '';
  UPDATE public.technical_configuration_option_responses r
  SET response_text = incoming.row->>'response_text',
      supplementary_information = incoming.row->>'supplementary_information',
      updated_at = now(),
      updated_by = v_user_id
  FROM jsonb_array_elements(v_validation->'rows') AS incoming(row)
  WHERE r.comparison_set_id = v_comparison_set_id
    AND r.criterion_id = (incoming.row->>'criterion_id')::UUID
    AND NOT (
      incoming.row->>'response_text' = ''
      AND incoming.row->>'supplementary_information' = ''
    );
  INSERT INTO public.technical_configuration_option_responses (
    comparison_set_id,
    baseline_version_id,
    criterion_id,
    response_text,
    supplementary_information,
    created_by,
    updated_by
  )
  SELECT
    v_comparison_set_id,
    p_baseline_version_id,
    (incoming.row->>'criterion_id')::UUID,
    incoming.row->>'response_text',
    incoming.row->>'supplementary_information',
    v_user_id,
    v_user_id
  FROM jsonb_array_elements(v_validation->'rows') AS incoming(row)
  WHERE NOT (
      incoming.row->>'response_text' = ''
      AND incoming.row->>'supplementary_information' = ''
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.technical_configuration_option_responses r
      WHERE r.comparison_set_id = v_comparison_set_id
        AND r.criterion_id = (incoming.row->>'criterion_id')::UUID
    );
  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;
  RETURN public.technical_configuration_comparison_set_get(
    p_option_id,
    p_baseline_version_id
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_option_import_apply(p_option_id uuid, p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_option_import_preview(uuid, uuid, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_import_preview(p_option_id uuid, p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_validation JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  v_validation := public._technical_configuration_option_import_validate(
    p_option_id,
    p_baseline_version_id,
    p_template_metadata,
    p_rows,
    p_expected_revision
  );
  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'metadata', v_validation->'metadata',
      'rows', v_validation->'rows'
    ),
    'errors', v_validation->'row_errors'
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_option_import_preview(p_option_id uuid, p_baseline_version_id uuid, p_template_metadata jsonb, p_rows jsonb, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_option_response_upsert(uuid, uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_response_upsert(p_comparison_set_id uuid, p_criterion_id uuid, p_response_text text, p_supplementary_information text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_dossier_id UUID;
  v_baseline_version_id UUID;
  v_criterion_version_id UUID;
  v_response_id UUID;
  v_revision BIGINT;
  v_data JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT cs.dossier_id, cs.baseline_version_id
  INTO v_dossier_id, v_baseline_version_id
  FROM public.technical_configuration_comparison_sets cs
  WHERE cs.id = p_comparison_set_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  SELECT c.baseline_version_id
  INTO v_criterion_version_id
  FROM public.technical_configuration_baseline_criteria c
  WHERE c.id = p_criterion_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF v_baseline_version_id IS DISTINCT FROM v_criterion_version_id THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id,
    p_expected_revision
  );

  INSERT INTO public.technical_configuration_option_responses (
    comparison_set_id,
    baseline_version_id,
    criterion_id,
    response_text,
    supplementary_information,
    created_by,
    updated_by
  )
  VALUES (
    p_comparison_set_id,
    v_baseline_version_id,
    p_criterion_id,
    COALESCE(p_response_text, ''),
    COALESCE(p_supplementary_information, ''),
    v_user_id,
    v_user_id
  )
  ON CONFLICT (comparison_set_id, criterion_id) DO UPDATE
  SET response_text = EXCLUDED.response_text,
      supplementary_information = EXCLUDED.supplementary_information,
      updated_at = now(),
      updated_by = EXCLUDED.updated_by
  RETURNING id INTO v_response_id;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;

  SELECT jsonb_build_object(
    'id', r.id,
    'comparison_set_id', r.comparison_set_id,
    'baseline_version_id', r.baseline_version_id,
    'criterion_id', r.criterion_id,
    'response_text', r.response_text,
    'supplementary_information', r.supplementary_information,
    'created_at', r.created_at,
    'created_by', r.created_by,
    'updated_at', r.updated_at,
    'updated_by', r.updated_by,
    'revision', v_revision
  )
  INTO v_data
  FROM public.technical_configuration_option_responses r
  WHERE r.id = v_response_id;

  RETURN jsonb_build_object('data', v_data);
END;
$$;


ALTER FUNCTION public.technical_configuration_option_response_upsert(p_comparison_set_id uuid, p_criterion_id uuid, p_response_text text, p_supplementary_information text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_option_update(uuid, text, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_option_update(p_option_id uuid, p_model text, p_manufacturer text, p_option_name text, p_notes text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_user_id BIGINT;
  v_dossier_id UUID;
  v_supplier_id UUID;
  v_supplier_name TEXT;
  v_revision BIGINT;
  v_data JSONB;
  v_model TEXT := NULLIF(btrim(regexp_replace(p_model, '[[:space:]]+', ' ', 'g')), '');
  v_manufacturer TEXT := NULLIF(btrim(regexp_replace(p_manufacturer, '[[:space:]]+', ' ', 'g')), '');
  v_option_name TEXT := NULLIF(btrim(regexp_replace(p_option_name, '[[:space:]]+', ' ', 'g')), '');
  v_notes TEXT := NULLIF(
    regexp_replace(p_notes, '^[[:space:]]+|[[:space:]]+$', '', 'g'),
    ''
  );
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT o.dossier_id, o.supplier_id
  INTO v_dossier_id, v_supplier_id
  FROM public.technical_configuration_options o
  WHERE o.id = p_option_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id,
    p_expected_revision
  );

  SELECT s.name
  INTO v_supplier_name
  FROM public.technical_configuration_options o
  JOIN public.technical_configuration_suppliers s
    ON s.id = o.supplier_id
   AND s.dossier_id = o.dossier_id
  WHERE o.id = p_option_id
    AND o.dossier_id = v_dossier_id
    AND o.supplier_id = v_supplier_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  IF v_model IS NULL AND v_option_name IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  UPDATE public.technical_configuration_options
  SET model = v_model,
      manufacturer = v_manufacturer,
      option_name = v_option_name,
      notes = v_notes,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = p_option_id
    AND dossier_id = v_dossier_id
    AND supplier_id = v_supplier_id
  RETURNING jsonb_build_object(
    'id', id,
    'dossier_id', dossier_id,
    'supplier_id', supplier_id,
    'supplier_name', v_supplier_name,
    'model', model,
    'manufacturer', manufacturer,
    'option_name', option_name,
    'notes', notes,
    'display_label', v_supplier_name || ' · ' || COALESCE(model, option_name),
    'created_at', created_at,
    'created_by', created_by,
    'updated_at', updated_at,
    'updated_by', updated_by
  )
  INTO v_data;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;

  RETURN jsonb_build_object(
    'data',
    v_data || jsonb_build_object('revision', v_revision)
  );
END;
$_$;


ALTER FUNCTION public.technical_configuration_option_update(p_option_id uuid, p_model text, p_manufacturer text, p_option_name text, p_notes text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_options_list(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_options_list(p_dossier_id uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  IF p_page IS NULL
     OR p_page_size IS NULL
     OR p_page < 1
     OR p_page_size < 1
     OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  WITH scope AS (
    SELECT d.revision
    FROM public.technical_configuration_dossiers d
    WHERE d.id = p_dossier_id
      AND (
        p_supplier_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public.technical_configuration_suppliers supplier_filter
          WHERE supplier_filter.id = p_supplier_id
            AND supplier_filter.dossier_id = d.id
        )
      )
  ),
  option_page AS (
    SELECT
      o.id,
      o.dossier_id,
      o.supplier_id,
      s.name AS supplier_name,
      s.normalized_name AS supplier_normalized_name,
      o.model,
      o.manufacturer,
      o.option_name,
      o.notes,
      s.name || ' · ' || COALESCE(o.model, o.option_name) AS display_label,
      COALESCE(o.model, o.option_name) AS identity_label,
      o.created_at,
      o.created_by,
      o.updated_at,
      o.updated_by
    FROM public.technical_configuration_options o
    JOIN public.technical_configuration_suppliers s
      ON s.id = o.supplier_id
     AND s.dossier_id = o.dossier_id
    CROSS JOIN scope
    WHERE o.dossier_id = p_dossier_id
      AND (p_supplier_id IS NULL OR o.supplier_id = p_supplier_id)
    ORDER BY s.normalized_name, COALESCE(o.model, o.option_name), o.id
    LIMIT p_page_size
    OFFSET (p_page::BIGINT - 1) * p_page_size::BIGINT
  ),
  option_summary AS (
    SELECT count(*) AS total
    FROM public.technical_configuration_options o
    CROSS JOIN scope
    WHERE o.dossier_id = p_dossier_id
      AND (p_supplier_id IS NULL OR o.supplier_id = p_supplier_id)
  )
  SELECT jsonb_build_object(
    'data',
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', page.id,
            'dossier_id', page.dossier_id,
            'supplier_id', page.supplier_id,
            'supplier_name', page.supplier_name,
            'model', page.model,
            'manufacturer', page.manufacturer,
            'option_name', page.option_name,
            'notes', page.notes,
            'display_label', page.display_label,
            'created_at', page.created_at,
            'created_by', page.created_by,
            'updated_at', page.updated_at,
            'updated_by', page.updated_by,
            'revision', d.revision
          )
          ORDER BY page.supplier_normalized_name, page.identity_label, page.id
        )
        FROM option_page page
      ),
      '[]'::JSONB
    ),
    'revision', d.revision,
    'total', summary.total,
    'page', p_page,
    'page_size', p_page_size
  )
  INTO v_result
  FROM scope d
  CROSS JOIN option_summary summary;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.technical_configuration_options_list(p_dossier_id uuid, p_supplier_id uuid, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_reference_citation_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_reference_citation_delete(p_reference_citation_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_user_id BIGINT; v_version_id UUID; v_revision BIGINT;
BEGIN
  SELECT baseline_version_id INTO v_version_id FROM public.technical_configuration_reference_citations WHERE id = p_reference_citation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404'; END IF;
  v_user_id := public._technical_configuration_require_editable_baseline_version(v_version_id, p_expected_revision);
  DELETE FROM public.technical_configuration_reference_citations WHERE id = p_reference_citation_id;
  v_revision := public._technical_configuration_baseline_bump_revision(v_version_id, v_user_id);
  RETURN jsonb_build_object('data', jsonb_build_object('id', p_reference_citation_id, 'revision', v_revision));
END;
$$;


ALTER FUNCTION public.technical_configuration_reference_citation_delete(p_reference_citation_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_reference_citation_upsert(uuid, uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_reference_citation_upsert(p_reference_document_id uuid, p_criterion_id uuid, p_page_section text, p_excerpt text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_user_id BIGINT; v_version_id UUID; v_id UUID; v_revision BIGINT;
BEGIN
  SELECT baseline_version_id INTO v_version_id FROM public.technical_configuration_reference_documents WHERE id = p_reference_document_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404'; END IF;
  v_user_id := public._technical_configuration_require_editable_baseline_version(v_version_id, p_expected_revision);
  IF NOT EXISTS (SELECT 1 FROM public.technical_configuration_baseline_criteria
                 WHERE id = p_criterion_id AND baseline_version_id = v_version_id) THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  INSERT INTO public.technical_configuration_reference_citations
    (baseline_version_id, reference_document_id, criterion_id, page_section, excerpt, created_by, updated_by)
  VALUES (v_version_id, p_reference_document_id, p_criterion_id, p_page_section, p_excerpt, v_user_id, v_user_id)
  ON CONFLICT (reference_document_id, criterion_id) DO UPDATE
  SET page_section = EXCLUDED.page_section, excerpt = EXCLUDED.excerpt,
      updated_at = now(), updated_by = EXCLUDED.updated_by RETURNING id INTO v_id;
  v_revision := public._technical_configuration_baseline_bump_revision(v_version_id, v_user_id);
  RETURN jsonb_build_object('data',
    public._technical_configuration_citation_payload('reference', v_id) || jsonb_build_object('revision', v_revision));
END;
$$;


ALTER FUNCTION public.technical_configuration_reference_citation_upsert(p_reference_document_id uuid, p_criterion_id uuid, p_page_section text, p_excerpt text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_reference_document_create(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_reference_document_create(p_reference_product_id uuid, p_name text, p_url text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_user_id BIGINT; v_version_id UUID; v_id UUID; v_revision BIGINT;
BEGIN
  SELECT baseline_version_id INTO v_version_id FROM public.technical_configuration_reference_products WHERE id = p_reference_product_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404'; END IF;
  v_user_id := public._technical_configuration_require_editable_baseline_version(v_version_id, p_expected_revision);
  IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422'; END IF;
  PERFORM public._technical_configuration_validate_document_url(p_url);
  INSERT INTO public.technical_configuration_reference_documents
    (baseline_version_id, reference_product_id, name, url, created_by, updated_by)
  VALUES (v_version_id, p_reference_product_id, btrim(p_name), p_url, v_user_id, v_user_id) RETURNING id INTO v_id;
  v_revision := public._technical_configuration_baseline_bump_revision(v_version_id, v_user_id);
  RETURN jsonb_build_object('data',
    public._technical_configuration_document_payload('reference', v_id) || jsonb_build_object('revision', v_revision));
END;
$$;


ALTER FUNCTION public.technical_configuration_reference_document_create(p_reference_product_id uuid, p_name text, p_url text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_reference_document_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_reference_document_delete(p_reference_document_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_user_id BIGINT; v_version_id UUID; v_revision BIGINT; v_links INTEGER;
BEGIN
  SELECT baseline_version_id INTO v_version_id FROM public.technical_configuration_reference_documents WHERE id = p_reference_document_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404'; END IF;
  v_user_id := public._technical_configuration_require_editable_baseline_version(v_version_id, p_expected_revision);
  SELECT count(*) INTO v_links FROM public.technical_configuration_reference_citations WHERE reference_document_id = p_reference_document_id;
  DELETE FROM public.technical_configuration_reference_documents WHERE id = p_reference_document_id;
  v_revision := public._technical_configuration_baseline_bump_revision(v_version_id, v_user_id);
  RETURN jsonb_build_object('data', jsonb_build_object(
    'id', p_reference_document_id, 'affected_link_count', v_links, 'revision', v_revision));
END;
$$;


ALTER FUNCTION public.technical_configuration_reference_document_delete(p_reference_document_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_reference_document_update(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_reference_document_update(p_reference_document_id uuid, p_name text, p_url text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_user_id BIGINT; v_version_id UUID; v_revision BIGINT;
BEGIN
  SELECT baseline_version_id INTO v_version_id FROM public.technical_configuration_reference_documents WHERE id = p_reference_document_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404'; END IF;
  v_user_id := public._technical_configuration_require_editable_baseline_version(v_version_id, p_expected_revision);
  IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422'; END IF;
  PERFORM public._technical_configuration_validate_document_url(p_url);
  UPDATE public.technical_configuration_reference_documents
  SET name = btrim(p_name), url = p_url, updated_at = now(), updated_by = v_user_id WHERE id = p_reference_document_id;
  v_revision := public._technical_configuration_baseline_bump_revision(v_version_id, v_user_id);
  RETURN jsonb_build_object('data',
    public._technical_configuration_document_payload('reference', p_reference_document_id) || jsonb_build_object('revision', v_revision));
END;
$$;


ALTER FUNCTION public.technical_configuration_reference_document_update(p_reference_document_id uuid, p_name text, p_url text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_reference_product_create(uuid, text, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_reference_product_create(p_baseline_version_id uuid, p_model text, p_manufacturer text, p_description text, p_notes text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_product_id UUID;
  v_revision BIGINT;
  v_model TEXT := NULLIF(btrim(p_model), '');
  v_manufacturer TEXT := NULLIF(btrim(p_manufacturer), '');
  v_description TEXT := NULLIF(btrim(p_description), '');
  v_notes TEXT := NULLIF(btrim(p_notes), '');
BEGIN
  v_user_id := public._technical_configuration_require_editable_baseline_version(
    p_baseline_version_id,
    p_expected_revision
  );
  IF v_model IS NULL AND v_manufacturer IS NULL AND v_description IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  INSERT INTO public.technical_configuration_reference_products (
    baseline_version_id, model, manufacturer, description, notes, created_by, updated_by
  )
  VALUES (
    p_baseline_version_id, v_model, v_manufacturer, v_description, v_notes,
    v_user_id, v_user_id
  )
  RETURNING id INTO v_product_id;
  v_revision := public._technical_configuration_baseline_bump_revision(
    p_baseline_version_id,
    v_user_id
  );
  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_reference_product_payload(v_product_id, v_revision)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_reference_product_create(p_baseline_version_id uuid, p_model text, p_manufacturer text, p_description text, p_notes text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_reference_product_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_reference_product_delete(p_reference_product_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT; v_version_id UUID; v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  SELECT p.baseline_version_id INTO v_version_id
  FROM public.technical_configuration_reference_products p
  WHERE p.id = p_reference_product_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  v_user_id := public._technical_configuration_require_editable_baseline_version(
    v_version_id,
    p_expected_revision
  );
  DELETE FROM public.technical_configuration_reference_products
  WHERE id = p_reference_product_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404'; END IF;
  v_revision := public._technical_configuration_baseline_bump_revision(
    v_version_id,
    v_user_id
  );
  RETURN jsonb_build_object(
    'data',
    jsonb_build_object('id', p_reference_product_id, 'revision', v_revision)
  );
END;
$$;


