--
-- Name: technical_configuration_reference_products_list(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_reference_products_list(p_baseline_version_id uuid, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  IF p_page IS NULL OR p_page < 1
     OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  WITH baseline AS MATERIALIZED (
    SELECT v.revision
    FROM public.technical_configuration_baseline_versions v
    WHERE v.id = p_baseline_version_id
  ),
  snapshot AS MATERIALIZED (
    SELECT
      baseline.revision,
      (
        SELECT count(*)
        FROM public.technical_configuration_reference_products product_count
        WHERE product_count.baseline_version_id = p_baseline_version_id
      ) AS total
    FROM baseline
  ),
  page AS MATERIALIZED (
    SELECT
      product.id,
      product.baseline_version_id,
      product.model,
      product.manufacturer,
      product.description,
      product.notes,
      product.created_at,
      product.created_by,
      product.updated_at,
      product.updated_by,
      snapshot.revision
    FROM public.technical_configuration_reference_products product
    CROSS JOIN snapshot
    WHERE product.baseline_version_id = p_baseline_version_id
    ORDER BY product.created_at, product.id
    LIMIT p_page_size
    OFFSET (p_page::BIGINT - 1) * p_page_size
  ),
  responses_by_product AS (
    SELECT
      response.reference_product_id,
      jsonb_agg(
        jsonb_build_object(
          'id', response.id,
          'baseline_version_id', response.baseline_version_id,
          'reference_product_id', response.reference_product_id,
          'criterion_id', response.criterion_id,
          'response_text', response.response_text,
          'created_at', response.created_at,
          'created_by', response.created_by,
          'updated_at', response.updated_at,
          'updated_by', response.updated_by,
          'revision', page_product.revision
        )
        ORDER BY criterion.sort_order, criterion.id
      ) AS responses
    FROM public.technical_configuration_reference_responses response
    JOIN public.technical_configuration_baseline_criteria criterion
      ON criterion.id = response.criterion_id
     AND criterion.baseline_version_id = response.baseline_version_id
    JOIN page page_product
      ON page_product.id = response.reference_product_id
    GROUP BY response.reference_product_id
  ),
  data AS (
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', page.id,
          'baseline_version_id', page.baseline_version_id,
          'model', page.model,
          'manufacturer', page.manufacturer,
          'description', page.description,
          'notes', page.notes,
          'created_at', page.created_at,
          'created_by', page.created_by,
          'updated_at', page.updated_at,
          'updated_by', page.updated_by,
          'revision', page.revision,
          'responses', COALESCE(responses.responses, '[]'::JSONB)
        )
        ORDER BY page.created_at, page.id
      ),
      '[]'::JSONB
    ) AS products
    FROM page
    LEFT JOIN responses_by_product responses
      ON responses.reference_product_id = page.id
  )
  SELECT jsonb_build_object(
    'data', data.products,
    'revision', snapshot.revision,
    'total', snapshot.total,
    'page', p_page,
    'page_size', p_page_size
  )
  INTO v_result
  FROM snapshot
  CROSS JOIN data;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.technical_configuration_reference_products_list(p_baseline_version_id uuid, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_reference_ranking_list(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_reference_ranking_list(p_dossier_id uuid, p_baseline_version_id uuid, p_page integer, p_page_size integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_total BIGINT; v_data JSONB; v_snapshot_token TEXT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  IF p_dossier_id IS NULL OR p_baseline_version_id IS NULL
     OR p_page IS NULL OR p_page < 1
     OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.technical_configuration_baseline_versions version
    WHERE version.id = p_baseline_version_id
      AND version.dossier_id = p_dossier_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  WITH ranked AS MATERIALIZED (
    SELECT
      ranking.option_id,
      ranking.rank_value,
      ranking.supplier_normalized_name,
      ranking.identity_label,
      ranking.ranking_item
    FROM public._technical_configuration_reference_ranking_snapshot(
      p_dossier_id, p_baseline_version_id
    ) ranking
  ),
  paged AS (
    SELECT ranking_item, rank_value, supplier_normalized_name, identity_label, option_id
    FROM ranked
    ORDER BY
      CASE WHEN rank_value IS NULL THEN 1 ELSE 0 END,
      rank_value, supplier_normalized_name, identity_label, option_id
    LIMIT p_page_size
    OFFSET (p_page - 1)::BIGINT * p_page_size
  )
  SELECT
    (SELECT count(*) FROM ranked),
    COALESCE((
      SELECT jsonb_agg(
        ranking_item ORDER BY
          CASE WHEN rank_value IS NULL THEN 1 ELSE 0 END,
          rank_value, supplier_normalized_name, identity_label, option_id
      )
      FROM paged
    ), '[]'::JSONB)
  INTO v_total, v_data;
  v_snapshot_token := public._technical_configuration_reference_ranking_token(
    p_dossier_id, p_baseline_version_id
  );
  RETURN jsonb_build_object(
    'data', v_data,
    'dossier_id', p_dossier_id,
    'baseline_version_id', p_baseline_version_id,
    'snapshot_token', v_snapshot_token,
    'total', v_total,
    'page', p_page,
    'page_size', p_page_size
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_reference_ranking_list(p_dossier_id uuid, p_baseline_version_id uuid, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_reference_response_upsert(uuid, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_reference_response_upsert(p_reference_product_id uuid, p_criterion_id uuid, p_response_text text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_product_version_id UUID;
  v_criterion_version_id UUID;
  v_response_id UUID;
  v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  SELECT p.baseline_version_id INTO v_product_version_id
  FROM public.technical_configuration_reference_products p
  WHERE p.id = p_reference_product_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  SELECT c.baseline_version_id INTO v_criterion_version_id
  FROM public.technical_configuration_baseline_criteria c
  WHERE c.id = p_criterion_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;
  IF v_product_version_id IS DISTINCT FROM v_criterion_version_id THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  v_user_id := public._technical_configuration_require_editable_baseline_version(
    v_product_version_id,
    p_expected_revision
  );
  INSERT INTO public.technical_configuration_reference_responses (
    baseline_version_id,
    reference_product_id,
    criterion_id,
    response_text,
    created_by,
    updated_by
  )
  VALUES (
    v_product_version_id,
    p_reference_product_id,
    p_criterion_id,
    COALESCE(p_response_text, ''),
    v_user_id,
    v_user_id
  )
  ON CONFLICT (reference_product_id, criterion_id) DO UPDATE
  SET response_text = EXCLUDED.response_text,
      updated_at = now(),
      updated_by = EXCLUDED.updated_by
  RETURNING id INTO v_response_id;
  v_revision := public._technical_configuration_baseline_bump_revision(
    v_product_version_id,
    v_user_id
  );
  RETURN jsonb_build_object(
    'data',
    public._technical_configuration_reference_response_payload(v_response_id, v_revision)
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_reference_response_upsert(p_reference_product_id uuid, p_criterion_id uuid, p_response_text text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_result_export_criterion_axis_list(uuid, uuid, uuid[], uuid[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_result_export_criterion_axis_list(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[], p_page integer, p_page_size integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_snapshot JSONB;
  v_data JSONB;
  v_total BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  IF p_page IS NULL OR p_page < 1
     OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  v_snapshot := public._technical_configuration_result_export_snapshot(
    p_dossier_id,
    p_baseline_version_id,
    p_option_ids,
    p_criterion_ids
  );
  v_total := (v_snapshot->>'criterion_total')::BIGINT;

  WITH paged AS (
    SELECT selected.item, selected.ordinal
    FROM jsonb_array_elements(v_snapshot->'criteria') WITH ORDINALITY
      AS selected(item, ordinal)
    ORDER BY selected.ordinal
    LIMIT p_page_size
    OFFSET (p_page - 1)::BIGINT * p_page_size
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
          'group_id', paged.item->'group_id',
          'group_name', paged.item->'group_name',
          'group_order', paged.item->'group_order',
          'criterion_id', paged.item->'criterion_id',
          'criterion_code', paged.item->'criterion_code',
          'criterion_title', paged.item->'criterion_title',
          'requirement_text', paged.item->'requirement_text',
          'criterion_order', paged.item->'criterion_order'
        )
      ORDER BY paged.ordinal
    ),
    '[]'::JSONB
  )
  INTO v_data
  FROM paged;

  RETURN jsonb_build_object(
    'data', v_data,
    'dossier_id', p_dossier_id,
    'baseline_version_id', p_baseline_version_id,
    'snapshot_token', v_snapshot->'snapshot_token',
    'ranking_snapshot_token', v_snapshot->'ranking_snapshot_token',
    'total', v_total,
    'page', p_page,
    'page_size', p_page_size
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_result_export_criterion_axis_list(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[], p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_result_export_manifest_get(uuid, uuid, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_result_export_manifest_get(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_snapshot JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  v_snapshot := public._technical_configuration_result_export_snapshot(
    p_dossier_id,
    p_baseline_version_id,
    p_option_ids,
    p_criterion_ids
  );
  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'dossier', v_snapshot->'dossier',
      'baseline_version', v_snapshot->'baseline_version',
      'option_total', v_snapshot->'option_total',
      'criterion_total', v_snapshot->'criterion_total',
      'snapshot_token', v_snapshot->'snapshot_token',
