ALTER FUNCTION public.technical_configuration_result_export_manifest_get(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[]) OWNER TO postgres;

--
-- Name: technical_configuration_result_export_matrix_list(uuid, uuid, uuid[], uuid[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_result_export_matrix_list(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[], p_page integer, p_page_size integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_snapshot JSONB; v_data JSONB; v_total BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  IF p_page IS NULL OR p_page < 1
     OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 1000 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  v_snapshot := public._technical_configuration_result_export_snapshot(
    p_dossier_id, p_baseline_version_id, p_option_ids, p_criterion_ids
  );
  v_total := (v_snapshot->>'option_total')::BIGINT
    * (v_snapshot->>'criterion_total')::BIGINT;
  WITH scoped_options AS MATERIALIZED (
    SELECT
      selected.ordinal,
      option_row.id AS option_id,
      option_row.supplier_id,
      supplier.name AS supplier_name,
      public._technical_configuration_option_display_label(
        supplier.name,
        option_row.model,
        option_row.option_name
      ) AS display_label,
      option_row.model,
      option_row.manufacturer,
      option_row.option_name
    FROM jsonb_array_elements_text(v_snapshot->'option_ids')
      WITH ORDINALITY AS selected(option_id, ordinal)
    JOIN public.technical_configuration_options option_row
      ON option_row.id = selected.option_id::UUID
     AND option_row.dossier_id = p_dossier_id
    JOIN public.technical_configuration_suppliers supplier
      ON supplier.id = option_row.supplier_id
     AND supplier.dossier_id = option_row.dossier_id
  ),
  scoped_criteria AS MATERIALIZED (
    SELECT
      selected.ordinal,
      group_row.id AS group_id,
      group_row.name AS group_name,
      group_row.sort_order AS group_order,
      criterion.id AS criterion_id,
      criterion.criterion_code,
      criterion.title AS criterion_title,
      criterion.requirement_text,
      criterion.sort_order AS criterion_order
    FROM jsonb_array_elements_text(v_snapshot->'criterion_ids')
      WITH ORDINALITY AS selected(criterion_id, ordinal)
    JOIN public.technical_configuration_baseline_criteria criterion
      ON criterion.id = selected.criterion_id::UUID
     AND criterion.baseline_version_id = p_baseline_version_id
    JOIN public.technical_configuration_baseline_groups group_row
      ON group_row.id = criterion.group_id
     AND group_row.baseline_version_id = criterion.baseline_version_id
  ),
  paged_cells AS MATERIALIZED (
    SELECT
      criterion.group_id,
      criterion.group_name,
      criterion.group_order,
      criterion.criterion_id,
      criterion.criterion_code,
      criterion.criterion_title,
      criterion.requirement_text,
      criterion.criterion_order,
      option_row.option_id,
      option_row.supplier_id,
      option_row.supplier_name,
      option_row.display_label,
      option_row.model,
      option_row.manufacturer,
      option_row.option_name,
      criterion.ordinal AS criterion_ordinal,
      option_row.ordinal AS option_ordinal
    FROM scoped_criteria criterion
    CROSS JOIN scoped_options option_row
    ORDER BY criterion.ordinal, option_row.ordinal
    LIMIT p_page_size
    OFFSET (p_page - 1)::BIGINT * p_page_size
  ),
  evidence AS MATERIALIZED (
    SELECT
      cell.option_id,
      cell.criterion_id,
      jsonb_agg(
        jsonb_build_object(
            'document_id', document.id,
            'document_name', document.name,
            'document_url', document.url,
            'citation_id', citation.id,
            'page_section', citation.page_section,
            'excerpt', citation.excerpt
          )
        ORDER BY document.name, document.id, citation.id
      ) AS document_links
    FROM paged_cells cell
    JOIN public.technical_configuration_comparison_sets comparison_set
      ON comparison_set.option_id = cell.option_id
     AND comparison_set.dossier_id = p_dossier_id
     AND comparison_set.baseline_version_id = p_baseline_version_id
    JOIN public.technical_configuration_option_citations citation
      ON citation.option_id = cell.option_id
     AND citation.comparison_set_id = comparison_set.id
     AND citation.baseline_version_id = p_baseline_version_id
     AND citation.criterion_id = cell.criterion_id
    JOIN public.technical_configuration_option_documents document
      ON document.id = citation.option_document_id
     AND document.option_id = cell.option_id
    GROUP BY cell.option_id, cell.criterion_id
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
            'group_id', cell.group_id,
            'group_name', cell.group_name,
            'group_order', cell.group_order,
            'criterion_id', cell.criterion_id,
            'criterion_code', cell.criterion_code,
            'criterion_title', cell.criterion_title,
            'requirement_text', cell.requirement_text,
            'criterion_order', cell.criterion_order,
            'option_id', cell.option_id,
            'supplier_id', cell.supplier_id,
            'supplier_name', cell.supplier_name,
            'display_label', cell.display_label,
            'model', cell.model,
            'manufacturer', cell.manufacturer,
            'option_name', cell.option_name,
            'response_text', response.response_text,
            'supplementary_information', response.supplementary_information,
            'document_links', COALESCE(evidence.document_links, '[]'::JSONB),
            'technical_axis', assessment.technical_axis,
            'evidence_axis', assessment.evidence_axis,
            'assessment_notes', assessment.notes,
            'conclusion', public._technical_configuration_derived_status(
              assessment.technical_axis,
              assessment.evidence_axis
            )
          )
    ORDER BY cell.criterion_ordinal, cell.option_ordinal
  ), '[]'::JSONB)
  INTO v_data
  FROM paged_cells cell
  LEFT JOIN public.technical_configuration_comparison_sets comparison_set
    ON comparison_set.option_id = cell.option_id
   AND comparison_set.dossier_id = p_dossier_id
   AND comparison_set.baseline_version_id = p_baseline_version_id
  LEFT JOIN public.technical_configuration_option_responses response
    ON response.comparison_set_id = comparison_set.id
   AND response.baseline_version_id = p_baseline_version_id
   AND response.criterion_id = cell.criterion_id
  LEFT JOIN public.technical_configuration_manual_assessments assessment
    ON assessment.comparison_set_id = comparison_set.id
   AND assessment.baseline_version_id = p_baseline_version_id
   AND assessment.criterion_id = cell.criterion_id
  LEFT JOIN evidence
    ON evidence.option_id = cell.option_id
   AND evidence.criterion_id = cell.criterion_id;
  RETURN jsonb_build_object(
    'data', v_data,
    'dossier_id', p_dossier_id,
    'baseline_version_id', p_baseline_version_id,
    'snapshot_token', v_snapshot->'snapshot_token',
    'ranking_snapshot_token', v_snapshot->'ranking_snapshot_token',
    'total', v_total,
    'page', p_page,
    'page_size', p_page_size
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_result_export_matrix_list(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[], p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_result_export_option_axis_list(uuid, uuid, uuid[], uuid[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_result_export_option_axis_list(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[], p_page integer, p_page_size integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_snapshot JSONB;
  v_data JSONB;
  v_total BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  IF p_page IS NULL OR p_page < 1
     OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  v_snapshot := public._technical_configuration_result_export_snapshot(
    p_dossier_id,
    p_baseline_version_id,
    p_option_ids,
    p_criterion_ids
  );
  v_total := (v_snapshot->>'option_total')::BIGINT;

  WITH paged AS (
    SELECT selected.item, selected.ordinal
    FROM jsonb_array_elements(v_snapshot->'options') WITH ORDINALITY
      AS selected(item, ordinal)
    ORDER BY selected.ordinal
    LIMIT p_page_size
    OFFSET (p_page - 1)::BIGINT * p_page_size
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
          'option_id', paged.item->'option_id',
          'supplier_id', paged.item->'supplier_id',
          'supplier_name', paged.item->'supplier_name',
          'display_label', public._technical_configuration_option_display_label(
            paged.item->>'supplier_name',
            paged.item->>'model',
            paged.item->>'option_name'
          ),
          'model', paged.item->'model',
          'manufacturer', paged.item->'manufacturer',
          'option_name', paged.item->'option_name'
        )
      ORDER BY paged.ordinal
    ),
    '[]'::JSONB
  )
  INTO v_data
  FROM paged;

  RETURN jsonb_build_object(
    'data', v_data,
    'dossier_id', p_dossier_id,
    'baseline_version_id', p_baseline_version_id,
    'snapshot_token', v_snapshot->'snapshot_token',
    'ranking_snapshot_token', v_snapshot->'ranking_snapshot_token',
    'total', v_total,
    'page', p_page,
    'page_size', p_page_size
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_result_export_option_axis_list(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[], p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_result_export_ranking_list(uuid, uuid, uuid[], uuid[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_result_export_ranking_list(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[], p_page integer, p_page_size integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_snapshot JSONB; v_data JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();
  IF p_page IS NULL OR p_page < 1
     OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;
  v_snapshot := public._technical_configuration_result_export_snapshot(
    p_dossier_id, p_baseline_version_id, p_option_ids, p_criterion_ids
  );
  WITH selected_options AS MATERIALIZED (
    SELECT option_id::UUID
    FROM jsonb_array_elements_text(v_snapshot->'option_ids')
      WITH ORDINALITY AS selected(option_id, ordinal)
  ),
  ranked AS MATERIALIZED (
    SELECT
      ranking.option_id,
      ranking.rank_value,
      ranking.supplier_normalized_name,
      ranking.identity_label,
      ranking.ranking_item
    FROM public._technical_configuration_reference_ranking_snapshot(
      p_dossier_id, p_baseline_version_id
    ) ranking
    JOIN selected_options selected ON selected.option_id = ranking.option_id
  ),
  paged AS (
    SELECT
      option_id,
      rank_value,
      supplier_normalized_name,
      identity_label,
      ranking_item
    FROM ranked
    ORDER BY
      CASE WHEN rank_value IS NULL THEN 1 ELSE 0 END,
      rank_value, supplier_normalized_name, identity_label, option_id
    LIMIT p_page_size
    OFFSET (p_page - 1)::BIGINT * p_page_size
  )
  SELECT COALESCE((
    SELECT jsonb_agg(
      ranking_item ORDER BY
        CASE WHEN rank_value IS NULL THEN 1 ELSE 0 END,
        rank_value, supplier_normalized_name, identity_label, option_id
    )
    FROM paged
  ), '[]'::JSONB)
  INTO v_data;
  RETURN jsonb_build_object(
    'data', v_data,
    'dossier_id', p_dossier_id,
    'baseline_version_id', p_baseline_version_id,
    'snapshot_token', v_snapshot->'snapshot_token',
    'ranking_snapshot_token', v_snapshot->'ranking_snapshot_token',
    'total', v_snapshot->'option_total',
    'page', p_page,
    'page_size', p_page_size
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_result_export_ranking_list(p_dossier_id uuid, p_baseline_version_id uuid, p_option_ids uuid[], p_criterion_ids uuid[], p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: technical_configuration_supplier_create(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_supplier_create(p_dossier_id uuid, p_name text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_revision BIGINT;
  v_data JSONB;
  v_name TEXT := NULLIF(btrim(regexp_replace(p_name, '[[:space:]]+', ' ', 'g')), '');
BEGIN
  v_user_id := public._technical_configuration_require_editable_dossier(
    p_dossier_id,
    p_expected_revision
  );

  IF v_name IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  BEGIN
    INSERT INTO public.technical_configuration_suppliers (
      dossier_id,
      name,
      created_by,
      updated_by
    )
    VALUES (
      p_dossier_id,
      v_name,
      v_user_id,
      v_user_id
    )
    RETURNING jsonb_build_object(
      'id', id,
      'dossier_id', dossier_id,
      'name', name,
      'normalized_name', normalized_name,
      'created_at', created_at,
      'created_by', created_by,
      'updated_at', updated_at,
      'updated_by', updated_by
    )
    INTO v_data;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'duplicate_supplier' USING ERRCODE = 'PT409';
  END;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = p_dossier_id
  RETURNING revision INTO v_revision;

  v_data := v_data || jsonb_build_object('revision', v_revision);

  RETURN jsonb_build_object('data', v_data);
END;
$$;


ALTER FUNCTION public.technical_configuration_supplier_create(p_dossier_id uuid, p_name text, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_supplier_delete(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_supplier_delete(p_supplier_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_dossier_id UUID;
  v_deleted_id UUID;
  v_revision BIGINT;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT s.dossier_id
  INTO v_dossier_id
  FROM public.technical_configuration_suppliers s
  WHERE s.id = p_supplier_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id,
    p_expected_revision
  );

  DELETE FROM public.technical_configuration_suppliers
  WHERE id = p_supplier_id
    AND dossier_id = v_dossier_id
  RETURNING id INTO v_deleted_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;

  RETURN jsonb_build_object(
    'data',
    jsonb_build_object(
      'id', v_deleted_id,
      'revision', v_revision
    )
  );
END;
$$;


ALTER FUNCTION public.technical_configuration_supplier_delete(p_supplier_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: technical_configuration_supplier_update(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_supplier_update(p_supplier_id uuid, p_name text, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id BIGINT;
  v_dossier_id UUID;
  v_revision BIGINT;
  v_data JSONB;
  v_name TEXT := NULLIF(btrim(regexp_replace(p_name, '[[:space:]]+', ' ', 'g')), '');
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  SELECT s.dossier_id
  INTO v_dossier_id
  FROM public.technical_configuration_suppliers s
  WHERE s.id = p_supplier_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  v_user_id := public._technical_configuration_require_editable_dossier(
    v_dossier_id,
    p_expected_revision
  );

  IF v_name IS NULL THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  BEGIN
    UPDATE public.technical_configuration_suppliers
    SET name = v_name,
        updated_at = now(),
        updated_by = v_user_id
    WHERE id = p_supplier_id
      AND dossier_id = v_dossier_id
    RETURNING jsonb_build_object(
      'id', id,
      'dossier_id', dossier_id,
      'name', name,
      'normalized_name', normalized_name,
      'created_at', created_at,
      'created_by', created_by,
      'updated_at', updated_at,
      'updated_by', updated_by
    )
    INTO v_data;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'duplicate_supplier' USING ERRCODE = 'PT409';
  END;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  UPDATE public.technical_configuration_dossiers
  SET revision = revision + 1,
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = v_dossier_id
  RETURNING revision INTO v_revision;

  v_data := v_data || jsonb_build_object('revision', v_revision);

  RETURN jsonb_build_object('data', v_data);
END;
$$;


