--
-- Name: technical_configuration_suppliers_list(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_configuration_suppliers_list(p_dossier_id uuid, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  PERFORM public._technical_configuration_require_global_user();

  IF p_page IS NULL
     OR p_page < 1
     OR p_page_size IS NULL
     OR p_page_size < 1
     OR p_page_size > 100 THEN
    RAISE EXCEPTION 'validation_error' USING ERRCODE = 'PT422';
  END IF;

  WITH dossier AS (
    SELECT d.revision
    FROM public.technical_configuration_dossiers d
    WHERE d.id = p_dossier_id
  ),
  supplier_page AS (
    SELECT
      s.id,
      s.dossier_id,
      s.name,
      s.normalized_name,
      s.created_at,
      s.created_by,
      s.updated_at,
      s.updated_by
    FROM public.technical_configuration_suppliers s
    WHERE s.dossier_id = p_dossier_id
    ORDER BY s.normalized_name, s.id
    LIMIT p_page_size
    OFFSET (p_page::BIGINT - 1) * p_page_size::BIGINT
  ),
  supplier_summary AS (
    SELECT count(*) AS total
    FROM public.technical_configuration_suppliers s
    WHERE s.dossier_id = p_dossier_id
  )
  SELECT jsonb_build_object(
    'data',
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', page.id,
            'dossier_id', page.dossier_id,
            'name', page.name,
            'normalized_name', page.normalized_name,
            'created_at', page.created_at,
            'created_by', page.created_by,
            'updated_at', page.updated_at,
            'updated_by', page.updated_by,
            'revision', d.revision
          )
          ORDER BY page.normalized_name, page.id
        )
        FROM supplier_page page
      ),
      '[]'::JSONB
    ),
    'revision', d.revision,
    'total', summary.total,
    'page', p_page,
    'page_size', p_page_size
  )
  INTO v_result
  FROM dossier d
  CROSS JOIN supplier_summary summary;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'PT404';
  END IF;

  RETURN v_result;
END;
$$;


