--
-- Name: test_jwt_claims(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.test_jwt_claims() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_result JSONB;
    v_jwt_claims JSONB;
BEGIN
    -- Try to get JWT claims
    BEGIN
        v_jwt_claims := current_setting('request.jwt.claims', true)::jsonb;
    EXCEPTION WHEN OTHERS THEN
        v_jwt_claims := jsonb_build_object('error', SQLERRM);
    END;
    
    -- Build result with all possible claims
    v_result := jsonb_build_object(
        'jwt_claims', v_jwt_claims,
        'app_role', COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), 'NULL'),
        'role', COALESCE(public._get_jwt_claim('role'), 'NULL'),
        'don_vi', COALESCE(public._get_jwt_claim('don_vi'), 'NULL'),
        'dia_ban', COALESCE(public._get_jwt_claim('dia_ban'), 'NULL'),
        'user_id', COALESCE(public._get_jwt_claim('user_id'), 'NULL'),
        'raw_jwt_setting', COALESCE(current_setting('request.jwt.claims', true), 'NOT_SET')
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.test_jwt_claims() OWNER TO postgres;

--
-- Name: FUNCTION test_jwt_claims(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.test_jwt_claims() IS 'Test function to verify JWT claim passing from RPC proxy. Returns all available claims and debug information.';


