--
-- Name: transfer_change_history_list(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_change_history_list(p_entity_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(
    public._get_jwt_claim('app_role'),
    public._get_jwt_claim('role'), ''
  ));
  v_user_id TEXT := NULLIF(COALESCE(
    public._get_jwt_claim('user_id'),
    public._get_jwt_claim('sub')
  ), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_is_global BOOLEAN := false;
  v_allowed BIGINT[] := NULL;
  v_result JSONB;
BEGIN
  -- Input guard
  IF p_entity_id IS NULL THEN
    RETURN '[]'::JSONB;
  END IF;

  -- JWT claim guards
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  -- Tenant isolation
  v_is_global := v_role IN ('global', 'admin');

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
  END IF;

  IF NOT v_is_global THEN
    v_allowed := public.allowed_don_vi_for_session_safe();
    IF array_length(v_allowed, 1) IS NULL THEN
      RETURN '[]'::JSONB;
    END IF;
  END IF;

  -- Query audit_logs for this transfer request, tenant-scoped
  SELECT jsonb_agg(jsonb_build_object(
    'id', al.id,
    'action_type', al.action_type,
    'admin_username', al.admin_username,
    'admin_full_name', COALESCE(nv.full_name, al.admin_username),
    'action_details', al.action_details,
    'created_at', al.created_at
  ) ORDER BY al.created_at DESC)
  INTO v_result
  FROM public.audit_logs al
  LEFT JOIN public.nhan_vien nv ON nv.id = al.admin_user_id
  -- Tenant scope: join through transfer → equipment → don_vi
  LEFT JOIN public.yeu_cau_luan_chuyen yclc ON yclc.id = al.entity_id
  LEFT JOIN public.thiet_bi tb ON tb.id = yclc.thiet_bi_id
  WHERE al.entity_type = 'transfer_request'
    AND al.entity_id = p_entity_id
    AND (
      v_is_global
      OR (
        array_length(v_allowed, 1) IS NOT NULL
        AND tb.don_vi = ANY(v_allowed)
      )
    );

  RETURN COALESCE(v_result, '[]'::JSONB);
END;
$$;


ALTER FUNCTION public.transfer_change_history_list(p_entity_id bigint) OWNER TO postgres;

--
-- Name: transfer_request_complete(integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_complete(p_id integer, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_claims jsonb;
  v_role text;
  v_is_global boolean := false;
  v_don_vi text;
  v_user_id_text text;
  v_user_id bigint;
  v_req record;
  v_mo_ta text;
  v_loai_su_kien text;
  v_vi_tri_hoan_tra text;
  v_vi_tri_truoc_do text;
BEGIN
  v_claims := coalesce(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_role := lower(coalesce(nullif(v_claims->>'app_role', ''), nullif(v_claims->>'role', '')));
  v_is_global := v_role in ('global', 'admin');
  v_don_vi := nullif(v_claims->>'don_vi', '');
  v_user_id_text := nullif(v_claims->>'user_id', '');
  v_user_id := CASE
    WHEN v_user_id_text ~ '^[0-9]+$' THEN v_user_id_text::bigint
    ELSE NULL
  END;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim in JWT for non-global user' USING errcode = '42501';
  END IF;

  IF v_role = 'regional_leader' THEN
    RAISE EXCEPTION 'Regional leaders have read-only access to transfers' USING errcode = '42501';
  END IF;

  SELECT
    t.*,
    tb.don_vi AS tb_don_vi
  INTO v_req
  FROM public.yeu_cau_luan_chuyen t
  JOIN public.thiet_bi tb ON tb.id = t.thiet_bi_id
  WHERE t.id = p_id
  FOR UPDATE OF t, tb;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Yêu cầu không tồn tại';
  END IF;

  IF NOT v_is_global AND v_req.tb_don_vi::text IS DISTINCT FROM v_don_vi THEN
    RAISE EXCEPTION 'Không có quyền trên yêu cầu thuộc đơn vị khác' USING errcode = '42501';
  END IF;

  IF v_req.trang_thai = 'hoan_thanh' THEN
    RAISE EXCEPTION 'Không thể hoàn thành lại yêu cầu đã hoàn thành' USING errcode = '22023';
  END IF;

  IF (
    (v_req.loai_hinh = 'noi_bo' AND v_req.trang_thai <> 'dang_luan_chuyen')
    OR (v_req.loai_hinh = 'ben_ngoai' AND v_req.trang_thai <> 'da_ban_giao')
    OR (v_req.loai_hinh = 'thanh_ly' AND v_req.trang_thai <> 'da_duyet')
  ) THEN
    RAISE EXCEPTION 'Không thể hoàn thành yêu cầu % từ trạng thái %',
      v_req.loai_hinh,
      v_req.trang_thai
      USING errcode = '22023';
  END IF;

  -- External transfer return: validate and apply return location
  IF v_req.loai_hinh = 'ben_ngoai' THEN
    v_vi_tri_hoan_tra := NULLIF(BTRIM(p_payload->>'vi_tri_hoan_tra'), '');

    IF v_vi_tri_hoan_tra IS NULL THEN
      RAISE EXCEPTION 'Thiếu vi_tri_hoan_tra cho hoàn trả bên ngoài' USING errcode = '22023';
    END IF;

    IF v_vi_tri_hoan_tra = 'Đang luân chuyển bên ngoài' THEN
      RAISE EXCEPTION 'Vị trí hoàn trả không được là "Đang luân chuyển bên ngoài"' USING errcode = '22023';
    END IF;

    -- Capture previous location before update
    SELECT vi_tri_lap_dat INTO v_vi_tri_truoc_do
    FROM public.thiet_bi WHERE id = v_req.thiet_bi_id;

    -- Update equipment location to the return location
    UPDATE public.thiet_bi
    SET vi_tri_lap_dat = v_vi_tri_hoan_tra
    WHERE id = v_req.thiet_bi_id;
  END IF;

  UPDATE public.yeu_cau_luan_chuyen
  SET trang_thai = 'hoan_thanh',
      ngay_hoan_thanh = now(),
      ngay_hoan_tra = COALESCE(
        (p_payload->>'ngay_hoan_tra')::timestamptz,
        CASE WHEN v_req.loai_hinh = 'ben_ngoai' THEN now() ELSE ngay_hoan_tra END
      ),
      updated_by = v_user_id,
      updated_at = now()
  WHERE id = p_id;

  IF v_req.loai_hinh = 'noi_bo' AND v_req.khoa_phong_nhan IS NOT NULL THEN
    UPDATE public.thiet_bi
    SET khoa_phong_quan_ly = v_req.khoa_phong_nhan
    WHERE id = v_req.thiet_bi_id;
  ELSIF v_req.loai_hinh = 'thanh_ly' THEN
    UPDATE public.thiet_bi
    SET tinh_trang_hien_tai = 'Ngưng sử dụng',
        khoa_phong_quan_ly = 'Tổ QLTB'
    WHERE id = v_req.thiet_bi_id;
  END IF;

  IF v_req.loai_hinh = 'noi_bo' THEN
    v_loai_su_kien := 'Luân chuyển';
    v_mo_ta := format(
      'Thiết bị được luân chuyển từ "%s" đến "%s".',
      coalesce(v_req.khoa_phong_hien_tai, ''),
      coalesce(v_req.khoa_phong_nhan, '')
    );
  ELSIF v_req.loai_hinh = 'thanh_ly' THEN
    v_loai_su_kien := 'Thanh lý';
    v_mo_ta := format('Thiết bị được thanh lý. Lý do: %s', coalesce(v_req.ly_do_luan_chuyen, ''));
  ELSE
    v_loai_su_kien := 'Luân chuyển';
    v_mo_ta := format(
      'Thiết bị được hoàn trả từ đơn vị bên ngoài "%s".',
      coalesce(v_req.don_vi_nhan, '')
    );
  END IF;

  INSERT INTO public.lich_su_thiet_bi(thiet_bi_id, loai_su_kien, mo_ta, chi_tiet)
  VALUES (
    v_req.thiet_bi_id,
    v_loai_su_kien,
    v_mo_ta,
    jsonb_build_object(
      'ma_yeu_cau', v_req.ma_yeu_cau,
      'loai_hinh', v_req.loai_hinh,
      'khoa_phong_hien_tai', v_req.khoa_phong_hien_tai,
      'khoa_phong_nhan', v_req.khoa_phong_nhan,
      'don_vi_nhan', v_req.don_vi_nhan,
      'yeu_cau_id', v_req.id
    )
  );

  SELECT
    t.*,
    tb.don_vi AS tb_don_vi
  INTO v_req
  FROM public.yeu_cau_luan_chuyen t
  JOIN public.thiet_bi tb ON tb.id = t.thiet_bi_id
  WHERE t.id = p_id;

  IF NOT public.audit_log(
    'transfer_request_complete',
    'transfer_request',
    v_req.id,
    v_req.ma_yeu_cau,
    jsonb_build_object(
      'trang_thai', v_req.trang_thai,
      'loai_hinh', v_req.loai_hinh,
      'khoa_phong_hien_tai', v_req.khoa_phong_hien_tai,
      'khoa_phong_nhan', v_req.khoa_phong_nhan,
      'don_vi_nhan', v_req.don_vi_nhan,
      'ngay_hoan_thanh', v_req.ngay_hoan_thanh,
      'ngay_hoan_tra', v_req.ngay_hoan_tra,
      'vi_tri_truoc_do', v_vi_tri_truoc_do,
      'vi_tri_hoan_tra_moi', v_vi_tri_hoan_tra
    )
  ) THEN
    RAISE EXCEPTION 'audit_log failed for transfer_request %', v_req.id;
  END IF;
END;
$_$;


ALTER FUNCTION public.transfer_request_complete(p_id integer, p_payload jsonb) OWNER TO postgres;

--
-- Name: transfer_request_counts(text, bigint, date, date, text[], bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_counts(p_q text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_types text[] DEFAULT NULL::text[], p_assignee_ids bigint[] DEFAULT NULL::bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_effective_donvi BIGINT := NULL;
  v_allowed BIGINT[] := NULL;
BEGIN
  -- Tenant isolation (same logic as list function)
  IF v_role = 'global' THEN
    v_effective_donvi := p_don_vi;
  ELSE
    v_allowed := public.allowed_don_vi_for_session();
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      -- No access - return zero counts
      RETURN jsonb_build_object(
        'cho_duyet', 0,
        'da_duyet', 0,
        'dang_luan_chuyen', 0,
        'da_ban_giao', 0,
        'hoan_thanh', 0
      );
    END IF;
    
    IF p_don_vi IS NOT NULL AND NOT (p_don_vi = ANY(v_allowed)) THEN
      -- Requested facility not allowed - return zero counts
      RETURN jsonb_build_object(
        'cho_duyet', 0,
        'da_duyet', 0,
        'dang_luan_chuyen', 0,
        'da_ban_giao', 0,
        'hoan_thanh', 0
      );
    END IF;
    v_effective_donvi := p_don_vi;
  END IF;

  -- Return counts by status (excludes p_statuses filter)
  RETURN (
    WITH base AS (
      SELECT yclc.trang_thai
      FROM public.yeu_cau_luan_chuyen yclc
      JOIN public.thiet_bi tb ON tb.id = yclc.thiet_bi_id
      WHERE (
        (v_role = 'global' AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)) OR
        (v_role <> 'global' AND ((v_effective_donvi IS NOT NULL AND tb.don_vi = v_effective_donvi) OR (v_effective_donvi IS NULL AND tb.don_vi = ANY(v_allowed))))
      )
      AND (p_types IS NULL OR yclc.loai_hinh = ANY(p_types))
      AND (p_assignee_ids IS NULL OR yclc.nguoi_yeu_cau_id = ANY(p_assignee_ids))
      AND (
        p_q IS NULL OR p_q = '' OR
        yclc.ma_yeu_cau ILIKE '%' || p_q || '%' OR
        yclc.ly_do_luan_chuyen ILIKE '%' || p_q || '%' OR
        tb.ten_thiet_bi ILIKE '%' || p_q || '%' OR
        tb.ma_thiet_bi ILIKE '%' || p_q || '%'
      )
      AND (p_date_from IS NULL OR yclc.created_at >= (p_date_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
      AND (p_date_to IS NULL OR yclc.created_at < ((p_date_to + interval '1 day')::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
    )
    SELECT jsonb_build_object(
      'cho_duyet', COALESCE((SELECT count(*) FROM base WHERE trang_thai = 'cho_duyet'), 0),
      'da_duyet', COALESCE((SELECT count(*) FROM base WHERE trang_thai = 'da_duyet'), 0),
      'dang_luan_chuyen', COALESCE((SELECT count(*) FROM base WHERE trang_thai = 'dang_luan_chuyen'), 0),
      'da_ban_giao', COALESCE((SELECT count(*) FROM base WHERE trang_thai = 'da_ban_giao'), 0),
      'hoan_thanh', COALESCE((SELECT count(*) FROM base WHERE trang_thai = 'hoan_thanh'), 0)
    )
  );
END;
$$;


ALTER FUNCTION public.transfer_request_counts(p_q text, p_don_vi bigint, p_date_from date, p_date_to date, p_types text[], p_assignee_ids bigint[]) OWNER TO postgres;

--
-- Name: FUNCTION transfer_request_counts(p_q text, p_don_vi bigint, p_date_from date, p_date_to date, p_types text[], p_assignee_ids bigint[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.transfer_request_counts(p_q text, p_don_vi bigint, p_date_from date, p_date_to date, p_types text[], p_assignee_ids bigint[]) IS 'Returns counts per status for current filters (excludes status filter itself). 
Respects tenant isolation and matches transfer_request_list filter logic.';


--
-- Name: transfer_request_create(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_create(p_data jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id int;
  v_claims jsonb;
  v_role text;
  v_is_global boolean := false;
  v_don_vi text;
  v_user_id int;
  v_department_scope text;
  v_tb record;
BEGIN
  v_claims := coalesce(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_role := lower(coalesce(nullif(v_claims->>'app_role', ''), nullif(v_claims->>'role', '')));
  v_is_global := v_role in ('global', 'admin');
  v_don_vi := nullif(v_claims->>'don_vi', '');
  v_user_id := nullif(v_claims->>'user_id', '')::int;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  IF v_role = 'regional_leader' THEN
    RAISE EXCEPTION 'Regional leaders have read-only access to transfers' USING errcode = '42501';
  END IF;

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim for non-global role %', v_role USING errcode = '42501';
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(v_claims->>'khoa_phong');
  END IF;

  SELECT id, don_vi, khoa_phong_quan_ly
  INTO v_tb
  FROM public.thiet_bi
  WHERE id = (p_data->>'thiet_bi_id')::int
    AND is_deleted = false
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Thiết bị không tồn tại' USING errcode = 'P0002';
  END IF;

  IF NOT v_is_global AND v_tb.don_vi::text IS DISTINCT FROM v_don_vi THEN
    RAISE EXCEPTION 'Không có quyền trên thiết bị thuộc đơn vị khác' USING errcode = '42501';
  END IF;

  IF v_role = 'user'
     AND (
       v_department_scope IS NULL
       OR public._normalize_department_scope(v_tb.khoa_phong_quan_ly) IS DISTINCT FROM v_department_scope
     ) THEN
    RAISE EXCEPTION 'Không có quyền trên thiết bị thuộc khoa/phòng khác' USING errcode = '42501';
  END IF;

  INSERT INTO public.yeu_cau_luan_chuyen(
    thiet_bi_id,
    loai_hinh,
    ly_do_luan_chuyen,
    khoa_phong_hien_tai,
    khoa_phong_nhan,
    muc_dich,
    don_vi_nhan,
    dia_chi_don_vi,
    nguoi_lien_he,
    so_dien_thoai,
    ngay_du_kien_tra,
    nguoi_yeu_cau_id,
    trang_thai,
    created_by,
    updated_by
  )
  VALUES (
    (p_data->>'thiet_bi_id')::int,
    p_data->>'loai_hinh',
    nullif(p_data->>'ly_do_luan_chuyen', ''),
    nullif(p_data->>'khoa_phong_hien_tai', ''),
    nullif(p_data->>'khoa_phong_nhan', ''),
    nullif(p_data->>'muc_dich', ''),
    nullif(p_data->>'don_vi_nhan', ''),
    nullif(p_data->>'dia_chi_don_vi', ''),
    nullif(p_data->>'nguoi_lien_he', ''),
    nullif(p_data->>'so_dien_thoai', ''),
    CASE
      WHEN coalesce(p_data->>'ngay_du_kien_tra', '') <> '' THEN (p_data->>'ngay_du_kien_tra')::date
      ELSE NULL
    END,
    v_user_id,
    'cho_duyet',
    v_user_id,
    v_user_id
  )
  RETURNING id INTO v_id;

  IF NOT public.audit_log(
    'transfer_request_create',
    'transfer_request',
    v_id,
    NULL,
    p_data - 'created_by' - 'updated_by' - 'nguoi_yeu_cau_id'
  ) THEN
    RAISE EXCEPTION 'audit_log failed for transfer_request %', v_id;
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.transfer_request_create(p_data jsonb) OWNER TO postgres;

--
-- Name: transfer_request_delete(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_delete(p_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims JSONB;
  v_role TEXT;
  v_user_id TEXT;
  v_don_vi TEXT;
  v_req RECORD;
BEGIN
  v_claims := COALESCE(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_role := COALESCE(NULLIF(v_claims->>'app_role',''), NULLIF(v_claims->>'role',''));
  v_user_id := NULLIF(v_claims->>'user_id','');
  v_don_vi := NULLIF(v_claims->>'don_vi','');

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'regional_leader' THEN
    RAISE EXCEPTION 'Regional leaders have read-only access to transfers' USING ERRCODE = '42501';
  END IF;

  SELECT t.*, tb.don_vi AS tb_don_vi
  INTO v_req
  FROM public.yeu_cau_luan_chuyen t
  JOIN public.thiet_bi tb ON tb.id = t.thiet_bi_id
  WHERE t.id = p_id
  FOR UPDATE OF t, tb;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Yêu cầu không tồn tại' USING ERRCODE = '42501';
  END IF;

  IF v_role IS DISTINCT FROM 'global'
    AND (v_don_vi IS NULL OR v_req.tb_don_vi::text IS DISTINCT FROM v_don_vi)
  THEN
    RAISE EXCEPTION 'Không có quyền xóa yêu cầu này' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.yeu_cau_luan_chuyen WHERE id = p_id;
END;
$$;


ALTER FUNCTION public.transfer_request_delete(p_id integer) OWNER TO postgres;

--
-- Name: transfer_request_external_pending_returns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_external_pending_returns() RETURNS SETOF jsonb
    LANGUAGE sql SECURITY DEFINER
    AS $$
  select to_jsonb(t) || jsonb_build_object('thiet_bi', to_jsonb(tb))
  from yeu_cau_luan_chuyen t
  join thiet_bi tb on tb.id = t.thiet_bi_id
  where t.loai_hinh = 'ben_ngoai'
    and t.trang_thai in ('da_ban_giao','dang_luan_chuyen')
    and t.ngay_du_kien_tra is not null;
$$;


ALTER FUNCTION public.transfer_request_external_pending_returns() OWNER TO postgres;

--
-- Name: transfer_request_get(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_get(p_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id TEXT := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_don_vi BIGINT := NULLIF(public._get_jwt_claim('don_vi'), '')::BIGINT;
  v_is_global BOOLEAN := false;
  v_allowed BIGINT[] := NULL;
  v_result JSONB;
BEGIN
  IF p_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  v_is_global := v_role IN ('global', 'admin');

  IF NOT v_is_global THEN
    IF v_role <> 'regional_leader' AND v_don_vi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim' USING ERRCODE = '42501';
    END IF;

    -- regional_leader may legitimately have don_vi = NULL because scope comes from dia_ban.
    v_allowed := public.allowed_don_vi_for_session_safe();

    IF array_length(v_allowed, 1) IS NULL THEN
      RETURN NULL;
    END IF;
  END IF;

  SELECT jsonb_build_object(
    'id', yclc.id,
    'ma_yeu_cau', yclc.ma_yeu_cau,
    'thiet_bi_id', yclc.thiet_bi_id,
    'loai_hinh', yclc.loai_hinh,
    'trang_thai', yclc.trang_thai,
    'nguoi_yeu_cau_id', yclc.nguoi_yeu_cau_id,
    'ly_do_luan_chuyen', yclc.ly_do_luan_chuyen,
    'khoa_phong_hien_tai', yclc.khoa_phong_hien_tai,
    'khoa_phong_nhan', yclc.khoa_phong_nhan,
    'muc_dich', yclc.muc_dich,
    'don_vi_nhan', yclc.don_vi_nhan,
    'dia_chi_don_vi', yclc.dia_chi_don_vi,
    'nguoi_lien_he', yclc.nguoi_lien_he,
    'so_dien_thoai', yclc.so_dien_thoai,
    'ngay_du_kien_tra', yclc.ngay_du_kien_tra,
    'ngay_ban_giao', yclc.ngay_ban_giao,
    'ngay_hoan_tra', yclc.ngay_hoan_tra,
    'ngay_hoan_thanh', yclc.ngay_hoan_thanh,
    'nguoi_duyet_id', yclc.nguoi_duyet_id,
    'ngay_duyet', yclc.ngay_duyet,
    'ghi_chu_duyet', yclc.ghi_chu_duyet,
    'created_at', yclc.created_at,
    'updated_at', yclc.updated_at,
    'created_by', yclc.created_by,
    'updated_by', yclc.updated_by,
    'equipment_is_deleted', tb.is_deleted,
    'thiet_bi',
      CASE
        WHEN tb.id IS NULL THEN NULL
        ELSE jsonb_build_object(
          'id', tb.id,
          'ten_thiet_bi', tb.ten_thiet_bi,
          'ma_thiet_bi', tb.ma_thiet_bi,
          'model', tb.model,
          'serial', tb.serial,
          'serial_number', tb.serial,
          'khoa_phong_quan_ly', tb.khoa_phong_quan_ly,
          'facility_name', dv.name,
          'facility_id', dv.id,
          'don_vi', dv.id,
          'tinh_trang', tb.tinh_trang_hien_tai
        )
      END,
    'nguoi_yeu_cau',
      CASE
        WHEN requester.id IS NULL THEN NULL
        ELSE jsonb_build_object(
          'id', requester.id,
          'username', requester.username,
          'full_name', requester.full_name,
          'role', requester.role,
          'khoa_phong', requester.khoa_phong,
          'created_at', requester.created_at
        )
      END,
    'nguoi_duyet',
      CASE
        WHEN approver.id IS NULL THEN NULL
        ELSE jsonb_build_object(
          'id', approver.id,
          'username', approver.username,
          'full_name', approver.full_name,
          'role', approver.role,
          'khoa_phong', approver.khoa_phong,
          'created_at', approver.created_at
        )
      END
  )
  INTO v_result
  FROM public.yeu_cau_luan_chuyen yclc
  LEFT JOIN public.thiet_bi tb ON tb.id = yclc.thiet_bi_id
  LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
  LEFT JOIN public.nhan_vien requester ON requester.id = yclc.nguoi_yeu_cau_id
  LEFT JOIN public.nhan_vien approver ON approver.id = yclc.nguoi_duyet_id
  WHERE yclc.id = p_id
    AND (
      v_is_global
      OR (
        array_length(v_allowed, 1) IS NOT NULL
        AND tb.don_vi = ANY(v_allowed)
      )
    )
  LIMIT 1;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.transfer_request_get(p_id integer) OWNER TO postgres;

--
-- Name: FUNCTION transfer_request_get(p_id integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.transfer_request_get(p_id integer) IS 'Fetches a single transfer request detail payload with related requester and approver user objects for the Transfers detail dialog.';


--
-- Name: transfer_request_list(text, text[], text[], integer, integer, bigint, date, date, bigint[], text, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_list(p_q text DEFAULT NULL::text, p_statuses text[] DEFAULT NULL::text[], p_types text[] DEFAULT NULL::text[], p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_don_vi bigint DEFAULT NULL::bigint, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_assignee_ids bigint[] DEFAULT NULL::bigint[], p_view_mode text DEFAULT 'table'::text, p_per_column_limit integer DEFAULT 30, p_exclude_completed boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_is_global BOOLEAN := false;
  v_effective_donvi BIGINT := NULL;
  v_allowed BIGINT[] := NULL;
  v_limit INT := GREATEST(COALESCE(p_page_size, 50), 1);
  v_offset INT := GREATEST((COALESCE(p_page, 1) - 1) * v_limit, 0);
  v_total BIGINT := 0;
  v_data JSONB := '[]'::jsonb;
  v_kanban_result JSONB;
  v_max_array_size INT := 100;
  v_sanitized_q TEXT;
BEGIN
  v_is_global := v_role IN ('global', 'admin');

  IF p_view_mode NOT IN ('table', 'kanban') THEN
    RAISE EXCEPTION 'Invalid view_mode: must be ''table'' or ''kanban''';
  END IF;

  p_per_column_limit := LEAST(GREATEST(COALESCE(p_per_column_limit, 30), 1), 100);

  IF p_types IS NOT NULL AND array_length(p_types, 1) > v_max_array_size THEN
    RAISE EXCEPTION 'p_types array exceeds maximum size of %', v_max_array_size;
  END IF;
  IF p_assignee_ids IS NOT NULL AND array_length(p_assignee_ids, 1) > v_max_array_size THEN
    RAISE EXCEPTION 'p_assignee_ids array exceeds maximum size of %', v_max_array_size;
  END IF;
  IF p_statuses IS NOT NULL AND array_length(p_statuses, 1) > v_max_array_size THEN
    RAISE EXCEPTION 'p_statuses array exceeds maximum size of %', v_max_array_size;
  END IF;

  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  IF v_is_global THEN
    v_effective_donvi := p_don_vi;
  ELSE
    v_allowed := public.allowed_don_vi_for_session();
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      IF p_view_mode = 'kanban' THEN
        RETURN jsonb_build_object('columns', '{}'::jsonb, 'totalCount', 0);
      ELSE
        RETURN jsonb_build_object('data', '[]'::jsonb, 'total', 0, 'page', p_page, 'pageSize', p_page_size);
      END IF;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF p_don_vi = ANY(v_allowed) THEN
        v_effective_donvi := p_don_vi;
      ELSE
        IF p_view_mode = 'kanban' THEN
          RETURN jsonb_build_object('columns', '{}'::jsonb, 'totalCount', 0);
        ELSE
          RETURN jsonb_build_object('data', '[]'::jsonb, 'total', 0, 'page', p_page, 'pageSize', p_page_size);
        END IF;
      END IF;
    END IF;
  END IF;

  IF p_view_mode = 'kanban' THEN
    WITH active_statuses AS (
      SELECT status FROM (
        SELECT unnest(
          CASE
            WHEN p_exclude_completed THEN ARRAY['cho_duyet', 'da_duyet', 'dang_luan_chuyen', 'da_ban_giao']::TEXT[]
            ELSE ARRAY['cho_duyet', 'da_duyet', 'dang_luan_chuyen', 'da_ban_giao', 'hoan_thanh']::TEXT[]
          END
        ) AS status
      ) base
      WHERE p_statuses IS NULL OR status = ANY(p_statuses)
    ),
    status_counts AS (
      SELECT
        yclc.trang_thai as status,
        COUNT(*) as total_count
      FROM public.yeu_cau_luan_chuyen yclc
      LEFT JOIN public.thiet_bi tb ON tb.id = yclc.thiet_bi_id
      WHERE yclc.trang_thai = ANY(SELECT status FROM active_statuses)
        AND (p_statuses IS NULL OR yclc.trang_thai = ANY(p_statuses))
        AND (
          (v_is_global AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)) OR
          (NOT v_is_global AND ((v_effective_donvi IS NOT NULL AND tb.don_vi = v_effective_donvi) OR (v_effective_donvi IS NULL AND tb.don_vi = ANY(v_allowed))))
        )
        AND (p_types IS NULL OR yclc.loai_hinh = ANY(p_types))
        AND (p_assignee_ids IS NULL OR yclc.nguoi_yeu_cau_id = ANY(p_assignee_ids))
        AND (
          v_sanitized_q IS NULL OR
          yclc.ma_yeu_cau ILIKE '%' || v_sanitized_q || '%' OR
          yclc.ly_do_luan_chuyen ILIKE '%' || v_sanitized_q || '%' OR
          tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%' OR
          tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
        )
        AND (p_date_from IS NULL OR yclc.created_at >= (p_date_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
        AND (p_date_to IS NULL OR yclc.created_at < ((p_date_to + interval '1 day')::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
      GROUP BY yclc.trang_thai
    ),
    status_groups AS (
      SELECT
        s.status,
        COALESCE(sc.total_count, 0) as total_count,
        COALESCE(jsonb_agg(lateral_data.row_data ORDER BY lateral_data.created_at DESC) FILTER (WHERE lateral_data.row_data IS NOT NULL), '[]'::jsonb) as tasks
      FROM active_statuses s
      LEFT JOIN status_counts sc ON sc.status = s.status
      LEFT JOIN LATERAL (
        SELECT
          jsonb_build_object(
            'id', yclc.id,
            'ma_yeu_cau', yclc.ma_yeu_cau,
            'thiet_bi_id', yclc.thiet_bi_id,
            'loai_hinh', yclc.loai_hinh,
            'trang_thai', yclc.trang_thai,
            'nguoi_yeu_cau_id', yclc.nguoi_yeu_cau_id,
            'ly_do_luan_chuyen', yclc.ly_do_luan_chuyen,
            'khoa_phong_hien_tai', yclc.khoa_phong_hien_tai,
            'khoa_phong_nhan', yclc.khoa_phong_nhan,
            'muc_dich', yclc.muc_dich,
            'don_vi_nhan', yclc.don_vi_nhan,
            'dia_chi_don_vi', yclc.dia_chi_don_vi,
            'nguoi_lien_he', yclc.nguoi_lien_he,
            'so_dien_thoai', yclc.so_dien_thoai,
            'ngay_du_kien_tra', yclc.ngay_du_kien_tra,
            'ngay_ban_giao', yclc.ngay_ban_giao,
            'ngay_hoan_tra', yclc.ngay_hoan_tra,
            'ngay_hoan_thanh', yclc.ngay_hoan_thanh,
            'nguoi_duyet_id', yclc.nguoi_duyet_id,
            'ngay_duyet', yclc.ngay_duyet,
            'ghi_chu_duyet', yclc.ghi_chu_duyet,
            'created_at', yclc.created_at,
            'updated_at', yclc.updated_at,
            'created_by', yclc.created_by,
            'updated_by', yclc.updated_by,
            'equipment_is_deleted', tb.is_deleted,
            'thiet_bi', jsonb_build_object(
              'ten_thiet_bi', tb.ten_thiet_bi,
              'ma_thiet_bi', tb.ma_thiet_bi,
              'model', tb.model,
              'serial', tb.serial,
              'khoa_phong_quan_ly', tb.khoa_phong_quan_ly,
              'facility_name', dv.name,
              'facility_id', dv.id,
              'is_deleted', tb.is_deleted
            )
          ) AS row_data,
          yclc.created_at
        FROM public.yeu_cau_luan_chuyen yclc
        LEFT JOIN public.thiet_bi tb ON tb.id = yclc.thiet_bi_id
        LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
        WHERE yclc.trang_thai = s.status
          AND (p_statuses IS NULL OR yclc.trang_thai = ANY(p_statuses))
          AND (
            (v_is_global AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)) OR
            (NOT v_is_global AND ((v_effective_donvi IS NOT NULL AND tb.don_vi = v_effective_donvi) OR (v_effective_donvi IS NULL AND tb.don_vi = ANY(v_allowed))))
          )
          AND (p_types IS NULL OR yclc.loai_hinh = ANY(p_types))
          AND (p_assignee_ids IS NULL OR yclc.nguoi_yeu_cau_id = ANY(p_assignee_ids))
          AND (
            v_sanitized_q IS NULL OR
            yclc.ma_yeu_cau ILIKE '%' || v_sanitized_q || '%' OR
            yclc.ly_do_luan_chuyen ILIKE '%' || v_sanitized_q || '%' OR
            tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%' OR
            tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
          )
          AND (p_date_from IS NULL OR yclc.created_at >= (p_date_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
          AND (p_date_to IS NULL OR yclc.created_at < ((p_date_to + interval '1 day')::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
        ORDER BY yclc.created_at DESC
        LIMIT p_per_column_limit
      ) lateral_data ON true
      GROUP BY s.status, sc.total_count
    )
    SELECT jsonb_build_object(
      'columns', COALESCE(jsonb_object_agg(status, jsonb_build_object(
        'tasks', COALESCE(tasks, '[]'::jsonb),
        'total', total_count,
        'hasMore', total_count > p_per_column_limit
      )), '{}'::jsonb),
      'totalCount', (SELECT COALESCE(SUM(total_count), 0) FROM status_groups)
    ) INTO v_kanban_result
    FROM status_groups;

    RETURN v_kanban_result;
  END IF;

  SELECT count(*) INTO v_total
  FROM public.yeu_cau_luan_chuyen yclc
  LEFT JOIN public.thiet_bi tb ON tb.id = yclc.thiet_bi_id
  LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
  WHERE (
    (v_is_global AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)) OR
    (NOT v_is_global AND ((v_effective_donvi IS NOT NULL AND tb.don_vi = v_effective_donvi) OR (v_effective_donvi IS NULL AND tb.don_vi = ANY(v_allowed))))
  )
  AND (p_statuses IS NULL OR yclc.trang_thai = ANY(p_statuses))
  AND (p_types IS NULL OR yclc.loai_hinh = ANY(p_types))
  AND (p_assignee_ids IS NULL OR yclc.nguoi_yeu_cau_id = ANY(p_assignee_ids))
  AND (
    v_sanitized_q IS NULL OR
    yclc.ma_yeu_cau ILIKE '%' || v_sanitized_q || '%' OR
    yclc.ly_do_luan_chuyen ILIKE '%' || v_sanitized_q || '%' OR
    tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%' OR
    tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
  )
  AND (p_date_from IS NULL OR yclc.created_at >= (p_date_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
  AND (p_date_to IS NULL OR yclc.created_at < ((p_date_to + interval '1 day')::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'));

  SELECT COALESCE(jsonb_agg(row_data ORDER BY created_at DESC), '[]'::jsonb) INTO v_data
  FROM (
    SELECT jsonb_build_object(
      'id', yclc.id,
      'ma_yeu_cau', yclc.ma_yeu_cau,
      'thiet_bi_id', yclc.thiet_bi_id,
      'loai_hinh', yclc.loai_hinh,
      'trang_thai', yclc.trang_thai,
      'nguoi_yeu_cau_id', yclc.nguoi_yeu_cau_id,
      'ly_do_luan_chuyen', yclc.ly_do_luan_chuyen,
      'khoa_phong_hien_tai', yclc.khoa_phong_hien_tai,
      'khoa_phong_nhan', yclc.khoa_phong_nhan,
      'muc_dich', yclc.muc_dich,
      'don_vi_nhan', yclc.don_vi_nhan,
      'dia_chi_don_vi', yclc.dia_chi_don_vi,
      'nguoi_lien_he', yclc.nguoi_lien_he,
      'so_dien_thoai', yclc.so_dien_thoai,
      'ngay_du_kien_tra', yclc.ngay_du_kien_tra,
      'ngay_ban_giao', yclc.ngay_ban_giao,
      'ngay_hoan_tra', yclc.ngay_hoan_tra,
      'ngay_hoan_thanh', yclc.ngay_hoan_thanh,
      'nguoi_duyet_id', yclc.nguoi_duyet_id,
      'ngay_duyet', yclc.ngay_duyet,
      'ghi_chu_duyet', yclc.ghi_chu_duyet,
      'created_at', yclc.created_at,
      'updated_at', yclc.updated_at,
      'created_by', yclc.created_by,
      'updated_by', yclc.updated_by,
      'equipment_is_deleted', tb.is_deleted,
      'thiet_bi', jsonb_build_object(
        'ten_thiet_bi', tb.ten_thiet_bi,
        'ma_thiet_bi', tb.ma_thiet_bi,
        'model', tb.model,
        'serial', tb.serial,
        'khoa_phong_quan_ly', tb.khoa_phong_quan_ly,
        'facility_name', dv.name,
        'facility_id', dv.id,
        'is_deleted', tb.is_deleted
      )
    ) AS row_data,
    yclc.created_at
    FROM public.yeu_cau_luan_chuyen yclc
    LEFT JOIN public.thiet_bi tb ON tb.id = yclc.thiet_bi_id
    LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
    WHERE (
      (v_is_global AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)) OR
      (NOT v_is_global AND ((v_effective_donvi IS NOT NULL AND tb.don_vi = v_effective_donvi) OR (v_effective_donvi IS NULL AND tb.don_vi = ANY(v_allowed))))
    )
    AND (p_statuses IS NULL OR yclc.trang_thai = ANY(p_statuses))
    AND (p_types IS NULL OR yclc.loai_hinh = ANY(p_types))
    AND (p_assignee_ids IS NULL OR yclc.nguoi_yeu_cau_id = ANY(p_assignee_ids))
    AND (
      v_sanitized_q IS NULL OR
      yclc.ma_yeu_cau ILIKE '%' || v_sanitized_q || '%' OR
      yclc.ly_do_luan_chuyen ILIKE '%' || v_sanitized_q || '%' OR
      tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%' OR
      tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
    )
    AND (p_date_from IS NULL OR yclc.created_at >= (p_date_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
    AND (p_date_to IS NULL OR yclc.created_at < ((p_date_to + interval '1 day')::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
    ORDER BY yclc.created_at DESC
    LIMIT v_limit
    OFFSET v_offset
  ) subquery;

  RETURN jsonb_build_object(
    'data', v_data,
    'total', v_total,
    'page', p_page,
    'pageSize', p_page_size
  );
END;
$$;


ALTER FUNCTION public.transfer_request_list(p_q text, p_statuses text[], p_types text[], p_page integer, p_page_size integer, p_don_vi bigint, p_date_from date, p_date_to date, p_assignee_ids bigint[], p_view_mode text, p_per_column_limit integer, p_exclude_completed boolean) OWNER TO postgres;

--
-- Name: FUNCTION transfer_request_list(p_q text, p_statuses text[], p_types text[], p_page integer, p_page_size integer, p_don_vi bigint, p_date_from date, p_date_to date, p_assignee_ids bigint[], p_view_mode text, p_per_column_limit integer, p_exclude_completed boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.transfer_request_list(p_q text, p_statuses text[], p_types text[], p_page integer, p_page_size integer, p_don_vi bigint, p_date_from date, p_date_to date, p_assignee_ids bigint[], p_view_mode text, p_per_column_limit integer, p_exclude_completed boolean) IS 'Unified transfer list function with P0 security fixes: ILIKE sanitization and array size validation';


--
-- Name: transfer_request_list_enhanced(text, text, integer, integer, bigint, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_list_enhanced(p_q text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 100, p_don_vi bigint DEFAULT NULL::bigint, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_khoa_phong text DEFAULT NULL::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_user_id text;
  v_is_global boolean := false;
  v_allowed bigint[];
  v_effective_donvi bigint;
  v_effective bigint[] := NULL;
  v_limit int := GREATEST(COALESCE(p_page_size, 100), 1);
  v_offset int;
  v_sanitized_q text := NULL;
  v_department_scope text;
  v_requested_department_scope text;
BEGIN
  v_role := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id := NULLIF(public._get_jwt_claim('user_id'), '');
  v_is_global := v_role IN ('global', 'admin');
  v_allowed := public.allowed_don_vi_for_session_safe();
  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING ERRCODE = '42501';
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    END IF;
  ELSIF v_role = 'regional_leader' THEN
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF p_don_vi = ANY(v_allowed) THEN
        v_effective := ARRAY[p_don_vi];
      ELSE
        RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
      END IF;
    ELSE
      v_effective := v_allowed;
    END IF;
  ELSE
    v_effective_donvi := NULLIF(public._get_jwt_claim('don_vi'), '')::bigint;
    IF v_effective_donvi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim for role %', v_role USING ERRCODE = '42501';
    END IF;
    IF p_don_vi IS NOT NULL AND p_don_vi != v_effective_donvi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING ERRCODE = '42501';
    END IF;
    v_effective := ARRAY[v_effective_donvi];
  END IF;

  IF v_role = 'user' THEN
    v_department_scope := public._normalize_department_scope(public._get_jwt_claim('khoa_phong'));
    IF v_department_scope IS NULL THEN
      RETURN;
    END IF;

    IF p_khoa_phong IS NOT NULL THEN
      v_requested_department_scope := public._normalize_department_scope(p_khoa_phong);
      IF v_requested_department_scope IS DISTINCT FROM v_department_scope THEN
        RETURN;
      END IF;
    END IF;
  END IF;

  v_offset := GREATEST((COALESCE(p_page, 1) - 1), 0) * v_limit;

  RETURN QUERY
  SELECT to_jsonb(row) FROM (
    SELECT
      yc.*,
      tb.is_deleted AS equipment_is_deleted,
      jsonb_build_object(
        'id', tb.id,
        'ma_thiet_bi', tb.ma_thiet_bi,
        'ten_thiet_bi', tb.ten_thiet_bi,
        'model', tb.model,
        'serial', tb.serial,
        'khoa_phong_quan_ly', tb.khoa_phong_quan_ly,
        'don_vi', tb.don_vi,
        'is_deleted', tb.is_deleted
      ) AS thiet_bi
    FROM public.yeu_cau_luan_chuyen yc
    LEFT JOIN public.thiet_bi tb ON yc.thiet_bi_id = tb.id
    WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
      AND (
        (v_role = 'user' AND public._normalize_department_scope(tb.khoa_phong_quan_ly) = v_department_scope)
        OR
        (v_role <> 'user' AND (p_khoa_phong IS NULL OR tb.khoa_phong_quan_ly = p_khoa_phong))
      )
      AND (p_status IS NULL OR yc.trang_thai = p_status)
      AND (p_date_from IS NULL OR yc.created_at::date >= p_date_from)
      AND (p_date_to IS NULL OR yc.created_at::date <= p_date_to)
      AND (
        v_sanitized_q IS NULL OR (
          yc.ma_yeu_cau ILIKE '%' || v_sanitized_q || '%' OR
          yc.ly_do_luan_chuyen ILIKE '%' || v_sanitized_q || '%' OR
          tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%' OR
          tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
        )
      )
    ORDER BY yc.created_at DESC
    OFFSET v_offset LIMIT v_limit
  ) row;
END;
$$;


ALTER FUNCTION public.transfer_request_list_enhanced(p_q text, p_status text, p_page integer, p_page_size integer, p_don_vi bigint, p_date_from date, p_date_to date, p_khoa_phong text) OWNER TO postgres;

--
-- Name: FUNCTION transfer_request_list_enhanced(p_q text, p_status text, p_page integer, p_page_size integer, p_don_vi bigint, p_date_from date, p_date_to date, p_khoa_phong text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.transfer_request_list_enhanced(p_q text, p_status text, p_page integer, p_page_size integer, p_don_vi bigint, p_date_from date, p_date_to date, p_khoa_phong text) IS 'Returns transfer requests with equipment details and filtering support.
FIXED: Added regional_leader support with allowed_don_vi_for_session_safe() validation.';


--
-- Name: transfer_request_page_data(text, text[], text[], integer, integer, bigint, date, date, bigint[], text, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_page_data(p_q text DEFAULT NULL::text, p_statuses text[] DEFAULT NULL::text[], p_types text[] DEFAULT NULL::text[], p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_don_vi bigint DEFAULT NULL::bigint, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_assignee_ids bigint[] DEFAULT NULL::bigint[], p_view_mode text DEFAULT 'table'::text, p_per_column_limit integer DEFAULT 30, p_exclude_completed boolean DEFAULT false, p_include_counts boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id text := NULLIF(COALESCE(public._get_jwt_claim('user_id'), public._get_jwt_claim('sub')), '');
  v_view_mode text := COALESCE(p_view_mode, 'table');
  v_is_global boolean := false;
  v_effective_donvi bigint := NULL;
  v_allowed bigint[] := NULL;
  v_has_scope boolean := true;
  v_sanitized_q text := NULL;
  v_today date := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_list jsonb := NULL;
  v_kanban jsonb := NULL;
  v_counts_raw jsonb := NULL;
  v_counts jsonb := NULL;
  v_total_count bigint := 0;
  v_overdue_summary jsonb := jsonb_build_object(
    'total', 0,
    'overdue', 0,
    'due_today', 0,
    'due_soon', 0,
    'items', '[]'::jsonb
  );
BEGIN
  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF v_view_mode NOT IN ('table', 'kanban') THEN
    RAISE EXCEPTION 'Invalid view mode: %', v_view_mode USING ERRCODE = '22023';
  END IF;

  p_per_column_limit := LEAST(GREATEST(COALESCE(p_per_column_limit, 30), 1), 100);
  v_is_global := v_role IN ('global', 'admin');
  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  IF v_is_global THEN
    v_effective_donvi := p_don_vi;
  ELSE
    v_allowed := public.allowed_don_vi_for_session();
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      v_has_scope := false;
    ELSIF p_don_vi IS NOT NULL THEN
      IF p_don_vi = ANY(v_allowed) THEN
        v_effective_donvi := p_don_vi;
      ELSE
        v_has_scope := false;
      END IF;
    END IF;
  END IF;

  IF p_include_counts THEN
    v_counts_raw := public.transfer_request_counts(
      p_q,
      p_don_vi,
      p_date_from,
      p_date_to,
      p_types,
      p_assignee_ids
    );

    v_total_count :=
      COALESCE((v_counts_raw->>'cho_duyet')::bigint, 0) +
      COALESCE((v_counts_raw->>'da_duyet')::bigint, 0) +
      COALESCE((v_counts_raw->>'dang_luan_chuyen')::bigint, 0) +
      COALESCE((v_counts_raw->>'da_ban_giao')::bigint, 0) +
      COALESCE((v_counts_raw->>'hoan_thanh')::bigint, 0);

    v_counts := jsonb_build_object(
      'totalCount', v_total_count,
      'columnCounts', jsonb_build_object(
        'cho_duyet', COALESCE((v_counts_raw->>'cho_duyet')::integer, 0),
        'da_duyet', COALESCE((v_counts_raw->>'da_duyet')::integer, 0),
        'dang_luan_chuyen', COALESCE((v_counts_raw->>'dang_luan_chuyen')::integer, 0),
        'da_ban_giao', COALESCE((v_counts_raw->>'da_ban_giao')::integer, 0),
        'hoan_thanh', COALESCE((v_counts_raw->>'hoan_thanh')::integer, 0)
      )
    );
  END IF;

  IF v_has_scope THEN
    WITH filtered AS (
      SELECT
        yclc.id,
        yclc.ma_yeu_cau,
        yclc.thiet_bi_id,
        yclc.loai_hinh,
        yclc.trang_thai,
        yclc.nguoi_yeu_cau_id,
        yclc.ly_do_luan_chuyen,
        yclc.khoa_phong_hien_tai,
        yclc.khoa_phong_nhan,
        yclc.muc_dich,
        yclc.don_vi_nhan,
        yclc.dia_chi_don_vi,
        yclc.nguoi_lien_he,
        yclc.so_dien_thoai,
        yclc.ngay_du_kien_tra,
        yclc.ngay_ban_giao,
        yclc.ngay_hoan_tra,
        yclc.ngay_hoan_thanh,
        yclc.nguoi_duyet_id,
        yclc.ngay_duyet,
        yclc.ghi_chu_duyet,
        yclc.created_at,
        yclc.updated_at,
        yclc.created_by,
        yclc.updated_by,
        tb.ten_thiet_bi,
        tb.ma_thiet_bi,
        tb.model,
        tb.serial,
        tb.khoa_phong_quan_ly,
        tb.is_deleted,
        dv.name AS facility_name,
        dv.id AS facility_id
      FROM public.yeu_cau_luan_chuyen yclc
      LEFT JOIN public.thiet_bi tb ON tb.id = yclc.thiet_bi_id
      LEFT JOIN public.don_vi dv ON dv.id = tb.don_vi
      WHERE (
        (v_is_global AND (v_effective_donvi IS NULL OR tb.don_vi = v_effective_donvi)) OR
        (
          NOT v_is_global
          AND (
            (v_effective_donvi IS NOT NULL AND tb.don_vi = v_effective_donvi) OR
            (v_effective_donvi IS NULL AND tb.don_vi = ANY(v_allowed))
          )
        )
      )
      AND (p_statuses IS NULL OR yclc.trang_thai = ANY(p_statuses))
      AND (p_types IS NULL OR yclc.loai_hinh = ANY(p_types))
      AND (p_assignee_ids IS NULL OR yclc.nguoi_yeu_cau_id = ANY(p_assignee_ids))
      AND (
        v_sanitized_q IS NULL OR
        yclc.ma_yeu_cau ILIKE '%' || v_sanitized_q || '%' OR
        yclc.ly_do_luan_chuyen ILIKE '%' || v_sanitized_q || '%' OR
        tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%' OR
        tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
      )
      AND (p_date_from IS NULL OR yclc.created_at >= (p_date_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
      AND (p_date_to IS NULL OR yclc.created_at < ((p_date_to + interval '1 day')::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
    ),
    due_items AS (
      SELECT
        *,
        ((ngay_du_kien_tra AT TIME ZONE 'Asia/Ho_Chi_Minh')::date - v_today) AS days_difference
      FROM filtered
      WHERE loai_hinh = 'ben_ngoai'
        AND trang_thai IN ('da_ban_giao', 'dang_luan_chuyen')
        AND ngay_du_kien_tra IS NOT NULL
        AND (ngay_du_kien_tra AT TIME ZONE 'Asia/Ho_Chi_Minh')::date <= v_today + 7
    ),
    due_aggregated AS (
      SELECT
        count(*) AS total_count,
        count(*) FILTER (WHERE days_difference < 0) AS overdue_count,
        count(*) FILTER (WHERE days_difference = 0) AS due_today_count,
        count(*) FILTER (WHERE days_difference BETWEEN 1 AND 7) AS due_soon_count
      FROM due_items
    ),
    ranked_items AS (
      SELECT *
      FROM due_items
      ORDER BY (ngay_du_kien_tra AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ASC, id ASC
      LIMIT 50
    )
    SELECT jsonb_build_object(
      'total', COALESCE(due_aggregated.total_count, 0),
      'overdue', COALESCE(due_aggregated.overdue_count, 0),
      'due_today', COALESCE(due_aggregated.due_today_count, 0),
      'due_soon', COALESCE(due_aggregated.due_soon_count, 0),
      'items', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', id,
            'ma_yeu_cau', ma_yeu_cau,
            'thiet_bi_id', thiet_bi_id,
            'loai_hinh', loai_hinh,
            'trang_thai', trang_thai,
            'nguoi_yeu_cau_id', nguoi_yeu_cau_id,
            'ly_do_luan_chuyen', ly_do_luan_chuyen,
            'khoa_phong_hien_tai', khoa_phong_hien_tai,
            'khoa_phong_nhan', khoa_phong_nhan,
            'muc_dich', muc_dich,
            'don_vi_nhan', don_vi_nhan,
            'dia_chi_don_vi', dia_chi_don_vi,
            'nguoi_lien_he', nguoi_lien_he,
            'so_dien_thoai', so_dien_thoai,
            'ngay_du_kien_tra', ngay_du_kien_tra,
            'ngay_ban_giao', ngay_ban_giao,
            'ngay_hoan_tra', ngay_hoan_tra,
            'ngay_hoan_thanh', ngay_hoan_thanh,
            'nguoi_duyet_id', nguoi_duyet_id,
            'ngay_duyet', ngay_duyet,
            'ghi_chu_duyet', ghi_chu_duyet,
            'created_at', created_at,
            'updated_at', updated_at,
            'created_by', created_by,
            'updated_by', updated_by,
            'equipment_is_deleted', is_deleted,
            'days_difference', days_difference,
            'thiet_bi', jsonb_build_object(
              'ten_thiet_bi', ten_thiet_bi,
              'ma_thiet_bi', ma_thiet_bi,
              'model', model,
              'serial', serial,
              'khoa_phong_quan_ly', khoa_phong_quan_ly,
              'facility_name', facility_name,
              'facility_id', facility_id,
              'is_deleted', is_deleted
            )
          )
          ORDER BY (ngay_du_kien_tra AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ASC, id ASC
        )
        FROM ranked_items
      ), '[]'::jsonb)
    )
    INTO v_overdue_summary
    FROM due_aggregated;
  END IF;

  IF v_view_mode = 'kanban' THEN
    v_kanban := public.transfer_request_list(
      p_q,
      NULL,
      p_types,
      p_page,
      p_page_size,
      p_don_vi,
      p_date_from,
      p_date_to,
      p_assignee_ids,
      'kanban',
      p_per_column_limit,
      p_exclude_completed
    );
  ELSE
    v_list := public.transfer_request_list(
      p_q,
      p_statuses,
      p_types,
      p_page,
      p_page_size,
      p_don_vi,
      p_date_from,
      p_date_to,
      p_assignee_ids,
      'table',
      p_per_column_limit,
      p_exclude_completed
    );
  END IF;

  RETURN jsonb_build_object(
    'viewMode', v_view_mode,
    'list', v_list,
    'counts', v_counts,
    'kanban', v_kanban,
    'overdue_summary', v_overdue_summary
  );
END;
$$;


ALTER FUNCTION public.transfer_request_page_data(p_q text, p_statuses text[], p_types text[], p_page integer, p_page_size integer, p_don_vi bigint, p_date_from date, p_date_to date, p_assignee_ids bigint[], p_view_mode text, p_per_column_limit integer, p_exclude_completed boolean, p_include_counts boolean) OWNER TO postgres;

--
-- Name: transfer_request_update(integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_update(p_id integer, p_data jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_req record;
  v_claims jsonb;
  v_role text;
  v_is_global boolean := false;
  v_don_vi text;
  v_tb_don_vi text;
  v_user_id int;
  v_new_thiet_bi_id integer;
  v_target_tb record;
BEGIN
  v_claims := coalesce(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_role := lower(coalesce(nullif(v_claims->>'app_role', ''), nullif(v_claims->>'role', '')));
  v_is_global := v_role in ('global', 'admin');
  v_don_vi := nullif(v_claims->>'don_vi', '');
  v_user_id := nullif(v_claims->>'user_id', '')::int;

  if v_role is null or v_role = '' then
    raise exception 'Missing role claim in JWT' using errcode = '42501';
  end if;

  if v_user_id is null then
    raise exception 'Missing user_id claim in JWT' using errcode = '42501';
  end if;

  if not v_is_global and v_don_vi is null then
    raise exception 'Missing don_vi claim in JWT for non-global user' using errcode = '42501';
  end if;

  if v_role = 'regional_leader' then
    raise exception 'Regional leaders have read-only access to transfers' using errcode = '42501';
  end if;

  select t.*, tb.don_vi as tb_don_vi
  into v_req
  from public.yeu_cau_luan_chuyen t
  join public.thiet_bi tb on tb.id = t.thiet_bi_id
  where t.id = p_id
  for update of t;

  if not found then
    raise exception 'Yêu cầu không tồn tại';
  end if;

  v_tb_don_vi := v_req.tb_don_vi;

  if not v_is_global and v_tb_don_vi is distinct from v_don_vi then
    raise exception 'Không có quyền trên thiết bị thuộc đơn vị khác';
  end if;

  if v_req.trang_thai not in ('cho_duyet', 'da_duyet') then
    raise exception 'Chỉ có thể chỉnh sửa khi yêu cầu ở trạng thái Chờ duyệt hoặc Đã duyệt';
  end if;

  v_new_thiet_bi_id := nullif(p_data->>'thiet_bi_id', '')::int;

  if v_new_thiet_bi_id is not null and v_new_thiet_bi_id is distinct from v_req.thiet_bi_id then
    select tb.id, tb.don_vi
    into v_target_tb
    from public.thiet_bi tb
    where tb.id = v_new_thiet_bi_id
      and tb.is_deleted = false
    for update;

    if not found then
      raise exception 'Thiết bị không tồn tại' using errcode = 'P0002';
    end if;

    if not v_is_global and v_target_tb.don_vi::text is distinct from v_don_vi then
      raise exception 'Không có quyền trên thiết bị thuộc đơn vị khác';
    end if;
  end if;

  update public.yeu_cau_luan_chuyen set
    thiet_bi_id = coalesce(v_new_thiet_bi_id, thiet_bi_id),
    loai_hinh = coalesce(nullif(p_data->>'loai_hinh', ''), loai_hinh),
    ly_do_luan_chuyen = coalesce(nullif(p_data->>'ly_do_luan_chuyen', ''), ly_do_luan_chuyen),
    khoa_phong_hien_tai = case
      when p_data ? 'loai_hinh' and nullif(p_data->>'loai_hinh', '') is not null then
        case
          when p_data->>'loai_hinh' = 'noi_bo' then nullif(p_data->>'khoa_phong_hien_tai', '')
          else null
        end
      else khoa_phong_hien_tai
    end,
    khoa_phong_nhan = case
      when p_data ? 'loai_hinh' and nullif(p_data->>'loai_hinh', '') is not null then
        case
          when p_data->>'loai_hinh' = 'noi_bo' then nullif(p_data->>'khoa_phong_nhan', '')
          else null
        end
      else khoa_phong_nhan
    end,
    muc_dich = case
      when p_data ? 'loai_hinh' and nullif(p_data->>'loai_hinh', '') is not null then
        case
          when p_data->>'loai_hinh' <> 'noi_bo' then nullif(p_data->>'muc_dich', '')
          else null
        end
      else muc_dich
    end,
    don_vi_nhan = case
      when p_data ? 'loai_hinh' and nullif(p_data->>'loai_hinh', '') is not null then
        case
          when p_data->>'loai_hinh' <> 'noi_bo' then nullif(p_data->>'don_vi_nhan', '')
          else null
        end
      else don_vi_nhan
    end,
    dia_chi_don_vi = case
      when p_data ? 'loai_hinh' and nullif(p_data->>'loai_hinh', '') is not null then
        case
          when p_data->>'loai_hinh' <> 'noi_bo' then nullif(p_data->>'dia_chi_don_vi', '')
          else null
        end
      else dia_chi_don_vi
    end,
    nguoi_lien_he = case
      when p_data ? 'loai_hinh' and nullif(p_data->>'loai_hinh', '') is not null then
        case
          when p_data->>'loai_hinh' <> 'noi_bo' then nullif(p_data->>'nguoi_lien_he', '')
          else null
        end
      else nguoi_lien_he
    end,
    so_dien_thoai = case
      when p_data ? 'loai_hinh' and nullif(p_data->>'loai_hinh', '') is not null then
        case
          when p_data->>'loai_hinh' <> 'noi_bo' then nullif(p_data->>'so_dien_thoai', '')
          else null
        end
      else so_dien_thoai
    end,
    ngay_du_kien_tra = case
      when p_data ? 'loai_hinh' and nullif(p_data->>'loai_hinh', '') is not null then
        case
          when p_data->>'loai_hinh' <> 'noi_bo'
            and coalesce(p_data->>'ngay_du_kien_tra', '') <> ''
            then (p_data->>'ngay_du_kien_tra')::date
          else null
        end
      else ngay_du_kien_tra
    end,
    updated_by = v_user_id,
    updated_at = now()
  where id = p_id;

  -- FIX: strip client-supplied identity fields before auditing, consistent with
  -- transfer_request_create which strips created_by/updated_by/nguoi_yeu_cau_id.
  -- Prevents spoofed updated_by/updated_at appearing in action_details.
  perform public.audit_log(
    'transfer_request_update',
    'transfer_request',
    p_id,
    v_req.ma_yeu_cau,
    p_data - 'updated_by' - 'updated_at'
  );
END;
$$;


ALTER FUNCTION public.transfer_request_update(p_id integer, p_data jsonb) OWNER TO postgres;

--
-- Name: transfer_request_update_status(integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_request_update_status(p_id integer, p_status text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_claims jsonb;
  v_role text;
  v_is_global boolean := false;
  v_don_vi text;
  v_user_id_text text;
  v_user_id bigint;
  v_req record;
BEGIN
  v_claims := coalesce(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_role := lower(coalesce(nullif(v_claims->>'app_role', ''), nullif(v_claims->>'role', '')));
  v_is_global := v_role in ('global', 'admin');
  v_don_vi := nullif(v_claims->>'don_vi', '');
  v_user_id_text := nullif(v_claims->>'user_id', '');
  v_user_id := CASE
    WHEN v_user_id_text ~ '^[0-9]+$' THEN v_user_id_text::bigint
    ELSE NULL
  END;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim in JWT for non-global user' USING errcode = '42501';
  END IF;

  IF v_role = 'regional_leader' THEN
    RAISE EXCEPTION 'Regional leaders have read-only access to transfers' USING errcode = '42501';
  END IF;

  SELECT
    t.*,
    tb.don_vi AS tb_don_vi
  INTO v_req
  FROM public.yeu_cau_luan_chuyen t
  JOIN public.thiet_bi tb ON tb.id = t.thiet_bi_id
  WHERE t.id = p_id
  FOR UPDATE OF t, tb;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Yêu cầu không tồn tại';
  END IF;

  IF NOT v_is_global AND v_req.tb_don_vi::text IS DISTINCT FROM v_don_vi THEN
    RAISE EXCEPTION 'Không có quyền trên yêu cầu thuộc đơn vị khác' USING errcode = '42501';
  END IF;

  IF p_status IS NULL THEN
    RAISE EXCEPTION 'p_status is required' USING errcode = '22023';
  END IF;

  IF v_req.trang_thai = 'hoan_thanh' AND p_status <> 'hoan_thanh' THEN
    RAISE EXCEPTION 'Không thể thay đổi trạng thái của yêu cầu đã hoàn thành' USING errcode = '22023';
  END IF;

  IF p_status = 'hoan_thanh' THEN
    RAISE EXCEPTION 'Hoàn thành yêu cầu phải dùng transfer_request_complete' USING errcode = '22023';
  END IF;

  IF p_status NOT IN ('da_duyet', 'dang_luan_chuyen', 'da_ban_giao') THEN
    RAISE EXCEPTION 'Trạng thái không hợp lệ: %', p_status USING errcode = '22023';
  END IF;

  -- Transition matrix: reject skipped or type-incompatible jumps.
  IF NOT (
    (v_req.trang_thai = 'cho_duyet' AND p_status = 'da_duyet')
    OR (
      v_req.loai_hinh IN ('noi_bo', 'ben_ngoai')
      AND v_req.trang_thai = 'da_duyet'
      AND p_status = 'dang_luan_chuyen'
    )
    OR (
      v_req.loai_hinh = 'ben_ngoai'
      AND v_req.trang_thai = 'dang_luan_chuyen'
      AND p_status = 'da_ban_giao'
    )
  ) THEN
    RAISE EXCEPTION 'Không thể chuyển từ % sang %', v_req.trang_thai, p_status
      USING errcode = '22023';
  END IF;

  UPDATE public.yeu_cau_luan_chuyen
  SET trang_thai = p_status,
      updated_by = v_user_id,
      updated_at = now()
  WHERE id = p_id;

  IF p_status = 'da_duyet' THEN
    UPDATE public.yeu_cau_luan_chuyen
    SET nguoi_duyet_id = v_user_id,
        ngay_duyet = COALESCE((p_payload->>'ngay_duyet')::timestamptz, ngay_duyet, now()),
        updated_by = v_user_id,
        updated_at = now()
    WHERE id = p_id;
  ELSIF p_status IN ('dang_luan_chuyen', 'da_ban_giao') THEN
    UPDATE public.yeu_cau_luan_chuyen
    SET ngay_ban_giao = COALESCE((p_payload->>'ngay_ban_giao')::timestamptz, ngay_ban_giao, now()),
        updated_by = v_user_id,
        updated_at = now()
    WHERE id = p_id;
  END IF;

  -- External transfer outbound: mark equipment as "in external transit"
  IF p_status = 'dang_luan_chuyen' AND v_req.loai_hinh = 'ben_ngoai' THEN
    UPDATE public.thiet_bi
    SET vi_tri_lap_dat = 'Đang luân chuyển bên ngoài'
    WHERE id = v_req.thiet_bi_id;
  END IF;
  -- da_ban_giao: no location change needed (stays as 'Đang luân chuyển bên ngoài')

  SELECT
    t.*,
    tb.don_vi AS tb_don_vi
  INTO v_req
  FROM public.yeu_cau_luan_chuyen t
  JOIN public.thiet_bi tb ON tb.id = t.thiet_bi_id
  WHERE t.id = p_id;

  IF p_status IN ('da_duyet', 'dang_luan_chuyen', 'da_ban_giao') THEN
    IF NOT public.audit_log(
      'transfer_request_update_status',
      'transfer_request',
      v_req.id,
      v_req.ma_yeu_cau,
      jsonb_build_object(
        'trang_thai', v_req.trang_thai,
        'loai_hinh', v_req.loai_hinh,
        'khoa_phong_hien_tai', v_req.khoa_phong_hien_tai,
        'khoa_phong_nhan', v_req.khoa_phong_nhan,
        'don_vi_nhan', v_req.don_vi_nhan,
        'ngay_duyet', v_req.ngay_duyet,
        'ngay_ban_giao', v_req.ngay_ban_giao
      )
    ) THEN
      RAISE EXCEPTION 'audit_log failed for transfer_request %', v_req.id;
    END IF;
  END IF;
END;
$_$;


ALTER FUNCTION public.transfer_request_update_status(p_id integer, p_status text, p_payload jsonb) OWNER TO postgres;

--
-- Name: FUNCTION transfer_request_update_status(p_id integer, p_status text, p_payload jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.transfer_request_update_status(p_id integer, p_status text, p_payload jsonb) IS 'Fixed: Cast v_don_vi from TEXT to BIGINT to match tb.don_vi type for proper comparison.
Resolves "operator does not exist: bigint = text" error during transfer approval.';


--
-- Name: unused_equipment_report_for_reports(bigint, text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unused_equipment_report_for_reports(p_don_vi bigint DEFAULT NULL::bigint, p_q text DEFAULT NULL::text, p_khoa_phong text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20, p_sort text DEFAULT 'ten_thiet_bi.asc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role text;
  v_user_id text;
  v_claim_don_vi bigint;
  v_allowed bigint[];
  v_effective_don_vi bigint;
  v_sort_col text;
  v_sort_dir text;
  v_order_sql text;
  v_limit integer;
  v_offset integer;
  v_sanitized_q text;
  v_pattern text;
  v_summary jsonb;
  v_top_device_groups jsonb;
  v_departments jsonb;
  v_department_options jsonb;
  v_items jsonb;
  v_total_count integer;
BEGIN
  v_role := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_user_id := nullif(public._get_jwt_claim('user_id'), '');
  v_claim_don_vi := nullif(public._get_jwt_claim('don_vi'), '')::bigint;

  IF v_role = '' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing required JWT claims' USING errcode = '42501';
  END IF;

  IF v_role IN ('global', 'admin') THEN
    IF p_don_vi IS NULL THEN
      RAISE EXCEPTION 'Facility selection is required' USING errcode = '42501';
    END IF;
    v_effective_don_vi := p_don_vi;
  ELSIF v_role = 'regional_leader' THEN
    IF p_don_vi IS NULL THEN
      RAISE EXCEPTION 'Facility selection is required' USING errcode = '42501';
    END IF;

    v_allowed := public.allowed_don_vi_for_session_safe();
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL OR NOT p_don_vi = ANY(v_allowed) THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING errcode = '42501';
    END IF;

    v_effective_don_vi := p_don_vi;
  ELSE
    IF v_claim_don_vi IS NULL THEN
      RAISE EXCEPTION 'Missing don_vi claim for role %', v_role USING errcode = '42501';
    END IF;

    IF p_don_vi IS NOT NULL AND p_don_vi <> v_claim_don_vi THEN
      RAISE EXCEPTION 'Access denied for facility %', p_don_vi USING errcode = '42501';
    END IF;

    v_effective_don_vi := v_claim_don_vi;
  END IF;

  v_sort_col := lower(split_part(coalesce(p_sort, 'ten_thiet_bi.asc'), '.', 1));
  v_sort_dir := CASE lower(split_part(coalesce(p_sort, 'ten_thiet_bi.asc'), '.', 2))
    WHEN 'desc' THEN 'DESC'
    ELSE 'ASC'
  END;

  IF v_sort_col NOT IN ('id', 'ma_thiet_bi', 'ten_thiet_bi', 'khoa_phong_quan_ly', 'ngay_nhap', 'gia_goc', 'created_at') THEN
    v_sort_col := 'ten_thiet_bi';
  END IF;

  v_order_sql := format('%I %s, id ASC', v_sort_col, v_sort_dir);
  v_limit := LEAST(GREATEST(coalesce(p_page_size, 20), 1), 100);
  v_offset := GREATEST(coalesce(p_page, 1) - 1, 0) * v_limit;
  v_sanitized_q := public._sanitize_ilike_pattern(lower(trim(coalesce(p_q, ''))));
  v_pattern := CASE WHEN v_sanitized_q IS NULL THEN NULL ELSE '%' || v_sanitized_q || '%' END;

  WITH base_filtered AS MATERIALIZED (
    SELECT
      tb.id,
      tb.ma_thiet_bi,
      tb.ten_thiet_bi,
      tb.model,
      tb.serial,
      tb.khoa_phong_quan_ly,
      tb.ngay_nhap,
      tb.created_at,
      tb.gia_goc,
      tb.don_vi
    FROM public.thiet_bi tb
    WHERE coalesce(tb.is_deleted, false) = false
      AND tb.don_vi = v_effective_don_vi
      AND tb.tinh_trang_hien_tai = 'Chưa có nhu cầu sử dụng'
      AND (
        v_pattern IS NULL
        OR lower(coalesce(tb.ten_thiet_bi, '')) ILIKE v_pattern ESCAPE '\'
        OR lower(coalesce(tb.ma_thiet_bi, '')) ILIKE v_pattern ESCAPE '\'
        OR lower(coalesce(tb.model, '')) ILIKE v_pattern ESCAPE '\'
        OR lower(coalesce(tb.serial, '')) ILIKE v_pattern ESCAPE '\'
      )
  ),
  filtered AS MATERIALIZED (
    SELECT *
    FROM base_filtered
    WHERE p_khoa_phong IS NULL
      OR p_khoa_phong = ''
      OR (p_khoa_phong = 'Không xác định' AND nullif(trim(khoa_phong_quan_ly), '') IS NULL)
      OR khoa_phong_quan_ly = p_khoa_phong
  ),
  summary_data AS (
    SELECT
      count(*)::int AS total_count,
      count(DISTINCT nullif(trim(ten_thiet_bi), ''))::int AS device_type_count,
      count(DISTINCT nullif(trim(khoa_phong_quan_ly), ''))::int AS department_count,
      coalesce(sum(gia_goc), 0)::numeric AS total_original_value
    FROM filtered
  ),
  top_device_groups AS (
    SELECT
      coalesce(nullif(trim(ten_thiet_bi), ''), 'Không xác định') AS device_name,
      count(*)::int AS equipment_count,
      coalesce(sum(gia_goc), 0)::numeric AS total_original_value
    FROM filtered
    GROUP BY coalesce(nullif(trim(ten_thiet_bi), ''), 'Không xác định')
    ORDER BY equipment_count DESC, device_name ASC
    LIMIT 10
  ),
  top_departments AS (
    SELECT
      coalesce(nullif(trim(khoa_phong_quan_ly), ''), 'Không xác định') AS department_name,
      count(*)::int AS equipment_count,
      coalesce(sum(gia_goc), 0)::numeric AS total_original_value
    FROM filtered
    GROUP BY coalesce(nullif(trim(khoa_phong_quan_ly), ''), 'Không xác định')
    ORDER BY equipment_count DESC, department_name ASC
    LIMIT 10
  ),
  department_options AS (
    SELECT
      coalesce(nullif(trim(khoa_phong_quan_ly), ''), 'Không xác định') AS department_name,
      count(*)::int AS equipment_count,
      coalesce(sum(gia_goc), 0)::numeric AS total_original_value
    FROM base_filtered
    GROUP BY coalesce(nullif(trim(khoa_phong_quan_ly), ''), 'Không xác định')
    ORDER BY department_name ASC
  )
  SELECT
    jsonb_build_object(
      'totalCount', s.total_count,
      'deviceTypeCount', s.device_type_count,
      'departmentCount', s.department_count,
      'totalOriginalValue', s.total_original_value
    ),
    s.total_count,
    coalesce(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'deviceName', device_name,
            'equipmentCount', equipment_count,
            'totalOriginalValue', total_original_value
          )
          ORDER BY equipment_count DESC, device_name ASC
        )
        FROM top_device_groups
      ),
      '[]'::jsonb
    ),
    coalesce(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'departmentName', department_name,
            'equipmentCount', equipment_count,
            'totalOriginalValue', total_original_value
          )
          ORDER BY equipment_count DESC, department_name ASC
        )
        FROM top_departments
      ),
      '[]'::jsonb
    ),
    coalesce(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'departmentName', department_name,
            'equipmentCount', equipment_count,
            'totalOriginalValue', total_original_value
          )
          ORDER BY department_name ASC
        )
        FROM department_options
      ),
      '[]'::jsonb
    )
  INTO v_summary, v_total_count, v_top_device_groups, v_departments, v_department_options
  FROM summary_data s;

  EXECUTE format(
    $sql$
      WITH filtered AS (
        SELECT
          tb.id,
          tb.ma_thiet_bi,
          tb.ten_thiet_bi,
          tb.model,
          tb.serial,
          tb.khoa_phong_quan_ly,
          tb.ngay_nhap,
          tb.created_at,
          tb.gia_goc,
          tb.don_vi
        FROM public.thiet_bi tb
        WHERE coalesce(tb.is_deleted, false) = false
          AND tb.don_vi = $1
          AND tb.tinh_trang_hien_tai = 'Chưa có nhu cầu sử dụng'
          AND (
            $2::text IS NULL
            OR $2 = ''
            OR ($2 = 'Không xác định' AND nullif(trim(tb.khoa_phong_quan_ly), '') IS NULL)
            OR tb.khoa_phong_quan_ly = $2
          )
          AND (
            $3::text IS NULL
            OR lower(coalesce(tb.ten_thiet_bi, '')) ILIKE $3 ESCAPE '\'
            OR lower(coalesce(tb.ma_thiet_bi, '')) ILIKE $3 ESCAPE '\'
            OR lower(coalesce(tb.model, '')) ILIKE $3 ESCAPE '\'
            OR lower(coalesce(tb.serial, '')) ILIKE $3 ESCAPE '\'
          )
      ),
      paged AS (
        SELECT *
        FROM filtered
        ORDER BY %s
        OFFSET $4 LIMIT $5
      )
      SELECT coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', id,
            'maThietBi', ma_thiet_bi,
            'tenThietBi', ten_thiet_bi,
            'model', model,
            'serial', serial,
            'khoaPhongQuanLy', khoa_phong_quan_ly,
            'ngayNhap', ngay_nhap,
            'createdAt', created_at,
            'giaGoc', gia_goc,
            'donVi', don_vi
          )
        ),
        '[]'::jsonb
      )
      FROM paged
    $sql$,
    v_order_sql
  )
  INTO v_items
  USING v_effective_don_vi, p_khoa_phong, v_pattern, v_offset, v_limit;

  RETURN jsonb_build_object(
    'summary', coalesce(v_summary, jsonb_build_object(
      'totalCount', 0,
      'deviceTypeCount', 0,
      'departmentCount', 0,
      'totalOriginalValue', 0
    )),
    'topDeviceGroups', coalesce(v_top_device_groups, '[]'::jsonb),
    'departments', coalesce(v_departments, '[]'::jsonb),
    'departmentOptions', coalesce(v_department_options, '[]'::jsonb),
    'items', coalesce(v_items, '[]'::jsonb),
    'totalCount', coalesce(v_total_count, 0),
    'page', GREATEST(coalesce(p_page, 1), 1),
    'pageSize', v_limit
  );
END;
$_$;


