--
-- Name: update_user_info(integer, integer, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_user_info(p_admin_user_id integer, p_target_user_id integer, p_username text, p_password text, p_full_name text, p_role text, p_khoa_phong text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_admin_role TEXT;
  v_admin_username TEXT;
  v_target_username TEXT;
BEGIN
  SELECT role, username
  INTO v_admin_role, v_admin_username
  FROM public.nhan_vien
  WHERE id = p_admin_user_id;

  IF v_admin_role IS NULL THEN
    RAISE EXCEPTION 'Access denied: acting user not found';
  END IF;

  IF v_admin_role NOT IN ('admin', 'global') THEN
    RAISE EXCEPTION 'Access denied: Admin or Global privileges required';
  END IF;

  IF NOT public.validate_username(p_username) THEN
    RAISE EXCEPTION 'Invalid username format';
  END IF;

  SELECT username
  INTO v_target_username
  FROM public.nhan_vien
  WHERE id = p_target_user_id;

  IF v_target_username IS NULL THEN
    RAISE EXCEPTION 'User not found with ID: %', p_target_user_id;
  END IF;

  UPDATE public.nhan_vien
  SET username = p_username,
      hashed_password = extensions.crypt(p_password, extensions.gen_salt('bf', 12)),
      password = 'hashed password',
      full_name = p_full_name,
      role = p_role,
      khoa_phong = p_khoa_phong
  WHERE id = p_target_user_id;

  INSERT INTO public.audit_logs (
    admin_user_id,
    admin_username,
    action_type,
    target_user_id,
    target_username,
    action_details,
    ip_address,
    user_agent
  ) VALUES (
    p_admin_user_id,
    v_admin_username,
    'USER_UPDATE',
    p_target_user_id,
    v_target_username,
    jsonb_build_object(
      'username', p_username,
      'full_name', p_full_name,
      'role', p_role,
      'khoa_phong', p_khoa_phong,
      'password_updated', TRUE
    ),
      COALESCE(pg_catalog.inet_client_addr(), '0.0.0.0'::INET),
    COALESCE(current_setting('request.headers', true), 'unknown')
  );

  RETURN TRUE;
END;
$$;


