--
-- Name: usage_analytics_daily(integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.usage_analytics_daily(p_days integer DEFAULT 30, p_don_vi bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_allowed BIGINT[] := public.allowed_don_vi_for_session();
  v_effective BIGINT[] := NULL;
BEGIN
  IF v_role = 'global' THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT p_don_vi = ANY(v_allowed) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_effective IS NOT NULL AND array_length(v_effective, 1) IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT to_jsonb(row) FROM (
    SELECT 
      date_trunc('day', nk.thoi_gian_bat_dau)::date as date,
      COUNT(*) as session_count,
      COALESCE(SUM(
        CASE 
          WHEN nk.thoi_gian_ket_thuc IS NOT NULL 
          THEN EXTRACT(EPOCH FROM (nk.thoi_gian_ket_thuc - nk.thoi_gian_bat_dau)) / 60
          ELSE 0 
        END
      ), 0)::int as total_usage_time,
      COUNT(DISTINCT nk.nguoi_su_dung_id) as unique_users,
      COUNT(DISTINCT nk.thiet_bi_id) as unique_equipment
    FROM public.nhat_ky_su_dung nk
    LEFT JOIN public.thiet_bi tb ON nk.thiet_bi_id = tb.id
    WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
      AND nk.thoi_gian_bat_dau >= CURRENT_DATE - INTERVAL '1 day' * p_days
    GROUP BY date_trunc('day', nk.thoi_gian_bat_dau)
    ORDER BY date DESC
  ) row;
END;
$$;


ALTER FUNCTION public.usage_analytics_daily(p_days integer, p_don_vi bigint) OWNER TO postgres;

--
-- Name: usage_analytics_overview(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.usage_analytics_overview(p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_allowed BIGINT[] := public.allowed_don_vi_for_session();
  v_effective BIGINT[] := NULL;
  result JSONB;
BEGIN
  IF v_role = 'global' THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN jsonb_build_object(
        'total_sessions', 0,
        'active_sessions', 0,
        'total_usage_time', 0
      );
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT p_don_vi = ANY(v_allowed) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_effective IS NOT NULL AND array_length(v_effective, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'total_sessions', 0,
      'active_sessions', 0,
      'total_usage_time', 0
    );
  END IF;

  SELECT jsonb_build_object(
    'total_sessions', COUNT(*),
    'active_sessions', COUNT(*) FILTER (WHERE nk.trang_thai = 'dang_su_dung'),
    'total_usage_time', COALESCE(SUM(
      CASE 
        WHEN nk.thoi_gian_ket_thuc IS NOT NULL 
        THEN EXTRACT(EPOCH FROM (nk.thoi_gian_ket_thuc - nk.thoi_gian_bat_dau)) / 60
        ELSE 0 
      END
    ), 0)::int
  ) INTO result
  FROM public.nhat_ky_su_dung nk
  LEFT JOIN public.thiet_bi tb ON nk.thiet_bi_id = tb.id
  WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective));

  RETURN COALESCE(result, jsonb_build_object(
    'total_sessions', 0,
    'active_sessions', 0,
    'total_usage_time', 0
  ));
END;
$$;


ALTER FUNCTION public.usage_analytics_overview(p_don_vi bigint) OWNER TO postgres;

--
-- Name: usage_log_delete(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.usage_log_delete(p_usage_log_id bigint, p_don_vi bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_allowed BIGINT[] := public.allowed_don_vi_for_session();
  rec RECORD;
BEGIN
  PERFORM set_config('search_path', 'public', true);

  IF p_usage_log_id IS NULL THEN
    RAISE EXCEPTION 'Usage log ID is required' USING ERRCODE = '22023';
  END IF;

  IF v_role <> 'global' THEN
    RAISE EXCEPTION 'Only global administrators may delete usage logs' USING ERRCODE = '42501';
  END IF;

  SELECT nk.*, tb.don_vi AS equipment_don_vi
  INTO rec
  FROM public.nhat_ky_su_dung nk
  JOIN public.thiet_bi tb ON tb.id = nk.thiet_bi_id
  WHERE nk.id = p_usage_log_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Usage log not found' USING ERRCODE = 'P0002';
  END IF;

  IF rec.trang_thai <> 'hoan_thanh' THEN
    RAISE EXCEPTION 'Only completed sessions may be deleted' USING ERRCODE = 'P0001';
  END IF;

  DELETE FROM public.nhat_ky_su_dung WHERE id = p_usage_log_id;

  RETURN jsonb_build_object('success', TRUE, 'id', p_usage_log_id);
END;
$$;


ALTER FUNCTION public.usage_log_delete(p_usage_log_id bigint, p_don_vi bigint) OWNER TO postgres;

--
-- Name: usage_log_list(text, text, integer, integer, date, date, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.usage_log_list(p_q text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 100, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_don_vi bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_is_global BOOLEAN := false;
  v_allowed BIGINT[] := public.allowed_don_vi_for_session();
  v_effective BIGINT[] := NULL;
  v_offset INT := GREATEST(p_page - 1, 0) * GREATEST(p_page_size, 1);
  v_sanitized_q TEXT := NULL;
BEGIN
  v_is_global := v_role IN ('global', 'admin');
  v_sanitized_q := public._sanitize_ilike_pattern(p_q);

  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := NULL;
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT p_don_vi = ANY(v_allowed) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  IF v_effective IS NOT NULL AND array_length(v_effective, 1) IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT to_jsonb(nk)
    || jsonb_build_object(
      'thiet_bi', to_jsonb(tb),
      'equipment_is_deleted', tb.is_deleted
    )
    || jsonb_build_object(
      'nguoi_su_dung',
      CASE
        WHEN u.id IS NOT NULL THEN jsonb_build_object(
          'id', u.id,
          'full_name', u.full_name,
          'khoa_phong', u.khoa_phong
        )
        ELSE NULL
      END
    )
  FROM public.nhat_ky_su_dung nk
  LEFT JOIN public.thiet_bi tb ON nk.thiet_bi_id = tb.id
  LEFT JOIN public.nhan_vien u ON nk.nguoi_su_dung_id = u.id
  WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
    AND (p_status IS NULL OR nk.trang_thai = p_status)
    AND (p_date_from IS NULL OR nk.thoi_gian_bat_dau::date >= p_date_from)
    AND (p_date_to IS NULL OR nk.thoi_gian_bat_dau::date <= p_date_to)
    AND (
      v_sanitized_q IS NULL OR
      tb.ten_thiet_bi ILIKE '%' || v_sanitized_q || '%' OR
      tb.ma_thiet_bi ILIKE '%' || v_sanitized_q || '%'
    )
  ORDER BY nk.thoi_gian_bat_dau DESC
  OFFSET v_offset
  LIMIT GREATEST(p_page_size, 1);
END;
$$;


ALTER FUNCTION public.usage_log_list(p_q text, p_status text, p_page integer, p_page_size integer, p_date_from date, p_date_to date, p_don_vi bigint) OWNER TO postgres;

--
-- Name: FUNCTION usage_log_list(p_q text, p_status text, p_page integer, p_page_size integer, p_date_from date, p_date_to date, p_don_vi bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.usage_log_list(p_q text, p_status text, p_page integer, p_page_size integer, p_date_from date, p_date_to date, p_don_vi bigint) IS 'Returns usage log entries with filtering. FIXED: Now uses consistent JWT claim reading.';


--
-- Name: usage_log_list(bigint, text, boolean, timestamp with time zone, timestamp with time zone, integer, integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.usage_log_list(p_thiet_bi_id bigint DEFAULT NULL::bigint, p_trang_thai text DEFAULT NULL::text, p_active_only boolean DEFAULT false, p_started_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_started_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 200, p_offset integer DEFAULT 0, p_don_vi bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := lower(COALESCE(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_is_global BOOLEAN := false;
  v_allowed BIGINT[] := public.allowed_don_vi_for_session();
  v_effective BIGINT[] := NULL;
  v_limit INT := GREATEST(p_limit, 1);
  v_offset INT := GREATEST(p_offset, 0);
BEGIN
  v_is_global := v_role IN ('global', 'admin');

  IF p_trang_thai IS NOT NULL AND p_trang_thai NOT IN ('dang_su_dung', 'hoan_thanh') THEN
    RAISE EXCEPTION 'Invalid status filter' USING ERRCODE = '22023';
  END IF;

  IF v_is_global THEN
    IF p_don_vi IS NOT NULL THEN
      v_effective := ARRAY[p_don_vi];
    END IF;
  ELSE
    IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
      RETURN;
    END IF;

    IF p_don_vi IS NOT NULL THEN
      IF NOT p_don_vi = ANY(v_allowed) THEN
        RAISE EXCEPTION 'Access denied for tenant %', p_don_vi USING ERRCODE = '42501';
      END IF;
      v_effective := ARRAY[p_don_vi];
    ELSE
      v_effective := v_allowed;
    END IF;
  END IF;

  RETURN QUERY
  SELECT jsonb_build_object(
    'id', nk.id,
    'thiet_bi_id', nk.thiet_bi_id,
    'nguoi_su_dung_id', nk.nguoi_su_dung_id,
    'thoi_gian_bat_dau', nk.thoi_gian_bat_dau,
    'thoi_gian_ket_thuc', nk.thoi_gian_ket_thuc,
    'tinh_trang_thiet_bi', nk.tinh_trang_thiet_bi,
    'tinh_trang_ban_dau', nk.tinh_trang_ban_dau,
    'tinh_trang_ket_thuc', nk.tinh_trang_ket_thuc,
    'ghi_chu', nk.ghi_chu,
    'trang_thai', nk.trang_thai,
    'created_at', nk.created_at,
    'updated_at', nk.updated_at,
    'equipment_is_deleted', tb.is_deleted,
    'thiet_bi', jsonb_build_object(
      'id', tb.id,
      'ma_thiet_bi', tb.ma_thiet_bi,
      'ten_thiet_bi', tb.ten_thiet_bi,
      'khoa_phong_quan_ly', tb.khoa_phong_quan_ly,
      'don_vi', tb.don_vi,
      'is_deleted', tb.is_deleted
    ),
    'nguoi_su_dung', CASE
      WHEN nv.id IS NOT NULL THEN jsonb_build_object(
        'id', nv.id,
        'full_name', nv.full_name,
        'khoa_phong', nv.khoa_phong
      )
      ELSE NULL
    END
  )
  FROM public.nhat_ky_su_dung nk
  LEFT JOIN public.thiet_bi tb ON tb.id = nk.thiet_bi_id
  LEFT JOIN public.nhan_vien nv ON nv.id = nk.nguoi_su_dung_id
  WHERE (v_effective IS NULL OR tb.don_vi = ANY(v_effective))
    AND (p_thiet_bi_id IS NULL OR nk.thiet_bi_id = p_thiet_bi_id)
    AND (NOT p_active_only OR nk.trang_thai = 'dang_su_dung')
    AND (p_trang_thai IS NULL OR nk.trang_thai = p_trang_thai)
    AND (p_started_from IS NULL OR nk.thoi_gian_bat_dau >= p_started_from)
    AND (p_started_to IS NULL OR nk.thoi_gian_bat_dau <= p_started_to)
  ORDER BY nk.thoi_gian_bat_dau DESC
  OFFSET v_offset
  LIMIT v_limit;
END;
$$;


ALTER FUNCTION public.usage_log_list(p_thiet_bi_id bigint, p_trang_thai text, p_active_only boolean, p_started_from timestamp with time zone, p_started_to timestamp with time zone, p_limit integer, p_offset integer, p_don_vi bigint) OWNER TO postgres;

--
-- Name: usage_session_end(bigint, text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.usage_session_end(p_usage_log_id bigint, p_tinh_trang_thiet_bi text DEFAULT NULL::text, p_ghi_chu text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_tinh_trang_ket_thuc text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_is_global boolean := false;
  v_allowed bigint[] := null;
  v_user_id bigint := nullif(public._get_jwt_claim('user_id'), '')::bigint;
  rec record;
  result jsonb;
BEGIN
  v_is_global := v_role in ('global', 'admin');

  if p_usage_log_id is null then
    raise exception 'Usage log ID is required' using errcode = '22023';
  end if;

  if p_tinh_trang_ket_thuc is not null and trim(p_tinh_trang_ket_thuc) = '' then
    raise exception 'Final equipment status cannot be empty' using errcode = '22023';
  end if;

  if v_role = 'regional_leader' then
    raise exception 'Permission denied' using errcode = '42501';
  end if;

  if v_role is null or v_role = '' then
    raise exception 'Missing role claim' using errcode = '42501';
  end if;

  if v_user_id is null then
    raise exception 'Missing user_id claim' using errcode = '42501';
  end if;

  select nk.*, tb.don_vi as equipment_don_vi
  into rec
  from public.nhat_ky_su_dung nk
  join public.thiet_bi tb on tb.id = nk.thiet_bi_id
  where nk.id = p_usage_log_id
  for update;

  if not found then
    raise exception 'Usage session not found' using errcode = 'P0002';
  end if;

  if rec.trang_thai != 'dang_su_dung' then
    raise exception 'Usage session already closed' using errcode = 'P0001';
  end if;

  if not v_is_global then
    v_allowed := public.allowed_don_vi_for_session();
    if v_allowed is null or array_length(v_allowed, 1) is null or not rec.equipment_don_vi = any(v_allowed) then
      raise exception 'Access denied for equipment tenant' using errcode = '42501';
    end if;
  else
    if p_don_vi is not null then
      rec.equipment_don_vi := p_don_vi;
    end if;
  end if;

  if v_role in ('user', 'qltb_khoa') and rec.nguoi_su_dung_id is distinct from v_user_id then
    raise exception 'Cannot close session for another user' using errcode = '42501';
  end if;

  update public.nhat_ky_su_dung
  set thoi_gian_ket_thuc = timezone('utc', now()),
      tinh_trang_thiet_bi = coalesce(p_tinh_trang_ket_thuc, p_tinh_trang_thiet_bi, rec.tinh_trang_thiet_bi),
      tinh_trang_ket_thuc = p_tinh_trang_ket_thuc,
      ghi_chu = coalesce(p_ghi_chu, rec.ghi_chu),
      trang_thai = 'hoan_thanh',
      updated_at = timezone('utc', now())
  where id = p_usage_log_id;

  select jsonb_build_object(
    'id', nk.id,
    'thiet_bi_id', nk.thiet_bi_id,
    'nguoi_su_dung_id', nk.nguoi_su_dung_id,
    'thoi_gian_bat_dau', nk.thoi_gian_bat_dau,
    'thoi_gian_ket_thuc', nk.thoi_gian_ket_thuc,
    'tinh_trang_thiet_bi', nk.tinh_trang_thiet_bi,
    'tinh_trang_ban_dau', nk.tinh_trang_ban_dau,
    'tinh_trang_ket_thuc', nk.tinh_trang_ket_thuc,
    'ghi_chu', nk.ghi_chu,
    'trang_thai', nk.trang_thai,
    'created_at', nk.created_at,
    'updated_at', nk.updated_at,
    'thiet_bi', jsonb_build_object(
      'id', tb.id,
      'ma_thiet_bi', tb.ma_thiet_bi,
      'ten_thiet_bi', tb.ten_thiet_bi,
      'khoa_phong_quan_ly', tb.khoa_phong_quan_ly,
      'don_vi', tb.don_vi
    ),
    'nguoi_su_dung', case
      when nv.id is not null then jsonb_build_object(
        'id', nv.id,
        'full_name', nv.full_name,
        'khoa_phong', nv.khoa_phong
      )
      else null
    end
  )
  into result
  from public.nhat_ky_su_dung nk
  join public.thiet_bi tb on tb.id = nk.thiet_bi_id
  left join public.nhan_vien nv on nv.id = nk.nguoi_su_dung_id
  where nk.id = p_usage_log_id;

  return result;
END;
$$;


ALTER FUNCTION public.usage_session_end(p_usage_log_id bigint, p_tinh_trang_thiet_bi text, p_ghi_chu text, p_don_vi bigint, p_tinh_trang_ket_thuc text) OWNER TO postgres;

--
-- Name: usage_session_start(bigint, bigint, text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.usage_session_start(p_thiet_bi_id bigint, p_nguoi_su_dung_id bigint DEFAULT NULL::bigint, p_tinh_trang_thiet_bi text DEFAULT NULL::text, p_ghi_chu text DEFAULT NULL::text, p_don_vi bigint DEFAULT NULL::bigint, p_tinh_trang_ban_dau text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := lower(coalesce(public._get_jwt_claim('app_role'), public._get_jwt_claim('role'), ''));
  v_is_global boolean := false;
  v_allowed bigint[] := null;
  v_user_id bigint := nullif(public._get_jwt_claim('user_id'), '')::bigint;
  v_target_user bigint;
  v_equipment_don_vi bigint;
  v_new_id bigint;
  result jsonb;
BEGIN
  v_is_global := v_role in ('global', 'admin');

  if v_role is null or v_role = '' then
    raise exception 'Missing role claim' using errcode = '42501';
  end if;

  if p_thiet_bi_id is null then
    raise exception 'Equipment ID is required' using errcode = '22023';
  end if;

  -- Validate new param: NULL = skip (backward compat), empty = reject
  if p_tinh_trang_ban_dau is not null and trim(p_tinh_trang_ban_dau) = '' then
    raise exception 'Initial equipment status cannot be empty' using errcode = '22023';
  end if;

  if v_role = 'regional_leader' then
    raise exception 'Permission denied' using errcode = '42501';
  end if;

  if v_user_id is null then
    raise exception 'Authenticated user required' using errcode = '42501';
  end if;

  v_target_user := coalesce(p_nguoi_su_dung_id, v_user_id);

  if not (v_is_global or v_role in ('to_qltb', 'technician', 'qltb_khoa'))
     and v_target_user <> v_user_id then
    raise exception 'Cannot start session for another user' using errcode = '42501';
  end if;

  select tb.don_vi into v_equipment_don_vi
  from public.thiet_bi tb
  where tb.id = p_thiet_bi_id
    and tb.is_deleted = false
  for update;

  if not found then
    raise exception 'Equipment not found' using errcode = 'P0002';
  end if;

  if not v_is_global then
    v_allowed := public.allowed_don_vi_for_session();
    if v_allowed is null or array_length(v_allowed, 1) is null or not v_equipment_don_vi = any(v_allowed) then
      raise exception 'Access denied for equipment tenant' using errcode = '42501';
    end if;
  else
    if p_don_vi is not null then
      v_equipment_don_vi := p_don_vi;
    end if;
  end if;

  perform 1
  from public.nhat_ky_su_dung nk
  where nk.thiet_bi_id = p_thiet_bi_id
    and nk.trang_thai = 'dang_su_dung';

  if found then
    raise exception 'Thiết bị đang được sử dụng bởi người khác' using errcode = 'P0001';
  end if;

  insert into public.nhat_ky_su_dung (
    thiet_bi_id,
    nguoi_su_dung_id,
    thoi_gian_bat_dau,
    tinh_trang_thiet_bi,
    tinh_trang_ban_dau,
    ghi_chu,
    trang_thai,
    created_at,
    updated_at
  )
  values (
    p_thiet_bi_id,
    v_target_user,
    timezone('utc', now()),
    coalesce(p_tinh_trang_ban_dau, p_tinh_trang_thiet_bi),
    p_tinh_trang_ban_dau,
    p_ghi_chu,
    'dang_su_dung',
    timezone('utc', now()),
    timezone('utc', now())
  )
  returning id into v_new_id;

  select jsonb_build_object(
    'id', nk.id,
    'thiet_bi_id', nk.thiet_bi_id,
    'nguoi_su_dung_id', nk.nguoi_su_dung_id,
    'thoi_gian_bat_dau', nk.thoi_gian_bat_dau,
    'thoi_gian_ket_thuc', nk.thoi_gian_ket_thuc,
    'tinh_trang_thiet_bi', nk.tinh_trang_thiet_bi,
    'tinh_trang_ban_dau', nk.tinh_trang_ban_dau,
    'tinh_trang_ket_thuc', nk.tinh_trang_ket_thuc,
    'ghi_chu', nk.ghi_chu,
    'trang_thai', nk.trang_thai,
    'created_at', nk.created_at,
    'updated_at', nk.updated_at,
    'thiet_bi', jsonb_build_object(
      'id', tb.id,
      'ma_thiet_bi', tb.ma_thiet_bi,
      'ten_thiet_bi', tb.ten_thiet_bi,
      'khoa_phong_quan_ly', tb.khoa_phong_quan_ly,
      'don_vi', tb.don_vi
    ),
    'nguoi_su_dung', case
      when nv.id is not null then jsonb_build_object(
        'id', nv.id,
        'full_name', nv.full_name,
        'khoa_phong', nv.khoa_phong
      )
      else null
    end
  )
  into result
  from public.nhat_ky_su_dung nk
  join public.thiet_bi tb on tb.id = nk.thiet_bi_id
  left join public.nhan_vien nv on nv.id = nk.nguoi_su_dung_id
  where nk.id = v_new_id;

  return result;
END;
$$;


ALTER FUNCTION public.usage_session_start(p_thiet_bi_id bigint, p_nguoi_su_dung_id bigint, p_tinh_trang_thiet_bi text, p_ghi_chu text, p_don_vi bigint, p_tinh_trang_ban_dau text) OWNER TO postgres;

--
-- Name: user_create(text, text, text, text, bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.user_create(p_username text, p_password text, p_full_name text, p_role text, p_current_don_vi bigint, p_memberships bigint[] DEFAULT NULL::bigint[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_claims JSONB := COALESCE(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_app_role TEXT := LOWER(NULLIF(COALESCE(v_claims->>'app_role', v_claims->>'role'), ''));
  v_admin_user_id BIGINT := NULLIF(v_claims->>'user_id', '')::BIGINT;
  v_admin_username TEXT;
  v_admin_role TEXT;
  v_id INTEGER;
  v_hashed_password TEXT;
  v_username TEXT := TRIM(p_username);
  v_password TEXT := TRIM(p_password);
  v_full_name TEXT := TRIM(p_full_name);
  v_role TEXT := LOWER(TRIM(p_role));
BEGIN
  IF v_app_role = 'admin' THEN
    v_app_role := 'global';
  END IF;

  IF v_app_role IS NULL OR v_app_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_admin_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  SELECT nv.username, nv.role
  INTO v_admin_username, v_admin_role
  FROM public.nhan_vien nv
  WHERE nv.id = v_admin_user_id;

  IF v_admin_role IS NULL OR v_admin_role NOT IN ('admin', 'global') OR v_app_role <> 'global' THEN
    RAISE EXCEPTION 'Access denied: Admin or Global privileges required' USING ERRCODE = '42501';
  END IF;

  IF p_username IS NULL OR v_username = '' OR POSITION(' ' IN v_username) > 0 THEN
    RAISE EXCEPTION 'Invalid username format' USING ERRCODE = '22023';
  END IF;

  IF p_password IS NULL OR v_password = '' THEN
    RAISE EXCEPTION 'Invalid password format' USING ERRCODE = '22023';
  END IF;

  IF p_full_name IS NULL OR v_full_name = '' OR p_role IS NULL OR v_role = '' OR p_current_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing required fields' USING ERRCODE = '22023';
  END IF;

  v_hashed_password := extensions.crypt(v_password, extensions.gen_salt('bf', 12));

  INSERT INTO public.nhan_vien(
    username,
    password,
    hashed_password,
    full_name,
    role,
    don_vi,
    current_don_vi
  )
  VALUES (
    v_username,
    'hashed password',
    v_hashed_password,
    v_full_name,
    v_role,
    p_current_don_vi,
    p_current_don_vi
  )
  RETURNING id INTO v_id;

  INSERT INTO public.user_don_vi_memberships(user_id, don_vi)
  VALUES (v_id, p_current_don_vi)
  ON CONFLICT DO NOTHING;

  IF p_memberships IS NOT NULL THEN
    INSERT INTO public.user_don_vi_memberships(user_id, don_vi)
    SELECT v_id, m
    FROM unnest(p_memberships) AS m
    WHERE m IS NOT NULL AND m <> p_current_don_vi
    ON CONFLICT DO NOTHING;
  END IF;

  INSERT INTO public.audit_logs (
    admin_user_id,
    admin_username,
    action_type,
    target_user_id,
    target_username,
    action_details,
    ip_address,
    user_agent,
    entity_type,
    entity_id,
    entity_label
  ) VALUES (
    v_admin_user_id,
    v_admin_username,
    'USER_CREATE',
    v_id,
    v_username,
    jsonb_build_object(
      'username', v_username,
      'full_name', v_full_name,
      'role', v_role,
      'current_don_vi', p_current_don_vi,
      'memberships', COALESCE(p_memberships, ARRAY[]::BIGINT[])
    ),
    COALESCE(pg_catalog.inet_client_addr(), '0.0.0.0'::INET),
    COALESCE(
      NULLIF((COALESCE(NULLIF(current_setting('request.headers', true), ''), '{}')::jsonb)->>'user-agent', ''),
      'unknown'
    ),
    'nhan_vien',
    v_id,
    v_username
  );

  RETURN v_id;
END;
$$;


