--
-- Name: user_set_current_don_vi(integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.user_set_current_don_vi(p_user_id integer, p_don_vi bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims JSONB := COALESCE(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_app_role TEXT := LOWER(NULLIF(COALESCE(v_claims->>'app_role', v_claims->>'role'), ''));
  v_claim_user_id BIGINT := NULLIF(v_claims->>'user_id', '')::BIGINT;
  v_has_membership BOOLEAN;
  v_tenant_active BOOLEAN;
BEGIN
  IF v_app_role = 'admin' THEN
    v_app_role := 'global';
  END IF;

  IF v_app_role IS NULL OR v_app_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_claim_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NULL OR p_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing user or tenant id' USING ERRCODE = '22023';
  END IF;

  IF v_claim_user_id IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'user claim mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(dv.active, TRUE)
  INTO v_tenant_active
  FROM public.don_vi dv
  WHERE dv.id = p_don_vi;

  IF v_tenant_active IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'Invalid or inactive tenant' USING ERRCODE = '22023';
  END IF;

  IF v_app_role <> 'global' THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.user_don_vi_memberships udvm
      WHERE udvm.user_id = p_user_id
        AND udvm.don_vi = p_don_vi
    )
    INTO v_has_membership;

    IF v_has_membership IS DISTINCT FROM TRUE THEN
      RAISE EXCEPTION 'Người dùng không thuộc đơn vị này' USING ERRCODE = '42501';
    END IF;
  END IF;

  UPDATE public.nhan_vien
  SET current_don_vi = p_don_vi
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User not found with ID: %', p_user_id USING ERRCODE = '22023';
  END IF;
END;
$$;


ALTER FUNCTION public.user_set_current_don_vi(p_user_id integer, p_don_vi bigint) OWNER TO postgres;

--
-- Name: user_update_profile(integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.user_update_profile(p_target_user_id integer, p_username text, p_full_name text, p_role text, p_khoa_phong text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims JSONB := COALESCE(current_setting('request.jwt.claims', true), '{}')::jsonb;
  v_role TEXT := LOWER(NULLIF(COALESCE(v_claims->>'app_role', v_claims->>'role'), ''));
  v_admin_user_id BIGINT := NULLIF(v_claims->>'user_id', '')::BIGINT;
  v_admin_username TEXT;
  v_admin_role TEXT;
  v_target_username TEXT;
BEGIN
  IF v_role = 'admin' THEN
    v_role := 'global';
  END IF;

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim' USING ERRCODE = '42501';
  END IF;

  IF v_admin_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim' USING ERRCODE = '42501';
  END IF;

  SELECT nv.username, nv.role
  INTO v_admin_username, v_admin_role
  FROM public.nhan_vien nv
  WHERE nv.id = v_admin_user_id;

  IF v_admin_role IS NULL OR v_admin_role NOT IN ('admin', 'global') OR v_role <> 'global' THEN
    RAISE EXCEPTION 'Access denied: Admin or Global privileges required' USING ERRCODE = '42501';
  END IF;

  IF p_target_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing target user id' USING ERRCODE = '22023';
  END IF;

  IF NOT public.validate_username(p_username) THEN
    RAISE EXCEPTION 'Invalid username format' USING ERRCODE = '22023';
  END IF;

  IF p_full_name IS NULL OR TRIM(p_full_name) = '' THEN
    RAISE EXCEPTION 'Missing full_name' USING ERRCODE = '22023';
  END IF;

  IF p_role IS NULL OR LOWER(TRIM(p_role)) NOT IN (
    'global',
    'admin',
    'regional_leader',
    'to_qltb',
    'technician',
    'qltb_khoa',
    'user'
  ) THEN
    RAISE EXCEPTION 'Invalid role' USING ERRCODE = '22023';
  END IF;

  SELECT nv.username
  INTO v_target_username
  FROM public.nhan_vien nv
  WHERE nv.id = p_target_user_id;

  IF v_target_username IS NULL THEN
    RAISE EXCEPTION 'User not found with ID: %', p_target_user_id USING ERRCODE = '22023';
  END IF;

  UPDATE public.nhan_vien
  SET username = TRIM(p_username),
      full_name = TRIM(p_full_name),
      role = LOWER(TRIM(p_role)),
      khoa_phong = NULLIF(TRIM(COALESCE(p_khoa_phong, '')), '')
  WHERE id = p_target_user_id;

  INSERT INTO public.audit_logs (
    admin_user_id,
    admin_username,
    action_type,
    target_user_id,
    target_username,
    action_details,
    ip_address,
    user_agent,
    entity_type,
    entity_id,
    entity_label
  ) VALUES (
    v_admin_user_id,
    v_admin_username,
    'USER_UPDATE',
    p_target_user_id,
    v_target_username,
    jsonb_build_object(
      'username', TRIM(p_username),
      'full_name', TRIM(p_full_name),
      'role', LOWER(TRIM(p_role)),
      'khoa_phong', NULLIF(TRIM(COALESCE(p_khoa_phong, '')), ''),
      'password_updated', FALSE
    ),
    COALESCE(pg_catalog.inet_client_addr(), '0.0.0.0'::INET),
    COALESCE(
      NULLIF((COALESCE(NULLIF(current_setting('request.headers', true), ''), '{}')::jsonb)->>'user-agent', ''),
      'unknown'
    ),
    'nhan_vien',
    p_target_user_id,
    TRIM(p_username)
  );

  RETURN TRUE;
END;
$$;


ALTER FUNCTION public.user_update_profile(p_target_user_id integer, p_username text, p_full_name text, p_role text, p_khoa_phong text) OWNER TO postgres;

