--
-- Name: verify_regional_leader_schema(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_regional_leader_schema() RETURNS TABLE(check_name text, status text, details text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Check dia_ban table exists
    RETURN QUERY
    SELECT 
        'dia_ban_table_exists'::TEXT,
        CASE WHEN EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'dia_ban') 
             THEN 'PASS'::TEXT ELSE 'FAIL'::TEXT END,
        'dia_ban table creation'::TEXT;
    
    -- Check dia_ban_id columns exist
    RETURN QUERY
    SELECT 
        'don_vi_dia_ban_id_column'::TEXT,
        CASE WHEN EXISTS (
            SELECT 1 FROM information_schema.columns 
            WHERE table_name = 'don_vi' AND column_name = 'dia_ban_id'
        ) THEN 'PASS'::TEXT ELSE 'FAIL'::TEXT END,
        'don_vi.dia_ban_id column exists'::TEXT;
    
    RETURN QUERY
    SELECT 
        'nhan_vien_dia_ban_id_column'::TEXT,
        CASE WHEN EXISTS (
            SELECT 1 FROM information_schema.columns 
            WHERE table_name = 'nhan_vien' AND column_name = 'dia_ban_id'
        ) THEN 'PASS'::TEXT ELSE 'FAIL'::TEXT END,
        'nhan_vien.dia_ban_id column exists'::TEXT;
    
    -- Check helper function exists
    RETURN QUERY
    SELECT 
        'allowed_don_vi_function'::TEXT,
        CASE WHEN EXISTS (
            SELECT 1 FROM information_schema.routines 
            WHERE routine_name = 'allowed_don_vi_for_session'
        ) THEN 'PASS'::TEXT ELSE 'FAIL'::TEXT END,
        'allowed_don_vi_for_session function exists'::TEXT;
    
    -- Check indexes exist
    RETURN QUERY
    SELECT 
        'dia_ban_indexes'::TEXT,
        CASE WHEN EXISTS (
            SELECT 1 FROM pg_indexes 
            WHERE tablename = 'dia_ban' AND indexname = 'idx_dia_ban_ma_dia_ban'
        ) THEN 'PASS'::TEXT ELSE 'FAIL'::TEXT END,
        'dia_ban primary indexes created'::TEXT;
        
END;
$$;


ALTER FUNCTION public.verify_regional_leader_schema() OWNER TO postgres;

--
-- Name: zbs_notification_outbox_claim_for_dispatch(integer, timestamp with time zone, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.zbs_notification_outbox_claim_for_dispatch(p_limit integer DEFAULT 25, p_now timestamp with time zone DEFAULT now(), p_outbox_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(id uuid, event_type text, source_type text, source_id bigint, don_vi_id bigint, recipient_config_id uuid, recipient_phone text, template_id text, template_data jsonb, tracking_id text, status text, provider text, last_attempt_at timestamp with time zone, next_attempt_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_status_pending constant text := 'pending';
  v_status_processing constant text := 'processing';
  v_status_failed constant text := 'failed';
  v_claims jsonb := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb,
    '{}'::jsonb
  );
  v_now timestamptz := coalesce(p_now, now());
BEGIN
  IF coalesce(v_claims->>'role', '') <> 'service_role' THEN
    RAISE EXCEPTION 'ZBS live dispatch RPC requires service_role JWT'
      USING errcode = '42501';
  END IF;

  RETURN QUERY
  WITH expired_ids AS (
    SELECT outbox.id
    FROM public.zbs_notification_outbox outbox
    WHERE outbox.provider = 'zalo_zbs'
      AND outbox.event_type = 'repair_request_created'
      AND outbox.source_type = 'repair_request'
      AND outbox.status = v_status_processing
      AND outbox.last_attempt_at <= v_now - interval '10 minutes'
      AND outbox.attempt_count >= 3
      AND (
        p_outbox_ids IS NULL
        OR outbox.id = ANY(p_outbox_ids)
      )
    ORDER BY outbox.created_at ASC
    LIMIT least(greatest(coalesce(p_limit, 25), 0), 100)
    FOR UPDATE OF outbox SKIP LOCKED
  ),
  expired_processing AS (
    UPDATE public.zbs_notification_outbox outbox
    SET
      status = v_status_failed,
      next_attempt_at = outbox.next_attempt_at,
      last_error_code = 'dispatch_lease_expired',
      last_error_message = 'ZBS processing lease expired after final attempt',
      updated_at = now()
    FROM expired_ids
    WHERE outbox.id = expired_ids.id
    RETURNING 1 AS expired_row
  ),
  expired_processing_done AS (
    SELECT count(*) AS expired_count
    FROM expired_processing
  ),
  claimed AS (
    SELECT outbox.id
    FROM public.zbs_notification_outbox outbox
    CROSS JOIN expired_processing_done
    WHERE outbox.provider = 'zalo_zbs'
      AND outbox.event_type = 'repair_request_created'
      AND outbox.source_type = 'repair_request'
      AND outbox.attempt_count < 3
      AND (
        (
          outbox.status = v_status_pending
          AND outbox.next_attempt_at <= v_now
        )
        OR (
          outbox.status = v_status_processing
          AND outbox.last_attempt_at <= v_now - interval '10 minutes'
        )
      )
      AND (
        p_outbox_ids IS NULL
        OR outbox.id = ANY(p_outbox_ids)
      )
    ORDER BY outbox.created_at ASC
    LIMIT least(greatest(coalesce(p_limit, 25), 0), 100)
    FOR UPDATE OF outbox SKIP LOCKED
  ),
  updated AS (
    UPDATE public.zbs_notification_outbox outbox
    SET
      status = v_status_processing,
      attempt_count = outbox.attempt_count + 1,
      last_attempt_at = v_now,
      updated_at = now()
    FROM claimed
    WHERE outbox.id = claimed.id
    RETURNING
      outbox.id,
      outbox.event_type,
      outbox.source_type,
      outbox.source_id,
      outbox.don_vi_id,
      outbox.recipient_config_id,
      outbox.recipient_phone,
      outbox.template_id,
      outbox.template_data,
      outbox.tracking_id,
      outbox.status,
      outbox.provider,
      outbox.last_attempt_at,
      outbox.next_attempt_at,
      outbox.created_at
  )
  SELECT
    updated.id,
    updated.event_type,
    updated.source_type,
    updated.source_id,
    updated.don_vi_id,
    updated.recipient_config_id,
    updated.recipient_phone,
    updated.template_id,
    updated.template_data,
    updated.tracking_id,
    updated.status,
    updated.provider,
    updated.last_attempt_at,
    updated.next_attempt_at
  FROM updated
  ORDER BY updated.created_at ASC;
END;
$$;


ALTER FUNCTION public.zbs_notification_outbox_claim_for_dispatch(p_limit integer, p_now timestamp with time zone, p_outbox_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION zbs_notification_outbox_claim_for_dispatch(p_limit integer, p_now timestamp with time zone, p_outbox_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.zbs_notification_outbox_claim_for_dispatch(p_limit integer, p_now timestamp with time zone, p_outbox_ids uuid[]) IS 'Server-only live ZBS dispatcher claim boundary. Reclaims stale processing rows only before the final attempt cap; final-attempt expiry is bounded, status predicates use local constants, and CTE dependencies are explicit.';


--
-- Name: zbs_notification_outbox_mark_failed(uuid, timestamp with time zone, boolean, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.zbs_notification_outbox_mark_failed(p_id uuid, p_claimed_at timestamp with time zone, p_retryable boolean, p_error_code text, p_error_message text, p_provider_response jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_claims jsonb := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb,
    '{}'::jsonb
  );
BEGIN
  IF coalesce(v_claims->>'role', '') <> 'service_role' THEN
    RAISE EXCEPTION 'ZBS live dispatch RPC requires service_role JWT'
      USING errcode = '42501';
  END IF;

  UPDATE public.zbs_notification_outbox outbox
  SET
    status = CASE
      WHEN coalesce(p_retryable, false) AND outbox.attempt_count < 3 THEN 'pending'
      ELSE 'failed'
    END,
    next_attempt_at = CASE
      WHEN coalesce(p_retryable, false) AND outbox.attempt_count = 1 THEN v_now + interval '5 minutes'
      WHEN coalesce(p_retryable, false) AND outbox.attempt_count = 2 THEN v_now + interval '30 minutes'
      ELSE outbox.next_attempt_at
    END,
    provider_response = coalesce(p_provider_response, '{}'::jsonb),
    last_error_code = NULLIF(p_error_code, ''),
    last_error_message = NULLIF(p_error_message, ''),
    updated_at = v_now
  WHERE outbox.id = p_id
    AND outbox.provider = 'zalo_zbs'
    AND outbox.status = 'processing'
    AND p_claimed_at IS NOT NULL
    AND outbox.last_attempt_at BETWEEN p_claimed_at - interval '1 millisecond'
      AND p_claimed_at + interval '1 millisecond';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ZBS outbox row % is not claimable as failed for this lease', p_id
      USING errcode = 'P0002';
  END IF;
END;
$$;


ALTER FUNCTION public.zbs_notification_outbox_mark_failed(p_id uuid, p_claimed_at timestamp with time zone, p_retryable boolean, p_error_code text, p_error_message text, p_provider_response jsonb) OWNER TO postgres;

--
-- Name: FUNCTION zbs_notification_outbox_mark_failed(p_id uuid, p_claimed_at timestamp with time zone, p_retryable boolean, p_error_code text, p_error_message text, p_provider_response jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.zbs_notification_outbox_mark_failed(p_id uuid, p_claimed_at timestamp with time zone, p_retryable boolean, p_error_code text, p_error_message text, p_provider_response jsonb) IS 'Server-only live ZBS dispatcher failure boundary. Requires service_role JWT and a matching processing lease timestamp, tolerating client/DB precision drift.';


--
-- Name: zbs_notification_outbox_mark_sent(uuid, timestamp with time zone, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.zbs_notification_outbox_mark_sent(p_id uuid, p_claimed_at timestamp with time zone, p_provider_message_id text, p_sent_at timestamp with time zone, p_provider_response jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims jsonb := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb,
    '{}'::jsonb
  );
BEGIN
  IF coalesce(v_claims->>'role', '') <> 'service_role' THEN
    RAISE EXCEPTION 'ZBS live dispatch RPC requires service_role JWT'
      USING errcode = '42501';
  END IF;

  UPDATE public.zbs_notification_outbox
  SET
    status = 'sent',
    provider_message_id = NULLIF(p_provider_message_id, ''),
    provider_response = coalesce(p_provider_response, '{}'::jsonb),
    last_error_code = NULL,
    last_error_message = NULL,
    sent_at = coalesce(p_sent_at, now()),
    updated_at = now()
  WHERE id = p_id
    AND provider = 'zalo_zbs'
    AND status = 'processing'
    AND p_claimed_at IS NOT NULL
    AND last_attempt_at BETWEEN p_claimed_at - interval '1 millisecond'
      AND p_claimed_at + interval '1 millisecond';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ZBS outbox row % is not claimable as sent for this lease', p_id
      USING errcode = 'P0002';
  END IF;
END;
$$;


ALTER FUNCTION public.zbs_notification_outbox_mark_sent(p_id uuid, p_claimed_at timestamp with time zone, p_provider_message_id text, p_sent_at timestamp with time zone, p_provider_response jsonb) OWNER TO postgres;

--
-- Name: FUNCTION zbs_notification_outbox_mark_sent(p_id uuid, p_claimed_at timestamp with time zone, p_provider_message_id text, p_sent_at timestamp with time zone, p_provider_response jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.zbs_notification_outbox_mark_sent(p_id uuid, p_claimed_at timestamp with time zone, p_provider_message_id text, p_sent_at timestamp with time zone, p_provider_response jsonb) IS 'Server-only live ZBS dispatcher success boundary. Requires service_role JWT and a matching processing lease timestamp, tolerating client/DB precision drift.';


--
-- Name: zbs_notification_outbox_pending_for_dispatch(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.zbs_notification_outbox_pending_for_dispatch(p_limit integer DEFAULT 25, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(id uuid, event_type text, source_type text, source_id bigint, don_vi_id bigint, recipient_config_id uuid, recipient_phone text, template_id text, template_data jsonb, tracking_id text, status text, provider text, next_attempt_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims jsonb;
  v_role text;
  v_user_id bigint;
  v_don_vi bigint;
  v_is_global boolean := false;
  v_limit integer;
BEGIN
  v_claims := coalesce(current_setting('request.jwt.claims', true), '{}'::text)::jsonb;
  v_role := lower(coalesce(nullif(v_claims->>'app_role', ''), nullif(v_claims->>'role', '')));
  v_user_id := nullif(v_claims->>'user_id', '')::bigint;
  v_don_vi := nullif(v_claims->>'don_vi', '')::bigint;
  v_is_global := v_role in ('global', 'admin');
  v_limit := least(greatest(coalesce(p_limit, 25), 1), 100);

  IF v_role IS NULL OR v_role = '' THEN
    RAISE EXCEPTION 'Missing role claim in JWT' USING errcode = '42501';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing user_id claim in JWT' USING errcode = '42501';
  END IF;

  IF v_role NOT IN ('global', 'admin', 'to_qltb') THEN
    RAISE EXCEPTION 'Permission denied' USING errcode = '42501';
  END IF;

  IF NOT v_is_global AND v_don_vi IS NULL THEN
    RAISE EXCEPTION 'Missing don_vi claim for non-global role %', v_role USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT
    outbox.id,
    outbox.event_type,
    outbox.source_type,
    outbox.source_id,
    outbox.don_vi_id,
    outbox.recipient_config_id,
    outbox.recipient_phone,
    outbox.template_id,
    outbox.template_data,
    outbox.tracking_id,
    outbox.status,
    outbox.provider,
    outbox.next_attempt_at
  FROM public.zbs_notification_outbox outbox
  WHERE outbox.status = 'pending'
    AND outbox.provider = 'zalo_zbs'
    AND outbox.event_type = 'repair_request_created'
    AND outbox.source_type = 'repair_request'
    AND outbox.next_attempt_at <= coalesce(p_now, now())
    AND (v_is_global OR outbox.don_vi_id = v_don_vi)
  ORDER BY outbox.created_at ASC, outbox.id ASC
  LIMIT v_limit;
END;
$$;


