--
-- Name: zbs_oauth_token_state_get(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.zbs_oauth_token_state_get(p_provider text DEFAULT 'zalo_zbs'::text) RETURNS TABLE(provider text, access_token text, access_token_expires_at timestamp with time zone, refresh_token text, refresh_token_issued_at timestamp with time zone, refresh_token_expires_at timestamp with time zone, last_refresh_at timestamp with time zone, last_refresh_error_code text, last_refresh_error_message text, last_refresh_error_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims jsonb := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb,
    '{}'::jsonb
  );
BEGIN
  IF coalesce(v_claims->>'role', '') <> 'service_role' THEN
    RAISE EXCEPTION 'ZBS token state RPC requires service_role JWT'
      USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT
    state.provider,
    state.access_token,
    state.access_token_expires_at,
    state.refresh_token,
    state.refresh_token_issued_at,
    state.refresh_token_expires_at,
    state.last_refresh_at,
    state.last_refresh_error_code,
    state.last_refresh_error_message,
    state.last_refresh_error_at,
    state.updated_at
  FROM public.zbs_oauth_token_state state
  WHERE state.provider = coalesce(nullif(p_provider, ''), 'zalo_zbs');
END;
$$;


