CREATE TABLE public.technical_configuration_baseline_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    dossier_id uuid NOT NULL,
    version_number bigint NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    next_criterion_number bigint DEFAULT 1 NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by bigint NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by bigint NOT NULL,
    source_baseline_version_id uuid,
    locked_at timestamp with time zone,
    locked_by bigint,
    CONSTRAINT technical_configuration_baseline_ve_next_criterion_number_check CHECK ((next_criterion_number > 0)),
    CONSTRAINT technical_configuration_baseline_versions_lock_state_check CHECK ((((status = 'draft'::text) AND (locked_at IS NULL) AND (locked_by IS NULL)) OR ((status = 'locked'::text) AND (locked_at IS NOT NULL) AND (locked_by IS NOT NULL)))),
    CONSTRAINT technical_configuration_baseline_versions_revision_check CHECK ((revision > 0)),
    CONSTRAINT technical_configuration_baseline_versions_source_not_self_check CHECK (((source_baseline_version_id IS NULL) OR (source_baseline_version_id <> id))),
    CONSTRAINT technical_configuration_baseline_versions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'locked'::text]))),
    CONSTRAINT technical_configuration_baseline_versions_version_number_check CHECK ((version_number > 0))
);


