--
-- Name: v_don_vi_dia_ban_check; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_don_vi_dia_ban_check AS
 SELECT dv.id AS don_vi_id,
    dv.code AS don_vi_code,
    dv.name AS don_vi_name,
    dv.dia_ban_id,
    db.ma_dia_ban,
    db.ten_dia_ban
   FROM (public.don_vi dv
     LEFT JOIN public.dia_ban db ON ((db.id = dv.dia_ban_id)));


ALTER VIEW public.v_don_vi_dia_ban_check OWNER TO postgres;

--
-- Name: VIEW v_don_vi_dia_ban_check; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_don_vi_dia_ban_check IS 'Diagnostic view for verifying don_vi to dia_ban assignments';


