    CONSTRAINT yeu_cau_luan_chuyen_loai_hinh_check CHECK ((loai_hinh = ANY (ARRAY['noi_bo'::text, 'ben_ngoai'::text]))),
    CONSTRAINT yeu_cau_luan_chuyen_muc_dich_check CHECK (((muc_dich IS NULL) OR (muc_dich = ANY (ARRAY['sua_chua'::text, 'cho_muon'::text, 'thanh_ly'::text, 'khac'::text])))),
    CONSTRAINT yeu_cau_luan_chuyen_trang_thai_check CHECK ((trang_thai = ANY (ARRAY['cho_duyet'::text, 'da_duyet'::text, 'dang_luan_chuyen'::text, 'da_ban_giao'::text, 'hoan_thanh'::text])))
