--
-- Name: zbs_notification_outbox; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.zbs_notification_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_type text NOT NULL,
    source_type text NOT NULL,
    source_id bigint NOT NULL,
    don_vi_id bigint NOT NULL,
    recipient_config_id uuid NOT NULL,
    recipient_phone text NOT NULL,
    template_id text,
    template_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    tracking_id text DEFAULT (gen_random_uuid())::text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    last_attempt_at timestamp with time zone,
    provider text DEFAULT 'zalo_zbs'::text NOT NULL,
    provider_message_id text,
    provider_response jsonb,
    last_error_code text,
    last_error_message text,
    sent_at timestamp with time zone,
    delivered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    delivery_webhook_received_at timestamp with time zone,
    CONSTRAINT zbs_notification_outbox_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT zbs_notification_outbox_event_type_check CHECK ((btrim(event_type) <> ''::text)),
    CONSTRAINT zbs_notification_outbox_provider_check CHECK ((provider = 'zalo_zbs'::text)),
    CONSTRAINT zbs_notification_outbox_recipient_phone_check CHECK ((recipient_phone ~ '^[0-9]{8,15}$'::text)),
    CONSTRAINT zbs_notification_outbox_source_type_check CHECK ((btrim(source_type) <> ''::text)),
    CONSTRAINT zbs_notification_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'sent'::text, 'delivered'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT zbs_notification_outbox_template_data_check CHECK ((jsonb_typeof(template_data) = 'object'::text))
);


ALTER TABLE public.zbs_notification_outbox OWNER TO postgres;

--
-- Name: TABLE zbs_notification_outbox; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.zbs_notification_outbox IS 'Server-only generic notification outbox for Zalo ZBS delivery. Phase 1 only enqueues repair request notifications.';


--
-- Name: COLUMN zbs_notification_outbox.template_data; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.zbs_notification_outbox.template_data IS 'Internal semantic snapshot for dispatcher mapping to provider-approved ZBS template fields.';


--
-- Name: COLUMN zbs_notification_outbox.delivery_webhook_received_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.zbs_notification_outbox.delivery_webhook_received_at IS 'Server receipt timestamp for trusted Zalo ZBS delivery webhooks.';


--
-- Name: zbs_oauth_token_state; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.zbs_oauth_token_state (
    provider text NOT NULL,
    access_token text,
    access_token_expires_at timestamp with time zone,
    refresh_token text,
    refresh_token_issued_at timestamp with time zone,
    refresh_token_expires_at timestamp with time zone,
    last_refresh_at timestamp with time zone,
    last_refresh_error_code text,
    last_refresh_error_message text,
    last_refresh_error_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT zbs_oauth_token_state_check CHECK (((access_token IS NULL) OR (access_token_expires_at IS NOT NULL))),
    CONSTRAINT zbs_oauth_token_state_check1 CHECK (((refresh_token IS NULL) OR (refresh_token_issued_at IS NOT NULL))),
