--
-- Name: user_fcm_tokens Users can only delete their own tokens; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can only delete their own tokens" ON public.user_fcm_tokens FOR DELETE USING ((( SELECT auth.uid() AS uid) = user_id));


--
-- Name: user_fcm_tokens Users can only insert their own tokens; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can only insert their own tokens" ON public.user_fcm_tokens FOR INSERT WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));


--
-- Name: user_fcm_tokens Users can only select their own tokens; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can only select their own tokens" ON public.user_fcm_tokens FOR SELECT USING ((( SELECT auth.uid() AS uid) = user_id));


--
-- Name: user_fcm_tokens Users can only update their own tokens; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can only update their own tokens" ON public.user_fcm_tokens FOR UPDATE USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));


